export interface HoodedAdventurerAnimationDefinition {
  readonly id: HoodedAdventurerAnimationId;
  readonly displayName: string;
  readonly category: HoodedAdventurerAnimationCategory;
  readonly url: string;
  readonly durationSeconds: number;
  readonly loop: boolean;
  /** Runtime locomotion owns X/Z. Clip Y is retained for jumps and crouches. */
  readonly lockHorizontalRootMotion: true;
  /** Variant meaning still needs a visual contact/prop pass. */
  readonly needsContactReview?: boolean;
}

export const HOODED_ADVENTURER_MODEL_URL =
  'assets/characters/hooded-adventurer/model.fbx';

const animationUrl = (fileName: string): string =>
  `assets/characters/hooded-adventurer/animations/${fileName}`;

/** Newly reviewed source clips can stay in the public drop folder while the
 * semantic catalogue shields gameplay from their human-readable filenames. */
const uploadedAnimationUrl = (fileName: string): string =>
  `assets/${encodeURIComponent(fileName)}`;

const animation = (
  id: HoodedAdventurerAnimationId,
  displayName: string,
  category: HoodedAdventurerAnimationCategory,
  fileName: string,
  durationSeconds: number,
  loop: boolean,
  needsContactReview = false,
  directUrl?: string,
): HoodedAdventurerAnimationDefinition => Object.freeze({
  id,
  displayName,
  category,
  url: directUrl ?? animationUrl(fileName),
  durationSeconds,
  loop,
  lockHorizontalRootMotion: true,
  needsContactReview: needsContactReview || undefined,
});

