/**
 * The imported model has no neutral idle clip of its own. A frozen frame from
 * the normal walk supplies an upright, hands-free pose until one is imported.
 */
export const HOODED_ADVENTURER_DEFAULT_POSE_ID = 'WALK_STANDARD' as const;

/** Small first-load set. Frequent survival actions preload; prop clips stay lazy. */
export const HOODED_ADVENTURER_CORE_ANIMATION_IDS = Object.freeze([
  HOODED_ADVENTURER_DEFAULT_POSE_ID,
  'RUN',
  'DEEP_SNOW_RUN',
  'JUMP',
  'TWO_HAND_IDLE',
  'HEAVY_TOOL_SWING',
  'PICKUP_GROUND',
  'PICK_FRUIT_SHRUB',
] satisfies readonly HoodedAdventurerAnimationId[]);

const animationById = new Map(
  HOODED_ADVENTURER_ANIMATIONS.map((definition) => [definition.id, definition]),
);

export const hoodedAdventurerAnimation = (
  id: HoodedAdventurerAnimationId,
): HoodedAdventurerAnimationDefinition => {
  const definition = animationById.get(id);
  if (!definition) throw new Error(`Unknown hooded-adventurer animation: ${id}`);
  return definition;
};

