import {
  BoxGeometry,
  BufferAttribute,
  BufferGeometry,
  Color,
  CylinderGeometry,
  DataTexture,
  Group,
  LinearFilter,
  Mesh,
  MeshStandardMaterial,
  Object3D,
  PointLight,
  Points,
  PointsMaterial,
  RGBAFormat,
  SphereGeometry,
  SpotLight,
  UnsignedByteType,
  type Scene,
} from 'three';
import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';
import { clamp, damp, hash2D, lerp } from '../utils/math';
import type { BulldozerState } from './BulldozerSimulation';
import type { LandSnowPlowResult } from './LandSnowSystem';
import {
  BULLDOZER_BLADE_PROFILES,
  DEFAULT_BULLDOZER_CAPABILITIES,
  MAX_BULLDOZER_BLADE_ANGLE_RADIANS,
  type BulldozerCapabilities,
} from './BulldozerUpgrades';
import {
  TerrainVehicleAttitude,
  type TerrainVehicleSurfaceNormal,
} from './TerrainVehicleAttitude';

interface SnowParticle {
  x: number;
  y: number;
  z: number;
  velocityX: number;
  velocityY: number;
  velocityZ: number;
  life: number;
  large: boolean;
}

const PARTICLE_COUNT = 160;
const SUSPENSION_RESPONSE = 5.2;
const MAXIMUM_SUSPENSION_RISE_PER_SECOND = 0.9;
const MAXIMUM_SUSPENSION_FALL_PER_SECOND = 1.15;
const BLADE_RAISED_Y = 1.32;
const BLADE_LOWERED_Y = 0.39;

const createSnowParticleTexture = (): DataTexture => {
  const size = 32;
  const data = new Uint8Array(size * size * 4);
  for (let row = 0; row < size; row += 1) {
    for (let column = 0; column < size; column += 1) {
      const x = ((column + 0.5) / size) * 2 - 1;
      const y = ((row + 0.5) / size) * 2 - 1;
      const distance = Math.sqrt(x * x + y * y);
      const falloff = clamp(1 - distance, 0, 1);
      const alpha = Math.round(
        255 * falloff * falloff * (3 - 2 * falloff),
      );
      const offset = (row * size + column) * 4;
      data[offset] = 255;
      data[offset + 1] = 255;
      data[offset + 2] = 255;
      data[offset + 3] = alpha;
    }
  }
  const texture = new DataTexture(
    data,
    size,
    size,
    RGBAFormat,
    UnsignedByteType,
  );
  texture.minFilter = LinearFilter;
  texture.magFilter = LinearFilter;
  texture.needsUpdate = true;
  return texture;
};

export class BulldozerPresenter {
  private readonly group = new Group();
  private readonly modelRoot = new Group();
  private readonly bladePivot = new Group();
  private readonly bucketPivot = new Group();
  private readonly bucketBowl = new Group();
  private bucketSnowFill?: Mesh;
  private readonly leftBladeWing = new Group();
  private readonly rightBladeWing = new Group();
  private readonly wheels: Mesh[] = [];
  private readonly tracks: Mesh[] = [];
  private readonly chainCleats: Mesh[] = [];
  private readonly workLights: SpotLight[] = [];
  private readonly workLightLenses: Mesh[] = [];
  private readonly cabViewOccluders: Mesh[] = [];
  private readonly beaconAssembly = new Group();
  private readonly beaconLight = new PointLight(0xff861f, 0, 5.5, 2);
  private readonly beaconSweep = new SpotLight(
    0xff8a24,
    0,
    7,
    0.3,
    0.72,
    1.4,
  );
  private readonly beaconTarget = new Object3D();
  private readonly materials: MeshStandardMaterial[] = [];
  private readonly particles: SnowParticle[] = Array.from(
    { length: PARTICLE_COUNT },
    () => ({
      x: 0,
      y: -10,
      z: 0,
      velocityX: 0,
      velocityY: 0,
      velocityZ: 0,
      life: 0,
      large: false,
    }),
  );
  private readonly particleTexture = createSnowParticleTexture();
  private readonly particlePositions = new Float32Array(
    PARTICLE_COUNT * 3,
  );
  private readonly puffPositions = new Float32Array(
    PARTICLE_COUNT * 3,
  );
  private readonly particleGeometry = new BufferGeometry();
  private readonly puffGeometry = new BufferGeometry();
  private readonly particleMaterial = new PointsMaterial({
    color: new Color(0xe1f6f8),
    size: 0.66,
    map: this.particleTexture,
    transparent: true,
    opacity: 0.88,
    alphaTest: 0.015,
    depthWrite: false,
  });
  private readonly puffMaterial = new PointsMaterial({
    color: new Color(0xc5e6eb),
    size: 2.08,
    map: this.particleTexture,
    transparent: true,
    opacity: 0.68,
    alphaTest: 0.015,
    depthWrite: false,
  });
  private readonly particlePoints: Points;
  private readonly puffPoints: Points;
  private particleCursor = 0;
  private bladeY = 0.4;
  private suspensionY?: number;
  private readonly terrainAttitude = new TerrainVehicleAttitude();
  private environmentNight = 0;
  private presentationVisible = false;
  private workLightsEnabled = true;
  private workLightShadowCursor = 0;
  private workLightShadowUpdates = 0;
  private shaderWarmupActive = false;
  private workLightLensMaterial?: MeshStandardMaterial;
  private beaconRequestedOn = false;
  private beaconPhase = 0;
  private beaconLensMaterial?: MeshStandardMaterial;
  private coldStartSeconds = 0;
  private coldStartDuration = 1;
  private engineVibrationPhase = 0;
  private engineDormant = false;
  private capabilities: BulldozerCapabilities = {
    ...DEFAULT_BULLDOZER_CAPABILITIES,
  };

  public constructor(scene: Scene) {
    this.group.name = 'Player deployable bulldozer';
    this.modelRoot.name = 'Player deployable bulldozer visual vibration root';
    this.group.add(this.modelRoot);
    this.createModel();
    for (let index = 0; index < PARTICLE_COUNT; index += 1) {
      this.particlePositions[index * 3 + 1] = -10;
      this.puffPositions[index * 3 + 1] = -10;
    }
    this.particleGeometry.setAttribute(
      'position',
      new BufferAttribute(this.particlePositions, 3),
    );
    this.puffGeometry.setAttribute(
      'position',
      new BufferAttribute(this.puffPositions, 3),
    );
    this.particlePoints = new Points(
      this.particleGeometry,
      this.particleMaterial,
    );
    this.particlePoints.name = 'Bulldozer snow spray';
    this.particlePoints.frustumCulled = false;
    this.puffPoints = new Points(
      this.puffGeometry,
      this.puffMaterial,
    );
    this.puffPoints.name = 'Bulldozer large snow puffs';
    this.puffPoints.frustumCulled = false;
    scene.add(this.group);
    scene.add(this.particlePoints, this.puffPoints);
  }

  public setVisible(visible: boolean): void {
    this.presentationVisible = visible;
    this.group.visible = visible;
    this.particlePoints.visible = visible;
    this.puffPoints.visible = visible;
    this.applyWorkLightState();
    this.updateBeacon(0);
  }

  public setCabViewActive(active: boolean): void {
    for (const mesh of this.cabViewOccluders) mesh.visible = !active;
  }

  /** Enables the real night/shadow variants while the loading cover is up. */
  public setShaderWarmupActive(active: boolean): void {
    this.shaderWarmupActive = active;
    this.applyWorkLightState();
    if (active) {
      for (const light of this.workLights) light.shadow.needsUpdate = true;
    }
  }

  public getWorkLightStats(): Readonly<{
    lights: number;
    shadowCastingLights: number;
    shadowUpdatesThisFrame: number;
  }> {
    let shadowCastingLights = 0;
    for (const light of this.workLights) {
      if (light.castShadow) shadowCastingLights += 1;
    }
    return {
      lights: this.workLights.length,
      shadowCastingLights,
      shadowUpdatesThisFrame: this.workLightShadowUpdates,
    };
  }

  public applyCapabilities(
    capabilities: Readonly<BulldozerCapabilities>,
  ): void {
    this.capabilities = { ...capabilities };
    const side = capabilities.heavyChassis
      ? 0.96
      : capabilities.wideTracks
        ? 0.85
        : 0.79;
    const scale = capabilities.heavyChassis
      ? 1.48
      : capabilities.wideTracks
        ? 1.32
        : 1;
    for (const track of this.tracks) {
      track.position.x = Math.sign(track.position.x) * side;
      track.scale.x = scale;
    }
    for (const wheel of this.wheels) {
      wheel.position.x = Math.sign(wheel.position.x) * side;
      wheel.scale.y = scale;
    }
    for (const cleat of this.chainCleats) {
      const trackSide = Math.sign(cleat.position.x) || 1;
      cleat.position.x = trackSide * (side + 0.25);
      cleat.visible = capabilities.chainTracks;
    }
    for (const lens of this.workLightLenses) {
      lens.scale.setScalar(capabilities.polarWorkLights ? 1.34 : 1);
    }
    this.group.scale.set(
      capabilities.heavyChassis ? 1.12 : 1,
      capabilities.heavyChassis ? 1.08 : 1,
      capabilities.heavyChassis ? 1.15 : 1,
    );
    this.bladePivot.scale.x = capabilities.highCapacityBlade ? 1.25 : 1;
    this.applyWorkLightState();
    this.updateBeacon(0);
  }

  public setEnvironmentLighting(night: number): void {
    this.environmentNight = Math.max(0, Math.min(1, night));
    this.applyWorkLightState();
  }

  public setWorkLightsEnabled(enabled: boolean): void {
    this.workLightsEnabled = enabled;
    this.applyWorkLightState();
  }

  public setEngineDormant(dormant: boolean): void {
    if (this.engineDormant === dormant) return;
    this.engineDormant = dormant;
    this.group.userData.engineState = dormant ? 'DORMANT' : 'RUNNING';
    this.applyWorkLightState();
  }

  public triggerColdStart(
    state: Readonly<BulldozerState>,
    durationSeconds = 0.92,
  ): void {
    this.coldStartDuration = Math.max(0.1, durationSeconds);
    this.coldStartSeconds = this.coldStartDuration;
    this.group.userData.startEffectAssetId = 'EFFECT_STARTER_TRACTOR_CRANK_01';
    const forwardX = Math.sin(state.heading);
    const forwardZ = Math.cos(state.heading);
    const rightX = Math.cos(state.heading);
    const rightZ = -Math.sin(state.heading);
    for (let index = 0; index < 12; index += 1) {
      const particle = this.particles[this.particleCursor]!;
      this.particleCursor = (this.particleCursor + 1) % PARTICLE_COUNT;
      const random = hash2D(index, this.particleCursor, 427);
      particle.large = true;
      particle.x = state.x + forwardX * 0.6 + rightX * 0.43;
      particle.y = (this.suspensionY ?? 0) + 1.55;
      particle.z = state.z + forwardZ * 0.6 + rightZ * 0.43;
      particle.velocityX = rightX * (random - 0.5) * 0.3;
      particle.velocityY = 0.35 + random * 0.45;
      particle.velocityZ = rightZ * (random - 0.5) * 0.3;
      particle.life = 0.72 + random * 0.55;
    }
  }

  public update(
    state: Readonly<BulldozerState>,
    deltaSeconds: number,
    surfaceY: number,
    surfaceNormal: Readonly<TerrainVehicleSurfaceNormal> = {
      normalX: 0,
      normalY: 1,
      normalZ: 0,
    },
  ): void {
    const targetSurfaceY = Number.isFinite(surfaceY)
      ? surfaceY
      : (this.suspensionY ?? 0);
    if (this.suspensionY === undefined || deltaSeconds <= 0) {
      this.suspensionY = targetSurfaceY;
    } else {
      const delta = Math.max(0, Math.min(0.05, deltaSeconds));
      const damped = damp(
        this.suspensionY,
        targetSurfaceY,
        SUSPENSION_RESPONSE,
        delta,
      );
      const maximumChange =
        (damped >= this.suspensionY
          ? MAXIMUM_SUSPENSION_RISE_PER_SECOND
          : MAXIMUM_SUSPENSION_FALL_PER_SECOND) * delta;
      this.suspensionY += Math.max(
        -maximumChange,
        Math.min(maximumChange, damped - this.suspensionY),
      );
    }
    this.group.position.set(state.x, this.suspensionY, state.z);
    this.group.quaternion.copy(this.terrainAttitude.update(
      state.heading,
      surfaceNormal,
      deltaSeconds,
      this.capabilities.heavyChassis ? 3.15 : 4.1,
      this.capabilities.heavyChassis ? 0.58 : 0.76,
    ));
    this.updateWorkLightShadows();
    this.modelRoot.position.set(0, 0, 0);
    this.modelRoot.rotation.set(0, 0, 0);
    if (!this.engineDormant) {
      this.engineVibrationPhase += Math.max(0, deltaSeconds) *
        (7.5 + Math.abs(state.speed) * 0.8);
      const primary = Math.sin(this.engineVibrationPhase * 2.03);
      const secondary = Math.sin(this.engineVibrationPhase * 3.71 + 0.8);
      this.modelRoot.position.y += primary * 0.0035 + secondary * 0.0018;
      this.modelRoot.rotateZ(primary * 0.0028 + secondary * 0.0011);
      this.modelRoot.rotateX(secondary * 0.0013);
    }
    if (this.coldStartSeconds > 0) {
      this.coldStartSeconds = Math.max(0, this.coldStartSeconds - deltaSeconds);
      const strength = clamp(
        this.coldStartSeconds / this.coldStartDuration,
        0,
        1,
      );
      this.modelRoot.rotateZ(
        Math.sin(this.coldStartSeconds * 29) * 0.018 * strength,
      );
      this.modelRoot.position.y += Math.abs(
        Math.sin(this.coldStartSeconds * 24),
      ) * 0.018 * strength;
    }
    const bladeTarget =
      BLADE_RAISED_Y +
      (BLADE_LOWERED_Y - BLADE_RAISED_Y) * state.bladePosition;
    this.bladeY = damp(this.bladeY, bladeTarget, 9, deltaSeconds);
    this.bladePivot.position.y = this.bladeY;
    this.bladePivot.visible = state.attachment === 'PLOW';
    this.bucketPivot.visible = state.attachment === 'BUCKET';
    this.bladePivot.rotation.x =
      -0.48 + (-0.08 + 0.48) * state.bladePosition;
    this.bladePivot.rotation.y = damp(
      this.bladePivot.rotation.y,
      state.bladeAngle * MAX_BULLDOZER_BLADE_ANGLE_RADIANS,
      9,
      deltaSeconds,
    );
    const wingAngle =
      BULLDOZER_BLADE_PROFILES[state.bladeMode].wingAngleRadians;
    this.leftBladeWing.rotation.y = damp(
      this.leftBladeWing.rotation.y,
      wingAngle,
      8,
      deltaSeconds,
    );
    this.rightBladeWing.rotation.y = damp(
      this.rightBladeWing.rotation.y,
      -wingAngle,
      8,
      deltaSeconds,
    );
    const bucketY =
      BLADE_RAISED_Y +
      (BLADE_LOWERED_Y - BLADE_RAISED_Y) * state.bladePosition;
    this.bucketPivot.position.y = damp(
      this.bucketPivot.position.y,
      bucketY,
      9,
      deltaSeconds,
    );
    this.bucketPivot.rotation.x =
      -0.14 + state.bladePosition * 0.1;
    // The authored bowl's dump travel uses negative local X: a lower tilt
    // value must roll the open face away from the tractor, not back into it.
    // Keep the end position short of 90 degrees so the visible load remains
    // on the bowl until the snow-transfer simulation releases it.
    this.bucketBowl.rotation.x = -1.22 + state.bucketTilt * 1.37;
    if (this.bucketSnowFill) {
      const fill = clamp(state.bucketMass / 0.72, 0, 1);
      this.bucketSnowFill.visible = fill > 0.005;
      this.bucketSnowFill.scale.y = Math.max(0.04, fill);
      this.bucketSnowFill.position.y = 0.1 + fill * 0.17;
    }
    for (const wheel of this.wheels) {
      wheel.rotation.x += state.speed * deltaSeconds * 2.4;
    }
    this.beaconRequestedOn = state.beaconOn;
    this.updateBeacon(deltaSeconds);
    this.updateParticles(deltaSeconds);
  }

  public emitSnow(
    state: Readonly<BulldozerState>,
    plow: Readonly<LandSnowPlowResult>,
  ): void {
    if (plow.removedSnow <= 0) return;
    const plumeStrength = clamp(
      plow.removedSnow * 0.42 + plow.resistance * 0.72,
      0,
      1,
    );
    const count = Math.min(
      24,
      Math.max(
        3,
        Math.ceil(plow.removedSnow * 8 + plow.resistance * 9),
      ),
    );
    const forwardX = Math.sin(state.heading);
    const forwardZ = Math.cos(state.heading);
    const rightX = Math.cos(state.heading);
    const rightZ = -Math.sin(state.heading);
    for (let index = 0; index < count; index += 1) {
      const particle = this.particles[this.particleCursor]!;
      this.particleCursor =
        (this.particleCursor + 1) % PARTICLE_COUNT;
      const phase = hash2D(index, this.particleCursor, 991);
      const randomSide = phase * 2 - 1;
      const bladeAngleStrength = Math.abs(state.bladeAngle);
      const dischargeSide = Math.sign(state.bladeAngle);
      const side = bladeAngleStrength > 0.001
        ? lerp(randomSide, dischargeSide, bladeAngleStrength * 0.88)
        : randomSide;
      particle.large =
        (index === 0 && plumeStrength > 0.42) ||
        phase > 0.78 - plumeStrength * 0.12 ||
        (plow.resistance > 0.66 && index % 3 === 0);
      const lateralForce =
        state.bladeMode === 'V_PLOW'
          ? 1.25
          : state.bladeMode === 'SCOOP'
            ? 0.38
            : 0.82 + bladeAngleStrength * 0.7;
      particle.x =
        state.x + forwardX * (1.43 + phase * 0.34) +
        rightX * side * (0.62 + phase * 0.42);
      particle.y =
        (this.suspensionY ?? 0.31) + 0.44 + phase * 0.28;
      particle.z =
        state.z + forwardZ * (1.43 + phase * 0.34) +
        rightZ * side * (0.62 + phase * 0.42);
      particle.velocityX =
        forwardX * (0.45 + phase * 0.6) +
        rightX * side * lateralForce * (particle.large ? 0.78 : 1);
      particle.velocityY =
        (particle.large ? 0.48 : 0.65) + phase * 0.75;
      particle.velocityZ =
        forwardZ * (0.45 + phase * 0.6) +
        rightZ * side * lateralForce * (particle.large ? 0.78 : 1);
      particle.life = particle.large
        ? 0.82 + phase * 0.68
        : 0.5 + phase * 0.52;
    }
  }

  public dispose(): void {
    this.group.traverse((object) => {
      if (object instanceof Mesh) object.geometry.dispose();
    });
    for (const material of this.materials) material.dispose();
    this.particleGeometry.dispose();
    this.puffGeometry.dispose();
    this.particleMaterial.dispose();
    this.puffMaterial.dispose();
    this.particleTexture.dispose();
    this.group.removeFromParent();
    this.particlePoints.removeFromParent();
    this.puffPoints.removeFromParent();
  }

  private createModel(): void {
    const orange = this.material(0xf3a33b, 0.62, 0.08);
    const dark = this.material(0x293b3d, 0.82, 0.14);
    const glass = this.material(0x9bd6dc, 0.28, 0.08);
    const steel = this.material(0x6b8587, 0.52, 0.42);
    const light = this.material(
      0xffe8a3,
      0.3,
      0.05,
      0xffcb58,
      0.58,
    );
    this.workLightLensMaterial = light;

    const chassis = new Mesh(
      new RoundedBoxGeometry(1.45, 0.48, 1.8, 3, 0.16),
      orange,
    );
    chassis.position.y = 0.58;
    this.addMesh(chassis);
    const hood = new Mesh(
      new RoundedBoxGeometry(1.15, 0.5, 0.82, 3, 0.13),
      orange,
    );
    hood.position.set(0, 0.88, 0.63);
    this.addMesh(hood);
    const cabin = new Mesh(
      new RoundedBoxGeometry(1.05, 0.95, 0.8, 3, 0.12),
      orange,
    );
    cabin.position.set(0, 1.18, -0.32);
    this.cabViewOccluders.push(cabin);
    this.addMesh(cabin);
    const windshield = new Mesh(
      new BoxGeometry(0.82, 0.48, 0.035),
      glass,
    );
    windshield.position.set(0, 1.28, 0.095);
    this.cabViewOccluders.push(windshield);
    this.addMesh(windshield);
    for (const side of [-0.79, 0.79]) {
      const track = new Mesh(
        new RoundedBoxGeometry(0.34, 0.42, 1.88, 3, 0.13),
        dark,
      );
      track.position.set(side, 0.35, 0);
      this.tracks.push(track);
      this.addMesh(track);
      for (const z of [-0.72, -0.48, -0.24, 0, 0.24, 0.48, 0.72]) {
        const cleat = new Mesh(
          new RoundedBoxGeometry(0.075, 0.5, 0.105, 2, 0.025),
          steel,
        );
        cleat.name = 'Starter tractor traction-chain cleat';
        cleat.position.set(side > 0 ? 1.04 : -1.04, 0.35, z);
        cleat.visible = false;
        this.chainCleats.push(cleat);
        this.addMesh(cleat);
      }
      for (const z of [-0.55, 0, 0.55]) {
        const wheel = new Mesh(
          new CylinderGeometry(0.18, 0.18, 0.39, 12),
          steel,
        );
        wheel.rotation.z = Math.PI / 2;
        wheel.position.set(side, 0.35, z);
        this.wheels.push(wheel);
        this.addMesh(wheel);
      }
    }
    const exhaust = new Mesh(
      new CylinderGeometry(0.055, 0.07, 0.6, 8),
      dark,
    );
    exhaust.position.set(0.43, 1.25, 0.58);
    this.addMesh(exhaust);
    const beaconMount = new Mesh(
      new CylinderGeometry(0.14, 0.16, 0.055, 16),
      dark,
    );
    beaconMount.position.set(0, 1.72, -0.3);
    this.addMesh(beaconMount);

    this.beaconLensMaterial = this.material(
      0xff8a20,
      0.3,
      0.05,
      0xff6a00,
      0.08,
    );
    const beaconLens = new Mesh(
      new CylinderGeometry(0.085, 0.115, 0.19, 16),
      this.beaconLensMaterial,
    );
    beaconLens.name = 'Bulldozer amber beacon lens';
    beaconLens.position.y = 0.1;
    beaconLens.castShadow = true;
    const beaconDome = new Mesh(
      new SphereGeometry(0.095, 16, 10),
      this.beaconLensMaterial,
    );
    beaconDome.position.y = 0.19;
    beaconDome.castShadow = true;
    this.beaconAssembly.name = 'Bulldozer amber warning beacon';
    this.beaconAssembly.position.set(0, 1.74, -0.3);
    this.beaconLight.name = 'Bulldozer amber beacon glow';
    this.beaconLight.position.y = 0.12;
    this.beaconSweep.name = 'Bulldozer rotating amber beacon beam';
    this.beaconSweep.position.y = 0.12;
    this.beaconTarget.position.set(0, -1.3, 5);
    this.beaconSweep.target = this.beaconTarget;
    this.beaconAssembly.add(
      beaconLens,
      beaconDome,
      this.beaconLight,
      this.beaconSweep,
      this.beaconTarget,
    );
    this.beaconAssembly.visible = false;
    this.modelRoot.add(this.beaconAssembly);

    for (const side of [-0.36, 0.36]) {
      const lens = new Mesh(
        new CylinderGeometry(0.105, 0.105, 0.065, 12),
        light,
      );
      lens.rotation.x = Math.PI / 2;
      lens.position.set(side, 1.02, 1.065);
      this.workLightLenses.push(lens);
      this.addMesh(lens);

      const workLight = new SpotLight(
        0xfff1bc,
        0,
        10,
        0.42,
        0.48,
        1.25,
      );
      workLight.name = `Bulldozer ${side < 0 ? 'left' : 'right'} work light`;
      workLight.position.set(side, 1.02, 1.11);
      workLight.shadow.mapSize.set(512, 512);
      workLight.shadow.camera.near = 0.12;
      workLight.shadow.camera.far = 9;
      workLight.shadow.bias = -0.0003;
      workLight.shadow.normalBias = 0.025;
      // Every lamp still has a real shadow map, but only one moving map is
      // refreshed per frame. This preserves blade occlusion and scales to
      // future side work lights without multiplying the whole scene pass.
      workLight.shadow.autoUpdate = false;
      const target = new Object3D();
      target.position.set(side * 0.55, 0.08, 10);
      this.modelRoot.add(workLight, target);
      workLight.target = target;
      this.workLights.push(workLight);
    }

    this.bladePivot.position.set(0, this.bladeY, 1.42);
    this.bladePivot.name = 'Bulldozer blade lift';
    const leftBlade = new Mesh(
      new RoundedBoxGeometry(1.11, 0.5, 0.16, 3, 0.08),
      steel,
    );
    leftBlade.position.x = -0.555;
    leftBlade.castShadow = true;
    leftBlade.receiveShadow = true;
    this.leftBladeWing.add(leftBlade);
    const rightBlade = new Mesh(
      new RoundedBoxGeometry(1.11, 0.5, 0.16, 3, 0.08),
      steel,
    );
    rightBlade.position.x = 0.555;
    rightBlade.castShadow = true;
    rightBlade.receiveShadow = true;
    this.rightBladeWing.add(rightBlade);
    this.bladePivot.add(this.leftBladeWing, this.rightBladeWing);
    for (const side of [-0.62, 0.62]) {
      const arm = new Mesh(new BoxGeometry(0.11, 0.11, 1.1), steel);
      arm.position.set(side, 0.18, -0.45);
      arm.rotation.x = -0.08;
      this.bladePivot.add(arm);
    }
    this.modelRoot.add(this.bladePivot);

    this.bucketPivot.position.set(0, BLADE_RAISED_Y, 1.38);
    this.bucketPivot.name = 'Starter tractor bucket lift';
    for (const side of [-0.64, 0.64]) {
      const arm = new Mesh(new BoxGeometry(0.12, 0.14, 1.28), steel);
      arm.position.set(side, 0.18, -0.38);
      arm.rotation.x = -0.13;
      this.bucketPivot.add(arm);
    }
    const bucketBack = new Mesh(
      new RoundedBoxGeometry(1.78, 0.55, 0.16, 3, 0.06),
      steel,
    );
    bucketBack.position.set(0, 0.02, 0.32);
    bucketBack.castShadow = true;
    bucketBack.receiveShadow = true;
    const bucketFloor = new Mesh(
      new RoundedBoxGeometry(1.82, 0.11, 0.88, 3, 0.04),
      steel,
    );
    bucketFloor.position.set(0, -0.22, 0.69);
    bucketFloor.rotation.x = -0.08;
    bucketFloor.castShadow = true;
    bucketFloor.receiveShadow = true;
    const bucketSnow = new Mesh(
      new RoundedBoxGeometry(1.58, 0.42, 0.66, 3, 0.08),
      this.material(0xdceff0, 0.95, 0),
    );
    bucketSnow.position.set(0, 0.18, 0.67);
    bucketSnow.castShadow = true;
    bucketSnow.visible = false;
    this.bucketSnowFill = bucketSnow;
    this.bucketBowl.name = 'Starter tractor bucket bowl';
    this.bucketBowl.add(bucketBack, bucketFloor, bucketSnow);
    this.bucketPivot.add(this.bucketBowl);
    this.bucketPivot.visible = false;
    this.modelRoot.add(this.bucketPivot);
    this.applyWorkLightState();
  }

  private addMesh(mesh: Mesh): void {
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    this.modelRoot.add(mesh);
  }

  private material(
    color: number,
    roughness: number,
    metalness: number,
    emissive = 0,
    emissiveIntensity = 0,
  ): MeshStandardMaterial {
    const material = new MeshStandardMaterial({
      color,
      roughness,
      metalness,
      emissive,
      emissiveIntensity,
    });
    this.materials.push(material);
    return material;
  }

  private updateParticles(deltaSeconds: number): void {
    for (let index = 0; index < this.particles.length; index += 1) {
      const particle = this.particles[index]!;
      if (particle.life > 0) {
        particle.life -= deltaSeconds;
        particle.x += particle.velocityX * deltaSeconds;
        particle.y += particle.velocityY * deltaSeconds;
        particle.z += particle.velocityZ * deltaSeconds;
        particle.velocityY -=
          (particle.large ? 1.45 : 2.8) * deltaSeconds;
      } else {
        particle.y = -10;
      }
      this.particlePositions[index * 3] = particle.x;
      this.particlePositions[index * 3 + 1] = particle.large
        ? -10
        : particle.y;
      this.particlePositions[index * 3 + 2] = particle.z;
      this.puffPositions[index * 3] = particle.x;
      this.puffPositions[index * 3 + 1] = particle.large
        ? particle.y
        : -10;
      this.puffPositions[index * 3 + 2] = particle.z;
    }
    const position = this.particleGeometry.getAttribute('position');
    position.needsUpdate = true;
    const puffPosition = this.puffGeometry.getAttribute('position');
    puffPosition.needsUpdate = true;
  }

  private applyWorkLightState(): void {
    const upgraded = this.capabilities.polarWorkLights;
    const nightStrength = Math.max(
      0,
      Math.min(1, (this.environmentNight - 0.12) / 0.72),
    );
    const activeStrength = this.shaderWarmupActive
      ? 1
      : this.workLightsEnabled && !this.engineDormant ? nightStrength : 0;
    if (this.workLightLensMaterial) {
      this.workLightLensMaterial.emissiveIntensity =
        this.workLightsEnabled ? 0.58 : 0;
    }
    for (const light of this.workLights) {
      light.intensity = activeStrength * (upgraded ? 105 : 22);
      light.distance = upgraded ? 18 : 9;
      light.angle = upgraded ? 0.5 : 0.38;
      light.castShadow =
        (this.presentationVisible || this.shaderWarmupActive) &&
        activeStrength > 0.02;
      if (light.shadow.camera.far !== light.distance) {
        light.shadow.camera.far = light.distance;
        light.shadow.camera.updateProjectionMatrix();
      }
    }
  }

  private updateWorkLightShadows(): void {
    this.workLightShadowUpdates = 0;
    let activeCount = 0;
    for (const light of this.workLights) {
      if (light.castShadow) activeCount += 1;
    }
    if (activeCount === 0) return;
    if (this.shaderWarmupActive) {
      for (const light of this.workLights) {
        if (light.castShadow) light.shadow.needsUpdate = true;
      }
      this.workLightShadowUpdates = activeCount;
      return;
    }
    const targetActiveIndex = this.workLightShadowCursor % activeCount;
    let activeIndex = 0;
    for (const light of this.workLights) {
      if (!light.castShadow) continue;
      light.shadow.needsUpdate = activeIndex === targetActiveIndex;
      activeIndex += 1;
    }
    this.workLightShadowCursor = (this.workLightShadowCursor + 1) % activeCount;
    this.workLightShadowUpdates = 1;
  }

  private updateBeacon(deltaSeconds: number): void {
    const installed = this.capabilities.amberBeacon;
    const active =
      installed && this.beaconRequestedOn && this.presentationVisible;
    this.beaconAssembly.visible = installed;
    if (active) {
      this.beaconPhase =
        (this.beaconPhase + Math.max(0, deltaSeconds) * 5.8) %
        (Math.PI * 2);
    }
    const flash = active
      ? Math.pow((Math.cos(this.beaconPhase) + 1) * 0.5, 7)
      : 0;
    if (this.beaconLensMaterial) {
      this.beaconLensMaterial.emissiveIntensity = active
        ? 1.55 + flash * 3.4
        : 0.08;
    }
    this.beaconLight.intensity = active ? 12 + flash * 20 : 0;
    this.beaconSweep.intensity = active ? 48 : 0;
    this.beaconTarget.position.set(
      Math.sin(this.beaconPhase) * 5,
      -1.3,
      Math.cos(this.beaconPhase) * 5,
    );
  }
}
