import { EMPTY_UPGRADE_LEVELS, UPGRADES } from '../data/config';
import type {
  UpgradeDefinition,
  UpgradeId,
  UpgradeLevels,
  VesselStats,
} from '../data/types';

export interface PurchaseResult {
  success: boolean;
  cost: number;
  reason?: 'maxed' | 'insufficient-funds' | 'unknown-upgrade';
}

export class UpgradeSystem {
  private levels: UpgradeLevels;

  public constructor(initialLevels?: Partial<UpgradeLevels>) {
    this.levels = {
      ...EMPTY_UPGRADE_LEVELS,
      ...(initialLevels ?? {}),
    };
    this.sanitize();
  }

  public getDefinitions(): UpgradeDefinition[] {
    return UPGRADES;
  }

  public getLevels(): UpgradeLevels {
    return { ...this.levels };
  }

  public getLevel(id: UpgradeId): number {
    return this.levels[id];
  }

  public getCost(id: UpgradeId): number {
    const definition = UPGRADES.find((upgrade) => upgrade.id === id);
    if (!definition) return Number.POSITIVE_INFINITY;
    const level = this.levels[id];
    return Math.round(definition.baseCost * definition.costMultiplier ** level / 10) * 10;
  }

  public purchase(id: UpgradeId, availableMoney: number): PurchaseResult {
    const definition = UPGRADES.find((upgrade) => upgrade.id === id);
    if (!definition) return { success: false, cost: 0, reason: 'unknown-upgrade' };

    const currentLevel = this.levels[id];
    if (currentLevel >= definition.maxLevel) {
      return { success: false, cost: 0, reason: 'maxed' };
    }

    const cost = this.getCost(id);
    if (availableMoney < cost) {
      return { success: false, cost, reason: 'insufficient-funds' };
    }

    this.levels[id] = currentLevel + 1;
    return { success: true, cost };
  }

  public getStats(): VesselStats {
    return {
      enginePower: 1 + this.levels.engine * 0.16,
      iceBreakingPower: 1 + this.levels.bow * 0.18,
      fuelEfficiency: 1 + this.levels.fuel * 0.14,
      openWaterSpeed: 1 + this.levels.propeller * 0.11,
      convoyStability: 1 + this.levels.escort * 0.12,
      scannerLevel: this.levels.scanner,
    };
  }

  private sanitize(): void {
    for (const definition of UPGRADES) {
      const value = this.levels[definition.id];
      this.levels[definition.id] = Math.max(0, Math.min(definition.maxLevel, Math.floor(value)));
    }
  }
}
