interface SnowLayer {
  system: ParticleSystem;
  emission: ConstantValue;
  forceX: ConstantValue;
  forceZ: ConstantValue;
  shape: RectangleEmitter;
}

interface WindLayer {
  system: ParticleSystem;
  emission: ConstantValue;
  forceX: ConstantValue;
  forceZ: ConstantValue;
  shape: RectangleEmitter;
}

interface CharacterSnowLayer {
  system: ParticleSystem;
  emission: ConstantValue;
  forceX: ConstantValue;
  forceZ: ConstantValue;
  shape: SphereEmitter;
  centerHeight: number;
}

export interface SnowfallLocalWeatherField {
  readonly timeSeconds?: number;
  readonly precipitationMultiplier: number;
  readonly whiteout: number;
  readonly gust: number;
}

export type PrecipitationOcclusionSampler = (
  x: number,
  y: number,
  z: number,
) => boolean;

/**
 * Visual precipitation is intentionally front-loaded above the first sparse
 * flakes. A forecast can begin almost empty, while an established
 * `light-snow` state must fill a wide OTS volume instead of looking like a few
 * isolated sprites. The upper end is capped to keep whiteout particle cost
 * bounded; distance fog supplies most of the storm density.
 */
export const resolveSnowfallVisualRate = (intensity: number): number => {
  const snowfall = clamp(intensity, 0, 1.35);
  const presence = smoothstep(0.015, 0.2, snowfall);
  return presence * Math.min(
    1.28,
    0.2 + Math.pow(snowfall, 0.72) * 1.08,
  );
};

export type LocalSnowfallPhase =
  | 'clear'
  | 'light'
  | 'steady'
  | 'heavy'
  | 'whiteout';

/**
 * A readable label for the continuous local density curve. This does not own
 * weather state: phase boundaries are diagnostic/presentation landmarks over
 * the exact authoritative local precipitation scalar.
 */
export const resolveLocalSnowfallPhase = (
  localPrecipitation: number,
): LocalSnowfallPhase => {
  const intensity = clamp(localPrecipitation, 0, 1.35);
  if (intensity < 0.015) return 'clear';
  if (intensity < 0.24) return 'light';
  if (intensity < 0.58) return 'steady';
  if (intensity < 0.92) return 'heavy';
  return 'whiteout';
};

/** Kills only flakes that physically enter a roofed excavated void. */
class PrecipitationOcclusionBehavior implements Behavior {
  public readonly type = 'IcewayPrecipitationOcclusion';

  public constructor(
    private readonly sampler: () =>
      PrecipitationOcclusionSampler | undefined,
  ) {}

  public initialize(
    _particle: Particle,
    _particleSystem: IParticleSystem,
  ): void {}

  public update(particle: Particle, _delta: number): void {
    const sample = this.sampler();
    if (!sample || !sample(
      particle.position.x,
      particle.position.y,
      particle.position.z,
    )) return;
    particle.age = particle.life;
  }

  public frameUpdate(_delta: number): void {}
  public reset(): void {}
  public toJSON(): unknown {
    return { type: this.type };
  }
  public clone(): Behavior {
    return new PrecipitationOcclusionBehavior(this.sampler);
  }
}

const createSnowflakeTexture = (): CanvasTexture => {
  const canvas = document.createElement('canvas');
  canvas.width = 96;
  canvas.height = 96;
  const context = canvas.getContext('2d');
  if (context) {
    const glow = context.createRadialGradient(48, 48, 1, 48, 48, 45);
    glow.addColorStop(0, 'rgba(255,255,255,1)');
    glow.addColorStop(0.12, 'rgba(249,254,255,0.98)');
    glow.addColorStop(0.36, 'rgba(232,248,255,0.34)');
    glow.addColorStop(1, 'rgba(210,240,255,0)');
    context.fillStyle = glow;
    context.fillRect(0, 0, 96, 96);
    // A soft six-arm crystal remains round at distance but avoids the smeared
    // pill silhouette of the old radial blob when a near flake crosses OTS.
    context.save();
    context.translate(48, 48);
    context.lineCap = 'round';
    context.strokeStyle = 'rgba(250,255,255,0.62)';
    context.lineWidth = 2.2;
    for (let arm = 0; arm < 6; arm += 1) {
      context.rotate(Math.PI / 3);
      context.beginPath();
      context.moveTo(0, 0);
      context.lineTo(0, 29);
      context.moveTo(0, 18);
      context.lineTo(-6, 24);
      context.moveTo(0, 18);
      context.lineTo(6, 24);
      context.stroke();
    }
    context.restore();
  }
  const texture = new CanvasTexture(canvas);
  texture.colorSpace = SRGBColorSpace;
  texture.minFilter = LinearFilter;
  texture.magFilter = LinearFilter;
  texture.needsUpdate = true;
  return texture;
};

const createWindTexture = (): CanvasTexture => {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 32;
  const context = canvas.getContext('2d');
  if (context) {
    const glow = context.createLinearGradient(0, 16, 128, 16);
    glow.addColorStop(0, 'rgba(205,241,248,0)');
    glow.addColorStop(0.28, 'rgba(220,248,252,0.42)');
    glow.addColorStop(0.7, 'rgba(232,252,255,0.82)');
    glow.addColorStop(1, 'rgba(232,252,255,0)');
    context.fillStyle = glow;
    context.beginPath();
    context.ellipse(64, 16, 62, 4.5, 0, 0, Math.PI * 2);
    context.fill();
  }
  const texture = new CanvasTexture(canvas);
  texture.colorSpace = SRGBColorSpace;
  texture.minFilter = LinearFilter;
  texture.magFilter = LinearFilter;
  texture.needsUpdate = true;
  return texture;
};

export class SnowfallSystem {
  private readonly scene: Scene;
  private readonly renderer = new BatchedRenderer();
  private readonly texture = createSnowflakeTexture();
  private readonly material = new MeshBasicMaterial({
    color: 0xffffff,
    map: this.texture,
    transparent: true,
    opacity: 0.96,
    depthWrite: false,
    // Cave walls and roofs must occlude outdoor precipitation. The previous
    // overlay material drew every flake through solid rock.
    depthTest: true,
    alphaTest: 0.018,
    blending: NormalBlending,
    side: DoubleSide,
  });
  private readonly windTexture = createWindTexture();
  private readonly windMaterial = new MeshBasicMaterial({
    color: 0xd7f5f8,
    map: this.windTexture,
    transparent: true,
    opacity: 0.92,
    depthWrite: false,
    depthTest: true,
    alphaTest: 0.006,
    blending: AdditiveBlending,
    side: DoubleSide,
  });
  private readonly near: SnowLayer;
  private readonly far: SnowLayer;
  private readonly characterNear: CharacterSnowLayer;
  private readonly characterFar: CharacterSnowLayer;
  private readonly wind: WindLayer;
  private readonly gpuSnowfall: GpuSnowfallField;
  private readonly gpuSpindrift: GpuSpindriftField;
  private readonly cameraUp = new Vector3();
  private readonly snowSpawnCenter = new Vector3();
  private readonly volumeNearCenter = new Vector3();
  private readonly volumeFarCenter = new Vector3();
  private readonly windFrontCenter = new Vector3(
    Number.POSITIVE_INFINITY,
    0,
    Number.POSITIVE_INFINITY,
  );
  private windWorldTime = 0;
  private intensity = 0;
  private blowingSnowIntensity = 0;
  private gustStrength = 0;
  private gustRemaining = 0;
  private windStreaksVisible = true;
  private localWeatherVisible = true;
  private volumeViewActive = false;
  private precipitationOcclusionSampler?: PrecipitationOcclusionSampler;
  private cloudTime = 0;
  private cloudDirectionX = 1;
  private cloudDirectionZ = 0;
  private cloudCover = 0;

  public constructor(scene: Scene, particleQualityMultiplier = 1) {
    this.scene = scene;
    this.renderer.name = 'Quarks snowfall batch';
    this.renderer.renderOrder = 7;
    this.scene.add(this.renderer);
    this.far = this.createLayer({
      width: 54,
      depth: 46,
      height: 22,
      lifeMin: 8.5,
      lifeMax: 11.5,
      sizeMin: 0.045,
      sizeMax: 0.105,
      alphaMin: 0.28,
      alphaMax: 0.54,
      gravity: -1.85,
    });
    this.near = this.createLayer({
      width: 34,
      depth: 29,
      height: 19,
      lifeMin: 6.4,
      lifeMax: 8,
      sizeMin: 0.075,
      sizeMax: 0.19,
      alphaMin: 0.5,
      alphaMax: 0.9,
      gravity: -3.2,
    });
    this.characterFar = this.createCharacterLayer({
      radius: 104,
      verticalScale: 0.31,
      centerHeight: 20,
      lifeMin: 10,
      lifeMax: 14,
      sizeMin: 0.045,
      sizeMax: 0.12,
      alphaMin: 0.3,
      alphaMax: 0.62,
      gravity: -0.58,
    });
    this.characterNear = this.createCharacterLayer({
      radius: 52,
      verticalScale: 0.28,
      centerHeight: 9.5,
      lifeMin: 6,
      lifeMax: 9,
      sizeMin: 0.07,
      sizeMax: 0.19,
      alphaMin: 0.5,
      alphaMax: 0.9,
      gravity: -0.84,
    });
    this.wind = this.createWindLayer();
    this.gpuSnowfall = new GpuSnowfallField(
      scene,
      this.texture,
      particleQualityMultiplier,
    );
    this.gpuSpindrift = new GpuSpindriftField(scene);
  }

  public setLocalWeatherVisible(visible: boolean): void {
    if (visible === this.localWeatherVisible) return;
    this.localWeatherVisible = visible;
    this.renderer.visible = visible;
    this.gpuSnowfall.setLocallyVisible(visible);
    this.gpuSpindrift.setLocalVisible(visible);
    // Clear old outdoor particles immediately when entering shelter. Without
    // this, long-lived flakes remain inside the cave for several seconds.
    for (const layer of this.allLayers()) layer.system.restart();
  }

  public setShaderWarmupActive(active: boolean): void {
    this.gpuSnowfall.setShaderWarmupActive(active);
  }

  public setGpuParticleBudgetMultiplier(multiplier: number): void {
    this.gpuSnowfall.setRuntimeBudgetMultiplier(multiplier);
  }

  public setLocalDensityVolumeEnabled(enabled: boolean): void {
    this.gpuSnowfall.setLocalDensityEnabled(enabled);
  }

  /** Updates only scalar uniforms; no per-frame particle field is allocated. */
  public setWorldCloudPrecipitationField(
    timeSeconds: number,
    directionX: number,
    directionZ: number,
    cloudCover: number,
  ): void {
    this.cloudTime = Math.max(0, timeSeconds);
    this.cloudDirectionX = directionX;
    this.cloudDirectionZ = directionZ;
    this.cloudCover = clamp(cloudCover, 0, 1);
  }

  public setPrecipitationOcclusionSampler(
    sampler: PrecipitationOcclusionSampler | undefined,
  ): void {
    this.precipitationOcclusionSampler = sampler;
  }

  public setGroundingQuality(quality: AtmosphereGroundingQuality): void {
    this.gpuSpindrift.setQuality(quality);
  }

  public setSurfaceHeightSampler(sampler: SnowSurfaceHeightSampler): void {
    this.gpuSpindrift.setSurfaceHeightSampler(sampler);
  }

  public setGroundingLighting(daylight: number, night: number): void {
    this.gpuSpindrift.setLighting(daylight, night);
  }

  public setIntensity(intensity: number): void {
    this.intensity = clamp(intensity, 0, 1);
  }

  public setBlowingSnowIntensity(windMultiplier: number): void {
    this.blowingSnowIntensity = clamp(
      (windMultiplier - 1.02) / 0.48,
      0,
      1,
    );
  }

  public triggerGust(strength: number, duration: number): void {
    this.gustStrength = Math.max(
      this.gustStrength,
      clamp(strength, 0, 1),
    );
    this.gustRemaining = Math.max(
      this.gustRemaining,
      clamp(duration, 0.5, 12),
    );
  }

  public toggleWindStreaksVisible(): boolean {
    this.windStreaksVisible = !this.windStreaksVisible;
    return this.windStreaksVisible;
  }

  public areWindStreaksVisible(): boolean {
    return this.windStreaksVisible;
  }

  public update(
    deltaSeconds: number,
    camera: Camera,
    windX: number,
    windZ: number,
    windStrength: number,
    characterView = false,
    focus?: Readonly<{ x: number; y?: number; z: number }>,
    weatherField?: Readonly<SnowfallLocalWeatherField>,
  ): void {
    this.windWorldTime = Number.isFinite(weatherField?.timeSeconds)
      ? Math.max(0, weatherField?.timeSeconds ?? 0)
      : this.windWorldTime + Math.max(0, deltaSeconds);
    const volumeView = characterView || camera instanceof PerspectiveCamera;
    if (volumeView !== this.volumeViewActive) {
      this.volumeViewActive = volumeView;
      for (const layer of this.allLayers()) layer.system.restart();
    }
    const strength = clamp(windStrength, 0, 2);
    if (this.gustRemaining > 0) {
      this.gustRemaining = Math.max(
        0,
        this.gustRemaining - deltaSeconds,
      );
    } else {
      this.gustStrength *= Math.exp(-deltaSeconds * 2.4);
      if (this.gustStrength < 0.002) this.gustStrength = 0;
    }
    const fieldGust = clamp(weatherField?.gust ?? 0, 0, 1);
    const whiteout = clamp(weatherField?.whiteout ?? 0, 0, 1);
    const visibleWindIntensity = clamp(
      this.blowingSnowIntensity + this.gustStrength * 0.55 +
        fieldGust * this.intensity * 0.28 + whiteout * 0.42,
      0,
      1,
    );
    // Wind is a visible part of snowfall, not just a slow positional drift.
    // The shared gust envelope modulates the slant without changing the
    // deterministic forecast direction.
    const acceleration =
      (0.075 + this.intensity * 0.17) *
      strength *
      (0.72 + this.gustStrength * 0.48 + fieldGust * 0.26);
    // Precipitation duration is owned by the slow cloud-mass envelope passed
    // through `intensity`. The wind field's old 13-second broad wave belongs
    // to gust/slant variation only; multiplying flakes by it was the source
    // of the visible two-second emitter pulse regression.
    const localIntensity = clamp(this.intensity, 0, 1.35);
    const visibleRate = this.localWeatherVisible
      ? resolveSnowfallVisualRate(localIntensity)
      : 0;
    for (const layer of [
      this.far,
      this.near,
      this.characterFar,
      this.characterNear,
    ]) {
      layer.forceX.value = windX * acceleration;
      layer.forceZ.value = windZ * acceleration;
    }

    if (volumeView) {
      this.far.emission.value = 0;
      this.near.emission.value = 0;
      camera.updateMatrixWorld();
      if (focus) {
        const focusY = focus.y ?? 0;
        this.volumeNearCenter.set(
          focus.x,
          focusY + this.characterNear.centerHeight,
          focus.z,
        );
        this.volumeFarCenter.set(
          focus.x,
          focusY + this.characterFar.centerHeight,
          focus.z,
        );
      } else {
        this.volumeNearCenter.copy(camera.position);
        this.volumeNearCenter.y += this.characterNear.centerHeight;
        this.volumeFarCenter.copy(camera.position);
        this.volumeFarCenter.y += this.characterFar.centerHeight;
      }
      this.characterNear.system.emitter.position.copy(this.volumeNearCenter);
      this.characterFar.system.emitter.position.copy(this.volumeFarCenter);
      // Character snowfall is one GPU-instanced 3D volume. The legacy Quarks
      // layers remain available for the orthographic view, but running both
      // would simulate tens of thousands of the same flakes on the CPU.
      this.characterNear.emission.value = 0;
      this.characterFar.emission.value = 0;
      this.gpuSnowfall.update(
        deltaSeconds,
        camera,
        windX,
        windZ,
        strength,
        visibleRate,
        localIntensity,
        focus ?? camera.position,
        this.cloudTime,
        this.cloudDirectionX,
        this.cloudDirectionZ,
        this.cloudCover,
        true,
      );
      // Spindrift belongs to the landscape, not the actor. The emitter is
      // anchored to a coarse world cell and begins well upwind of that cell;
      // existing particles remain world-space while the player moves inside
      // the much larger front.
      const focusY = focus?.y ?? 0;
      const focusX = focus?.x ?? camera.position.x;
      const focusZ = focus?.z ?? camera.position.z;
      const windLength = Math.max(0.001, Math.hypot(windX, windZ));
      const directionX = windX / windLength;
      const directionZ = windZ / windLength;
      const crossX = -directionZ;
      const crossZ = directionX;
      // Quantise a thin spawn front in wind-oriented world space. New lines
      // are born 44–108 m upwind, never around the actor, then travel through
      // the landscape as a persistent front of world-space particles.
      const focusAlong = focusX * directionX + focusZ * directionZ;
      const focusAcross = focusX * crossX + focusZ * crossZ;
      const anchorAlong = Math.floor((focusAlong - 44) / 64) * 64;
      const anchorAcross = Math.round(focusAcross / 64) * 64;
      const anchorX = directionX * anchorAlong + crossX * anchorAcross;
      const anchorZ = directionZ * anchorAlong + crossZ * anchorAcross;
      if (
        !Number.isFinite(this.windFrontCenter.x) ||
        Math.hypot(
          this.windFrontCenter.x - anchorX,
          this.windFrontCenter.z - anchorZ,
        ) > 24
      ) {
        this.windFrontCenter.set(anchorX, focusY + 0.18, anchorZ);
      } else {
        this.windFrontCenter.y = focusY + 0.18;
      }
      this.wind.system.emitter.position.copy(this.windFrontCenter);
      this.wind.system.emitter.rotation.set(
        -Math.PI / 2,
        Math.atan2(directionX, directionZ),
        0,
      );
      this.wind.shape.width = 176;
      this.wind.shape.height = 14;
      // The old CPU streak emitter is intentionally disabled in OTS. Its
      // particles were born around a moving anchor and visibly teleported
      // whenever that anchor crossed a cell. GpuSpindriftField below owns the
      // continuous world-space surface drift instead.
      this.wind.emission.value = 0;
    } else if (camera instanceof OrthographicCamera) {
      this.gpuSnowfall.update(
        deltaSeconds,
        camera,
        windX,
        windZ,
        strength,
        0,
        0,
        focus ?? camera.position,
        this.cloudTime,
        this.cloudDirectionX,
        this.cloudDirectionZ,
        this.cloudCover,
        false,
      );
      this.characterNear.emission.value = 0;
      this.characterFar.emission.value = 0;
      const coverage = calculateWeatherCoverage(camera);
      this.cameraUp
        .set(0, 1, 0)
        .applyQuaternion(camera.quaternion);
      const viewWidth =
        (camera.right - camera.left) / camera.zoom;
      const viewHeight =
        (camera.top - camera.bottom) / camera.zoom;
      calculateWeatherSpawnCenter(
        camera,
        coverage,
        viewHeight * 0.59 + 3,
        0,
        this.snowSpawnCenter,
      );
      const areaScale = clamp(viewWidth / 54, 1, 2.4);
      this.far.emission.value = visibleRate * areaScale * 238;
      this.near.emission.value = visibleRate * areaScale * 142;
      this.far.shape.width = viewWidth * 1.3;
      this.far.shape.height = 6;
      this.near.shape.width = viewWidth * 1.24;
      this.near.shape.height = 5;
      for (const layer of [this.far, this.near]) {
        layer.system.emitter.position.copy(this.snowSpawnCenter);
        layer.system.emitter.quaternion.copy(camera.quaternion);
      }
      const windLength = Math.max(0.001, Math.hypot(windX, windZ));
      const directionX = windX / windLength;
      const directionZ = windZ / windLength;
      const upwindDistance = Math.max(36, coverage.depth * 0.54);
      this.wind.system.emitter.position.x = coverage.centerX - directionX * upwindDistance;
      this.wind.system.emitter.position.z = coverage.centerZ - directionZ * upwindDistance;
      this.wind.system.emitter.rotation.set(
        -Math.PI / 2,
        Math.atan2(directionX, directionZ),
        0,
      );
      this.wind.shape.width = Math.max(coverage.width * 1.45, 142);
      this.wind.shape.height = 12;
      this.wind.emission.value =
        this.localWeatherVisible && this.windStreaksVisible
          ? visibleWindIntensity * (38 + areaScale * 18)
          : 0;
    } else {
      this.gpuSnowfall.update(
        deltaSeconds,
        camera,
        windX,
        windZ,
        strength,
        0,
        0,
        focus ?? camera.position,
        this.cloudTime,
        this.cloudDirectionX,
        this.cloudDirectionZ,
        this.cloudCover,
        false,
      );
      this.far.emission.value = 0;
      this.near.emission.value = 0;
      this.characterNear.emission.value = 0;
      this.characterFar.emission.value = 0;
      this.wind.emission.value = 0;
    }
    this.gpuSpindrift.update(
      deltaSeconds,
      camera,
      focus ?? camera.position,
      windX,
      windZ,
      strength,
      this.windStreaksVisible ? visibleWindIntensity : 0,
    );
    const windAcceleration =
      (2.8 + strength * 2.4) *
      (0.5 + visibleWindIntensity * 0.5);
    this.wind.forceX.value = windX * windAcceleration;
    this.wind.forceZ.value = windZ * windAcceleration;
    this.renderer.update(clamp(deltaSeconds, 0, 0.1));
  }

  public getActiveParticleCount(): number {
    return this.near.system.particleNum + this.far.system.particleNum +
      this.characterNear.system.particleNum +
      this.characterFar.system.particleNum +
      this.gpuSnowfall.getActiveCount();
  }

  public getGpuSnowfallCounts(): ReturnType<
    GpuSnowfallField['getActiveCounts']
  > {
    return this.gpuSnowfall.getActiveCounts();
  }

  public getLocalSnowfallPhase(): LocalSnowfallPhase {
    return resolveLocalSnowfallPhase(this.intensity);
  }

  public getActiveWindParticleCount(): number {
    const grounding = this.gpuSpindrift.getActiveCounts();
    return this.wind.system.particleNum + grounding.powder +
      grounding.crystals;
  }

  public getGroundingParticleCounts(): Readonly<{
    powder: number;
    crystals: number;
  }> {
    return this.gpuSpindrift.getActiveCounts();
  }

  public dispose(): void {
    for (const layer of this.allLayers()) {
      this.renderer.deleteSystem(layer.system);
      this.scene.remove(layer.system.emitter);
      layer.system.dispose();
    }
    this.scene.remove(this.renderer);
    for (const batch of this.renderer.batches) batch.dispose();
    this.material.dispose();
    this.texture.dispose();
    this.windMaterial.dispose();
    this.windTexture.dispose();
    this.gpuSnowfall.dispose(this.scene);
    this.gpuSpindrift.dispose();
  }

  private allLayers(): readonly (
    SnowLayer | CharacterSnowLayer | WindLayer
  )[] {
    return [
      this.near,
      this.far,
      this.characterNear,
      this.characterFar,
      this.wind,
    ];
  }

  private createLayer(options: {
    width: number;
    depth: number;
    height: number;
    lifeMin: number;
    lifeMax: number;
    sizeMin: number;
    sizeMax: number;
    alphaMin: number;
    alphaMax: number;
    gravity: number;
  }): SnowLayer {
    const emission = new ConstantValue(0);
    const forceX = new ConstantValue(0);
    const forceZ = new ConstantValue(0);
    const shape = new RectangleEmitter({
      width: options.width,
      height: options.depth,
      thickness: 1,
    });
    const system = new ParticleSystem({
      looping: true,
      duration: 12,
      worldSpace: true,
      shape,
      startLife: new IntervalValue(options.lifeMin, options.lifeMax),
      startSpeed: new IntervalValue(0.015, 0.075),
      startRotation: new IntervalValue(0, Math.PI * 2),
      startSize: new IntervalValue(options.sizeMin, options.sizeMax),
      startColor: new ColorRange(
        new ParticleColor(0.88, 0.96, 1, options.alphaMin),
        new ParticleColor(1, 1, 1, options.alphaMax),
      ),
      emissionOverTime: emission,
      behaviors: [
        new ForceOverLife(
          forceX,
          new ConstantValue(options.gravity),
          forceZ,
        ),
        new ColorOverLife(
          new Gradient(
            undefined,
            [
              [0, 0],
              [1, 0.08],
              [1, 0.94],
              [0, 1],
            ],
          ),
        ),
      ],
      material: this.material,
      renderMode: RenderMode.BillBoard,
      renderOrder: 7,
    });
    system.emitter.name = 'Snowfall emitter';
    system.emitter.position.y = options.height;
    this.scene.add(system.emitter);
    this.renderer.addSystem(system);
    return { system, emission, forceX, forceZ, shape };
  }

  private createCharacterLayer(options: {
    radius: number;
    verticalScale: number;
    centerHeight: number;
    lifeMin: number;
    lifeMax: number;
    sizeMin: number;
    sizeMax: number;
    alphaMin: number;
    alphaMax: number;
    gravity: number;
  }): CharacterSnowLayer {
    const emission = new ConstantValue(0);
    const forceX = new ConstantValue(0);
    const forceZ = new ConstantValue(0);
    const shape = new SphereEmitter({
      radius: options.radius,
      thickness: 1,
    });
    const system = new ParticleSystem({
      looping: true,
      prewarm: true,
      duration: 12,
      worldSpace: true,
      shape,
      startLife: new IntervalValue(options.lifeMin, options.lifeMax),
      // SphereEmitter derives its initial velocity from the spawn radius.
      // Keep it nearly zero so gravity and wind, rather than radial spray,
      // own the visible motion.
      startSpeed: new IntervalValue(0.001, 0.012),
      startRotation: new IntervalValue(0, Math.PI * 2),
      startSize: new IntervalValue(options.sizeMin, options.sizeMax),
      startColor: new ColorRange(
        new ParticleColor(0.88, 0.96, 1, options.alphaMin),
        new ParticleColor(1, 1, 1, options.alphaMax),
      ),
      emissionOverTime: emission,
      behaviors: [
        new ForceOverLife(
          forceX,
          new ConstantValue(options.gravity),
          forceZ,
        ),
        new ColorOverLife(
          new Gradient(
            undefined,
            [
              [0, 0],
              [1, 0.08],
              [1, 0.9],
              [0, 1],
            ],
          ),
        ),
        new PrecipitationOcclusionBehavior(
          () => this.precipitationOcclusionSampler,
        ),
      ],
      material: this.material,
      renderMode: RenderMode.BillBoard,
      renderOrder: 7,
    });
    system.emitter.name = 'Wide character snowfall volume emitter';
    // Scaling a full sphere creates a broad ellipsoid around the player. It
    // has real depth in every view direction and cannot expose a rectangular
    // emitter edge when the OTS camera turns.
    system.emitter.scale.set(1, options.verticalScale, 1);
    this.scene.add(system.emitter);
    this.renderer.addSystem(system);
    return {
      system,
      emission,
      forceX,
      forceZ,
      shape,
      centerHeight: options.centerHeight,
    };
  }

  private createWindLayer(): WindLayer {
    const emission = new ConstantValue(0);
    const forceX = new ConstantValue(0);
    const forceZ = new ConstantValue(0);
    const shape = new RectangleEmitter({
      width: 100,
      height: 80,
      thickness: 1,
    });
    const system = new ParticleSystem({
      looping: true,
      duration: 4,
      worldSpace: true,
      shape,
      startLife: new IntervalValue(3.2, 5.1),
      startSpeed: new IntervalValue(1.2, 2.8),
      startRotation: new IntervalValue(0, Math.PI * 2),
      startSize: new IntervalValue(0.045, 0.09),
      startColor: new ColorRange(
        new ParticleColor(0.65, 0.9, 0.94, 0.3),
        new ParticleColor(0.92, 1, 1, 0.62),
      ),
      emissionOverTime: emission,
      behaviors: [
        new ForceOverLife(
          forceX,
          new ConstantValue(0.015),
          forceZ,
        ),
      ],
      material: this.windMaterial,
      renderMode: RenderMode.StretchedBillBoard,
      rendererEmitterSettings: {
        speedFactor: 1.8,
        lengthFactor: 6.2,
      },
      renderOrder: 7,
    });
    system.emitter.name = 'Visible wind streak emitter';
    system.emitter.position.y = 7;
    system.emitter.rotation.x = -Math.PI / 2;
    this.scene.add(system.emitter);
    this.renderer.addSystem(system);
    return {
      system,
      emission,
      forceX,
      forceZ,
      shape,
    };
  }
}
