import { MathUtils } from 'three';
import { createWorldSocketSnappedTransform } from '../construction/ConstructionSockets';
import {
  survivalBuildDefinition,
  survivalBuildSocketsCompatible,
  type SurvivalBuildPieceDefinition,
  type SurvivalBuildPieceId,
  type SurvivalBuildSocketDefinition,
} from './SurvivalBuildingCatalog';

export type SurvivalBuildPlacementIntent =
  | 'GROUND_GRID'
  | 'EXTEND_EDGE'
  | 'CONTINUE_RUN'
  | 'STACK'
  | 'ATTACH';

export interface SurvivalBuildConnectionLike {
  readonly targetPieceId: string;
  readonly targetSocketId: string;
  readonly sourceSocketId: string;
}

export interface SurvivalBuildPlacementPiece {
  readonly id: string;
  readonly definitionId: SurvivalBuildPieceId;
  readonly x: number;
  readonly y: number;
  readonly z: number;
  readonly yawDegrees: number;
  readonly mirrored?: boolean;
  readonly connection?: SurvivalBuildConnectionLike;
}

export interface SurvivalBuildSurfaceHit {
  readonly pieceId: string;
  readonly x: number;
  readonly y: number;
  readonly z: number;
  readonly normalX: number;
  readonly normalY: number;
  readonly normalZ: number;
  readonly assisted?: boolean;
}

export interface SurvivalBuildPlacementAim {
  readonly x: number;
  readonly y: number;
  readonly z: number;
  /** Horizontal camera/reticle direction, used only to break a centre-hit tie. */
  readonly forwardX: number;
  readonly forwardZ: number;
  readonly hit?: SurvivalBuildSurfaceHit;
}

export interface SurvivalBuildSocketHint {
  readonly key: string;
  readonly pieceId: string;
  readonly socketId: string;
  readonly x: number;
  readonly y: number;
  readonly z: number;
  readonly selected: boolean;
}

export interface SurvivalBuildPlacementResolution {
  readonly x: number;
  readonly y: number;
  readonly z: number;
  readonly yawDegrees: number;
  readonly intent: SurvivalBuildPlacementIntent;
  readonly targetPieceId?: string;
  readonly snapKey?: string;
  readonly connection?: SurvivalBuildConnectionLike;
  readonly socketHints: readonly SurvivalBuildSocketHint[];
}

interface WorldSocket {
  readonly key: string;
  readonly canonicalKey: string;
  readonly piece: SurvivalBuildPlacementPiece;
  readonly definition: SurvivalBuildPieceDefinition;
  readonly socket: SurvivalBuildSocketDefinition;
  readonly x: number;
  readonly y: number;
  readonly z: number;
  readonly normalX: number;
  readonly normalY: number;
  readonly normalZ: number;
}

interface ScoredPlacement {
  readonly score: number;
  readonly tieKey: string;
  readonly target: WorldSocket;
  readonly source: SurvivalBuildSocketDefinition;
  readonly transform: Readonly<{ x: number; y: number; z: number; yawDegrees: number }>;
}

const SOCKET_CAPTURE_METRES = 1.08;
const HOST_SOCKET_CAPTURE_METRES = 1.55;
const STICKY_SCORE_BONUS = 0.34;
const HIT_HOST_SCORE_BONUS = 0.82;

const normalizeDegrees = (degrees: number): number =>
  ((degrees + 180) % 360 + 360) % 360 - 180;

const rotateXZ = (
  x: number,
  z: number,
  yawDegrees: number,
): readonly [number, number] => {
  const yaw = MathUtils.degToRad(yawDegrees);
  return [
    x * Math.cos(yaw) + z * Math.sin(yaw),
    -x * Math.sin(yaw) + z * Math.cos(yaw),
  ];
};

export const mirrorSurvivalBuildSocket = (
  socket: Readonly<SurvivalBuildSocketDefinition>,
  mirrored: boolean,
): SurvivalBuildSocketDefinition => mirrored
  ? {
      ...socket,
      position: { ...socket.position, z: -socket.position.z },
      normal: { ...socket.normal, z: -socket.normal.z },
    }
  : socket;

const canonicalCoordinate = (value: number): number => Math.round(value * 1_000);

/**
 * A physical join has one identity even if two neighbouring modules expose
 * coincident sockets with opposite normals. Socket kind keeps unrelated
 * utilities from reserving a structural join at the same world coordinate.
 */
export const canonicalSurvivalBuildSocketKey = (
  kind: SurvivalBuildSocketDefinition['kind'],
  x: number,
  y: number,
  z: number,
): string => `${kind}:${canonicalCoordinate(x)}:${canonicalCoordinate(y)}:${canonicalCoordinate(z)}`;

const resolveWorldSocket = (
  piece: SurvivalBuildPlacementPiece,
  definition: SurvivalBuildPieceDefinition,
  originalSocket: SurvivalBuildSocketDefinition,
): WorldSocket => {
  const socket = mirrorSurvivalBuildSocket(originalSocket, piece.mirrored ?? false);
  const [offsetX, offsetZ] = rotateXZ(
    socket.position.x,
    socket.position.z,
    piece.yawDegrees,
  );
  const [normalX, normalZ] = rotateXZ(
    socket.normal.x,
    socket.normal.z,
    piece.yawDegrees,
  );
  const x = piece.x + offsetX;
  const y = piece.y + socket.position.y;
  const z = piece.z + offsetZ;
  return {
    key: `${piece.id}:${socket.id}`,
    canonicalKey: canonicalSurvivalBuildSocketKey(socket.kind, x, y, z),
    piece,
    definition,
    socket,
    x,
    y,
    z,
    normalX,
    normalY: socket.normal.y,
    normalZ,
  };
};

const allWorldSockets = (
  pieces: readonly SurvivalBuildPlacementPiece[],
): readonly WorldSocket[] => pieces.flatMap((piece) => {
  const definition = survivalBuildDefinition(piece.definitionId);
  return definition.sockets.map((socket) => resolveWorldSocket(piece, definition, socket));
});

const occupiedSocketKeys = (
  pieces: readonly SurvivalBuildPlacementPiece[],
  sockets: readonly WorldSocket[],
): Readonly<{ direct: ReadonlySet<string>; canonical: ReadonlySet<string> }> => {
  const direct = new Set<string>();
  const canonical = new Set<string>();
  const byKey = new Map(sockets.map((socket) => [socket.key, socket] as const));
  for (const piece of pieces) {
    const connection = piece.connection;
    if (!connection) continue;
    const targetKey = `${connection.targetPieceId}:${connection.targetSocketId}`;
    const sourceKey = `${piece.id}:${connection.sourceSocketId}`;
    direct.add(targetKey);
    direct.add(sourceKey);
    const target = byKey.get(targetKey);
    const source = byKey.get(sourceKey);
    if (target) canonical.add(target.canonicalKey);
    if (source) canonical.add(source.canonicalKey);
  }
  return { direct, canonical };
};

const oppositeSocketId = (id: string): string | undefined => {
  if (id === 'left') return 'right';
  if (id === 'right') return 'left';
  if (id === 'north') return 'south';
  if (id === 'south') return 'north';
  if (id === 'east') return 'west';
  if (id === 'west') return 'east';
  if (id === 'top') return 'bottom';
  if (id === 'bottom') return 'top';
  return undefined;
};

const sourceMatePenalty = (
  target: SurvivalBuildSocketDefinition,
  source: SurvivalBuildSocketDefinition,
): number => {
  const opposite = oppositeSocketId(target.id);
  if (opposite === source.id) return 0;
  if (target.id === source.id) return 0.28;
  if (target.kind === source.kind) return 0.08;
  return 0.14;
};

const socketDistance = (
  socket: WorldSocket,
  aim: SurvivalBuildPlacementAim,
): number => Math.hypot(socket.x - aim.x, socket.y - aim.y, socket.z - aim.z);

/**
 * Wall fixtures share one logical socket address on both faces of a wall. The
 * face itself comes from the pointed surface, so a player standing indoors is
 * never offered the matching point on the far/outdoor side. Keeping one
 * canonical address also prevents two fixtures from silently occupying the
 * same piece of wall back-to-back.
 */
const wallMountTargetOnAimedFace = (
  target: WorldSocket,
  aim: SurvivalBuildPlacementAim,
  belongsToHit: boolean,
): WorldSocket => {
  if (target.socket.kind !== 'WALL_MOUNT' || !belongsToHit) return target;
  const hitHorizontalLength = aim.hit
    ? Math.hypot(aim.hit.normalX, aim.hit.normalZ)
    : 0;
  const desiredX = hitHorizontalLength > 0.35
    ? aim.hit!.normalX / hitHorizontalLength
    : -aim.forwardX;
  const desiredZ = hitHorizontalLength > 0.35
    ? aim.hit!.normalZ / hitHorizontalLength
    : -aim.forwardZ;
  const authoredDot = target.normalX * desiredX + target.normalZ * desiredZ;
  if (authoredDot >= 0) return target;
  return {
    ...target,
    normalX: -target.normalX,
    normalZ: -target.normalZ,
  };
};

const normalizedHorizontal = (
  x: number,
  z: number,
): readonly [number, number] => {
  const length = Math.hypot(x, z);
  return length > 0.0001 ? [x / length, z / length] : [0, 1];
};

const resolveSocketTransform = (
  target: WorldSocket,
  source: SurvivalBuildSocketDefinition,
  manualYawDegrees: number,
  selectedDefinition: SurvivalBuildPieceDefinition,
): Readonly<{ x: number; y: number; z: number; yawDegrees: number }> | undefined => {
  if (
    target.socket.kind === 'ROOF_EDGE' &&
    source.kind === 'GROUND_FOOT' &&
    selectedDefinition.family === 'WALL'
  ) {
    // A floor-edge socket describes its outward normal. A wall's long local X
    // axis belongs on the edge tangent, while its bottom stays on the edge.
    const tangentX = -target.normalZ;
    const tangentZ = target.normalX;
    const yawDegrees = normalizeDegrees(
      MathUtils.radToDeg(Math.atan2(-tangentZ, tangentX)) + manualYawDegrees,
    );
    const [sourceX, sourceZ] = rotateXZ(source.position.x, source.position.z, yawDegrees);
    return {
      x: target.x - sourceX,
      y: target.y - source.position.y,
      z: target.z - sourceZ,
      yawDegrees,
    };
  }
  const verticalPair = Math.abs(target.normalY) > 0.7 && Math.abs(source.normal.y) > 0.7;
  if (verticalPair) {
    // A vertical normal cannot define yaw. Preserve the host's readable run and
    // treat R as a deliberate relative adjustment instead of an absolute yaw.
    const yawDegrees = normalizeDegrees(target.piece.yawDegrees + manualYawDegrees);
    const [sourceX, sourceZ] = rotateXZ(source.position.x, source.position.z, yawDegrees);
    return {
      x: target.x - sourceX,
      y: target.y - source.position.y,
      z: target.z - sourceZ,
      yawDegrees,
    };
  }
  return createWorldSocketSnappedTransform({
    target: {
      position: { x: target.x, y: target.y, z: target.z },
      normal: { x: target.normalX, y: target.normalY, z: target.normalZ },
    },
    source,
    yawOffsetDegrees: manualYawDegrees,
  });
};

const placementIntent = (
  target: WorldSocket,
  selectedDefinition: SurvivalBuildPieceDefinition,
): SurvivalBuildPlacementIntent => {
  if (Math.abs(target.normalY) > 0.7) return 'STACK';
  if (target.definition.family === selectedDefinition.family) {
    return selectedDefinition.family === 'SURFACE' ? 'EXTEND_EDGE' : 'CONTINUE_RUN';
  }
  return 'ATTACH';
};

/**
 * Build V2's pure intention resolver. It favours the object and face under the
 * pointer, then selects one deterministic compatible socket pair. The actual
 * socket transform remains shared with the vessel builder.
 */
export const resolveSurvivalBuildPlacementV2 = (options: Readonly<{
  definition: SurvivalBuildPieceDefinition;
  pieces: readonly SurvivalBuildPlacementPiece[];
  aim: SurvivalBuildPlacementAim;
  groundYawDegrees: number;
  socketYawOffsetDegrees: number;
  mirrored: boolean;
  stickySocketKey?: string;
  sampleTerrainHeight: (x: number, z: number) => number;
  defaultGridMetres: number;
}>): SurvivalBuildPlacementResolution => {
  const {
    definition,
    pieces,
    aim,
    groundYawDegrees,
    socketYawOffsetDegrees,
    mirrored,
    stickySocketKey,
    sampleTerrainHeight,
    defaultGridMetres,
  } = options;
  const sockets = allWorldSockets(pieces);
  const occupied = occupiedSocketKeys(pieces, sockets);
  const hitPiece = aim.hit
    ? pieces.find((piece) => piece.id === aim.hit?.pieceId)
    : undefined;
  const [forwardX, forwardZ] = normalizedHorizontal(aim.forwardX, aim.forwardZ);
  const scored: ScoredPlacement[] = [];
  const hintScores = new Map<string, number>();

  for (const authoredTarget of sockets) {
    if (
      authoredTarget.socket.placementRole === 'SOURCE' ||
      occupied.direct.has(authoredTarget.key) ||
      occupied.canonical.has(authoredTarget.canonicalKey)
    ) continue;
    const belongsToHit = authoredTarget.piece.id === hitPiece?.id;
    const target = wallMountTargetOnAimedFace(authoredTarget, aim, belongsToHit);
    const distance = socketDistance(target, aim);
    const captureDistance = belongsToHit ? HOST_SOCKET_CAPTURE_METRES : SOCKET_CAPTURE_METRES;
    if (distance > captureDistance) continue;

    for (const originalSource of definition.sockets) {
      if (originalSource.placementRole === 'TARGET') continue;
      const source = mirrorSurvivalBuildSocket(originalSource, mirrored);
      if (!survivalBuildSocketsCompatible(target.socket, source)) continue;
      const transform = resolveSocketTransform(
        target,
        source,
        socketYawOffsetDegrees,
        definition,
      );
      if (!transform) continue;

      let score = distance + sourceMatePenalty(target.socket, source);
      if (belongsToHit) score -= HIT_HOST_SCORE_BONUS;
      if (target.key === stickySocketKey) score -= STICKY_SCORE_BONUS;
      if (target.definition.family === definition.family) score -= 0.09;

      if (aim.hit && belongsToHit) {
        const normalDot = MathUtils.clamp(
          target.normalX * aim.hit.normalX +
            target.normalY * aim.hit.normalY +
            target.normalZ * aim.hit.normalZ,
          -1,
          1,
        );
        score += (1 - normalDot) * 0.2;

        const relativeX = aim.hit.x - target.piece.x;
        const relativeZ = aim.hit.z - target.piece.z;
        const nearHostCentre = Math.hypot(relativeX, relativeZ) < 0.45;
        if (nearHostCentre && Math.hypot(target.normalX, target.normalZ) > 0.5) {
          const directionDot = target.normalX * forwardX + target.normalZ * forwardZ;
          score += (1 - directionDot) * 0.16;
        }
      }

      const tieKey = `${target.key}:${source.id}`;
      scored.push({ score, tieKey, target, source, transform });
      hintScores.set(target.key, Math.min(hintScores.get(target.key) ?? Number.POSITIVE_INFINITY, score));
    }
  }

  scored.sort((a, b) => a.score - b.score || a.tieKey.localeCompare(b.tieKey));
  const selected = scored[0];
  const hints = [...hintScores]
    .sort((a, b) => a[1] - b[1] || a[0].localeCompare(b[0]))
    .slice(0, 4)
    .map(([key]): SurvivalBuildSocketHint => {
      const socket = sockets.find((candidate) => candidate.key === key)!;
      return {
        key,
        pieceId: socket.piece.id,
        socketId: socket.socket.id,
        x: socket.x,
        y: socket.y,
        z: socket.z,
        selected: key === selected?.target.key,
      };
    });

  if (selected) {
    return {
      ...selected.transform,
      intent: placementIntent(selected.target, definition),
      targetPieceId: selected.target.piece.id,
      snapKey: selected.target.key,
      connection: {
        targetPieceId: selected.target.piece.id,
        targetSocketId: selected.target.socket.id,
        sourceSocketId: selected.source.id,
      },
      socketHints: hints,
    };
  }

  const gridMetres = definition.placementGridMetres ?? defaultGridMetres;
  const x = Math.round(aim.x / gridMetres) * gridMetres;
  const z = Math.round(aim.z / gridMetres) * gridMetres;
  return {
    x,
    y: sampleTerrainHeight(x, z),
    z,
    yawDegrees: normalizeDegrees(groundYawDegrees),
    intent: 'GROUND_GRID',
    socketHints: hints,
  };
};

const rectangleAxes = (yawDegrees: number): readonly [
  readonly [number, number],
  readonly [number, number],
] => {
  const yaw = MathUtils.degToRad(yawDegrees);
  return [
    [Math.cos(yaw), -Math.sin(yaw)],
    [Math.sin(yaw), Math.cos(yaw)],
  ];
};

/** Oriented XZ footprint test used by both ghost and commit validation. */
export const survivalBuildFootprintsOverlap = (
  first: Readonly<{ x: number; z: number; yawDegrees: number; halfWidth: number; halfDepth: number }>,
  second: Readonly<{ x: number; z: number; yawDegrees: number; halfWidth: number; halfDepth: number }>,
  separationEpsilon = 0.025,
): boolean => {
  const firstAxes = rectangleAxes(first.yawDegrees);
  const secondAxes = rectangleAxes(second.yawDegrees);
  const deltaX = second.x - first.x;
  const deltaZ = second.z - first.z;
  for (const [axisX, axisZ] of [...firstAxes, ...secondAxes]) {
    const distance = Math.abs(deltaX * axisX + deltaZ * axisZ);
    const firstRadius =
      first.halfWidth * Math.abs(firstAxes[0][0] * axisX + firstAxes[0][1] * axisZ) +
      first.halfDepth * Math.abs(firstAxes[1][0] * axisX + firstAxes[1][1] * axisZ);
    const secondRadius =
      second.halfWidth * Math.abs(secondAxes[0][0] * axisX + secondAxes[0][1] * axisZ) +
      second.halfDepth * Math.abs(secondAxes[1][0] * axisX + secondAxes[1][1] * axisZ);
    if (distance >= firstRadius + secondRadius - separationEpsilon) return false;
  }
  return true;
};

const buildPieceEndpoint = (
  piece: Readonly<{
    x: number;
    z: number;
    yawDegrees: number;
    halfWidth: number;
  }>,
  side: -1 | 1,
): readonly [number, number] => {
  const yaw = MathUtils.degToRad(piece.yawDegrees);
  return [
    piece.x + Math.cos(yaw) * piece.halfWidth * side,
    piece.z - Math.sin(yaw) * piece.halfWidth * side,
  ];
};

/**
 * Narrow structural logs are allowed to meet at one shared endpoint even
 * when their thickness makes the two oriented footprint rectangles overlap.
 * This is what lets a snapped foundation turn 45/90 degrees without the
 * collision guard mistaking the intentional timber joint for an intrusion.
 */
export const survivalBuildFoundationEndpointsMeet = (
  first: Readonly<{
    x: number;
    z: number;
    yawDegrees: number;
    halfWidth: number;
  }>,
  second: Readonly<{
    x: number;
    z: number;
    yawDegrees: number;
    halfWidth: number;
  }>,
  toleranceMetres = 0.075,
): boolean => {
  const firstEndpoints = [
    buildPieceEndpoint(first, -1),
    buildPieceEndpoint(first, 1),
  ];
  const secondEndpoints = [
    buildPieceEndpoint(second, -1),
    buildPieceEndpoint(second, 1),
  ];
  return firstEndpoints.some(([firstX, firstZ]) =>
    secondEndpoints.some(([secondX, secondZ]) =>
      Math.hypot(firstX - secondX, firstZ - secondZ) <= toleranceMetres
    )
  );
};
