import type {
  PlayerId,
  ServerTick,
  TransactionId,
} from '../../netcode/core/NetworkPrimitives';
import type { ReliableAuthorityOperation } from '../../netcode/protocol/AuthorityIngress';
import {
  cloneReplicatedConstructionSite,
  MAX_CONSTRUCTION_PIECES_PER_MESSAGE,
  MAX_CONSTRUCTION_PIECES_PER_SITE,
  MAX_CONSTRUCTION_SITES,
  type ConstructionBlueprintDelta,
  type ConstructionBlueprintMetadata,
  type ConstructionResourcePolicy,
  type ConstructionSiteAccessPolicy,
  type ReplicatedConstructionSite,
  validateConstructionStateDeltaPayload,
} from '../../netcode/protocol/ConstructionReplication';
