import { ICEAWAY_TARGET_WORLD_PARTITION } from '../../world/WorldPartitionTypes';

export const BOREALIS_SHARED_CONSTRUCTION_SITE_ID =
  'construction-site:borealis-yard';

export interface MultiplayerConstructionAuthorityCheckpoint {
  readonly version: 1;
  readonly revision: number;
  readonly nextPieceSequence: number;
  readonly sites: readonly ReplicatedConstructionSite[];
  readonly transactionJournal: readonly ConstructionTransactionJournalEntry[];
}

export interface ConstructionTransactionJournalEntry {
  readonly requestId: TransactionId;
  readonly fingerprint: string;
  readonly result: Omit<ConstructionAuthorityOperationResult, 'replayed'>;
}

export interface ConstructionAuthorityOperationContext {
  readonly serverTick: ServerTick;
  readonly actorIsHost: boolean;
  readonly actorPosition: Readonly<GlobalPosition>;
}

export interface ConstructionResourceMutation {
  readonly requestId: TransactionId;
  readonly serverTick: ServerTick;
  readonly operation: ConstructionBlueprintDelta['operation'];
  readonly actorPlayerId: PlayerId;
  readonly site: Readonly<ReplicatedConstructionSite>;
  readonly before: Readonly<ConstructionBlueprint>;
  readonly after: Readonly<ConstructionBlueprint>;
}

export interface ConstructionResourceAuthorizationResult {
  readonly accepted: boolean;
  readonly status: string;
  readonly contentRevision?: number;
}

export interface MultiplayerConstructionAuthorityOptions {
  readonly checkpoint?: Readonly<MultiplayerConstructionAuthorityCheckpoint>;
  readonly initialSites?: readonly Readonly<ReplicatedConstructionSite>[];
  readonly maximumSites?: number;
  readonly maximumPiecesPerSite?: number;
  readonly maximumRememberedTransactions?: number;
  readonly interactionRadiusMetres?: number;
  readonly authorizeResourceMutation?: (
    mutation: Readonly<ConstructionResourceMutation>,
  ) => ConstructionResourceAuthorizationResult;
}

export interface ConstructionAuthorityOperationResult {
  readonly accepted: boolean;
  readonly status: string;
  readonly stateChanged: boolean;
  readonly revision: number;
  readonly blueprintRevision?: number;
  readonly delta?: ConstructionBlueprintDelta;
  readonly replayed: boolean;
}

interface MutableConstructionSite {
  siteId: string;
  anchor: GlobalPosition;
  access: ConstructionSiteAccessPolicy;
  resources: ConstructionResourcePolicy;
  blueprint: ConstructionBlueprint;
}

interface PendingMutation {
  operation: ConstructionBlueprintDelta['operation'];
  blueprint: ConstructionBlueprint;
  upsertedPlacements: ConstructionPlacement[];
  removedPlacementIds: string[];
  metadata?: ConstructionBlueprintMetadata;
}

const jsonClone = <T>(value: T): T =>
  JSON.parse(JSON.stringify(value)) as T;

const sameJson = (left: unknown, right: unknown): boolean =>
  deterministicStateHash(left) === deterministicStateHash(right);

const deterministicTimestamp = (tick: ServerTick): string =>
  new Date(Math.floor(Number(tick) * 1_000 / 60)).toISOString();

const metadataOf = (
  blueprint: Readonly<ConstructionBlueprint>,
): ConstructionBlueprintMetadata => {
  const { placements: _placements, ...metadata } = blueprint;
  return { ...metadata, palette: { ...metadata.palette } };
};

const blueprintWithPlacements = (
  source: Readonly<ConstructionBlueprint>,
  placements: readonly Readonly<ConstructionPlacement>[],
): ConstructionBlueprint => ({
  ...source,
  palette: { ...source.palette },
  placements: placements.map(cloneConstructionPlacement),
});

const mountHostId = (
  placement: Readonly<ConstructionPlacement>,
): string | undefined =>
  placement.mount.kind === 'surface'
    ? placement.mount.hostPlacementId
    : placement.mount.connection?.hostPlacementId;

const dependentClosure = (
  blueprint: Readonly<ConstructionBlueprint>,
  rootId: string,
): Set<string> => {
  const closure = new Set([rootId]);
  let changed = true;
  while (changed) {
    changed = false;
    for (const placement of blueprint.placements) {
      const hostId = mountHostId(placement);
      if (hostId && closure.has(hostId) && !closure.has(placement.id)) {
        closure.add(placement.id);
        changed = true;
      }
    }
  }
  return closure;
};

const horizontallySupported = (
  candidate: Readonly<ConstructionPlacement>,
  blueprint: Readonly<ConstructionBlueprint>,
): boolean => {
  const definition = getConstructionModule(candidate.moduleId);
  if (!definition) return false;
  const candidateBounds = constructionPlacementBounds(candidate, definition);
  if (candidateBounds.minY <= 0.01) return true;
  for (const support of blueprint.placements) {
    if (support.id === candidate.id || support.mount.kind === 'surface') continue;
    const supportDefinition = getConstructionModule(support.moduleId);
    if (!supportDefinition) continue;
    const bounds = constructionPlacementBounds(support, supportDefinition);
    if (Math.abs(bounds.maxY - candidateBounds.minY) > 0.03) continue;
    const overlapX = Math.min(bounds.maxX, candidateBounds.maxX) -
      Math.max(bounds.minX, candidateBounds.minX);
    const overlapZ = Math.min(bounds.maxZ, candidateBounds.maxZ) -
      Math.max(bounds.minZ, candidateBounds.minZ);
    if (overlapX > 0.05 && overlapZ > 0.05) return true;
  }
  return false;
};

const validateWholeBlueprint = (
  blueprint: Readonly<ConstructionBlueprint>,
  maximumPieces: number,
): string | undefined => {
  if (blueprint.placements.length > maximumPieces) return 'SITE_PIECE_LIMIT';
  const sanitized = sanitizeConstructionBlueprint(blueprint);
  if (!sanitized || !sameJson(sanitized, blueprint)) {
    return 'INVALID_BLUEPRINT_DATA';
  }
  for (const placement of blueprint.placements) {
    const withoutCandidate = blueprintWithPlacements(
      blueprint,
      blueprint.placements.filter((candidate) => candidate.id !== placement.id),
    );
    const validation = validateConstructionPlacement(withoutCandidate, placement);
    if (!validation.accepted) return `INVALID_PLACEMENT:${validation.reason ?? 'UNKNOWN'}`;
    if (
      placement.mount.kind === 'grid' &&
      !placement.mount.connection &&
      !horizontallySupported(placement, blueprint)
    ) return 'UNSUPPORTED_PLACEMENT';
  }
  const connections = validateConstructionConnections(blueprint);
  return connections.accepted ? undefined : connections.reason ?? 'INVALID_CONNECTION';
};

const defaultSharedSite = (): ReplicatedConstructionSite => {
  const createdAt = new Date(0);
  const blueprint = createConstructionBlueprint(
    'Borealis shared construction yard',
    createdAt,
    'harbor-facility',
  );
  blueprint.id = 'construction-blueprint:borealis-yard';
  return {
    siteId: BOREALIS_SHARED_CONSTRUCTION_SITE_ID,
    anchor: prototypeLocalToGlobalPosition({ x: -39.5, y: 0, z: 22 }),
    access: { mode: 'SHARED' },
    resources: { mode: 'DEV_UNLIMITED' },
    blueprint,
  };
};

/**
 * Canonical, renderer-free building authority. Every accepted edit is one
 * revision transition and yields a compact replayable blueprint delta.
 */
export class MultiplayerConstructionAuthority {
  private readonly sites = new Map<string, MutableConstructionSite>();
  private readonly transactionJournal = new Map<
    TransactionId,
    ConstructionTransactionJournalEntry
  >();
  private readonly transactionOrder: TransactionId[] = [];
  private readonly maximumSites: number;
  private readonly maximumPiecesPerSite: number;
  private readonly maximumRememberedTransactions: number;
  private readonly interactionRadiusMetres: number;
  private readonly resourceAuthorizer?: MultiplayerConstructionAuthorityOptions['authorizeResourceMutation'];
  private revisionValue = 0;
  private nextPieceSequence = 1;

  public constructor(
    options: Readonly<MultiplayerConstructionAuthorityOptions> = {},
  ) {
    this.maximumSites = options.maximumSites ?? MAX_CONSTRUCTION_SITES;
    this.maximumPiecesPerSite =
      options.maximumPiecesPerSite ?? MAX_CONSTRUCTION_PIECES_PER_SITE;
    this.maximumRememberedTransactions =
      options.maximumRememberedTransactions ?? 2_048;
    this.interactionRadiusMetres = options.interactionRadiusMetres ?? 120;
    this.resourceAuthorizer = options.authorizeResourceMutation;
    if (
      !Number.isSafeInteger(this.maximumSites) ||
      this.maximumSites < 1 ||
      this.maximumSites > MAX_CONSTRUCTION_SITES ||
      !Number.isSafeInteger(this.maximumPiecesPerSite) ||
      this.maximumPiecesPerSite < 1 ||
      this.maximumPiecesPerSite > MAX_CONSTRUCTION_PIECES_PER_SITE ||
      !Number.isSafeInteger(this.maximumRememberedTransactions) ||
      this.maximumRememberedTransactions < 128 ||
      !Number.isFinite(this.interactionRadiusMetres) ||
      this.interactionRadiusMetres < 1
    ) throw new Error('Invalid multiplayer construction authority limits.');

    if (options.checkpoint) {
      this.restoreCheckpoint(options.checkpoint);
      return;
    }
    const initial = options.initialSites ?? [defaultSharedSite()];
    if (initial.length > this.maximumSites) {
      throw new Error('Too many initial multiplayer construction sites.');
    }
    for (const site of initial) this.restoreSite(site);
  }

  public get revision(): number {
    return this.revisionValue;
  }

  public listSites(): readonly ReplicatedConstructionSite[] {
    return [...this.sites.values()]
      .sort((left, right) => left.siteId.localeCompare(right.siteId))
      .map((site) => cloneReplicatedConstructionSite(site));
  }

  public getSite(siteId: string): ReplicatedConstructionSite | undefined {
    const site = this.sites.get(siteId);
    return site ? cloneReplicatedConstructionSite(site) : undefined;
  }

  public processOperation(
    operation: Readonly<ReliableAuthorityOperation>,
    context: Readonly<ConstructionAuthorityOperationContext>,
  ): ConstructionAuthorityOperationResult {
    const fingerprint = deterministicStateHash({
      playerId: operation.playerId,
      channel: operation.channel,
      operation: operation.operation,
      observedRevision: operation.observedRevision,
      payload: operation.payload,
    });
    const remembered = this.transactionJournal.get(operation.requestId);
    if (remembered) {
      if (remembered.fingerprint !== fingerprint) {
        return this.reject('OPERATION_ID_CONFLICT', true);
      }
      return { ...jsonClone(remembered.result), replayed: true };
    }
    if (operation.channel !== 'CONSTRUCTION') {
      return this.remember(operation.requestId, fingerprint, this.reject(
        'INVALID_CONSTRUCTION_CHANNEL',
      ));
    }
    const siteId = operation.payload.siteId;
    if (typeof siteId !== 'string' || siteId.length === 0 || siteId.length > 160) {
      return this.remember(operation.requestId, fingerprint, this.reject(
        'INVALID_CONSTRUCTION_SITE_ID',
      ));
    }
    const site = this.sites.get(siteId);
    if (!site) {
      return this.remember(operation.requestId, fingerprint, this.reject(
        'UNKNOWN_CONSTRUCTION_SITE',
      ));
    }
    const accessRejection = this.accessRejection(site, operation.playerId, context);
    if (accessRejection) {
      return this.remember(
        operation.requestId,
        fingerprint,
        this.reject(accessRejection),
      );
    }
    if (
      operation.observedRevision === undefined ||
      Number(operation.observedRevision) !== site.blueprint.revision
    ) {
      return this.remember(operation.requestId, fingerprint, this.reject(
        'STALE_BLUEPRINT_REVISION',
        false,
        site.blueprint.revision,
      ));
    }

    const mutation = this.prepareMutation(site, operation);
    if (typeof mutation === 'string') {
      return this.remember(
        operation.requestId,
        fingerprint,
        this.reject(mutation, false, site.blueprint.revision),
      );
    }
    const validationFailure = validateWholeBlueprint(
      mutation.blueprint,
      this.maximumPiecesPerSite,
    );
    if (validationFailure) {
      return this.remember(
        operation.requestId,
        fingerprint,
        this.reject(validationFailure, false, site.blueprint.revision),
      );
    }
    const resourceResult = this.authorizeResources(
      operation,
      context.serverTick,
      site,
      mutation,
    );
    if (!resourceResult.accepted) {
      return this.remember(
        operation.requestId,
        fingerprint,
        this.reject(resourceResult.status, false, site.blueprint.revision),
      );
    }

    const baseBlueprintRevision = site.blueprint.revision;
    const baseRevision = this.revisionValue;
    mutation.blueprint.revision = baseBlueprintRevision + 1;
    mutation.blueprint.updatedAt = deterministicTimestamp(context.serverTick);
    site.blueprint = mutation.blueprint;
    if (
      site.resources.mode === 'AUTHORITY_INVENTORY' &&
      resourceResult.contentRevision !== undefined
    ) {
      site.resources = {
        ...site.resources,
        contentRevision: resourceResult.contentRevision,
      };
    }
    this.revisionValue = baseRevision + 1;
    const delta: ConstructionBlueprintDelta = {
      requestId: operation.requestId,
      actorPlayerId: operation.playerId,
      operation: mutation.operation,
      siteId: site.siteId,
      blueprintId: site.blueprint.id,
      baseBlueprintRevision,
      blueprintRevision: site.blueprint.revision,
      upsertedPlacements: mutation.upsertedPlacements.map(
        cloneConstructionPlacement,
      ),
      removedPlacementIds: [...mutation.removedPlacementIds],
      // Metadata is small and carries the canonical updatedAt/revision fence
      // for every structural delta, so clients never synthesize timestamps.
      metadata: metadataOf(site.blueprint),
      resources: site.resources.mode === 'AUTHORITY_INVENTORY'
        ? { ...site.resources }
        : { mode: 'DEV_UNLIMITED' },
    };
    return this.remember(operation.requestId, fingerprint, {
      accepted: true,
      status: 'CONSTRUCTION_COMMITTED',
      stateChanged: true,
      revision: this.revisionValue,
      blueprintRevision: site.blueprint.revision,
      delta,
      replayed: false,
    });
  }

  public resultFor(
    operation: Readonly<ReliableAuthorityOperation>,
  ): ConstructionAuthorityOperationResult | undefined {
    const entry = this.transactionJournal.get(operation.requestId);
    if (!entry) return undefined;
    const fingerprint = deterministicStateHash({
      playerId: operation.playerId,
      channel: operation.channel,
      operation: operation.operation,
      observedRevision: operation.observedRevision,
      payload: operation.payload,
    });
    return entry.fingerprint === fingerprint
      ? { ...jsonClone(entry.result), replayed: true }
      : this.reject('OPERATION_ID_CONFLICT', true);
  }

  public exportCheckpoint(): MultiplayerConstructionAuthorityCheckpoint {
    return {
      version: 1,
      revision: this.revisionValue,
      nextPieceSequence: this.nextPieceSequence,
      sites: this.listSites(),
      transactionJournal: this.transactionOrder.map((requestId) =>
        jsonClone(this.transactionJournal.get(requestId)!)),
    };
  }

  private restoreCheckpoint(
    checkpoint: Readonly<MultiplayerConstructionAuthorityCheckpoint>,
  ): void {
    if (
      checkpoint.version !== 1 ||
      !Number.isSafeInteger(checkpoint.revision) ||
      checkpoint.revision < 0 ||
      !Number.isSafeInteger(checkpoint.nextPieceSequence) ||
      checkpoint.nextPieceSequence < 1 ||
      checkpoint.sites.length > this.maximumSites ||
      checkpoint.transactionJournal.length > this.maximumRememberedTransactions
    ) throw new Error('Invalid multiplayer construction checkpoint.');
    for (const site of checkpoint.sites) this.restoreSite(site);
    const maximumBlueprintRevision = Math.max(
      0,
      ...[...this.sites.values()].map((site) => site.blueprint.revision),
    );
    if (checkpoint.revision < maximumBlueprintRevision) {
      throw new Error('Construction checkpoint revision precedes a site revision.');
    }
    let maximumAuthorityPieceSequence = 0;
    for (const site of this.sites.values()) {
      const prefix = `piece:${site.siteId}:`;
      for (const placement of site.blueprint.placements) {
        if (!placement.id.startsWith(prefix)) continue;
        const sequence = Number(placement.id.slice(prefix.length));
        if (!Number.isSafeInteger(sequence) || sequence < 1) {
          throw new Error('Construction checkpoint contains an invalid piece ID.');
        }
        maximumAuthorityPieceSequence = Math.max(
          maximumAuthorityPieceSequence,
          sequence,
        );
      }
    }
    if (checkpoint.nextPieceSequence <= maximumAuthorityPieceSequence) {
      throw new Error('Construction checkpoint would reuse a stable piece ID.');
    }
    const requestIds = new Set<TransactionId>();
    for (const entry of checkpoint.transactionJournal) {
      if (
        requestIds.has(entry.requestId) ||
        typeof entry.fingerprint !== 'string' ||
        !entry.fingerprint ||
        typeof entry.result?.accepted !== 'boolean' ||
        typeof entry.result?.status !== 'string' ||
        !Number.isSafeInteger(entry.result?.revision) ||
        entry.result.revision < 0 ||
        entry.result.revision > checkpoint.revision ||
        entry.result.stateChanged !== entry.result.accepted ||
        (entry.result.accepted && !entry.result.delta) ||
        (!entry.result.accepted && entry.result.delta !== undefined) ||
        (entry.result.delta !== undefined &&
          (!validateConstructionStateDeltaPayload({
            version: 1,
            kind: 'CONSTRUCTION_STATE_DELTA',
            baseRevision: entry.result.revision - 1,
            revision: entry.result.revision,
            serverTick: 0,
            change: entry.result.delta,
          }) || entry.result.delta.requestId !== entry.requestId))
      ) throw new Error('Invalid construction transaction journal.');
      requestIds.add(entry.requestId);
      const cloned = jsonClone(entry);
      this.transactionJournal.set(entry.requestId, cloned);
      this.transactionOrder.push(entry.requestId);
    }
    this.revisionValue = checkpoint.revision;
    this.nextPieceSequence = checkpoint.nextPieceSequence;
  }

  private restoreSite(input: Readonly<ReplicatedConstructionSite>): void {
    if (
      this.sites.has(input.siteId) ||
      typeof input.siteId !== 'string' ||
      input.siteId.length < 1 ||
      input.siteId.length > 160 ||
      !isGlobalPositionInPartition(ICEAWAY_TARGET_WORLD_PARTITION, input.anchor)
    ) throw new Error('Invalid or duplicate multiplayer construction site.');
    const blueprint = sanitizeConstructionBlueprint(input.blueprint);
    if (!blueprint || !sameJson(blueprint, input.blueprint)) {
      throw new Error(`Invalid blueprint for construction site ${input.siteId}.`);
    }
    const validationFailure = validateWholeBlueprint(
      blueprint,
      this.maximumPiecesPerSite,
    );
    if (validationFailure) {
      throw new Error(
        `Invalid construction site ${input.siteId}: ${validationFailure}.`,
      );
    }
    if (
      input.access.mode !== 'SHARED' &&
      input.access.mode !== 'HOST_ONLY' &&
      (input.access.mode !== 'OWNER_ONLY' || !input.access.ownerPlayerId)
    ) throw new Error('Invalid construction access policy.');
    if (
      input.resources.mode !== 'DEV_UNLIMITED' &&
      (input.resources.mode !== 'AUTHORITY_INVENTORY' ||
        !input.resources.containerId ||
        !Number.isSafeInteger(input.resources.contentRevision) ||
        input.resources.contentRevision < 0)
    ) throw new Error('Invalid construction resource policy.');
    this.sites.set(input.siteId, cloneReplicatedConstructionSite(input));
  }

  private accessRejection(
    site: Readonly<MutableConstructionSite>,
    actorPlayerId: PlayerId,
    context: Readonly<ConstructionAuthorityOperationContext>,
  ): string | undefined {
    if (
      site.access.mode === 'HOST_ONLY' && !context.actorIsHost ||
      site.access.mode === 'OWNER_ONLY' &&
        site.access.ownerPlayerId !== actorPlayerId
    ) return 'CONSTRUCTION_ACCESS_DENIED';
    if (!isGlobalPositionInPartition(
      ICEAWAY_TARGET_WORLD_PARTITION,
      context.actorPosition,
    )) return 'INVALID_ACTOR_POSITION';
    if (
      globalPositionDistanceMetres(
        ICEAWAY_TARGET_WORLD_PARTITION,
        site.anchor,
        context.actorPosition,
      ) > this.interactionRadiusMetres
    ) return 'CONSTRUCTION_SITE_OUT_OF_RANGE';
    return undefined;
  }

  private prepareMutation(
    site: Readonly<MutableConstructionSite>,
    operation: Readonly<ReliableAuthorityOperation>,
  ): PendingMutation | string {
    switch (operation.operation) {
      case 'PLACE_PIECE':
        return this.preparePlace(site, operation.payload.placement);
      case 'MOVE_PIECES':
        return this.prepareMove(
          site,
          operation.payload.rootPlacementId,
          operation.payload.placements,
        );
      case 'REMOVE_PIECE':
        return this.prepareRemove(site, operation.payload.placementId);
      case 'CONFIGURE_PIECE':
        return this.prepareConfigurePiece(site, operation.payload.placement);
      case 'CONFIGURE_BLUEPRINT':
        return this.prepareConfigureBlueprint(site, operation.payload);
      default:
        return 'UNSUPPORTED_CONSTRUCTION_OPERATION';
    }
  }

  private preparePlace(
    site: Readonly<MutableConstructionSite>,
    input: unknown,
  ): PendingMutation | string {
    const candidate = sanitizeConstructionPlacement(input);
    if (!candidate) return 'INVALID_PLACEMENT_PAYLOAD';
    const placement = cloneConstructionPlacement(candidate);
    placement.id = `piece:${site.siteId}:${this.nextPieceSequence}`;
    const blueprint = cloneConstructionBlueprint(site.blueprint);
    blueprint.placements.push(placement);
    // Consume an identity only once the operation is otherwise structurally valid.
    const validationFailure = validateWholeBlueprint(
      blueprint,
      this.maximumPiecesPerSite,
    );
    if (validationFailure) return validationFailure;
    this.nextPieceSequence += 1;
    return {
      operation: 'PLACE_PIECE',
      blueprint,
      upsertedPlacements: [placement],
      removedPlacementIds: [],
    };
  }

  private prepareMove(
    site: Readonly<MutableConstructionSite>,
    rootInput: unknown,
    placementsInput: unknown,
  ): PendingMutation | string {
    if (
      typeof rootInput !== 'string' ||
      rootInput.length === 0 ||
      !Array.isArray(placementsInput) ||
      placementsInput.length < 1 ||
      placementsInput.length > MAX_CONSTRUCTION_PIECES_PER_MESSAGE
    ) return 'INVALID_MOVE_PAYLOAD';
    const currentById = new Map(
      site.blueprint.placements.map((placement) => [placement.id, placement] as const),
    );
    if (!currentById.has(rootInput)) return 'UNKNOWN_PLACEMENT';
    const closure = dependentClosure(site.blueprint, rootInput);
    if (closure.size !== placementsInput.length) return 'INCOMPLETE_MOVE_CLOSURE';
    const replacements = new Map<string, ConstructionPlacement>();
    for (const raw of placementsInput) {
      const replacement = sanitizeConstructionPlacement(raw);
      const current = replacement ? currentById.get(replacement.id) : undefined;
      if (!replacement || !current || replacements.has(replacement.id)) {
        return 'INVALID_MOVE_PAYLOAD';
      }
      if (!closure.has(replacement.id)) return 'MOVE_CLOSURE_MISMATCH';
      if (!sameJson(
        {
          moduleId: replacement.moduleId,
          materialId: replacement.materialId,
          surfaceId: replacement.surfaceId,
          shape: replacement.shape,
          decals: replacement.decals,
          machineState: replacement.machineState,
        },
        {
          moduleId: current.moduleId,
          materialId: current.materialId,
          surfaceId: current.surfaceId,
          shape: current.shape,
          decals: current.decals,
          machineState: current.machineState,
        },
      )) return 'MOVE_CHANGED_CONFIGURATION';
      replacements.set(replacement.id, replacement);
    }
    const blueprint = blueprintWithPlacements(
      site.blueprint,
      site.blueprint.placements.map(
        (placement) => replacements.get(placement.id) ?? placement,
      ),
    );
    return {
      operation: 'MOVE_PIECES',
      blueprint,
      upsertedPlacements: [...replacements.values()],
      removedPlacementIds: [],
    };
  }

  private prepareRemove(
    site: Readonly<MutableConstructionSite>,
    placementId: unknown,
  ): PendingMutation | string {
    if (typeof placementId !== 'string' || !placementId) {
      return 'INVALID_REMOVE_PAYLOAD';
    }
    if (!site.blueprint.placements.some((placement) => placement.id === placementId)) {
      return 'UNKNOWN_PLACEMENT';
    }
    const blueprint = cloneConstructionBlueprint(site.blueprint);
    const removedPlacementIds = removeConstructionPlacementTree(
      blueprint,
      placementId,
    ).sort();
    const original = new Map(
      site.blueprint.placements.map((placement) => [placement.id, placement] as const),
    );
    const upsertedPlacements = blueprint.placements.filter(
      (placement) => !sameJson(placement, original.get(placement.id)),
    );
    return {
      operation: 'REMOVE_PIECE',
      blueprint,
      upsertedPlacements,
      removedPlacementIds,
    };
  }

  private prepareConfigurePiece(
    site: Readonly<MutableConstructionSite>,
    input: unknown,
  ): PendingMutation | string {
    const replacement = sanitizeConstructionPlacement(input);
    if (!replacement) return 'INVALID_CONFIGURATION_PAYLOAD';
    const current = site.blueprint.placements.find(
      (placement) => placement.id === replacement.id,
    );
    if (!current) return 'UNKNOWN_PLACEMENT';
    if (!sameJson(
      {
        id: replacement.id,
        moduleId: replacement.moduleId,
        position: replacement.position,
        yawDegrees: replacement.yawDegrees,
        pitchDegrees: replacement.pitchDegrees,
        rollDegrees: replacement.rollDegrees,
        flipped: replacement.flipped,
        mount: replacement.mount,
      },
      {
        id: current.id,
        moduleId: current.moduleId,
        position: current.position,
        yawDegrees: current.yawDegrees,
        pitchDegrees: current.pitchDegrees,
        rollDegrees: current.rollDegrees,
        flipped: current.flipped,
        mount: current.mount,
      },
    )) return 'CONFIGURATION_CHANGED_STRUCTURE';
    const definition = getConstructionModule(replacement.moduleId)!;
    if (replacement.shape && !definition.shapeEditing) return 'SHAPE_NOT_SUPPORTED';
    if (replacement.machineState && !definition.mechanism) {
      return 'MACHINE_STATE_NOT_SUPPORTED';
    }
    const decalSlots = new Set(definition.decalSlots?.map((slot) => slot.id) ?? []);
    if (replacement.decals?.some((decal) => !decalSlots.has(decal.slotId))) {
      return 'INVALID_DECAL_SLOT';
    }
    const blueprint = blueprintWithPlacements(
      site.blueprint,
      site.blueprint.placements.map((placement) =>
        placement.id === replacement.id ? replacement : placement),
    );
    return {
      operation: 'CONFIGURE_PIECE',
      blueprint,
      upsertedPlacements: [replacement],
      removedPlacementIds: [],
    };
  }

  private prepareConfigureBlueprint(
    site: Readonly<MutableConstructionSite>,
    payload: Readonly<Record<string, unknown>>,
  ): PendingMutation | string {
    const name = payload.name ?? site.blueprint.name;
    const palette = payload.palette ?? site.blueprint.palette;
    if (
      typeof name !== 'string' ||
      name.trim().length < 1 ||
      name.length > 80 ||
      !palette ||
      typeof palette !== 'object'
    ) {
      return 'INVALID_BLUEPRINT_CONFIGURATION';
    }
    if (payload.palette !== undefined) {
      const candidate = palette as Partial<ConstructionPalette>;
      const keys = Object.keys(site.blueprint.palette) as Array<keyof ConstructionPalette>;
      if (keys.some((key) =>
        typeof candidate[key] !== 'string' ||
        !/^(#[0-9a-f]{6}|#[0-9a-f]{3})$/i.test(candidate[key]!))) {
        return 'INVALID_BLUEPRINT_CONFIGURATION';
      }
    }
    const blueprint = sanitizeConstructionBlueprint({
      ...site.blueprint,
      name: name.trim(),
      palette,
    });
    if (!blueprint) return 'INVALID_BLUEPRINT_CONFIGURATION';
    if (
      blueprint.name === site.blueprint.name &&
      sameJson(blueprint.palette, site.blueprint.palette)
    ) return 'NO_CONSTRUCTION_CHANGE';
    return {
      operation: 'CONFIGURE_BLUEPRINT',
      blueprint,
      upsertedPlacements: [],
      removedPlacementIds: [],
      metadata: metadataOf(blueprint),
    };
  }

  private authorizeResources(
    operation: Readonly<ReliableAuthorityOperation>,
    tick: ServerTick,
    site: Readonly<MutableConstructionSite>,
    mutation: Readonly<PendingMutation>,
  ): ConstructionResourceAuthorizationResult {
    if (site.resources.mode === 'DEV_UNLIMITED') {
      return { accepted: true, status: 'DEV_UNLIMITED' };
    }
    if (!this.resourceAuthorizer) {
      return { accepted: false, status: 'RESOURCE_AUTHORITY_UNAVAILABLE' };
    }
    const result = this.resourceAuthorizer({
      requestId: operation.requestId,
      serverTick: tick,
      operation: mutation.operation,
      actorPlayerId: operation.playerId,
      site: cloneReplicatedConstructionSite(site),
      before: cloneConstructionBlueprint(site.blueprint),
      after: cloneConstructionBlueprint(mutation.blueprint),
    });
    if (
      result.accepted &&
      (!Number.isSafeInteger(result.contentRevision) ||
        result.contentRevision! < site.resources.contentRevision)
    ) return {
      accepted: false,
      status: 'INVALID_RESOURCE_AUTHORITY_REVISION',
    };
    return result;
  }

  private reject(
    status: string,
    replayed = false,
    blueprintRevision?: number,
  ): ConstructionAuthorityOperationResult {
    return {
      accepted: false,
      status,
      stateChanged: false,
      revision: this.revisionValue,
      ...(blueprintRevision === undefined ? {} : { blueprintRevision }),
      replayed,
    };
  }

  private remember(
    requestId: TransactionId,
    fingerprint: string,
    result: ConstructionAuthorityOperationResult,
  ): ConstructionAuthorityOperationResult {
    const { replayed: _replayed, ...storedResult } = jsonClone(result);
    const entry: ConstructionTransactionJournalEntry = {
      requestId,
      fingerprint,
      result: storedResult,
    };
    this.transactionJournal.set(requestId, entry);
    this.transactionOrder.push(requestId);
    while (this.transactionOrder.length > this.maximumRememberedTransactions) {
      const expired = this.transactionOrder.shift();
      if (expired) this.transactionJournal.delete(expired);
    }
    return result;
  }
}
