export const wildernessCreekCenterX = (z: number): number =>
  WILDERNESS_SURVIVAL_REGION.creekX +
  Math.sin((z - WILDERNESS_SURVIVAL_REGION.centerZ) * 0.085) * 2.4;

/** 0..1 deterministic centre-line velocity from grade and constrictions. */
export const wildernessCreekFlowAt = (z: number): number => {
  const localZ = z - WILDERNESS_SURVIVAL_REGION.centerZ;
  const gradePulse = 0.5 + Math.sin(localZ * 0.071 - 0.85) * 0.5;
  const constrictionPulse = 0.5 + Math.sin(localZ * 0.163 + 1.7) * 0.5;
  return Math.max(0.12, Math.min(
    1,
    0.2 + gradePulse * 0.42 + constrictionPulse ** 3 * 0.46,
  ));
};

export const wildernessCreekOpenHalfWidth = (z: number): number => {
  const flow = wildernessCreekFlowAt(z);
  return flow <= 0.42 ? 0 : 0.16 + (flow - 0.42) * 2.15;
};

export const isWildernessOpenWaterAt = (
  x: number,
  z: number,
  padding = 0,
): boolean => {
  if (Math.abs(z - WILDERNESS_SURVIVAL_REGION.centerZ) > 64 + padding) return false;
  const openHalfWidth = wildernessCreekOpenHalfWidth(z);
  return openHalfWidth > 0 &&
    Math.abs(x - wildernessCreekCenterX(z)) < Math.max(0, openHalfWidth + padding);
};

export const isWildernessCreekAt = (
  x: number,
  z: number,
  padding = 0,
): boolean => Math.abs(x - wildernessCreekCenterX(z)) <= 3.3 + padding &&
  Math.abs(z - WILDERNESS_SURVIVAL_REGION.centerZ) <= 64 + padding;

export const isWildernessLakeAt = (
  x: number,
  z: number,
  padding = 0,
): boolean => WILDERNESS_FROZEN_LAKES.some((lake) => {
  const nx = (x - lake.x) / (lake.radiusX + padding);
  const nz = (z - lake.z) / (lake.radiusZ + padding);
  return nx * nx + nz * nz <= 1;
});

export const isWildernessFrozenWaterAt = (
  x: number,
  z: number,
  padding = 0,
): boolean => isWildernessCreekAt(x, z, padding) ||
  isWildernessLakeAt(x, z, padding);

