export const wildernessHabitatForSpecies = (
  species: string,
  ordinal: number,
): WildernessWildlifeHabitat | undefined => {
  const candidates = WILDERNESS_WILDLIFE_HABITATS.filter((habitat) =>
    habitat.species.includes(species));
  return candidates.length > 0
    ? candidates[Math.abs(ordinal) % candidates.length]
    : undefined;
};

