export type WildernessGroundScatterKind = 'ROCK' | 'SHRUB' | 'BRANCH';
export interface WildernessGroundScatter {
  readonly kind: WildernessGroundScatterKind;
  readonly x: number;
  readonly z: number;
  readonly scale: number;
  readonly heading: number;
}

const createGroundScatter = (): readonly WildernessGroundScatter[] => {
  const result: WildernessGroundScatter[] = [];
  for (let index = 0; index < 420 && result.length < 270; index += 1) {
    const angle = hash2D(index, 1709, 1721) * Math.PI * 2;
    const radius = 7 + Math.sqrt(hash2D(index, 1723, 1733)) * 69;
    const x = WILDERNESS_SURVIVAL_REGION.centerX + Math.cos(angle) * radius;
    const z = WILDERNESS_SURVIVAL_REGION.centerZ + Math.sin(angle) * radius;
    if (isWildernessFrozenWaterAt(x, z, 0.8)) continue;
    if (Math.hypot(
      x - WILDERNESS_SURVIVAL_REGION.spawnX,
      z - WILDERNESS_SURVIVAL_REGION.spawnZ,
    ) < 5.5) continue;
    const selector = hash2D(index, 1741, 1747);
    const kind: WildernessGroundScatterKind = selector < 0.42
      ? 'ROCK'
      : selector < 0.76
        ? 'SHRUB'
        : 'BRANCH';
    result.push({
      kind,
      x,
      z,
      scale: kind === 'ROCK'
        ? 0.28 + hash2D(index, 1753, 1759) * 0.42
        : kind === 'SHRUB'
          ? 0.34 + hash2D(index, 1777, 1783) * 0.52
          : 0.55 + hash2D(index, 1787, 1789) * 0.58,
      heading: hash2D(index, 1801, 1811) * Math.PI * 2,
    });
  }
  return result;
};

export const WILDERNESS_GROUND_SCATTER = createGroundScatter();

export type WildernessUnderstoryNiche =
  | 'FOREST_FLOOR'
  | 'HEATH'
  | 'MEADOW'
  | 'CREEK_BANK'
  | 'ROCKY';

export type WildernessUnderstoryPrefabId =
  | 'UNDERSTORY_GRASS_FINE_01'
  | 'UNDERSTORY_GRASS_TUFT_02'
  | 'UNDERSTORY_GRASS_TALL_03'
  | 'UNDERSTORY_GRASS_DRY_04'
  | 'UNDERSTORY_HEATH_SHORT_01'
  | 'UNDERSTORY_HEATH_TALL_02'
  | 'UNDERSTORY_SHRUB_DWARF_01'
  | 'UNDERSTORY_SHRUB_ROUND_02'
  | 'UNDERSTORY_SHRUB_DETAIL_03'
  | 'UNDERSTORY_SHRUB_LOW_04'
  | 'UNDERSTORY_SHRUB_ANGULAR_05'
  | 'UNDERSTORY_SHRUB_LARGE_06';

export interface WildernessUnderstory {
  readonly x: number;
  readonly z: number;
  readonly scale: number;
  readonly heading: number;
  readonly prefabId: WildernessUnderstoryPrefabId;
  readonly niche: WildernessUnderstoryNiche;
  /** Browsers such as deer can deliberately uncover this plant from snow. */
  readonly edible: boolean;
}

const understoryPrefabFor = (
  niche: WildernessUnderstoryNiche,
  selector: number,
): WildernessUnderstoryPrefabId => {
  if (niche === 'CREEK_BANK') {
    return selector < 0.36
      ? 'UNDERSTORY_GRASS_TALL_03'
      : selector < 0.68
        ? 'UNDERSTORY_GRASS_TUFT_02'
        : 'UNDERSTORY_HEATH_TALL_02';
  }
  if (niche === 'MEADOW') {
    return selector < 0.42
      ? 'UNDERSTORY_GRASS_FINE_01'
      : selector < 0.72
        ? 'UNDERSTORY_GRASS_DRY_04'
        : 'UNDERSTORY_SHRUB_DWARF_01';
  }
  if (niche === 'ROCKY') {
    return selector < 0.5
      ? 'UNDERSTORY_HEATH_SHORT_01'
      : selector < 0.8
        ? 'UNDERSTORY_SHRUB_ANGULAR_05'
        : 'UNDERSTORY_SHRUB_LOW_04';
  }
  if (niche === 'FOREST_FLOOR') {
    return selector < 0.3
      ? 'UNDERSTORY_HEATH_SHORT_01'
      : selector < 0.55
        ? 'UNDERSTORY_SHRUB_DWARF_01'
        : selector < 0.76
          ? 'UNDERSTORY_SHRUB_DETAIL_03'
          : selector < 0.9
            ? 'UNDERSTORY_GRASS_TUFT_02'
            : 'UNDERSTORY_SHRUB_LARGE_06';
  }
  return selector < 0.34
    ? 'UNDERSTORY_HEATH_SHORT_01'
    : selector < 0.62
      ? 'UNDERSTORY_HEATH_TALL_02'
      : selector < 0.84
        ? 'UNDERSTORY_SHRUB_ROUND_02'
        : 'UNDERSTORY_SHRUB_LOW_04';
};

/**
 * Deterministic clustered undergrowth. Plants sit on the terrain rather than
 * the snow surface: deep snow hides them, shallow snow exposes tips and a
 * cleared patch reveals the whole plant without a per-frame visibility pass.
 */
const createUnderstory = (): readonly WildernessUnderstory[] => {
  const result: WildernessUnderstory[] = [];
  const clusterCount = 92;
  for (let cluster = 0; cluster < clusterCount; cluster += 1) {
    const angle = hash2D(cluster, 1877, 1889) * Math.PI * 2;
    const radius = 10 + Math.sqrt(hash2D(cluster, 1901, 1907)) * 64;
    const centerX = WILDERNESS_SURVIVAL_REGION.centerX + Math.cos(angle) * radius;
    const centerZ = WILDERNESS_SURVIVAL_REGION.centerZ + Math.sin(angle) * radius;
    const creekDistance = Math.abs(centerX - wildernessCreekCenterX(centerZ));
    const ridgeDistance = Math.hypot(centerX + 864, centerZ + 187);
    const meadowDistance = Math.min(
      Math.hypot(centerX + 822, centerZ + 202),
      Math.hypot(centerX + 832, centerZ + 249),
    );
    const forestDensity = WILDERNESS_FOREST_PATCHES.reduce((best, patch) => {
      const nx = (centerX - patch.x) / patch.radiusX;
      const nz = (centerZ - patch.z) / patch.radiusZ;
      return Math.max(best, 1 - Math.sqrt(nx * nx + nz * nz));
    }, 0);
    const niche: WildernessUnderstoryNiche = creekDistance < 6.5
      ? 'CREEK_BANK'
      : ridgeDistance < 25
        ? 'ROCKY'
        : meadowDistance < 13
          ? 'MEADOW'
          : forestDensity > 0.18
            ? 'FOREST_FLOOR'
            : 'HEATH';
    const count = 5 + Math.floor(hash2D(cluster, 1913, 1931) * 8);
    const clusterRadius = niche === 'CREEK_BANK' ? 4.8 : niche === 'MEADOW' ? 5.6 : 3.8;
    for (let item = 0; item < count; item += 1) {
      const sequence = cluster * 17 + item;
      const localAngle = hash2D(sequence, 1933, 1949) * Math.PI * 2;
      const localRadius = Math.sqrt(hash2D(sequence, 1951, 1973)) * clusterRadius;
      const x = centerX + Math.cos(localAngle) * localRadius;
      const z = centerZ + Math.sin(localAngle) * localRadius;
      if (Math.hypot(
        x - WILDERNESS_SURVIVAL_REGION.centerX,
        z - WILDERNESS_SURVIVAL_REGION.centerZ,
      ) > WILDERNESS_SURVIVAL_REGION.radius - 1.5) continue;
      if (isWildernessOpenWaterAt(x, z, 0.55)) continue;
      if (Math.hypot(
        x - WILDERNESS_SURVIVAL_REGION.spawnX,
        z - WILDERNESS_SURVIVAL_REGION.spawnZ,
      ) < 4.5) continue;
      const selector = hash2D(sequence, 1979, 1987);
      const prefabId = understoryPrefabFor(niche, selector);
      result.push({
        x,
        z,
        prefabId,
        niche,
        edible: niche !== 'ROCKY' && (
          prefabId.includes('HEATH') || prefabId.includes('SHRUB')
        ),
        scale: 0.68 + hash2D(sequence, 1993, 1997) * 0.72,
        heading: hash2D(sequence, 1999, 2003) * Math.PI * 2,
      });
    }
  }
  return result;
};

export const WILDERNESS_UNDERSTORY = createUnderstory();

const createSceneryTrees = (): readonly WildernessSceneryTree[] => {
  const trees: WildernessSceneryTree[] = [];
  let sequence = 0;
  for (const [patchIndex, patch] of WILDERNESS_FOREST_PATCHES.entries()) {
    let accepted = 0;
    for (let attempt = 0; attempt < patch.count * 3 && accepted < patch.count; attempt += 1) {
      const angle = hash2D(sequence, patchIndex * 31 + 181, 12011) * Math.PI * 2;
      // sqrt gives an even area distribution; the secondary low-frequency
      // radius modulation keeps the silhouette from reading as an ellipse.
      const radius = Math.sqrt(hash2D(sequence, patchIndex * 37 + 191, 12037));
      const edgeNoise = 0.84 + hash2D(sequence, patchIndex * 41 + 193, 12041) * 0.28;
      const x = patch.x + Math.cos(angle) * radius * patch.radiusX * edgeNoise;
      const z = patch.z + Math.sin(angle) * radius * patch.radiusZ * edgeNoise;
      sequence += 1;
      if (Math.hypot(
        x - WILDERNESS_SURVIVAL_REGION.centerX,
        z - WILDERNESS_SURVIVAL_REGION.centerZ,
      ) > WILDERNESS_SURVIVAL_REGION.radius - 2) continue;
      if (isWildernessFrozenWaterAt(x, z, 1.35)) continue;
      // Old walking routes are narrow, but their immediate shoulder must
      // remain readable and traversable instead of passing through trunks.
      if (isWinterWorldRouteAt(x, z, 1.35)) continue;
      if (Math.hypot(
        x - WILDERNESS_SURVIVAL_REGION.spawnX,
        z - WILDERNESS_SURVIVAL_REGION.spawnZ,
      ) < 8.5) continue;
      // Preserve two legible open snow meadows rather than filling every gap.
      if (
        Math.hypot(x + 822, z + 202) < 10.5 ||
        Math.hypot(x + 832, z + 249) < 8.5
      ) continue;
      trees.push({
        x,
        z,
        // Neighbouring trees share a little stand age while retaining enough
        // individual variation to avoid a repeated height profile.
        scale: (() => {
          const individual = hash2D(sequence, patchIndex * 43 + 197, 12049);
          const standAge = hash2D(
            Math.floor(x / 9),
            Math.floor(z / 9),
            patchIndex * 211 + 12079,
          );
          const maturity = Math.min(1, individual * 0.68 + standAge * 0.42);
          return patch.scaleMinimum +
            Math.pow(maturity, 0.78) *
            (patch.scaleMaximum - patch.scaleMinimum);
        })(),
        heading: hash2D(sequence, patchIndex * 47 + 199, 12071) * Math.PI * 2,
        prefabId: (() => {
          const selector = hash2D(sequence, patchIndex * 53 + 211, 12073);
          if (patch.id === 'east-creek-scrub') {
            return selector < 0.46
              ? 'CONIFER_SPRUCE_04'
              : selector < 0.74
                ? 'DECIDUOUS_BARE_03'
                : 'CONIFER_SPRUCE_02';
          }
          if (patch.id === 'north-grove') {
            return selector < 0.38
              ? 'CONIFER_SPRUCE_03'
              : selector < 0.65
                ? 'CONIFER_SPRUCE_05'
                : selector < 0.82
                  ? 'DECIDUOUS_BARE_03'
                  : 'CONIFER_SPRUCE_01';
          }
          return selector < 0.4
            ? 'CONIFER_SPRUCE_01'
            : selector < 0.61
              ? 'CONIFER_SPRUCE_02'
              : selector < 0.76
                ? 'CONIFER_SPRUCE_03'
                : selector < 0.88
                  ? 'CONIFER_SPRUCE_04'
                  : selector < 0.96
                    ? 'CONIFER_SPRUCE_05'
                    : 'DECIDUOUS_BARE_03';
        })(),
      });
      accepted += 1;
    }
  }
  return trees;
};

export const WILDERNESS_SCENERY_TREES = createSceneryTrees();

/**
 * A low-cost snow-covered tree belt bridges the old empty gap between the
 * authored survival grove and generated-world ecology. These silhouettes are
 * deliberately outside the main interaction space: they close the horizon
 * and make forest rooms without adding hundreds of colliders or AI objects.
 */
const createHorizonTrees = (): readonly WildernessHorizonTree[] => {
  const trees: WildernessHorizonTree[] = [];
  const innerRadius = 82;
  const outerRadius = 124;
  for (let attempt = 0; attempt < 1_650 && trees.length < 760; attempt += 1) {
    const angle = hash2D(attempt, 12721, 12739) * Math.PI * 2;
    const radialBlend = Math.sqrt(hash2D(attempt, 12743, 12757));
    const radius = innerRadius + (outerRadius - innerRadius) * radialBlend;
    const broadStand = 0.5 +
      Math.sin(angle * 3.0 - 0.7) * 0.22 +
      Math.sin(angle * 7.0 + 1.3) * 0.12;
    if (hash2D(attempt, 12763, 12781) > broadStand + 0.28) continue;
    const x = WILDERNESS_SURVIVAL_REGION.centerX +
      Math.cos(angle) * radius +
      (hash2D(attempt, 12791, 12799) - 0.5) * 8;
    const z = WILDERNESS_SURVIVAL_REGION.centerZ +
      Math.sin(angle) * radius +
      (hash2D(attempt, 12809, 12821) - 0.5) * 8;
    if (isWildernessFrozenWaterAt(x, z, 1.6)) continue;
    const variant = hash2D(attempt, 12823, 12829);
    const standHeight = hash2D(
      Math.floor(x / 13),
      Math.floor(z / 13),
      12841,
    );
    const detailedMidDistance = radius < 105;
    trees.push({
      x,
      z,
      heading: hash2D(attempt, 12853, 12889) * Math.PI * 2,
      scale: 0.82 + standHeight * 0.54 +
        hash2D(attempt, 12893, 12907) * 0.48,
      prefabId: detailedMidDistance
        ? variant < 0.23
          ? 'CONIFER_SPRUCE_01'
          : variant < 0.45
            ? 'CONIFER_SPRUCE_02'
            : variant < 0.66
              ? 'CONIFER_SPRUCE_03'
              : variant < 0.84
                ? 'CONIFER_SPRUCE_04'
                : 'CONIFER_SPRUCE_05'
        : variant < 0.72
          ? 'NATURE_FOREST_HLOD_SPRUCE_01'
          : 'NATURE_FOREST_HLOD_PINE_01',
    });
  }
  return trees;
};

export const WILDERNESS_HORIZON_TREES = createHorizonTrees();

/**
 * Extra settled snow for the authored wilderness terrain profile.
 *
 * This mirrors the same cheap warped waves and named hollows used by the
 * heightfield. Low pockets therefore fill and exposed shoulders scour without
 * running a second terrain simulation or sampling editor geometry per flake.
 */
export const wildernessSnowTopographicFill = (
  x: number,
  z: number,
): number => {
  const distance = Math.hypot(
    x - WILDERNESS_SURVIVAL_REGION.centerX,
    z - WILDERNESS_SURVIVAL_REGION.centerZ,
  );
  const influence = 1 - smoothstep(
    WILDERNESS_SURVIVAL_REGION.radius - 8,
    WILDERNESS_SURVIVAL_REGION.radius + 22,
    distance,
  );
  if (influence <= 0) return 0;
  const warpX = Math.sin(z * 0.031 + x * 0.006 + 0.7) * 4.2;
  const warpZ = Math.sin(x * 0.027 - z * 0.005 - 1.1) * 4.2;
  const noiseX = x + warpX;
  const noiseZ = z + warpZ;
  const rollingRelief =
    Math.sin(noiseX * 0.024 + noiseZ * 0.011 + 1.9) * 0.54 +
    Math.sin(noiseZ * 0.039 - noiseX * 0.009 - 0.4) * 0.27 +
    Math.sin((noiseX - noiseZ) * 0.013) * 0.16;
  const rollingPocket = smoothstep(0.08, 0.72, -rollingRelief) * 0.22;
  const exposedScour = smoothstep(0.3, 0.82, rollingRelief) * 0.09;
  const hollow = (
    centerX: number,
    centerZ: number,
    radiusX: number,
    radiusZ: number,
    depth: number,
  ): number => {
    const nx = (noiseX - centerX) / radiusX;
    const nz = (noiseZ - centerZ) / radiusZ;
    return (1 - smoothstep(0.08, 1, Math.hypot(nx, nz))) * depth;
  };
  const namedHollows = Math.max(
    hollow(-849, -239, 17, 15, 0.42),
    hollow(-804, -247, 22, 17, 0.31),
    hollow(-786, -196, 16, 24, 0.27),
  );
  return (rollingPocket + namedHollows - exposedScour) * influence;
};

/**
 * A deterministic, low-frequency terrain layer. It keeps the wilderness
 * editable: world-builder deltas are still applied on top of this base.
 * Lakes are gently flattened through a wide shore blend so neither movement
 * nor snow receives a sharp seam.
 */
export const applyWildernessTerrainProfile = (
  authoredBaseHeight: number,
  x: number,
  z: number,
): number => {
  const distance = Math.hypot(
    x - WILDERNESS_SURVIVAL_REGION.centerX,
    z - WILDERNESS_SURVIVAL_REGION.centerZ,
  );
  const influence = 1 - smoothstep(
    WILDERNESS_SURVIVAL_REGION.radius - 8,
    WILDERNESS_SURVIVAL_REGION.radius + 22,
    distance,
  );
  if (influence <= 0) return authoredBaseHeight;

  // Terrain height is one of the hottest queries in the game: snow, movement,
  // collisions and presentation can sample it tens of thousands of times in a
  // frame. Keep this profile analytical. The previous domain-warped value
  // noise looked pleasant but multiplied every height query into dozens of
  // hash/interpolation operations and could collapse an active snow scene to
  // single-digit FPS.
  const warpX = Math.sin(z * 0.031 + x * 0.006 + 0.7) * 4.2;
  const warpZ = Math.sin(x * 0.027 - z * 0.005 - 1.1) * 4.2;
  const noiseX = x + warpX;
  const noiseZ = z + warpZ;
  const rollingRelief =
    Math.sin(noiseX * 0.024 + noiseZ * 0.011 + 1.9) * 0.54 +
    Math.sin(noiseZ * 0.039 - noiseX * 0.009 - 0.4) * 0.27 +
    Math.sin((noiseX - noiseZ) * 0.013) * 0.16;
  let height = authoredBaseHeight + rollingRelief * influence;

  const ellipticalFeature = (
    centerX: number,
    centerZ: number,
    radiusX: number,
    radiusZ: number,
    amplitude: number,
    shoulder = 0.12,
  ): number => {
    // Reuse the one continuous domain warp above for every landform. Besides
    // being far cheaper, this keeps adjoining features on exactly the same
    // smooth surface and avoids snow/terrain seams.
    const nx = (noiseX - centerX) / radiusX;
    const nz = (noiseZ - centerZ) / radiusZ;
    const normalized = Math.sqrt(nx * nx + nz * nz);
    const body = 1 - smoothstep(shoulder, 1, normalized);
    return body * amplitude * influence;
  };
  // Broad, overlapping moraines turn the wilderness into a sequence of
  // sheltered rooms. Every compass direction gets a landform before the far
  // render horizon, while saddles keep exploration routes legible.
  height += ellipticalFeature(-821, -158, 63, 17, 10.5, 0.18);
  height += ellipticalFeature(-880, -224, 19, 58, 11.2, 0.16);
  height += ellipticalFeature(-766, -222, 17, 55, 9.6, 0.16);
  height += ellipticalFeature(-817, -281, 57, 16, 8.8, 0.18);

  // Inner ridges, a wind-scoured saddle and deep sheltered hollows break the
  // large silhouette into recognisable local landmarks. Broad interpolation
  // prevents terrain/snow needles while retaining metre-scale relief.
  height += ellipticalFeature(-864, -183, 31, 38, 13.8, 0.26);
  height += ellipticalFeature(-872, -205, 13, 23, 7.5, 0.08);
  height += ellipticalFeature(-847, -266, 31, 18, 6.2, 0.26);
  height += ellipticalFeature(-849, -239, 17, 15, -5.8, 0.16);
  height += ellipticalFeature(-805, -176, 22, 13, 4.8, 0.18);
  height += ellipticalFeature(-804, -247, 22, 17, -3.9, 0.14);
  height += ellipticalFeature(-786, -196, 16, 24, -3.1, 0.12);

  // Give the creek an actual bed and two readable banks. The centre line is
  // still analytical and cheap, but water no longer looks painted over a
  // flat snowfield.
  if (Math.abs(z - WILDERNESS_SURVIVAL_REGION.centerZ) <= 68) {
    const creekDistance = Math.abs(x - wildernessCreekCenterX(z));
    const creekBed = 1 - smoothstep(1.35, 3.25, creekDistance);
    const creekBank = smoothstep(2.15, 3.85, creekDistance) *
      (1 - smoothstep(3.85, 7.4, creekDistance));
    const bankVariation = 0.82 +
      Math.sin(z * 0.19 + Math.sin(z * 0.047) * 1.4) * 0.18;
    height -= creekBed * 0.82 * influence;
    height += creekBank * (0.56 + bankVariation * 0.42) * influence;
  }

  for (const lake of WILDERNESS_FROZEN_LAKES) {
    const nx = (x - lake.x) / lake.radiusX;
    const nz = (z - lake.z) / lake.radiusZ;
    const ellipseDistance = Math.sqrt(nx * nx + nz * nz);
    const lakeBlend = 1 - smoothstep(0.58, 1.04, ellipseDistance);
    if (lakeBlend > 0) height = lerp(height, lake.elevation, lakeBlend);
    const shoreline = smoothstep(0.82, 1.02, ellipseDistance) *
      (1 - smoothstep(1.02, 1.56, ellipseDistance));
    if (shoreline <= 0) continue;
    const shorelineVariation = 0.84 +
      Math.sin((x + z) * 0.42 + lake.x * 0.017) * 0.16;
    height += shoreline * shorelineVariation * 0.92 * influence;
  }
  return height;
};
