import { clamp } from '../utils/math';
import { WILDERNESS_SURVIVAL_REGION } from './WildernessBiome';
import type { WildernessRuneId } from './WildernessRuneCatalog';

export type WildernessLandmarkId =
  | 'OLD_HEARTH_STONE'
  | 'QUIET_GROVE'
  | 'BURIED_GARDEN';

export interface WildernessLandmarkDefinition {
  readonly id: WildernessLandmarkId;
  readonly name: string;
  readonly hint: string;
  readonly x: number;
  readonly z: number;
  readonly runeId: WildernessRuneId;
}

/**
 * Authored discovery anchors are data, not animal AI state. Future world
 * compiler maps can replace these coordinates without rewriting guidance,
 * cartography or rune discovery.
 */
export const WILDERNESS_LANDMARKS: readonly WildernessLandmarkDefinition[] = [
  {
    id: 'OLD_HEARTH_STONE',
    name: 'Old hearth stone',
    hint: 'Warm scoring remains beneath the rime.',
    x: -841,
    z: -204,
    runeId: 'EMBER_WATCH',
  },
  {
    id: 'QUIET_GROVE',
    name: 'Quiet grove',
    hint: 'Animals rest here when the wind is kind.',
    x: -775,
    z: -205,
    runeId: 'CALM_CIRCLE',
  },
  {
    id: 'BURIED_GARDEN',
    name: 'Buried garden',
    hint: 'Old rows wait beneath the long winter.',
    x: -842,
    z: -267,
    runeId: 'GROWTH_PROMISE',
  },
] as const;

export const wildernessLandmark = (
  id: WildernessLandmarkId,
): WildernessLandmarkDefinition | undefined =>
  WILDERNESS_LANDMARKS.find((landmark) => landmark.id === id);

export interface WildernessCartographySaveData {
  readonly version: 1;
  readonly trail: readonly Readonly<{ x: number; z: number }>[];
  readonly visitedCells: readonly string[];
  readonly discoveredLandmarkIds: readonly WildernessLandmarkId[];
}

export interface WildernessCartographyView {
  readonly open: boolean;
  readonly centreX: number;
  readonly centreZ: number;
  readonly radius: number;
  readonly playerX: number;
  readonly playerZ: number;
  readonly trail: readonly Readonly<{ x: number; z: number }>[];
  readonly visitedCells: readonly string[];
  readonly landmarks: readonly WildernessLandmarkDefinition[];
}

const MAP_CELL_METRES = 6;
const TRAIL_STEP_METRES = 1.6;
const MAX_TRAIL_POINTS = 1_400;
const MAX_VISITED_CELLS = 1_600;

export class WildernessCartographySystem {
  private readonly trail: Array<{ x: number; z: number }>;
  private readonly visitedCells: Set<string>;
  private readonly discoveredLandmarks: Set<WildernessLandmarkId>;
  private open = false;
  private playerX: number = WILDERNESS_SURVIVAL_REGION.spawnX;
  private playerZ: number = WILDERNESS_SURVIVAL_REGION.spawnZ;

  public constructor(saved?: Readonly<WildernessCartographySaveData>) {
    this.trail = (saved?.trail ?? []).slice(-MAX_TRAIL_POINTS).map((point) => ({
      x: Number.isFinite(point.x) ? point.x : WILDERNESS_SURVIVAL_REGION.spawnX,
      z: Number.isFinite(point.z) ? point.z : WILDERNESS_SURVIVAL_REGION.spawnZ,
    }));
    this.visitedCells = new Set((saved?.visitedCells ?? []).slice(-MAX_VISITED_CELLS));
    this.discoveredLandmarks = new Set(
      (saved?.discoveredLandmarkIds ?? []).filter((id) => wildernessLandmark(id)),
    );
  }

  public toggle(): boolean {
    this.open = !this.open;
    return this.open;
  }

  public close(): void {
    this.open = false;
  }

  public record(x: number, z: number): void {
    this.playerX = x;
    this.playerZ = z;
    const cellX = Math.floor((x - WILDERNESS_SURVIVAL_REGION.centerX) / MAP_CELL_METRES);
    const cellZ = Math.floor((z - WILDERNESS_SURVIVAL_REGION.centerZ) / MAP_CELL_METRES);
    const key = `${cellX}:${cellZ}`;
    if (!this.visitedCells.has(key) && this.visitedCells.size < MAX_VISITED_CELLS) {
      this.visitedCells.add(key);
    }
    const previous = this.trail.at(-1);
    if (previous && Math.hypot(x - previous.x, z - previous.z) < TRAIL_STEP_METRES) return;
    this.trail.push({ x, z });
    if (this.trail.length > MAX_TRAIL_POINTS) {
      // Keep every second old point and all recent detail. The drawn map stays
      // bounded without forgetting where the player has travelled.
      const old = this.trail.splice(0, Math.floor(MAX_TRAIL_POINTS * 0.55));
      this.trail.unshift(...old.filter((_, index) => index % 2 === 0));
    }
  }

  public discoverLandmark(id: WildernessLandmarkId): boolean {
    if (this.discoveredLandmarks.has(id) || !wildernessLandmark(id)) return false;
    this.discoveredLandmarks.add(id);
    return true;
  }

  public isLandmarkDiscovered(id: WildernessLandmarkId): boolean {
    return this.discoveredLandmarks.has(id);
  }

  public undiscoveredLandmarks(): readonly WildernessLandmarkDefinition[] {
    return WILDERNESS_LANDMARKS.filter((landmark) =>
      !this.discoveredLandmarks.has(landmark.id));
  }

  public view(): WildernessCartographyView {
    return {
      open: this.open,
      centreX: WILDERNESS_SURVIVAL_REGION.centerX,
      centreZ: WILDERNESS_SURVIVAL_REGION.centerZ,
      radius: WILDERNESS_SURVIVAL_REGION.radius,
      playerX: this.playerX,
      playerZ: this.playerZ,
      trail: this.trail,
      visitedCells: [...this.visitedCells],
      landmarks: WILDERNESS_LANDMARKS.filter((landmark) =>
        this.discoveredLandmarks.has(landmark.id)),
    };
  }

  public exportState(): WildernessCartographySaveData {
    return {
      version: 1,
      trail: this.trail.map((point) => ({ ...point })),
      visitedCells: [...this.visitedCells],
      discoveredLandmarkIds: [...this.discoveredLandmarks],
    };
  }

  public static mapPercent(value: number, centre: number, radius: number): number {
    return clamp((value - (centre - radius)) / (radius * 2), 0, 1) * 100;
  }
}
