import type { SettlementSeason } from '../../gameplay/settlement/SettlementTypes';

export interface ClimateRegionDefinition {
  readonly id: string;
  readonly displayName: string;
  readonly season: SettlementSeason;
  readonly centerX: number;
  readonly centerZ: number;
  readonly coreRadiusMetres: number;
  readonly transitionMetres: number;
  readonly temperatureCelsius: number;
  readonly moisture: number;
  readonly precipitationBias: number;
  readonly snowRetention: number;
  readonly growthMultiplier: number;
}

export interface RegionalClimateSample {
  readonly dominantRegionId: string;
  readonly season: SettlementSeason;
  readonly temperatureCelsius: number;
  readonly moisture: number;
  readonly precipitationBias: number;
  readonly snowRetention: number;
  readonly growthMultiplier: number;
  readonly transition: number;
}

const clamp01 = (value: number): number => Math.max(0, Math.min(1, value));
const smoothstep = (value: number): number => {
  const t = clamp01(value);
  return t * t * (3 - 2 * t);
};

