export class RegionalClimateSystem {
  public constructor(
    private readonly regions: readonly Readonly<ClimateRegionDefinition>[] =
      ICEWAY_PROTOTYPE_CLIMATE_REGIONS,
  ) {
    if (regions.length === 0) throw new Error('At least one climate region is required.');
  }

  public sample(x: number, z: number, elevationMetres = 0): RegionalClimateSample {
    const weighted = this.regions.map((region) => {
      const distance = Math.hypot(x - region.centerX, z - region.centerZ);
      const transition = Math.max(1, region.transitionMetres);
      const weight = 1 - smoothstep(
        (distance - region.coreRadiusMetres) / transition,
      );
      return { region, weight: Math.max(0.0001, weight) };
    }).sort((left, right) => right.weight - left.weight);
    const total = weighted.reduce((sum, entry) => sum + entry.weight, 0);
    const dominant = weighted[0]!;
    const blend = (field: keyof Pick<ClimateRegionDefinition,
      'temperatureCelsius' | 'moisture' | 'precipitationBias' |
      'snowRetention' | 'growthMultiplier'>): number =>
      weighted.reduce((sum, entry) => sum + entry.region[field] * entry.weight, 0) / total;
    // Elevation creates snow-capable highlands without a separate hard biome.
    const temperature = blend('temperatureCelsius') - Math.max(0, elevationMetres) * 0.0065;
    return Object.freeze({
      dominantRegionId: dominant.region.id,
      season: dominant.region.season,
      temperatureCelsius: temperature,
      moisture: clamp01(blend('moisture')),
      precipitationBias: clamp01(blend('precipitationBias')),
      snowRetention: temperature > 2 ? 0 : clamp01(blend('snowRetention')),
      growthMultiplier: clamp01(blend('growthMultiplier')),
      transition: clamp01(1 - dominant.weight / total),
    });
  }

  public definitions(): readonly Readonly<ClimateRegionDefinition>[] {
    return this.regions;
  }
}
