import {
  BatchedMesh,
  BufferGeometry,
  Color,
  Float32BufferAttribute,
  FrontSide,
  Matrix4,
  MeshStandardMaterial,
  Quaternion,
  Scene,
  Uint16BufferAttribute,
  Uint8BufferAttribute,
  Vector2,
  Vector3,
  type Camera,
  type WebGLProgramParametersWithUniforms,
} from 'three';
import cloudLibraryJson from './generated/CloudMeshLibraryV2.json';
import { clamp, smoothstep } from '../utils/math';
import type { VolumetricCloudPresentation } from './VolumetricCloudSystem';

export type CloudRendererMode = 'LEGACY_PUFFS' | 'MESH_LIBRARY_V2';

interface PackedCloudGeometry {
  vertexCount: number;
  indexCount: number;
  positionRange: number;
  positions: string;
  normals: string;
  colors: string;
  indices: string;
}

interface PackedCloudRecord {
  id: string;
  family: number;
  activation: number;
  driftScale: number;
  center: readonly [number, number, number];
  scale: readonly [number, number, number];
  phase: number;
  lods: readonly [PackedCloudGeometry, PackedCloudGeometry, PackedCloudGeometry];
}

interface PackedCloudLibrary {
  version: number;
  cloudCount: number;
  worldPeriod: number;
  clouds: PackedCloudRecord[];
}

interface CloudRuntimeRecord {
  source: PackedCloudRecord;
  instanceId: number;
  geometryIds: readonly [number, number, number];
  lod: number;
  visible: boolean;
}

export interface CloudMeshLibraryV2Update {
  opacity: number;
  cover: number;
  arrivalProgress: number;
  clearingProgress: number;
  windOffset: Readonly<Vector2>;
  windDirection: Readonly<Vector2>;
  presentationVisible: boolean;
}

const library = cloudLibraryJson as unknown as PackedCloudLibrary;
const UP = new Vector3(0, 1, 0);

const decodeBytes = (encoded: string): Uint8Array => {
  const decoded = atob(encoded);
  const bytes = new Uint8Array(decoded.length);
  for (let index = 0; index < decoded.length; index += 1) {
    bytes[index] = decoded.charCodeAt(index);
  }
  return bytes;
};

const decodeInt16 = (encoded: string): Int16Array => {
  const bytes = decodeBytes(encoded);
  return new Int16Array(bytes.buffer, bytes.byteOffset, bytes.byteLength / 2);
};

const decodeUint16 = (encoded: string): Uint16Array => {
  const bytes = decodeBytes(encoded);
  return new Uint16Array(bytes.buffer, bytes.byteOffset, bytes.byteLength / 2);
};

export const decodeCloudGeometryV2 = (
  packed: PackedCloudGeometry,
): BufferGeometry => {
  const encodedPositions = decodeInt16(packed.positions);
  const positions = new Float32Array(encodedPositions.length);
  const positionScale = packed.positionRange / 32_767;
  for (let index = 0; index < encodedPositions.length; index += 1) {
    positions[index] = (encodedPositions[index] ?? 0) * positionScale;
  }
  const encodedNormals = new Int8Array(decodeBytes(packed.normals).buffer);
  const normals = new Float32Array(encodedNormals.length);
  for (let index = 0; index < encodedNormals.length; index += 1) {
    normals[index] = (encodedNormals[index] ?? 0) / 127;
  }
  const colors = decodeBytes(packed.colors);
  const indices = decodeUint16(packed.indices);
  const geometry = new BufferGeometry();
  geometry.setAttribute('position', new Float32BufferAttribute(positions, 3));
  geometry.setAttribute('normal', new Float32BufferAttribute(normals, 3));
  geometry.setAttribute('color', new Uint8BufferAttribute(colors, 3, true));
  geometry.setIndex(new Uint16BufferAttribute(indices, 1));
  geometry.computeBoundingBox();
  geometry.computeBoundingSphere();
  return geometry;
};

/**
 * Draws 240 deterministic, individually identified cloud hulls in one
 * BatchedMesh. The offline generator turns broad core lobes and smaller rim
 * lobes into one closed surface, so no internal transparent puff cards remain
 * for the GPU to shade repeatedly.
 */
export class CloudMeshLibrarySystemV2 {
  private readonly material: MeshStandardMaterial;
  private readonly mesh: BatchedMesh;
  private readonly records: CloudRuntimeRecord[] = [];
  private readonly matrix = new Matrix4();
  private readonly position = new Vector3();
  private readonly scale = new Vector3();
  private readonly rotation = new Quaternion();
  private readonly rimColor = new Color(0xffffff);
  private readonly sunDirectionWorld = new Vector3(0.4, 0.7, 0.3);
  private readonly sunDirectionView = new Vector3(0.4, 0.7, 0.3);
  private shader?: WebGLProgramParametersWithUniforms;
  private visibleCount = 0;
  private nearLodCount = 0;
  private middleLodCount = 0;
  private farLodCount = 0;

  public constructor(scene: Scene) {
    let maxVertexCount = 0;
    let maxIndexCount = 0;
    for (const cloud of library.clouds) {
      for (const lod of cloud.lods) {
        maxVertexCount += lod.vertexCount;
        maxIndexCount += lod.indexCount;
      }
    }

    this.material = new MeshStandardMaterial({
      name: 'Cloud mesh library V2 material',
      color: 0xdbe5ea,
      emissive: 0x17212a,
      emissiveIntensity: 0.14,
      roughness: 0.98,
      metalness: 0,
      vertexColors: true,
      transparent: true,
      opacity: 0,
      depthTest: true,
      depthWrite: false,
      side: FrontSide,
      // Terrain fog reaches full density far below the authored cloud deck.
      // Applying it here erased the complete hull before it reached the
      // horizon; cloud-front boundary fades and sky colours own this layer.
      fog: false,
    });
    this.material.onBeforeCompile = (shader) => {
      this.shader = shader;
      shader.uniforms.uCloudV2RimColor = { value: this.rimColor };
      shader.uniforms.uCloudV2RimStrength = { value: 0.2 };
      shader.uniforms.uCloudV2SunDirectionView = {
        value: this.sunDirectionView,
      };
      shader.fragmentShader = shader.fragmentShader.replace(
        '#include <common>',
        `
          #include <common>
          uniform vec3 uCloudV2RimColor;
          uniform float uCloudV2RimStrength;
          uniform vec3 uCloudV2SunDirectionView;
        `,
      );
      shader.fragmentShader = shader.fragmentShader.replace(
        '#include <output_fragment>',
        `
          float cloudV2Facing = clamp(
            dot(normalize(normal), normalize(vViewPosition)),
            0.0,
            1.0
          );
          float cloudV2SunFacing = clamp(
            dot(normalize(normal), normalize(uCloudV2SunDirectionView)) *
              0.5 + 0.5,
            0.0,
            1.0
          );
          float cloudV2SilverLining = pow(1.0 - cloudV2Facing, 3.4) *
            (0.16 + cloudV2SunFacing * 0.84) * uCloudV2RimStrength;
          outgoingLight += uCloudV2RimColor * cloudV2SilverLining;
          #include <output_fragment>
        `,
      );
    };
    this.material.customProgramCacheKey = () => 'cloud-mesh-library-v2-rim-1';

    this.mesh = new BatchedMesh(
      library.cloudCount,
      maxVertexCount,
      maxIndexCount,
      this.material,
    );
    this.mesh.name = 'Cloud mesh library V2 · 240 authored hulls';
    this.mesh.renderOrder = -997;
    this.mesh.frustumCulled = true;
    this.mesh.perObjectFrustumCulled = true;
    this.mesh.sortObjects = true;

    for (const source of library.clouds) {
      const geometryIds: number[] = [];
      for (const packed of source.lods) {
        const geometry = decodeCloudGeometryV2(packed);
        geometryIds.push(this.mesh.addGeometry(geometry));
        geometry.dispose();
      }
      const typedGeometryIds = geometryIds as [number, number, number];
      const instanceId = this.mesh.addInstance(typedGeometryIds[2]);
      this.records.push({
        source,
        instanceId,
        geometryIds: typedGeometryIds,
        lod: 2,
        visible: false,
      });
      this.mesh.setVisibleAt(instanceId, false);
    }
    this.mesh.visible = false;
    scene.add(this.mesh);
  }

  public setPresentation(
    input: Readonly<VolumetricCloudPresentation>,
  ): void {
    this.material.color.copy(input.cloudColor).lerp(input.cloudLightColor, 0.1);
    this.material.emissive.copy(input.cloudShadowColor).multiplyScalar(
      0.06 + clamp(input.night, 0, 1) * 0.12,
    );
    this.rimColor.copy(input.cloudLightColor).lerp(input.sunColor, 0.48);
    this.sunDirectionWorld.copy(input.sunDirection);
    if (this.shader) {
      this.shader.uniforms.uCloudV2RimStrength!.value =
        0.16 + clamp(input.twilight, 0, 1) * 0.24;
    }
  }

  public setVisible(visible: boolean): void {
    this.mesh.visible = visible && this.visibleCount > 0;
  }

  public update(
    camera: Camera,
    timeSeconds: number,
    state: Readonly<CloudMeshLibraryV2Update>,
  ): void {
    const enabled = state.presentationVisible && state.opacity > 0.012;
    this.mesh.visible = enabled;
    this.material.opacity = clamp(0.22 + state.opacity * 0.76, 0, 0.94);
    if (!enabled) {
      this.visibleCount = 0;
      return;
    }
    this.sunDirectionView.copy(this.sunDirectionWorld).transformDirection(
      camera.matrixWorldInverse,
    );

    const halfPeriod = library.worldPeriod * 0.5;
    const wrap = (value: number): number => (
      ((value + halfPeriod) % library.worldPeriod + library.worldPeriod) %
        library.worldPeriod - halfPeriod
    );
    const windLength = Math.max(
      0.0001,
      Math.hypot(state.windDirection.x, state.windDirection.y),
    );
    const windX = state.windDirection.x / windLength;
    const windZ = state.windDirection.y / windLength;
    this.visibleCount = 0;
    this.nearLodCount = 0;
    this.middleLodCount = 0;
    this.farLodCount = 0;

    for (const record of this.records) {
      const source = record.source;
      const movingX = source.center[0] + state.windOffset.x * source.driftScale;
      const movingZ = source.center[2] + state.windOffset.y * source.driftScale;
      const relativeX = wrap(movingX - camera.position.x);
      const relativeZ = wrap(movingZ - camera.position.z);
      const distance = Math.hypot(relativeX, source.center[1], relativeZ);
      const alongWind = relativeX * windX + relativeZ * windZ;
      const crossWind = Math.abs(-relativeX * windZ + relativeZ * windX);
      const boundaryFade = smoothstep(-halfPeriod, -halfPeriod * 0.76, alongWind) *
        (1 - smoothstep(halfPeriod * 0.7, halfPeriod, alongWind)) *
        (1 - smoothstep(halfPeriod * 0.78, halfPeriod * 0.985, crossWind));
      const coverPresence = smoothstep(
        source.activation - 0.18,
        source.activation + 0.06,
        state.cover,
      );
      const arrivalFront = -halfPeriod * 1.08 +
        halfPeriod * 2.16 * state.arrivalProgress;
      const arrivalPresence = 1 - smoothstep(
        arrivalFront - 780,
        arrivalFront + 780,
        alongWind,
      );
      const clearingFront = -halfPeriod * 0.96 +
        halfPeriod * 2.04 * state.clearingProgress;
      const clearingPresence = smoothstep(
        clearingFront - 620,
        clearingFront + 620,
        alongWind,
      );
      const presence = boundaryFade * coverPresence * arrivalPresence *
        clearingPresence;
      const visible = presence > 0.025 && distance < 4_440;
      if (record.visible !== visible) {
        record.visible = visible;
        this.mesh.setVisibleAt(record.instanceId, visible);
      }
      if (!visible) continue;

      let lod = distance < 1_250 ? 0 : distance < 2_650 ? 1 : 2;
      // Broad storm decks deserve one extra silhouette tier when near enough
      // to dominate the sky.
      if (source.family === 3 && distance < 3_150) lod = Math.max(0, lod - 1);
      if (record.lod !== lod) {
        record.lod = lod;
        this.mesh.setGeometryIdAt(record.instanceId, record.geometryIds[lod]!);
      }

      const breathing = 1 + Math.sin(
        timeSeconds * 0.011 + source.phase * Math.PI * 2,
      ) * 0.018;
      const presenceScale = smoothstep(0.025, 0.24, presence);
      this.position.set(
        camera.position.x + relativeX,
        source.center[1],
        camera.position.z + relativeZ,
      );
      this.scale.set(
        source.scale[0] * breathing * presenceScale,
        source.scale[1] * (1 + (breathing - 1) * 0.45) * presenceScale,
        source.scale[2] * breathing * presenceScale,
      );
      this.rotation.setFromAxisAngle(UP, source.phase * Math.PI * 2);
      this.matrix.compose(this.position, this.rotation, this.scale);
      this.mesh.setMatrixAt(record.instanceId, this.matrix);
      this.visibleCount += 1;
      if (lod === 0) this.nearLodCount += 1;
      else if (lod === 1) this.middleLodCount += 1;
      else this.farLodCount += 1;
    }
  }

  public getStats(): Readonly<{
    libraryClouds: number;
    visibleClouds: number;
    nearLod: number;
    middleLod: number;
    farLod: number;
    totalVertices: number;
    totalTriangles: number;
  }> {
    return {
      libraryClouds: library.cloudCount,
      visibleClouds: this.visibleCount,
      nearLod: this.nearLodCount,
      middleLod: this.middleLodCount,
      farLod: this.farLodCount,
      totalVertices: this.mesh.geometry.getAttribute('position').count,
      totalTriangles: (this.mesh.geometry.index?.count ?? 0) / 3,
    };
  }

  public dispose(scene: Scene): void {
    scene.remove(this.mesh);
    this.mesh.dispose();
    this.material.dispose();
  }
}
