import { inspectAssetPerformanceBudget } from '../performance/AssetPerformanceBudget';
import type {
  ContentAuthoringDomain,
  ContentAuthoringIssue,
  IcewayContentAuthoringDocument,
} from './ContentAuthoringTypes';

const finite01 = (value: number): boolean =>
  Number.isFinite(value) && value >= 0 && value <= 1;

const duplicates = (ids: readonly string[]): Set<string> => {
  const seen = new Set<string>();
  const repeated = new Set<string>();
  for (const id of ids) {
    if (seen.has(id)) repeated.add(id);
    seen.add(id);
  }
  return repeated;
};

export const validateContentAuthoringDocument = (
  document: Readonly<IcewayContentAuthoringDocument>,
): readonly ContentAuthoringIssue[] => {
  const issues: ContentAuthoringIssue[] = [];
  const add = (
    severity: ContentAuthoringIssue['severity'],
    domain: ContentAuthoringDomain | 'DOCUMENT',
    path: string,
    message: string,
  ): void => {
    issues.push({ severity, domain, path, message });
  };

  if (document.version !== 1) {
    add('ERROR', 'DOCUMENT', 'version', 'Only authoring document version 1 is supported.');
  }
  if (!document.id?.trim()) add('ERROR', 'DOCUMENT', 'id', 'Document ID is required.');
  const locationIds = new Set(document.locations.map((location) => location.id));
  for (const id of duplicates(document.locations.map((location) => location.id))) {
    add('ERROR', 'DOCUMENT', `locations.${id}`, 'Location ID is duplicated.');
  }

  const questIds = new Set(document.quests.map((quest) => quest.id));
  for (const id of duplicates(document.quests.map((quest) => quest.id))) {
    add('ERROR', 'QUESTS', id, 'Quest ID is duplicated.');
  }
  for (const quest of document.quests) {
    const stageIds = new Set(quest.stages.map((stage) => stage.id));
    if (!stageIds.has(quest.initialStageId)) {
      add('ERROR', 'QUESTS', `${quest.id}.initialStageId`, 'Initial stage does not exist.');
    }
    for (const duplicate of duplicates(quest.stages.map((stage) => stage.id))) {
      add('ERROR', 'QUESTS', `${quest.id}.stages.${duplicate}`, 'Stage ID is duplicated.');
    }
    for (const stage of quest.stages) {
      if (stage.nextStageId && !stageIds.has(stage.nextStageId)) {
        add('ERROR', 'QUESTS', `${quest.id}.${stage.id}.nextStageId`, 'Next stage does not exist.');
      }
      if (stage.hudTargetLocationId && !locationIds.has(stage.hudTargetLocationId)) {
        add('ERROR', 'QUESTS', `${quest.id}.${stage.id}.hudTargetLocationId`, 'HUD target location does not exist.');
      }
      if (stage.completionConditions.length === 0) {
        add('WARNING', 'QUESTS', `${quest.id}.${stage.id}`, 'Stage has no completion condition.');
      }
    }
  }

  for (const id of duplicates(document.dialogues.map((dialogue) => dialogue.id))) {
    add('ERROR', 'DIALOGUES', id, 'Conversation ID is duplicated.');
  }
  for (const conversation of document.dialogues) {
    const nodeIds = new Set(conversation.nodes.map((node) => node.id));
    if (!nodeIds.has(conversation.entryNodeId)) {
      add('ERROR', 'DIALOGUES', `${conversation.id}.entryNodeId`, 'Entry node does not exist.');
    }
    for (const duplicate of duplicates(conversation.nodes.map((node) => node.id))) {
      add('ERROR', 'DIALOGUES', `${conversation.id}.nodes.${duplicate}`, 'Dialogue node ID is duplicated.');
    }
    for (const node of conversation.nodes) {
      if (!node.text.trim()) {
        add('ERROR', 'DIALOGUES', `${conversation.id}.${node.id}.text`, 'Dialogue text is empty.');
      }
      if (node.choices.length === 0) {
        add('ERROR', 'DIALOGUES', `${conversation.id}.${node.id}`, 'Dialogue node has no exit choice.');
      }
      for (const choice of node.choices) {
        if (choice.nextNodeId && !nodeIds.has(choice.nextNodeId)) {
          add('ERROR', 'DIALOGUES', `${conversation.id}.${node.id}.${choice.id}`, 'Choice target node does not exist.');
        }
        if (!choice.nextNodeId && !choice.endsConversation) {
          add('ERROR', 'DIALOGUES', `${conversation.id}.${node.id}.${choice.id}`, 'Choice neither continues nor ends the conversation.');
        }
        for (const consequence of choice.consequences ?? []) {
          if (consequence.type === 'START_STORY_QUEST' && !questIds.has(consequence.questId)) {
            add('ERROR', 'DIALOGUES', `${conversation.id}.${node.id}.${choice.id}`, `Unknown story quest ${consequence.questId}.`);
          }
        }
      }
    }
  }

  for (const id of duplicates(document.materials.map((material) => material.id))) {
    add('ERROR', 'MATERIALS', id, 'Material ID is duplicated.');
  }
  for (const material of document.materials) {
    if (!/^#[0-9a-f]{6}$/i.test(material.baseColor)) {
      add('ERROR', 'MATERIALS', `${material.id}.baseColor`, 'Base color must be a six-digit hex color.');
    }
    for (const field of ['roughness', 'metalness', 'snowAffinity', 'thermalOutput', 'windResponse'] as const) {
      if (!finite01(material[field])) {
        add('ERROR', 'MATERIALS', `${material.id}.${field}`, `${field} must be between 0 and 1.`);
      }
    }
  }

  for (const id of duplicates(document.scenarios.map((scenario) => scenario.id))) {
    add('ERROR', 'SCENARIOS', id, 'Scenario ID is duplicated.');
  }
  for (const scenario of document.scenarios) {
    if (!locationIds.has(scenario.spawnLocationId)) {
      add('ERROR', 'SCENARIOS', `${scenario.id}.spawnLocationId`, 'Scenario spawn location does not exist.');
    }
  }

  for (const id of duplicates(document.assets.map((asset) => asset.id))) {
    add('ERROR', 'ASSETS', id, 'Asset ID is duplicated.');
  }
  for (const asset of document.assets) {
    if (!asset.suggestedModelUrl.trim()) {
      add('WARNING', 'ASSETS', `${asset.id}.suggestedModelUrl`, 'Asset has no replaceable model URL.');
    }
    if (!asset.performanceFacts) {
      if (asset.tags.includes('IMPORT_CANDIDATE')) {
        add('WARNING', 'ASSETS', `${asset.id}.performanceFacts`, 'Imported candidate has not been measured yet.');
      }
      continue;
    }
    const report = inspectAssetPerformanceBudget({
      id: asset.id,
      budgetClass: asset.budgetClass,
      ...asset.performanceFacts,
    });
    for (const issue of report.issues) {
      add(issue.severity, 'ASSETS', `${asset.id}.${String(issue.field)}`, issue.message);
    }
  }

  return Object.freeze(issues);
};
