import type { PlayerId } from '../../netcode/core/NetworkPrimitives';
import { playerId } from '../../netcode/core/NetworkPrimitives';
import type { ReliableAuthorityOperation } from '../../netcode/protocol/AuthorityIngress';
import type { ReplicatedWorldDomainEvent } from '../../netcode/protocol/WorldReplication';
import type {
  DialogueChoiceDefinition,
  DialogueConsequenceDefinition,
  DialogueConversationDefinition,
  DialogueConversationStatus,
  DialogueScope,
  ReplicatedDialogueConversation,
  ReplicatedDialogueState,
  ReplicatedSystemNotice,
  SystemNoticeChannel,
} from '../../gameplay/dialogue/DialogueTypes';

export interface DialogueConsequenceContext {
  readonly requestId: string;
  readonly instanceId: string;
  readonly conversationId: string;
  readonly choiceId: string;
  readonly scope: DialogueScope;
  readonly actorPlayerId: PlayerId;
}

export interface DialogueConsequenceCommitResult {
  readonly accepted: boolean;
  readonly status: string;
}

export interface MultiplayerDialogueOperationResult {
  readonly accepted: boolean;
  readonly status: string;
  readonly stateChanged: boolean;
}

interface DialogueInstanceState {
  instanceId: string;
  conversationId: string;
  scope: DialogueScope;
  ownerPlayerId?: PlayerId;
  status: DialogueConversationStatus;
  currentNodeId?: string;
  revision: number;
  participants: PlayerId[];
  lastChoiceId?: string;
  lastActorPlayerId?: PlayerId;
}

interface SystemNoticeState {
  noticeId: string;
  channel: SystemNoticeChannel;
  scope: DialogueScope;
  title: string;
  body: string;
  createdAtWorldTimeSeconds: number;
  ownerPlayerId?: PlayerId;
  sourceEventId?: string;
  acknowledgedByPlayerIds: PlayerId[];
}

export interface MultiplayerDialogueAuthorityCheckpoint {
  readonly version: 1;
  readonly worldEventCursor: number;
  readonly playerRevisions: readonly Readonly<{
    playerId: PlayerId;
    revision: number;
  }>[];
  readonly instances: readonly Readonly<DialogueInstanceState>[];
  readonly notices: readonly Readonly<SystemNoticeState>[];
}

export interface MultiplayerDialogueAuthorityOptions {
  readonly validateNpcId?: (npcId: string) => boolean;
  readonly validateNpcGoal?: (npcId: string, goalId: string | undefined) => boolean;
  readonly validateStoryQuestId?: (questId: string) => boolean;
  readonly validatePortableItemDefinitionId?: (definitionId: string) => boolean;
}

const SCOPES = new Set<DialogueScope>([
  'PERSONAL',
  'PARTY_SHARED',
  'WORLD_SHARED',
]);
const MAXIMUM_INSTANCES = 512;
const MAXIMUM_NOTICES = 512;

const bounded = (value: unknown, maximum: number): value is string =>
  typeof value === 'string' &&
  value.trim().length > 0 &&
  value.length <= maximum;

const cloneInstance = (
  state: Readonly<DialogueInstanceState>,
): DialogueInstanceState => ({
  ...state,
  participants: [...state.participants],
});

const cloneNotice = (
  state: Readonly<SystemNoticeState>,
): SystemNoticeState => ({
  ...state,
  acknowledgedByPlayerIds: [...state.acknowledgedByPlayerIds],
});

/** Definition-driven authority for scoped dialogue and non-chat notices. */
export class MultiplayerDialogueAuthority {
  private readonly definitions = new Map<string, DialogueConversationDefinition>();
  private readonly instances = new Map<string, DialogueInstanceState>();
  private readonly notices = new Map<string, SystemNoticeState>();
  private readonly playerRevisions = new Map<PlayerId, number>();
  private worldEventCursorValue = 0;

  public constructor(
    definitions: readonly Readonly<DialogueConversationDefinition>[],
    private readonly options: Readonly<MultiplayerDialogueAuthorityOptions> = {},
    checkpoint?: Readonly<MultiplayerDialogueAuthorityCheckpoint>,
  ) {
    this.validateAndIndexDefinitions(definitions);
    if (checkpoint) this.restoreCheckpoint(checkpoint);
  }

  public ensurePlayer(targetPlayerId: PlayerId): void {
    if (!this.playerRevisions.has(targetPlayerId)) {
      this.playerRevisions.set(targetPlayerId, 1);
    }
  }

  public playerIds(): readonly PlayerId[] {
    return [...this.playerRevisions.keys()].sort();
  }

  public getDefinition(
    conversationId: string,
  ): Readonly<DialogueConversationDefinition> | undefined {
    return this.definitions.get(conversationId);
  }

  public get worldEventCursor(): number {
    return this.worldEventCursorValue;
  }

  public skipWorldEventsThrough(cursor: number): void {
    if (Number.isSafeInteger(cursor) && cursor >= this.worldEventCursorValue) {
      this.worldEventCursorValue = cursor;
    }
  }

  public processOperation(
    operation: Readonly<ReliableAuthorityOperation>,
    input: Readonly<{
      canStartConversation: (
        definition: Readonly<DialogueConversationDefinition>,
      ) => boolean;
      worldTimeSeconds: number;
      commitConsequences: (
        consequences: readonly DialogueConsequenceDefinition[],
        context: Readonly<DialogueConsequenceContext>,
      ) => DialogueConsequenceCommitResult;
    }>,
  ): MultiplayerDialogueOperationResult {
    if (operation.channel !== 'DIALOGUE') {
      return { accepted: false, status: 'INVALID_DIALOGUE_CHANNEL', stateChanged: false };
    }
    if (!this.playerRevisions.has(operation.playerId)) {
      return { accepted: false, status: 'UNKNOWN_PLAYER', stateChanged: false };
    }
    if (operation.operation === 'START_CONVERSATION') {
      const conversationId = operation.payload.conversationId;
      if (!bounded(conversationId, 160)) {
        return { accepted: false, status: 'INVALID_CONVERSATION', stateChanged: false };
      }
      const definition = this.definitions.get(conversationId);
      if (!definition) {
        return { accepted: false, status: 'UNKNOWN_CONVERSATION', stateChanged: false };
      }
      if (!input.canStartConversation(definition)) {
        return { accepted: false, status: 'NOT_NEAR_DIALOGUE_TARGET', stateChanged: false };
      }
      return this.startConversation(operation.playerId, definition);
    }
    if (operation.operation === 'CHOOSE_DIALOGUE') {
      const instanceId = operation.payload.instanceId;
      const nodeId = operation.payload.nodeId;
      const choiceId = operation.payload.choiceId;
      if (
        !bounded(instanceId, 384) ||
        !bounded(nodeId, 160) ||
        !bounded(choiceId, 160)
      ) {
        return { accepted: false, status: 'INVALID_DIALOGUE_CHOICE', stateChanged: false };
      }
      return this.choose(
        operation,
        instanceId,
        nodeId,
        choiceId,
        input.worldTimeSeconds,
        input.commitConsequences,
      );
    }
    if (operation.operation === 'ACKNOWLEDGE_NOTICE') {
      const noticeId = operation.payload.noticeId;
      if (!bounded(noticeId, 384)) {
        return { accepted: false, status: 'INVALID_NOTICE', stateChanged: false };
      }
      return this.acknowledgeNotice(operation.playerId, noticeId);
    }
    return {
      accepted: false,
      status: 'UNSUPPORTED_DIALOGUE_OPERATION',
      stateChanged: false,
    };
  }

  public receiveWorldEvents(
    records: readonly Readonly<ReplicatedWorldDomainEvent>[],
    worldTimeSeconds: number,
  ): void {
    for (const record of [...records].sort((left, right) =>
      left.cursor - right.cursor)) {
      if (record.cursor <= this.worldEventCursorValue) continue;
      const event = record.event;
      if (
        event.type === 'WORLD_INCIDENT_CHANGED' &&
        event.status === 'REPORTED'
      ) {
        this.createNotice({
          noticeId: `notice:${event.eventId}`,
          channel: 'NPC',
          scope: 'WORLD_SHARED',
          title: 'Distress report',
          body: `${event.subjectId} requires assistance.`,
          createdAtWorldTimeSeconds: worldTimeSeconds,
          sourceEventId: event.eventId,
        });
      } else if (event.type === 'SERVICE_AVAILABILITY_CHANGED') {
        this.createNotice({
          noticeId: `notice:${event.eventId}`,
          channel: 'SYSTEM',
          scope: 'WORLD_SHARED',
          title: 'Service update',
          body: `${event.serviceId}: ${event.availability.toLowerCase()}.`,
          createdAtWorldTimeSeconds: worldTimeSeconds,
          sourceEventId: event.eventId,
        });
      } else if (event.type === 'STORY_QUEST_STATE_CHANGED') {
        this.createNotice({
          noticeId: `notice:${event.eventId}`,
          channel: 'SYSTEM',
          scope: 'WORLD_SHARED',
          title: 'Story update',
          body: `${event.questId}: ${event.status.toLowerCase()}.`,
          createdAtWorldTimeSeconds: worldTimeSeconds,
          sourceEventId: event.eventId,
        });
      }
      this.worldEventCursorValue = record.cursor;
    }
  }

  public snapshot(targetPlayerId: PlayerId): ReplicatedDialogueState {
    if (!this.playerRevisions.has(targetPlayerId)) {
      throw new Error(`Unknown dialogue player ${targetPlayerId}.`);
    }
    const conversations = [...this.instances.values()]
      .filter((instance) =>
        instance.scope !== 'PERSONAL' ||
        instance.ownerPlayerId === targetPlayerId)
      .sort((left, right) => left.instanceId.localeCompare(right.instanceId))
      .map((instance) => this.replicatedConversation(instance));
    const notices = [...this.notices.values()]
      .filter((notice) =>
        notice.scope !== 'PERSONAL' || notice.ownerPlayerId === targetPlayerId)
      .sort((left, right) =>
        left.createdAtWorldTimeSeconds - right.createdAtWorldTimeSeconds ||
        left.noticeId.localeCompare(right.noticeId))
      .map((notice): ReplicatedSystemNotice => ({
        noticeId: notice.noticeId,
        channel: notice.channel,
        scope: notice.scope,
        title: notice.title,
        body: notice.body,
        createdAtWorldTimeSeconds: notice.createdAtWorldTimeSeconds,
        acknowledged: notice.acknowledgedByPlayerIds.includes(targetPlayerId),
        ...(notice.sourceEventId ? { sourceEventId: notice.sourceEventId } : {}),
      }));
    return {
      revision: this.playerRevisions.get(targetPlayerId)!,
      conversations,
      notices,
      inputPolicy: {
        localDialogueLocksMovement: false,
        localDialoguePausesAuthority: false,
      },
    };
  }

  public exportCheckpoint(): MultiplayerDialogueAuthorityCheckpoint {
    return {
      version: 1,
      worldEventCursor: this.worldEventCursorValue,
      playerRevisions: this.playerIds().map((targetPlayerId) => ({
        playerId: targetPlayerId,
        revision: this.playerRevisions.get(targetPlayerId)!,
      })),
      instances: [...this.instances.values()]
        .sort((left, right) => left.instanceId.localeCompare(right.instanceId))
        .map(cloneInstance),
      notices: [...this.notices.values()]
        .sort((left, right) => left.noticeId.localeCompare(right.noticeId))
        .map(cloneNotice),
    };
  }

  public restoreCheckpoint(
    checkpoint: Readonly<MultiplayerDialogueAuthorityCheckpoint>,
  ): void {
    if (
      checkpoint.version !== 1 ||
      !Number.isSafeInteger(checkpoint.worldEventCursor) ||
      checkpoint.worldEventCursor < 0 ||
      !Array.isArray(checkpoint.playerRevisions) ||
      checkpoint.playerRevisions.length > 4 ||
      !Array.isArray(checkpoint.instances) ||
      checkpoint.instances.length > MAXIMUM_INSTANCES ||
      !Array.isArray(checkpoint.notices) ||
      checkpoint.notices.length > MAXIMUM_NOTICES
    ) throw new Error('Invalid dialogue checkpoint.');

    const players = new Map<PlayerId, number>();
    for (const candidate of checkpoint.playerRevisions) {
      const id = playerId(candidate.playerId);
      if (
        players.has(id) ||
        !Number.isSafeInteger(candidate.revision) ||
        candidate.revision < 1
      ) throw new Error('Invalid dialogue checkpoint player.');
      players.set(id, candidate.revision);
    }
    const instances = new Map<string, DialogueInstanceState>();
    for (const candidate of checkpoint.instances) {
      const definition = this.definitions.get(candidate.conversationId);
      if (
        !definition ||
        !bounded(candidate.instanceId, 384) ||
        candidate.scope !== definition.scope ||
        !['ACTIVE', 'COMPLETED'].includes(candidate.status) ||
        !Number.isSafeInteger(candidate.revision) ||
        candidate.revision < 1 ||
        instances.has(candidate.instanceId) ||
        !Array.isArray(candidate.participants) ||
        candidate.participants.length > 4 ||
        candidate.participants.some((id: PlayerId) => !players.has(id)) ||
        (candidate.scope === 'PERSONAL' &&
          (!candidate.ownerPlayerId || !players.has(candidate.ownerPlayerId))) ||
        (candidate.currentNodeId !== undefined &&
          !definition.nodes.some((node) => node.id === candidate.currentNodeId))
      ) throw new Error('Invalid dialogue checkpoint instance.');
      instances.set(candidate.instanceId, cloneInstance(candidate));
    }
    const notices = new Map<string, SystemNoticeState>();
    for (const candidate of checkpoint.notices) {
      if (
        !bounded(candidate.noticeId, 384) ||
        !['NPC', 'SYSTEM'].includes(candidate.channel) ||
        !SCOPES.has(candidate.scope) ||
        !bounded(candidate.title, 160) ||
        !bounded(candidate.body, 1_000) ||
        !Number.isFinite(candidate.createdAtWorldTimeSeconds) ||
        candidate.createdAtWorldTimeSeconds < 0 ||
        notices.has(candidate.noticeId) ||
        !Array.isArray(candidate.acknowledgedByPlayerIds) ||
        candidate.acknowledgedByPlayerIds.some(
          (id: PlayerId) => !players.has(id),
        ) ||
        (candidate.scope === 'PERSONAL' &&
          (!candidate.ownerPlayerId || !players.has(candidate.ownerPlayerId)))
      ) throw new Error('Invalid dialogue checkpoint notice.');
      notices.set(candidate.noticeId, cloneNotice(candidate));
    }
    this.playerRevisions.clear();
    this.instances.clear();
    this.notices.clear();
    for (const [id, value] of players) this.playerRevisions.set(id, value);
    for (const [id, value] of instances) this.instances.set(id, value);
    for (const [id, value] of notices) this.notices.set(id, value);
    this.worldEventCursorValue = checkpoint.worldEventCursor;
  }

  private startConversation(
    actorPlayerId: PlayerId,
    definition: Readonly<DialogueConversationDefinition>,
  ): MultiplayerDialogueOperationResult {
    const instanceId = this.instanceId(definition, actorPlayerId);
    const existing = this.instances.get(instanceId);
    if (existing?.status === 'ACTIVE') {
      if (!existing.participants.includes(actorPlayerId)) {
        existing.participants.push(actorPlayerId);
        existing.participants.sort();
        existing.revision += 1;
        this.bumpVisible(existing);
        return { accepted: true, status: 'DIALOGUE_JOINED', stateChanged: true };
      }
      return { accepted: true, status: 'DIALOGUE_ALREADY_ACTIVE', stateChanged: false };
    }
    if (existing && !definition.restartable) {
      return { accepted: false, status: 'DIALOGUE_ALREADY_COMPLETED', stateChanged: false };
    }
    const next: DialogueInstanceState = {
      instanceId,
      conversationId: definition.id,
      scope: definition.scope,
      ...(definition.scope === 'PERSONAL'
        ? { ownerPlayerId: actorPlayerId }
        : {}),
      status: 'ACTIVE',
      currentNodeId: definition.entryNodeId,
      revision: (existing?.revision ?? 0) + 1,
      participants: [actorPlayerId],
    };
    this.instances.set(instanceId, next);
    this.bumpVisible(next);
    return { accepted: true, status: 'DIALOGUE_STARTED', stateChanged: true };
  }

  private choose(
    operation: Readonly<ReliableAuthorityOperation>,
    instanceId: string,
    nodeId: string,
    choiceId: string,
    worldTimeSeconds: number,
    commitConsequences: (
      consequences: readonly DialogueConsequenceDefinition[],
      context: Readonly<DialogueConsequenceContext>,
    ) => DialogueConsequenceCommitResult,
  ): MultiplayerDialogueOperationResult {
    const instance = this.instances.get(instanceId);
    if (!instance || !this.canObserve(instance, operation.playerId)) {
      return { accepted: false, status: 'DIALOGUE_INSTANCE_NOT_FOUND', stateChanged: false };
    }
    if (instance.status !== 'ACTIVE' || instance.currentNodeId !== nodeId) {
      return { accepted: false, status: 'STALE_DIALOGUE_NODE', stateChanged: false };
    }
    const definition = this.definitions.get(instance.conversationId)!;
    const node = definition.nodes.find((value) => value.id === nodeId)!;
    const choice = node.choices.find((value) => value.id === choiceId);
    if (!choice) {
      return { accepted: false, status: 'UNKNOWN_DIALOGUE_CHOICE', stateChanged: false };
    }
    const consequences = choice.consequences ?? [];
    const committed = commitConsequences(consequences, {
      requestId: operation.requestId,
      instanceId,
      conversationId: definition.id,
      choiceId,
      scope: definition.scope,
      actorPlayerId: operation.playerId,
    });
    if (!committed.accepted) {
      return { accepted: false, status: committed.status, stateChanged: false };
    }

    instance.lastChoiceId = choice.id;
    instance.lastActorPlayerId = operation.playerId;
    if (!instance.participants.includes(operation.playerId)) {
      instance.participants.push(operation.playerId);
      instance.participants.sort();
    }
    if (choice.endsConversation || !choice.nextNodeId) {
      instance.status = 'COMPLETED';
      instance.currentNodeId = undefined;
    } else {
      instance.currentNodeId = choice.nextNodeId;
    }
    instance.revision += 1;
    for (const consequence of consequences) {
      if (consequence.type !== 'CREATE_NOTICE') continue;
      const scope = consequence.scope ?? definition.scope;
      this.createNotice({
        noticeId:
          `notice:dialogue:${instance.instanceId}:` +
          `${instance.revision}:${consequence.consequenceId}`,
        channel: consequence.channel,
        scope,
        title: consequence.title,
        body: consequence.body,
        createdAtWorldTimeSeconds: worldTimeSeconds,
        ...(scope === 'PERSONAL'
          ? { ownerPlayerId: operation.playerId }
          : {}),
      });
    }
    this.bumpVisible(instance);
    return { accepted: true, status: 'DIALOGUE_CHOICE_COMMITTED', stateChanged: true };
  }

  private acknowledgeNotice(
    targetPlayerId: PlayerId,
    noticeId: string,
  ): MultiplayerDialogueOperationResult {
    const notice = this.notices.get(noticeId);
    if (
      !notice ||
      (notice.scope === 'PERSONAL' && notice.ownerPlayerId !== targetPlayerId)
    ) {
      return { accepted: false, status: 'NOTICE_NOT_FOUND', stateChanged: false };
    }
    if (notice.acknowledgedByPlayerIds.includes(targetPlayerId)) {
      return { accepted: true, status: 'NOTICE_ALREADY_ACKNOWLEDGED', stateChanged: false };
    }
    notice.acknowledgedByPlayerIds.push(targetPlayerId);
    notice.acknowledgedByPlayerIds.sort();
    this.bumpPlayer(targetPlayerId);
    return { accepted: true, status: 'NOTICE_ACKNOWLEDGED', stateChanged: true };
  }

  private createNotice(
    input: Omit<SystemNoticeState, 'acknowledgedByPlayerIds'>,
  ): boolean {
    if (this.notices.has(input.noticeId)) return false;
    this.notices.set(input.noticeId, {
      ...input,
      acknowledgedByPlayerIds: [],
    });
    while (this.notices.size > MAXIMUM_NOTICES) {
      const first = this.notices.keys().next().value as string | undefined;
      if (!first) break;
      this.notices.delete(first);
    }
    if (input.scope === 'PERSONAL' && input.ownerPlayerId) {
      this.bumpPlayer(input.ownerPlayerId);
    } else {
      this.bumpAllPlayers();
    }
    return true;
  }

  private replicatedConversation(
    instance: Readonly<DialogueInstanceState>,
  ): ReplicatedDialogueConversation {
    const definition = this.definitions.get(instance.conversationId)!;
    const node = instance.currentNodeId
      ? definition.nodes.find((value) => value.id === instance.currentNodeId)
      : undefined;
    return {
      instanceId: instance.instanceId,
      conversationId: instance.conversationId,
      scope: instance.scope,
      status: instance.status,
      revision: instance.revision,
      participants: [...instance.participants],
      ...(node
        ? {
            currentNode: {
              nodeId: node.id,
              speakerId: node.speakerId,
              speakerName: node.speakerName,
              text: node.text,
              choices: node.choices.map((choice) => ({
                choiceId: choice.id,
                text: choice.text,
              })),
            },
          }
        : {}),
      ...(instance.lastChoiceId ? { lastChoiceId: instance.lastChoiceId } : {}),
      ...(instance.lastActorPlayerId
        ? { lastActorPlayerId: instance.lastActorPlayerId }
        : {}),
    };
  }

  private canObserve(
    instance: Readonly<DialogueInstanceState>,
    targetPlayerId: PlayerId,
  ): boolean {
    return instance.scope !== 'PERSONAL' ||
      instance.ownerPlayerId === targetPlayerId;
  }

  private instanceId(
    definition: Readonly<DialogueConversationDefinition>,
    actorPlayerId: PlayerId,
  ): string {
    if (definition.scope === 'PERSONAL') {
      return `dialogue:personal:${actorPlayerId}:${definition.id}`;
    }
    if (definition.scope === 'PARTY_SHARED') {
      return `dialogue:party:${definition.id}`;
    }
    return `dialogue:world:${definition.id}`;
  }

  private bumpVisible(instance: Readonly<DialogueInstanceState>): void {
    if (instance.scope === 'PERSONAL' && instance.ownerPlayerId) {
      this.bumpPlayer(instance.ownerPlayerId);
    } else {
      this.bumpAllPlayers();
    }
  }

  private bumpAllPlayers(): void {
    for (const id of this.playerRevisions.keys()) this.bumpPlayer(id);
  }

  private bumpPlayer(targetPlayerId: PlayerId): void {
    const current = this.playerRevisions.get(targetPlayerId);
    if (current !== undefined) this.playerRevisions.set(targetPlayerId, current + 1);
  }

  private validateAndIndexDefinitions(
    definitions: readonly Readonly<DialogueConversationDefinition>[],
  ): void {
    for (const definition of definitions) {
      if (
        !bounded(definition.id, 160) ||
        this.definitions.has(definition.id) ||
        !SCOPES.has(definition.scope) ||
        !bounded(definition.entryNodeId, 160) ||
        !Array.isArray(definition.nodes) ||
        definition.nodes.length === 0 ||
        definition.nodes.length > 128 ||
        (definition.targetNpcId !== undefined &&
          (!bounded(definition.targetNpcId, 160) ||
            this.options.validateNpcId?.(definition.targetNpcId) === false)) ||
        (definition.interactionRadiusMetres !== undefined &&
          (!Number.isFinite(definition.interactionRadiusMetres) ||
            definition.interactionRadiusMetres < 1 ||
            definition.interactionRadiusMetres > 20))
      ) throw new Error(`Invalid dialogue definition ${definition.id}.`);
      const nodeIds = new Set<string>();
      for (const node of definition.nodes) {
        if (
          !bounded(node.id, 160) ||
          nodeIds.has(node.id) ||
          !bounded(node.speakerId, 160) ||
          !bounded(node.speakerName, 160) ||
          !bounded(node.text, 4_000) ||
          !Array.isArray(node.choices) ||
          node.choices.length === 0 ||
          node.choices.length > 32
        ) throw new Error(`Invalid dialogue node ${definition.id}:${node.id}.`);
        nodeIds.add(node.id);
        const choiceIds = new Set<string>();
        for (const choice of node.choices) {
          if (
            !bounded(choice.id, 160) ||
            choiceIds.has(choice.id) ||
            !bounded(choice.text, 1_000) ||
            (choice.nextNodeId !== undefined &&
              !bounded(choice.nextNodeId, 160)) ||
            (choice.consequences?.length ?? 0) > 32
          ) throw new Error(`Invalid dialogue choice ${definition.id}:${node.id}.`);
          choiceIds.add(choice.id);
          for (const consequence of choice.consequences ?? []) {
            this.validateConsequence(consequence, definition.id);
          }
        }
      }
      if (!nodeIds.has(definition.entryNodeId)) {
        throw new Error(`Dialogue ${definition.id} has no entry node.`);
      }
      for (const node of definition.nodes) {
        for (const choice of node.choices) {
          if (choice.nextNodeId && !nodeIds.has(choice.nextNodeId)) {
            throw new Error(`Dialogue ${definition.id} has a missing next node.`);
          }
          if (!choice.endsConversation && !choice.nextNodeId) {
            throw new Error(`Dialogue ${definition.id} has a dead-end choice.`);
          }
        }
      }
      this.definitions.set(definition.id, structuredClone(definition));
    }
  }

  private validateConsequence(
    consequence: Readonly<DialogueConsequenceDefinition>,
    conversationId: string,
  ): void {
    if (!bounded(consequence.consequenceId, 160)) {
      throw new Error(`Dialogue ${conversationId} has an invalid consequence ID.`);
    }
    if (consequence.type === 'SET_NPC_GOAL') {
      if (
        !bounded(consequence.npcId, 160) ||
        (consequence.goalId !== undefined && !bounded(consequence.goalId, 160)) ||
        this.options.validateNpcGoal?.(
          consequence.npcId,
          consequence.goalId,
        ) === false
      ) throw new Error(`Dialogue ${conversationId} has an invalid NPC goal.`);
    } else if (consequence.type === 'START_STORY_QUEST') {
      if (
        !bounded(consequence.questId, 160) ||
        this.options.validateStoryQuestId?.(consequence.questId) === false
      ) throw new Error(`Dialogue ${conversationId} has an invalid story quest.`);
    } else if (consequence.type === 'SET_WORLD_FACT') {
      if (
        !bounded(consequence.factId, 240) ||
        (typeof consequence.value === 'number' &&
          !Number.isFinite(consequence.value))
      ) throw new Error(`Dialogue ${conversationId} has an invalid world fact.`);
    } else if (consequence.type === 'EMIT_WORLD_SIGNAL') {
      if (
        !bounded(consequence.signal, 160) ||
        (consequence.subjectId !== undefined &&
          !bounded(consequence.subjectId, 160))
      ) throw new Error(`Dialogue ${conversationId} has an invalid signal.`);
    } else if (consequence.type === 'GRANT_PORTABLE_ITEM') {
      if (
        !bounded(consequence.definitionId, 160) ||
        (consequence.preferredSlotId !== undefined &&
          !bounded(consequence.preferredSlotId, 64)) ||
        this.options.validatePortableItemDefinitionId?.(
          consequence.definitionId,
        ) === false
      ) throw new Error(`Dialogue ${conversationId} has an invalid portable item grant.`);
    } else if (
      !bounded(consequence.title, 160) ||
      !bounded(consequence.body, 1_000) ||
      (consequence.scope !== undefined && !SCOPES.has(consequence.scope))
    ) {
      throw new Error(`Dialogue ${conversationId} has an invalid notice.`);
    }
  }
}
