import { clamp } from '../utils/math';
import {
  ICEWAY_BUILD_ID,
  ICEWAY_PLAYTEST_MODE,
} from '../core/RuntimeBuildFlags';
import {
  WILDERNESS_PLAN_ORDER,
  WILDERNESS_PORTABLE_ITEM_ORDER,
  WILDERNESS_TOOL_LABEL,
  type WildernessInteractionView,
  type WildernessPreparedProvisionKind,
  type WildernessPortableItemKind,
  type WildernessSurvivalSimulation,
  type WildernessTool,
} from './WildernessSurvivalSimulation';
import type { SurvivalConstructionStationView } from './SurvivalConstructionSystem';
import type { SurvivalHearthRecipeId } from './SurvivalHearthRecipeCatalog';
import { WILDERNESS_SKILL_CATALOG } from './WildernessProgression';
import {
  WildernessCartographySystem,
  type WildernessCartographyView,
} from './WildernessLivingWorld';
import type { AncientEchoesView } from './ancient-echoes/AncientEchoesModel';
import type {
  WildernessAnimalCareKind,
  WildernessAnimalCareView,
} from './WildernessAnimalCompanionSystem';

export interface WildernessSurvivalHUDActivity {
  readonly title: string;
  readonly detail: string;
  readonly progress: number;
}

export interface WildernessAtmosphereView {
  readonly skyStoryName: string;
  readonly weatherStoryName: string;
  readonly weatherPhase: string;
}

export class WildernessSurvivalHUD {
  private readonly element: HTMLElement;
  private readonly title: HTMLElement;
  private readonly detail: HTMLElement;
  private readonly progress: HTMLElement;
  private readonly atmosphere: HTMLElement;
  private readonly context: HTMLButtonElement;
  private readonly status: HTMLElement;
  private readonly inventory: HTMLElement;
  private readonly backpack: HTMLElement;
  private readonly backpackPanel: HTMLElement;
  private readonly echoStatus: HTMLElement;
  private readonly skills: HTMLElement;
  private readonly fishing: HTMLElement;
  private readonly map: HTMLElement;
  private readonly indoorSmoke: HTMLElement;
  private readonly animalCare: HTMLElement;
  private readonly station: HTMLElement;
  private readonly stationBody: HTMLElement;
  private readonly toolButtons: NodeListOf<HTMLButtonElement>;
  private statusSignature = '';
  private inventorySignature = '';
  private backpackSignature = '';
  private planSignature = '';
  private mapSignature = '';
  private backpackOpen = false;
  private stationSignature = '';
  private animalCareSignature = '';

  public constructor(
    root: HTMLElement,
    actions: Readonly<{
      onSelectTool: (tool: WildernessTool) => void;
      onSelectQuickSlot: (index: number) => void;
      onAssignQuickSlot: (index: number, tool: WildernessTool) => void;
      onDropItem: (kind: WildernessPortableItemKind) => void;
      onInteract: () => void;
      onJump: () => void;
      onToggleMap: () => void;
      onUseFireRootExtract: () => void;
      onPrimeAncientEchoes: () => void;
      onTravelAncientLaboratory: () => void;
      onCloseStation: () => void;
      onCraftAtStation: (recipeId: SurvivalHearthRecipeId) => void;
      onTransferStorage: (
        inventoryKey: keyof WildernessSurvivalSimulation['inventory'],
        direction: 'DEPOSIT' | 'WITHDRAW',
      ) => void;
      onConsumePreparedProvision: (kind: WildernessPreparedProvisionKind) => void;
      onAnimalCare: (animalId: string, kind: WildernessAnimalCareKind) => void;
      onNameAnimal: (animalId: string, name: string) => void;
    }>,
  ) {
    this.element = document.createElement('section');
    this.element.className = 'wilderness-survival-hud is-hidden';
    this.element.innerHTML = `
      <section class="wilderness-survival-objective">
        <header><small>THE LONG WINTER</small><strong data-wilderness="title">SURVIVE · EXPLORE · OBSERVE</strong><em>${ICEWAY_BUILD_ID}</em></header>
        <p data-wilderness="detail">There is no final destination. Make a place that feels safe, then follow your curiosity.</p>
        <span class="wilderness-survival-atmosphere" data-wilderness="atmosphere"></span>
        <i class="wilderness-survival-progress"><b data-wilderness="progress"></b></i>
      </section>
      <aside class="wilderness-survival-vitals" data-wilderness="status"></aside>
      <button class="wilderness-backpack-toggle" data-wilderness-action="backpack" aria-expanded="false"><span>BACKPACK</span><kbd>I</kbd></button>
      <aside class="wilderness-survival-pack" data-wilderness="pack">
        <header><small>FIELD NOTES · ${ICEWAY_BUILD_ID}</small><strong>BACKPACK</strong><button data-wilderness-action="backpack" aria-label="Close backpack">×</button></header>
        <section class="wilderness-echo-status is-hidden" data-wilderness="echo"></section>
        <small class="wilderness-pack-section-title">SUPPLIES</small>
        <div class="wilderness-survival-inventory" data-wilderness="inventory"></div>
        <details class="wilderness-survival-backpack" open>
          <summary>PHYSICAL ITEMS</summary>
          <div data-wilderness="backpack"></div>
        </details>
        <details class="wilderness-survival-discoveries">
          <summary>SKILLS · LEARNED BY DOING</summary>
          <div data-wilderness="skills"></div>
        </details>
        <button class="wilderness-survival-map-button" data-wilderness-action="map"><kbd>M</kbd> DRAWN MAP</button>
        ${ICEWAY_PLAYTEST_MODE ? `<details class="wilderness-survival-playtest"><summary>PLAYTEST ACCESS</summary><div><button data-wilderness-action="prime-ancient">ADD ANCIENT TEST SUPPLIES</button><button data-wilderness-action="travel-ancient">TRAVEL TO BURIED LABORATORY</button></div></details>` : ''}
      </aside>
      <nav class="wilderness-survival-tools" aria-label="Survival plans">
        <small>INTENT · ITEMS STAY IN THE BACKPACK</small>
        ${WILDERNESS_PLAN_ORDER.map((plan) => `
          <button data-wilderness-plan="${plan}" title="Choose a plan">
            <span>${WILDERNESS_TOOL_LABEL[plan]}</span>
          </button>
        `).join('')}
        <button data-wilderness-plan="HANDS" title="Clear current plan"><span>CLEAR PLAN</span></button>
      </nav>
      <div class="wilderness-survival-fishing is-hidden" data-wilderness="fishing"><small>WAIT FOR GOLD · PULL WITH F</small><i><b></b><em></em></i></div>
      <button class="wilderness-survival-context" data-wilderness-action="interact"><kbd>F</kbd><span>EXPLORE</span></button>
      <section class="wilderness-animal-care is-hidden" data-wilderness="animal-care" aria-live="polite"></section>
      <button class="wilderness-survival-jump" data-wilderness-action="jump"><kbd>SPACE</kbd><span>JUMP</span></button>
      <section class="wilderness-cartography is-hidden" data-wilderness="map" aria-label="Drawn wilderness map"></section>
      <section class="wilderness-station-panel is-hidden" data-wilderness="station" aria-label="Survival work station">
        <header><small>HEARTH & HOME</small><strong>FIELD STATION</strong><button data-wilderness-action="close-station" aria-label="Close station">×</button></header>
        <div data-wilderness="station-body"></div>
      </section>
      <div class="wilderness-echo-overlay" aria-hidden="true"><i></i><b></b></div>
      <div class="wilderness-indoor-smoke" data-wilderness="indoor-smoke" aria-hidden="true"></div>
    `;
    root.appendChild(this.element);
    this.title = this.require('[data-wilderness="title"]');
    this.detail = this.require('[data-wilderness="detail"]');
    this.progress = this.require('[data-wilderness="progress"]');
    this.atmosphere = this.require('[data-wilderness="atmosphere"]');
    this.context = this.require<HTMLButtonElement>('[data-wilderness-action="interact"]');
    this.status = this.require('[data-wilderness="status"]');
    this.inventory = this.require('[data-wilderness="inventory"]');
    this.backpack = this.require('[data-wilderness="backpack"]');
    this.backpackPanel = this.require('[data-wilderness="pack"]');
    this.echoStatus = this.require('[data-wilderness="echo"]');
    this.skills = this.require('[data-wilderness="skills"]');
    this.fishing = this.require('[data-wilderness="fishing"]');
    this.map = this.require('[data-wilderness="map"]');
    this.indoorSmoke = this.require('[data-wilderness="indoor-smoke"]');
    this.animalCare = this.require('[data-wilderness="animal-care"]');
    this.station = this.require('[data-wilderness="station"]');
    this.stationBody = this.require('[data-wilderness="station-body"]');
    this.toolButtons = this.element.querySelectorAll('[data-wilderness-plan]');
    this.element.addEventListener('click', (event) => {
      const target = event.target as HTMLElement;
      const plan = target.closest<HTMLButtonElement>('[data-wilderness-plan]')
        ?.dataset.wildernessPlan as WildernessTool | undefined;
      if (plan) actions.onSelectTool(plan);
      const tool = target.closest<HTMLButtonElement>('[data-wilderness-inventory-tool]')
        ?.dataset.wildernessInventoryTool as WildernessTool | undefined;
      if (tool) actions.onSelectTool(tool);
      const drop = target.closest<HTMLButtonElement>('[data-wilderness-drop-item]')
        ?.dataset.wildernessDropItem as WildernessPortableItemKind | undefined;
      if (drop) actions.onDropItem(drop);
      const provision = target.closest<HTMLButtonElement>('[data-wilderness-provision]')
        ?.dataset.wildernessProvision as WildernessPreparedProvisionKind | undefined;
      if (provision) actions.onConsumePreparedProvision(provision);
      const recipe = target.closest<HTMLButtonElement>('[data-wilderness-recipe]')
        ?.dataset.wildernessRecipe as SurvivalHearthRecipeId | undefined;
      if (recipe) actions.onCraftAtStation(recipe);
      const storageButton = target.closest<HTMLButtonElement>('[data-wilderness-storage]');
      const storageKey = storageButton?.dataset.wildernessStorage as
        keyof WildernessSurvivalSimulation['inventory'] | undefined;
      const storageDirection = storageButton?.dataset.wildernessStorageDirection as
        'DEPOSIT' | 'WITHDRAW' | undefined;
      if (storageKey && storageDirection) actions.onTransferStorage(storageKey, storageDirection);
      const animalCareButton = target.closest<HTMLButtonElement>('[data-wilderness-animal-care]');
      const animalCareKind = animalCareButton?.dataset.wildernessAnimalCare as
        WildernessAnimalCareKind | undefined;
      const animalCareId = animalCareButton?.dataset.wildernessAnimalId;
      if (animalCareKind && animalCareId) actions.onAnimalCare(animalCareId, animalCareKind);
      const animalNameButton = target.closest<HTMLButtonElement>('[data-wilderness-name-animal]');
      const animalNameId = animalNameButton?.dataset.wildernessNameAnimal;
      if (animalNameId) {
        const input = this.animalCare.querySelector<HTMLInputElement>('[data-wilderness-animal-name]');
        actions.onNameAnimal(animalNameId, input?.value ?? '');
      }
      const action = target.closest<HTMLButtonElement>('[data-wilderness-action]')
        ?.dataset.wildernessAction;
      if (action === 'interact') actions.onInteract();
      if (action === 'jump') actions.onJump();
      if (action === 'map') actions.onToggleMap();
      if (action === 'backpack') this.setBackpackOpen(!this.backpackOpen);
      if (action === 'use-fire-root-extract') actions.onUseFireRootExtract();
      if (action === 'prime-ancient') actions.onPrimeAncientEchoes();
      if (action === 'travel-ancient') actions.onTravelAncientLaboratory();
      if (action === 'close-station') actions.onCloseStation();
    });
  }

  public setVisible(visible: boolean): void {
    this.element.classList.toggle('is-hidden', !visible);
  }

  public update(
    simulation: Readonly<WildernessSurvivalSimulation>,
    interaction: Readonly<WildernessInteractionView>,
    activity: Readonly<WildernessSurvivalHUDActivity>,
    cartography: Readonly<WildernessCartographyView>,
    atmosphere: Readonly<WildernessAtmosphereView>,
    ancient?: Readonly<AncientEchoesView>,
    indoorSmokeExposure = 0,
    station: Readonly<SurvivalConstructionStationView> = {
      open: false,
      recipes: [],
      storage: [],
    },
    animalCare?: Readonly<WildernessAnimalCareView>,
  ): void {
    this.title.textContent = activity.title.toUpperCase();
    this.detail.textContent = activity.detail;
    this.progress.style.width = `${Math.round(clamp(activity.progress, 0, 1) * 100)}%`;
    this.atmosphere.textContent = `${atmosphere.skyStoryName} · ${atmosphere.weatherStoryName} · ${atmosphere.weatherPhase}`;
    const smoke = clamp(indoorSmokeExposure, 0, 1);
    this.indoorSmoke.style.opacity = smoke.toFixed(3);
    this.indoorSmoke.classList.toggle('is-dangerous', smoke > 0.58);
    const condition = simulation.condition;
    const statusSignature = [
      Math.round(condition.health * 100),
      Math.round(condition.warmth * 100),
      Math.round(condition.energy * 100),
      Math.round((1 - condition.satiety) * 100),
      Math.round(condition.wetness * 100),
      condition.nearFire ? 'F' : condition.sheltered ? 'S' : 'E',
    ].join(':');
    if (statusSignature !== this.statusSignature) {
      this.statusSignature = statusSignature;
      this.status.replaceChildren(
        this.vital('HEALTH', condition.health),
        this.vital('WARMTH', condition.warmth, condition.nearFire ? 'BY FIRE' : condition.sheltered ? 'SHELTERED' : 'EXPOSED'),
        this.vital('ENERGY', condition.energy),
        this.vital('HUNGER', 1 - condition.satiety, '', true),
        this.vital('WETNESS', condition.wetness, '', true),
      );
    }
    const inventory = simulation.inventory;
    const inventoryRows: ReadonlyArray<readonly [string, number]> = [
      ['BRANCH', inventory.branches],
      ['TINDER', inventory.tinder],
      ['LOG', inventory.logs],
      ['STONE', inventory.stone],
      ['CHIP', inventory.stoneChips],
      ['FLINT', inventory.flint],
      ['FIBER', inventory.fiber],
      ['BERRY', inventory.berries],
      ['FISH', inventory.fish],
      ['GAME', inventory.smallGame],
      ['ROOT', inventory.roots],
      ['MELTWATER', inventory.cleanWater],
      ['EMBER FISH', inventory.emberFish],
      ['ROAST ROOT', inventory.roastedRoots],
      ['ROAST GAME', inventory.roastedGame],
      ['BERRY ROOT', inventory.berryRootMeals],
      ['TONIC', inventory.frostberryTonics],
      ['FIRE-ROOT', inventory.fireRoot],
      ['EXTRACT', inventory.fireRootExtract],
      ['OLD METAL', inventory.ancientMetal],
      ['ECHO-BLADE', inventory.ancientWeapon],
    ];
    const inventorySignature = inventoryRows.map(([label, amount]) =>
      `${label}:${amount}`).join('|');
    if (inventorySignature !== this.inventorySignature) {
      this.inventorySignature = inventorySignature;
      this.inventory.innerHTML = inventoryRows.map(([label, amount]) =>
        `<span class="${amount > 0 ? 'has-stock' : ''}"><b>${amount}</b>${label}</span>`).join('');
    }
    const backpackSignature = `${inventorySignature}|${simulation.selectedTool}|${ancient?.echoActive ? 'E' : 'N'}`;
    if (backpackSignature !== this.backpackSignature) {
      this.backpackSignature = backpackSignature;
      const ordinaryRows = WILDERNESS_PORTABLE_ITEM_ORDER.map((tool) => {
        const amount = tool === 'BRANCH' ? inventory.branches
          : tool === 'LOG' ? inventory.logs
          : tool === 'TINDER' ? inventory.tinder
          : tool === 'STONE' ? inventory.stone
          : tool === 'STONE_CHIP' ? inventory.stoneChips
          : tool === 'FLINT' ? inventory.flint
          : tool === 'FIBER' ? inventory.fiber
          : tool === 'BERRY' ? inventory.berries
          : tool === 'FISH' ? inventory.fish
          : tool === 'SMALL_GAME' ? inventory.smallGame
          : tool === 'ROOT' ? inventory.roots
          : undefined;
        return `<div class="wilderness-survival-backpack-row"><span><b>${WILDERNESS_TOOL_LABEL[tool]}</b><small>${amount ?? 0} carried</small></span>${amount !== undefined && amount > 0 ? `<button data-wilderness-drop-item="${tool}">DROP 1</button>` : ''}</div>`;
      }).join('');
      const ancientRows = [
        inventory.fireRoot > 0
          ? `<div class="wilderness-survival-backpack-row is-ancient"><span><b>FIRE-ROOT RHIZOME</b><small>${inventory.fireRoot} living root${inventory.fireRoot === 1 ? '' : 's'} · brew in warmth</small></span></div>`
          : '',
        inventory.fireRootExtract > 0
          ? `<div class="wilderness-survival-backpack-row is-ancient"><span><b>AMBER FIRE-ROOT EXTRACT</b><small>${inventory.fireRootExtract} dose${inventory.fireRootExtract === 1 ? '' : 's'} · Echo Sight lasts briefly</small></span><button data-wilderness-action="use-fire-root-extract" ${ancient?.echoActive ? 'disabled' : ''}>DRINK</button></div>`
          : '',
        inventory.ancientMetal > 0
          ? `<div class="wilderness-survival-backpack-row is-ancient"><span><b>PRIMAL METAL</b><small>${inventory.ancientMetal} resonant shard${inventory.ancientMetal === 1 ? '' : 's'}</small></span></div>`
          : '',
        inventory.ancientWeapon > 0
          ? `<div class="wilderness-survival-backpack-row is-ancient"><span><b>ECHO-BLADE</b><small>Visible and usable only through Echo Sight</small></span></div>`
          : '',
      ].join('');
      const provisionRows: ReadonlyArray<readonly [
        WildernessPreparedProvisionKind,
        string,
        number,
        string,
      ]> = [
        ['emberFish', 'EMBER FISH', inventory.emberFish, 'Warm meal · restores hunger and warmth'],
        ['roastedRoots', 'ROASTED WINTER ROOT', inventory.roastedRoots, 'Simple meal · restores energy'],
        ['roastedGame', 'SMALL-GAME ROAST', inventory.roastedGame, 'Substantial hot meal'],
        ['berryRootMeals', 'BERRY-GLAZED ROOT', inventory.berryRootMeals, 'A bright, sustaining meal'],
        ['frostberryTonics', 'FROSTBERRY TONIC', inventory.frostberryTonics, 'Warming remedy · dries wet cold'],
      ];
      const preparedRows = provisionRows.filter(([, , amount]) => amount > 0)
        .map(([kind, name, amount, detail]) => `<div class="wilderness-survival-backpack-row is-prepared"><span><b>${name}</b><small>${amount} prepared · ${detail}</small></span><button data-wilderness-provision="${kind}">${kind === 'frostberryTonics' ? 'DRINK' : 'EAT'}</button></div>`)
        .join('');
      this.backpack.innerHTML = ordinaryRows + preparedRows + ancientRows;
    }
    const planSignature = [
      simulation.toolCondition.stoneAxe,
      simulation.toolCondition.flintTool,
      simulation.selectedTool,
      ...WILDERNESS_PLAN_ORDER,
      ...simulation.progression.unlockedSkills,
    ].join('|');
    if (planSignature !== this.planSignature) {
      this.planSignature = planSignature;
      for (const button of this.toolButtons) {
        const tool = (button.dataset.wildernessPlan ?? 'HANDS') as WildernessTool;
        button.classList.toggle(
          'is-selected',
          tool === simulation.selectedTool ||
            (tool === 'HANDS' && !WILDERNESS_PLAN_ORDER.includes(simulation.selectedTool)),
        );
        button.disabled = tool === 'TRAP_KIT' &&
          !simulation.isSkillUnlocked('TRAPPING');
      }
      this.skills.innerHTML = WILDERNESS_SKILL_CATALOG
        .filter((skill) => simulation.isSkillUnlocked(skill.id))
        .map((skill) => `<span><b>${skill.name}</b><small>${skill.description}</small></span>`)
        .join('');
    }
    const fishing = simulation.fishingTiming();
    this.fishing.classList.toggle('is-hidden', !fishing);
    if (fishing) {
      const marker = this.fishing.querySelector<HTMLElement>('i > b');
      const target = this.fishing.querySelector<HTMLElement>('i > em');
      const instruction = this.fishing.querySelector<HTMLElement>('small');
      const ready = Math.abs(fishing.marker - fishing.target) <=
        fishing.tolerance;
      if (marker) marker.style.left = `${Math.round(fishing.marker * 100)}%`;
      if (target) {
        target.style.left = `${Math.round((fishing.target - fishing.tolerance) * 100)}%`;
        target.style.width = `${Math.round(fishing.tolerance * 2 * 100)}%`;
      }
      if (instruction) {
        instruction.textContent = ready
          ? `PULL NOW · F · ${Math.round(fishing.progress * 100)}% LANDED`
          : `LET IT BREATHE · ${Math.round(fishing.progress * 100)}% LANDED`;
      }
      this.fishing.classList.toggle('is-ready', ready);
      this.fishing.style.setProperty('--reel-progress', `${Math.round(fishing.progress * 100)}%`);
    }
    this.context.disabled = !interaction.enabled;
    this.context.classList.toggle('is-ready', interaction.enabled);
    this.context.querySelector('span')!.textContent = interaction.label;
    this.updateAnimalCare(animalCare);
    this.updateAncientEchoes(ancient);
    this.updateCartography(cartography);
    this.updateStation(station);
  }

  private updateAnimalCare(view?: Readonly<WildernessAnimalCareView>): void {
    this.animalCare.classList.toggle('is-hidden', !view);
    if (!view) {
      this.animalCareSignature = '';
      return;
    }
    const signature = [
      view.animalId,
      view.displayName,
      view.disposition,
      view.bodyLanguage,
      view.hint,
      view.canName ? 'NAME' : 'HIDDEN',
      view.givenName ?? '',
    ].join('|');
    if (signature === this.animalCareSignature) return;
    this.animalCareSignature = signature;
    this.animalCare.innerHTML = `
      <header><small>${view.speciesName.toUpperCase()}</small><strong>${view.displayName}</strong><em>${view.disposition}</em></header>
      <p>${view.bodyLanguage}</p>
      <small class="wilderness-animal-observation">${view.hint}</small>
      ${view.canName ? `<div class="wilderness-animal-name"><input data-wilderness-animal-name maxlength="24" value="${view.givenName ?? ''}" placeholder="Give a name"><button data-wilderness-name-animal="${view.animalId}">NAME</button></div>` : ''}
    `;
  }

  public dispose(): void {
    this.element.remove();
  }

  public toggleBackpack(): void {
    this.setBackpackOpen(!this.backpackOpen);
  }

  private setBackpackOpen(open: boolean): void {
    this.backpackOpen = open;
    this.backpackPanel.classList.toggle('is-open', open);
    const toggle = this.element.querySelector<HTMLButtonElement>('.wilderness-backpack-toggle');
    toggle?.setAttribute('aria-expanded', String(open));
  }

  private updateAncientEchoes(view?: Readonly<AncientEchoesView>): void {
    const strength = view?.echoStrength ?? 0;
    this.element.style.setProperty('--echo-strength', strength.toFixed(3));
    this.element.classList.toggle('is-echo-sight', strength > 0.005);
    this.echoStatus.classList.toggle('is-hidden', !view || view.stage === 'DORMANT');
    if (!view || view.stage === 'DORMANT') return;
    this.echoStatus.innerHTML = view.echoActive
      ? `<small>ECHO SIGHT</small><strong>${Math.ceil(view.echoSecondsRemaining)}s</strong><p>Old metal burns through the sepia fog. The dose is finite.</p>`
      : `<small>${view.stageName}</small><strong>ECHO DORMANT</strong><p>${view.objective}</p>`;
  }

  private updateStation(view: Readonly<SurvivalConstructionStationView>): void {
    this.station.classList.toggle('is-hidden', !view.open);
    if (!view.open) {
      this.stationSignature = '';
      return;
    }
    const signature = JSON.stringify(view);
    if (signature === this.stationSignature) return;
    this.stationSignature = signature;
    const header = this.station.querySelector('header strong');
    if (header) header.textContent = view.title?.toUpperCase() ?? 'FIELD STATION';
    if (view.kind === 'STORAGE') {
      const visibleRows = view.storage.filter((row) => row.carried > 0 || row.stored > 0);
      this.stationBody.innerHTML = `
        <p class="wilderness-station-lede">A dry place for gathered, cooked and crafted supplies.</p>
        <div class="wilderness-station-capacity"><span>CHEST LOAD</span><b>${view.usedCapacity ?? 0} / ${view.capacity ?? 0}</b><i><em style="width:${Math.round(clamp((view.usedCapacity ?? 0) / Math.max(1, view.capacity ?? 1), 0, 1) * 100)}%"></em></i></div>
        <div class="wilderness-station-storage">${visibleRows.length > 0
          ? visibleRows.map((row) => `<div><span><b>${row.label}</b><small>${row.carried} carried · ${row.stored} stored</small></span><button data-wilderness-storage="${row.inventory}" data-wilderness-storage-direction="DEPOSIT" ${row.canDeposit ? '' : 'disabled'}>STORE</button><button data-wilderness-storage="${row.inventory}" data-wilderness-storage-direction="WITHDRAW" ${row.canWithdraw ? '' : 'disabled'}>TAKE</button></div>`).join('')
          : '<p class="wilderness-station-empty">The chest and backpack are empty.</p>'}</div>`;
      return;
    }
    const heat = clamp(view.heat ?? 0, 0, 1);
    const work = view.work
      ? `<section class="wilderness-station-work ${view.work.paused ? 'is-paused' : ''}"><span>${view.work.paused ? 'WAITING FOR HEAT' : 'PREPARING'}</span><b>${view.work.name}</b><i><em style="width:${Math.round(view.work.progress * 100)}%"></em></i><small>${Math.ceil(view.work.remainingSeconds)} seconds remaining</small></section>`
      : '<p class="wilderness-station-empty">The hanging pot is ready.</p>';
    this.stationBody.innerHTML = `
      <p class="wilderness-station-lede">Fit this insert into a stone hearth. Flames begin the work; heat held by the masonry can finish it.</p>
      <div class="wilderness-station-heat"><span>HEARTH HEAT</span><b>${Math.round(heat * 100)}%</b><i><em style="width:${Math.round(heat * 100)}%"></em></i></div>
      ${work}
      <div class="wilderness-station-recipes">${view.recipes.map((recipe) => `<article class="${recipe.category === 'REMEDY' ? 'is-remedy' : ''}"><span><small>${recipe.category} · ${recipe.durationSeconds}s</small><b>${recipe.name}</b><p>${recipe.description}</p><em>${recipe.ingredients} → ${recipe.output}</em>${recipe.reason ? `<i>${recipe.reason}</i>` : ''}</span><button data-wilderness-recipe="${recipe.id}" ${recipe.enabled ? '' : 'disabled'}>PREPARE</button></article>`).join('')}</div>`;
  }

  private vital(
    label: string,
    value: number,
    state = '',
    lowerIsBetter = false,
  ): HTMLElement {
    const element = document.createElement('div');
    const percentage = Math.round(clamp(value, 0, 1) * 100);
    element.className = lowerIsBetter
      ? value > 0.72 ? 'is-low' : value < 0.28 ? 'is-good' : ''
      : value < 0.28 ? 'is-low' : value > 0.72 ? 'is-good' : '';
    element.innerHTML = `<small>${label}${state ? ` · ${state}` : ''}</small><i><b style="width:${percentage}%"></b></i>`;
    return element;
  }

  private updateCartography(view: Readonly<WildernessCartographyView>): void {
    this.map.classList.toggle('is-hidden', !view.open);
    if (!view.open) return;
    const last = view.trail.at(-1);
    const signature = [
      view.trail.length,
      view.visitedCells.length,
      view.landmarks.map((landmark) => landmark.id).join(','),
      last ? `${last.x.toFixed(1)}:${last.z.toFixed(1)}` : '',
    ].join('|');
    if (signature === this.mapSignature) return;
    this.mapSignature = signature;
    const point = (x: number, z: number): readonly [number, number] => [
      WildernessCartographySystem.mapPercent(x, view.centreX, view.radius),
      WildernessCartographySystem.mapPercent(z, view.centreZ, view.radius),
    ];
    const path = view.trail.map((trailPoint, index) => {
      const [x, y] = point(trailPoint.x, trailPoint.z);
      return `${index === 0 ? 'M' : 'L'}${x.toFixed(2)} ${y.toFixed(2)}`;
    }).join(' ');
    const visited = view.visitedCells.slice(-520).map((key) => {
      const [cellX = 0, cellZ = 0] = key.split(':').map(Number);
      const worldX = view.centreX + (cellX + 0.5) * 6;
      const worldZ = view.centreZ + (cellZ + 0.5) * 6;
      const [x, y] = point(worldX, worldZ);
      return `<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="1.8" />`;
    }).join('');
    const landmarks = view.landmarks.map((landmark) => {
      const [x, y] = point(landmark.x, landmark.z);
      return `<g class="wilderness-map-landmark" transform="translate(${x.toFixed(2)} ${y.toFixed(2)})"><circle r="2.7"/><text y="-4">${landmark.name}</text></g>`;
    }).join('');
    const [playerX, playerY] = point(view.playerX, view.playerZ);
    this.map.innerHTML = `
      <header><small>YOUR DRAWN MAP · M TO CLOSE</small><strong>THE LONG WINTER</strong><p>Only paths you have walked and places you have learned are inked here.</p></header>
      <svg viewBox="0 0 100 100" role="img" aria-label="Map drawn from explored wilderness">
        <defs><radialGradient id="wilderness-map-paper"><stop offset="0" stop-color="#f4e8c7"/><stop offset="1" stop-color="#d8c69d"/></radialGradient></defs>
        <circle class="wilderness-map-paper" cx="50" cy="50" r="48"/>
        <g class="wilderness-map-visited">${visited}</g>
        <path class="wilderness-map-trail" d="${path}"/>
        ${landmarks}
        <g class="wilderness-map-player" transform="translate(${playerX.toFixed(2)} ${playerY.toFixed(2)})"><circle r="2.1"/><path d="M0 -3 L-1.3 0.2 L1.3 0.2 Z"/></g>
        <text class="wilderness-map-north" x="50" y="6">N</text>
      </svg>
    `;
  }

  private require<T extends Element = HTMLElement>(selector: string): T {
    const element = this.element.querySelector<T>(selector);
    if (!element) throw new Error(`Missing wilderness HUD element: ${selector}`);
    return element;
  }
}
