import type { PenguinControlCommand } from '../input/PlayerPenguinController';
import { clamp, damp, smoothstep } from '../utils/math';
import { BOREALIS_ARRIVAL_LANDING, isBorealisLand } from './BorealisLand';

export interface PenguinState {
  x: number;
  z: number;
  heading: number;
  speed: number;
  blowerActive: boolean;
  snowDepth: number;
  /** Runtime-only height above the sampled walk surface. */
  verticalOffset: number;
  verticalVelocity: number;
  grounded: boolean;
  /** Current locomotion intent; presentation selects shallow/deep run clips. */
  running?: boolean;
}

export interface PenguinSaveData {
  version: 1;
  x: number;
  z: number;
  heading: number;
}

export interface PenguinWalkSurface {
  sampleDepth(x: number, z: number): number;
  resolveSnowResponse?(snowDepth: number): PenguinSnowResponse;
  /** Terrain slope in radians. Steeper, still-walkable ground slows feet. */
  sampleSlope?(x: number, z: number): number;
  /** Ground height lets movement distinguish climbing from descending. */
  sampleHeight?(x: number, z: number): number;
  canWalkAt?(x: number, z: number, verticalOffset: number): boolean;
}

export interface PenguinMovementIntent {
  moveX: number;
  moveZ: number;
  aimHeading?: number;
}

export interface PenguinStepResult {
  travelled: number;
  blocked: boolean;
  /** Downward speed immediately before a landing. Zero/undefined means this
   * fixed step did not land. */
  landingImpactSpeed?: number;
}

export interface PenguinSnowResponse {
  speedMultiplier: number;
  /** Optional human traversal boost; deep-snow running must remain useful. */
  runSpeedMultiplier?: number;
  sinkDepth: number;
  trailStrength: number;
}

/**
 * Physical contact dimensions for the 1.72 m survival actor.
 *
 * Movement resistance and trail width are intentionally independent:
 * knee-deep snow can slow the actor heavily while the two boots still leave
 * separate, foot-width impressions. A body-width wading trough only begins
 * once the snow approaches the upper thigh / hip.
 */
export interface HumanSnowContactProfile {
  readonly footSeparation: number;
  readonly canonicalFootRadius: number;
  readonly footCompression: number;
  /** Visible snow height against the 1.72 m actor after presentation sink. */
  readonly visualImmersion: number;
  /** Continuous lower-leg sweep; separate from the central hip trough. */
  readonly legSweepStrength: number;
  readonly bodyWadeStrength: number;
}

export const resolveHumanSnowContactProfile = (
  snowDepth: number,
): HumanSnowContactProfile => {
  const depth = Math.max(0, snowDepth);
  const sinkEngagement = smoothstep(0.04, 0.24, depth);
  const visualImmersion = Math.min(0.78, depth * 0.96 * sinkEngagement);
  const legSweepStrength = smoothstep(0.22, 0.5, visualImmersion);
  return {
    // Centre-to-centre boot spacing. It widens only when the actor really has
    // to force their legs around hip-deep snow.
    footSeparation: 0.19 + legSweepStrength * 0.035,
    // V3 is a 25 cm authoritative lattice, so this is only its durable proxy.
    // V5/V6 owns the exact 11-17 cm visual boot impression.
    canonicalFootRadius: 0.092 + legSweepStrength * 0.018,
    footCompression: 0.28 + legSweepStrength * 0.34,
    visualImmersion,
    legSweepStrength,
    // This is intentionally derived from what the player sees. At the spawn
    // drift the actor is immersed about 70 cm, so their pelvis must already
    // leave a full-width trough even though raw snow depth is below one metre.
    bodyWadeStrength: smoothstep(0.5, 0.72, visualImmersion),
  };
};

export const resolvePenguinSnowResponse = (
  snowDepth: number,
): PenguinSnowResponse => {
  const depth = Math.max(0, snowDepth);
  const resistance = smoothstep(0.18, 1, depth);
  const wading = smoothstep(0.31, 0.66, depth);
  return {
    speedMultiplier: 1 - resistance * 0.58,
    sinkDepth:
      wading * clamp((depth - 0.28) * 0.52, 0, 0.36),
    trailStrength: smoothstep(0.32, 0.64, depth),
  };
};

/** 1.72 m survival actor wades through, rather than rides over, deep snow. */
export const resolveHumanSnowResponse = (
  snowDepth: number,
): PenguinSnowResponse => {
  const depth = Math.max(0, snowDepth);
  const generalResistance = smoothstep(0.12, 0.85, depth);
  const extremeResistance = smoothstep(0.8, 1.6, depth);
  const deepRunResistance = smoothstep(0.42, 0.82, depth);
  const sinkEngagement = smoothstep(0.04, 0.24, depth);
  return {
    // Snow must communicate weight without turning ordinary traversal into a
    // punishment. The old compounded penguin + human curves left the spawn
    // drift at only ~24% speed. The human has a lightly brisk game-scale walk,
    // and hip-deep snow still retains about 80% of that response.
    speedMultiplier:
      1.08 - generalResistance * 0.28 - extremeResistance * 0.1,
    // The source run clip and old 2.18 m/s cap read as a fast walk. Keep the
    // walk controlled while allowing running to solve traversal tedium.
    // Keep the much friendlier traversal introduced for the survival slice,
    // but take a restrained 5-8% off running once the snow reaches the upper
    // thigh. Shallow ground and ordinary walking are intentionally unchanged.
    runSpeedMultiplier: 1.22 - deepRunResistance * 0.085,
    sinkDepth: Math.min(0.78, depth * 0.96 * sinkEngagement),
    // Keep leg resistance and trail width independent. The old 12 cm onset
    // turned ordinary knee-deep walking into a 68-104 cm bulldozer trench.
    trailStrength: resolveHumanSnowContactProfile(depth).bodyWadeStrength,
  };
};

export const writeHeadingRelativePenguinMovement = (
  right: number,
  forward: number,
  heading: number,
  target: PenguinMovementIntent,
): void => {
  const forwardX = Math.sin(heading);
  const forwardZ = Math.cos(heading);
  const rightX = Math.cos(heading);
  const rightZ = -Math.sin(heading);
  target.moveX = forwardX * forward + rightX * right;
  target.moveZ = forwardZ * forward + rightZ * right;
};

const WALK_SPEED = 1.38;
const RUN_SPEED = 2.18;

const angleDifference = (from: number, to: number): number =>
  Math.atan2(Math.sin(to - from), Math.cos(to - from));

export class PenguinSimulation {
  public readonly state: PenguinState = {
    x: BOREALIS_ARRIVAL_LANDING.x - 1.2,
    z: BOREALIS_ARRIVAL_LANDING.z + 1.5,
    heading: BOREALIS_ARRIVAL_LANDING.heading,
    speed: 0,
    blowerActive: false,
    snowDepth: 0,
    verticalOffset: 0,
    verticalVelocity: 0,
    grounded: true,
    running: false,
  };

  public step(
    command: Readonly<PenguinControlCommand>,
    deltaSeconds: number,
    surface: PenguinWalkSurface,
    intent: Readonly<PenguinMovementIntent>,
  ): PenguinStepResult {
    const delta = clamp(deltaSeconds, 0, 0.05);
    if (delta <= 0) return { travelled: 0, blocked: false };
    const state = this.state;
    state.blowerActive = command.blower;
    state.running = command.run;
    state.snowDepth = surface.sampleDepth(state.x, state.z);
    const snowResponse = surface.resolveSnowResponse?.(state.snowDepth) ??
      resolvePenguinSnowResponse(state.snowDepth);
    const movementMagnitude = clamp(
      Math.hypot(intent.moveX, intent.moveZ),
      0,
      1,
    );
    const directionScale = movementMagnitude > 0.001
      ? 1 / movementMagnitude
      : 0;
    const directionX = intent.moveX * directionScale;
    const directionZ = intent.moveZ * directionScale;
    const unsignedSlopeRadians = Math.max(
      0,
      surface.sampleSlope?.(state.x, state.z) ?? 0,
    );
    let signedSlopeRadians = unsignedSlopeRadians;
    if (surface.sampleHeight && movementMagnitude > 0.001) {
      // Sample in the actual travel direction. The former unsigned terrain
      // slope punished walking downhill and traversing across a hillside just
      // as heavily as climbing it.
      const probe = 0.52;
      const behind = 0.13;
      const forwardHeight = surface.sampleHeight(
        state.x + directionX * probe,
        state.z + directionZ * probe,
      );
      const rearHeight = surface.sampleHeight(
        state.x - directionX * behind,
        state.z - directionZ * behind,
      );
      signedSlopeRadians = Math.atan2(
        forwardHeight - rearHeight,
        probe + behind,
      );
    }
    // Uphill keeps a readable effort curve, but is 20% faster than the old
    // prototype. Downhill never inherits the climbing penalty and gains a
    // small, bounded gravity assist. Walkability still rejects true cliffs.
    const uphillSeverity = smoothstep(
      Math.PI * 0.075,
      Math.PI * 0.267,
      Math.max(0, signedSlopeRadians),
    );
    const oldUphillMultiplier = 1 - uphillSeverity * 0.62;
    const uphillMultiplier = uphillSeverity > 0
      ? Math.min(1, oldUphillMultiplier * 1.2)
      : 1;
    const downhillMultiplier = 1 + smoothstep(
      Math.PI * 0.035,
      Math.PI * 0.24,
      Math.max(0, -signedSlopeRadians),
    ) * 0.1;
    const slopeSpeedMultiplier = signedSlopeRadians < 0
      ? downhillMultiplier
      : uphillMultiplier;
    const maximumForward =
      (command.run ? RUN_SPEED : WALK_SPEED) *
      snowResponse.speedMultiplier *
      (command.run ? snowResponse.runSpeedMultiplier ?? 1 : 1) *
      slopeSpeedMultiplier *
      (state.blowerActive ? 0.56 : 1);
    const targetSpeed = movementMagnitude * maximumForward;
    state.speed = damp(state.speed, targetSpeed, 8.5, delta);
    if (movementMagnitude < 0.01) {
      state.speed = damp(state.speed, 0, 11, delta);
    }
    if (command.jump && state.grounded) {
      state.verticalVelocity = 3.75;
      state.grounded = false;
    }
    let landingImpactSpeed: number | undefined;
    if (!state.grounded) {
      state.verticalVelocity -= 9.4 * delta;
      state.verticalOffset += state.verticalVelocity * delta;
      if (state.verticalOffset <= 0) {
        landingImpactSpeed = Math.max(0, -state.verticalVelocity);
        state.verticalOffset = 0;
        state.verticalVelocity = 0;
        state.grounded = true;
      }
    }

    const movementHeading = movementMagnitude > 0.01
      ? Math.atan2(intent.moveX, intent.moveZ)
      : undefined;
    const targetHeading = intent.aimHeading ?? movementHeading;
    if (targetHeading !== undefined) {
      const response = intent.aimHeading === undefined ? 13 : 18;
      state.heading +=
        angleDifference(state.heading, targetHeading) *
        (1 - Math.exp(-response * delta));
    }

    const previousX = state.x;
    const previousZ = state.z;
    const nextX =
      state.x + intent.moveX * directionScale * state.speed * delta;
    const nextZ =
      state.z + intent.moveZ * directionScale * state.speed * delta;
    const allowed =
      isBorealisLand(nextX, nextZ) &&
      (surface.canWalkAt?.(nextX, nextZ, state.verticalOffset) ?? true);
    let slid = false;
    if (allowed) {
      state.x = nextX;
      state.z = nextZ;
    } else {
      // A binary diagonal rejection makes a rounded cave wall feel sticky:
      // the blocked component also cancels the tangential component. Try the
      // two cardinal components independently so the actor glides along the
      // actual Surface Nets boundary instead of catching on every triangle.
      const canMoveX = Math.abs(nextX - previousX) > 0.000001 &&
        isBorealisLand(nextX, previousZ) &&
        (surface.canWalkAt?.(
          nextX,
          previousZ,
          state.verticalOffset,
        ) ?? true);
      if (canMoveX) {
        state.x = nextX;
        slid = true;
      }
      const canMoveZ = Math.abs(nextZ - previousZ) > 0.000001 &&
        isBorealisLand(state.x, nextZ) &&
        (surface.canWalkAt?.(
          state.x,
          nextZ,
          state.verticalOffset,
        ) ?? true);
      if (canMoveZ) {
        state.z = nextZ;
        slid = true;
      }
      if (!slid) state.speed = 0;
    }
    return {
      travelled: Math.hypot(state.x - previousX, state.z - previousZ),
      blocked: !allowed && !slid,
      ...(landingImpactSpeed !== undefined ? { landingImpactSpeed } : {}),
    };
  }

  public deployBesideVehicle(
    vehicle: Readonly<{ x: number; z: number; heading: number }>,
    canStandAt: (x: number, z: number) => boolean = () => true,
  ): void {
    const rightX = Math.cos(vehicle.heading);
    const rightZ = -Math.sin(vehicle.heading);
    const forwardX = Math.sin(vehicle.heading);
    const forwardZ = Math.cos(vehicle.heading);
    const candidates = [
      { side: 1.75, rear: 0 },
      { side: -1.75, rear: 0 },
      { side: 1.5, rear: -1.25 },
      { side: -1.5, rear: -1.25 },
    ];
    for (const candidate of candidates) {
      const x =
        vehicle.x + rightX * candidate.side + forwardX * candidate.rear;
      const z =
        vehicle.z + rightZ * candidate.side + forwardZ * candidate.rear;
      if (!isBorealisLand(x, z) || !canStandAt(x, z)) continue;
      this.state.x = x;
      this.state.z = z;
      this.state.heading = vehicle.heading;
      this.state.speed = 0;
      this.state.blowerActive = false;
      this.resetJump();
      return;
    }
    this.state.x = vehicle.x;
    this.state.z = vehicle.z;
    this.state.heading = vehicle.heading;
    this.state.speed = 0;
    this.state.blowerActive = false;
    this.resetJump();
  }

  public importState(saved: unknown): boolean {
    if (!saved || typeof saved !== 'object') return false;
    const candidate = saved as Partial<PenguinSaveData>;
    if (
      candidate.version !== 1 ||
      !Number.isFinite(candidate.x) ||
      !Number.isFinite(candidate.z) ||
      !Number.isFinite(candidate.heading) ||
      !isBorealisLand(candidate.x!, candidate.z!)
    ) {
      return false;
    }
    this.state.x = candidate.x!;
    this.state.z = candidate.z!;
    this.state.heading = candidate.heading!;
    this.state.speed = 0;
    this.state.blowerActive = false;
    this.resetJump();
    return true;
  }

  public exportState(): PenguinSaveData {
    return {
      version: 1,
      x: this.state.x,
      z: this.state.z,
      heading: this.state.heading,
    };
  }

  private resetJump(): void {
    this.state.verticalOffset = 0;
    this.state.verticalVelocity = 0;
    this.state.grounded = true;
  }
}
