import {
  survivalBuildV3EdgeEndpoints,
  survivalBuildV3LocalToWorld,
  type SurvivalBuildV3AnchorAddress,
  type SurvivalBuildV3Frame,
} from './SurvivalBuildV3Model';

export type SurvivalBuildV3TerrainFitStatus =
  | 'READY'
  | 'NEEDS_PIERS'
  | 'NEEDS_SITE_PREPARATION'
  | 'BLOCKED';

export interface SurvivalBuildV3TerrainSupportSample {
  readonly t: number;
  readonly x: number;
  readonly z: number;
  readonly groundY: number;
  /** Positive means a pier/support is needed below the level foundation. */
  readonly supportDepth: number;
  /** Positive means terrain must be cleared below the level foundation. */
  readonly cutDepth: number;
}

export interface SurvivalBuildV3TerrainFit {
  readonly status: SurvivalBuildV3TerrainFitStatus;
  readonly samples: readonly SurvivalBuildV3TerrainSupportSample[];
  readonly relief: number;
  readonly maximumSupportDepth: number;
  readonly maximumCutDepth: number;
}

export type SurvivalBuildV3TerrainHeightSampler = (
  x: number,
  z: number,
) => number;

// TLW is not Yarrgone's flat deck. A cabin may begin on a fell, creek bank or
// snow-buried slope, so the level structural frame is allowed to grow real
// piers far below itself. Uphill intersections remain bounded because they
// require excavation rather than a longer support.
const BLOCKED_SUPPORT_DEPTH = 8;
const BLOCKED_CUT_DEPTH = 1.8;
const BLOCKED_RELIEF = 8.25;
const SITE_PREPARATION_CUT_DEPTH = 0.12;
const PIER_DEPTH = 0.18;

/**
 * Samples a level foundation rail against terrain without bending the
 * structure to the hill. Runtime visuals can turn the returned support depth
 * into authored stone/log piers; the same result is stored at commit time.
 */
export const evaluateSurvivalBuildV3FoundationTerrainFit = (
  frame: Readonly<SurvivalBuildV3Frame>,
  anchor: Readonly<SurvivalBuildV3AnchorAddress>,
  sampleHeight: SurvivalBuildV3TerrainHeightSampler,
): SurvivalBuildV3TerrainFit | undefined => {
  if (anchor.kind !== 'EDGE') return undefined;
  const [first, second] = survivalBuildV3EdgeEndpoints(anchor.edge);
  const samples: SurvivalBuildV3TerrainSupportSample[] = [];
  let minimumGround = Number.POSITIVE_INFINITY;
  let maximumGround = Number.NEGATIVE_INFINITY;
  let maximumSupportDepth = 0;
  let maximumCutDepth = 0;
  for (const t of [0, 0.5, 1] as const) {
    const localU = first.u + (second.u - first.u) * t;
    const localV = first.v + (second.v - first.v) * t;
    const world = survivalBuildV3LocalToWorld(frame, {
      x: localU * frame.moduleMetres,
      y: anchor.level * frame.storeyHeightMetres,
      z: localV * frame.moduleMetres,
    });
    const groundY = sampleHeight(world.x, world.z);
    const delta = world.y - groundY;
    const supportDepth = Math.max(0, delta);
    const cutDepth = Math.max(0, -delta);
    minimumGround = Math.min(minimumGround, groundY);
    maximumGround = Math.max(maximumGround, groundY);
    maximumSupportDepth = Math.max(maximumSupportDepth, supportDepth);
    maximumCutDepth = Math.max(maximumCutDepth, cutDepth);
    samples.push({
      t,
      x: world.x,
      z: world.z,
      groundY,
      supportDepth,
      cutDepth,
    });
  }
  const relief = maximumGround - minimumGround;
  const blocked = maximumSupportDepth > BLOCKED_SUPPORT_DEPTH ||
    maximumCutDepth > BLOCKED_CUT_DEPTH || relief > BLOCKED_RELIEF;
  const status: SurvivalBuildV3TerrainFitStatus = blocked
    ? 'BLOCKED'
    : maximumCutDepth > SITE_PREPARATION_CUT_DEPTH
      ? 'NEEDS_SITE_PREPARATION'
      : maximumSupportDepth > PIER_DEPTH
        ? 'NEEDS_PIERS'
        : 'READY';
  return {
    status,
    samples,
    relief,
    maximumSupportDepth,
    maximumCutDepth,
  };
};
