import type { WorldSimulation } from '../simulation/WorldSimulation';

export interface EmergentWorldInspector {
  snapshot(): ReturnType<WorldSimulation['getEmergentSnapshot']>;
  definitions(): WorldSimulation['emergentRegistry']['definitions'];
  explain(subjectId: string): ReturnType<WorldSimulation['causalityTrace']['explain']>;
  trace(subjectId?: string): ReturnType<WorldSimulation['causalityTrace']['inspect']>;
  setNpcGoal(npcId: string, goalId?: string): boolean;
  startStoryQuest(questId: string): boolean;
}

export const installEmergentWorldInspector = (
  world: WorldSimulation,
): EmergentWorldInspector => {
  const inspector: EmergentWorldInspector = Object.freeze({
    snapshot: () => world.getEmergentSnapshot(),
    definitions: () => world.emergentRegistry.definitions,
    explain: (subjectId: string) => world.causalityTrace.explain(subjectId),
    trace: (subjectId?: string) => world.causalityTrace.inspect(subjectId),
    setNpcGoal: (npcId: string, goalId?: string) => world.setNpcGoalOverride(npcId, goalId),
    startStoryQuest: (questId: string) => world.startStoryQuest(questId),
  });
  (window as Window & { __ICEWAY_EMERGENCE__?: EmergentWorldInspector }).__ICEWAY_EMERGENCE__ = inspector;
  return inspector;
};
