import {
  createConstructionBlueprint,
  type ConstructionBlueprint,
  type ConstructionBlueprintKind,
  type ConstructionMaterialId,
  type ConstructionPlacement,
  type ConstructionSurfaceId,
} from './ConstructionBlueprint';
import { getConstructionModule } from './ConstructionModuleCatalog';

export type ConstructionTemplateId =
  | 'blank-vessel'
  | 'icebreaker-starter'
  | 'fishing-hut-starter'
  | 'resource-platform-starter'
  | 'harbor-workshop-starter';

export interface ConstructionTemplateDefinition {
  id: ConstructionTemplateId;
  kind: ConstructionBlueprintKind;
  label: string;
  description: string;
}

export const CONSTRUCTION_TEMPLATES: readonly ConstructionTemplateDefinition[] = [
  {
    id: 'blank-vessel',
    kind: 'vessel',
    label: 'Blank vessel',
    description: 'An empty 25 cm grid for a fully custom vessel.',
  },
  {
    id: 'icebreaker-starter',
    kind: 'vessel',
    label: 'Icebreaker starter',
    description: 'A visible continuous V-bottom foundation with a rounded stern and compound bow.',
  },
  {
    id: 'fishing-hut-starter',
    kind: 'fishing-hut',
    label: 'Fishing hut',
    description: 'A small floating foundation, enclosed work room and roof.',
  },
  {
    id: 'resource-platform-starter',
    kind: 'resource-platform',
    label: 'Resource platform',
    description: 'A broad working platform ready for machinery and utility modules.',
  },
  {
    id: 'harbor-workshop-starter',
    kind: 'harbor-facility',
    label: 'Harbor workshop',
    description: 'A quay-side workshop shell with expandable foundation.',
  },
] as const;

const placement = (
  id: string,
  moduleId: string,
  x: number,
  y: number,
  z: number,
  yawDegrees = 0,
  materialId?: ConstructionMaterialId,
  surfaceId?: ConstructionSurfaceId,
): ConstructionPlacement => {
  const definition = getConstructionModule(moduleId);
  if (!definition) throw new Error(`Unknown template module: ${moduleId}`);
  return {
    id,
    moduleId,
    position: { x, y, z },
    yawDegrees,
    pitchDegrees: 0,
    rollDegrees: 0,
    flipped: false,
    materialId: materialId ?? definition.defaultMaterial,
    surfaceId: surfaceId ?? definition.defaultSurface,
    machineState: definition.mechanism
      ? { enabled: true, control: 0.72 }
      : undefined,
    mount: { kind: 'grid' },
  };
};

const fillGrid = (
  prefix: string,
  moduleId: string,
  xs: readonly number[],
  zs: readonly number[],
  y: number,
  materialId?: ConstructionMaterialId,
): ConstructionPlacement[] => {
  const result: ConstructionPlacement[] = [];
  for (const x of xs) {
    for (const z of zs) {
      result.push(
        placement(`${prefix}-${x}-${z}`, moduleId, x, y, z, 0, materialId),
      );
    }
  }
  return result;
};

const roof = (
  prefix: string,
  xs: readonly number[],
  zs: readonly number[],
  y: number,
): ConstructionPlacement[] =>
  fillGrid(prefix, 'roof-panel', xs, zs, y, 'hull-red');

export const createConstructionTemplate = (
  templateId: ConstructionTemplateId,
  now = new Date(),
): ConstructionBlueprint => {
  if (templateId === 'blank-vessel') {
    return createConstructionBlueprint('Untitled vessel', now, 'vessel');
  }

  if (templateId === 'icebreaker-starter') {
    const blueprint = createConstructionBlueprint(
      'Icebreaker concept',
      now,
      'vessel',
    );
    blueprint.placements = [
      placement('starter-rounded-stern', 'hull-stern-rounded', 0, 0, -6),
      placement('starter-v-bottom-aft', 'hull-v-bottom-1m', 0, 0, -2),
      placement('starter-v-bottom-forward', 'hull-v-bottom-1m', 0, 0, 2),
      placement('starter-compound-bow', 'hull-bow-compound', 0, 0, 6),
    ];
    return blueprint;
  }

  if (templateId === 'fishing-hut-starter') {
    const blueprint = createConstructionBlueprint(
      'Fishing hut concept',
      now,
      'fishing-hut',
    );
    blueprint.placements = [
      ...fillGrid(
        'hut-base',
        'foundation-pontoon',
        [-4, 0, 4],
        [-4, 0, 4],
        0,
      ),
      placement('hut-room', 'cabin-block', 0, 2, 0, 0, 'arctic-white'),
      placement('hut-generator', 'generator-set', 6, 2, 0),
      placement('hut-winch', 'fishing-winch', -6, 2, 0),
      ...roof('hut-roof', [-4, 0, 4], [-4, 0, 4], 10),
    ];
    return blueprint;
  }

  if (templateId === 'resource-platform-starter') {
    const blueprint = createConstructionBlueprint(
      'Deep-resource platform concept',
      now,
      'resource-platform',
    );
    blueprint.placements = [
      ...fillGrid(
        'platform-base',
        'foundation-pontoon',
        [-6, -2, 2, 6],
        [-6, -2, 2, 6],
        0,
      ),
      placement('platform-control-room', 'cabin-block', -2, 2, -2),
      placement('platform-drill', 'resource-drill', 6, 2, 2),
      placement('platform-generator', 'generator-set', 2, 2, 8),
      placement('platform-crane', 'deck-crane', -6, 2, 6),
    ];
    return blueprint;
  }

  const blueprint = createConstructionBlueprint(
    'Harbor workshop concept',
    now,
    'harbor-facility',
  );
  blueprint.placements = [
    ...fillGrid(
      'workshop-base',
      'foundation-pontoon',
      [-6, -2, 2, 6],
      [-4, 0, 4],
      0,
    ),
    placement('workshop-room-left', 'cabin-block', -4, 2, 0),
    placement('workshop-room-right', 'cabin-block', 4, 2, 0),
    ...roof('workshop-roof', [-6, -2, 2, 6], [-4, 0, 4], 10),
  ];
  return blueprint;
};
