/**
 * Explicit tester affordances. Production progression remains unchanged unless
 * the build is deliberately created with VITE_ICEWAY_PLAYTEST=true.
 */
export const ICEWAY_PLAYTEST_MODE =
  import.meta.env.DEV || import.meta.env.VITE_ICEWAY_PLAYTEST === 'true';

/** Visible identifier so testers can report the exact browser build in use. */
export const ICEWAY_BUILD_ID =
  import.meta.env.VITE_ICEWAY_BUILD_ID?.trim() ||
  (import.meta.env.DEV ? 'DEV SOURCE' : 'PRODUCTION');

/**
 * Build V3 is now the canonical The Long Winter construction authority. The
 * explicit false seam is retained for emergency comparison builds only; it
 * must never grant playtest inventory or other god-mode privileges.
 */
export const THE_LONG_WINTER_BUILD_V3_ENABLED =
  import.meta.env.VITE_TLW_BUILD_V3 !== 'false';

/**
 * The Long Winter is still in construction-feel playtesting. Keep building
 * costs detached from the survival inventory in every served build so a
 * production-mode preview cannot accidentally force testers to farm logs.
 * Set VITE_TLW_FREE_CONSTRUCTION=false for an explicit economy test build.
 */
export const THE_LONG_WINTER_FREE_CONSTRUCTION_ENABLED =
  import.meta.env.VITE_TLW_FREE_CONSTRUCTION !== 'false';

/**
 * A detachable The Long Winter feature island: fire-root, Echo Sight,
 * excavation, the buried stone laboratory and Mechanos. It defaults on in
 * the playable prototype, but a single explicit false restores the survival
 * game without importing any of its progression into the core loop.
 */
export const THE_LONG_WINTER_ANCIENT_ECHOES_ENABLED =
  import.meta.env.VITE_TLW_ANCIENT_ECHOES !== 'false';

/** Fine-grained rollback seams for experiments inside Ancient Echoes. */
export const THE_LONG_WINTER_MECHANOS_ENABLED =
  THE_LONG_WINTER_ANCIENT_ECHOES_ENABLED &&
  import.meta.env.VITE_TLW_MECHANOS !== 'false';
export const THE_LONG_WINTER_FIRE_ROOT_ENABLED =
  THE_LONG_WINTER_ANCIENT_ECHOES_ENABLED &&
  import.meta.env.VITE_TLW_FIRE_ROOT !== 'false';
export const THE_LONG_WINTER_STONE_LAB_ENABLED =
  THE_LONG_WINTER_ANCIENT_ECHOES_ENABLED &&
  import.meta.env.VITE_TLW_STONE_LAB !== 'false';

/**
 * Standalone visual prototype for the colour-draining shadow monolith near
 * the survival spawn. It deliberately has its own rollback seam because the
 * eventual shadow-world mechanics must not be coupled to Ancient Echoes.
 */
export const THE_LONG_WINTER_SHADOW_MONOLITH_ENABLED =
  import.meta.env.VITE_TLW_SHADOW_MONOLITH === 'true';
