import {
  type Revision,
  type ServerTick,
  revision,
  serverTick,
} from '../core/NetworkPrimitives';
import {
  LAND_SNOW_FORMAT_VERSION,
  LAND_SNOW_SAMPLE_COUNT,
  type PackedSnowSample,
} from '../../land/LandSnowData';

interface SnowTileSnapshotSource {
  tileX: number;
  tileZ: number;
  revision: Revision;
  changes: readonly PackedSnowSample[];
}

interface SnowTileDeltaSource extends SnowTileSnapshotSource {
  baseRevision: Revision;
  serverTick: ServerTick;
  removedIndices: readonly number[];
}

export interface PackedSnowSampleRun {
  startIndex: number;
  /** Alternating encoded depth (u16) and compaction (u8). */
  values: readonly number[];
}

export interface PackedSnowIndexRun {
  startIndex: number;
  count: number;
}

export interface ReplicatedSnowTileBaseline {
  tileX: number;
  tileZ: number;
  revision: Revision;
  checksum: string;
  runs: readonly PackedSnowSampleRun[];
}

export interface ReplicatedSnowTileDelta extends ReplicatedSnowTileBaseline {
  baseRevision: Revision;
  removedRuns: readonly PackedSnowIndexRun[];
}

export interface SnowBaselinePartPayload {
  version: 1;
  kind: 'SNOW_BASELINE_PART';
  scope: 'FULL' | 'TILE_RESYNC';
  baselineId: string;
  formatVersion: typeof LAND_SNOW_FORMAT_VERSION;
  worldDatasetHash: string;
  transferId: string;
  partIndex: number;
  partCount: number;
  serverTick: ServerTick;
  tiles: readonly ReplicatedSnowTileBaseline[];
}

export interface SnowDeltaPayload {
  version: 1;
  kind: 'SNOW_TILE_DELTA';
  deltaSequence: number;
  serverTick: ServerTick;
  tiles: readonly ReplicatedSnowTileDelta[];
}

export interface SnowTileResyncRequestPayload {
  version: 1;
  tileX: number;
  tileZ: number;
  observedRevision: Revision;
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const integer = (value: unknown, minimum: number, maximum: number): value is number =>
  typeof value === 'number' && Number.isSafeInteger(value) &&
  value >= minimum && value <= maximum;
const boundedString = (value: unknown, maximum: number): value is string =>
  typeof value === 'string' && value.length > 0 && value.length <= maximum;

export const packSnowSampleRuns = (
  samples: readonly PackedSnowSample[],
): readonly PackedSnowSampleRun[] => {
  const sorted = [...samples].sort((a, b) => a[0] - b[0]);
  const runs: Array<{ startIndex: number; values: number[] }> = [];
  let previousIndex = -2;
  for (const [index, depth, compaction] of sorted) {
    if (
      !integer(index, 0, LAND_SNOW_SAMPLE_COUNT - 1) ||
      !integer(depth, 0, 65_535) ||
      !integer(compaction, 0, 255)
    ) throw new Error('Cannot pack an invalid snow sample.');
    const previous = runs[runs.length - 1];
    if (!previous || index !== previousIndex + 1) {
      runs.push({ startIndex: index, values: [depth, compaction] });
    } else {
      previous.values.push(depth, compaction);
    }
    previousIndex = index;
  }
  return runs;
};

export const unpackSnowSampleRuns = (
  runs: readonly PackedSnowSampleRun[],
): readonly PackedSnowSample[] => {
  const samples: PackedSnowSample[] = [];
  const seen = new Set<number>();
  for (const run of runs) {
    if (
      !integer(run.startIndex, 0, LAND_SNOW_SAMPLE_COUNT - 1) ||
      !Array.isArray(run.values) ||
      run.values.length === 0 ||
      run.values.length % 2 !== 0 ||
      run.values.length > LAND_SNOW_SAMPLE_COUNT * 2
    ) throw new Error('Invalid packed snow sample run.');
    for (let offset = 0; offset < run.values.length; offset += 2) {
      const index = run.startIndex + offset / 2;
      const depth = run.values[offset];
      const compaction = run.values[offset + 1];
      if (
        !integer(index, 0, LAND_SNOW_SAMPLE_COUNT - 1) ||
        !integer(depth, 0, 65_535) ||
        !integer(compaction, 0, 255) ||
        seen.has(index)
      ) throw new Error('Invalid packed snow sample value.');
      seen.add(index);
      samples.push([index, depth, compaction]);
    }
  }
  return samples.sort((a, b) => a[0] - b[0]);
};

export const packSnowIndexRuns = (
  indices: readonly number[],
): readonly PackedSnowIndexRun[] => {
  const sorted = [...new Set(indices)].sort((a, b) => a - b);
  const runs: Array<{ startIndex: number; count: number }> = [];
  for (const index of sorted) {
    if (!integer(index, 0, LAND_SNOW_SAMPLE_COUNT - 1)) {
      throw new Error('Cannot pack an invalid snow sample index.');
    }
    const previous = runs[runs.length - 1];
    if (previous && index === previous.startIndex + previous.count) {
      previous.count += 1;
    } else {
      runs.push({ startIndex: index, count: 1 });
    }
  }
  return runs;
};

export const unpackSnowIndexRuns = (
  runs: readonly PackedSnowIndexRun[],
): readonly number[] => {
  const indices: number[] = [];
  const seen = new Set<number>();
  for (const run of runs) {
    if (
      !integer(run.startIndex, 0, LAND_SNOW_SAMPLE_COUNT - 1) ||
      !integer(run.count, 1, LAND_SNOW_SAMPLE_COUNT) ||
      run.startIndex + run.count > LAND_SNOW_SAMPLE_COUNT
    ) throw new Error('Invalid packed snow index run.');
    for (let offset = 0; offset < run.count; offset += 1) {
      const index = run.startIndex + offset;
      if (seen.has(index)) throw new Error('Overlapping packed snow index run.');
      seen.add(index);
      indices.push(index);
    }
  }
  return indices.sort((a, b) => a - b);
};

export const snowTileChecksum = (
  tileX: number,
  tileZ: number,
  tileRevision: Revision,
  changes: readonly PackedSnowSample[],
): string => {
  let hash = 0x811c9dc5;
  const accept = (value: number): void => {
    let remaining = value | 0;
    for (let byte = 0; byte < 4; byte += 1) {
      hash ^= remaining & 0xff;
      hash = Math.imul(hash, 0x01000193) >>> 0;
      remaining >>= 8;
    }
  };
  accept(tileX);
  accept(tileZ);
  accept(tileRevision);
  for (const [index, depth, compaction] of [...changes].sort((a, b) => a[0] - b[0])) {
    accept(index);
    accept(depth);
    accept(compaction);
  }
  return hash.toString(16).padStart(8, '0');
};

export const replicatedSnowBaselineTile = (
  tile: Readonly<SnowTileSnapshotSource>,
): ReplicatedSnowTileBaseline => ({
  tileX: tile.tileX,
  tileZ: tile.tileZ,
  revision: tile.revision,
  checksum: snowTileChecksum(tile.tileX, tile.tileZ, tile.revision, tile.changes),
  runs: packSnowSampleRuns(tile.changes),
});

export const replicatedSnowDeltaTile = (
  delta: Readonly<SnowTileDeltaSource>,
  fullTile: Readonly<SnowTileSnapshotSource>,
): ReplicatedSnowTileDelta => ({
  tileX: delta.tileX,
  tileZ: delta.tileZ,
  baseRevision: delta.baseRevision,
  revision: delta.revision,
  checksum: snowTileChecksum(
    fullTile.tileX,
    fullTile.tileZ,
    fullTile.revision,
    fullTile.changes,
  ),
  runs: packSnowSampleRuns(delta.changes),
  removedRuns: packSnowIndexRuns(delta.removedIndices),
});

const validateRuns = (input: unknown): readonly PackedSnowSampleRun[] | undefined => {
  if (!Array.isArray(input) || input.length > 256) return undefined;
  const runs: PackedSnowSampleRun[] = [];
  try {
    for (const candidate of input) {
      if (!isRecord(candidate) || !Array.isArray(candidate.values)) return undefined;
      const run = {
        startIndex: candidate.startIndex as number,
        values: candidate.values as number[],
      };
      unpackSnowSampleRuns([run]);
      runs.push({ startIndex: run.startIndex, values: [...run.values] });
    }
    unpackSnowSampleRuns(runs);
  } catch {
    return undefined;
  }
  return runs;
};

const validateIndexRuns = (
  input: unknown,
): readonly PackedSnowIndexRun[] | undefined => {
  if (!Array.isArray(input) || input.length > 256) return undefined;
  const runs: PackedSnowIndexRun[] = [];
  try {
    for (const candidate of input) {
      if (!isRecord(candidate)) return undefined;
      const run = {
        startIndex: candidate.startIndex as number,
        count: candidate.count as number,
      };
      unpackSnowIndexRuns([run]);
      runs.push(run);
    }
    unpackSnowIndexRuns(runs);
  } catch {
    return undefined;
  }
  return runs;
};

const validateTile = (
  input: unknown,
  delta: boolean,
): ReplicatedSnowTileBaseline | ReplicatedSnowTileDelta | undefined => {
  if (
    !isRecord(input) ||
    !integer(input.tileX, -1_000_000, 1_000_000) ||
    !integer(input.tileZ, -1_000_000, 1_000_000) ||
    !integer(input.revision, 0, Number.MAX_SAFE_INTEGER) ||
    !boundedString(input.checksum, 32)
  ) return undefined;
  const runs = validateRuns(input.runs);
  if (!runs) return undefined;
  const base = {
    tileX: input.tileX,
    tileZ: input.tileZ,
    revision: revision(input.revision),
    checksum: input.checksum,
    runs,
  };
  if (!delta) return base;
  if (!integer(input.baseRevision, 0, Number.MAX_SAFE_INTEGER)) return undefined;
  const removedRuns = validateIndexRuns(input.removedRuns);
  if (!removedRuns) return undefined;
  try {
    const changedIndices = new Set(unpackSnowSampleRuns(runs).map((sample) => sample[0]));
    if (unpackSnowIndexRuns(removedRuns).some((index) => changedIndices.has(index))) {
      return undefined;
    }
  } catch {
    return undefined;
  }
  return {
    ...base,
    baseRevision: revision(input.baseRevision),
    removedRuns,
  };
};

export const validateSnowBaselinePartPayload = (
  input: unknown,
): SnowBaselinePartPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    input.kind !== 'SNOW_BASELINE_PART' ||
    (input.scope !== 'FULL' && input.scope !== 'TILE_RESYNC') ||
    !boundedString(input.baselineId, 160) ||
    input.formatVersion !== LAND_SNOW_FORMAT_VERSION ||
    !boundedString(input.worldDatasetHash, 256) ||
    !boundedString(input.transferId, 160) ||
    !integer(input.partIndex, 0, 4_095) ||
    !integer(input.partCount, 1, 4_096) ||
    input.partIndex >= input.partCount ||
    !integer(input.serverTick, 0, Number.MAX_SAFE_INTEGER) ||
    !Array.isArray(input.tiles) ||
    input.tiles.length > 16
  ) return undefined;
  const tiles = input.tiles.map((tile) => validateTile(tile, false));
  if (tiles.some((tile) => !tile)) return undefined;
  return {
    version: 1,
    kind: 'SNOW_BASELINE_PART',
    scope: input.scope,
    baselineId: input.baselineId,
    formatVersion: LAND_SNOW_FORMAT_VERSION,
    worldDatasetHash: input.worldDatasetHash,
    transferId: input.transferId,
    partIndex: input.partIndex,
    partCount: input.partCount,
    serverTick: serverTick(input.serverTick),
    tiles: tiles as ReplicatedSnowTileBaseline[],
  };
};

export const validateSnowDeltaPayload = (input: unknown): SnowDeltaPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    input.kind !== 'SNOW_TILE_DELTA' ||
    !integer(input.deltaSequence, 1, Number.MAX_SAFE_INTEGER) ||
    !integer(input.serverTick, 0, Number.MAX_SAFE_INTEGER) ||
    !Array.isArray(input.tiles) ||
    input.tiles.length > 64
  ) return undefined;
  const tiles = input.tiles.map((tile) => validateTile(tile, true));
  if (tiles.some((tile) => !tile)) return undefined;
  return {
    version: 1,
    kind: 'SNOW_TILE_DELTA',
    deltaSequence: input.deltaSequence,
    serverTick: serverTick(input.serverTick),
    tiles: tiles as ReplicatedSnowTileDelta[],
  };
};

export const validateSnowTileResyncRequestPayload = (
  input: unknown,
): SnowTileResyncRequestPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    !integer(input.tileX, -1_000_000, 1_000_000) ||
    !integer(input.tileZ, -1_000_000, 1_000_000) ||
    !integer(input.observedRevision, 0, Number.MAX_SAFE_INTEGER)
  ) return undefined;
  return {
    version: 1,
    tileX: input.tileX,
    tileZ: input.tileZ,
    observedRevision: revision(input.observedRevision),
  };
};
