export const resolveStarterBulldozerCapabilities = (
  isOwned: (upgradeId: string) => boolean,
): BulldozerCapabilities => {
  const chainTracks = isOwned(BULLDOZER_UPGRADE_IDS.chainTracks);
  const wideTracks = chainTracks || isOwned(BULLDOZER_UPGRADE_IDS.wideTracks);
  return {
    adjustableWingPlow: isOwned(
      BULLDOZER_UPGRADE_IDS.adjustableWingPlow,
    ),
    wideTracks,
    chainTracks,
    polarWorkLights: isOwned(BULLDOZER_UPGRADE_IDS.polarWorkLights),
    amberBeacon: isOwned(BULLDOZER_UPGRADE_IDS.amberBeacon),
    heavyChassis: false,
    highCapacityBlade: false,
    heavyPowertrain: false,
    maximumPushDepth: chainTracks ? 0.82 : wideTracks ? 0.65 : 0.5,
    maximumFrontPileDepth: chainTracks ? 1.78 : wideTracks ? 1.52 : 1.28,
    maximumPileDepth: 4.8,
    massCapacityMultiplier: chainTracks ? 1.02 : wideTracks ? 0.86 : 0.72,
    tractionLimit: chainTracks ? 0.84 : wideTracks ? 0.7 : 0.56,
    displayTier: 'STARTER',
  };
};

export const resolveBulldozerCapabilities = (
  isOwned: (upgradeId: string) => boolean,
): BulldozerCapabilities => {
  const starter = resolveStarterBulldozerCapabilities(isOwned);
  const heavyChassis = isOwned(BULLDOZER_UPGRADE_IDS.heavyChassis);
  const highCapacityBlade =
    heavyChassis && isOwned(BULLDOZER_UPGRADE_IDS.highCapacityBlade);
  const heavyPowertrain =
    heavyChassis && isOwned(BULLDOZER_UPGRADE_IDS.heavyPowertrain);
  const fullyEquipped = highCapacityBlade && heavyPowertrain;
  return {
    ...starter,
    heavyChassis,
    highCapacityBlade,
    heavyPowertrain,
    maximumPushDepth: fullyEquipped
      ? 4.8
      : highCapacityBlade
        ? 3.2
        : heavyChassis
          ? 1.65
          : starter.maximumPushDepth,
    maximumFrontPileDepth: fullyEquipped
      ? 4.8
      : highCapacityBlade
        ? 3.35
        : heavyChassis
          ? 2.15
          : starter.maximumFrontPileDepth,
    maximumPileDepth: fullyEquipped
      ? 6
      : highCapacityBlade
        ? 4.2
        : heavyChassis
          ? 2.8
          : starter.maximumPileDepth,
    massCapacityMultiplier: fullyEquipped
      ? 2.55
      : heavyPowertrain
        ? 1.85
        : heavyChassis
          ? 1.2
          : starter.massCapacityMultiplier,
    tractionLimit: fullyEquipped
      ? 0.96
      : heavyPowertrain
        ? 0.9
        : heavyChassis
          ? 0.8
          : starter.tractionLimit,
    displayTier: fullyEquipped
      ? 'POLAR HEAVY'
      : heavyChassis
        ? 'HEAVY'
        : 'STARTER',
  };
};

export const nextBulldozerBladeMode = (
  mode: BulldozerBladeMode,
): BulldozerBladeMode => {
  const index = BULLDOZER_BLADE_MODES.indexOf(mode);
  return BULLDOZER_BLADE_MODES[
    (Math.max(0, index) + 1) % BULLDOZER_BLADE_MODES.length
  ]!;
};
