import { clamp, smoothstep } from '../utils/math';
import {
  CELESTIAL_RESONANCE_SECONDS,
  resolveTwinStarCycle,
} from './CelestialCycle';

const TAU = Math.PI * 2;

/**
 * The first full four-body alignment is deliberately placed at the naturally
 * occurring Aerion/Sirion conjunction in the 4:7 calendar. It repeats once
 * per four Aerion days: rare in ordinary play, but predictable and practical
 * to observe with an astronomical calendar.
 */
export const AERION_GRAND_ALIGNMENT_EPOCH_SECONDS =
  CELESTIAL_RESONANCE_SECONDS * 0.69561;
export const AERION_PLANET_ORBIT_SECONDS =
  CELESTIAL_RESONANCE_SECONDS / 3;
export const AERION_MOON_ORBIT_SECONDS =
  CELESTIAL_RESONANCE_SECONDS / 11;

export type CelestialOmenTier = 0 | 1 | 2 | 3;

export interface AerionOrbitalState {
  /** Apparent elliptical orbit in sky angular radians relative to Aerion. */
  planetOffsetX: number;
  planetOffsetY: number;
  /** The moon is expressed relative to Aerion, not relative to the planet. */
  moonOffsetX: number;
  moonOffsetY: number;
  planetPhase: number;
  moonPhase: number;
  planetInFront: number;
  moonInFront: number;
  /** Whether the small moon is closer to the observer than its planet. */
  moonInFrontOfPlanet: number;
  planetCentralTransit: number;
  nestedMoonTransit: number;
  grandAlignment: number;
  omenTier: CelestialOmenTier;
}

export interface CelestialOmenDefinition {
  tier: Exclude<CelestialOmenTier, 0>;
  id: 'VEILED_WORLD' | 'WATCHER_WITHIN' | 'DIVIDED_CROWN';
  name: string;
  undiscoveredHint: string;
  discoveredMeaning: string;
}

/** Datapoints for the later observatory / rune-lore quest chain. */
export const CELESTIAL_OMENS: readonly CelestialOmenDefinition[] = [
  {
    tier: 1,
    id: 'VEILED_WORLD',
    name: 'The Veiled World',
    undiscoveredHint: 'A dark world crosses the wounded fire.',
    discoveredMeaning: 'The first mark names the road beyond the winter.',
  },
  {
    tier: 2,
    id: 'WATCHER_WITHIN',
    name: 'The Watcher Within',
    undiscoveredHint: 'Watch the smaller shadow carried by the blue world.',
    discoveredMeaning: 'The second mark tells where the old gate was sealed.',
  },
  {
    tier: 3,
    id: 'DIVIDED_CROWN',
    name: 'The Divided Crown',
    undiscoveredHint: 'Four lights must become one before the crown is legible.',
    discoveredMeaning: 'The final mark completes the path to the winter heart.',
  },
] as const;

const fract = (value: number): number => value - Math.floor(value);

/**
 * Predictable nested ellipses around Aerion. The apparent minor axes are
 * intentionally shallow: each body visibly circles the star, yet sometimes
 * crosses its photosphere instead of forever missing it in projection.
 */
export const resolveAerionOrbitalState = (
  celestialTimeSeconds: number,
): AerionOrbitalState => {
  const safeTime = Math.max(0, celestialTimeSeconds);
  const planetPhase = fract(
    (safeTime - AERION_GRAND_ALIGNMENT_EPOCH_SECONDS) /
      AERION_PLANET_ORBIT_SECONDS + 0.25,
  );
  const moonPhase = fract(
    (safeTime - AERION_GRAND_ALIGNMENT_EPOCH_SECONDS) /
      AERION_MOON_ORBIT_SECONDS + 0.75,
  );
  const planetAngle = planetPhase * TAU;
  const moonAngle = moonPhase * TAU;

  // The companion's apparent orbit must clear Aerion often enough to read as
  // an orbit rather than a permanent transit. The shallow Y ellipse keeps
  // the rare, authored crossings intact.
  const planetOffsetX = Math.cos(planetAngle) * 0.052;
  const planetOffsetY = Math.sin(planetAngle) * 0.00115;
  const moonRelativeX = Math.cos(moonAngle) * 0.0072;
  const moonRelativeY = Math.sin(moonAngle) * 0.00115;
  const moonOffsetX = planetOffsetX + moonRelativeX;
  const moonOffsetY = planetOffsetY + moonRelativeY;
  const planetDistance = Math.hypot(planetOffsetX, planetOffsetY);
  const moonDistance = Math.hypot(moonOffsetX, moonOffsetY);

  // Depth is evaluated hierarchically. The old moon flag only described its
  // local orbit, so the moon stayed visible through Aerion or disappeared
  // behind its planet on the wrong half of the orbit.
  const planetDepth = Math.sin(planetAngle);
  const moonRelativeDepth = -Math.sin(moonAngle) * 0.22;
  const moonAbsoluteDepth = planetDepth + moonRelativeDepth;
  const planetInFront = smoothstep(-0.08, 0.08, planetDepth);
  const moonInFront = smoothstep(-0.08, 0.08, moonAbsoluteDepth);
  const moonInFrontOfPlanet = smoothstep(-0.035, 0.035, moonRelativeDepth);
  const planetCentralTransit = (
    1 - smoothstep(0.0014, 0.0052, planetDistance)
  ) * planetInFront;
  const moonCentralTransit = (
    1 - smoothstep(0.0012, 0.0042, moonDistance)
  ) * moonInFront;
  const nestedMoonTransit = Math.min(
    planetCentralTransit,
    moonCentralTransit,
  );

  const twinCycle = resolveTwinStarCycle(safeTime);
  const starConjunction = (
    1 - smoothstep(0.008, 0.085, twinCycle.angularSeparation)
  ) * smoothstep(
    0.08,
    0.42,
    Math.min(
      twinCycle.aerionAboveHorizon,
      twinCycle.sirionAboveHorizon,
    ),
  );
  const grandAlignment = nestedMoonTransit * starConjunction;
  const omenTier: CelestialOmenTier = grandAlignment > 0.08
    ? 3
    : nestedMoonTransit > 0.48
      ? 2
      : planetCentralTransit > 0.48
        ? 1
        : 0;

  return {
    planetOffsetX,
    planetOffsetY,
    moonOffsetX,
    moonOffsetY,
    planetPhase,
    moonPhase,
    planetInFront: clamp(planetInFront, 0, 1),
    moonInFront: clamp(moonInFront, 0, 1),
    moonInFrontOfPlanet: clamp(moonInFrontOfPlanet, 0, 1),
    planetCentralTransit: clamp(planetCentralTransit, 0, 1),
    nestedMoonTransit: clamp(nestedMoonTransit, 0, 1),
    grandAlignment: clamp(grandAlignment, 0, 1),
    omenTier,
  };
};

/** Exact next authored observation window for journals and observatories. */
export const predictNextCelestialOmen = (
  afterCelestialTimeSeconds: number,
  tier: Exclude<CelestialOmenTier, 0>,
): number => {
  const period = tier === 1
    ? AERION_PLANET_ORBIT_SECONDS
    : CELESTIAL_RESONANCE_SECONDS;
  const elapsed = afterCelestialTimeSeconds -
    AERION_GRAND_ALIGNMENT_EPOCH_SECONDS;
  const cycle = Math.max(0, Math.ceil(elapsed / period));
  return AERION_GRAND_ALIGNMENT_EPOCH_SECONDS + cycle * period;
};
