import type { SettlementContentRegistry } from './SettlementContentRegistry';
import type {
  SettlementCultivationCellRuntimeState,
  SettlementCultivationCellView,
  SettlementCultivationGroundKind,
  SettlementCultivationPatchDefinition,
  SettlementCultivationPatchView,
  SettlementCultivationSaveData,
  SettlementGoodAmount,
  SettlementMutationResult,
  SettlementPlantDefinition,
  SettlementPlantGrowthStage,
} from './SettlementTypes';
import type { SettlementWarehouse } from './SettlementWarehouse';

interface MutableCultivationCellState {
  patchId: string;
  cellIndex: number;
  ground: SettlementCultivationGroundKind;
  leafDensity: number;
  plantId?: string;
  plantedAt?: number;
  matureAt?: number;
  nextHarvestAt?: number;
  lastCutHeightMetres?: number;
  harvestReady: boolean;
  harvestCount: number;
  revision: number;
}

const clamp01 = (value: number): number => Math.max(0, Math.min(1, value));

const cellKey = (patchId: string, cellIndex: number): string =>
  `${patchId}:${cellIndex}`;

const cloneCell = (
  state: Readonly<MutableCultivationCellState>,
): SettlementCultivationCellRuntimeState => ({ ...state });

const mergeAmounts = (
  amounts: readonly Readonly<SettlementGoodAmount>[],
): readonly SettlementGoodAmount[] => {
  const merged = new Map<string, number>();
  for (const amount of amounts) {
    merged.set(amount.goodId, (merged.get(amount.goodId) ?? 0) + amount.quantity);
  }
  return [...merged]
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([goodId, quantity]) => ({ goodId, quantity }));
};

const growthStage = (growth: number): SettlementPlantGrowthStage =>
  growth >= 1 ? 'MATURE'
    : growth >= 0.58 ? 'GROWING'
      : growth >= 0.25 ? 'SPROUT'
        : 'SEED';

/**
 * Sparse, timestamp-driven 3x3 cultivation patches. This domain layer owns
 * soil, leaves and plant yield; tools and renderers only submit intents or
 * present the resulting cells.
 */
export class SettlementCultivationSystem {
  private readonly cells = new Map<string, MutableCultivationCellState>();

  public constructor(
    private readonly registry: SettlementContentRegistry,
    private readonly warehouse: SettlementWarehouse,
    saved?: Readonly<SettlementCultivationSaveData>,
  ) {
    for (const patch of registry.definitions.cultivationPatches ?? []) {
      const count = patch.subdivision * patch.subdivision;
      for (let cellIndex = 0; cellIndex < count; cellIndex += 1) {
        this.cells.set(cellKey(patch.id, cellIndex), {
          patchId: patch.id,
          cellIndex,
          ground: patch.initialGround,
          leafDensity: clamp01(
            (patch.initialLeafDensity ?? 0) *
            (0.82 + ((cellIndex * 37) % 23) / 64),
          ),
          harvestReady: false,
          harvestCount: 0,
          revision: 0,
        });
      }
    }
    if (saved?.version === 1 && Array.isArray(saved.cells)) {
      for (const candidate of saved.cells) this.importCell(candidate);
    }
  }

  public tillCell(
    patchId: string,
    cellIndex: number,
  ): SettlementMutationResult {
    const state = this.cell(patchId, cellIndex);
    if (!state) return this.rejected('CULTIVATION_CELL_INVALID');
    if (state.plantId) return this.rejected('CULTIVATION_CELL_OCCUPIED');
    if (state.ground === 'TILLED' && state.leafDensity <= 0.05) {
      return this.rejected('CULTIVATION_CELL_ALREADY_TILLED');
    }
    state.ground = 'TILLED';
    state.leafDensity = Math.min(state.leafDensity, 0.05);
    state.revision += 1;
    return this.accepted('CULTIVATION_CELL_TILLED', 1);
  }

  public tillPatch(patchId: string): SettlementMutationResult {
    let changed = 0;
    for (const state of this.patchCells(patchId)) {
      if (state.plantId || (state.ground === 'TILLED' && state.leafDensity <= 0.05)) continue;
      state.ground = 'TILLED';
      state.leafDensity = Math.min(state.leafDensity, 0.05);
      state.revision += 1;
      changed += 1;
    }
    return changed > 0
      ? this.accepted('CULTIVATION_PATCH_TILLED', changed)
      : this.rejected('CULTIVATION_PATCH_NOT_TILLABLE');
  }

  public restoreLawnCell(
    patchId: string,
    cellIndex: number,
  ): SettlementMutationResult {
    const state = this.cell(patchId, cellIndex);
    if (!state) return this.rejected('CULTIVATION_CELL_INVALID');
    if (state.plantId) return this.rejected('CULTIVATION_CELL_OCCUPIED');
    if (state.ground === 'LAWN' && state.leafDensity <= 0.05) {
      return this.rejected('CULTIVATION_CELL_ALREADY_LAWN');
    }
    state.ground = 'LAWN';
    state.leafDensity = Math.min(state.leafDensity, 0.05);
    state.revision += 1;
    return this.accepted('CULTIVATION_CELL_RESTORED_TO_LAWN', 1);
  }

  public restoreLawnPatch(patchId: string): SettlementMutationResult {
    let changed = 0;
    for (const state of this.patchCells(patchId)) {
      if (state.plantId || (state.ground === 'LAWN' && state.leafDensity <= 0.05)) continue;
      state.ground = 'LAWN';
      state.leafDensity = Math.min(state.leafDensity, 0.05);
      state.revision += 1;
      changed += 1;
    }
    return changed > 0
      ? this.accepted('CULTIVATION_PATCH_RESTORED_TO_LAWN', changed)
      : this.rejected('CULTIVATION_PATCH_NOT_RESTORABLE');
  }

  public clearLeavesPatch(patchId: string): SettlementMutationResult {
    let changed = 0;
    for (const state of this.patchCells(patchId)) {
      if (state.leafDensity <= 0.01) continue;
      state.leafDensity = 0;
      state.revision += 1;
      changed += 1;
    }
    return changed > 0
      ? this.accepted('CULTIVATION_LEAVES_GATHERED', changed)
      : this.rejected('CULTIVATION_NO_LEAVES');
  }

  /**
   * Continuous Leaves V2 tool operation. Density is authoritative; airborne
   * leaves remain presentation-only. Removed density is offered to the most
   * downwind cell in the same patch and any saturated remainder is restored.
   */
  public blowLeaves(
    x: number,
    z: number,
    heading: number,
    deltaSeconds: number,
  ): Readonly<{
    changed: boolean;
    movedDensity: number;
    affectedCells: number;
    targetX: number;
    targetZ: number;
  }> {
    const forwardX = Math.sin(heading);
    const forwardZ = Math.cos(heading);
    const cosineLimit = Math.cos(Math.PI * 0.2);
    const elapsed = Math.max(0, Math.min(0.1, deltaSeconds));
    let movedDensity = 0;
    let affectedCells = 0;
    let targetX = x + forwardX * 2.6;
    let targetZ = z + forwardZ * 2.6;
    for (const patch of this.registry.definitions.cultivationPatches ?? []) {
      const cells = this.patchCells(patch.id);
      for (const source of cells) {
        if (source.leafDensity <= 0.001) continue;
        const sourcePoint = this.cellPosition(patch, source.cellIndex);
        const dx = sourcePoint.x - x;
        const dz = sourcePoint.z - z;
        const distance = Math.hypot(dx, dz);
        if (distance < 0.15 || distance > 4.6) continue;
        const facing = (dx * forwardX + dz * forwardZ) / Math.max(0.001, distance);
        if (facing < cosineLimit) continue;
        const strength = elapsed * (0.34 + (1 - distance / 4.6) * 0.78) *
          (0.35 + ((facing - cosineLimit) / (1 - cosineLimit)) * 0.65);
        const offered = Math.min(source.leafDensity, strength);
        if (offered <= 1e-6) continue;
        const desiredX = sourcePoint.x + forwardX * (patch.sizeMetres / patch.subdivision) * 1.35;
        const desiredZ = sourcePoint.z + forwardZ * (patch.sizeMetres / patch.subdivision) * 1.35;
        const destination = cells
          .filter((candidate) => candidate !== source)
          .map((candidate) => ({
            candidate,
            point: this.cellPosition(patch, candidate.cellIndex),
          }))
          .sort((left, right) =>
            Math.hypot(left.point.x - desiredX, left.point.z - desiredZ) -
            Math.hypot(right.point.x - desiredX, right.point.z - desiredZ))[0];
        if (!destination) continue;
        const accepted = Math.min(offered, 1 - destination.candidate.leafDensity);
        if (accepted <= 1e-6) continue;
        source.leafDensity -= accepted;
        source.revision += 1;
        destination.candidate.leafDensity += accepted;
        destination.candidate.revision += 1;
        movedDensity += accepted;
        affectedCells += 2;
        targetX = destination.point.x;
        targetZ = destination.point.z;
      }
    }
    return Object.freeze({
      changed: movedDensity > 0,
      movedDensity,
      affectedCells,
      targetX,
      targetZ,
    });
  }

  public plantCell(
    patchId: string,
    cellIndex: number,
    plantId: string,
    simulationTime: number,
  ): SettlementMutationResult {
    const patch = this.registry.getCultivationPatch(patchId);
    const plant = this.registry.getPlant(plantId);
    const state = this.cell(patchId, cellIndex);
    const invalid = this.plantingProblem(patch, plant, state);
    if (invalid) return this.rejected(invalid);
    this.applyPlant(state!, plant!, simulationTime);
    return this.accepted('CULTIVATION_CELL_PLANTED', 1);
  }

  public plantPatch(
    patchId: string,
    plantId: string,
    simulationTime: number,
  ): SettlementMutationResult {
    const patch = this.registry.getCultivationPatch(patchId);
    const plant = this.registry.getPlant(plantId);
    if (!patch || !plant) return this.rejected('CULTIVATION_PLANT_OR_PATCH_INVALID');
    if (!this.isPlantUnlocked(plant)) return this.rejected('CULTIVATION_PLANT_LOCKED');
    if (!this.plantMatchesPatch(plant, patch)) {
      return this.rejected('CULTIVATION_PLANT_WRONG_REGION');
    }
    let changed = 0;
    for (const state of this.patchCells(patchId)) {
      if (state.plantId || !plant.requiredGround.includes(state.ground)) continue;
      this.applyPlant(state, plant, simulationTime);
      changed += 1;
    }
    return changed > 0
      ? this.accepted('CULTIVATION_PATCH_PLANTED', changed)
      : this.rejected('CULTIVATION_PATCH_HAS_NO_PLANTABLE_CELLS');
  }

  public harvestCell(
    patchId: string,
    cellIndex: number,
    simulationTime: number,
  ): SettlementMutationResult {
    const state = this.cell(patchId, cellIndex);
    const plant = state?.plantId ? this.registry.getPlant(state.plantId) : undefined;
    if (!state || !plant) return this.rejected('CULTIVATION_CELL_EMPTY');
    if (!this.isHarvestReady(state, simulationTime)) {
      return this.rejected('CULTIVATION_PLANT_NOT_READY');
    }
    if (!this.warehouse.canApply(plant.harvestOutputs, 1) ||
      !this.warehouse.apply(plant.harvestOutputs, 1)) {
      return this.rejected('WAREHOUSE_FULL');
    }
    this.completeHarvest(state, plant, simulationTime);
    const quantity = plant.harvestOutputs.reduce((sum, output) => sum + output.quantity, 0);
    return this.accepted('CULTIVATION_SICKLE_HARVESTED', quantity);
  }

  /** God-mode sickle: one joyful sweep collects every ready cell in a patch. */
  public sicklePatch(
    patchId: string,
    simulationTime: number,
  ): SettlementMutationResult {
    const ready = this.patchCells(patchId).flatMap((state) => {
      const plant = state.plantId ? this.registry.getPlant(state.plantId) : undefined;
      return plant && this.isHarvestReady(state, simulationTime)
        ? [{ state, plant }]
        : [];
    });
    if (ready.length === 0) return this.rejected('CULTIVATION_NOTHING_READY');
    const outputs = mergeAmounts(ready.flatMap(({ plant }) => plant.harvestOutputs));
    if (!this.warehouse.canApply(outputs, 1) || !this.warehouse.apply(outputs, 1)) {
      return this.rejected('WAREHOUSE_FULL');
    }
    for (const { state, plant } of ready) {
      this.completeHarvest(state, plant, simulationTime);
    }
    return this.accepted(
      'CULTIVATION_SICKLE_SWEEP_COMPLETE',
      outputs.reduce((sum, output) => sum + output.quantity, 0),
    );
  }

  public update(simulationTime: number): boolean {
    let changed = false;
    for (const state of this.cells.values()) {
      if (!state.plantId || state.harvestReady || state.nextHarvestAt === undefined) continue;
      if (simulationTime < state.nextHarvestAt) continue;
      state.harvestReady = true;
      state.revision += 1;
      changed = true;
    }
    return changed;
  }

  public getPatchView(
    patchId: string,
    simulationTime: number,
  ): SettlementCultivationPatchView | undefined {
    const patch = this.registry.getCultivationPatch(patchId);
    const region = patch ? this.registry.getSeasonRegion(patch.regionId) : undefined;
    if (!patch || !region) return undefined;
    const cells = this.patchCells(patchId).map((state) =>
      this.cellView(patch, state, simulationTime));
    return {
      patchId: patch.id,
      displayName: patch.displayName,
      regionId: patch.regionId,
      season: region.season,
      x: patch.x,
      z: patch.z,
      sizeMetres: patch.sizeMetres,
      subdivision: patch.subdivision,
      interactionRadius: patch.interactionRadius,
      revision: cells.reduce((sum, cell) => sum + cell.revision, 0),
      cells,
    };
  }

  public getPatchViews(simulationTime: number): readonly SettlementCultivationPatchView[] {
    return (this.registry.definitions.cultivationPatches ?? []).flatMap((patch) => {
      const view = this.getPatchView(patch.id, simulationTime);
      return view ? [view] : [];
    });
  }

  public isPlantUnlocked(plant: Readonly<SettlementPlantDefinition>): boolean {
    return !plant.unlockGoodId || this.warehouse.getQuantity(plant.unlockGoodId) > 0;
  }

  public exportState(): SettlementCultivationSaveData {
    return {
      version: 1,
      cells: [...this.cells.values()]
        .sort((left, right) => left.patchId.localeCompare(right.patchId) ||
          left.cellIndex - right.cellIndex)
        .map(cloneCell),
    };
  }

  private cellView(
    patch: Readonly<SettlementCultivationPatchDefinition>,
    state: Readonly<MutableCultivationCellState>,
    simulationTime: number,
  ): SettlementCultivationCellView {
    const plant = state.plantId ? this.registry.getPlant(state.plantId) : undefined;
    const cellSize = patch.sizeMetres / patch.subdivision;
    const column = state.cellIndex % patch.subdivision;
    const row = Math.floor(state.cellIndex / patch.subdivision);
    const offset = (patch.subdivision - 1) * 0.5;
    const x = patch.x + (column - offset) * cellSize;
    const z = patch.z + (row - offset) * cellSize;
    const growth = !plant || state.plantedAt === undefined || state.matureAt === undefined
      ? 0
      : clamp01(
          (simulationTime - state.plantedAt) /
          Math.max(0.001, state.matureAt - state.plantedAt),
        );
    const ready = !!plant && this.isHarvestReady(state, simulationTime);
    const mature = growth >= 1;
    const status = !plant
      ? 'EMPTY' as const
      : ready
        ? 'READY' as const
        : mature
          ? 'REGROWING' as const
          : 'GROWING' as const;
    const produceGrowth = !plant || !mature
      ? growth
      : ready || state.nextHarvestAt === undefined
        ? 1
        : clamp01(1 - (state.nextHarvestAt - simulationTime) /
          Math.max(0.001, plant.regrowthSeconds ?? plant.growthSeconds));
    const plantHeightMetres = !plant
      ? 0
      : plant.kind === 'GRASS'
        ? mature
          ? (state.lastCutHeightMetres ?? 0.06) +
            produceGrowth * (0.72 - (state.lastCutHeightMetres ?? 0.06))
          : growth * 0.72
        : growth;
    return {
      ...cloneCell(state),
      x,
      z,
      status,
      growth,
      growthStage: growthStage(growth),
      produceGrowth,
      plantHeightMetres,
      ...(plant ? { plantDisplayName: plant.displayName } : {}),
      ...(plant ? { plantKind: plant.kind } : {}),
      ...(plant ? { plantVisualKind: plant.visualKind } : {}),
      harvestOutputs: plant?.harvestOutputs.map((output) => ({ ...output })) ?? [],
    };
  }

  private plantingProblem(
    patch: Readonly<SettlementCultivationPatchDefinition> | undefined,
    plant: Readonly<SettlementPlantDefinition> | undefined,
    state: MutableCultivationCellState | undefined,
  ): string | undefined {
    if (!patch || !plant || !state) return 'CULTIVATION_PLANT_OR_CELL_INVALID';
    if (state.plantId) return 'CULTIVATION_CELL_OCCUPIED';
    if (!this.isPlantUnlocked(plant)) return 'CULTIVATION_PLANT_LOCKED';
    if (!this.plantMatchesPatch(plant, patch)) return 'CULTIVATION_PLANT_WRONG_REGION';
    if (!plant.requiredGround.includes(state.ground)) return 'CULTIVATION_GROUND_NOT_READY';
    return undefined;
  }

  private plantMatchesPatch(
    plant: Readonly<SettlementPlantDefinition>,
    patch: Readonly<SettlementCultivationPatchDefinition>,
  ): boolean {
    const region = this.registry.getSeasonRegion(patch.regionId);
    return !!region && (!plant.season || plant.season === region.season) &&
      (!patch.allowedPlantKinds || patch.allowedPlantKinds.includes(plant.kind));
  }

  private applyPlant(
    state: MutableCultivationCellState,
    plant: Readonly<SettlementPlantDefinition>,
    simulationTime: number,
  ): void {
    const now = Math.max(0, simulationTime);
    state.plantId = plant.id;
    state.plantedAt = now;
    state.matureAt = now + plant.growthSeconds;
    state.nextHarvestAt = state.matureAt;
    delete state.lastCutHeightMetres;
    state.harvestReady = false;
    state.leafDensity = Math.min(state.leafDensity, 0.08);
    state.revision += 1;
  }

  private completeHarvest(
    state: MutableCultivationCellState,
    plant: Readonly<SettlementPlantDefinition>,
    simulationTime: number,
  ): void {
    state.harvestCount += 1;
    state.harvestReady = false;
    state.revision += 1;
    if (plant.lifecycle === 'ANNUAL') {
      delete state.plantId;
      delete state.plantedAt;
      delete state.matureAt;
      delete state.nextHarvestAt;
      delete state.lastCutHeightMetres;
      state.ground = 'TILLED';
      return;
    }
    if (plant.kind === 'GRASS') state.lastCutHeightMetres = 0.06;
    state.nextHarvestAt = Math.max(0, simulationTime) +
      (plant.regrowthSeconds ?? plant.growthSeconds);
  }

  private isHarvestReady(
    state: Readonly<MutableCultivationCellState>,
    simulationTime: number,
  ): boolean {
    return state.harvestReady ||
      (state.nextHarvestAt !== undefined && simulationTime >= state.nextHarvestAt);
  }

  private cell(
    patchId: string,
    cellIndex: number,
  ): MutableCultivationCellState | undefined {
    return Number.isSafeInteger(cellIndex)
      ? this.cells.get(cellKey(patchId, cellIndex))
      : undefined;
  }

  private patchCells(patchId: string): MutableCultivationCellState[] {
    const patch = this.registry.getCultivationPatch(patchId);
    if (!patch) return [];
    const result: MutableCultivationCellState[] = [];
    for (let index = 0; index < patch.subdivision ** 2; index += 1) {
      const state = this.cell(patchId, index);
      if (state) result.push(state);
    }
    return result;
  }

  private importCell(candidate: Readonly<SettlementCultivationCellRuntimeState>): void {
    const state = this.cell(candidate?.patchId, candidate?.cellIndex);
    if (!state) return;
    const grounds: readonly SettlementCultivationGroundKind[] =
      ['WILD', 'LAWN', 'TILLED', 'MULCHED'];
    state.ground = grounds.includes(candidate.ground)
      ? candidate.ground
      : state.ground;
    state.leafDensity = Number.isFinite(candidate.leafDensity)
      ? clamp01(candidate.leafDensity)
      : state.leafDensity;
    state.harvestCount = Number.isSafeInteger(candidate.harvestCount) &&
      candidate.harvestCount >= 0 ? candidate.harvestCount : 0;
    state.revision = Number.isSafeInteger(candidate.revision) &&
      candidate.revision >= 0 ? candidate.revision : 0;
    const plant = candidate.plantId ? this.registry.getPlant(candidate.plantId) : undefined;
    if (!plant || !Number.isFinite(candidate.plantedAt) ||
      !Number.isFinite(candidate.matureAt) ||
      !Number.isFinite(candidate.nextHarvestAt) ||
      candidate.matureAt! < candidate.plantedAt! ||
      candidate.nextHarvestAt! < candidate.matureAt!) return;
    state.plantId = plant.id;
    state.plantedAt = Math.max(0, candidate.plantedAt!);
    state.matureAt = Math.max(state.plantedAt, candidate.matureAt!);
    state.nextHarvestAt = Math.max(state.matureAt, candidate.nextHarvestAt!);
    state.lastCutHeightMetres = Number.isFinite(candidate.lastCutHeightMetres)
      ? Math.max(0, Math.min(0.72, candidate.lastCutHeightMetres!))
      : undefined;
    state.harvestReady = candidate.harvestReady === true;
  }

  private cellPosition(
    patch: Readonly<SettlementCultivationPatchDefinition>,
    cellIndex: number,
  ): Readonly<{ x: number; z: number }> {
    const cellSize = patch.sizeMetres / patch.subdivision;
    const column = cellIndex % patch.subdivision;
    const row = Math.floor(cellIndex / patch.subdivision);
    const offset = (patch.subdivision - 1) * 0.5;
    return {
      x: patch.x + (column - offset) * cellSize,
      z: patch.z + (row - offset) * cellSize,
    };
  }

  private accepted(status: string, quantity: number): SettlementMutationResult {
    return { accepted: true, stateChanged: true, status, quantity };
  }

  private rejected(status: string): SettlementMutationResult {
    return { accepted: false, stateChanged: false, status };
  }
}
