const formatAchievementValue = (
  presentation: Readonly<AchievementStatPresentation>,
  value: number,
): string => {
  if (presentation.format === 'DURATION') {
    const seconds = Math.max(0, Math.floor(value));
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return hours > 0
      ? `${hours}h ${minutes}m`
      : `${minutes}m ${seconds % 60}s`;
  }
  const numeric =
    presentation.format === 'INTEGER'
      ? String(Math.floor(Math.max(0, value)))
      : Math.max(0, value).toFixed(1);
  return presentation.suffix
    ? `${numeric} ${presentation.suffix}`
    : numeric;
};

const formatRadioIdentifier = (id: string | undefined): string =>
  id
    ? id
        .split('-')
        .filter(Boolean)
        .map(
          (part) => `${part.charAt(0).toUpperCase()}${part.slice(1)}`,
        )
        .join(' ')
    : 'NO STATION';

const debugCommandForCode = (
  code: string,
): DrivingDebugCommand | undefined => {
  if (SPHERICAL_WORLD_KEY_CODES.has(code)) {
    return 'toggle-spherical-world';
  }
  if (DEBUG_KEY_CODES.has(code)) return 'toggle-metrics';
  if (ICE_TIME_KEY_CODES.has(code)) return 'cycle-ice-time';
  if (OCEAN_MODE_KEY_CODES.has(code)) return 'cycle-ocean-mode';
  if (OCEAN_FREEZE_KEY_CODES.has(code)) return 'toggle-ocean-freeze';
  if (OCEAN_TIME_KEY_CODES.has(code)) return 'cycle-ocean-time';
  if (ICE_DRIFT_FREEZE_KEY_CODES.has(code)) return 'toggle-ice-drift';
  if (REFREEZE_FREEZE_KEY_CODES.has(code)) return 'toggle-refreeze';
  if (ICE_HISTORY_RESET_KEY_CODES.has(code))
    return 'reset-ice-history';
  if (FLOE_VIEW_KEY_CODES.has(code)) return 'cycle-ice-view';
  if (VISUAL_PROFILE_KEY_CODES.has(code))
    return 'cycle-ocean-profile';
  if (ICE_VISUAL_PROFILE_KEY_CODES.has(code))
    return 'cycle-ice-profile';
  if (FLOE_SEPARATION_KEY_CODES.has(code)) return 'separate-floes';
  if (FLOE_COMPRESSION_KEY_CODES.has(code)) return 'compress-floes';
  if (WEATHER_MODE_KEY_CODES.has(code)) return 'cycle-weather-mode';
  if (WEATHER_TIME_KEY_CODES.has(code)) return 'cycle-weather-time';
  if (WEATHER_FREEZE_KEY_CODES.has(code))
    return 'toggle-weather-freeze';
  if (DAY_MODE_KEY_CODES.has(code)) return 'cycle-day-mode';
  if (DAY_TIME_KEY_CODES.has(code)) return 'cycle-day-time';
  if (ENVIRONMENT_MASTER_TIME_KEY_CODES.has(code)) {
    return 'cycle-environment-master-time';
  }
  if (AMBIENT_TOGGLE_KEY_CODES.has(code)) return 'toggle-ambient';
  if (AMBIENT_BUDGET_KEY_CODES.has(code)) {
    return 'cycle-ambient-budget';
  }
  if (AMBIENT_FORCE_KEY_CODES.has(code)) return 'force-ambient';
  return undefined;
};

