const portAccessPoint = (portIndex: number): WorldPoint => {
  const port = PORTS[portIndex] ?? PORTS[0]!;
  const length = Math.max(
    0.001,
    Math.hypot(port.position.x, port.position.z),
  );
  return {
    x:
      port.position.x -
      (port.position.x / length) * PORT_ACCESS_DISTANCE,
    z:
      port.position.z -
      (port.position.z / length) * PORT_ACCESS_DISTANCE,
  };
};

