import { clamp, damp, hash2D } from '../utils/math';

export type WeatherKind =
  | 'clear'
  | 'overcast'
  | 'light-snow'
  | 'fog'
  | 'strong-wind'
  | 'snowstorm';
export type WeatherMode = 'auto' | WeatherKind;
export type WeatherPhase =
  | 'calm'
  | 'transition'
  | 'active'
  | 'recovery'
  | 'forced';
export type WeatherTimeScale = 1 | 4 | 12;
export type WeatherStoryId =
  | 'CLEARING_WINDOW'
  | 'DIAMOND_AIR'
  | 'LOW_CEILING'
  | 'SOFT_FRONT'
  | 'FEATHER_SNOW'
  | 'NEEDLE_SNOW'
  | 'SILVER_VEIL'
  | 'GROUND_MIST'
  | 'WIND_SHIFT'
  | 'TIMBER_GALE'
  | 'WHITEOUT_WALL'
  | 'DRIFTING_CURTAIN'
  | 'POLAR_SQUALL';

export interface WeatherProfile {
  cloudCover: number;
  fogDensity: number;
  snowIntensity: number;
  windMultiplier: number;
  waveMultiplier: number;
  refreezeMultiplier: number;
  iceContrast: number;
}

export interface WeatherState extends WeatherProfile {
  mode: WeatherMode;
  current: WeatherKind;
  target: WeatherKind;
  phase: WeatherPhase;
  phaseProgress: number;
  frozen: boolean;
  timeScale: WeatherTimeScale;
  weatherTime: number;
  updates: number;
  /** Slowly evolving large-scale wind direction, in world X/Z radians. */
  windDirectionRadians: number;
  windTargetDirectionRadians: number;
  /** Deterministic 0..1 gust envelope shared by shader and snowfall. */
  windGust: number;
  /** Forecast-scale strength including the current gust envelope. */
  windStrength: number;
  /** A readable beginning, crest and release layered over the weather kind. */
  weatherStoryId: WeatherStoryId;
  weatherStoryName: string;
}

export interface WeatherForecast {
  snowExpected: boolean;
  kind: WeatherKind;
  minutesUntil: number;
  expectedIntensity: number;
  windDirectionRadians: number;
  expectedWindStrength: number;
}

export interface WeatherSystemSaveData {
  version: 1;
  /** Wind-field members are optional for version-1 backward compatibility. */
  state: Omit<
    WeatherState,
    | 'windDirectionRadians'
    | 'windTargetDirectionRadians'
    | 'windGust'
    | 'windStrength'
    | 'weatherStoryId'
    | 'weatherStoryName'
  > & Partial<Pick<
    WeatherState,
    | 'windDirectionRadians'
    | 'windTargetDirectionRadians'
    | 'windGust'
    | 'windStrength'
    | 'weatherStoryId'
    | 'weatherStoryName'
  >>;
  accumulator: number;
  phaseElapsed: number;
  eventIndex: number;
  activeWeather: WeatherKind;
}

const WEATHER_STEP = 0.25;
const TRANSITION_SECONDS = 82;
const RECOVERY_SECONDS = 76;
const WEATHER_MODES: readonly WeatherMode[] = [
  'auto',
  'overcast',
  'light-snow',
  'fog',
  'strong-wind',
  'snowstorm',
  'clear',
];
const WEATHER_TIME_SCALES: readonly WeatherTimeScale[] = [1, 4, 12];

export const weatherStoryFor = (
  kind: WeatherKind,
  eventIndex: number,
): Readonly<{ id: WeatherStoryId; name: string }> => {
  if (kind === 'snowstorm') return ([
    { id: 'WHITEOUT_WALL', name: 'Whiteout wall' },
    { id: 'DRIFTING_CURTAIN', name: 'Drifting curtain' },
    { id: 'POLAR_SQUALL', name: 'Polar squall' },
  ] as const)[Math.abs(eventIndex) % 3]!;
  if (kind === 'fog') return Math.abs(eventIndex) % 2
    ? { id: 'GROUND_MIST', name: 'Ground mist' }
    : { id: 'SILVER_VEIL', name: 'Silver veil' };
  if (kind === 'strong-wind') return Math.abs(eventIndex) % 2
    ? { id: 'TIMBER_GALE', name: 'Timber gale' }
    : { id: 'WIND_SHIFT', name: 'Turning wind' };
  if (kind === 'light-snow') return ([
    { id: 'SOFT_FRONT', name: 'Soft snow front' },
    { id: 'FEATHER_SNOW', name: 'Feather snow' },
    { id: 'NEEDLE_SNOW', name: 'Needle snow' },
  ] as const)[Math.abs(eventIndex) % 3]!;
  if (kind === 'overcast') return { id: 'LOW_CEILING', name: 'Low winter ceiling' };
  return Math.abs(eventIndex) % 2
    ? { id: 'DIAMOND_AIR', name: 'Diamond air' }
    : { id: 'CLEARING_WINDOW', name: 'A clearing window' };
};

interface WeatherStoryShape {
  readonly snow: number;
  readonly fog: number;
  readonly wind: number;
  readonly cloud: number;
}

/**
 * A tiny deterministic envelope gives a forecast event its own cadence. It
 * does not add particles, entities or another simulation: every presentation
 * consumer still reads the same one authoritative weather state.
 */
export const weatherStoryShape = (
  id: WeatherStoryId,
  phaseProgress: number,
  weatherTime: number,
  eventIndex: number,
): Readonly<WeatherStoryShape> => {
  const progress = clamp(phaseProgress, 0, 1);
  const crest = Math.sin(progress * Math.PI);
  // Snow mass evolves on the same multi-minute scale as the cloud bank. Fast
  // gusts may change slant and visibility, but must never pulse precipitation
  // itself on and off every few seconds.
  const slow = Math.sin(weatherTime * 0.0085 + eventIndex * 1.71);
  const gust = Math.max(0, Math.sin(weatherTime * 0.16 + eventIndex * 2.37));
  switch (id) {
    case 'DIAMOND_AIR':
      return { snow: 1, fog: 0.72, wind: 0.84, cloud: 0.72 };
    case 'LOW_CEILING':
      return { snow: 1, fog: 1.14 + crest * 0.08, wind: 0.88, cloud: 1.12 };
    case 'FEATHER_SNOW':
      return { snow: 0.78 + crest * 0.18 + slow * 0.05, fog: 0.94, wind: 0.82, cloud: 1.03 };
    case 'NEEDLE_SNOW':
      return { snow: 0.82 + crest * 0.14 + gust * 0.06, fog: 1.04, wind: 1.18 + gust * 0.12, cloud: 1.06 };
    case 'GROUND_MIST':
      return { snow: 0.72, fog: 1.3 + crest * 0.12, wind: 0.66, cloud: 1.03 };
    case 'SILVER_VEIL':
      return { snow: 0.8, fog: 1.14 + crest * 0.08, wind: 0.76, cloud: 1.04 };
    case 'TIMBER_GALE':
      return { snow: 1, fog: 0.92, wind: 1.2 + gust * 0.18, cloud: 1.01 };
    case 'WIND_SHIFT':
      return { snow: 1, fog: 0.96, wind: 0.92 + crest * 0.18 + gust * 0.12, cloud: 1 };
    case 'DRIFTING_CURTAIN':
      return { snow: 0.84 + crest * 0.16 + Math.abs(slow) * 0.08, fog: 1.06 + crest * 0.12, wind: 1.03 + gust * 0.12, cloud: 1.04 };
    case 'POLAR_SQUALL':
      return { snow: 0.9 + crest * 0.14 + gust * 0.06, fog: 1.1 + crest * 0.12, wind: 1.12 + gust * 0.16, cloud: 1.06 };
    case 'WHITEOUT_WALL':
      return { snow: 0.92 + crest * 0.12 + gust * 0.035, fog: 1.08 + crest * 0.18, wind: 1.04 + crest * 0.08, cloud: 1.08 };
    case 'SOFT_FRONT':
      return { snow: 0.86 + crest * 0.14 + slow * 0.045, fog: 0.98, wind: 0.92, cloud: 1.04 };
    case 'CLEARING_WINDOW':
    default:
      return { snow: 1, fog: 0.9, wind: 0.92, cloud: 0.9 };
  }
};

/** Forecast events are air masses, not short particle-emitter cues. */
export const resolveWeatherActiveDuration = (
  kind: WeatherKind,
  eventIndex: number,
  winterBias: boolean,
): number => {
  const variation = Math.abs(Math.floor(eventIndex)) % 4;
  if (kind === 'light-snow') {
    return (480 + variation * 55) * (winterBias ? 1.12 : 1);
  }
  if (kind === 'snowstorm') {
    return (540 + variation * 65) * (winterBias ? 1.1 : 1);
  }
  return (118 + variation * 24) * (winterBias ? 1.08 : 1);
};
const WEATHER_TRANSITIONS: Readonly<
  Record<WeatherKind, readonly WeatherKind[]>
> = {
  clear: ['clear', 'overcast', 'overcast', 'strong-wind'],
  overcast: ['clear', 'light-snow', 'fog', 'strong-wind'],
  'light-snow': ['clear', 'overcast', 'snowstorm'],
  fog: ['clear', 'clear', 'overcast'],
  'strong-wind': ['clear', 'overcast', 'snowstorm'],
  snowstorm: ['light-snow', 'overcast', 'clear'],
};

/**
 * The Long Winter keeps the same readable weather states, but revisits gentle
 * snowfall a little more often than Borealis. Duplicates are deterministic
 * weights, not additional simulation work.
 */
const SNOW_BIASED_WEATHER_TRANSITIONS: Readonly<
  Record<WeatherKind, readonly WeatherKind[]>
> = {
  clear: ['clear', 'overcast', 'light-snow', 'light-snow', 'strong-wind'],
  overcast: ['clear', 'light-snow', 'light-snow', 'fog', 'strong-wind', 'snowstorm'],
  'light-snow': ['clear', 'overcast', 'light-snow', 'snowstorm', 'snowstorm'],
  fog: ['clear', 'clear', 'overcast', 'light-snow'],
  'strong-wind': ['clear', 'overcast', 'light-snow', 'snowstorm', 'snowstorm'],
  snowstorm: ['light-snow', 'light-snow', 'overcast', 'clear'],
};

export const WEATHER_PROFILES: Readonly<
  Record<WeatherKind, Readonly<WeatherProfile>>
> = {
  clear: Object.freeze({
    cloudCover: 0.08,
    fogDensity: 0.0105,
    snowIntensity: 0,
    windMultiplier: 0.82,
    waveMultiplier: 0.9,
    refreezeMultiplier: 0.92,
    iceContrast: 1,
  }),
  overcast: Object.freeze({
    cloudCover: 0.72,
    fogDensity: 0.014,
    snowIntensity: 0,
    windMultiplier: 0.96,
    waveMultiplier: 1,
    refreezeMultiplier: 1.04,
    iceContrast: 0.94,
  }),
  'light-snow': Object.freeze({
    cloudCover: 0.88,
    // The transition still begins with isolated flakes, but the settled
    // profile is now a readable snowfall rather than near-empty air. Falling
    // snow itself owns the distance veil; this is not also a generic fog day.
    fogDensity: 0.013,
    snowIntensity: 0.58,
    windMultiplier: 1.02,
    waveMultiplier: 1.02,
    refreezeMultiplier: 1.14,
    iceContrast: 0.9,
  }),
  fog: Object.freeze({
    cloudCover: 0.82,
    fogDensity: 0.023,
    snowIntensity: 0.04,
    windMultiplier: 0.68,
    waveMultiplier: 0.82,
    refreezeMultiplier: 1.08,
    iceContrast: 0.88,
  }),
  'strong-wind': Object.freeze({
    cloudCover: 0.54,
    fogDensity: 0.0135,
    snowIntensity: 0.03,
    windMultiplier: 1.38,
    waveMultiplier: 1.24,
    refreezeMultiplier: 0.94,
    iceContrast: 0.96,
  }),
  snowstorm: Object.freeze({
    cloudCover: 1,
    fogDensity: 0.027,
    snowIntensity: 1,
    windMultiplier: 1.55,
    waveMultiplier: 1.32,
    refreezeMultiplier: 1.22,
    iceContrast: 0.84,
  }),
};

const cycleValue = <T>(values: readonly T[], current: T): T => {
  const index = values.indexOf(current);
  return values[(index + 1) % values.length] ?? values[0]!;
};

export class WeatherSystem {
  private readonly state: WeatherState = {
    mode: 'auto',
    current: 'clear',
    target: 'overcast',
    phase: 'transition',
    phaseProgress: 0,
    frozen: false,
    timeScale: 1,
    weatherTime: 0,
    updates: 0,
    windDirectionRadians: Math.PI * 0.18,
    windTargetDirectionRadians: Math.PI * 0.18,
    windGust: 0.35,
    windStrength: WEATHER_PROFILES.clear.windMultiplier,
    weatherStoryId: 'CLEARING_WINDOW',
    weatherStoryName: 'A clearing window',
    ...WEATHER_PROFILES.clear,
  };
  private accumulator = 0;
  private phaseElapsed = 0;
  private eventIndex = 0;
  private activeWeather: WeatherKind = 'overcast';
  private snowFrequencyBias = false;

  public update(deltaSeconds: number, masterTimeScale = 1): void {
    if (this.state.frozen) return;
    const realStep = clamp(deltaSeconds, 0, 0.1);
    const masterStep = realStep * clamp(masterTimeScale, 1, 64);
    this.accumulator += masterStep;

    while (this.accumulator >= WEATHER_STEP) {
      const step = WEATHER_STEP * this.state.timeScale;
      this.state.weatherTime += step;
      if (this.state.mode === 'auto') this.advanceAutomaticCycle(step);
      else this.advanceForcedPreview();
      this.state.updates += 1;
      this.accumulator -= WEATHER_STEP;
    }

    this.approachTargetProfile(masterStep * this.state.timeScale);
  }

  public getState(): Readonly<WeatherState> {
    return this.state;
  }

  public setSnowFrequencyBias(enabled: boolean): void {
    this.snowFrequencyBias = enabled;
  }

  public getForecast(): WeatherForecast {
    const currentSnow = WEATHER_PROFILES[this.state.current].snowIntensity;
    if (this.state.snowIntensity >= 0.12 || currentSnow >= 0.2) {
      return {
        snowExpected: true,
        kind: this.state.current,
        minutesUntil: 0,
        expectedIntensity: Math.max(this.state.snowIntensity, currentSnow),
        windDirectionRadians: this.state.windDirectionRadians,
        expectedWindStrength: this.state.windStrength,
      };
    }
    const targetSnow = WEATHER_PROFILES[this.state.target].snowIntensity;
    if (targetSnow >= 0.2) {
      const remaining = this.state.phase === 'transition'
        ? Math.max(0, TRANSITION_SECONDS - this.phaseElapsed)
        : 0;
      return {
        snowExpected: true,
        kind: this.state.target,
        minutesUntil: remaining / 60,
        expectedIntensity: targetSnow,
        windDirectionRadians: this.state.windTargetDirectionRadians,
        expectedWindStrength: WEATHER_PROFILES[this.state.target].windMultiplier,
      };
    }
    if (this.state.mode === 'auto' && this.state.phase === 'calm') {
      const next = this.selectNextWeather();
      const nextSnow = WEATHER_PROFILES[next].snowIntensity;
      if (nextSnow >= 0.2) {
        const calmDuration = this.calmDurationSeconds();
        return {
          snowExpected: true,
          kind: next,
          minutesUntil:
            (Math.max(0, calmDuration - this.phaseElapsed) +
              TRANSITION_SECONDS) /
            60,
          expectedIntensity: nextSnow,
          windDirectionRadians: this.previewWindDirection(this.eventIndex + 1),
          expectedWindStrength: WEATHER_PROFILES[next].windMultiplier,
        };
      }
    }
    return {
      snowExpected: false,
      kind: this.state.target,
      minutesUntil: Number.POSITIVE_INFINITY,
      expectedIntensity: targetSnow,
      windDirectionRadians: this.state.windTargetDirectionRadians,
      expectedWindStrength: WEATHER_PROFILES[this.state.target].windMultiplier,
    };
  }

  public setMode(mode: WeatherMode): WeatherMode {
    if (!WEATHER_MODES.includes(mode)) return this.state.mode;
    this.state.mode = mode;
    this.phaseElapsed = 0;
    if (mode === 'auto') {
      this.state.phase = 'recovery';
      this.state.target = 'clear';
      this.state.phaseProgress = 0;
    } else {
      this.state.windTargetDirectionRadians = this.previewWindDirection(
        this.eventIndex + WEATHER_MODES.indexOf(mode) + 1,
      );
      this.advanceForcedPreview();
    }
    return this.state.mode;
  }

  public applyAuthorityState(
    kind: WeatherKind,
    values: Readonly<{
      windMultiplier: number;
      fogDensity: number;
      snowIntensity: number;
      refreezeMultiplier: number;
    }>,
  ): void {
    if (!Object.hasOwn(WEATHER_PROFILES, kind)) return;
    const profile = WEATHER_PROFILES[kind];
    Object.assign(this.state, profile, {
      mode: kind,
      current: kind,
      target: kind,
      phase: 'forced',
      phaseProgress: 1,
      windMultiplier: clamp(values.windMultiplier, 0.5, 1.7),
      fogDensity: clamp(values.fogDensity, 0, 0.08),
      snowIntensity: clamp(values.snowIntensity, 0, 1),
      refreezeMultiplier: clamp(values.refreezeMultiplier, 0.5, 2),
      ...(() => {
        const story = weatherStoryFor(kind, this.eventIndex);
        return { weatherStoryId: story.id, weatherStoryName: story.name };
      })(),
    });
    this.state.windStrength = this.state.windMultiplier *
      (0.78 + this.state.windGust * 0.36);
    this.phaseElapsed = 0;
    this.accumulator = 0;
  }

  public exportState(): WeatherSystemSaveData {
    return {
      version: 1,
      state: { ...this.state },
      accumulator: this.accumulator,
      phaseElapsed: this.phaseElapsed,
      eventIndex: this.eventIndex,
      activeWeather: this.activeWeather,
    };
  }

  public importState(saved: unknown): boolean {
    if (!saved || typeof saved !== 'object') return false;
    const candidate = saved as Partial<WeatherSystemSaveData>;
    const state = candidate.state as Partial<WeatherState> | undefined;
    if (
      candidate.version !== 1 ||
      !state ||
      !WEATHER_MODES.includes(state.mode as WeatherMode) ||
      !Object.hasOwn(WEATHER_PROFILES, state.current ?? '') ||
      !Object.hasOwn(WEATHER_PROFILES, state.target ?? '') ||
      !['calm', 'transition', 'active', 'recovery', 'forced']
        .includes(state.phase ?? '') ||
      !WEATHER_TIME_SCALES.includes(
        state.timeScale as WeatherTimeScale,
      ) ||
      !Object.hasOwn(
        WEATHER_PROFILES,
        candidate.activeWeather ?? '',
      )
    ) {
      return false;
    }
    const numericState = [
      state.phaseProgress,
      state.weatherTime,
      state.updates,
      state.cloudCover,
      state.fogDensity,
      state.snowIntensity,
      state.windMultiplier,
      state.waveMultiplier,
      state.refreezeMultiplier,
      state.iceContrast,
      candidate.accumulator,
      candidate.phaseElapsed,
      candidate.eventIndex,
    ];
    if (!numericState.every((value) => Number.isFinite(value))) {
      return false;
    }

    Object.assign(this.state, {
      mode: state.mode,
      current: state.current,
      target: state.target,
      phase: state.phase,
      phaseProgress: clamp(state.phaseProgress ?? 0, 0, 1),
      frozen: state.frozen === true,
      timeScale: state.timeScale,
      weatherTime: Math.max(0, state.weatherTime ?? 0),
      updates: Math.max(0, Math.floor(state.updates ?? 0)),
      cloudCover: clamp(state.cloudCover ?? 0.08, 0, 1),
      fogDensity: clamp(state.fogDensity ?? 0.0105, 0, 0.08),
      snowIntensity: clamp(state.snowIntensity ?? 0, 0, 1),
      windMultiplier: clamp(state.windMultiplier ?? 1, 0.5, 1.7),
      waveMultiplier: clamp(state.waveMultiplier ?? 1, 0.7, 1.5),
      refreezeMultiplier: clamp(
        state.refreezeMultiplier ?? 1,
        0.5,
        2,
      ),
      iceContrast: clamp(state.iceContrast ?? 1, 0.5, 1.5),
      windDirectionRadians: Number.isFinite(state.windDirectionRadians)
        ? state.windDirectionRadians
        : this.previewWindDirection(candidate.eventIndex ?? 0),
      windTargetDirectionRadians: Number.isFinite(state.windTargetDirectionRadians)
        ? state.windTargetDirectionRadians
        : this.previewWindDirection((candidate.eventIndex ?? 0) + 1),
      windGust: clamp(state.windGust ?? 0.35, 0, 1),
      windStrength: clamp(
        state.windStrength ?? (state.windMultiplier ?? 1),
        0.2,
        2.8,
      ),
      weatherStoryId: weatherStoryFor(
        state.current as WeatherKind,
        candidate.eventIndex ?? 0,
      ).id,
      weatherStoryName: weatherStoryFor(
        state.current as WeatherKind,
        candidate.eventIndex ?? 0,
      ).name,
    });
    this.accumulator = clamp(
      candidate.accumulator ?? 0,
      0,
      WEATHER_STEP,
    );
    this.phaseElapsed = Math.max(0, candidate.phaseElapsed ?? 0);
    this.eventIndex = Math.max(
      0,
      Math.floor(candidate.eventIndex ?? 0),
    );
    this.activeWeather = candidate.activeWeather as WeatherKind;
    return true;
  }

  public cycleMode(): WeatherMode {
    return this.setMode(cycleValue(WEATHER_MODES, this.state.mode));
  }

  public toggleFrozen(): boolean {
    this.state.frozen = !this.state.frozen;
    return this.state.frozen;
  }

  public cycleTimeScale(): WeatherTimeScale {
    this.state.timeScale = cycleValue(
      WEATHER_TIME_SCALES,
      this.state.timeScale,
    );
    return this.state.timeScale;
  }

  public setTimeScale(timeScale: WeatherTimeScale): void {
    this.state.timeScale = timeScale;
  }

  private advanceForcedPreview(): void {
    const forced = this.state.mode === 'auto'
      ? 'clear'
      : this.state.mode;
    this.state.phase = 'forced';
    this.state.target = forced;
    this.state.current = forced;
    this.state.phaseProgress = 1;
    const story = weatherStoryFor(forced, this.eventIndex);
    this.state.weatherStoryId = story.id;
    this.state.weatherStoryName = story.name;
  }

  private advanceAutomaticCycle(step: number): void {
    this.phaseElapsed += step;
    const calmDuration = this.calmDurationSeconds();
    const activeDuration = resolveWeatherActiveDuration(
      this.activeWeather,
      this.eventIndex,
      this.snowFrequencyBias,
    );

    if (this.state.phase === 'calm') {
      this.state.current = 'clear';
      this.state.target = 'clear';
      this.state.phaseProgress = clamp(
        this.phaseElapsed / calmDuration,
        0,
        1,
      );
      if (this.phaseElapsed >= calmDuration) {
        this.phaseElapsed = 0;
        this.activeWeather = this.selectNextWeather();
        const story = weatherStoryFor(this.activeWeather, this.eventIndex);
        this.state.weatherStoryId = story.id;
        this.state.weatherStoryName = story.name;
        this.state.windTargetDirectionRadians = this.previewWindDirection(
          this.eventIndex + 1,
        );
        this.state.phase = 'transition';
        this.state.target = this.activeWeather;
        this.state.phaseProgress = 0;
      }
      return;
    }

    if (this.state.phase === 'transition') {
      this.state.target = this.activeWeather;
      this.state.phaseProgress = clamp(
        this.phaseElapsed / TRANSITION_SECONDS,
        0,
        1,
      );
      this.state.current =
        this.state.phaseProgress < 0.5 ? 'clear' : this.activeWeather;
      if (this.phaseElapsed >= TRANSITION_SECONDS) {
        this.phaseElapsed = 0;
        this.state.phase = 'active';
        this.state.current = this.activeWeather;
        this.state.phaseProgress = 0;
      }
      return;
    }

    if (this.state.phase === 'active') {
      this.state.current = this.activeWeather;
      this.state.target = this.activeWeather;
      this.state.phaseProgress = clamp(
        this.phaseElapsed / activeDuration,
        0,
        1,
      );
      if (this.phaseElapsed >= activeDuration) {
        this.phaseElapsed = 0;
        this.state.phase = 'recovery';
        this.state.target = 'clear';
        this.state.phaseProgress = 0;
      }
      return;
    }

    this.state.target = 'clear';
    this.state.phaseProgress = clamp(
      this.phaseElapsed / RECOVERY_SECONDS,
      0,
      1,
    );
    this.state.current =
      this.state.phaseProgress < 0.5 ? this.activeWeather : 'clear';
    if (this.phaseElapsed >= RECOVERY_SECONDS) {
      this.phaseElapsed = 0;
      this.eventIndex += 1;
      this.state.phase = 'calm';
      this.state.current = 'clear';
      this.state.target = 'clear';
      this.state.phaseProgress = 0;
    }
  }

  private approachTargetProfile(step: number): void {
    const target = WEATHER_PROFILES[this.state.target];
    const response = this.state.phase === 'forced' ? 2.4 : 0.11;
    const winterSeverity = this.snowFrequencyBias &&
      (this.state.target === 'snowstorm' || this.state.target === 'strong-wind')
      ? 1
      : 0;
    const storyShape = this.state.phase === 'active' || this.state.phase === 'forced'
      ? weatherStoryShape(
          this.state.weatherStoryId,
          this.state.phaseProgress,
          this.state.weatherTime,
          this.eventIndex,
        )
      : { snow: 1, fog: 1, wind: 1, cloud: 1 };
    this.state.cloudCover = damp(
      this.state.cloudCover,
      clamp(target.cloudCover * storyShape.cloud, 0, 1),
      response,
      step,
    );
    this.state.fogDensity = damp(
      this.state.fogDensity,
      target.fogDensity * (1 + winterSeverity * 0.08) * storyShape.fog,
      response,
      step,
    );
    this.state.snowIntensity = damp(
      this.state.snowIntensity,
      clamp(
        target.snowIntensity * storyShape.snow *
          (this.snowFrequencyBias && target.snowIntensity > 0.1 ? 1.12 : 1),
        0,
        1,
      ),
      response,
      step,
    );
    this.state.windMultiplier = damp(
      this.state.windMultiplier,
      clamp((target.windMultiplier + winterSeverity * 0.11) * storyShape.wind, 0.5, 1.7),
      response,
      step,
    );
    this.state.waveMultiplier = damp(
      this.state.waveMultiplier,
      target.waveMultiplier,
      response,
      step,
    );
    this.state.refreezeMultiplier = damp(
      this.state.refreezeMultiplier,
      target.refreezeMultiplier,
      response,
      step,
    );
    this.state.iceContrast = damp(
      this.state.iceContrast,
      target.iceContrast,
      response,
      step,
    );
    const angleDelta = Math.atan2(
      Math.sin(this.state.windTargetDirectionRadians - this.state.windDirectionRadians),
      Math.cos(this.state.windTargetDirectionRadians - this.state.windDirectionRadians),
    );
    const requestedTurn = angleDelta *
      (1 - Math.exp(-step / (this.state.phase === 'forced' ? 12 : 68)));
    // Even at 128x developer time, one rendered update cannot rotate the
    // entire climate field like a switch. Trees, flakes and cloud banks all
    // receive this same slowly turning global backbone; local gusts alter
    // strength much more than direction.
    const maximumTurnPerUpdate = this.state.phase === 'forced'
      ? 0.018
      : 0.008;
    this.state.windDirectionRadians += clamp(
      requestedTurn,
      -maximumTurnPerUpdate,
      maximumTurnPerUpdate,
    );
    const gustTarget = clamp(
      0.46 +
        Math.sin(this.state.weatherTime * 0.071 + this.eventIndex * 1.7) * 0.22 +
        Math.sin(this.state.weatherTime * 0.019 + 2.4) * 0.16,
      0,
      1,
    );
    this.state.windGust = damp(this.state.windGust, gustTarget, 0.55, step);
    this.state.windStrength = this.state.windMultiplier *
      (0.78 + this.state.windGust * 0.36);
  }

  private previewWindDirection(index: number): number {
    return hash2D(index, 91, 8_113) * Math.PI * 2;
  }

  private selectNextWeather(): WeatherKind {
    const options = (
      this.snowFrequencyBias
        ? SNOW_BIASED_WEATHER_TRANSITIONS
        : WEATHER_TRANSITIONS
    )[this.activeWeather];
    const random = hash2D(
      this.eventIndex,
      Math.floor(this.state.weatherTime / 17),
      2027,
    );
    return options[
      Math.min(
        options.length - 1,
        Math.floor(random * options.length),
      )
    ] ?? 'overcast';
  }

  private calmDurationSeconds(): number {
    const defaultDuration = 82 + (this.eventIndex % 3) * 14;
    return defaultDuration * (this.snowFrequencyBias ? 0.74 : 1);
  }
}
