/**
 * Stable source-local noise. Fire animation must not depend on draw order,
 * distance sorting or a moving world position: all three made a carried
 * torch visibly change rhythm as the player moved between pooled slots.
 */
export const wildernessFireAnimationUnit = (sourceId: string): number => {
  let hash = 2166136261;
  for (let index = 0; index < sourceId.length; index += 1) {
    hash ^= sourceId.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0) / 0xffffffff;
};

