/**
 * Physical solar melt is deliberately restricted to genuinely thawing air.
 * A previous prototype applied melt around the player in clear sub-zero
 * weather. Walking therefore painted overlapping circles into newly streamed
 * snow and made distant chunks appear to dissolve in front of the camera.
 *
 * Sub-zero sun still affects lighting and surface sparkle. Persistent winter
 * snow remains unchanged until the future chunk-climate authority can evolve
 * every world cell independently of player or camera position.
 */
export const resolveWildernessSolarMeltRate = (
  context: Readonly<Pick<
    WildernessStepContext,
    | 'weatherKind'
    | 'airTemperatureCelsius'
    | 'sunIntensity'
    | 'daylight'
  >>,
  localDepth: number,
): number => {
  const daylight = context.daylight ?? 0;
  const sunIntensity = context.sunIntensity ?? 0;
  const airTemperature = context.airTemperatureCelsius ?? -30;
  if (
    context.weatherKind !== 'clear' ||
    daylight < 0.82 ||
    sunIntensity < 0.9 ||
    airTemperature < 0 ||
    localDepth <= 0.018 ||
    localDepth >= 0.18
  ) return 0;
  const warmth = clamp(airTemperature / 6, 0.08, 1);
  return 0.0012 * warmth * clamp(sunIntensity / 1.1, 0.72, 1.15);
};

