/**
 * Keep source selection deliberately ignorant of fire kind. Campfires,
 * torches, braziers and burning structure cells all use the canonical
 * volumetric presentation throughout the meaningful near/mid field. Only
 * genuinely distant sources use the orange billboard LOD.
 */
export const selectWildernessVolumetricFireSources = (
  fires: readonly PresentedWildernessFire[],
  ready: boolean,
  playerX = 0,
  playerZ = 0,
  maximumDistance = WILDERNESS_VOLUMETRIC_FIRE_RENDER_DISTANCE_METRES,
): readonly PresentedWildernessFire[] =>
  ready
    ? fires.filter((fire) =>
        Math.hypot(fire.x - playerX, fire.z - playerZ) <= maximumDistance)
    : [];

const material = (
  color: number,
  roughness = 0.86,
  emissive = 0,
  transparent = false,
): MeshStandardMaterial => new MeshStandardMaterial({
  color,
  roughness,
  metalness: 0.02,
  emissive,
  emissiveIntensity: emissive ? 0.75 : 0,
  transparent,
  opacity: transparent ? 0.46 : 1,
});

const addMesh = (
  parent: Group,
  geometry: BoxGeometry | ConeGeometry | CylinderGeometry | DodecahedronGeometry | SphereGeometry,
  meshMaterial: MeshStandardMaterial,
): Mesh => {
  const mesh = new Mesh(geometry, meshMaterial);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  parent.add(mesh);
  return mesh;
};

/**
 * Dense wilderness dressing is already lit by the shared directional and
 * hemisphere lights. Rendering every distant tree/snow shell into the 2K sun
 * shadow map doubled much of the forest workload and could overwhelm lower
 * power GPUs. Interactive resource trees keep full shadows; scenery relies on
 * the forest floor/contact language and remains visually dense.
 */
const configureSceneryBatchLighting = (
  root: Object3D,
  receiveShadow: boolean,
): void => {
  root.traverse((object) => {
    if (!(object instanceof Mesh)) return;
    object.castShadow = false;
    object.receiveShadow = receiveShadow;
  });
};

