  public suggestedActivity(): Readonly<{
    title: string;
    detail: string;
    progress: number;
  }> {
    const { inventory, firePits, shelters } = this.simulation;
    const lit = firePits.some((fire) => fire.stage === 'LIT');
    if (inventory.branches < 2) {
      return {
        title: 'Listen to the forest',
        detail: 'Gather dry branches beneath the spruce trees. There is no hurry.',
        progress: inventory.branches / 2,
      };
    }
    if (inventory.stone < 1) {
      return {
        title: 'Find a hearth stone',
        detail: 'Use the flint tool on one of the exposed surface rocks.',
        progress: inventory.stone,
      };
    }
    if (firePits.length === 0) {
      return {
        title: 'Make a sheltered hollow',
        detail: 'Choose the Fire hollow plan. Nearby tools and materials are then used contextually.',
        progress: 0,
      };
    }
    if (!lit) {
      const fire = firePits[0];
      return {
        title: 'Bring warmth to the hollow',
        detail: fire?.layStage === 'TINDER'
          ? 'Move close and press F. The flint is equipped automatically for the sparks.'
          : fire?.layStage === 'WOOD'
            ? 'Move close and place the tinder gathered with dry branches.'
            : 'Move close and lay two gathered branches into the hollow.',
        progress: fire?.layStage === 'TINDER'
          ? 0.62
          : fire?.layStage === 'WOOD'
            ? 0.48
            : 0.34,
      };
    }
    if (inventory.logs < 2 && shelters.length === 0) {
      return {
        title: 'Shape a place to rest',
        detail: 'Use the stone axe on a nearby tree. Falling trees yield physical shelter material.',
        progress: inventory.logs / 2,
      };
    }
    if (shelters.length === 0) {
      return {
        title: 'Raise a little lean-to',
        detail: 'Choose the Lean-to plan near your fire. Its first frame is only the beginning.',
        progress: 0.72,
      };
    }
    const bestShelterStage = shelters.reduce(
      (best, shelter) => Math.max(best, shelter.stage),
      0,
    );
    if (bestShelterStage < 3) {
      return {
        title: bestShelterStage === 1
          ? 'Turn the frame into shelter'
          : 'Close the roof against the snow',
        detail: bestShelterStage === 1
          ? 'Gather more timber and improve the lean-to with side cover.'
          : 'One final layer makes the roof weather-tight enough to rest beneath.',
        progress: 0.72 + bestShelterStage * 0.09,
      };
    }
    const livingFireNearShelter = shelters.some((shelter) =>
      shelter.stage >= 3 && firePits.some((fire) =>
        fire.stage === 'LIT' &&
        (fire.heatLevel ?? 0) > 0.08 &&
        Math.hypot(fire.x - shelter.x, fire.z - shelter.z) <= 7.2));
    if (!livingFireNearShelter) {
      return {
        title: 'Keep a living fire beside the roof',
        detail: 'Relight or feed the campfire. A cold roof alone is not a safe first night.',
        progress: 0.92,
      };
    }
    if (!this.simulation.hasMilestone('SAFE_FIRST_NIGHT')) {
      return {
        title: 'Let the first night become quiet',
        detail: 'Look at the finished lean-to and settle in beside the living fire.',
        progress: 0.97,
      };
    }
    const ancient = this.ancientEchoes?.view();
    if (ancient && ancient.stage !== 'MECHANOS_ATTUNED') {
      return {
        title: ancient.stageName,
        detail: ancient.objective,
        progress: ancient.progress,
      };
    }
    return {
      title: 'The camp remembers your fire',
      detail: 'Follow tracks, fish the frozen creek, bind a rune or add a lasting piece to your home.',
      progress: 1,
    };
  }

