import type { ReplicatedControlLeaseSnapshot, ReplicatedEntitySnapshot } from '../../netcode/protocol/EntityReplication';
import type { SessionRosterPayload } from '../../netcode/protocol/SessionRoster';
import type {
  MultiplayerSessionClient,
  MultiplayerSessionClientDiagnostics,
  MultiplayerSessionClientState,
} from '../client/MultiplayerSessionClient';

export interface MultiplayerNetworkInspectorSnapshot {
  state: MultiplayerSessionClientState;
  roster?: SessionRosterPayload;
  controlledEntityId?: string;
  entities: readonly ReplicatedEntitySnapshot[];
  leases: readonly ReplicatedControlLeaseSnapshot[];
  diagnostics: MultiplayerSessionClientDiagnostics;
}

export interface MultiplayerNetworkInspector {
  snapshot(): MultiplayerNetworkInspectorSnapshot;
}

declare global {
  interface Window {
    /** Development-safe network state. Never includes reconnect credentials. */
    __ICEWAY_NET__?: MultiplayerNetworkInspector;
  }
}

/** Installs the bounded read-only inspector required by the netcode roadmap. */
export const installMultiplayerNetworkInspector = (
  client: MultiplayerSessionClient,
): (() => void) => {
  const inspector: MultiplayerNetworkInspector = Object.freeze({
    snapshot: (): MultiplayerNetworkInspectorSnapshot => ({
      state: client.state(),
      roster: client.sessionRoster(),
      controlledEntityId: client.controlledReplicatedEntityId(),
      entities: client.listReplicatedEntities(),
      leases: client.replicatedLeases(),
      diagnostics: client.diagnostics(),
    }),
  });
  window.__ICEWAY_NET__ = inspector;
  return () => {
    if (window.__ICEWAY_NET__ === inspector) delete window.__ICEWAY_NET__;
  };
};
