import { clamp } from '../../utils/math';
import type {
  RouteBlockageReason,
  RouteConditionStatus,
  RouteDefinition,
  RouteState,
  RouteWidthClass,
  ShipClass,
  Vec3Like,
} from '../definitions/GameplayTypes';

export interface RoutePhysicalObservation {
  routeId: string;
  openness: number;
  measuredWidth: number;
  connected: boolean;
  minimumOpenWidth?: number;
  averageOpenWidth?: number;
  worstPoint?: Vec3Like;
  blockage?: RouteBlockageReason;
  refreezePressure?: number;
  iceRevision?: number;
}

export type RouteTransitionType =
  | 'ROUTE_OPENED'
  | 'ROUTE_WIDENED'
  | 'ROUTE_NARROWED'
  | 'ROUTE_SERVICED';

export interface RouteTransition {
  type: RouteTransitionType;
  routeId: string;
  improvement: number;
  previousWidthClass?: RouteWidthClass;
  widthClass?: RouteWidthClass;
}

export interface RouteConditionTransition {
  routeId: string;
  previousStatus: RouteConditionStatus;
  status: RouteConditionStatus;
  worstPoint?: Vec3Like;
}

export interface RouteRuntimeSaveData {
  version: 1 | 2;
  routes: RouteState[];
}

export interface RouteUpdateResult {
  transitions: RouteTransition[];
  conditionTransitions: RouteConditionTransition[];
  updatedRoutes: number;
}

export const ROUTE_OPENNESS_THRESHOLD = 0.64;
export const ROUTE_WIDTH_THRESHOLDS = Object.freeze({
  small: 1.2,
  standard: 3.2,
  heavy: 5.2,
});
export const ROUTE_STATUS_RECOVERY_STABILITY_SECONDS = 6;
export const ROUTE_STATUS_WORSENING_STABILITY_SECONDS = 12;
export const ROUTE_STATUS_STABILITY_SECONDS =
  ROUTE_STATUS_RECOVERY_STABILITY_SECONDS;

const STATUS_SEVERITY: Readonly<
  Record<RouteConditionStatus, number>
> = {
  UNKNOWN: 0,
  OPEN: 1,
  NARROW: 2,
  CRITICAL: 3,
  BLOCKED: 4,
};

const WIDTH_CLASS_RANK: Readonly<
  Record<RouteWidthClass, number>
> = {
  SMALL: 0,
  STANDARD: 1,
  HEAVY: 2,
};

export const classifyRouteWidth = (
  measuredWidth: number,
): RouteWidthClass => {
  if (measuredWidth >= ROUTE_WIDTH_THRESHOLDS.heavy) {
    return 'HEAVY';
  }
  if (measuredWidth >= ROUTE_WIDTH_THRESHOLDS.standard) {
    return 'STANDARD';
  }
  return 'SMALL';
};

export const classifyRouteCondition = (
  condition: Pick<
    RouteState,
    | 'connected'
    | 'openness'
    | 'minimumOpenWidth'
    | 'averageOpenWidth'
    | 'refreezePressure'
    | 'blockage'
  >,
): RouteConditionStatus => {
  if (
    !condition.connected ||
    condition.blockage === 'START_BLOCKED' ||
    condition.blockage === 'END_BLOCKED'
  ) {
    return 'BLOCKED';
  }
  if (
    condition.openness < ROUTE_OPENNESS_THRESHOLD ||
    condition.minimumOpenWidth <
      ROUTE_WIDTH_THRESHOLDS.small
  ) {
    return 'CRITICAL';
  }
  if (
    condition.minimumOpenWidth <
      ROUTE_WIDTH_THRESHOLDS.small * 1.18 ||
    condition.refreezePressure >= 0.72
  ) {
    return 'CRITICAL';
  }
  if (
    condition.minimumOpenWidth <
      ROUTE_WIDTH_THRESHOLDS.standard ||
    condition.averageOpenWidth <
      ROUTE_WIDTH_THRESHOLDS.standard * 1.15 ||
    condition.refreezePressure >= 0.46 ||
    condition.blockage === 'BOTTLENECK'
  ) {
    return 'NARROW';
  }
  return 'OPEN';
};

export const eligibleShipClasses = (
  state: Readonly<RouteState>,
): readonly ShipClass[] => {
  if (
    !state.connected ||
    state.openness < ROUTE_OPENNESS_THRESHOLD ||
    state.minimumOpenWidth <
      ROUTE_WIDTH_THRESHOLDS.small
  ) {
    return [];
  }
  if (
    state.minimumOpenWidth >=
    ROUTE_WIDTH_THRESHOLDS.heavy
  ) {
    return ['SMALL', 'STANDARD', 'HEAVY'];
  }
  if (
    state.minimumOpenWidth >=
    ROUTE_WIDTH_THRESHOLDS.standard
  ) {
    return ['SMALL', 'STANDARD'];
  }
  return ['SMALL'];
};

const initialState = (
  definition: Readonly<RouteDefinition>,
): RouteState => ({
  id: definition.id,
  openness: 0,
  measuredWidth: 0,
  minimumOpenWidth: 0,
  averageOpenWidth: 0,
  widthClass: 'SMALL',
  connected: false,
  blockage: 'DISCONNECTED',
  conditionStatus: 'UNKNOWN',
  refreezePressure: 0,
  measuredAt: 0,
  iceRevision: 0,
  refreezeRate: definition.baseRefreezeRate,
  lastServicedAt: 0,
  isDiscovered: !definition.discoveryRequired,
});

const finitePoint = (
  point: Readonly<Vec3Like> | undefined,
): Vec3Like | undefined =>
  point &&
  Number.isFinite(point.x) &&
  Number.isFinite(point.y) &&
  Number.isFinite(point.z)
    ? { ...point }
    : undefined;

const validBlockage = (
  value: RouteBlockageReason | undefined,
): value is RouteBlockageReason =>
  value !== undefined &&
  [
    'NONE',
    'DISCONNECTED',
    'START_BLOCKED',
    'END_BLOCKED',
    'BOTTLENECK',
  ].includes(value);

const validStatus = (
  value: RouteConditionStatus | undefined,
): value is RouteConditionStatus =>
  value !== undefined &&
  [
    'UNKNOWN',
    'OPEN',
    'NARROW',
    'CRITICAL',
    'BLOCKED',
  ].includes(value);

const sanitizeState = (
  definition: Readonly<RouteDefinition>,
  state: Readonly<Partial<RouteState> & { id: string }>,
): RouteState => {
  const minimumOpenWidth = Math.max(
    0,
    Number.isFinite(state.minimumOpenWidth)
      ? state.minimumOpenWidth!
      : Number.isFinite(state.measuredWidth)
        ? state.measuredWidth!
        : 0,
  );
  const averageOpenWidth = Math.max(
    minimumOpenWidth,
    Number.isFinite(state.averageOpenWidth)
      ? state.averageOpenWidth!
      : minimumOpenWidth,
  );
  const openness = clamp(
    Number.isFinite(state.openness)
      ? state.openness!
      : 0,
    0,
    1,
  );
  const connected =
    state.connected ??
    (openness >= ROUTE_OPENNESS_THRESHOLD &&
      minimumOpenWidth >=
        ROUTE_WIDTH_THRESHOLDS.small);
  const blockage = validBlockage(state.blockage)
    ? state.blockage
    : connected
      ? 'NONE'
      : 'DISCONNECTED';
  const condition = {
    connected,
    openness,
    minimumOpenWidth,
    averageOpenWidth,
    refreezePressure: clamp(
      Number.isFinite(state.refreezePressure)
        ? state.refreezePressure!
        : 0,
      0,
      1,
    ),
    blockage,
  };
  return {
    id: definition.id,
    openness,
    measuredWidth: minimumOpenWidth,
    minimumOpenWidth,
    averageOpenWidth,
    widthClass: classifyRouteWidth(
      minimumOpenWidth,
    ),
    connected,
    blockage,
    conditionStatus: validStatus(
      state.conditionStatus,
    )
      ? state.conditionStatus
      : classifyRouteCondition(condition),
    worstPoint: finitePoint(state.worstPoint),
    refreezePressure: condition.refreezePressure,
    measuredAt: Math.max(
      0,
      Number.isFinite(state.measuredAt)
        ? state.measuredAt!
        : 0,
    ),
    iceRevision: Math.max(
      0,
      Number.isFinite(state.iceRevision)
        ? Math.floor(state.iceRevision!)
        : 0,
    ),
    refreezeRate: clamp(
      Number.isFinite(state.refreezeRate)
        ? state.refreezeRate!
        : definition.baseRefreezeRate,
      0,
      3,
    ),
    lastServicedAt: Math.max(
      0,
      Number.isFinite(state.lastServicedAt)
        ? state.lastServicedAt!
        : 0,
    ),
    isDiscovered: state.isDiscovered === true,
  };
};

interface PendingCondition {
  status: RouteConditionStatus;
  seconds: number;
}

export class RouteRuntimeSystem {
  private readonly definitions = new Map<
    string,
    RouteDefinition
  >();
  private readonly states = new Map<string, RouteState>();
  private readonly lastObservedOpenness = new Map<
    string,
    number
  >();
  private readonly lastObservedWidth = new Map<string, number>();
  private readonly pendingConditions = new Map<
    string,
    PendingCondition
  >();

  public constructor(
    definitions: readonly RouteDefinition[],
    saved?: Readonly<RouteRuntimeSaveData>,
  ) {
    for (const definition of definitions) {
      this.definitions.set(definition.id, definition);
      this.states.set(
        definition.id,
        initialState(definition),
      );
    }
    if (saved) this.importState(saved);
  }

  public getState(routeId: string): RouteState | undefined {
    const state = this.states.get(routeId);
    return state
      ? {
          ...state,
          worstPoint: state.worstPoint
            ? { ...state.worstPoint }
            : undefined,
        }
      : undefined;
  }

  public getStates(): readonly RouteState[] {
    return [...this.states.values()].map((state) => ({
      ...state,
      worstPoint: state.worstPoint
        ? { ...state.worstPoint }
        : undefined,
    }));
  }

  public update(
    deltaSeconds: number,
    simulationTime: number,
    observations: readonly RoutePhysicalObservation[],
    environmentRefreezeMultiplier = 1,
  ): RouteUpdateResult {
    const delta = clamp(deltaSeconds, 0, 30);
    const observationByRoute = new Map(
      observations.map((observation) => [
        observation.routeId,
        observation,
      ]),
    );
    const transitions: RouteTransition[] = [];
    const conditionTransitions: RouteConditionTransition[] =
      [];
    let updatedRoutes = 0;

    for (const [routeId, definition] of this.definitions) {
      const state = this.states.get(routeId)!;
      const wasOpen =
        eligibleShipClasses(state).length > 0;
      const previousWidthClass = state.widthClass;
      const observation = observationByRoute.get(routeId);

      if (observation) {
        const targetOpenness = clamp(
          observation.connected
            ? Math.max(
                observation.openness,
                ROUTE_OPENNESS_THRESHOLD,
              )
            : Math.min(
                observation.openness,
                ROUTE_OPENNESS_THRESHOLD - 0.01,
              ),
          0,
          1,
        );
        const targetMinimumWidth = Math.max(
          0,
          observation.minimumOpenWidth ??
            observation.measuredWidth,
        );
        const targetAverageWidth = Math.max(
          targetMinimumWidth,
          observation.averageOpenWidth ??
            targetMinimumWidth,
        );
        const response = 1 - Math.exp(-2.8 * delta);
        state.openness +=
          (targetOpenness - state.openness) * response;
        state.minimumOpenWidth +=
          (targetMinimumWidth -
            state.minimumOpenWidth) *
          response;
        state.averageOpenWidth +=
          (targetAverageWidth -
            state.averageOpenWidth) *
          response;
        state.measuredWidth = state.minimumOpenWidth;
        state.connected = observation.connected;
        state.blockage =
          observation.blockage ??
          (observation.connected
            ? targetMinimumWidth <
              (definition.nominalWidth ??
                ROUTE_WIDTH_THRESHOLDS.standard)
              ? 'BOTTLENECK'
              : 'NONE'
            : 'DISCONNECTED');
        state.worstPoint = finitePoint(
          observation.worstPoint,
        );
        state.refreezePressure = clamp(
          observation.refreezePressure ?? 0,
          0,
          1,
        );
        state.measuredAt = Math.max(
          0,
          simulationTime,
        );
        state.iceRevision = Math.max(
          0,
          Math.floor(observation.iceRevision ?? 0),
        );
        if (
          observation.connected ||
          targetOpenness >= 0.32
        ) {
          state.isDiscovered = true;
        }

        const previousObservedOpenness =
          this.lastObservedOpenness.get(routeId);
        const previousObservedWidth =
          this.lastObservedWidth.get(routeId);
        if (previousObservedOpenness !== undefined) {
          const opennessImprovement =
            targetOpenness - previousObservedOpenness;
          const widthImprovement =
            targetMinimumWidth -
            (previousObservedWidth ?? 0);
          const improvement = Math.max(
            opennessImprovement,
            widthImprovement /
              ROUTE_WIDTH_THRESHOLDS.heavy,
          );
          if (improvement >= 0.035) {
            state.lastServicedAt = Math.max(
              0,
              simulationTime,
            );
            transitions.push({
              type: 'ROUTE_SERVICED',
              routeId,
              improvement,
            });
          }
        }
        this.lastObservedOpenness.set(
          routeId,
          targetOpenness,
        );
        this.lastObservedWidth.set(
          routeId,
          targetMinimumWidth,
        );
      } else if (delta > 0) {
        const closure =
          (definition.baseRefreezeRate *
            Math.max(
              0,
              environmentRefreezeMultiplier,
            ) *
            delta) /
          1800;
        state.openness = Math.max(
          0,
          state.openness - closure,
        );
        state.minimumOpenWidth = Math.max(
          0,
          state.minimumOpenWidth - closure * 2.4,
        );
        state.averageOpenWidth = Math.max(
          state.minimumOpenWidth,
          state.averageOpenWidth - closure * 1.6,
        );
        state.measuredWidth = state.minimumOpenWidth;
        state.refreezePressure = clamp(
          state.refreezePressure + closure * 0.8,
          0,
          1,
        );
        if (
          state.minimumOpenWidth <
          ROUTE_WIDTH_THRESHOLDS.small
        ) {
          state.blockage = 'BOTTLENECK';
        }
      }

      state.widthClass = classifyRouteWidth(
        state.minimumOpenWidth,
      );
      const rawCondition = classifyRouteCondition(state);
      const conditionTransition =
        this.updateStableCondition(
          routeId,
          state,
          rawCondition,
          delta,
        );
      if (conditionTransition) {
        conditionTransitions.push(conditionTransition);
      }

      const isOpen =
        eligibleShipClasses(state).length > 0;
      if (!wasOpen && isOpen) {
        transitions.push({
          type: 'ROUTE_OPENED',
          routeId,
          improvement: state.openness,
        });
      }
      if (
        isOpen &&
        state.widthClass !== previousWidthClass
      ) {
        transitions.push({
          type:
            WIDTH_CLASS_RANK[state.widthClass] >
            WIDTH_CLASS_RANK[previousWidthClass]
              ? 'ROUTE_WIDENED'
              : 'ROUTE_NARROWED',
          routeId,
          improvement:
            state.minimumOpenWidth /
            ROUTE_WIDTH_THRESHOLDS.heavy,
          previousWidthClass,
          widthClass: state.widthClass,
        });
      }
      updatedRoutes += 1;
    }

    return {
      transitions,
      conditionTransitions,
      updatedRoutes,
    };
  }

  public exportState(): RouteRuntimeSaveData {
    return {
      version: 2,
      routes: this.getStates().map((state) => ({
        ...state,
        worstPoint: state.worstPoint
          ? { ...state.worstPoint }
          : undefined,
      })),
    };
  }

  public importState(
    saved: Readonly<RouteRuntimeSaveData>,
  ): boolean {
    if (
      ![1, 2].includes(saved.version) ||
      !Array.isArray(saved.routes)
    ) {
      return false;
    }
    for (const candidate of saved.routes) {
      const definition = this.definitions.get(candidate.id);
      if (!definition) continue;
      this.states.set(
        definition.id,
        sanitizeState(definition, candidate),
      );
    }
    return true;
  }

  private updateStableCondition(
    routeId: string,
    state: RouteState,
    rawStatus: RouteConditionStatus,
    deltaSeconds: number,
  ): RouteConditionTransition | undefined {
    const current = state.conditionStatus;
    if (current === 'UNKNOWN') {
      state.conditionStatus = rawStatus;
      this.pendingConditions.delete(routeId);
      return undefined;
    }
    if (rawStatus === current) {
      this.pendingConditions.delete(routeId);
      return undefined;
    }
    const worsening =
      STATUS_SEVERITY[rawStatus] >
      STATUS_SEVERITY[current];
    const pending = this.pendingConditions.get(routeId);
    const seconds =
      pending?.status === rawStatus
        ? pending.seconds + deltaSeconds
        : deltaSeconds;
    const requiredStability = worsening
      ? ROUTE_STATUS_WORSENING_STABILITY_SECONDS
      : ROUTE_STATUS_RECOVERY_STABILITY_SECONDS;
    if (seconds < requiredStability) {
      this.pendingConditions.set(routeId, {
        status: rawStatus,
        seconds,
      });
      return undefined;
    }
    state.conditionStatus = rawStatus;
    this.pendingConditions.delete(routeId);
    return {
      routeId,
      previousStatus: current,
      status: rawStatus,
      worstPoint: state.worstPoint
        ? { ...state.worstPoint }
        : undefined,
    };
  }
}
