import {
  BoxGeometry,
  CylinderGeometry,
  Group,
  Mesh,
  MeshStandardMaterial,
  TorusGeometry,
  type Scene,
} from 'three';
import { clamp, lerp, smoothstep } from '../utils/math';
import { BOREALIS_GROUND_HEIGHT } from './BorealisLand';
import type { LandSnowSystem } from './LandSnowSystem';

export const LAND_OPERATIONS_UPGRADE_IDS = Object.freeze({
  compactCarrier: 'snow-compact-carrier',
  wheelLoader: 'snow-wheel-loader',
  heavyTruck: 'snow-heavy-haul-truck',
  helicopterSling: 'snow-helicopter-sling',
  heatingCable: 'borealis-heating-cable-kit',
  coziumEmitter: 'cozium-snow-suppression-emitter',
  municipalPlow: 'borealis-municipal-plow-service',
});

export type SnowCarrierType =
  | 'HAND_SLED'
  | 'COMPACT_CARRIER'
  | 'HEAVY_TRUCK'
  | 'HELICOPTER_SLING';

export type SnowProtectionType = 'HEATING_CABLE' | 'COZIUM_EMITTER';

export interface LandOperationsCapabilities {
  compactCarrier: boolean;
  wheelLoader: boolean;
  heavyTruck: boolean;
  helicopterSling: boolean;
  heatingCable: boolean;
  coziumEmitter: boolean;
  municipalPlow: boolean;
}

export const DEFAULT_LAND_OPERATIONS_CAPABILITIES: LandOperationsCapabilities =
  Object.freeze({
    compactCarrier: false,
    wheelLoader: false,
    heavyTruck: false,
    helicopterSling: false,
    heatingCable: false,
    coziumEmitter: false,
    municipalPlow: false,
  });

export interface SnowProtectionFieldSaveData {
  id: number;
  type: SnowProtectionType;
  x: number;
  z: number;
  heading: number;
}

export interface LandOperationsSaveData {
  version: 1 | 2;
  selectedCarrier: SnowCarrierType;
  cargoMass: number;
  selectedProtection: SnowProtectionType;
  protections: readonly SnowProtectionFieldSaveData[];
  nextProtectionId: number;
  npcEnabled: boolean;
  npcPermissionGranted?: boolean;
  npcSegment: number;
  npcSegmentProgress: number;
}

export interface LandOperationsViewModel {
  carrier: SnowCarrierType;
  carrierDisplayName: string;
  cargoMass: number;
  cargoCapacity: number;
  protection: SnowProtectionType;
  protectionDisplayName: string;
  protectionAvailable: boolean;
  protectionCount: number;
  npcAvailable: boolean;
  npcEnabled: boolean;
  npcPermissionGranted: boolean;
  npcActive: boolean;
  snowingNow: boolean;
  snowIntensity: number;
  snowForecast: boolean;
}

export interface LandOperationResult {
  changed: boolean;
  message: string;
}

const CARRIER_ORDER: readonly SnowCarrierType[] = [
  'HAND_SLED',
  'COMPACT_CARRIER',
  'HEAVY_TRUCK',
  'HELICOPTER_SLING',
];

const CARRIER_CAPACITY: Readonly<Record<SnowCarrierType, number>> = {
  HAND_SLED: 0.8,
  COMPACT_CARRIER: 4,
  HEAVY_TRUCK: 22,
  HELICOPTER_SLING: 12,
};

const CARRIER_NAME: Readonly<Record<SnowCarrierType, string>> = {
  HAND_SLED: 'hand sled',
  COMPACT_CARRIER: 'compact carrier',
  HEAVY_TRUCK: 'heavy snow truck',
  HELICOPTER_SLING: 'helicopter sling',
};

const PROTECTION_NAME: Readonly<Record<SnowProtectionType, string>> = {
  HEATING_CABLE: 'street heating cable',
  COZIUM_EMITTER: 'cozium snow emitter',
};

const NPC_ROUTE = Object.freeze([
  { x: -43, z: 8.4 },
  { x: -331, z: 8.4 },
  { x: -331, z: 40.4 },
  { x: -43, z: 40.4 },
  { x: -43, z: 72.4 },
  { x: -331, z: 72.4 },
  { x: -331, z: 104.4 },
  { x: -43, z: 104.4 },
  { x: -43, z: -23.6 },
  { x: -331, z: -23.6 },
  { x: -331, z: -55.6 },
  { x: -43, z: -55.6 },
]);

const availableCarrier = (
  carrier: SnowCarrierType,
  capabilities: Readonly<LandOperationsCapabilities>,
): boolean =>
  carrier === 'HAND_SLED' ||
  (carrier === 'COMPACT_CARRIER' && capabilities.compactCarrier) ||
  (carrier === 'HEAVY_TRUCK' && capabilities.heavyTruck) ||
  (carrier === 'HELICOPTER_SLING' && capabilities.helicopterSling);

export const resolveLandOperationsCapabilities = (
  isOwned: (upgradeId: string) => boolean,
): LandOperationsCapabilities => ({
  compactCarrier: isOwned(LAND_OPERATIONS_UPGRADE_IDS.compactCarrier),
  wheelLoader: isOwned(LAND_OPERATIONS_UPGRADE_IDS.wheelLoader),
  heavyTruck: isOwned(LAND_OPERATIONS_UPGRADE_IDS.heavyTruck),
  helicopterSling: isOwned(
    LAND_OPERATIONS_UPGRADE_IDS.helicopterSling,
  ),
  heatingCable: isOwned(LAND_OPERATIONS_UPGRADE_IDS.heatingCable),
  coziumEmitter: isOwned(LAND_OPERATIONS_UPGRADE_IDS.coziumEmitter),
  municipalPlow: isOwned(LAND_OPERATIONS_UPGRADE_IDS.municipalPlow),
});

export class LandOperationsSystem {
  private readonly root = new Group();
  private readonly protectionRoot = new Group();
  private readonly npc = new Group();
  private readonly cargoMarker = new Group();
  private readonly materials: MeshStandardMaterial[] = [];
  private capabilities: LandOperationsCapabilities = {
    ...DEFAULT_LAND_OPERATIONS_CAPABILITIES,
  };
  private selectedCarrier: SnowCarrierType = 'HAND_SLED';
  private cargoMass = 0;
  private selectedProtection: SnowProtectionType = 'HEATING_CABLE';
  private protections: SnowProtectionFieldSaveData[] = [];
  private nextProtectionId = 1;
  private npcEnabled = false;
  private npcPermissionGranted = false;
  private npcActive = false;
  private snowingNow = false;
  private snowIntensity = 0;
  private snowForecast = false;
  private npcSegment = 0;
  private npcSegmentProgress = 0;
  private weatherAccumulator = 0;
  private npcAccumulator = 0;
  private operationX = -27.4;
  private operationZ = 8.4;
  private visible = false;

  public constructor(
    scene: Scene,
    private readonly sampleGroundHeight: (x: number, z: number) => number =
      () => BOREALIS_GROUND_HEIGHT,
  ) {
    this.root.name = 'Borealis snow logistics and maintenance';
    this.protectionRoot.name = 'Player snow protection fields';
    this.createNpcModel();
    this.createCargoMarker();
    this.root.add(this.protectionRoot, this.npc, this.cargoMarker);
    this.root.visible = false;
    scene.add(this.root);
  }

  public setCapabilities(
    capabilities: Readonly<LandOperationsCapabilities>,
  ): void {
    this.capabilities = { ...capabilities };
    if (!availableCarrier(this.selectedCarrier, capabilities)) {
      this.selectedCarrier = 'HAND_SLED';
      this.cargoMass = Math.min(
        this.cargoMass,
        CARRIER_CAPACITY.HAND_SLED,
      );
    }
    if (
      this.selectedProtection === 'COZIUM_EMITTER' &&
      !capabilities.coziumEmitter
    ) {
      this.selectedProtection = 'HEATING_CABLE';
    }
    if (!capabilities.municipalPlow) {
      this.npcEnabled = false;
      this.npcPermissionGranted = false;
    }
    this.refreshPresentation();
  }

  public setVisible(visible: boolean): void {
    this.visible = visible;
    this.root.visible = visible;
    this.refreshPresentation();
  }

  public setOperationPosition(x: number, z: number): void {
    this.operationX = x;
    this.operationZ = z;
    this.cargoMarker.position.set(
      x + 1.1,
      this.sampleGroundHeight(x + 1.1, z + 1.1) + 0.32,
      z + 1.1,
    );
  }

  public cycleCarrier(): LandOperationResult {
    const available = CARRIER_ORDER.filter((carrier) =>
      availableCarrier(carrier, this.capabilities),
    );
    const current = available.indexOf(this.selectedCarrier);
    this.selectedCarrier = available[(Math.max(0, current) + 1) % available.length]!;
    this.cargoMass = Math.min(
      this.cargoMass,
      CARRIER_CAPACITY[this.selectedCarrier],
    );
    this.refreshPresentation();
    return {
      changed: true,
      message: `${CARRIER_NAME[this.selectedCarrier]} selected (${CARRIER_CAPACITY[this.selectedCarrier].toFixed(1)} m³).`,
    };
  }

  public loadSnow(snow: LandSnowSystem): LandOperationResult {
    const capacity = CARRIER_CAPACITY[this.selectedCarrier];
    const remaining = capacity - this.cargoMass;
    if (remaining <= 0.01) {
      return { changed: false, message: 'Snow carrier is already full.' };
    }
    const radius =
      this.selectedCarrier === 'HEAVY_TRUCK'
        ? 2.7
        : this.selectedCarrier === 'HELICOPTER_SLING'
          ? 2.2
          : 1.45;
    const result = snow.extractSnow(
      this.operationX,
      this.operationZ,
      radius,
      remaining,
    );
    this.cargoMass += result.snowMass;
    this.refreshPresentation();
    return result.snowMass > 0.01
      ? {
          changed: true,
          message: `Loaded ${result.snowMass.toFixed(1)} m³ of snow. Cargo ${this.cargoMass.toFixed(1)}/${capacity.toFixed(1)} m³.`,
        }
      : { changed: false, message: 'No loadable snow at this position.' };
  }

  public unloadSnow(snow: LandSnowSystem): LandOperationResult {
    if (this.cargoMass <= 0.01) {
      return { changed: false, message: 'Snow carrier is empty.' };
    }
    const radius =
      this.selectedCarrier === 'HEAVY_TRUCK'
        ? 3.3
        : this.selectedCarrier === 'HELICOPTER_SLING'
          ? 2.6
          : 1.65;
    const result = snow.depositSnow(
      this.operationX,
      this.operationZ,
      radius,
      this.cargoMass,
      6,
    );
    this.cargoMass = Math.max(0, this.cargoMass - result.snowMass);
    this.refreshPresentation();
    return result.snowMass > 0.01
      ? {
          changed: true,
          message: `Unloaded ${result.snowMass.toFixed(1)} m³. Pile peak ${result.peakDepth.toFixed(1)} m.`,
        }
      : { changed: false, message: 'There is no room for more snow here.' };
  }

  public cycleProtection(): LandOperationResult {
    if (this.capabilities.coziumEmitter) {
      this.selectedProtection =
        this.selectedProtection === 'HEATING_CABLE'
          ? 'COZIUM_EMITTER'
          : 'HEATING_CABLE';
    }
    return {
      changed: true,
      message: `${PROTECTION_NAME[this.selectedProtection]} selected.`,
    };
  }

  public installProtection(heading: number): LandOperationResult {
    const available =
      this.selectedProtection === 'HEATING_CABLE'
        ? this.capabilities.heatingCable
        : this.capabilities.coziumEmitter;
    if (!available) {
      return {
        changed: false,
        message:
          this.selectedProtection === 'HEATING_CABLE'
            ? 'Purchase the heating cable kit at Borealis first.'
            : 'Purchase the cozium snow emitter at Borealis first.',
      };
    }
    const limit = this.selectedProtection === 'HEATING_CABLE' ? 12 : 6;
    if (
      this.protections.filter(
        (field) => field.type === this.selectedProtection,
      ).length >= limit
    ) {
      return {
        changed: false,
        message: `${PROTECTION_NAME[this.selectedProtection]} deployment limit reached.`,
      };
    }
    this.protections.push({
      id: this.nextProtectionId++,
      type: this.selectedProtection,
      x: this.operationX,
      z: this.operationZ,
      heading,
    });
    this.rebuildProtectionPresentation();
    return {
      changed: true,
      message:
        this.selectedProtection === 'HEATING_CABLE'
          ? 'Heating cable installed: this street strip now melts and rejects snow.'
          : 'Cozium emitter installed: its eight-metre field now suppresses snow.',
    };
  }

  public toggleMunicipalPlow(): LandOperationResult {
    if (!this.capabilities.municipalPlow) {
      return {
        changed: false,
        message: 'Fund the municipal plow service at Borealis first.',
      };
    }
    this.npcPermissionGranted = !this.npcPermissionGranted;
    this.npcEnabled = this.npcPermissionGranted;
    this.refreshPresentation();
    return {
      changed: true,
      message: this.npcPermissionGranted
        ? 'The NPC may now borrow your starter tractor whenever snow is falling or forecast.'
        : 'The NPC will leave your starter tractor at the depot for you.',
    };
  }

  public sampleProtection(x: number, z: number): number {
    let strength = 0;
    for (const field of this.protections) {
      const dx = x - field.x;
      const dz = z - field.z;
      if (field.type === 'COZIUM_EMITTER') {
        const distance = Math.hypot(dx, dz);
        strength = Math.max(strength, 1 - smoothstep(6.4, 8, distance));
        continue;
      }
      const rightX = Math.cos(field.heading);
      const rightZ = -Math.sin(field.heading);
      const forwardX = Math.sin(field.heading);
      const forwardZ = Math.cos(field.heading);
      const lateral = Math.abs(dx * rightX + dz * rightZ);
      const forward = Math.abs(dx * forwardX + dz * forwardZ);
      const sideStrength = 1 - smoothstep(2.2, 3, lateral);
      const endStrength = 1 - smoothstep(8, 9, forward);
      strength = Math.max(strength, sideStrength * endStrength);
    }
    return clamp(strength, 0, 1);
  }

  public update(
    deltaSeconds: number,
    snowIntensity: number,
    snow: LandSnowSystem,
    snowForecast = false,
    starterTractorAvailable = true,
    simulateLocalWorld = true,
    externalSnowProtection: (x: number, z: number) => number = () => 0,
    wind: Readonly<{ x: number; z: number; strength: number }> = {
      x: 1,
      z: 0,
      strength: 0,
    },
    allowMunicipalPlow = true,
  ): void {
    const delta = clamp(deltaSeconds, 0, 0.1);
    this.weatherAccumulator += delta;
    if (this.weatherAccumulator >= 0.25) {
      if (simulateLocalWorld) {
        snow.applyWeather(
          this.weatherAccumulator,
          snowIntensity,
          (x, z) => Math.max(
            this.sampleProtection(x, z),
            clamp(externalSnowProtection(x, z), 0, 1),
          ),
          wind,
        );
      }
      this.weatherAccumulator = 0;
    }
    this.snowIntensity = clamp(snowIntensity, 0, 1);
    this.snowingNow = this.snowIntensity >= 0.015;
    this.snowForecast = snowForecast;
    this.npcActive =
      allowMunicipalPlow &&
      simulateLocalWorld &&
      this.capabilities.municipalPlow &&
      this.npcPermissionGranted &&
      starterTractorAvailable &&
      (snowIntensity >= 0.1 || snowForecast);
    if (!this.npcActive) {
      this.npc.visible = false;
      return;
    }
    this.npc.visible = this.visible;
    this.npcAccumulator += delta;
    if (this.npcAccumulator < 0.2) {
      this.writeNpcTransform();
      return;
    }
    const simulationDelta = this.npcAccumulator;
    this.npcAccumulator = 0;
    const previous = this.npcPosition();
    this.advanceNpc(simulationDelta * 2.15);
    const current = this.npcPosition();
    const heading = Math.atan2(current.x - previous.x, current.z - previous.z);
    snow.serviceCorridor(
      previous.x,
      previous.z,
      current.x,
      current.z,
      heading,
      1.85,
    );
    this.writeNpcTransform();
  }

  public getViewModel(): LandOperationsViewModel {
    const protectionAvailable =
      this.selectedProtection === 'HEATING_CABLE'
        ? this.capabilities.heatingCable
        : this.capabilities.coziumEmitter;
    return {
      carrier: this.selectedCarrier,
      carrierDisplayName: CARRIER_NAME[this.selectedCarrier],
      cargoMass: this.cargoMass,
      cargoCapacity: CARRIER_CAPACITY[this.selectedCarrier],
      protection: this.selectedProtection,
      protectionDisplayName: PROTECTION_NAME[this.selectedProtection],
      protectionAvailable,
      protectionCount: this.protections.length,
      npcAvailable: this.capabilities.municipalPlow,
      npcEnabled: this.npcPermissionGranted,
      npcPermissionGranted: this.npcPermissionGranted,
      npcActive: this.npcActive,
      snowingNow: this.snowingNow,
      snowIntensity: this.snowIntensity,
      snowForecast: this.snowForecast,
    };
  }

  public writePerformanceTrace(target: {
    landProtectionFields?: number;
    landCargoMass?: number;
    landNpcPlowEnabled?: number;
    landNpcRouteProgress?: number;
  }): void {
    target.landProtectionFields = this.protections.length;
    target.landCargoMass = this.cargoMass;
    target.landNpcPlowEnabled = this.npcActive ? 1 : 0;
    target.landNpcRouteProgress =
      this.npcSegment + this.npcSegmentProgress;
  }

  public importState(saved: unknown): boolean {
    if (!saved || typeof saved !== 'object') return false;
    const candidate = saved as Partial<LandOperationsSaveData>;
    if (candidate.version !== 1 && candidate.version !== 2) return false;
    if (CARRIER_ORDER.includes(candidate.selectedCarrier as SnowCarrierType)) {
      this.selectedCarrier = candidate.selectedCarrier as SnowCarrierType;
    }
    this.cargoMass = Math.max(
      0,
      Number.isFinite(candidate.cargoMass) ? candidate.cargoMass! : 0,
    );
    if (
      candidate.selectedProtection === 'HEATING_CABLE' ||
      candidate.selectedProtection === 'COZIUM_EMITTER'
    ) {
      this.selectedProtection = candidate.selectedProtection;
    }
    this.protections = Array.isArray(candidate.protections)
      ? candidate.protections.flatMap((field) =>
          field &&
          Number.isInteger(field.id) &&
          (field.type === 'HEATING_CABLE' ||
            field.type === 'COZIUM_EMITTER') &&
          Number.isFinite(field.x) &&
          Number.isFinite(field.z) &&
          Number.isFinite(field.heading)
            ? [{ ...field }]
            : [],
        )
      : [];
    this.nextProtectionId = Math.max(
      1,
      Number.isInteger(candidate.nextProtectionId)
        ? candidate.nextProtectionId!
        : Math.max(0, ...this.protections.map((field) => field.id)) + 1,
    );
    this.npcPermissionGranted =
      candidate.version >= 2
        ? candidate.npcPermissionGranted === true
        : candidate.npcEnabled === true;
    this.npcEnabled = this.npcPermissionGranted;
    this.npcSegment = clamp(
      Math.floor(candidate.npcSegment ?? 0),
      0,
      NPC_ROUTE.length - 1,
    );
    this.npcSegmentProgress = clamp(candidate.npcSegmentProgress ?? 0, 0, 1);
    this.rebuildProtectionPresentation();
    this.writeNpcTransform();
    return true;
  }

  public exportState(): LandOperationsSaveData {
    return {
      version: 2,
      selectedCarrier: this.selectedCarrier,
      cargoMass: this.cargoMass,
      selectedProtection: this.selectedProtection,
      protections: this.protections.map((field) => ({ ...field })),
      nextProtectionId: this.nextProtectionId,
      npcEnabled: this.npcEnabled,
      npcPermissionGranted: this.npcPermissionGranted,
      npcSegment: this.npcSegment,
      npcSegmentProgress: this.npcSegmentProgress,
    };
  }

  public dispose(): void {
    this.root.traverse((object) => {
      if (object instanceof Mesh) object.geometry.dispose();
    });
    for (const material of this.materials) material.dispose();
    this.root.removeFromParent();
  }

  private advanceNpc(distance: number): void {
    let remaining = distance;
    while (remaining > 0.0001) {
      const start = NPC_ROUTE[this.npcSegment]!;
      const end = NPC_ROUTE[(this.npcSegment + 1) % NPC_ROUTE.length]!;
      const length = Math.max(0.001, Math.hypot(end.x - start.x, end.z - start.z));
      const available = (1 - this.npcSegmentProgress) * length;
      if (remaining < available) {
        this.npcSegmentProgress += remaining / length;
        return;
      }
      remaining -= available;
      this.npcSegment = (this.npcSegment + 1) % NPC_ROUTE.length;
      this.npcSegmentProgress = 0;
    }
  }

  private npcPosition(): { x: number; z: number } {
    const start = NPC_ROUTE[this.npcSegment]!;
    const end = NPC_ROUTE[(this.npcSegment + 1) % NPC_ROUTE.length]!;
    return {
      x: lerp(start.x, end.x, this.npcSegmentProgress),
      z: lerp(start.z, end.z, this.npcSegmentProgress),
    };
  }

  private writeNpcTransform(): void {
    const position = this.npcPosition();
    const end = NPC_ROUTE[(this.npcSegment + 1) % NPC_ROUTE.length]!;
    this.npc.position.set(
      position.x,
      this.sampleGroundHeight(position.x, position.z) + 0.3,
      position.z,
    );
    this.npc.rotation.y = Math.atan2(end.x - position.x, end.z - position.z);
  }

  private rebuildProtectionPresentation(): void {
    for (const child of [...this.protectionRoot.children]) {
      this.protectionRoot.remove(child);
      child.traverse((object) => {
        if (object instanceof Mesh) object.geometry.dispose();
      });
    }
    const cableMaterial = this.material(0xffa941, 0.58, 0.05, 0xff6d1f, 0.5);
    const coziumMaterial = this.material(0x65e5d3, 0.3, 0.12, 0x29baa7, 0.75);
    for (const field of this.protections) {
      const group = new Group();
      group.name = `${PROTECTION_NAME[field.type]} ${field.id}`;
      group.position.set(
        field.x,
        this.sampleGroundHeight(field.x, field.z) + 0.022,
        field.z,
      );
      group.rotation.y = field.heading;
      if (field.type === 'HEATING_CABLE') {
        for (const side of [-1.45, 0, 1.45]) {
          const cable = new Mesh(new BoxGeometry(0.045, 0.025, 17), cableMaterial);
          cable.position.x = side;
          group.add(cable);
        }
      } else {
        const ring = new Mesh(new TorusGeometry(0.42, 0.055, 8, 28), coziumMaterial);
        ring.rotation.x = Math.PI / 2;
        ring.position.y = 0.08;
        const mast = new Mesh(new CylinderGeometry(0.08, 0.12, 0.7, 10), coziumMaterial);
        mast.position.y = 0.35;
        group.add(ring, mast);
      }
      this.protectionRoot.add(group);
    }
  }

  private createNpcModel(): void {
    const orange = this.material(0xe89a36, 0.68, 0.06);
    const dark = this.material(0x263536, 0.84, 0.12);
    const steel = this.material(0x789092, 0.55, 0.32);
    const body = new Mesh(new BoxGeometry(1.05, 0.55, 1.35), orange);
    body.position.y = 0.38;
    const cabin = new Mesh(new BoxGeometry(0.82, 0.75, 0.68), orange);
    cabin.position.set(0, 0.91, -0.2);
    for (const side of [-0.62, 0.62]) {
      const track = new Mesh(new BoxGeometry(0.25, 0.3, 1.45), dark);
      track.position.set(side, 0.22, 0);
      this.npc.add(track);
    }
    const blade = new Mesh(new BoxGeometry(1.65, 0.34, 0.1), steel);
    blade.position.set(0, 0.24, 0.95);
    blade.rotation.x = -0.12;
    this.npc.add(body, cabin, blade);
    this.npc.name = 'Borealis municipal NPC snow tractor';
    this.npc.visible = false;
  }

  private createCargoMarker(): void {
    const frame = this.material(0x36484a, 0.75, 0.18);
    const snow = this.material(0xdaf3f4, 0.92, 0);
    const sled = new Mesh(new BoxGeometry(1.1, 0.18, 1.45), frame);
    const load = new Mesh(new BoxGeometry(0.95, 0.38, 1.2), snow);
    load.position.y = 0.27;
    this.cargoMarker.add(sled, load);
    this.cargoMarker.name = 'Active snow logistics cargo';
    this.cargoMarker.visible = false;
  }

  private refreshPresentation(): void {
    this.npc.visible =
      this.visible && this.capabilities.municipalPlow && this.npcActive;
    // The legacy abstract cargo token is intentionally dormant. Snow now
    // exists only in physical buckets, trailers, truck beds and slings.
    this.cargoMarker.visible = false;
    const fill = clamp(
      this.cargoMass / CARRIER_CAPACITY[this.selectedCarrier],
      0.08,
      1,
    );
    this.cargoMarker.scale.set(
      this.selectedCarrier === 'HEAVY_TRUCK' ? 1.8 : 1,
      fill,
      this.selectedCarrier === 'HELICOPTER_SLING' ? 1.45 : 1,
    );
  }

  private material(
    color: number,
    roughness: number,
    metalness: number,
    emissive = 0,
    emissiveIntensity = 0,
  ): MeshStandardMaterial {
    const material = new MeshStandardMaterial({
      color,
      roughness,
      metalness,
      emissive,
      emissiveIntensity,
    });
    this.materials.push(material);
    return material;
  }
}
