import {
  cloneInventoryContentSnapshot,
  clonePortableItemSnapshot,
  inventoryContentIdForOwner,
  validateInventoryOwnershipGraph,
  type InventoryContentSnapshot,
  type InventoryStateBaselinePartPayload,
  type InventoryStateDeltaPayload,
  type InventoryStateResyncRequestPayload,
  type PortableItemSnapshot,
} from '../../netcode/protocol/InventoryReplication';
import type { PlayerId } from '../../netcode/core/NetworkPrimitives';

export interface InventoryReplicationClientDiagnostics {
  revision: number;
  items: number;
  contents: number;
  occupiedSlots: number;
  completedBaselines: number;
  appliedDeltas: number;
  staleDeltas: number;
  rejectedBaselines: number;
  rejectedDeltas: number;
  resyncRequests: number;
  pendingTransfers: number;
}

export type InventoryReplicationClientEvent =
  | {
      readonly kind: 'BASELINE';
      readonly payload: Readonly<InventoryStateBaselinePartPayload>;
      readonly items: readonly PortableItemSnapshot[];
      readonly contents: readonly InventoryContentSnapshot[];
    }
  | {
      readonly kind: 'DELTA';
      readonly payload: Readonly<InventoryStateDeltaPayload>;
      readonly changedItems: readonly PortableItemSnapshot[];
      readonly changedContents: readonly InventoryContentSnapshot[];
    };

interface PendingInventoryBaseline {
  readonly transferId: string;
  readonly revision: number;
  readonly partCount: number;
  readonly totalItemCount: number;
  readonly totalContentCount: number;
  readonly parts: Map<number, InventoryStateBaselinePartPayload>;
}

/** Atomically applies complete item/content baselines and contiguous deltas. */
export class InventoryReplicationClient {
  private readonly items = new Map<string, PortableItemSnapshot>();
  private readonly contents = new Map<string, InventoryContentSnapshot>();
  private readonly pendingTransfers = new Map<string, PendingInventoryBaseline>();
  private pendingResync?: InventoryStateResyncRequestPayload;
  private revisionValue = 0;
  private completedBaselines = 0;
  private appliedDeltas = 0;
  private staleDeltas = 0;
  private rejectedBaselines = 0;
  private rejectedDeltas = 0;
  private resyncRequestCount = 0;

  public constructor(
    private readonly expectedWorldDatasetHash: string,
    private readonly requestResync?: (
      request: Readonly<InventoryStateResyncRequestPayload>,
    ) => void,
  ) {}

  public get revision(): number {
    return this.revisionValue;
  }

  public listItems(): readonly PortableItemSnapshot[] {
    return [...this.items.values()]
      .sort((left, right) => left.itemId.localeCompare(right.itemId))
      .map(clonePortableItemSnapshot);
  }

  public listContents(): readonly InventoryContentSnapshot[] {
    return [...this.contents.values()]
      .sort((left, right) => left.contentId.localeCompare(right.contentId))
      .map(cloneInventoryContentSnapshot);
  }

  public getItem(itemId: string): PortableItemSnapshot | undefined {
    const item = this.items.get(itemId);
    return item ? clonePortableItemSnapshot(item) : undefined;
  }

  public getContent(contentId: string): InventoryContentSnapshot | undefined {
    const content = this.contents.get(contentId);
    return content ? cloneInventoryContentSnapshot(content) : undefined;
  }

  public playerContent(playerId: PlayerId): InventoryContentSnapshot | undefined {
    return this.getContent(inventoryContentIdForOwner({ kind: 'PLAYER', playerId }));
  }

  public diagnostics(): InventoryReplicationClientDiagnostics {
    return {
      revision: this.revisionValue,
      items: this.items.size,
      contents: this.contents.size,
      occupiedSlots: [...this.contents.values()].reduce(
        (total, content) =>
          total + content.slots.filter((slot) => Boolean(slot.itemId)).length,
        0,
      ),
      completedBaselines: this.completedBaselines,
      appliedDeltas: this.appliedDeltas,
      staleDeltas: this.staleDeltas,
      rejectedBaselines: this.rejectedBaselines,
      rejectedDeltas: this.rejectedDeltas,
      resyncRequests: this.resyncRequestCount,
      pendingTransfers: this.pendingTransfers.size,
    };
  }

  public applyBaselinePart(
    payload: Readonly<InventoryStateBaselinePartPayload>,
  ): InventoryReplicationClientEvent | undefined {
    if (
      payload.worldDatasetHash !== this.expectedWorldDatasetHash ||
      payload.revision < this.revisionValue
    ) {
      this.rejectedBaselines += 1;
      return undefined;
    }
    let transfer = this.pendingTransfers.get(payload.transferId);
    if (!transfer) {
      transfer = {
        transferId: payload.transferId,
        revision: payload.revision,
        partCount: payload.partCount,
        totalItemCount: payload.totalItemCount,
        totalContentCount: payload.totalContentCount,
        parts: new Map(),
      };
      this.pendingTransfers.set(payload.transferId, transfer);
      while (this.pendingTransfers.size > 4) {
        const oldest = this.pendingTransfers.keys().next().value as
          | string
          | undefined;
        if (!oldest) break;
        this.pendingTransfers.delete(oldest);
      }
    }
    if (
      transfer.revision !== payload.revision ||
      transfer.partCount !== payload.partCount ||
      transfer.totalItemCount !== payload.totalItemCount ||
      transfer.totalContentCount !== payload.totalContentCount
    ) {
      this.rejectTransfer(payload.transferId);
      return undefined;
    }
    const existing = transfer.parts.get(payload.partIndex);
    if (existing && JSON.stringify(existing) !== JSON.stringify(payload)) {
      this.rejectTransfer(payload.transferId);
      return undefined;
    }
    if (!existing) transfer.parts.set(payload.partIndex, {
      ...payload,
      items: payload.items.map(clonePortableItemSnapshot),
      contents: payload.contents.map(cloneInventoryContentSnapshot),
    });
    if (transfer.parts.size !== transfer.partCount) return undefined;
    this.pendingTransfers.delete(payload.transferId);
    const assembled = this.assembleBaseline(transfer);
    if (!assembled) {
      this.rejectedBaselines += 1;
      this.queueResync();
      return undefined;
    }
    this.items.clear();
    this.contents.clear();
    for (const item of assembled.items) this.items.set(item.itemId, item);
    for (const content of assembled.contents) {
      this.contents.set(content.contentId, content);
    }
    this.revisionValue = payload.revision;
    this.completedBaselines += 1;
    this.pendingResync = undefined;
    return {
      kind: 'BASELINE',
      payload,
      items: this.listItems(),
      contents: this.listContents(),
    };
  }

  public applyDelta(
    payload: Readonly<InventoryStateDeltaPayload>,
  ): InventoryReplicationClientEvent | undefined {
    if (payload.revision <= this.revisionValue) {
      this.staleDeltas += 1;
      return undefined;
    }
    if (payload.baseRevision !== this.revisionValue) {
      this.rejectedDeltas += 1;
      this.queueResync();
      return undefined;
    }
    const prospectiveItems = new Map(
      this.listItems().map((item) => [item.itemId, item] as const),
    );
    const prospectiveContents = new Map(
      this.listContents().map((content) => [content.contentId, content] as const),
    );
    for (const item of payload.changedItems) {
      const current = prospectiveItems.get(item.itemId);
      if (current && item.revision !== current.revision + 1) {
        this.rejectedDeltas += 1;
        this.queueResync();
        return undefined;
      }
      prospectiveItems.set(item.itemId, clonePortableItemSnapshot(item));
    }
    for (const content of payload.changedContents) {
      const current = prospectiveContents.get(content.contentId);
      if (current && content.revision !== current.revision + 1) {
        this.rejectedDeltas += 1;
        this.queueResync();
        return undefined;
      }
      prospectiveContents.set(
        content.contentId,
        cloneInventoryContentSnapshot(content),
      );
    }
    const items = [...prospectiveItems.values()];
    const contents = [...prospectiveContents.values()];
    if (validateInventoryOwnershipGraph(items, contents)) {
      this.rejectedDeltas += 1;
      this.queueResync();
      return undefined;
    }
    this.items.clear();
    this.contents.clear();
    for (const item of items) this.items.set(item.itemId, item);
    for (const content of contents) this.contents.set(content.contentId, content);
    this.revisionValue = payload.revision;
    this.appliedDeltas += 1;
    this.pendingResync = undefined;
    return {
      kind: 'DELTA',
      payload,
      changedItems: payload.changedItems.map(clonePortableItemSnapshot),
      changedContents: payload.changedContents.map(
        cloneInventoryContentSnapshot,
      ),
    };
  }

  public drainResyncRequests(): readonly InventoryStateResyncRequestPayload[] {
    if (this.requestResync || !this.pendingResync) return [];
    const request = this.pendingResync;
    this.pendingResync = undefined;
    return [request];
  }

  public reset(): void {
    this.items.clear();
    this.contents.clear();
    this.pendingTransfers.clear();
    this.pendingResync = undefined;
    this.revisionValue = 0;
  }

  private assembleBaseline(
    transfer: Readonly<PendingInventoryBaseline>,
  ): {
    items: PortableItemSnapshot[];
    contents: InventoryContentSnapshot[];
  } | undefined {
    const itemSlots = new Array<PortableItemSnapshot | undefined>(
      transfer.totalItemCount,
    );
    const contentSlots = new Array<InventoryContentSnapshot | undefined>(
      transfer.totalContentCount,
    );
    for (const part of [...transfer.parts.values()].sort(
      (left, right) => left.partIndex - right.partIndex,
    )) {
      for (let index = 0; index < part.items.length; index += 1) {
        const target = part.itemOffset + index;
        if (target >= itemSlots.length || itemSlots[target]) return undefined;
        itemSlots[target] = clonePortableItemSnapshot(part.items[index]!);
      }
      for (let index = 0; index < part.contents.length; index += 1) {
        const target = part.contentOffset + index;
        if (target >= contentSlots.length || contentSlots[target]) return undefined;
        contentSlots[target] = cloneInventoryContentSnapshot(part.contents[index]!);
      }
    }
    if (
      itemSlots.some((item) => !item) ||
      contentSlots.some((content) => !content)
    ) return undefined;
    const items = itemSlots as PortableItemSnapshot[];
    const contents = contentSlots as InventoryContentSnapshot[];
    return validateInventoryOwnershipGraph(items, contents)
      ? undefined
      : { items, contents };
  }

  private rejectTransfer(transferId: string): void {
    this.pendingTransfers.delete(transferId);
    this.rejectedBaselines += 1;
    this.queueResync();
  }

  private queueResync(): void {
    if (this.pendingResync) return;
    const request: InventoryStateResyncRequestPayload = {
      version: 1,
      kind: 'INVENTORY_STATE_RESYNC_REQUEST',
      observedRevision: this.revisionValue,
    };
    this.pendingResync = request;
    this.resyncRequestCount += 1;
    this.requestResync?.(request);
  }
}
