  public createCommand(options: {
    controlledEntityId?: NetworkEntityId;
    predictedTick?: ServerTick;
    movement: NormalizedMovementCommand;
    tool?: NormalizedToolCommand;
    actionBits?: number;
  }): PlayerCommandFrame {
    if (!this.playerId) throw new Error('Cannot create a command before joining.');
    return {
      version: 1,
      playerId: this.playerId,
      controlledEntityId: options.controlledEntityId,
      commandSequence: commandSequence(this.nextCommandSequence++),
      predictedTick: options.predictedTick ?? this.predictedServerTick(),
      movement: { ...options.movement },
      tool: options.tool
        ? { ...options.tool }
        : { primaryAxis: 0, secondaryAxis: 0 },
      actionBits: options.actionBits ?? 0,
    };
  }

  public sendCommandBatch(
    commands: readonly PlayerCommandFrame[],
  ): TransportSendResult {
    if (!this.playerId || !this.sessionEpoch || this.currentPhase !== 'JOINED') {
      return { accepted: false, reason: 'NOT_OPEN' };
    }
    if (commands.length === 0 || commands.length > 8) {
      return { accepted: false, reason: 'INVALID_MESSAGE' };
    }
    const validated: PlayerCommandFrame[] = [];
    for (const candidate of commands) {
      const validation = validatePlayerCommandFrame(candidate);
      const previous = validated[validated.length - 1];
      if (
        !validation.ok ||
        validation.value.playerId !== this.playerId ||
        (previous !== undefined &&
          (validation.value.commandSequence <= previous.commandSequence ||
            validation.value.predictedTick < previous.predictedTick))
      ) {
        return { accepted: false, reason: 'INVALID_MESSAGE' };
      }
      validated.push(validation.value);
    }
    const latest = validated[validated.length - 1]!;
    const result = this.endpoint!.send(
      createCoreNetworkEnvelope({
        type: 'PLAYER_COMMAND_BATCH',
        sessionId: this.options.sessionId,
        sessionEpoch: this.sessionEpoch,
        streamId: `player-command:${this.playerId}`,
        streamSequence: streamSequence(latest.commandSequence),
        payload: { version: 1, commands: validated },
      }),
    );
    if (result.accepted) this.stats.sentCommandFrames += validated.length;
    if (result.accepted) {
      for (const command of validated) {
        this.entityReplication.recordPredictedCommand(command);
      }
    }
    return result;
  }

  public submitOperation(options: {
    channel: ReliableAuthorityChannel;
    operation: string;
    targetEntityId?: NetworkEntityId;
    observedRevision?: Revision;
    payload?: JsonObject;
    requestId?: TransactionId;
  }): { operation?: ReliableAuthorityOperation; result: TransportSendResult } {
    if (!this.playerId) {
      return { result: { accepted: false, reason: 'NOT_OPEN' } };
    }
    const requestId =
      options.requestId ??
      transactionId(`tx:${this.nextOperationSequence++}:${this.idFactory()}`);
    const operation: ReliableAuthorityOperation = {
      version: 1,
      requestId,
      playerId: this.playerId,
      issuedAtTick: this.predictedServerTick(),
      channel: options.channel,
      operation: options.operation,
      targetEntityId: options.targetEntityId,
      observedRevision: options.observedRevision,
      payload: options.payload ? { ...options.payload } : {},
    };
    const validation = validateReliableAuthorityOperation(operation);
    if (!validation.ok) {
      return { result: { accepted: false, reason: 'INVALID_MESSAGE' } };
    }
    if (
      !this.reliableOutbox.has(requestId) &&
      this.reliableOutbox.size >= this.maximumReliableOutbox
    ) {
      return { result: { accepted: false, reason: 'QUEUE_FULL' } };
    }
    this.reliableOutbox.set(requestId, validation.value);
    const result = this.sendReliableOperation(validation.value);
    if (result.accepted) {
      this.nextReliableRetryAtMs = this.nowMs() + this.reliableRetryIntervalMs;
    }
    return { operation: validation.value, result };
  }

