  private submitPortableInventoryOperation(
    operation: string,
    item: Readonly<PortableItemSnapshot>,
    payload: unknown,
  ) {
    if (!this.inventoryCapabilityNegotiated()) {
      return this.unavailablePortableInventoryResult();
    }
    return this.submitOperation({
      channel: 'INVENTORY',
      operation,
      observedRevision: revision(item.revision),
      payload: asJsonObject(payload),
    });
  }

  private localInventorySlot(slotId: string) {
    const content = this.replicatedPlayerInventory();
    const slot = content?.slots.find((candidate) => candidate.slotId === slotId);
    return content && slot ? { content, slot } : undefined;
  }

  private sourceInventorySlot(parent: Readonly<PortableItemParent>) {
    let contentId: string | undefined;
    let slotId: string | undefined;
    switch (parent.kind) {
      case 'PLAYER':
        contentId = inventoryContentIdForOwner(parent);
        slotId = parent.slotId;
        break;
      case 'VEHICLE_SLOT':
        contentId = inventoryContentIdForOwner({
          kind: 'VEHICLE',
          entityId: parent.entityId,
        });
        slotId = parent.slotId;
        break;
      case 'CONTAINER_SLOT':
        contentId = inventoryContentIdForOwner({
          kind: 'CONTAINER',
          containerId: parent.containerId,
        });
        slotId = parent.slotId;
        break;
      case 'WORLD':
      case 'CONSUMED':
        return undefined;
    }
    const content = this.inventoryReplication.getContent(contentId);
    const slot = content?.slots.find((candidate) => candidate.slotId === slotId);
    return content && slot ? { content, slot } : undefined;
  }

  private unavailablePortableInventoryResult() {
    return {
      result: {
        accepted: false as const,
        reason: 'INVALID_MESSAGE' as const,
      },
    };
  }

