  private sendSnowResyncRequest(
    request: Readonly<{
      tileX: number;
      tileZ: number;
      observedRevision: Revision;
    }>,
  ): TransportSendResult {
    if (!this.endpoint || !this.sessionEpoch || this.currentPhase !== 'JOINED') {
      return { accepted: false, reason: 'NOT_OPEN' };
    }
    return this.endpoint.send(createCoreNetworkEnvelope({
      type: 'SNOW_TILE_RESYNC_REQUEST',
      sessionId: this.options.sessionId,
      sessionEpoch: this.sessionEpoch,
      payload: {
        version: 1,
        tileX: request.tileX,
        tileZ: request.tileZ,
        observedRevision: request.observedRevision,
      },
    }));
  }

