export type WorldFactValue = string | number | boolean;

export interface WorldFactObservation {
  readonly factId: string;
  readonly value: WorldFactValue;
}

export interface WorldFactSaveData {
  readonly version: 1;
  readonly facts: readonly {
    readonly factId: string;
    readonly value: WorldFactValue;
    readonly revision: number;
  }[];
}

interface WorldFactRecord {
  value: WorldFactValue;
  revision: number;
}

const validId = (value: unknown): value is string =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= 192;

const validValue = (value: unknown): value is WorldFactValue =>
  typeof value === 'string' || typeof value === 'boolean' ||
  (typeof value === 'number' && Number.isFinite(value));

/** Persistent authored facts plus replaceable physical observations. */
export class WorldFactSystem {
  private readonly persistent = new Map<string, WorldFactRecord>();
  private readonly observations = new Map<string, WorldFactValue>();

  public constructor(saved?: Readonly<WorldFactSaveData>) {
    if (saved?.version !== 1 || !Array.isArray(saved.facts)) return;
    for (const fact of saved.facts) {
      if (!validId(fact?.factId) || !validValue(fact.value)) continue;
      this.persistent.set(fact.factId, {
        value: fact.value,
        revision: Number.isSafeInteger(fact.revision) && fact.revision >= 0 ? fact.revision : 0,
      });
    }
  }

  public observe(values: readonly Readonly<WorldFactObservation>[]): void {
    for (const observation of values) {
      if (validId(observation.factId) && validValue(observation.value)) {
        this.observations.set(observation.factId, observation.value);
      }
    }
  }

  public setPersistent(factId: string, value: WorldFactValue): boolean {
    if (!validId(factId) || !validValue(value)) return false;
    const current = this.persistent.get(factId);
    if (current?.value === value) return false;
    this.persistent.set(factId, { value, revision: (current?.revision ?? 0) + 1 });
    return true;
  }

  public get(factId: string): WorldFactValue | undefined {
    return this.observations.get(factId) ?? this.persistent.get(factId)?.value;
  }

  public exportState(): WorldFactSaveData {
    return {
      version: 1,
      facts: [...this.persistent.entries()].sort(([left], [right]) => left.localeCompare(right)).map(([factId, fact]) => ({
        factId,
        value: fact.value,
        revision: fact.revision,
      })),
    };
  }
}

