import {
  BufferAttribute,
  DoubleSide,
  InstancedBufferAttribute,
  InstancedBufferGeometry,
  Mesh,
  NormalBlending,
  Scene,
  ShaderMaterial,
  Vector2,
  Vector3,
  type Camera,
  type Texture,
} from 'three';
import { clamp, smoothstep } from '../utils/math';
import { WORLD_CLOUD_FIELD_GLSL } from './WorldCloudField';

export const GPU_SNOWFLAKE_CAPACITY = 30_000;
export const LONG_WINTER_GENERAL_SNOWFLAKE_CAPACITY = 19_500;
export const LONG_WINTER_LOCAL_SNOWFLAKE_CAPACITY = 2_500;
export const LONG_WINTER_TOTAL_SNOWFLAKE_CAPACITY =
  LONG_WINTER_GENERAL_SNOWFLAKE_CAPACITY +
  LONG_WINTER_LOCAL_SNOWFLAKE_CAPACITY;

export interface GpuSnowfallCounts {
  readonly general: number;
  readonly localDensity: number;
  readonly submitted: number;
}

export const resolveGpuSnowflakeCount = (
  visualRate: number,
  qualityMultiplier = 1,
  runtimeBudgetMultiplier = 1,
): number => Math.floor(
  GPU_SNOWFLAKE_CAPACITY *
  clamp(qualityMultiplier, 0.35, 1) *
  clamp(runtimeBudgetMultiplier, 0.35, 1) *
  smoothstep(0.015, 1.08, clamp(visualRate, 0, 1.28)),
);

/** Stable shader density: changing weather fades a deterministic subset. */
export const resolveGpuSnowflakeDensity = (visualRate: number): number =>
  smoothstep(0.015, 1.08, clamp(visualRate, 0, 1.28));

/**
 * Resolves the visible prefix without allocating an emitter or a particle
 * list. The local instances are interleaved through the same prefix as the
 * general field, so both families can grow from one draw call.
 */
export const resolveGpuSnowfallCounts = (
  visualRate: number,
  qualityMultiplier = 1,
  runtimeBudgetMultiplier = 1,
  localDensityEnabled = false,
): GpuSnowfallCounts => {
  const density = resolveGpuSnowflakeDensity(visualRate);
  const quality = clamp(qualityMultiplier, 0.35, 1);
  const generalCapacity = localDensityEnabled
    ? LONG_WINTER_GENERAL_SNOWFLAKE_CAPACITY
    : Math.floor(
        GPU_SNOWFLAKE_CAPACITY *
        clamp(runtimeBudgetMultiplier, 0.35, 1),
      );
  const localCapacity = localDensityEnabled
    ? LONG_WINTER_LOCAL_SNOWFLAKE_CAPACITY
    : 0;
  const general = Math.floor(generalCapacity * quality * density);
  const localDensity = Math.floor(localCapacity * quality * density);
  return {
    general,
    localDensity,
    submitted: general + localDensity,
  };
};

/** Deterministic family assignment used by the shared instanced prefix. */
export const isLongWinterLocalSnowflakeIndex = (index: number): boolean => {
  if (index < 0 || index >= LONG_WINTER_TOTAL_SNOWFLAKE_CAPACITY) {
    return false;
  }
  const before = Math.floor(
    index * LONG_WINTER_LOCAL_SNOWFLAKE_CAPACITY /
    LONG_WINTER_TOTAL_SNOWFLAKE_CAPACITY,
  );
  const after = Math.floor(
    (index + 1) * LONG_WINTER_LOCAL_SNOWFLAKE_CAPACITY /
    LONG_WINTER_TOTAL_SNOWFLAKE_CAPACITY,
  );
  return after > before;
};

const positiveModulo = (value: number, divisor: number): number =>
  ((value % divisor) + divisor) % divisor;

/**
 * CPU twin of the shader wrap, kept public for the world-stability regression
 * test. Moving an anchor cannot move a flake until that flake crosses the
 * feathered recycle boundary.
 */
export const resolveWorldStableSnowflakeCoordinate = (
  seed: number,
  displacement: number,
  anchor: number,
  span: number,
): number => {
  const safeSpan = Math.max(0.001, span);
  const origin = anchor - safeSpan * 0.5;
  return positiveModulo(
    seed * safeSpan + displacement - origin,
    safeSpan,
  ) + origin;
};

const hash = (value: number): number => {
  const sine = Math.sin(value * 127.1 + 311.7) * 43_758.545_312_3;
  return sine - Math.floor(sine);
};

const GPU_SNOWFLAKE_POSITION_SEED_OFFSETS = [0.17, 1.73, 2.91] as const;

export const resolveGpuSnowflakePositionSeed = (
  index: number,
  axis: 0 | 1 | 2,
): number => hash(
  index * 3 + GPU_SNOWFLAKE_POSITION_SEED_OFFSETS[axis],
);

export const resolveGpuSnowflakeFamilySeed = (index: number): number =>
  hash(index * 11.47 + 73.1);

/**
 * One GPU-instanced snowfall draw for OTS/first-person views. The CPU only
 * changes uniforms; wrapping, fall, flutter and wind happen in the vertex
 * shader. The visible prefix grows continuously with weather intensity while
 * each instance keeps its own stable world-space seed.
 * The principle is compatible with the MIT-licensed
 * SnowSystemThreeJS demo, but the field here is world-stable, quality-scaled
 * and driven by ICEWAY's own climate and cloud gate.
 */
export class GpuSnowfallField {
  private readonly geometry = new InstancedBufferGeometry();
  private readonly material: ShaderMaterial;
  private readonly mesh: Mesh<InstancedBufferGeometry, ShaderMaterial>;
  private readonly windVelocity = new Vector2();
  private readonly windOffset = new Vector2();
  private elapsed = 0;
  private activeCount = 0;
  private generalActiveCount = 0;
  private localDensityActiveCount = 0;
  private locallyVisible = true;
  private shaderWarmupActive = false;
  private runtimeBudgetMultiplier = 1;
  private localDensityEnabled = false;

  public constructor(
    scene: Scene,
    texture: Texture,
    private readonly qualityMultiplier = 1,
  ) {
    this.geometry.setAttribute('position', new BufferAttribute(
      new Float32Array([
        -0.5, -0.5, 0,
        0.5, -0.5, 0,
        0.5, 0.5, 0,
        -0.5, 0.5, 0,
      ]),
      3,
    ));
    this.geometry.setAttribute('uv', new BufferAttribute(
      new Float32Array([0, 0, 1, 0, 1, 1, 0, 1]),
      2,
    ));
    this.geometry.setIndex([0, 1, 2, 0, 2, 3]);
    const seeds = new Float32Array(GPU_SNOWFLAKE_CAPACITY * 3);
    const variations = new Float32Array(GPU_SNOWFLAKE_CAPACITY);
    const families = new Float32Array(GPU_SNOWFLAKE_CAPACITY);
    const densityRanks = new Float32Array(GPU_SNOWFLAKE_CAPACITY);
    const localLayers = new Float32Array(GPU_SNOWFLAKE_CAPACITY);
    for (let index = 0; index < GPU_SNOWFLAKE_CAPACITY; index += 1) {
      const offset = index * 3;
      seeds[offset] = resolveGpuSnowflakePositionSeed(index, 0);
      seeds[offset + 1] = resolveGpuSnowflakePositionSeed(index, 1);
      seeds[offset + 2] = resolveGpuSnowflakePositionSeed(index, 2);
      variations[index] = hash(index * 7.13 + 19.7);
      // Family must not share an axis seed. Using aSeed.z here partitioned
      // slow, medium and powder flakes into visible multi-metre depth bands.
      families[index] = resolveGpuSnowflakeFamilySeed(index);
      densityRanks[index] = index / Math.max(1, GPU_SNOWFLAKE_CAPACITY - 1);
      localLayers[index] = isLongWinterLocalSnowflakeIndex(index) ? 1 : 0;
    }
    this.geometry.setAttribute(
      'aSeed',
      new InstancedBufferAttribute(seeds, 3),
    );
    this.geometry.setAttribute(
      'aVariation',
      new InstancedBufferAttribute(variations, 1),
    );
    this.geometry.setAttribute(
      'aFamily',
      new InstancedBufferAttribute(families, 1),
    );
    this.geometry.setAttribute(
      'aDensityRank',
      new InstancedBufferAttribute(densityRanks, 1),
    );
    this.geometry.setAttribute(
      'aLocalLayer',
      new InstancedBufferAttribute(localLayers, 1),
    );
    this.geometry.instanceCount = 0;

    this.material = new ShaderMaterial({
      uniforms: {
        uMap: { value: texture },
        uTime: { value: 0 },
        uCameraPosition: { value: new Vector3() },
        uFocusPosition: { value: new Vector3() },
        uVolume: { value: new Vector3(178, 58, 178) },
        uLocalVolume: { value: new Vector3(38, 27, 38) },
        uWindOffset: { value: new Vector2() },
        uIntensity: { value: 0 },
        uDensity: { value: 0 },
        uLocalPrecipitation: { value: 0 },
        uLocalDensityEnabled: { value: 0 },
        uCloudTime: { value: 0 },
        uCloudWindDirection: { value: new Vector2(1, 0) },
        uCloudCover: { value: 0 },
      },
      vertexShader: `
        uniform float uTime;
        uniform vec3 uCameraPosition;
        uniform vec3 uFocusPosition;
        uniform vec3 uVolume;
        uniform vec3 uLocalVolume;
        uniform vec2 uWindOffset;
        uniform float uIntensity;
        uniform float uDensity;
        uniform float uLocalPrecipitation;
        uniform float uLocalDensityEnabled;
        uniform float uCloudTime;
        uniform vec2 uCloudWindDirection;
        uniform float uCloudCover;
        attribute vec3 aSeed;
        attribute float aVariation;
        attribute float aFamily;
        attribute float aDensityRank;
        attribute float aLocalLayer;
        varying vec2 vUv;
        varying float vAlpha;

        ${WORLD_CLOUD_FIELD_GLSL}

        void main() {
          float localLayer = step(0.5, uLocalDensityEnabled) *
            step(0.5, aLocalLayer);
          float phase = aVariation * 6.28318530718;
          // Three stable physical families share one draw call. Classification
          // comes from an immutable seed, so a tracked flake never changes
          // size or fall behaviour as weather density changes.
          float largeFlake = 1.0 - step(0.095, aFamily);
          float powderFlake = step(0.66, aFamily);
          float mediumFlake = 1.0 - largeFlake - powderFlake;
          float fallSpeed = largeFlake * mix(0.3, 0.52, aVariation) +
            mediumFlake * mix(0.72, 1.28, aVariation) +
            powderFlake * mix(1.45, 2.7, aVariation);
          vec3 activeVolume = mix(uVolume, uLocalVolume, localLayer);
          vec3 activeAnchor = mix(uCameraPosition, uFocusPosition, localLayer);
          vec3 origin = activeAnchor - vec3(
            activeVolume.x * 0.5,
            activeVolume.y * 0.36,
            activeVolume.z * 0.5
          );
          float flutterRate = largeFlake * 0.34 +
            mediumFlake * 0.62 + powderFlake * 1.08;
          float flutterReach = largeFlake * 0.42 +
            mediumFlake * 0.29 + powderFlake * 0.62;
          vec3 flutter = vec3(
            sin(uTime * flutterRate + phase) +
              sin(uTime * flutterRate * 1.61 + phase * 1.71) * 0.22,
            0.0,
            cos(uTime * flutterRate * 0.83 + phase) +
              cos(uTime * flutterRate * 1.39 + phase * 1.33) * 0.22
          ) * flutterReach;
          float windResponse = largeFlake * 0.72 +
            mediumFlake * 1.0 + powderFlake * 1.42;
          vec3 displacement = vec3(
            uWindOffset.x * windResponse,
            -fallSpeed * uTime,
            uWindOffset.y * windResponse
          ) + flutter;
          // Subtracting and re-adding the moving origin makes positions stay
          // in world space until a flake crosses a volume boundary. The field
          // follows the camera without visibly dragging every flake with it.
          vec3 worldCentre = mod(
            aSeed * activeVolume + displacement - origin,
            activeVolume
          ) + origin;
          vec3 relative = (worldCentre - activeAnchor) /
            max(activeVolume, vec3(0.001));
          float generalEdgeFade = 1.0 - smoothstep(
            0.4,
            0.5,
            max(abs(relative.x), abs(relative.z))
          );
          // The close-density layer is wider overhead and gently narrows near
          // the actor. Only its spatial boundary is feathered; weather owns
          // its temporal appearance and disappearance.
          float localTaper = mix(
            0.33,
            0.5,
            smoothstep(-0.3, 0.5, relative.y)
          );
          float localEdgeFade = 1.0 - smoothstep(
            localTaper - 0.095,
            localTaper,
            length(relative.xz)
          );
          float edgeFade = mix(generalEdgeFade, localEdgeFade, localLayer);
          float verticalFade = smoothstep(-0.38, -0.24, relative.y) *
            (1.0 - smoothstep(0.52, 0.63, relative.y));
          // Density changes reveal the same deterministic flakes in the same
          // order. A soft threshold makes each one fade instead of vanishing
          // because CPU instanceCount changed between adjacent frames.
          float densityVisibility = 1.0 - smoothstep(
            uDensity - 0.035,
            uDensity + 0.018,
            aDensityRank
          );
          float size = (
            largeFlake * mix(0.16, 0.255, aVariation) +
            mediumFlake * mix(0.065, 0.13, aVariation) +
            powderFlake * mix(0.026, 0.065, aVariation)
          ) *
            mix(0.88, 1.18, uIntensity);
          float localCloudMask = smoothstep(
            0.035,
            0.2,
            icewayWorldCloudPrecipitation(
              worldCentre.xz,
              uCloudTime,
              uCloudWindDirection,
              uCloudCover
            )
          );
          float precipitationMask = mix(1.0, localCloudMask, localLayer);
          float layerIntensity = mix(
            uIntensity,
            uLocalPrecipitation,
            localLayer
          );
          vec3 cameraRight = vec3(
            viewMatrix[0][0], viewMatrix[1][0], viewMatrix[2][0]
          );
          vec3 cameraUp = vec3(
            viewMatrix[0][1], viewMatrix[1][1], viewMatrix[2][1]
          );
          vec3 worldPosition = worldCentre +
            cameraRight * position.x * size + cameraUp * position.y * size;
          gl_Position = projectionMatrix * viewMatrix *
            vec4(worldPosition, 1.0);
          vUv = uv;
          vAlpha = edgeFade * verticalFade *
            densityVisibility * mix(0.48, 0.96, aVariation) *
            smoothstep(0.01, 0.2, layerIntensity) * precipitationMask;
        }
      `,
      fragmentShader: `
        uniform sampler2D uMap;
        varying vec2 vUv;
        varying float vAlpha;

        void main() {
          vec4 flake = texture2D(uMap, vUv);
          float alpha = flake.a * vAlpha;
          if (alpha < 0.012) discard;
          gl_FragColor = vec4(flake.rgb, alpha);
          #include <tonemapping_fragment>
          #include <colorspace_fragment>
        }
      `,
      transparent: true,
      depthTest: true,
      depthWrite: false,
      side: DoubleSide,
      blending: NormalBlending,
      toneMapped: true,
    });
    this.material.name = 'GPU instanced snowfall material';
    this.mesh = new Mesh(this.geometry, this.material);
    this.mesh.name = 'GPU instanced OTS snowfall field';
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = 7;
    this.mesh.visible = false;
    scene.add(this.mesh);
  }

  public setLocallyVisible(visible: boolean): void {
    this.locallyVisible = visible;
    if (!visible) {
      this.activeCount = 0;
      this.generalActiveCount = 0;
      this.localDensityActiveCount = 0;
      this.geometry.instanceCount = 0;
      this.mesh.visible = false;
    }
  }

  /** Makes the otherwise weather-gated material eligible for renderer.compile. */
  public setShaderWarmupActive(active: boolean): void {
    this.shaderWarmupActive = active;
    if (active) {
      this.geometry.instanceCount = Math.max(1, this.geometry.instanceCount);
      this.mesh.visible = true;
    } else if (this.activeCount <= 0) {
      this.geometry.instanceCount = 0;
      this.mesh.visible = false;
    }
  }

  public setRuntimeBudgetMultiplier(multiplier: number): void {
    this.runtimeBudgetMultiplier = clamp(multiplier, 0.35, 1);
  }

  public setLocalDensityEnabled(enabled: boolean): void {
    this.localDensityEnabled = enabled;
    if (!enabled) this.localDensityActiveCount = 0;
  }

  public update(
    deltaSeconds: number,
    camera: Camera,
    windX: number,
    windZ: number,
    windStrength: number,
    visualRate: number,
    localPrecipitation: number,
    focus: Readonly<{ x: number; y?: number; z: number }>,
    cloudTime: number,
    cloudDirectionX: number,
    cloudDirectionZ: number,
    cloudCover: number,
    active: boolean,
  ): void {
    const delta = clamp(deltaSeconds, 0, 0.1);
    this.elapsed += delta;
    const windLength = Math.max(0.0001, Math.hypot(windX, windZ));
    const windSpeed = 0.35 + clamp(windStrength, 0, 2) * 2.35;
    this.windVelocity.set(
      windX / windLength * windSpeed,
      windZ / windLength * windSpeed,
    );
    // Integrate wind travel. Multiplying the *current* velocity by all elapsed
    // time caused every existing flake to teleport whenever a gust changed.
    this.windOffset.addScaledVector(this.windVelocity, delta);
    const counts = active && this.locallyVisible
      ? resolveGpuSnowfallCounts(
          visualRate,
          this.qualityMultiplier,
          this.runtimeBudgetMultiplier,
          this.localDensityEnabled,
        )
      : { general: 0, localDensity: 0, submitted: 0 };
    this.generalActiveCount = counts.general;
    this.localDensityActiveCount = counts.localDensity;
    this.activeCount = counts.submitted;
    // Density ranks are monotonic while position/behaviour seeds stay random.
    // This lets the draw itself stop at the active prefix instead of submitting
    // all 30k quads and discarding the inactive tail in the shader.
    this.geometry.instanceCount = this.activeCount > 0
      ? this.activeCount
      : this.shaderWarmupActive ? 1 : 0;
    this.mesh.visible = this.activeCount > 0 || this.shaderWarmupActive;
    if (!this.mesh.visible) return;
    this.material.uniforms.uTime!.value = this.elapsed;
    this.material.uniforms.uCameraPosition!.value.copy(camera.position);
    this.material.uniforms.uFocusPosition!.value.set(
      focus.x,
      focus.y ?? camera.position.y,
      focus.z,
    );
    this.material.uniforms.uWindOffset!.value.copy(this.windOffset);
    this.material.uniforms.uIntensity!.value = clamp(visualRate, 0, 1.28);
    this.material.uniforms.uDensity!.value = resolveGpuSnowflakeDensity(
      visualRate,
    );
    this.material.uniforms.uLocalPrecipitation!.value = clamp(
      localPrecipitation,
      0,
      1.35,
    );
    this.material.uniforms.uLocalDensityEnabled!.value =
      this.localDensityEnabled ? 1 : 0;
    this.material.uniforms.uCloudTime!.value = Math.max(0, cloudTime);
    this.material.uniforms.uCloudWindDirection!.value.set(
      cloudDirectionX,
      cloudDirectionZ,
    );
    this.material.uniforms.uCloudCover!.value = clamp(cloudCover, 0, 1);
  }

  public getActiveCount(): number {
    return this.activeCount;
  }

  public getActiveCounts(): GpuSnowfallCounts {
    return {
      general: this.generalActiveCount,
      localDensity: this.localDensityActiveCount,
      submitted: this.activeCount,
    };
  }

  public dispose(scene: Scene): void {
    scene.remove(this.mesh);
    this.geometry.dispose();
    this.material.dispose();
  }
}
