import { clamp, damp, hash2D, lerp } from '../utils/math';
import type {
  SnowEmergencyCityLayout,
  SnowEmergencyIntersection,
  SnowEmergencyRoadSegment,
} from './SnowEmergencyCityLayout';

export type SnowEmergencyVehicleType =
  | 'CAR'
  | 'BICYCLE'
  | 'SNOWMOBILE'
  | 'BUS'
  | 'TRUCK'
  | 'AMBULANCE'
  | 'GARBAGE_TRUCK';

export type SnowEmergencyDriverProfile =
  | 'CAUTIOUS'
  | 'COMMUTER'
  | 'IMPATIENT'
  | 'PROFESSIONAL'
  | 'EMERGENCY';

export type SnowEmergencySignalState = 'GREEN' | 'YELLOW' | 'RED';

export interface SnowEmergencyTrafficAgent {
  readonly id: number;
  readonly type: SnowEmergencyVehicleType;
  readonly profile: SnowEmergencyDriverProfile;
  edgeId: string;
  progress: number;
  lane: number;
  visualLane: number;
  speed: number;
  heading: number;
  visualHeading: number;
  waitingSeconds: number;
  turnCount: number;
  crashed: boolean;
  blockedBySnow: boolean;
  laneChanges: number;
}

export interface SnowEmergencyTrafficStats {
  readonly logicalAgents: number;
  readonly movingAgents: number;
  readonly waitingAgents: number;
  readonly snowBlockedAgents: number;
  readonly crashedAgents: number;
  readonly emergencyVehicles: number;
  readonly laneChanges: number;
  readonly completedSegments: number;
}

export interface SnowEmergencyTrafficStepContext {
  readonly sampleSnowDepth: (x: number, z: number) => number;
  readonly player?: Readonly<{
    x: number;
    z: number;
    radius: number;
  }>;
}

interface DirectedRoadEdge {
  readonly id: string;
  readonly road: SnowEmergencyRoadSegment;
  readonly from: SnowEmergencyIntersection;
  readonly to: SnowEmergencyIntersection;
  readonly dx: number;
  readonly dz: number;
  readonly heading: number;
}

const VEHICLE_LENGTH: Readonly<Record<SnowEmergencyVehicleType, number>> = {
  CAR: 3.8,
  BICYCLE: 1.55,
  SNOWMOBILE: 2.25,
  BUS: 9.6,
  TRUCK: 8.4,
  AMBULANCE: 5.4,
  GARBAGE_TRUCK: 7.2,
};

const VEHICLE_SPEED: Readonly<Record<SnowEmergencyVehicleType, number>> = {
  CAR: 1,
  BICYCLE: 0.48,
  SNOWMOBILE: 0.88,
  BUS: 0.72,
  TRUCK: 0.68,
  AMBULANCE: 1.08,
  GARBAGE_TRUCK: 0.62,
};

const VEHICLE_SNOW_TOLERANCE: Readonly<
  Record<SnowEmergencyVehicleType, number>
> = {
  CAR: 0.34,
  BICYCLE: 0.13,
  SNOWMOBILE: 1.35,
  BUS: 0.42,
  TRUCK: 0.52,
  AMBULANCE: 0.46,
  GARBAGE_TRUCK: 0.58,
};

const PROFILE_SPEED: Readonly<Record<SnowEmergencyDriverProfile, number>> = {
  CAUTIOUS: 0.78,
  COMMUTER: 0.94,
  IMPATIENT: 1.12,
  PROFESSIONAL: 0.86,
  EMERGENCY: 1.18,
};

const PROFILE_HEADWAY: Readonly<Record<SnowEmergencyDriverProfile, number>> = {
  CAUTIOUS: 2.1,
  COMMUTER: 1.5,
  IMPATIENT: 0.82,
  PROFESSIONAL: 1.8,
  EMERGENCY: 1.25,
};

const PROFILE_RISK: Readonly<Record<SnowEmergencyDriverProfile, number>> = {
  CAUTIOUS: 0.16,
  COMMUTER: 0.38,
  IMPATIENT: 0.82,
  PROFESSIONAL: 0.22,
  EMERGENCY: 0.44,
};

const vehicleTypeForIndex = (index: number): SnowEmergencyVehicleType => {
  const roll = hash2D(index, 17, 7701);
  if (roll < 0.58) return 'CAR';
  if (roll < 0.67) return 'BICYCLE';
  if (roll < 0.75) return 'SNOWMOBILE';
  if (roll < 0.83) return 'BUS';
  if (roll < 0.91) return 'TRUCK';
  if (roll < 0.96) return 'AMBULANCE';
  return 'GARBAGE_TRUCK';
};

const driverProfileFor = (
  type: SnowEmergencyVehicleType,
  index: number,
): SnowEmergencyDriverProfile => {
  if (type === 'AMBULANCE') return 'EMERGENCY';
  if (type === 'BUS' || type === 'TRUCK' || type === 'GARBAGE_TRUCK') {
    return 'PROFESSIONAL';
  }
  const roll = hash2D(index, 31, 1703);
  if (roll < 0.28) return 'CAUTIOUS';
  if (roll > 0.84) return 'IMPATIENT';
  return 'COMMUTER';
};

export class SnowEmergencyTrafficSimulation {
  private readonly intersections = new Map<
    string,
    SnowEmergencyIntersection
  >();
  private readonly edges = new Map<string, DirectedRoadEdge>();
  private readonly outgoing = new Map<string, DirectedRoadEdge[]>();
  private readonly agents: SnowEmergencyTrafficAgent[] = [];
  private simulationSeconds = 0;
  private tickIndex = 0;
  private laneChanges = 0;
  private completedSegments = 0;

  public constructor(
    private readonly layout: Readonly<SnowEmergencyCityLayout>,
    agentCount = 360,
  ) {
    for (const intersection of layout.intersections) {
      this.intersections.set(intersection.id, intersection);
    }
    for (const road of layout.roads) {
      const from = this.intersections.get(road.fromId)!;
      const to = this.intersections.get(road.toId)!;
      this.registerEdge(road, from, to, 'FORWARD');
      this.registerEdge(road, to, from, 'REVERSE');
    }
    const edgeList = [...this.edges.values()];
    const count = Math.max(0, Math.floor(agentCount));
    const spawnSlotsPerEdge = Math.max(1, Math.ceil(count / edgeList.length));
    for (let index = 0; index < count; index += 1) {
      const edge = edgeList[(index * 73) % edgeList.length]!;
      const edgeCycle = Math.floor(index / edgeList.length);
      const type = vehicleTypeForIndex(index);
      const laneCount = edge.road.laneCountPerDirection;
      const lane = Math.min(
        laneCount - 1,
        Math.floor(hash2D(index, 5, 233) * laneCount),
      );
      this.agents.push({
        id: index,
        type,
        profile: driverProfileFor(type, index),
        edgeId: edge.id,
        progress: clamp(
          (edgeCycle + 0.18 + hash2D(index, 7, 997) * 0.34) /
            spawnSlotsPerEdge,
          0.04,
          0.96,
        ),
        lane,
        visualLane: lane,
        speed: 0,
        heading: edge.heading,
        visualHeading: edge.heading,
        waitingSeconds: 0,
        turnCount: 0,
        crashed: false,
        blockedBySnow: false,
        laneChanges: 0,
      });
    }
  }

  public listAgents(): readonly Readonly<SnowEmergencyTrafficAgent>[] {
    return this.agents;
  }

  public getEdge(edgeId: string): Readonly<DirectedRoadEdge> | undefined {
    return this.edges.get(edgeId);
  }

  public signalState(
    intersectionId: string,
    approachAxis: 'X' | 'Z',
    atSeconds = this.simulationSeconds,
  ): SnowEmergencySignalState {
    const intersection = this.intersections.get(intersectionId);
    if (!intersection) return 'RED';
    const phase = (atSeconds + intersection.signalOffsetSeconds) % 36;
    if (approachAxis === 'X') {
      if (phase < 14) return 'GREEN';
      if (phase < 17) return 'YELLOW';
      return 'RED';
    }
    if (phase >= 18 && phase < 32) return 'GREEN';
    if (phase >= 32 && phase < 35) return 'YELLOW';
    return 'RED';
  }

  public step(
    deltaSeconds: number,
    context: Readonly<SnowEmergencyTrafficStepContext>,
  ): void {
    const delta = clamp(deltaSeconds, 0, 0.25);
    if (delta <= 0) return;
    this.simulationSeconds += delta;
    this.tickIndex += 1;

    const laneGroups = new Map<string, SnowEmergencyTrafficAgent[]>();
    for (const agent of this.agents) {
      if (agent.crashed) continue;
      const key = `${agent.edgeId}:${agent.lane}`;
      const group = laneGroups.get(key) ?? [];
      group.push(agent);
      laneGroups.set(key, group);
    }
    for (const group of laneGroups.values()) {
      group.sort((a, b) => a.progress - b.progress);
    }

    for (const agent of this.agents) {
      if (agent.crashed) continue;
      const edge = this.edges.get(agent.edgeId);
      if (!edge) continue;
      const position = this.positionOnEdge(agent, edge);
      const snowDepth = context.sampleSnowDepth(position.x, position.z);
      const snowTolerance = VEHICLE_SNOW_TOLERANCE[agent.type];
      agent.blockedBySnow = snowDepth > snowTolerance;
      const snowSpeed = clamp(
        1 - Math.max(0, snowDepth - 0.06) /
          Math.max(0.18, snowTolerance * 1.5),
        agent.type === 'SNOWMOBILE' ? 0.5 : 0.08,
        1,
      );
      const packedIce = clamp((0.18 - snowDepth) / 0.18, 0, 1) *
        (0.22 + hash2D(
          Math.round(position.x * 0.2),
          Math.round(position.z * 0.2),
          1129,
        ) * 0.34);
      const grip = clamp(
        1 - snowDepth * 0.72 - packedIce * 0.48,
        0.16,
        1,
      );
      let targetSpeed = edge.road.speedLimit *
        VEHICLE_SPEED[agent.type] *
        PROFILE_SPEED[agent.profile] *
        snowSpeed;
      if (agent.blockedBySnow && agent.type !== 'SNOWMOBILE') {
        targetSpeed = 0;
      }

      const distanceToSignal = (1 - agent.progress) * edge.road.length;
      const signal = this.signalState(edge.to.id, edge.road.axis);
      const obeysSignal = agent.profile !== 'EMERGENCY' ||
        hash2D(agent.id, agent.turnCount, 617) < 0.7;
      if (
        obeysSignal &&
        signal !== 'GREEN' &&
        distanceToSignal < Math.max(5.5, agent.speed * 2.2)
      ) targetSpeed = 0;

      const group = laneGroups.get(`${agent.edgeId}:${agent.lane}`) ?? [];
      const groupIndex = group.indexOf(agent);
      const lead = groupIndex >= 0 && groupIndex < group.length - 1
        ? group[groupIndex + 1]
        : undefined;
      let gap = Number.POSITIVE_INFINITY;
      if (lead) {
        gap = (lead.progress - agent.progress) * edge.road.length -
          VEHICLE_LENGTH[lead.type] * 0.5 -
          VEHICLE_LENGTH[agent.type] * 0.5;
        const desiredGap = 1.8 + agent.speed * PROFILE_HEADWAY[agent.profile];
        if (gap < desiredGap) targetSpeed = Math.min(targetSpeed, lead.speed);
        if (
          gap < desiredGap * 0.82 &&
          edge.road.laneCountPerDirection > 1
        ) {
          const alternateLane = agent.lane === 0 ? 1 : 0;
          if (this.laneIsClear(
            agent,
            alternateLane,
            laneGroups.get(`${agent.edgeId}:${alternateLane}`) ?? [],
            edge,
          )) {
            const previousGroupIndex = group.indexOf(agent);
            if (previousGroupIndex >= 0) group.splice(previousGroupIndex, 1);
            agent.lane = alternateLane;
            agent.laneChanges += 1;
            this.laneChanges += 1;
            const alternateKey = `${agent.edgeId}:${alternateLane}`;
            const alternateGroup = laneGroups.get(alternateKey) ?? [];
            alternateGroup.push(agent);
            alternateGroup.sort((a, b) => a.progress - b.progress);
            laneGroups.set(alternateKey, alternateGroup);
          }
        }
      }

      if (context.player) {
        const distanceToPlayer = Math.hypot(
          position.x - context.player.x,
          position.z - context.player.z,
        );
        if (distanceToPlayer < context.player.radius + 5.5) {
          targetSpeed = Math.min(targetSpeed, Math.max(0, distanceToPlayer - 3));
        }
      }

      const brakingDemand = lead && Number.isFinite(gap)
        ? clamp((agent.speed - lead.speed) / Math.max(0.1, gap), 0, 2)
        : 0;
      const crashRoll = hash2D(agent.id, this.tickIndex, 9011);
      if (
        lead &&
        gap < 0.35 &&
        agent.speed > 1.2 &&
        crashRoll < PROFILE_RISK[agent.profile] * (1 - grip) * 0.18
      ) {
        agent.crashed = true;
        agent.speed = 0;
        lead.speed *= 0.24;
        continue;
      }
      if (
        brakingDemand > grip * 1.6 &&
        crashRoll < PROFILE_RISK[agent.profile] * (1 - grip) * 0.025
      ) {
        agent.crashed = true;
        agent.speed = 0;
        continue;
      }

      const response = targetSpeed < agent.speed
        ? lerp(2.2, 5.8, grip)
        : lerp(0.55, 1.9, grip);
      agent.speed = damp(agent.speed, targetSpeed, response, delta);
      if (targetSpeed < 0.1) agent.waitingSeconds += delta;
      else agent.waitingSeconds = Math.max(0, agent.waitingSeconds - delta * 0.5);
      agent.progress += agent.speed * delta / edge.road.length;
      if (agent.progress >= 1) this.advanceAgent(agent, edge);
      agent.visualLane = damp(agent.visualLane, agent.lane, 3.8, delta);
      agent.visualHeading = this.dampAngle(
        agent.visualHeading,
        agent.heading,
        8,
        delta,
      );
    }
  }

  public getStats(): SnowEmergencyTrafficStats {
    let movingAgents = 0;
    let waitingAgents = 0;
    let snowBlockedAgents = 0;
    let crashedAgents = 0;
    let emergencyVehicles = 0;
    for (const agent of this.agents) {
      if (agent.speed > 0.45) movingAgents += 1;
      if (!agent.crashed && agent.speed <= 0.45) waitingAgents += 1;
      if (agent.blockedBySnow) snowBlockedAgents += 1;
      if (agent.crashed) crashedAgents += 1;
      if (agent.type === 'AMBULANCE') emergencyVehicles += 1;
    }
    return {
      logicalAgents: this.agents.length,
      movingAgents,
      waitingAgents,
      snowBlockedAgents,
      crashedAgents,
      emergencyVehicles,
      laneChanges: this.laneChanges,
      completedSegments: this.completedSegments,
    };
  }

  public positionForAgent(
    agent: Readonly<SnowEmergencyTrafficAgent>,
  ): Readonly<{ x: number; z: number; heading: number }> | undefined {
    const edge = this.edges.get(agent.edgeId);
    if (!edge) return undefined;
    return {
      ...this.positionOnEdge(agent, edge),
      heading: agent.visualHeading,
    };
  }

  private registerEdge(
    road: SnowEmergencyRoadSegment,
    from: SnowEmergencyIntersection,
    to: SnowEmergencyIntersection,
    direction: 'FORWARD' | 'REVERSE',
  ): void {
    const dx = (to.x - from.x) / road.length;
    const dz = (to.z - from.z) / road.length;
    const edge: DirectedRoadEdge = {
      id: `${road.id}:${direction}`,
      road,
      from,
      to,
      dx,
      dz,
      heading: Math.atan2(dx, dz),
    };
    this.edges.set(edge.id, edge);
    const outgoing = this.outgoing.get(from.id) ?? [];
    outgoing.push(edge);
    this.outgoing.set(from.id, outgoing);
  }

  private positionOnEdge(
    agent: Readonly<SnowEmergencyTrafficAgent>,
    edge: Readonly<DirectedRoadEdge>,
  ): Readonly<{ x: number; z: number }> {
    const laneWidth = edge.road.width /
      (edge.road.laneCountPerDirection * 2 + 0.5);
    const laneFromCenter = laneWidth * (0.72 + agent.visualLane);
    const rightX = edge.dz;
    const rightZ = -edge.dx;
    return {
      x: lerp(edge.from.x, edge.to.x, agent.progress) +
        rightX * laneFromCenter,
      z: lerp(edge.from.z, edge.to.z, agent.progress) +
        rightZ * laneFromCenter,
    };
  }

  private laneIsClear(
    agent: Readonly<SnowEmergencyTrafficAgent>,
    lane: number,
    candidates: readonly Readonly<SnowEmergencyTrafficAgent>[],
    edge: Readonly<DirectedRoadEdge>,
  ): boolean {
    return candidates.every((candidate) => {
      const distance = Math.abs(candidate.progress - agent.progress) *
        edge.road.length;
      return distance > 7 + Math.max(
        VEHICLE_LENGTH[agent.type],
        VEHICLE_LENGTH[candidate.type],
      );
    }) && lane >= 0 && lane < edge.road.laneCountPerDirection;
  }

  private advanceAgent(
    agent: SnowEmergencyTrafficAgent,
    previous: Readonly<DirectedRoadEdge>,
  ): void {
    const candidates = (this.outgoing.get(previous.to.id) ?? [])
      .filter((candidate) => candidate.to.id !== previous.from.id);
    const choices = candidates.length > 0
      ? candidates
      : this.outgoing.get(previous.to.id) ?? [];
    if (choices.length === 0) {
      agent.progress = 0.98;
      agent.speed = 0;
      return;
    }
    const choice = choices[
      Math.floor(
        hash2D(agent.id, agent.turnCount, 457) * choices.length,
      )
    ]!;
    const nextLane = Math.min(
      agent.lane,
      choice.road.laneCountPerDirection - 1,
    );
    const entryOccupied = this.agents.some((other) => {
      if (
        other === agent ||
        other.crashed ||
        other.edgeId !== choice.id ||
        other.lane !== nextLane
      ) return false;
      const clearance = (
        VEHICLE_LENGTH[agent.type] +
        VEHICLE_LENGTH[other.type] +
        2.5
      ) / choice.road.length;
      return other.progress < clearance;
    });
    if (entryOccupied) {
      agent.progress = 0.985;
      agent.speed = 0;
      return;
    }
    agent.edgeId = choice.id;
    agent.progress = Math.min(0.08, agent.progress - 1);
    agent.lane = nextLane;
    agent.heading = choice.heading;
    agent.turnCount += 1;
    this.completedSegments += 1;
  }

  private dampAngle(
    current: number,
    target: number,
    lambda: number,
    delta: number,
  ): number {
    const difference = Math.atan2(
      Math.sin(target - current),
      Math.cos(target - current),
    );
    return current + difference * (1 - Math.exp(-lambda * delta));
  }
}
