const panel = (
  id: string,
  label: string,
  horizontalArcDegrees: number,
  verticalArcDegrees: number,
  curvature: 'convex' | 'concave' = 'convex',
): ConstructionModuleDefinition => {
  const resolvedHorizontalArc =
    curvature === 'concave'
      ? -Math.abs(horizontalArcDegrees)
      : horizontalArcDegrees;
  const resolvedVerticalArc =
    curvature === 'concave'
      ? -Math.abs(verticalArcDegrees)
      : verticalArcDegrees;
  return {
  id,
  label,
  shortLabel:
    curvature === 'concave' &&
    horizontalArcDegrees > 0 &&
    verticalArcDegrees > 0
      ? `C H${horizontalArcDegrees} V${verticalArcDegrees}`
      : curvature === 'concave' && horizontalArcDegrees > 0
        ? `C H${horizontalArcDegrees}°`
        : curvature === 'concave' && verticalArcDegrees > 0
          ? `C V${verticalArcDegrees}°`
          : horizontalArcDegrees > 0 && verticalArcDegrees > 0
      ? `H${horizontalArcDegrees} V${verticalArcDegrees}`
      : horizontalArcDegrees > 0
        ? `H ${horizontalArcDegrees}°`
        : verticalArcDegrees > 0
          ? `V ${verticalArcDegrees}°`
          : 'STRAIGHT',
  description:
    curvature === 'concave'
      ? 'Inward-curving hull panel for recessed and hourglass forms.'
      : horizontalArcDegrees > 0 && verticalArcDegrees > 0
      ? 'Compound hull panel curving in both axes.'
      : horizontalArcDegrees > 0
        ? 'Hull panel with horizontal curvature.'
        : verticalArcDegrees > 0
          ? 'Hull panel with vertical tumblehome curvature.'
          : 'Straight paintable hull panel.',
  category: 'hull',
  mountMode: 'grid',
  canHostAttachments: true,
  footprint: { widthCells: 4, heightCells: 8, lengthCells: 1 },
  geometry: {
    kind: 'curved-panel',
    width: 1,
    height: 2,
    thickness: 0.16,
    horizontalArcDegrees: resolvedHorizontalArc,
    verticalArcDegrees: resolvedVerticalArc,
  },
  defaultMaterial: 'ice-blue',
  defaultSurface: 'painted-steel',
  decalSlots: [
    {
      id: 'outer-face',
      label: 'Outer face',
      position: { x: 0, y: 1, z: 0.09 },
      normal: { x: 0, y: 0, z: 1 },
      width: 0.72,
      height: 1.2,
    },
  ],
  sockets: hullPanelSockets(
    2,
    resolvedHorizontalArc,
    resolvedVerticalArc,
  ),
  };
};

