const modulesById = new Map(
  CONSTRUCTION_MODULES.map((definition) => [definition.id, definition]),
);

export const getConstructionModule = (
  id: string,
): ConstructionModuleDefinition | undefined => modulesById.get(id);

export const resolveConstructionModuleDefinition = (
  definition: Readonly<ConstructionModuleDefinition>,
  shape: Readonly<ConstructionShapeParameters> | undefined,
): ConstructionModuleDefinition => {
  if (
    !definition.shapeEditing ||
    definition.geometry.kind !== 'curved-panel' ||
    !shape
  ) {
    return definition as ConstructionModuleDefinition;
  }
  const horizontalArcDegrees = Math.max(
    -60,
    Math.min(60, shape.horizontalArcDegrees),
  );
  const verticalArcDegrees = Math.max(
    -60,
    Math.min(60, shape.verticalArcDegrees),
  );
  return {
    ...definition,
    geometry: {
      ...definition.geometry,
      profile: shape.profile,
      horizontalArcDegrees,
      verticalArcDegrees,
    },
    sockets: hullPanelSockets(
      definition.geometry.height,
      horizontalArcDegrees,
      verticalArcDegrees,
    ),
  };
};

export const getResolvedConstructionModule = (
  id: string,
  shape: Readonly<ConstructionShapeParameters> | undefined,
): ConstructionModuleDefinition | undefined => {
  const definition = getConstructionModule(id);
  return definition
    ? resolveConstructionModuleDefinition(definition, shape)
    : undefined;
};
