import {
  AddEquation,
  AdditiveBlending,
  BackSide,
  BufferGeometry,
  CircleGeometry,
  CustomBlending,
  DoubleSide,
  Float32BufferAttribute,
  Group,
  Mesh,
  MeshPhysicalMaterial,
  Object3D,
  OneFactor,
  PlaneGeometry,
  PointLight,
  Points,
  ReverseSubtractEquation,
  ShaderMaterial,
  SphereGeometry,
  SrcAlphaFactor,
  ZeroFactor,
  type Material,
  type Scene,
} from 'three';
import type { TerrainHeightSystem } from '../../land/TerrainHeightSystem';
import type { WorldAssetPlacementSystem } from '../../land/WorldAssetPlacementSystem';
import { smoothstep } from '../../utils/math';
import { WILDERNESS_SURVIVAL_REGION } from '../WildernessBiome';

const SHADOW_MONOLITH_PREFAB = 'TLW_SHADOW_MONOLITH_01';
const SHADOW_AURA_RADIUS = 8.4;

/**
 * Intentionally close to the default spawn and in the initial view. This is
 * a visual test landmark, not a permanent authored location.
 */
export const SHADOW_MONOLITH_TEST_POSITION = Object.freeze({
  x: -832,
  z: -250,
  heading: Math.atan2(
    WILDERNESS_SURVIVAL_REGION.spawnX + 832,
    WILDERNESS_SURVIVAL_REGION.spawnZ + 250,
  ),
});

export const shadowMonolithInfluenceAt = (x: number, z: number): number => {
  const distance = Math.hypot(
    x - SHADOW_MONOLITH_TEST_POSITION.x,
    z - SHADOW_MONOLITH_TEST_POSITION.z,
  );
  return 1 - smoothstep(SHADOW_AURA_RADIUS * 0.22, SHADOW_AURA_RADIUS, distance);
};

const subtractiveBlend = Object.freeze({
  blending: CustomBlending,
  blendEquation: ReverseSubtractEquation,
  blendSrc: SrcAlphaFactor,
  blendDst: OneFactor,
  // Preserve the destination alpha while subtracting only visible colour.
  blendEquationAlpha: AddEquation,
  blendSrcAlpha: ZeroFactor,
  blendDstAlpha: OneFactor,
});

const valueNoiseGlsl = `
  float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 345.45));
    p += dot(p, p + 34.345);
    return fract(p.x * p.y);
  }
  float noise21(vec2 p) {
    vec2 cell = floor(p);
    vec2 local = fract(p);
    local = local * local * (3.0 - 2.0 * local);
    float a = hash21(cell);
    float b = hash21(cell + vec2(1.0, 0.0));
    float c = hash21(cell + vec2(0.0, 1.0));
    float d = hash21(cell + vec2(1.0, 1.0));
    return mix(mix(a, b, local.x), mix(c, d, local.x), local.y);
  }
  float fbm(vec2 p) {
    float value = 0.0;
    value += noise21(p) * 0.58;
    value += noise21(p * 2.07 + 7.3) * 0.28;
    value += noise21(p * 4.13 - 3.8) * 0.14;
    return value;
  }
`;

/**
 * Detachable shadow-world visual experiment. The stone remains an asset-bank
 * prefab. Its shell is refractive black glass around nested animated energy
 * volumes. A negative point light still removes illumination from nearby PBR
 * surfaces while restrained violet and red sources leak out from the core.
 */
export class ShadowMonolithPrototype {
  private readonly root = new Group();
  private readonly effectRoot = new Group();
  private readonly darkLight = new PointLight(0xffffff, 0, 10.5, 1.72);
  private readonly violetCoreLight = new PointLight(0x8a24ff, 0, 7.5, 1.88);
  private readonly crimsonCoreLight = new PointLight(0xff173f, 0, 5.2, 2.05);
  private readonly glassMaterial = this.createBlackGlassMaterial();
  private readonly internalEnergyMaterials = [
    this.createInternalEnergyMaterial(0, 1),
    this.createInternalEnergyMaterial(2.17, 0.64),
  ] as const;
  private readonly innerDarknessMaterial = this.createInteriorVeilMaterial();
  private readonly groundStainMaterial = this.createGroundStainMaterial();
  private readonly fissureMaterial = this.createFissureMaterial();
  private readonly moteMaterial = this.createMoteMaterial();
  private readonly removeAssetBankListener: () => void;
  private readonly fissure: Mesh;
  private monolith?: Group;
  private ownedMonolithMaterials: Material[] = [];
  private active = false;
  private time = 0;

  public constructor(
    scene: Scene,
    private readonly terrain: TerrainHeightSystem,
    private readonly assetBank?: WorldAssetPlacementSystem,
  ) {
    this.root.name = 'The Long Winter · detachable shadow monolith prototype';
    this.effectRoot.name = 'Shadow monolith · reverse-radiant dark light';
    this.root.add(this.effectRoot);
    this.fissure = this.createEffects();
    this.rebuildMonolithVisual();
    this.removeAssetBankListener = this.assetBank?.addVisualListener(() =>
      this.rebuildMonolithVisual()) ?? (() => {});
    this.reanchor();

    scene.add(this.root);
    this.root.visible = false;
  }

  public setActive(active: boolean): void {
    this.active = active;
    this.root.visible = active;
    if (!active) {
      this.darkLight.intensity = 0;
      this.violetCoreLight.intensity = 0;
      this.crimsonCoreLight.intensity = 0;
    }
  }

  public canWalkAt(x: number, z: number, radius: number): boolean {
    if (!this.active) return true;
    const dx = x - SHADOW_MONOLITH_TEST_POSITION.x;
    const dz = z - SHADOW_MONOLITH_TEST_POSITION.z;
    const cosine = Math.cos(SHADOW_MONOLITH_TEST_POSITION.heading);
    const sine = Math.sin(SHADOW_MONOLITH_TEST_POSITION.heading);
    const localX = dx * cosine + dz * sine;
    const localZ = -dx * sine + dz * cosine;
    const radiusX = 1.08 + radius;
    const radiusZ = 0.82 + radius;
    return (localX * localX) / (radiusX * radiusX) +
      (localZ * localZ) / (radiusZ * radiusZ) >= 1;
  }

  public update(
    deltaSeconds: number,
    playerX: number,
    playerZ: number,
  ): void {
    if (!this.active) return;
    this.time += Math.max(0, deltaSeconds);
    const influence = shadowMonolithInfluenceAt(playerX, playerZ);
    const proximity = smoothstep(0.18, 0.94, influence);
    const slowPulse = 0.5 + Math.sin(this.time * 0.46) * 0.5;
    const uneasyPulse = 0.5 + Math.sin(this.time * 1.73 + Math.sin(this.time * 0.21)) * 0.5;

    for (const material of this.internalEnergyMaterials) {
      material.uniforms.uTime!.value = this.time;
      material.uniforms.uProximity!.value = proximity;
    }
    this.innerDarknessMaterial.uniforms.uTime!.value = this.time;
    this.innerDarknessMaterial.uniforms.uStrength!.value =
      smoothstep(0.72, 0.98, influence) * 0.2;
    this.groundStainMaterial.uniforms.uTime!.value = this.time;
    this.groundStainMaterial.uniforms.uStrength!.value =
      0.82 + proximity * 0.12;
    this.fissureMaterial.uniforms.uTime!.value = this.time;
    this.moteMaterial.uniforms.uTime!.value = this.time;
    this.moteMaterial.uniforms.uStrength!.value = 0.72 + proximity * 0.16;

    // Three.js forwards signed light intensities to PBR shaders. A restrained
    // negative value therefore removes nearby direct light with real distance
    // attenuation instead of drawing another translucent shell.
    this.darkLight.intensity = -(
      1.1 + slowPulse * 0.24 + uneasyPulse * 0.11 + proximity * 0.42
    );
    this.violetCoreLight.intensity =
      3.8 + slowPulse * 2.3 + uneasyPulse * 1.1 + proximity * 1.6;
    this.crimsonCoreLight.intensity =
      1.25 + (1 - slowPulse) * 0.9 + uneasyPulse * 0.72;
    this.fissure.scale.x = 0.96 + slowPulse * 0.055 + uneasyPulse * 0.018;
  }

  public reanchor(): void {
    const { x, z, heading } = SHADOW_MONOLITH_TEST_POSITION;
    this.root.position.set(x, this.terrain.sampleHeight(x, z), z);
    this.root.rotation.y = heading;
    this.root.userData.terrainAnchorX = x;
    this.root.userData.terrainAnchorZ = z;
  }

  public dispose(): void {
    this.removeAssetBankListener();
    this.disposeMonolithVisual();
    this.glassMaterial.dispose();
    for (const material of this.internalEnergyMaterials) material.dispose();
    this.innerDarknessMaterial.dispose();
    this.groundStainMaterial.dispose();
    this.fissureMaterial.dispose();
    this.moteMaterial.dispose();
    const geometries = new Set<BufferGeometry>();
    this.effectRoot.traverse((object) => {
      if (object instanceof Mesh || object instanceof Points) {
        geometries.add(object.geometry);
      }
    });
    for (const geometry of geometries) geometry.dispose();
    this.root.removeFromParent();
  }

  private createEffects(): Mesh {
    this.darkLight.name = 'Shadow monolith · negative PBR light';
    this.darkLight.position.set(0, 2.8, 0);
    this.darkLight.castShadow = false;
    this.violetCoreLight.name = 'Shadow monolith · violet core spill';
    this.violetCoreLight.position.set(0, 3.35, 0.12);
    this.violetCoreLight.castShadow = false;
    this.crimsonCoreLight.name = 'Shadow monolith · crimson core spill';
    this.crimsonCoreLight.position.set(0.18, 2.25, 0.46);
    this.crimsonCoreLight.castShadow = false;

    const stain = new Mesh(
      new CircleGeometry(SHADOW_AURA_RADIUS, 96),
      this.groundStainMaterial,
    );
    stain.name = 'Shadow monolith · crawling ground darkness';
    stain.rotation.x = -Math.PI / 2;
    stain.position.y = 0.045;
    stain.renderOrder = 16;
    stain.castShadow = false;
    stain.receiveShadow = false;

    // This volume never renders from outside. Only after the camera enters
    // the innermost field does it become a soft, borderless colourless veil.
    const innerDarkness = new Mesh(
      new SphereGeometry(4.25, 20, 12),
      this.innerDarknessMaterial,
    );
    innerDarkness.name = 'Shadow monolith · repulsion proximity veil';
    innerDarkness.position.y = 2.55;
    innerDarkness.renderOrder = 20;
    innerDarkness.castShadow = false;
    innerDarkness.receiveShadow = false;

    const motes = new Points(this.createMoteGeometry(), this.moteMaterial);
    motes.name = 'Shadow monolith · inward-falling shadow motes';
    motes.position.y = 0.12;
    motes.renderOrder = 21;
    motes.frustumCulled = false;

    const fissure = new Mesh(
      new PlaneGeometry(1.24, 4.9, 1, 1),
      this.fissureMaterial,
    );
    fissure.name = 'Shadow monolith · moving void fissure';
    fissure.position.set(0, 3.25, 0.825);
    fissure.renderOrder = 22;
    fissure.castShadow = false;
    fissure.receiveShadow = false;

    this.effectRoot.add(
      this.darkLight,
      this.violetCoreLight,
      this.crimsonCoreLight,
      stain,
      innerDarkness,
      motes,
      fissure,
    );
    return fissure;
  }

  private createMoteGeometry(): BufferGeometry {
    const count = 88;
    const positions = new Float32Array(count * 3);
    const seeds = new Float32Array(count * 4);
    const pseudo = (index: number, multiplier: number): number => {
      const value = Math.sin((index + 1) * multiplier) * 43758.5453123;
      return value - Math.floor(value);
    };
    for (let index = 0; index < count; index += 1) {
      const offset = index * 4;
      seeds[offset] = pseudo(index, 12.9898) * Math.PI * 2;
      seeds[offset + 1] = pseudo(index, 78.233);
      seeds[offset + 2] = 2.8 + pseudo(index, 39.425) * 5.8;
      seeds[offset + 3] = 0.035 + pseudo(index, 93.117) * 0.046;
    }
    const geometry = new BufferGeometry();
    geometry.setAttribute('position', new Float32BufferAttribute(positions, 3));
    geometry.setAttribute('aShadowSeed', new Float32BufferAttribute(seeds, 4));
    return geometry;
  }

  private rebuildMonolithVisual(): void {
    this.disposeMonolithVisual();
    const instance = this.assetBank?.createRuntimeInstance(SHADOW_MONOLITH_PREFAB);
    if (!instance) return;
    instance.name = 'Shadow monolith · asset-bank runtime';
    const glassMeshes: Mesh[] = [];
    instance.traverse((object: Object3D) => {
      if (!(object instanceof Mesh)) return;
      if (
        object.name === 'shadow-monolith-stone' ||
        object.name === 'shadow-monolith-crown' ||
        object.name === 'shadow-monolith-foot'
      ) {
        object.material = this.glassMaterial;
        object.renderOrder = 30;
        object.castShadow = true;
        object.receiveShadow = true;
        glassMeshes.push(object);
        return;
      }
      const cloned = Array.isArray(object.material)
        ? object.material.map((material) => material.clone())
        : object.material.clone();
      object.material = cloned;
      if (Array.isArray(cloned)) this.ownedMonolithMaterials.push(...cloned);
      else this.ownedMonolithMaterials.push(cloned);
    });
    for (const source of glassMeshes) {
      for (const [layer, material] of this.internalEnergyMaterials.entries()) {
        const energy = new Mesh(source.geometry, material);
        energy.name = `Shadow monolith · internal plasma ${layer + 1}`;
        energy.position.copy(source.position);
        energy.quaternion.copy(source.quaternion);
        energy.scale.copy(source.scale).multiplyScalar(layer === 0 ? 0.78 : 0.57);
        energy.renderOrder = 27 + layer;
        energy.castShadow = false;
        energy.receiveShadow = false;
        instance.add(energy);
      }
    }
    this.monolith = instance;
    this.root.add(instance);
  }

  private disposeMonolithVisual(): void {
    this.monolith?.removeFromParent();
    this.monolith = undefined;
    for (const material of this.ownedMonolithMaterials) material.dispose();
    this.ownedMonolithMaterials = [];
  }

  private createBlackGlassMaterial(): MeshPhysicalMaterial {
    return new MeshPhysicalMaterial({
      name: 'The Long Winter refractive black obsidian glass',
      color: 0x08040d,
      emissive: 0x120019,
      emissiveIntensity: 0.18,
      metalness: 0.04,
      roughness: 0.12,
      transmission: 0.58,
      opacity: 0.84,
      transparent: true,
      ior: 1.68,
      thickness: 1.42,
      attenuationColor: 0x26051f,
      attenuationDistance: 1.18,
      clearcoat: 0.92,
      clearcoatRoughness: 0.1,
      specularIntensity: 0.86,
      specularColor: 0xb878cf,
      side: DoubleSide,
      depthWrite: false,
    });
  }

  private createInternalEnergyMaterial(
    phase: number,
    strength: number,
  ): ShaderMaterial {
    return new ShaderMaterial({
      name: 'The Long Winter coiling violet-crimson monolith core',
      uniforms: {
        uTime: { value: 0 },
        uPhase: { value: phase },
        uStrength: { value: strength },
        uProximity: { value: 0 },
      },
      vertexShader: `
        varying vec3 vLocalPosition;
        varying vec3 vViewNormal;
        varying vec3 vViewDirection;
        void main() {
          vLocalPosition = position;
          vViewNormal = normalize(normalMatrix * normal);
          vec4 viewPosition = modelViewMatrix * vec4(position, 1.0);
          vViewDirection = -viewPosition.xyz;
          gl_Position = projectionMatrix * viewPosition;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform float uPhase;
        uniform float uStrength;
        uniform float uProximity;
        varying vec3 vLocalPosition;
        varying vec3 vViewNormal;
        varying vec3 vViewDirection;
        ${valueNoiseGlsl}
        void main() {
          vec3 p = vLocalPosition;
          float angle = atan(p.z, p.x);
          float height = p.y;
          float time = uTime * 0.34 + uPhase;
          float broadFlow = fbm(vec2(
            angle * 1.3 + time * 0.16,
            height * 2.7 - time * 0.31
          ));
          float foldedFlow = fbm(vec2(
            height * 4.2 + broadFlow * 1.8,
            angle * 2.1 - time * 0.22
          ));

          float coilA = 1.0 - smoothstep(
            0.08,
            0.43,
            abs(sin(angle * 2.25 + height * 8.2 - time * 1.25 + broadFlow * 3.4))
          );
          float coilB = 1.0 - smoothstep(
            0.045,
            0.29,
            abs(sin(-angle * 3.1 + height * 11.4 + time * 0.83 + foldedFlow * 2.7))
          );
          float emberKnots = smoothstep(0.61, 0.88, foldedFlow) *
            (0.55 + 0.45 * sin(height * 18.0 - time * 2.1));
          float fresnel = pow(
            1.0 - abs(dot(normalize(vViewNormal), normalize(vViewDirection))),
            1.7
          );
          float breath = 0.84 + sin(uTime * 0.48 + broadFlow * 2.2 + uPhase) * 0.13;
          float energy = coilA * 0.66 + coilB * 0.46 + max(0.0, emberKnots) * 0.31;
          energy *= mix(0.64, 1.08, foldedFlow) * breath;

          vec3 deepPurple = vec3(0.24, 0.008, 0.37);
          vec3 hotViolet = vec3(0.67, 0.045, 1.0);
          vec3 crimson = vec3(1.0, 0.018, 0.12);
          float colourFlow = 0.5 + 0.5 * sin(
            angle * 1.7 - height * 5.4 + time * 0.92 + broadFlow * 4.0
          );
          vec3 colour = mix(deepPurple, hotViolet, smoothstep(0.08, 0.66, colourFlow));
          colour = mix(colour, crimson, smoothstep(0.7, 1.0, colourFlow) * (0.48 + coilB * 0.35));
          float alpha = energy * (0.14 + fresnel * 0.2) *
            uStrength * (1.0 + uProximity * 0.14);
          if (alpha < 0.008) discard;
          gl_FragColor = vec4(colour * (0.72 + energy * 0.78), min(0.72, alpha));
        }
      `,
      transparent: true,
      depthTest: true,
      depthWrite: false,
      side: DoubleSide,
      blending: AdditiveBlending,
      toneMapped: false,
    });
  }

  private createInteriorVeilMaterial(): ShaderMaterial {
    return new ShaderMaterial({
      name: 'The Long Winter borderless shadow proximity veil',
      uniforms: {
        uTime: { value: 0 },
        uStrength: { value: 0 },
      },
      vertexShader: `
        varying vec3 vWorldPosition;
        void main() {
          vec4 worldPosition = modelMatrix * vec4(position, 1.0);
          vWorldPosition = worldPosition.xyz;
          gl_Position = projectionMatrix * viewMatrix * worldPosition;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform float uStrength;
        varying vec3 vWorldPosition;
        ${valueNoiseGlsl}
        void main() {
          float drift = fbm(vWorldPosition.xz * 0.42 + vec2(uTime * 0.035, 0.0));
          float alpha = uStrength * mix(0.72, 1.0, drift);
          gl_FragColor = vec4(vec3(0.001, 0.002, 0.006), alpha);
        }
      `,
      transparent: true,
      depthTest: false,
      depthWrite: false,
      side: BackSide,
      toneMapped: false,
    });
  }

  private createGroundStainMaterial(): ShaderMaterial {
    return new ShaderMaterial({
      name: 'The Long Winter crawling reverse-subtractive ground darkness',
      uniforms: {
        uTime: { value: 0 },
        uStrength: { value: 0.82 },
      },
      vertexShader: `
        varying vec2 vUv;
        void main() {
          vUv = uv;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform float uStrength;
        varying vec2 vUv;
        ${valueNoiseGlsl}
        void main() {
          vec2 p = (vUv - 0.5) * 2.0;
          float radius = length(p);
          float angle = atan(p.y, p.x);
          float radialTaper = smoothstep(0.03, 0.98, radius);
          float noise = fbm(vec2(
            angle * 1.24 + uTime * 0.009,
            radius * 3.7 - uTime * 0.026
          ));
          float warpedAngle = angle
            + (noise - 0.5) * mix(0.24, 0.055, radialTaper)
            + sin(angle * 2.0 + uTime * 0.04) * 0.022;

          // These are shadow roots, not cones: low exponents make them broad
          // beside the monolith; rising exponents taper them into long tips.
          float tendrilA = pow(
            abs(cos(warpedAngle * 3.0 + 0.43)),
            mix(5.0, 104.0, radialTaper)
          );
          float tendrilB = pow(
            abs(cos(warpedAngle * 5.0 - 0.81)),
            mix(9.0, 152.0, radialTaper)
          );
          float tendrilC = pow(
            abs(cos(warpedAngle * 8.0 + 1.31)),
            mix(18.0, 212.0, radialTaper)
          );
          float sectorA = floor((warpedAngle + 3.14159265) * 0.95492966);
          float sectorB = floor((warpedAngle + 3.14159265) * 1.59154943);
          float reachA = 0.68 + hash21(vec2(sectorA, 41.7)) * 0.29
            + sin(uTime * 0.07 + sectorA) * 0.018;
          float reachB = 0.48 + hash21(vec2(sectorB, 63.2)) * 0.39
            + sin(uTime * 0.09 + sectorB * 1.7) * 0.016;
          float lengthA = 1.0 - smoothstep(reachA - 0.17, reachA, radius);
          float lengthB = 1.0 - smoothstep(reachB - 0.15, reachB, radius);
          float lengthC = 1.0 - smoothstep(0.43 + noise * 0.16, 0.67 + noise * 0.19, radius);
          float tendrils = (
            tendrilA * lengthA * 0.86
            + tendrilB * lengthB * 0.53
            + tendrilC * lengthC * 0.22
          ) * (1.0 - smoothstep(0.9, 1.02, radius));

          float irregularReach = 0.39 + noise * 0.18;
          float stain = 1.0 - smoothstep(irregularReach - 0.14, irregularReach, radius);
          float inwardRipples = pow(
            max(0.0, sin(radius * 42.0 + noise * 5.0 + uTime * 0.72)),
            13.0
          ) * (1.0 - smoothstep(0.05, 0.72, radius));
          float centre = 1.0 - smoothstep(0.04, 0.48, radius);
          float alpha = (
            stain * 0.09
            + tendrils * 0.205
            + inwardRipples * 0.045
            + centre * 0.085
          )
            * uStrength;
          if (alpha < 0.004) discard;
          gl_FragColor = vec4(vec3(0.94), alpha);
        }
      `,
      transparent: true,
      depthTest: true,
      depthWrite: false,
      side: DoubleSide,
      polygonOffset: true,
      polygonOffsetFactor: -2,
      polygonOffsetUnits: -2,
      ...subtractiveBlend,
      toneMapped: false,
    });
  }

  private createFissureMaterial(): ShaderMaterial {
    return new ShaderMaterial({
      name: 'The Long Winter inward-flowing void fissure',
      uniforms: { uTime: { value: 0 } },
      vertexShader: `
        varying vec2 vUv;
        void main() {
          vUv = uv;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        varying vec2 vUv;
        ${valueNoiseGlsl}
        void main() {
          vec2 p = (vUv - 0.5) * vec2(2.0, 1.0);
          float flow = fbm(vec2(vUv.y * 5.0 - uTime * 0.16, uTime * 0.035));
          p.x += sin(vUv.y * 19.0 + uTime * 0.68) * 0.065 + (flow - 0.5) * 0.09;
          float distanceToCore = abs(p.x) + pow(abs(p.y), 2.8) * 0.21;
          float core = 1.0 - smoothstep(0.035, 0.19, distanceToCore);
          float rim = (1.0 - smoothstep(0.18, 0.39, distanceToCore)) - core;
          float inward = 0.62 + 0.38 * sin(vUv.y * 34.0 + uTime * 1.42);
          float alpha = core * (0.94 + inward * 0.04) + rim * 0.42;
          if (alpha < 0.01) discard;
          vec3 colour = mix(vec3(0.001, 0.001, 0.004), vec3(0.06, 0.1, 0.22), rim);
          gl_FragColor = vec4(colour, alpha);
        }
      `,
      transparent: true,
      depthTest: true,
      depthWrite: false,
      side: DoubleSide,
      toneMapped: false,
    });
  }

  private createMoteMaterial(): ShaderMaterial {
    return new ShaderMaterial({
      name: 'The Long Winter inward-falling shadow mote field',
      uniforms: {
        uTime: { value: 0 },
        uStrength: { value: 0.72 },
      },
      vertexShader: `
        uniform float uTime;
        attribute vec4 aShadowSeed;
        varying float vLife;
        void main() {
          float life = fract(aShadowSeed.y + uTime * aShadowSeed.w);
          float eased = life * life * (3.0 - 2.0 * life);
          float radius = mix(aShadowSeed.z, 0.22, eased);
          float angle = aShadowSeed.x + eased * 2.4 + sin(uTime * 0.18 + aShadowSeed.x) * 0.28;
          float height = mix(0.18 + mod(aShadowSeed.z, 1.8), 2.6, eased)
            + sin(angle * 2.0 + uTime * 0.7) * 0.16;
          vec3 local = vec3(cos(angle) * radius, height, sin(angle) * radius);
          vec4 viewPosition = modelViewMatrix * vec4(local, 1.0);
          gl_Position = projectionMatrix * viewPosition;
          gl_PointSize = mix(2.2, 6.2, sin(aShadowSeed.x * 4.7) * 0.5 + 0.5);
          vLife = smoothstep(0.0, 0.12, life) * (1.0 - smoothstep(0.78, 1.0, life));
        }
      `,
      fragmentShader: `
        uniform float uStrength;
        varying float vLife;
        void main() {
          vec2 p = gl_PointCoord - 0.5;
          float core = 1.0 - smoothstep(0.08, 0.5, length(p));
          float alpha = core * vLife * uStrength * 0.34;
          if (alpha < 0.008) discard;
          gl_FragColor = vec4(vec3(0.94), alpha);
        }
      `,
      transparent: true,
      depthTest: true,
      depthWrite: false,
      ...subtractiveBlend,
      toneMapped: false,
    });
  }
}
