import type { OceanConditionState } from './OceanConditionSystem';
import type {
  OceanBathymetryField,
  OceanBathymetrySample,
} from './OceanBathymetry';

export interface OceanSurfaceSample {
  height: number;
  normalX: number;
  normalY: number;
  normalZ: number;
  displacementX?: number;
  displacementZ?: number;
  curvature?: number;
  compression?: number;
  crestPotential?: number;
}

export interface OceanCurrentSample {
  x: number;
  z: number;
  angularVelocity: number;
}

export interface OceanEnvironmentSample {
  depth: number;
  seaState: number;
  windX: number;
  windZ: number;
  windStrength: number;
  waveExposure: number;
}

export interface OceanWave {
  directionX: number;
  directionZ: number;
  amplitude: number;
  wavelength: number;
  temporalFrequency: number;
  phase: number;
  choppiness: number;
  crestWeight: number;
}

export const OCEAN_SEA_LEVEL = -0.055;

export const OCEAN_MACRO_WAVE_TUNING = Object.freeze({
  regionalBase: 0.3,
  regionalSeaStateGain: 0.9,
  minimumExposure: 0.4,
  exposureStart: 0.08,
  exposureEnd: 0.92,
  swellBase: 0.46,
  swellGain: 0.54,
  transientSwellScale: 0.34,
  currentDirectionWeight: 5,
  directionOffsetScale: 0.35,
});

const OCEAN_SHOALS = [
  { x: -20.8, z: 8.4, radius: 8.4, influence: 0.48 },
  { x: 16.8, z: -10.9, radius: 8.1, influence: 0.44 },
  { x: 18.5, z: 10.8, radius: 8.2, influence: 0.46 },
  { x: 0.8, z: -2.6, radius: 5.9, influence: 0.34 },
] as const;

export const OCEAN_WAVES: readonly OceanWave[] = [
  {
    directionX: 1,
    directionZ: 0,
    amplitude: 0.072,
    wavelength: 11.8,
    temporalFrequency: 0.62,
    phase: 0.2,
    choppiness: 0.78,
    crestWeight: 1,
  },
  {
    directionX: 0.9135,
    directionZ: 0.4067,
    amplitude: 0.048,
    wavelength: 7.6,
    temporalFrequency: 0.82,
    phase: 1.9,
    choppiness: 0.64,
    crestWeight: 0.62,
  },
  {
    directionX: -0.225,
    directionZ: 0.9744,
    amplitude: 0.018,
    wavelength: 4.8,
    temporalFrequency: 1.18,
    phase: 4.1,
    choppiness: 0.28,
    crestWeight: 0.16,
  },
] as const;

export const OCEAN_SWELL_WAVES: readonly OceanWave[] = [
  {
    directionX: 0.9848,
    directionZ: -0.1736,
    amplitude: 0.105,
    wavelength: 30,
    temporalFrequency: 0.31,
    phase: 2.4,
    choppiness: 0.84,
    crestWeight: 0,
  },
] as const;

const TAU = Math.PI * 2;
const clamp01 = (value: number): number =>
  Math.max(0, Math.min(1, value));
const smoothstep01 = (value: number): number => {
  const clamped = clamp01(value);
  return clamped * clamped * (3 - 2 * clamped);
};

export interface OceanWaveBasis {
  cosine: number;
  sine: number;
}

export const resolveOceanWaveExposureScale = (
  waveExposure: number,
): number => {
  const range = Math.max(
    0.0001,
    OCEAN_MACRO_WAVE_TUNING.exposureEnd -
      OCEAN_MACRO_WAVE_TUNING.exposureStart,
  );
  const normalized =
    (waveExposure - OCEAN_MACRO_WAVE_TUNING.exposureStart) / range;
  return (
    OCEAN_MACRO_WAVE_TUNING.minimumExposure +
    (1 - OCEAN_MACRO_WAVE_TUNING.minimumExposure) *
      smoothstep01(normalized)
  );
};

export const resolveOceanMacroAmplitudeScale = (
  seaState: number,
  waveExposure: number,
): number =>
  (
    OCEAN_MACRO_WAVE_TUNING.regionalBase +
    clamp01(seaState) *
      OCEAN_MACRO_WAVE_TUNING.regionalSeaStateGain
  ) *
  resolveOceanWaveExposureScale(waveExposure);

export const resolveOceanWaveBasis = (
  windX: number,
  windZ: number,
  currentX: number,
  currentZ: number,
  directionOffset: number,
): OceanWaveBasis => {
  const dominantX =
    windX +
    currentX * OCEAN_MACRO_WAVE_TUNING.currentDirectionWeight;
  const dominantZ =
    windZ +
    currentZ * OCEAN_MACRO_WAVE_TUNING.currentDirectionWeight;
  const dominantLength = Math.max(
    0.0001,
    Math.hypot(dominantX, dominantZ),
  );
  const normalizedDominantX = dominantX / dominantLength;
  const normalizedDominantZ = dominantZ / dominantLength;
  const primary = OCEAN_WAVES[0]!;
  const baseCosine =
    primary.directionX * normalizedDominantX +
    primary.directionZ * normalizedDominantZ;
  const baseSine =
    primary.directionX * normalizedDominantZ -
    primary.directionZ * normalizedDominantX;
  const offset =
    directionOffset *
    OCEAN_MACRO_WAVE_TUNING.directionOffsetScale;
  const offsetCosine = Math.cos(offset);
  const offsetSine = Math.sin(offset);
  return {
    cosine:
      baseCosine * offsetCosine -
      baseSine * offsetSine,
    sine:
      baseSine * offsetCosine +
      baseCosine * offsetSine,
  };
};

export class OceanField {
  private condition?: Readonly<OceanConditionState>;
  private bathymetry?: OceanBathymetryField;
  private transientSwellStrength = 0;
  private readonly surfaceEnvironment: OceanEnvironmentSample = {
    depth: 0.5,
    seaState: 0.5,
    windX: 1,
    windZ: 0,
    windStrength: 0.5,
    waveExposure: 1,
  };
  private readonly surfaceCurrent: OceanCurrentSample = {
    x: 0,
    z: 0,
    angularVelocity: 0,
  };
  private readonly surfaceBathymetry: OceanBathymetrySample = {
    depth: 0.5,
    shoreDistance: 1,
    waveExposure: 1,
    authoredOverride: 0,
  };

  public setBathymetryField(
    bathymetry: OceanBathymetryField,
  ): void {
    this.bathymetry = bathymetry;
  }

  public setTransientSwellStrength(strength: number): void {
    this.transientSwellStrength = Math.max(
      0,
      Math.min(1.5, strength),
    );
  }

  public resolveSwellStrength(baseStrength: number): number {
    return Math.max(
      0,
      Math.min(
        1.6,
        baseStrength +
          this.transientSwellStrength *
            OCEAN_MACRO_WAVE_TUNING.transientSwellScale,
      ),
    );
  }

  public setConditionState(
    condition: Readonly<OceanConditionState>,
  ): void {
    this.condition = condition;
  }

  public sampleEnvironment(
    x: number,
    z: number,
    time: number,
    target: OceanEnvironmentSample = {
      depth: 0.5,
      seaState: 0.5,
      windX: 1,
      windZ: 0,
      windStrength: 0.5,
      waveExposure: 1,
    },
  ): OceanEnvironmentSample {
    const motionTime = this.condition?.motionTime ?? time;
    let depth =
      0.64 +
      Math.sin(x * 0.067 + z * 0.021 + 0.8) * 0.13 +
      Math.cos(z * 0.074 - x * 0.018 - 1.1) * 0.12 +
      Math.sin((x - z) * 0.031 + 2.4) * 0.07;
    for (const shoal of OCEAN_SHOALS) {
      const distanceSquared =
        (x - shoal.x) * (x - shoal.x) +
        (z - shoal.z) * (z - shoal.z);
      depth -=
        Math.exp(-distanceSquared / (shoal.radius * shoal.radius)) *
        shoal.influence;
    }

    const weatherFront =
      Math.sin(x * 0.043 + z * 0.027 + motionTime * 0.006 + 0.4);
    const crossWeather =
      Math.cos(z * 0.061 - x * 0.019 - motionTime * 0.004 - 1.3);
    const baseWindStrength = clamp01(
      0.48 + weatherFront * 0.3 + crossWeather * 0.17,
    );
    const baseSeaState = smoothstep01(
      0.08 +
      baseWindStrength * 0.82 +
      Math.sin((x + z) * 0.025 - 0.7) * 0.1,
    );
    const weatherWindMultiplier =
      this.condition?.weatherWindMultiplier ?? 1;
    const windStrength = Math.min(
      1.4,
      baseWindStrength * weatherWindMultiplier,
    );
    const seaState = clamp01(
      baseSeaState * (0.82 + weatherWindMultiplier * 0.18),
    );
    const windAngle =
      0.72 +
      Math.sin(z * 0.026 + motionTime * 0.003) * 0.34 +
      Math.cos(x * 0.022 - motionTime * 0.002) * 0.2;

    target.depth = clamp01(depth);
    target.seaState = seaState;
    target.windX = Math.cos(windAngle);
    target.windZ = Math.sin(windAngle);
    target.windStrength = windStrength;
    target.waveExposure =
      this.bathymetry?.sampleWorld(
        x,
        z,
        this.surfaceBathymetry,
      ).waveExposure ?? 1;
    return target;
  }

  public sampleSurface(
    x: number,
    z: number,
    time: number,
    amplitudeScale = 1,
    target: OceanSurfaceSample = {
      height: OCEAN_SEA_LEVEL,
      normalX: 0,
      normalY: 1,
      normalZ: 0,
      displacementX: 0,
      displacementZ: 0,
      curvature: 0,
      compression: 0,
      crestPotential: 0,
    },
  ): OceanSurfaceSample {
    const motionTime = this.condition?.motionTime ?? time;
    const waveScale = this.condition?.waveScale ?? 1;
    const swellStrength = this.resolveSwellStrength(
      this.condition?.swellStrength ?? 0,
    );
    const conditionDirectionOffset =
      this.condition?.directionOffset ?? 0;
    const environment = this.sampleEnvironment(
      x,
      z,
      motionTime,
      this.surfaceEnvironment,
    );
    const current = this.sampleCurrent(
      x,
      z,
      motionTime,
      this.surfaceCurrent,
    );
    const waveBasis = resolveOceanWaveBasis(
      environment.windX,
      environment.windZ,
      current.x,
      current.z,
      conditionDirectionOffset,
    );
    const localAmplitudeScale =
      amplitudeScale *
      resolveOceanMacroAmplitudeScale(
        environment.seaState,
        environment.waveExposure,
      ) *
      waveScale;
    let height = OCEAN_SEA_LEVEL;
    let gradientX = 0;
    let gradientZ = 0;
    let displacementX = 0;
    let displacementZ = 0;
    let horizontalDerivativeXX = 0;
    let horizontalDerivativeXZ = 0;
    let horizontalDerivativeZX = 0;
    let horizontalDerivativeZZ = 0;
    let curvature = 0;
    let crestPotential = 0;
    const directionCosine = waveBasis.cosine;
    const directionSine = waveBasis.sine;

    const accumulateWave = (
      wave: OceanWave,
      waveAmplitudeScale = 1,
    ): void => {
      const directionX =
        wave.directionX * directionCosine -
        wave.directionZ * directionSine;
      const directionZ =
        wave.directionX * directionSine +
        wave.directionZ * directionCosine;
      const spatialFrequency = TAU / wave.wavelength;
      const phase =
        spatialFrequency *
          (directionX * x + directionZ * z) +
        wave.temporalFrequency * motionTime +
        wave.phase;
      const amplitude =
        wave.amplitude *
        localAmplitudeScale *
        waveAmplitudeScale;
      const spatialSine = Math.sin(phase);
      const cosine = Math.cos(phase);
      height += amplitude * spatialSine;
      gradientX +=
        amplitude * cosine * spatialFrequency * directionX;
      gradientZ +=
        amplitude * cosine * spatialFrequency * directionZ;
      const horizontalAmplitude =
        amplitude * wave.choppiness;
      displacementX +=
        directionX * horizontalAmplitude * cosine;
      displacementZ +=
        directionZ * horizontalAmplitude * cosine;
      const horizontalDerivative =
        -horizontalAmplitude *
        spatialFrequency *
        spatialSine;
      horizontalDerivativeXX +=
        horizontalDerivative * directionX * directionX;
      horizontalDerivativeXZ +=
        horizontalDerivative * directionX * directionZ;
      horizontalDerivativeZX +=
        horizontalDerivative * directionZ * directionX;
      horizontalDerivativeZZ +=
        horizontalDerivative * directionZ * directionZ;
      curvature +=
        amplitude *
        spatialFrequency *
        spatialFrequency *
        spatialSine;
      const componentCrest = smoothstep01(
        (spatialSine - 0.58) / 0.4,
      ) * wave.crestWeight;
      crestPotential = Math.max(
        crestPotential,
        componentCrest,
      );
    };

    for (const wave of OCEAN_WAVES) {
      accumulateWave(wave);
    }
    for (const wave of OCEAN_SWELL_WAVES) {
      accumulateWave(
        wave,
        (
          OCEAN_MACRO_WAVE_TUNING.swellBase +
          swellStrength * OCEAN_MACRO_WAVE_TUNING.swellGain
        ),
      );
    }

    const tangentXx = 1 + horizontalDerivativeXX;
    const tangentXz = horizontalDerivativeZX;
    const tangentZx = horizontalDerivativeXZ;
    const tangentZz = 1 + horizontalDerivativeZZ;
    const normalX =
      gradientZ * tangentXz - tangentZz * gradientX;
    const normalY =
      tangentZz * tangentXx - tangentZx * tangentXz;
    const normalZ =
      tangentZx * gradientX - gradientZ * tangentXx;
    const normalLength = Math.hypot(normalX, normalY, normalZ);
    const horizontalJacobian =
      tangentXx * tangentZz - tangentZx * tangentXz;
    target.height = height;
    target.normalX = normalX / normalLength;
    target.normalY = normalY / normalLength;
    target.normalZ = normalZ / normalLength;
    target.displacementX = displacementX;
    target.displacementZ = displacementZ;
    target.curvature = curvature;
    target.compression = clamp01((1 - horizontalJacobian) * 4);
    target.crestPotential = crestPotential;
    return target;
  }

  public sampleCurrent(
    x: number,
    z: number,
    time: number,
    target: OceanCurrentSample = { x: 0, z: 0, angularVelocity: 0 },
  ): OceanCurrentSample {
    const motionTime = this.condition?.motionTime ?? time;
    const broad = Math.sin(z * 0.046 + motionTime * 0.024);
    const cross = Math.cos(x * 0.041 - motionTime * 0.019);
    const eddyPhase = (x + z) * 0.031 + motionTime * 0.016;
    target.x = 0.028 + broad * 0.021 + Math.cos(eddyPhase) * 0.014;
    target.z = 0.018 + cross * 0.022 - Math.sin(eddyPhase) * 0.012;
    target.angularVelocity =
      Math.cos(z * 0.046 + motionTime * 0.024) * 0.018 -
      Math.sin(x * 0.041 - motionTime * 0.019) * 0.014;
    return target;
  }
}

const glslNumber = (value: number): string => value.toFixed(8);

export const createOceanEnvironmentGLSL = (): string => {
  const shoals = OCEAN_SHOALS.map((shoal) => `
    depth -= exp(
      -dot(
        point - vec2(${glslNumber(shoal.x)}, ${glslNumber(shoal.z)}),
        point - vec2(${glslNumber(shoal.x)}, ${glslNumber(shoal.z)})
      ) / ${glslNumber(shoal.radius * shoal.radius)}
    ) * ${glslNumber(shoal.influence)};`).join('\n');

  return `
    void sampleOceanEnvironment(
      vec2 point,
      float time,
      out float depth,
      out float seaState,
      out vec2 wind,
      out float windStrength,
      out vec2 current
    ) {
      depth =
        0.64 +
        sin(point.x * 0.067 + point.y * 0.021 + 0.8) * 0.13 +
        cos(point.y * 0.074 - point.x * 0.018 - 1.1) * 0.12 +
        sin((point.x - point.y) * 0.031 + 2.4) * 0.07;
      ${shoals}
      depth = clamp(depth, 0.0, 1.0);

      float weatherFront =
        sin(point.x * 0.043 + point.y * 0.027 + time * 0.006 + 0.4);
      float crossWeather =
        cos(point.y * 0.061 - point.x * 0.019 - time * 0.004 - 1.3);
      windStrength = clamp(
        0.48 + weatherFront * 0.3 + crossWeather * 0.17,
        0.0,
        1.0
      );
      float rawSeaState = clamp(
        0.08 +
        windStrength * 0.82 +
        sin((point.x + point.y) * 0.025 - 0.7) * 0.1,
        0.0,
        1.0
      );
      seaState = rawSeaState * rawSeaState * (3.0 - 2.0 * rawSeaState);

      float windAngle =
        0.72 +
        sin(point.y * 0.026 + time * 0.003) * 0.34 +
        cos(point.x * 0.022 - time * 0.002) * 0.2;
      wind = vec2(cos(windAngle), sin(windAngle));

      float broad = sin(point.y * 0.046 + time * 0.024);
      float cross = cos(point.x * 0.041 - time * 0.019);
      float eddyPhase = (point.x + point.y) * 0.031 + time * 0.016;
      current = vec2(
        0.028 + broad * 0.021 + cos(eddyPhase) * 0.014,
        0.018 + cross * 0.022 - sin(eddyPhase) * 0.012
      );
    }
  `;
};

export const createOceanWaveFunctionGLSL = (): string => {
  const createWaveLines = (
    waves: readonly OceanWave[],
    amplitudeSuffix: string,
  ): string => waves.map((wave) => {
    const spatialFrequency = TAU / wave.wavelength;
    const sourceDirection =
      `vec2(${glslNumber(wave.directionX)}, ${glslNumber(wave.directionZ)})`;
    const phase =
      `${glslNumber(spatialFrequency)} * dot(direction, point) + ` +
      `${glslNumber(wave.temporalFrequency)} * time + ${glslNumber(wave.phase)}`;
    return `
      {
        vec2 sourceDirection = ${sourceDirection};
        vec2 direction = vec2(
          sourceDirection.x * directionCosine -
            sourceDirection.y * directionSine,
          sourceDirection.x * directionSine +
            sourceDirection.y * directionCosine
        );
        float phase = ${phase};
        float amplitude = ${glslNumber(wave.amplitude)}${amplitudeSuffix};
        float waveSine = sin(phase);
        float waveCosine = cos(phase);
        height += amplitude * waveSine;
        gradient +=
          amplitude * waveCosine * ${glslNumber(spatialFrequency)} * direction;
        float horizontalAmplitude =
          amplitude * ${glslNumber(wave.choppiness)};
        horizontalDisplacement +=
          direction * horizontalAmplitude * waveCosine;
        float horizontalDerivative =
          -horizontalAmplitude *
          ${glslNumber(spatialFrequency)} *
          waveSine;
        horizontalDerivatives += vec4(
          horizontalDerivative * direction.x * direction.x,
          horizontalDerivative * direction.x * direction.y,
          horizontalDerivative * direction.y * direction.x,
          horizontalDerivative * direction.y * direction.y
        );
        curvature +=
          amplitude *
          ${glslNumber(spatialFrequency * spatialFrequency)} *
          waveSine;
        crestPotential = max(
          crestPotential,
          smoothstep(0.58, 0.98, waveSine) *
            ${glslNumber(wave.crestWeight)}
        );
      }`;
  }).join('\n');
  const waveLines = createWaveLines(OCEAN_WAVES, '');
  const swellLines = createWaveLines(
    OCEAN_SWELL_WAVES,
    ' * resolveOceanSwellScale(swellStrength)',
  );
  const tuning = OCEAN_MACRO_WAVE_TUNING;
  const primary = OCEAN_WAVES[0]!;

  return `
    vec2 resolveOceanWaveBasis(
      vec2 wind,
      vec2 current,
      float directionOffset
    ) {
      vec2 dominant =
        wind +
        current * ${glslNumber(tuning.currentDirectionWeight)};
      dominant /= max(length(dominant), 0.0001);
      vec2 primary = vec2(
        ${glslNumber(primary.directionX)},
        ${glslNumber(primary.directionZ)}
      );
      float baseCosine = dot(primary, dominant);
      float baseSine =
        primary.x * dominant.y - primary.y * dominant.x;
      float offset =
        directionOffset *
        ${glslNumber(tuning.directionOffsetScale)};
      float offsetCosine = cos(offset);
      float offsetSine = sin(offset);
      return vec2(
        baseCosine * offsetCosine -
          baseSine * offsetSine,
        baseSine * offsetCosine +
          baseCosine * offsetSine
      );
    }

    float resolveOceanWaveExposure(float waveExposure) {
      float exposure = smoothstep(
        ${glslNumber(tuning.exposureStart)},
        ${glslNumber(tuning.exposureEnd)},
        waveExposure
      );
      return mix(
        ${glslNumber(tuning.minimumExposure)},
        1.0,
        exposure
      );
    }

    float resolveOceanMacroAmplitudeScale(
      float seaState,
      float waveExposure
    ) {
      return (
        ${glslNumber(tuning.regionalBase)} +
        clamp(seaState, 0.0, 1.0) *
          ${glslNumber(tuning.regionalSeaStateGain)}
      ) * resolveOceanWaveExposure(waveExposure);
    }

    float resolveOceanSwellScale(float swellStrength) {
      return
        ${glslNumber(tuning.swellBase)} +
        swellStrength * ${glslNumber(tuning.swellGain)};
    }

    float sampleOceanWaves(
      vec2 point,
      float time,
      vec2 wind,
      vec2 current,
      float directionOffset,
      float swellStrength,
      out vec2 gradient,
      out vec2 horizontalDisplacement,
      out vec4 horizontalDerivatives,
      out float curvature,
      out float crestPotential
    ) {
      float height = 0.0;
      gradient = vec2(0.0);
      horizontalDisplacement = vec2(0.0);
      horizontalDerivatives = vec4(0.0);
      curvature = 0.0;
      crestPotential = 0.0;
      vec2 waveBasis = resolveOceanWaveBasis(
        wind,
        current,
        directionOffset
      );
      float directionCosine = waveBasis.x;
      float directionSine = waveBasis.y;
      ${waveLines}
      ${swellLines}
      return height;
    }
  `;
};
