import { hash2D } from '../utils/math';

export type SnowEmergencyRoadClass = 'BOULEVARD' | 'AVENUE' | 'LOCAL';
export type SnowEmergencyPlowClass = 'COMPACT' | 'STANDARD' | 'HEAVY';

export interface SnowEmergencyIntersection {
  readonly id: string;
  readonly column: number;
  readonly row: number;
  readonly x: number;
  readonly z: number;
  readonly signalOffsetSeconds: number;
}

export interface SnowEmergencyRoadSegment {
  readonly id: string;
  readonly fromId: string;
  readonly toId: string;
  readonly axis: 'X' | 'Z';
  readonly centerX: number;
  readonly centerZ: number;
  readonly length: number;
  readonly width: number;
  readonly laneCountPerDirection: 1 | 2;
  readonly speedLimit: number;
  readonly roadClass: SnowEmergencyRoadClass;
  readonly requiredPlow: SnowEmergencyPlowClass;
  readonly priority: number;
}

export interface SnowEmergencyBuildingLot {
  readonly id: string;
  readonly x: number;
  readonly z: number;
  readonly width: number;
  readonly depth: number;
  readonly height: number;
  readonly color: number;
  readonly landmark?: 'HOSPITAL' | 'FIRE_STATION' | 'TRANSIT' | 'DEPOT';
}

export interface SnowEmergencySidewalk {
  readonly id: string;
  readonly centerX: number;
  readonly centerZ: number;
  readonly width: number;
  readonly depth: number;
  readonly axis: 'X' | 'Z';
  readonly requiredPlow: 'COMPACT';
}

export interface SnowEmergencyCityLayout {
  readonly id: 'snow-emergency-city-v1';
  readonly displayName: string;
  readonly centerX: number;
  readonly centerZ: number;
  readonly spawn: Readonly<{ x: number; z: number; heading: number }>;
  readonly intersections: readonly SnowEmergencyIntersection[];
  readonly roads: readonly SnowEmergencyRoadSegment[];
  readonly buildings: readonly SnowEmergencyBuildingLot[];
  readonly sidewalks: readonly SnowEmergencySidewalk[];
  readonly bounds: Readonly<{
    minX: number;
    maxX: number;
    minZ: number;
    maxZ: number;
  }>;
}

export const SNOW_EMERGENCY_CITY_CENTER = Object.freeze({
  x: -520,
  z: 260,
});

const COLUMNS = 7;
const ROWS = 7;
const X_PITCH = 46;
const Z_PITCH = 42;
const ROAD_HALF_SPAN_X = (COLUMNS - 1) * X_PITCH * 0.5;
const ROAD_HALF_SPAN_Z = (ROWS - 1) * Z_PITCH * 0.5;
const ROAD_COLORS = [
  0x506a77,
  0x6d657c,
  0x6f7e69,
  0x836a5d,
  0x556f72,
  0x736277,
  0x697483,
] as const;

const nodeId = (column: number, row: number): string =>
  `snow-city:i:${column}:${row}`;

const intersectionAt = (
  column: number,
  row: number,
): SnowEmergencyIntersection => ({
  id: nodeId(column, row),
  column,
  row,
  x: SNOW_EMERGENCY_CITY_CENTER.x +
    (column - (COLUMNS - 1) * 0.5) * X_PITCH,
  z: SNOW_EMERGENCY_CITY_CENTER.z +
    (row - (ROWS - 1) * 0.5) * Z_PITCH,
  signalOffsetSeconds: hash2D(column, row, 719) * 16,
});

const roadClassFor = (
  axis: 'X' | 'Z',
  fixedIndex: number,
): SnowEmergencyRoadClass => {
  if (fixedIndex === 3) return 'BOULEVARD';
  if (fixedIndex === 1 || fixedIndex === 5) return 'AVENUE';
  return axis === 'X' ? 'LOCAL' : 'LOCAL';
};

const roadDimensions = (
  roadClass: SnowEmergencyRoadClass,
): Readonly<{
  width: number;
  laneCount: 1 | 2;
  speedLimit: number;
  requiredPlow: SnowEmergencyPlowClass;
  priority: number;
}> => {
  switch (roadClass) {
    case 'BOULEVARD':
      return {
        width: 15.5,
        laneCount: 2,
        speedLimit: 10.8,
        requiredPlow: 'HEAVY',
        priority: 3,
      };
    case 'AVENUE':
      return {
        width: 12.5,
        laneCount: 2,
        speedLimit: 8.8,
        requiredPlow: 'STANDARD',
        priority: 2,
      };
    case 'LOCAL':
      return {
        width: 9.5,
        laneCount: 1,
        speedLimit: 6.8,
        requiredPlow: 'STANDARD',
        priority: 1,
      };
  }
};

const createRoad = (
  from: SnowEmergencyIntersection,
  to: SnowEmergencyIntersection,
  axis: 'X' | 'Z',
  fixedIndex: number,
): SnowEmergencyRoadSegment => {
  const roadClass = roadClassFor(axis, fixedIndex);
  const dimensions = roadDimensions(roadClass);
  return {
    id: `snow-city:road:${from.id}:${to.id}`,
    fromId: from.id,
    toId: to.id,
    axis,
    centerX: (from.x + to.x) * 0.5,
    centerZ: (from.z + to.z) * 0.5,
    length: Math.hypot(to.x - from.x, to.z - from.z),
    width: dimensions.width,
    laneCountPerDirection: dimensions.laneCount,
    speedLimit: dimensions.speedLimit,
    roadClass,
    requiredPlow: dimensions.requiredPlow,
    priority: dimensions.priority,
  };
};

const createBuilding = (
  blockColumn: number,
  blockRow: number,
  slot: 0 | 1,
): SnowEmergencyBuildingLot => {
  const leftRoadX = SNOW_EMERGENCY_CITY_CENTER.x - ROAD_HALF_SPAN_X +
    blockColumn * X_PITCH;
  const nearRoadZ = SNOW_EMERGENCY_CITY_CENTER.z - ROAD_HALF_SPAN_Z +
    blockRow * Z_PITCH;
  const seed = blockRow * 17 + blockColumn * 3 + slot * 41;
  const blockWidth = X_PITCH - 16.8;
  const blockDepth = Z_PITCH - 16.8;
  const width = blockWidth * (slot === 0 ? 0.46 : 0.38);
  const depth = blockDepth * (slot === 0 ? 0.72 : 0.58);
  const x = leftRoadX + X_PITCH * (slot === 0 ? 0.36 : 0.7);
  const z = nearRoadZ + Z_PITCH * (slot === 0 ? 0.5 : 0.48);
  const centrality = 1 - Math.min(
    1,
    Math.hypot(blockColumn - 2.5, blockRow - 2.5) / 4,
  );
  const height = 12 + centrality * 45 + hash2D(seed, 13, 991) * 26;
  const landmark = blockColumn === 4 && blockRow === 3 && slot === 0
    ? 'HOSPITAL' as const
    : blockColumn === 1 && blockRow === 4 && slot === 0
      ? 'FIRE_STATION' as const
      : blockColumn === 3 && blockRow === 1 && slot === 0
        ? 'TRANSIT' as const
        : blockColumn === 0 && blockRow === 2 && slot === 0
          ? 'DEPOT' as const
          : undefined;
  return {
    id: `snow-city:building:${blockColumn}:${blockRow}:${slot}`,
    x,
    z,
    width,
    depth,
    height: landmark ? Math.max(16, height * 0.48) : height,
    color: landmark === 'HOSPITAL'
      ? 0xe1ddd4
      : landmark === 'FIRE_STATION'
        ? 0xa64d43
        : landmark === 'TRANSIT'
          ? 0x5c7f8c
          : landmark === 'DEPOT'
            ? 0xc18c46
            : ROAD_COLORS[Math.floor(hash2D(seed, 7, 551) * ROAD_COLORS.length)]!,
    ...(landmark ? { landmark } : {}),
  };
};

export const createSnowEmergencyCityLayout = (): SnowEmergencyCityLayout => {
  const intersections: SnowEmergencyIntersection[] = [];
  const byId = new Map<string, SnowEmergencyIntersection>();
  for (let row = 0; row < ROWS; row += 1) {
    for (let column = 0; column < COLUMNS; column += 1) {
      const intersection = intersectionAt(column, row);
      intersections.push(intersection);
      byId.set(intersection.id, intersection);
    }
  }

  const roads: SnowEmergencyRoadSegment[] = [];
  for (let row = 0; row < ROWS; row += 1) {
    for (let column = 0; column < COLUMNS - 1; column += 1) {
      roads.push(createRoad(
        byId.get(nodeId(column, row))!,
        byId.get(nodeId(column + 1, row))!,
        'X',
        row,
      ));
    }
  }
  for (let column = 0; column < COLUMNS; column += 1) {
    for (let row = 0; row < ROWS - 1; row += 1) {
      roads.push(createRoad(
        byId.get(nodeId(column, row))!,
        byId.get(nodeId(column, row + 1))!,
        'Z',
        column,
      ));
    }
  }

  const sidewalks: SnowEmergencySidewalk[] = roads.flatMap<SnowEmergencySidewalk>((road) => {
    const sidewalkWidth = 2.45;
    const offset = road.width * 0.5 + sidewalkWidth * 0.5;
    if (road.axis === 'X') {
      return [-1, 1].map((side) => ({
        id: `${road.id}:sidewalk:${side}`,
        centerX: road.centerX,
        centerZ: road.centerZ + side * offset,
        width: road.length,
        depth: sidewalkWidth,
        axis: 'X' as const,
        requiredPlow: 'COMPACT' as const,
      }));
    }
    return [-1, 1].map((side) => ({
      id: `${road.id}:sidewalk:${side}`,
      centerX: road.centerX + side * offset,
      centerZ: road.centerZ,
      width: sidewalkWidth,
      depth: road.length,
      axis: 'Z' as const,
      requiredPlow: 'COMPACT' as const,
    }));
  });

  const buildings: SnowEmergencyBuildingLot[] = [];
  for (let row = 0; row < ROWS - 1; row += 1) {
    for (let column = 0; column < COLUMNS - 1; column += 1) {
      buildings.push(
        createBuilding(column, row, 0),
        createBuilding(column, row, 1),
      );
    }
  }

  return Object.freeze({
    id: 'snow-emergency-city-v1',
    displayName: 'Northbridge Snow Emergency',
    centerX: SNOW_EMERGENCY_CITY_CENTER.x,
    centerZ: SNOW_EMERGENCY_CITY_CENTER.z,
    spawn: Object.freeze({
      x: SNOW_EMERGENCY_CITY_CENTER.x - ROAD_HALF_SPAN_X + 7,
      z: SNOW_EMERGENCY_CITY_CENTER.z - Z_PITCH,
      heading: Math.PI / 2,
    }),
    intersections: Object.freeze(intersections),
    roads: Object.freeze(roads),
    buildings: Object.freeze(buildings),
    sidewalks: Object.freeze(sidewalks),
    bounds: Object.freeze({
      minX: SNOW_EMERGENCY_CITY_CENTER.x - ROAD_HALF_SPAN_X - 20,
      maxX: SNOW_EMERGENCY_CITY_CENTER.x + ROAD_HALF_SPAN_X + 20,
      minZ: SNOW_EMERGENCY_CITY_CENTER.z - ROAD_HALF_SPAN_Z - 20,
      maxZ: SNOW_EMERGENCY_CITY_CENTER.z + ROAD_HALF_SPAN_Z + 20,
    }),
  });
};

export const SNOW_EMERGENCY_CITY_LAYOUT = createSnowEmergencyCityLayout();

export const snowEmergencyRoadAt = (
  x: number,
  z: number,
  layout = SNOW_EMERGENCY_CITY_LAYOUT,
): SnowEmergencyRoadSegment | undefined => layout.roads.find((road) =>
  road.axis === 'X'
    ? Math.abs(z - road.centerZ) <= road.width * 0.5 &&
      Math.abs(x - road.centerX) <= road.length * 0.5
    : Math.abs(x - road.centerX) <= road.width * 0.5 &&
      Math.abs(z - road.centerZ) <= road.length * 0.5
);

export const snowEmergencySidewalkAt = (
  x: number,
  z: number,
  layout = SNOW_EMERGENCY_CITY_LAYOUT,
): SnowEmergencySidewalk | undefined => layout.sidewalks.find((sidewalk) =>
  Math.abs(x - sidewalk.centerX) <= sidewalk.width * 0.5 &&
  Math.abs(z - sidewalk.centerZ) <= sidewalk.depth * 0.5
);
