import {
  DayNightSystem,
  DAY_LENGTH_SECONDS,
  type DayMode,
  type DayNightState,
  type DayNightSystemSaveData,
  type DayTimeScale,
} from './DayNightSystem';
import {
  WeatherSystem,
  WEATHER_PROFILES,
  type WeatherKind,
  type WeatherMode,
  type WeatherForecast,
  type WeatherState,
  type WeatherSystemSaveData,
  type WeatherTimeScale,
} from './WeatherSystem';
import {
  OceanConditionSystem,
  type OceanConditionState,
  type OceanConditionSystemSaveData,
  type OceanPreviewMode,
  type OceanTimeScale,
} from '../ocean/OceanConditionSystem';
import {
  OceanField,
  type OceanCurrentSample,
  type OceanEnvironmentSample,
} from '../ocean/OceanField';
import { OceanBathymetryField } from '../ocean/OceanBathymetry';
import { clamp } from '../utils/math';
import {
  createEnvironmentPresentationState,
  resolveEnvironmentPresentation,
  type EnvironmentPresentationState,
} from './EnvironmentPresentation';
import {
  DEFAULT_CELESTIAL_MODEL,
  isCelestialModel,
  type CelestialModel,
} from './CelestialCycle';
import { predictNextCelestialOmen } from './AerionOrbitalSystem';

export interface EnvironmentSystemSaveData {
  version: 1;
  worldTime: number;
  celestialModel?: CelestialModel;
  weather: WeatherSystemSaveData;
  dayNight: DayNightSystemSaveData;
  ocean: OceanConditionSystemSaveData;
}

export interface EnvironmentFrameState {
  readonly revision: number;
  readonly worldTime: number;
  readonly weather: Readonly<WeatherState>;
  readonly dayNight: Readonly<DayNightState>;
  readonly ocean: Readonly<OceanConditionState>;
  readonly presentation: Readonly<EnvironmentPresentationState>;
}

export type EnvironmentMasterTimeScale = 1 | 4 | 16 | 64;

const ENVIRONMENT_MASTER_TIME_SCALES: readonly EnvironmentMasterTimeScale[] = [
  1,
  4,
  16,
  64,
];

interface MutableEnvironmentFrameState {
  revision: number;
  worldTime: number;
  weather: WeatherState;
  dayNight: DayNightState;
  ocean: OceanConditionState;
  presentation: EnvironmentPresentationState;
}

export interface LocalEnvironmentSample {
  depth: number;
  seaState: number;
  windX: number;
  windZ: number;
  windStrength: number;
  waveExposure: number;
  currentX: number;
  currentZ: number;
  currentAngularVelocity: number;
  waveScale: number;
  visibility: number;
}

const createLocalSample = (): LocalEnvironmentSample => ({
  depth: 0.5,
  seaState: 0.5,
  windX: 1,
  windZ: 0,
  windStrength: 0.5,
  waveExposure: 1,
  currentX: 0,
  currentZ: 0,
  currentAngularVelocity: 0,
  waveScale: 1,
  visibility: 1,
});

export class EnvironmentSystem {
  public readonly oceanField = new OceanField();
  public readonly oceanBathymetry = new OceanBathymetryField();

  private readonly weather: WeatherSystem;
  private readonly dayNight: DayNightSystem;
  private readonly ocean: OceanConditionSystem;
  private readonly localOcean: OceanEnvironmentSample = {
    depth: 0.5,
    seaState: 0.5,
    windX: 1,
    windZ: 0,
    windStrength: 0.5,
    waveExposure: 1,
  };
  private readonly localCurrent: OceanCurrentSample = {
    x: 0,
    z: 0,
    angularVelocity: 0,
  };
  private readonly frame: MutableEnvironmentFrameState;
  private worldTime = 0;
  private masterTimeScale: EnvironmentMasterTimeScale = 1;
  private celestialModel: CelestialModel = DEFAULT_CELESTIAL_MODEL;

  public constructor(saved?: unknown) {
    const restoredWeather = new WeatherSystem();
    const restoredDayNight = new DayNightSystem();
    const restoredOcean = new OceanConditionSystem();
    const candidate =
      saved && typeof saved === 'object'
        ? saved as Partial<EnvironmentSystemSaveData>
        : undefined;
    const restored =
      candidate?.version === 1 &&
      Number.isFinite(candidate.worldTime) &&
      restoredWeather.importState(candidate.weather) &&
      restoredDayNight.importState(candidate.dayNight) &&
      restoredOcean.importState(candidate.ocean);

    this.weather = restored ? restoredWeather : new WeatherSystem();
    this.dayNight = restored ? restoredDayNight : new DayNightSystem();
    this.ocean = restored ? restoredOcean : new OceanConditionSystem();
    this.worldTime = restored
      ? Math.max(0, candidate?.worldTime ?? 0)
      : 0;
    this.celestialModel = restored && isCelestialModel(candidate?.celestialModel)
      ? candidate.celestialModel
      : DEFAULT_CELESTIAL_MODEL;
    this.applyWeatherToOcean();
    this.oceanField.setBathymetryField(this.oceanBathymetry);
    this.oceanField.setConditionState(this.ocean.getState());
    this.frame = {
      revision: 0,
      worldTime: this.worldTime,
      weather: { ...this.weather.getState() },
      dayNight: { ...this.dayNight.getState() },
      ocean: { ...this.ocean.getState() },
      presentation: createEnvironmentPresentationState(),
    };
    this.synchronizeFrame();
  }

  public update(deltaSeconds: number): EnvironmentFrameState {
    const delta = clamp(deltaSeconds, 0, 0.1);
    if (delta <= 0) return this.frame;

    this.worldTime += delta;
    this.weather.update(delta, this.masterTimeScale);
    this.dayNight.update(delta, this.masterTimeScale);
    this.applyWeatherToOcean();
    this.ocean.update(delta, this.masterTimeScale);
    this.synchronizeFrame();
    return this.frame;
  }

  public getFrame(): EnvironmentFrameState {
    return this.frame;
  }

  public getMasterTimeScale(): EnvironmentMasterTimeScale {
    return this.masterTimeScale;
  }

  public cycleMasterTimeScale(): EnvironmentMasterTimeScale {
    const current = ENVIRONMENT_MASTER_TIME_SCALES.indexOf(
      this.masterTimeScale,
    );
    this.masterTimeScale = ENVIRONMENT_MASTER_TIME_SCALES[
      (current + 1) % ENVIRONMENT_MASTER_TIME_SCALES.length
    ] ?? 1;
    // The master clock is an immediately understandable inspection mode.
    // Clear old per-channel multipliers so day, weather and ocean cannot
    // silently drift apart after the player has previously used Y/B/F7.
    this.dayNight.setTimeScale(1);
    this.weather.setTimeScale(1);
    this.ocean.setTimeScale(1);
    this.synchronizeFrame();
    return this.masterTimeScale;
  }

  /** Playtest-only calendar jump; simulation remains deterministic afterward. */
  public jumpToNextCelestialOmen(): number {
    const targetTime = predictNextCelestialOmen(
      this.dayNight.getState().dayTime + 1,
      3,
    );
    this.dayNight.applyAuthorityWorldTime(targetTime);
    this.synchronizeFrame();
    return targetTime;
  }

  /** Playtest jump to a clear, genuinely starless twin-sun aurora window. */
  public jumpToNextAuroraPreview(): number {
    this.celestialModel = 'AERION_SIRION';
    this.masterTimeScale = 1;
    this.dayNight.setTimeScale(1);
    this.weather.setTimeScale(1);
    this.weather.applyAuthorityState('clear', WEATHER_PROFILES.clear);
    const start = this.dayNight.getState().dayTime + 1;
    const end = start + DAY_LENGTH_SECONDS * 14;
    for (let candidate = start; candidate <= end; candidate += 6) {
      this.dayNight.applyAuthorityWorldTime(candidate);
      this.synchronizeFrame();
      if (
        this.frame.presentation.auroraVisibility > 0.48 &&
        Math.max(
          this.frame.presentation.sunHeight,
          this.frame.presentation.moonHeight,
        ) < -0.015
      ) return candidate;
    }
    this.synchronizeFrame();
    return this.dayNight.getState().dayTime;
  }

  public sampleLocal(
    x: number,
    z: number,
    target: LocalEnvironmentSample = createLocalSample(),
  ): LocalEnvironmentSample {
    const ocean = this.frame.ocean;
    const weather = this.frame.weather;
    const environment = this.oceanField.sampleEnvironment(
      x,
      z,
      ocean.motionTime,
      this.localOcean,
    );
    const current = this.oceanField.sampleCurrent(
      x,
      z,
      ocean.motionTime,
      this.localCurrent,
    );
    target.depth = environment.depth;
    target.seaState = environment.seaState;
    // Ocean micro-variation keeps the field alive, but forecast direction is
    // authoritative so trees, flags, flakes and drifts all agree.
    const forecastX = Math.cos(weather.windDirectionRadians);
    const forecastZ = Math.sin(weather.windDirectionRadians);
    const mixedX = forecastX * 0.9 + environment.windX * 0.1;
    const mixedZ = forecastZ * 0.9 + environment.windZ * 0.1;
    const mixedLength = Math.max(0.0001, Math.hypot(mixedX, mixedZ));
    target.windX = mixedX / mixedLength;
    target.windZ = mixedZ / mixedLength;
    target.windStrength = environment.windStrength *
      (0.82 + weather.windGust * 0.36);
    target.waveExposure = environment.waveExposure;
    target.currentX = current.x;
    target.currentZ = current.z;
    target.currentAngularVelocity = current.angularVelocity;
    target.waveScale = ocean.waveScale;
    target.visibility = clamp(
      1 - (weather.fogDensity - 0.0105) / 0.0165,
      0,
      1,
    );
    return target;
  }

  public exportState(): EnvironmentSystemSaveData {
    return {
      version: 1,
      worldTime: this.worldTime,
      celestialModel: this.celestialModel,
      weather: this.weather.exportState(),
      dayNight: this.dayNight.exportState(),
      ocean: this.ocean.exportState(),
    };
  }

  public cycleWeatherMode(): WeatherMode {
    const mode = this.weather.cycleMode();
    this.synchronizeFrame();
    return mode;
  }

  public getWeatherForecast(): WeatherForecast {
    return this.weather.getForecast();
  }

  /** Applies a local-mode cadence bias without forcing or resetting weather. */
  public setSnowFrequencyBias(enabled: boolean): void {
    this.weather.setSnowFrequencyBias(enabled);
  }

  public forceSnowForecast(): WeatherMode {
    const mode = this.weather.setMode('light-snow');
    this.synchronizeFrame();
    return mode;
  }

  public applySharedAuthorityState(input: Readonly<{
    worldTimeSeconds: number;
    weather: Readonly<{
      kind: WeatherKind;
      windMultiplier: number;
      fogDensity: number;
      snowIntensity: number;
      refreezeMultiplier: number;
    }>;
  }>): void {
    if (!Number.isFinite(input.worldTimeSeconds) || input.worldTimeSeconds < 0) return;
    this.worldTime = input.worldTimeSeconds;
    this.weather.applyAuthorityState(input.weather.kind, input.weather);
    this.dayNight.applyAuthorityWorldTime(input.worldTimeSeconds);
    this.applyWeatherToOcean();
    this.synchronizeFrame();
  }

  public cycleWeatherTimeScale(): WeatherTimeScale {
    const timeScale = this.weather.cycleTimeScale();
    this.synchronizeFrame();
    return timeScale;
  }

  public toggleWeatherFrozen(): boolean {
    const frozen = this.weather.toggleFrozen();
    this.synchronizeFrame();
    return frozen;
  }

  public cycleDayMode(): DayMode {
    const mode = this.dayNight.cycleMode();
    this.synchronizeFrame();
    return mode;
  }

  public getCelestialModel(): CelestialModel {
    return this.celestialModel;
  }

  public cycleCelestialModel(): CelestialModel {
    this.celestialModel = this.celestialModel === 'AERION_SIRION'
      ? 'LEGACY_SUN_MOON'
      : 'AERION_SIRION';
    this.synchronizeFrame();
    return this.celestialModel;
  }

  public cycleDayTimeScale(): DayTimeScale {
    const timeScale = this.dayNight.cycleTimeScale();
    this.synchronizeFrame();
    return timeScale;
  }

  public toggleDayFrozen(): boolean {
    const frozen = this.dayNight.toggleFrozen();
    this.synchronizeFrame();
    return frozen;
  }

  public cycleOceanPreviewMode(): OceanPreviewMode {
    const mode = this.ocean.cyclePreviewMode();
    this.synchronizeFrame();
    return mode;
  }

  public cycleOceanTimeScale(): OceanTimeScale {
    const timeScale = this.ocean.cycleTimeScale();
    this.synchronizeFrame();
    return timeScale;
  }

  public toggleOceanFrozen(): boolean {
    const frozen = this.ocean.toggleFrozen();
    this.synchronizeFrame();
    return frozen;
  }

  private applyWeatherToOcean(): void {
    const weather = this.weather.getState();
    this.ocean.setWeatherInfluence(
      weather.waveMultiplier,
      weather.windMultiplier,
    );
  }

  private synchronizeFrame(): void {
    this.frame.revision += 1;
    this.frame.worldTime = this.worldTime;
    Object.assign(this.frame.weather, this.weather.getState());
    Object.assign(this.frame.dayNight, this.dayNight.getState());
    Object.assign(this.frame.ocean, this.ocean.getState());
    resolveEnvironmentPresentation(
      this.frame.weather,
      this.frame.dayNight,
      this.frame.presentation,
      this.celestialModel,
    );
  }
}
