export const resolveSkyStory = (
  _weather: Readonly<WeatherState>,
  day: Readonly<DayNightState>,
): Readonly<SkyStoryDefinition> => {
  const dayIndex = Math.floor(Math.max(0, day.dayTime) / DAY_LENGTH_SECONDS);
  return SKY_STORIES[dayIndex % SKY_STORIES.length]!;
};

/**
 * Aurora nights alternate at three- and four-night intervals. Day zero is an
 * event night on purpose: a fresh Long Winter world reaches its first long
 * starless hush during the opening session instead of making playtesters wait
 * through several complete celestial days.
 */
export const isAuroraNight = (dayIndex: number): boolean => {
  const normalizedDay = ((Math.floor(dayIndex) % 7) + 7) % 7;
  return normalizedDay === 0 || normalizedDay === 3;
};

/**
 * Aurora curtains belong only to a genuinely starless interval in the
 * twin-star sky. The small fade happens entirely below the geometric discs,
 * so neither Aerion nor Sirion can share the visible sky with an aurora.
 */
export const resolveTwinStarAuroraGate = (
  aerionHeight: number,
  sirionHeight: number,
): number => 1 - smoothstep(
  -0.028,
  -0.012,
  Math.max(aerionHeight, sirionHeight),
);

