export const resolveEnvironmentPresentation = (
  weather: Readonly<WeatherState>,
  day: Readonly<DayNightState>,
  target: EnvironmentPresentationState =
    createEnvironmentPresentationState(),
  celestialModel: CelestialModel = 'LEGACY_SUN_MOON',
): EnvironmentPresentationState => {
  const twinStars = celestialModel === 'AERION_SIRION';
  const twinCycle = resolveTwinStarCycle(day.dayTime);
  const sunAzimuth = twinStars
    ? twinCycle.aerionAzimuth
    : day.sunAzimuth;
  const sunHeight = twinStars
    ? twinCycle.aerionHeight
    : day.sunHeight;
  const aerionHorizonWeight = twinStars
    // Atmospheric magnification is strongest while the centre crosses the
    // horizon; it must not collapse merely because half the disc is already
    // below it. The depth/terrain silhouette owns the actual disappearance.
    ? 1 - smoothstep(0.025, 0.22, Math.abs(sunHeight))
    : 0;
  const cloud = clamp(weather.cloudCover, 0, 1);
  const fogFactor = clamp(
    (weather.fogDensity - 0.0105) / 0.0165,
    0,
    1,
  );
  const night = clamp(day.night, 0, 1);
  const twilight = clamp(day.twilight, 0, 1);
  const warmth = clamp(day.warmth, 0, 1);
  const daylight = clamp(day.daylight, 0.15, 1);
  const weatherMood = clamp(
    cloud * 0.32 + fogFactor * 0.12,
    0,
    0.42,
  );
  const dayIndex = Math.floor(Math.max(0, day.dayTime) / DAY_LENGTH_SECONDS);
  const cycleProgress = day.cycleProgress - Math.floor(day.cycleProgress);
  const skyStory = resolveSkyStory(weather, day);
  const previousSkyStory = SKY_STORIES[
    (dayIndex - 1 + SKY_STORIES.length) % SKY_STORIES.length
  ]!;
  // A new authored palette belongs to the coming day, but it must arrive as
  // dawn rather than replace the old night at the integer day boundary. At
  // midnight the previous story is still exact; over the following six real
  // minutes its colours seep into the horizon before Aerion appears.
  const skyStoryArrival = smoothstep(0, 0.14, cycleProgress);
  const absoluteDay = Math.max(0, day.dayTime) / DAY_LENGTH_SECONDS;
  const calendar = resolvePolarCalendar(day.dayTime);
  const calendarMonthPosition =
    calendar.yearProgress * POLAR_MONTHS_PER_YEAR;
  const calendarMonthIndex = Math.floor(calendarMonthPosition) %
    ARCTIC_DAY_PALETTES.length;
  const nextCalendarMonthIndex = (calendarMonthIndex + 1) %
    ARCTIC_DAY_PALETTES.length;
  const calendarMonthBlend = smoothstep(
    0,
    1,
    calendarMonthPosition - Math.floor(calendarMonthPosition),
  );
  const calendarDayPalette = ARCTIC_DAY_PALETTES[calendarMonthIndex]!;
  const nextCalendarDayPalette = ARCTIC_DAY_PALETTES[nextCalendarMonthIndex]!;
  CALENDAR_DAY_HORIZON
    .setHex(calendarDayPalette.horizon)
    .lerp(
      NEXT_CALENDAR_DAY_HORIZON.setHex(nextCalendarDayPalette.horizon),
      calendarMonthBlend,
    );
  CALENDAR_DAY_ZENITH
    .setHex(calendarDayPalette.zenith)
    .lerp(
      NEXT_CALENDAR_DAY_ZENITH.setHex(nextCalendarDayPalette.zenith),
      calendarMonthBlend,
    );
  const calendarDayStrength = lerp(
    calendarDayPalette.strength,
    nextCalendarDayPalette.strength,
    calendarMonthBlend,
  );
  const dawnDistance = Math.abs(cycleProgress - 0.14);
  const duskDistance = Math.abs(cycleProgress - 0.76);
  const dawnWeight = 1 - smoothstep(0.045, 0.19, dawnDistance);
  const duskWeight = 1 - smoothstep(0.045, 0.2, duskDistance);
  // A story palette can be fantastical, but direct solar colour still obeys
  // altitude. This closes the long red plateau after sunset while retaining
  // a short, saturated afterglow close to the horizon.
  const solarHorizonGate = smoothstep(-0.14, -0.018, sunHeight);
  const twilightDrama = lerp(
    TWILIGHT_DRAMA[previousSkyStory.id] ?? 1,
    TWILIGHT_DRAMA[skyStory.id] ?? 1,
    skyStoryArrival,
  );
  const dawnColorWeight = clamp(
    dawnWeight * solarHorizonGate * twilightDrama,
    0,
    1,
  );
  const duskColorWeight = clamp(
    duskWeight * solarHorizonGate * twilightDrama,
    0,
    1,
  );
  const twilightGlow = Math.max(dawnColorWeight, duskColorWeight);
  // Ordinary broken cloud often makes sunrise and sunset richer by catching
  // warm light on its underside. Only genuinely dense snowfall or fog should
  // collapse an authored sky story into the cold covered palette.
  const stormSeverity = clamp(
    smoothstep(0.68, 0.98, weather.snowIntensity) *
      (0.78 + smoothstep(1.08, 1.55, weather.windMultiplier) * 0.22),
    0,
    1,
  );
  const denseFogSeverity = smoothstep(0.58, 1, fogFactor);
  const twilightCloudLight = twilightGlow *
    (1 - stormSeverity) *
    (1 - denseFogSeverity * 0.82);
  const colourlessSkyCover = cloud * lerp(
    1,
    0.22,
    twilightCloudLight,
  );
  // The lunar orbit advances continuously rather than stepping at midnight.
  // One compact polar month is one complete eight-day lunar cycle.
  const lunarAngle = ((absoluteDay + 4) % 8) / 8 * Math.PI * 2;
  const moonPhase = twinStars
    ? 1
    : 0.5 - Math.cos(lunarAngle) * 0.5;
  // The moon has its own cheap deterministic orbit instead of being welded
  // to the exact antipode of the sun. A full moon still rises opposite the
  // sunset, while a new moon travels close enough to the sun for the rare
  // eclipse story below. Quarter moons occupy their own readable sky arcs.
  const moonAzimuth = twinStars
    ? twinCycle.sirionAzimuth
    : sunAzimuth + lunarAngle;
  const moonHeight = twinStars
    ? twinCycle.sirionHeight
    : clamp(
        sunHeight * Math.cos(lunarAngle) + Math.sin(lunarAngle) * 0.17,
        -0.36,
        0.92,
      );
  const moonAboveHorizon = smoothstep(-0.035, 0.045, moonHeight);
  // Civil twilight belongs to colour and silhouettes. The moon waits until
  // the sun is a few degrees below the horizon; stars wait longer still and
  // then emerge gradually through nautical twilight.
  const moonDarknessGate = twinStars
    ? 1
    : 1 - smoothstep(-0.1, -0.025, sunHeight);
  const starDarknessGate = 1 - smoothstep(-0.15, -0.055, sunHeight);
  const moonHorizonWeight = 1 - smoothstep(
    0.055,
    0.23,
    Math.abs(moonHeight),
  );
  const moonStoryTint = twinStars
    ? TWIN_SIRION_TINT
      .copy(SIRION)
      .lerp(SIRION_HORIZON, moonHorizonWeight * 0.9)
    : MOON_HORIZON_TINTS[dayIndex % MOON_HORIZON_TINTS.length]!;
  const lunarCycleIndex = Math.floor(dayIndex / 8);
  const bloodMoon = !twinStars && lunarCycleIndex % 11 === 7 && moonPhase > 0.78
    ? smoothstep(0.78, 0.98, moonPhase)
    : 0;
  // A solar eclipse is intentionally an event rather than an all-day new
  // moon. One alignment occurs every 29 lunar cycles and lasts roughly two
  // in-game minutes around the high daylight arc.
  const eclipseDay = lunarCycleIndex % 29 === 13 && dayIndex % 8 === 4;
  const eclipseDistance = Math.abs(cycleProgress - 0.48);
  const solarEclipse = !twinStars && eclipseDay
    ? 1 - smoothstep(0.018, 0.048, eclipseDistance)
    : 0;
  // The rare authored event resolves the final few degrees of alignment at
  // its centre. Outside that short window the moon continues its smooth orbit.
  const resolvedMoonAzimuth = lerp(
    moonAzimuth,
    sunAzimuth,
    solarEclipse,
  );
  const resolvedMoonHeight = lerp(
    moonHeight,
    sunHeight,
    solarEclipse,
  );
  const resolvedMoonTint = bloodMoon > 0
    ? BLOOD_MOON
    : moonStoryTint;
  const moonStoryGlow = moonHorizonWeight * Math.pow(moonPhase, 1.25) *
    (1 - cloud * 0.72);
  const solarClarity = 0.72 +
    (0.5 + Math.sin(dayIndex * 2.17 + 0.8) * 0.5) * 0.28;
  // Most noons return to restrained arctic blue. A small authored subset of
  // days retains a trace of its story palette in broad daylight, preserving
  // the world's fantasy without making every sunrise feel ordinary.
  const mysticDayWeight = lerp(
    MYSTIC_DAY_STRENGTH[previousSkyStory.id] ?? 0,
    MYSTIC_DAY_STRENGTH[skyStory.id] ?? 0,
    skyStoryArrival,
  ) *
    smoothstep(0.48, 0.82, daylight) *
    (1 - twilightGlow) * (1 - night) *
    (1 - stormSeverity * 0.86);
  const arcticDayWeight = smoothstep(0.52, 0.9, daylight) *
    (1 - twilightGlow) * (1 - night) *
    (1 - colourlessSkyCover * 0.76) * calendarDayStrength;

  target.skyZenithColor
    .copy(blendStoryColor(
      STORY_DAY_ZENITH,
      previousSkyStory.dayZenith,
      skyStory.dayZenith,
      skyStoryArrival,
    ))
    .lerp(CALENDAR_DAY_ZENITH, arcticDayWeight)
    .lerp(
      blendStoryColor(
        STORY_MYSTIC_DAY_ZENITH,
        previousSkyStory.dawnZenith,
        skyStory.dawnZenith,
        skyStoryArrival,
      ),
      mysticDayWeight * 0.24,
    )
    .lerp(blendStoryColor(
      STORY_DAWN_ZENITH,
      previousSkyStory.dawnZenith,
      skyStory.dawnZenith,
      skyStoryArrival,
    ), dawnColorWeight * 0.92)
    .lerp(blendStoryColor(
      STORY_DUSK_ZENITH,
      previousSkyStory.duskZenith,
      skyStory.duskZenith,
      skyStoryArrival,
    ), duskColorWeight * 0.94)
    .lerp(blendStoryColor(
      STORY_NIGHT_ZENITH,
      previousSkyStory.nightZenith,
      skyStory.nightZenith,
      skyStoryArrival,
    ), night * 0.96)
    .lerp(resolvedMoonTint, moonStoryGlow * (0.045 + bloodMoon * 0.08))
    .lerp(COVERED_SKY, clamp(
      colourlessSkyCover * 0.62 + fogFactor * 0.18,
      0,
      0.8,
    ))
    .offsetHSL(0, twilightGlow * 0.055, twilightGlow * 0.012);
  target.skyHorizonColor
    .copy(blendStoryColor(
      STORY_DAY_HORIZON,
      previousSkyStory.dayHorizon,
      skyStory.dayHorizon,
      skyStoryArrival,
    ))
    .lerp(CALENDAR_DAY_HORIZON, arcticDayWeight * 0.82)
    .lerp(
      blendStoryColor(
        STORY_MYSTIC_DAY_HORIZON,
        previousSkyStory.duskHorizon,
        skyStory.duskHorizon,
        skyStoryArrival,
      ),
      mysticDayWeight * 0.32,
    )
    .lerp(blendStoryColor(
      STORY_DAWN_HORIZON,
      previousSkyStory.dawnHorizon,
      skyStory.dawnHorizon,
      skyStoryArrival,
    ), dawnColorWeight)
    .lerp(blendStoryColor(
      STORY_DUSK_HORIZON,
      previousSkyStory.duskHorizon,
      skyStory.duskHorizon,
      skyStoryArrival,
    ), duskColorWeight)
    .lerp(blendStoryColor(
      STORY_NIGHT_HORIZON,
      previousSkyStory.nightHorizon,
      skyStory.nightHorizon,
      skyStoryArrival,
    ), night * 0.94)
    .lerp(resolvedMoonTint, moonStoryGlow * (0.3 + bloodMoon * 0.28))
    .lerp(COVERED_FOG, clamp(
      colourlessSkyCover * 0.48 + fogFactor * 0.3,
      0,
      0.82,
    ))
    .offsetHSL(
      0,
      twilightGlow * (0.11 + (twilightDrama - 1) * 0.16),
      twilightGlow * 0.022,
    );
  if (twinStars) {
    // The swollen low Aerion stains its own atmospheric horizon. This broad
    // grade is intentionally restrained; the directional sky shader adds the
    // concentrated glow around the actual star direction.
    target.skyHorizonColor.lerp(
      AERION_HORIZON,
      aerionHorizonWeight * (1 - cloud * 0.72) * 0.24,
    );
  }
  target.fogColor.copy(target.skyHorizonColor);
  target.cloudColor
    .copy(blendStoryColor(
      STORY_CLOUD,
      previousSkyStory.cloudTint,
      skyStory.cloudTint,
      skyStoryArrival,
    ))
    .lerp(
      COVERED_SKY,
      cloud * lerp(0.38, 0.14, twilightCloudLight),
    )
    .lerp(NIGHT_SKY, night * 0.72)
    .lerp(
      blendStoryColor(
        STORY_DUSK_HORIZON,
        previousSkyStory.duskHorizon,
        skyStory.duskHorizon,
        skyStoryArrival,
      ),
      duskColorWeight * (0.18 + twilightCloudLight * 0.5),
    )
    .lerp(
      blendStoryColor(
        STORY_DAWN_HORIZON,
        previousSkyStory.dawnHorizon,
        skyStory.dawnHorizon,
        skyStoryArrival,
      ),
      dawnColorWeight * (0.13 + twilightCloudLight * 0.44),
    )
    .lerp(resolvedMoonTint, moonStoryGlow * (0.18 + bloodMoon * 0.3))
    .offsetHSL(
      0,
      twilightGlow * (0.075 + (twilightDrama - 1) * 0.12),
      twilightGlow * 0.015,
    );
  target.sunColor
    .copy(COLD_DAY_SUN)
    .lerp(DAY_SUN, solarClarity * 0.2)
    .lerp(blendStoryColor(
      STORY_SUN,
      previousSkyStory.dawnSun,
      skyStory.dawnSun,
      skyStoryArrival,
    ), dawnColorWeight * 0.94)
    .lerp(blendStoryColor(
      STORY_SUN,
      previousSkyStory.duskSun,
      skyStory.duskSun,
      skyStoryArrival,
    ), duskColorWeight * 0.96)
    .lerp(
      blendStoryColor(
        STORY_SUN,
        previousSkyStory.dawnSun,
        skyStory.dawnSun,
        skyStoryArrival,
      ),
      mysticDayWeight * 0.16,
    )
    .lerp(NIGHT_SUN, night * 0.7);
  if (twinStars) {
    // Aerion remains unmistakably ember-orange even at its brightest. The
    // atmosphere may pale the glare, but the celestial body itself must not
    // collapse into the legacy white solar disc.
    target.sunColor
      .copy(AERION)
      .lerp(AERION_HORIZON, aerionHorizonWeight * 0.92)
      .lerp(target.skyHorizonColor, cloud * 0.08);
  }
  target.moonColor
    .copy(MOON)
    .lerp(FULL_MOON, moonPhase * 0.28)
    .lerp(moonStoryTint, moonHorizonWeight * 0.82)
    .lerp(BLOOD_MOON, bloodMoon * 0.94);
  if (twinStars) {
    target.moonColor
      .copy(SIRION)
      .lerp(SIRION_HORIZON, moonHorizonWeight * 0.88);
  }
  if (twinStars) {
    // The Long Winter's aurora belongs to the same authored sky mythology as
    // Aerion and Sirion. Its lower curtain stays red/crimson while the shader
    // is free to lift the thinnest upper folds toward rose and violet.
    target.auroraColor.copy(
      TWIN_AURORA_PALETTE[dayIndex % TWIN_AURORA_PALETTE.length]!,
    );
  } else {
    target.auroraColor.copy(blendStoryColor(
      STORY_AURORA,
      previousSkyStory.aurora,
      skyStory.aurora,
      skyStoryArrival,
    ));
  }
  // CodePen's strongest transferable idea is a three-level cloud response:
  // sunlight, veiled middle and optical-depth shadow. Our procedural field
  // resolves the levels in one shader instead of tens of thousands of CPU-
  // shaded billboards, but these authored colours provide the same readable
  // sunrise/sunset illumination.
  target.cloudLightColor
    .copy(CLOUD)
    .lerp(target.sunColor, 0.2 + twilightCloudLight * 0.62)
    .lerp(
      target.skyHorizonColor,
      twilightCloudLight * (0.18 + (twilightDrama - 1) * 0.22),
    );
  target.cloudShadowColor
    .copy(target.skyZenithColor)
    .lerp(target.cloudColor, 0.34)
    .lerp(NIGHT_SKY, night * 0.72)
    .multiplyScalar(0.68 + night * 0.1);

  target.seaDeepColor
    .copy(DEEP_SEA)
    .lerp(NIGHT_DEEP_SEA, night * 0.82)
    .lerp(COVERED_DEEP_SEA, weatherMood);
  target.seaMidColor
    .copy(MID_SEA)
    .lerp(NIGHT_MID_SEA, night * 0.78)
    .lerp(COVERED_MID_SEA, weatherMood);
  target.seaShallowColor
    .copy(SHALLOW_SEA)
    .lerp(NIGHT_SHALLOW_SEA, night * 0.72)
    .lerp(COVERED_SHALLOW_SEA, weatherMood);
  target.seaLightColor
    .copy(SEA_LIGHT)
    .lerp(EVENING_SUN, warmth * 0.18)
    .lerp(target.skyHorizonColor, twilightGlow * 0.34)
    .lerp(NIGHT_SEA_LIGHT, night * 0.74)
    .lerp(COVERED_SEA_LIGHT, weatherMood * 0.76);
  target.oceanCloudColor
    .copy(target.cloudColor)
    .lerp(target.skyHorizonColor, 0.24)
    .lerp(NIGHT_MID_SEA, night * 0.22);

  // Keep a sun that is actually touching the horizon atmospherically soft,
  // but let it reach full arctic glare within a few degrees. The earlier
  // 0.22 upper edge kept the disc grey until it was implausibly high.
  const sunVisibility = smoothstep(-0.025, 0.075, sunHeight);
  // `cloudCover` is a coverage forecast, not literal alpha. Mapping it
  // linearly to half opacity made fair-weather clouds indistinguishable from
  // the sky and medium cover look like vague colour noise. Preserve wisps at
  // low cover, then grow real readable bodies before the overcast end state.
  const readableCloudPresence = smoothstep(0.02, 0.34, cloud);
  target.cloudOpacity = clamp(
    cloud * (0.68 + fogFactor * 0.16) + readableCloudPresence * 0.16,
    0,
    0.99,
  );
  const oceanCloudAmount = smoothstep(0.14, 0.84, cloud);
  const windFactor = smoothstep(
    0.68,
    1.55,
    weather.windMultiplier,
  );
  target.oceanCloudAmount = oceanCloudAmount;
  target.oceanCloudScale =
    0.075 - oceanCloudAmount * 0.038 -
    weather.snowIntensity * 0.01;
  target.oceanCloudSpeed =
    0.018 + windFactor * 0.052;
  target.oceanCloudContrast = clamp(
    0.28 +
      oceanCloudAmount * 0.22 +
      weather.snowIntensity * 0.24 +
      fogFactor * 0.08,
    0.28,
    0.82,
  );
  target.haze = clamp(fogFactor * 0.82 + cloud * 0.18, 0, 1);
  const globalSolarCloudDimming = cloud * lerp(
    0.76,
    0.38,
    twilightCloudLight,
  );
  target.sunIntensity =
    sunVisibility * (0.7 + daylight * 0.34) * solarClarity *
    (1 - globalSolarCloudDimming) * (1 - solarEclipse * 0.94);
  target.moonIntensity = twinStars
    ? moonAboveHorizon *
      // Sirion's own light is not auto-exposed down when Aerion appears.
      // Their overlap is a real twinlight event; shadow budget, not a hidden
      // intensity compensation, decides which star owns the sharp shadow.
      0.82 *
      (1 - cloud * 0.62)
    : smoothstep(0.2, 0.86, night) * Math.pow(moonPhase, 1.35) *
      moonAboveHorizon * moonDarknessGate * (1 - cloud * 0.68) *
      lerp(1, 1.18, bloodMoon);
  target.celestialModel = celestialModel;
  target.sunAzimuth = sunAzimuth;
  target.sunHeight = sunHeight;
  target.sunDiscScale = twinStars
    // Aerion is intrinsically broader than the old sun. Atmospheric
    // magnification then swells it further while it touches the horizon.
    ? 1.2 * (1 + aerionHorizonWeight * 1.15)
    : 1;
  target.sunDiscIntensity = twinStars
    // Red/orange has lower perceived luminance than white. A restrained lift
    // preserves an equally brilliant surface while Aerion's hue deepens.
    ? 1.18 + aerionHorizonWeight * 0.3
    : clamp(0.72 + daylight * 0.36, 0.72, 1.08);
  target.moonPhase = moonPhase;
  target.moonAzimuth = resolvedMoonAzimuth;
  target.moonHeight = resolvedMoonHeight;
  target.moonDiscScale = twinStars
    // Sirion reads as a sharp, brilliant blue star, but stays visibly
    // smaller than Aerion throughout the complete orbit.
    ? 0.8 * (1 + moonHorizonWeight * 0.72)
    : 1;
  target.moonDiscIntensity = twinStars
    ? 0.96 + moonHorizonWeight * 0.18
    : target.moonIntensity;
  target.secondaryStar = twinStars;
  target.aerionCycleDay = twinCycle.aerionDay;
  target.sirionCycleDay = twinCycle.sirionDay;
  target.celestialOverlap = twinStars ? twinCycle.overlap : 0;
  target.celestialStoryName = twinStars
    ? twinCycle.storyName
    : 'Sun and moon';
  target.bloodMoon = bloodMoon;
  target.solarEclipse = solarEclipse;
  // Fog and a true white-out must materially shorten the readable horizon.
  // The previous compressed range made the dedicated fog profile barely
  // distinguishable from overcast weather in character view.
  // Clear air should reveal the macro landscape in perspective view. Weather
  // still owns a strong, readable horizon reduction instead of every day
  // looking like a permanent 200 metre fog bank.
  const snowfallVeil = Math.pow(
    smoothstep(0.08, 0.72, weather.snowIntensity),
    1.3,
  );
  const whiteoutVeil = smoothstep(
    0.68,
    0.98,
    weather.snowIntensity,
  );
  target.fogDensity =
    0.00052 + cloud * 0.00058 + fogFactor * 0.0068 +
    snowfallVeil * 0.0042 + whiteoutVeil * 0.024;
  target.iceContrast = clamp(weather.iceContrast, 0.75, 1.1);
  target.iceWarmth = clamp(
    warmth * 0.72 -
      cloud * 0.12 -
      weather.snowIntensity * 0.18,
    -1,
    1,
  );
  target.iceWetnessEmphasis = clamp(
    0.88 + weather.windMultiplier * 0.08 + fogFactor * 0.16,
    0.75,
    1.35,
  );
  target.iceSnowLightResponse = clamp(
    1.08 - cloud * 0.18 + daylight * 0.08,
    0.72,
    1.18,
  );
  target.starVisibility =
    day.starVisibility * starDarknessGate * (1 - cloud * 0.96) *
    (twinStars
      ? 1 - smoothstep(-0.13, 0.08, moonHeight) * 0.72
      : 1);
  // Aurora is a sky event rather than a nightly wallpaper. Two authored
  // nights in each seven-day span create an alternating four/three-night
  // cadence, while the continuous pulse lets each event breathe through the
  // night without an abrupt on/off switch.
  const auroraNight = isAuroraNight(dayIndex);
  const auroraNightPulse = 0.78 +
    Math.sin(absoluteDay * Math.PI * 2 * 1.37 + 0.64) * 0.16;
  const auroraCelestialGate = twinStars
    ? resolveTwinStarAuroraGate(
        twinCycle.aerionHeight,
        twinCycle.sirionHeight,
      )
    : 1;
  // Cloud optical depth already masks each aurora pixel in the sky shader.
  // Multiplying by both cloud-dimmed star visibility and (1-cloud) here made
  // otherwise valid events practically invisible under ordinary broken
  // cloud. Only a genuinely solid overcast now suppresses the whole event.
  const auroraOvercastGate = 1 - smoothstep(0.72, 0.98, cloud) * 0.94;
  target.auroraVisibility =
    day.starVisibility *
    smoothstep(0.48, 0.92, night) *
    (auroraNight ? auroraNightPulse : 0) *
    auroraCelestialGate *
    auroraOvercastGate *
    clamp(
      0.18 + (0.5 + Math.sin(dayIndex * 2.399 + 0.71) * 0.5) * 1.05 +
        (skyStory.id === 'MINT_AURORA' || skyStory.id === 'RUNE_VIOLET' ? 0.38 : 0),
      0,
      1,
    );
  target.artificialLight = day.artificialLight;
  target.daylight = daylight;
  target.night = night;
  target.twilight = twilight;
  target.warmth = warmth;
  target.skyStoryId = skyStory.id;
  target.skyStoryName = skyStory.name;
  target.skyBackdropId = weather.current === 'snowstorm' || weather.current === 'fog'
    ? 'PURE_SKY'
    : duskColorWeight > 0.42
      ? 'EVENING_FIELD'
      : skyStoryArrival < 0.999
        ? previousSkyStory.backdropId
        : skyStory.backdropId;
  return target;
};
