const smoothstepAudio = (
  minimum: number,
  maximum: number,
  value: number,
): number => {
  const amount = clamp(
    (value - minimum) / Math.max(0.0001, maximum - minimum),
    0,
    1,
  );
  return amount * amount * (3 - 2 * amount);
};

export interface WildernessDistanceAudioProfile {
  /** Perceptual distance attenuation before the authored source gain. */
  readonly audibility: number;
  /** Air absorption and shelter filtering meet at the lower cutoff. */
  readonly lowpassHz: number;
  /** Distant sources remain locatable without sounding hard-panned. */
  readonly panScale: number;
  /** Very near calls retain their attack; distance softens the transient. */
  readonly attackSeconds: number;
}

/**
 * Cheap world-space distance readability shared by wildlife calls and paws.
 * This is deliberately not a linear volume slider: high-frequency absorption,
 * softer attacks and a narrower stereo image make a far source read as far.
 */
export const resolveWildernessDistanceAudio = (
  distanceMetres: number,
  maximumDistanceMetres: number,
): WildernessDistanceAudioProfile => {
  const distance = Math.max(0, Number.isFinite(distanceMetres) ? distanceMetres : 0);
  const range = Math.max(2, maximumDistanceMetres);
  const nearness = 1 - smoothstepAudio(1.2, range, distance);
  const audibility = Math.pow(nearness, 1.28);
  return {
    audibility,
    lowpassHz: 780 + Math.pow(nearness, 0.72) * 17_220,
    panScale: 0.22 + nearness * 0.78,
    attackSeconds: (1 - nearness) * 0.055,
  };
};

