export type WildernessFireAudioKind = 'TORCH' | 'CAMPFIRE' | 'STRUCTURE';

export interface WildernessFireAudioEmitter {
  readonly id: string;
  readonly kind: WildernessFireAudioKind;
  readonly distance: number;
  readonly pan: number;
  readonly intensity: number;
  /** Connected burning build cells. One cell must never sound like a house fire. */
  readonly cells: number;
  /** Actual carried-torch motion, in metres per second. */
  readonly motion: number;
}

export interface WildernessFireAudioProfile {
  readonly gain: number;
  readonly maximumDistance: number;
  readonly lowpassHz: number;
  readonly playbackRate: number;
}

/**
 * Perceptual fire scale. Structural roar comes from connected burning area,
 * not merely from the existence of a burning flag, so a single floor cell
 * remains a small local flame while a spreading building becomes formidable.
 */
export const resolveWildernessFireAudioProfile = (
  emitter: Readonly<WildernessFireAudioEmitter>,
): WildernessFireAudioProfile => {
  const intensity = clamp(emitter.intensity, 0, 1);
  const cells = Math.max(1, Math.floor(emitter.cells));
  const motion = clamp(emitter.motion / 3.2, 0, 1);
  const kindScale = emitter.kind === 'TORCH'
    ? { gain: 0.044 + motion * 0.026, range: 13, rate: 1.05 + motion * 0.11 }
    : emitter.kind === 'CAMPFIRE'
      ? { gain: 0.105, range: 24, rate: 0.98 }
      : {
          // The first cell is deliberately campfire-sized. A real roar only
          // arrives after fire has crossed several structural boundaries.
          gain: 0.07 + smoothstepAudio(1, 10, cells) * 0.19,
          range: 20 + Math.sqrt(cells) * 5.2,
          rate: 0.96 - smoothstepAudio(1, 12, cells) * 0.08,
        };
  const distance = resolveWildernessDistanceAudio(
    emitter.distance,
    kindScale.range,
  );
  return {
    gain: kindScale.gain * (0.32 + intensity * 0.68) * distance.audibility,
    maximumDistance: kindScale.range,
    lowpassHz: Math.min(
      distance.lowpassHz,
      emitter.kind === 'TORCH' ? 13_500 : 16_500,
    ),
    playbackRate: kindScale.rate,
  };
};

interface WildernessFireAudioChannel {
  readonly kind: WildernessFireAudioKind;
  readonly source: AudioBufferSourceNode;
  readonly gain: GainNode;
  readonly pan: StereoPannerNode;
  readonly lowpass: BiquadFilterNode;
  ownerId?: string;
}

interface WildernessAnimalFootstepProfile {
  readonly strideMetres: number;
  readonly gain: number;
  readonly rate: number;
  readonly maximumDistance: number;
  readonly minimumRunSpeed: number;
}

export const resolveWildernessAnimalFootstepProfile = (
  species: string,
): WildernessAnimalFootstepProfile => {
  switch (species) {
    case 'RABBIT':
    case 'ARCTIC_HARE':
      return { strideMetres: 0.28, gain: 0.052, rate: 1.2, maximumDistance: 18, minimumRunSpeed: 0.68 };
    case 'FOX':
    case 'ARCTIC_FOX':
    case 'STOAT':
      return { strideMetres: 0.38, gain: 0.075, rate: 1.1, maximumDistance: 26, minimumRunSpeed: 0.76 };
    case 'WOLF':
    case 'LYNX':
    case 'WOLVERINE':
      return { strideMetres: 0.46, gain: 0.105, rate: 1.01, maximumDistance: 38, minimumRunSpeed: 0.82 };
    case 'DEER':
    case 'REINDEER':
      return { strideMetres: 0.52, gain: 0.115, rate: 1.06, maximumDistance: 44, minimumRunSpeed: 0.84 };
    case 'MOOSE':
    case 'MUSK_OX':
    case 'BISON':
      return { strideMetres: 0.64, gain: 0.18, rate: 0.86, maximumDistance: 58, minimumRunSpeed: 0.72 };
    case 'BEAR':
    case 'POLAR_BEAR':
    case 'WILD_BOAR':
      return { strideMetres: 0.6, gain: 0.17, rate: 0.82, maximumDistance: 54, minimumRunSpeed: 0.72 };
    default:
      return { strideMetres: 0.44, gain: 0.09, rate: 1, maximumDistance: 34, minimumRunSpeed: 0.8 };
  }
};

