import {
  Color,
  Vector3,
  type MeshStandardMaterial,
} from 'three';
import { WORLD_CLOUD_FIELD_GLSL } from '../environment/WorldCloudField';

export interface SnowSurfaceLighting {
  readonly timeSeconds: number;
  readonly sunDirection: Readonly<{ x: number; y: number; z: number }>;
  readonly moonDirection: Readonly<{ x: number; y: number; z: number }>;
  readonly sunColor: Readonly<Color>;
  readonly moonColor: Readonly<Color>;
  readonly sunStrength: number;
  readonly moonStrength: number;
  readonly cloudCover: number;
  readonly windDirectionX?: number;
  readonly windDirectionZ?: number;
  /** Normalized camera angular motion; view-dependent crystals flash on pan. */
  readonly cameraMotion?: number;
}

interface SnowUniform<T> {
  value: T;
}

/**
 * Adds sub-vertex crystalline grain to a normal MeshStandardMaterial.
 *
 * Snow mass and collision stay on their existing V3/V5 meshes; this is a
 * fragment-only layer, so it cannot introduce seams or simulation cost. The
 * two incommensurate world-space grain scales deliberately avoid lining up
 * with the 25/12.5/6.25 cm snow grids.
 */
export class SnowSurfaceMaterialController {
  private readonly time: SnowUniform<number> = { value: 0 };
  private readonly sunDirection: SnowUniform<Vector3> = {
    value: new Vector3(0, 1, 0),
  };
  private readonly moonDirection: SnowUniform<Vector3> = {
    value: new Vector3(0, 1, 0),
  };
  private readonly sunColor: SnowUniform<Color> = {
    value: new Color(0xfff5df),
  };
  private readonly moonColor: SnowUniform<Color> = {
    value: new Color(0xbfdcff),
  };
  private readonly sunStrength: SnowUniform<number> = { value: 0 };
  private readonly moonStrength: SnowUniform<number> = { value: 0 };
  private readonly cloudCover: SnowUniform<number> = { value: 0 };
  private readonly windDirection: SnowUniform<[number, number]> = {
    value: [1, 0],
  };
  private readonly cameraMotion: SnowUniform<number> = { value: 0 };
  private readonly authoringMode: SnowUniform<number> = { value: 0 };

  public constructor(
    material: MeshStandardMaterial,
    private readonly materialStrength = 1,
  ) {
    const previousCompile = material.onBeforeCompile;
    material.onBeforeCompile = (shader, renderer) => {
      previousCompile.call(material, shader, renderer);
      Object.assign(shader.uniforms, {
        uSnowCrystalTime: this.time,
        uSnowSunDirection: this.sunDirection,
        uSnowMoonDirection: this.moonDirection,
        uSnowSunColor: this.sunColor,
        uSnowMoonColor: this.moonColor,
        uSnowSunStrength: this.sunStrength,
        uSnowMoonStrength: this.moonStrength,
        uSnowCloudCover: this.cloudCover,
        uSnowWindDirection: this.windDirection,
        uSnowCameraMotion: this.cameraMotion,
        uSnowAuthoringMode: this.authoringMode,
      });
      shader.vertexShader = shader.vertexShader
        .replace(
          '#include <common>',
          `#include <common>
varying vec3 vSnowCrystalWorldPosition;
varying float vSnowCloudShadow;
uniform float uSnowCrystalTime;
uniform float uSnowCloudCover;
uniform vec2 uSnowWindDirection;
${WORLD_CLOUD_FIELD_GLSL}`,
        )
        .replace(
          '#include <project_vertex>',
          `
            vec4 snowCrystalWorldPosition = vec4(transformed, 1.0);
            #ifdef USE_INSTANCING
              snowCrystalWorldPosition = instanceMatrix * snowCrystalWorldPosition;
            #endif
            snowCrystalWorldPosition = modelMatrix * snowCrystalWorldPosition;
            vSnowCrystalWorldPosition = snowCrystalWorldPosition.xyz;
            vSnowCloudShadow = icewayWorldCloudShadow(
              vSnowCrystalWorldPosition.xz,
              uSnowCrystalTime,
              uSnowWindDirection,
              uSnowCloudCover
            );
            #include <project_vertex>
          `,
        );
      shader.fragmentShader = shader.fragmentShader
        .replace(
          '#include <common>',
          `
            #include <common>
            varying vec3 vSnowCrystalWorldPosition;
            varying float vSnowCloudShadow;
            uniform float uSnowCrystalTime;
            uniform vec3 uSnowSunDirection;
            uniform vec3 uSnowMoonDirection;
            uniform vec3 uSnowSunColor;
            uniform vec3 uSnowMoonColor;
            uniform float uSnowSunStrength;
            uniform float uSnowMoonStrength;
            uniform float uSnowCloudCover;
            uniform float uSnowCameraMotion;
            uniform float uSnowAuthoringMode;

            float snowCrystalHash(vec3 point) {
              point = fract(point * 0.1031);
              point += dot(point, point.yzx + 33.33);
              return fract((point.x + point.y) * point.z);
            }

            float snowSmoothNoise(vec2 point, float seed) {
              vec2 cell = floor(point);
              vec2 local = fract(point);
              local = local * local * (3.0 - 2.0 * local);
              float a = snowCrystalHash(vec3(cell.x, seed, cell.y));
              float b = snowCrystalHash(vec3(cell.x + 1.0, seed, cell.y));
              float c = snowCrystalHash(vec3(cell.x, seed, cell.y + 1.0));
              float d = snowCrystalHash(vec3(cell.x + 1.0, seed, cell.y + 1.0));
              return mix(mix(a, b, local.x), mix(c, d, local.x), local.y);
            }

            float snowCrystalPoint(
              vec2 worldPoint,
              float frequency,
              float seed,
              float pointRadius,
              float densityThreshold,
              out float crystalSeed
            ) {
              vec2 lattice = worldPoint * frequency;
              vec2 cell = floor(lattice);
              vec2 local = fract(lattice);
              crystalSeed = snowCrystalHash(vec3(cell.x, seed, cell.y));
              vec2 offset = vec2(
                snowCrystalHash(vec3(cell.x + 17.3, seed + 2.7, cell.y)),
                snowCrystalHash(vec3(cell.x, seed + 9.1, cell.y + 31.7))
              );
              offset = 0.14 + offset * 0.72;
              float pointDistance = length(local - offset);
              // Give a physical millimetre-scale crystal at least a fraction
              // of one pixel of derivative coverage. The former 0.3 mm mask
              // almost never contained a pixel centre and was functionally
              // invisible even though the shader was running correctly.
              float pointWidth = max(fwidth(pointDistance), 0.003);
              float readableRadius = max(
                pointRadius,
                pointWidth * 0.48
              );
              float tinyPoint = 1.0 - smoothstep(
                readableRadius,
                readableRadius + pointWidth * 0.82,
                pointDistance
              );
              return tinyPoint * smoothstep(
                densityThreshold,
                min(0.998, densityThreshold + 0.12),
                crystalSeed
              );
            }
          `,
        )
        .replace(
          '#include <color_fragment>',
          `
            #include <color_fragment>
            // V3 stores subtle cellular tint in vertex colours. It is useful
            // close up, but past the readable interaction range it formerly
            // resolved as a large Voronoi net. Return smoothly toward the
            // material's neutral snow colour while retaining geometry/light.
            float snowColourDistance = distance(
              cameraPosition,
              vSnowCrystalWorldPosition
            );
            float snowCellularDistanceFade = smoothstep(
              8.0,
              34.0,
              snowColourDistance
            );
            diffuseColor.rgb = mix(
              diffuseColor.rgb,
              diffuse,
              snowCellularDistanceFade * 0.985
            );
            diffuseColor.rgb = mix(
              diffuseColor.rgb,
              vec3(0.82, 0.86, 0.89),
              uSnowAuthoringMode
            );
          `,
        )
        .replace(
          '#include <normal_fragment_maps>',
          `
            #include <normal_fragment_maps>
            vec3 snowBaseWorldNormal = normalize(
              inverseTransformDirection(normal, viewMatrix)
            );
            float snowMicroNormalFade = 1.0 - smoothstep(
              7.0,
              30.0,
              distance(cameraPosition, vSnowCrystalWorldPosition)
            );
            // Retain the readable powder facets from the earlier material,
            // but make their cells roughly 35% smaller. The geometry remains
            // smooth; this is a lighting normal only and cannot form seams.
            vec3 snowNormalCellA = floor(
              vSnowCrystalWorldPosition * vec3(18.6, 28.7, 23.1)
            );
            vec3 snowNormalCellB = floor(
              vSnowCrystalWorldPosition * vec3(43.2, 65.4, 52.8)
            );
            vec3 snowMicroWorldNormal = normalize(
              snowBaseWorldNormal + vec3(
                snowCrystalHash(snowNormalCellA + 2.7) - 0.5,
                0.0,
                snowCrystalHash(snowNormalCellB + 8.9) - 0.5
              ) * 0.076 * snowMicroNormalFade
            );
            normal = normalize(
              mat3(viewMatrix) * snowMicroWorldNormal
            );
          `,
        )
        .replace(
          '#include <opaque_fragment>',
          `
            vec3 snowWorldNormal = normalize(
              inverseTransformDirection(normal, viewMatrix)
            );
            vec3 snowViewDirection = normalize(
              cameraPosition - vSnowCrystalWorldPosition
            );
            vec3 snowCellFine = floor(
              vSnowCrystalWorldPosition * vec3(17.3, 23.7, 19.1)
            );
            vec3 snowCellMicro = floor(
              vSnowCrystalWorldPosition * vec3(41.7, 53.1, 37.9)
            );
            float snowGrainA = snowCrystalHash(snowCellFine);
            float snowGrainB = snowCrystalHash(snowCellMicro + 17.31);
            float snowGrain = snowGrainA * 0.58 + snowGrainB * 0.42;
            float snowGrainFade = 1.0 - smoothstep(
              8.0,
              32.0,
              snowColourDistance
            );
            float snowFacetAzimuth = snowCrystalHash(
              snowCellMicro + 3.1
            ) * 6.2831853;
            float snowFacetLift = mix(
              0.16,
              0.96,
              snowCrystalHash(snowCellFine + 7.9)
            );
            float snowFacetHorizontal = sqrt(max(
              0.0,
              1.0 - snowFacetLift * snowFacetLift
            ));
            vec3 snowFacet = normalize(vec3(
              cos(snowFacetAzimuth) * snowFacetHorizontal,
              snowFacetLift,
              sin(snowFacetAzimuth) * snowFacetHorizontal
            ));
            snowFacet = normalize(mix(snowWorldNormal, snowFacet, 0.82));
            vec3 snowSunHalf = normalize(
              normalize(uSnowSunDirection) + snowViewDirection
            );
            vec3 snowMoonHalf = normalize(
              normalize(uSnowMoonDirection) + snowViewDirection
            );
            float snowSunGlint = pow(max(
              dot(snowFacet, snowSunHalf),
              0.0
            ), 28.0);
            float snowMoonGlint = pow(max(
              dot(snowFacet, snowMoonHalf),
              0.0
            ), 38.0);
            float snowCrystalSeedA = 0.0;
            float snowCrystalSeedB = 0.0;
            float snowCrystalSeedC = 0.0;
            float snowTinyCrystalA = snowCrystalPoint(
              vSnowCrystalWorldPosition.xz,
              46.0,
              3.7,
              0.1,
              0.56,
              snowCrystalSeedA
            );
            float snowTinyCrystalB = snowCrystalPoint(
              vSnowCrystalWorldPosition.xz + vec2(7.31, -4.19),
              83.0,
              11.9,
              0.075,
              0.64,
              snowCrystalSeedB
            );
            float snowReadableCrystal = snowCrystalPoint(
              vSnowCrystalWorldPosition.xz + vec2(-2.71, 9.43),
              21.0,
              23.1,
              0.17,
              0.86,
              snowCrystalSeedC
            );
            float snowFlashSeed = 0.0;
            float snowFlashCrystal = snowCrystalPoint(
              vSnowCrystalWorldPosition.xz + vec2(13.17, -8.63),
              8.5,
              41.7,
              0.19,
              0.91,
              snowFlashSeed
            );
            float snowGrazingCoreSeed = 0.0;
            float snowGrazingGlowSeed = 0.0;
            float snowGrazingCore = snowCrystalPoint(
              vSnowCrystalWorldPosition.xz + vec2(-19.41, 14.73),
              4.8,
              67.3,
              0.105,
              0.935,
              snowGrazingCoreSeed
            );
            float snowGrazingGlow = snowCrystalPoint(
              vSnowCrystalWorldPosition.xz + vec2(-19.41, 14.73),
              4.8,
              67.3,
              0.34,
              0.935,
              snowGrazingGlowSeed
            );
            float snowUpperSurface = smoothstep(0.18, 0.82, snowWorldNormal.y);
            float snowCloudComfort = mix(
              1.0,
              0.34,
              clamp(uSnowCloudCover, 0.0, 1.0)
            );
            float snowCameraSparkleMotion = smoothstep(
              0.015,
              0.62,
              clamp(uSnowCameraMotion, 0.0, 1.0)
            );
            float snowPulseA = 0.025 + 0.975 * pow(max(0.0, sin(
              uSnowCrystalTime * (3.1 + snowCrystalSeedA * 3.2) +
              snowCrystalSeedA * 41.0
            )), 4.0);
            float snowPulseB = 0.02 + 0.98 * pow(max(0.0, sin(
              uSnowCrystalTime * (4.0 + snowCrystalSeedB * 3.7) +
              snowCrystalSeedB * 57.0
            )), 5.0);
            float snowPulseC = pow(max(0.0, sin(
              uSnowCrystalTime * (2.25 + snowCrystalSeedC * 1.8) +
              snowCrystalSeedC * 73.0
            )), 7.0);
            // Crystal selection belongs to the world-space snow, not to the
            // clock. At rest most points remain stable and only a small micro
            // component twinkles. Camera movement progressively releases the
            // view-dependent pulses; sun motion already changes the physical
            // half-vector without randomly relocating the largest crystals.
            float snowTwinkleA = mix(
              0.34 + snowCrystalSeedA * 0.24,
              snowPulseA,
              0.025 + snowCameraSparkleMotion * 0.8
            );
            float snowTwinkleB = mix(
              0.3 + snowCrystalSeedB * 0.22,
              snowPulseB,
              0.032 + snowCameraSparkleMotion * 0.79
            );
            float snowTwinkleC = mix(
              0.26 + snowCrystalSeedC * 0.34,
              snowPulseC,
              0.008 + snowCameraSparkleMotion * 0.9
            );
            // Weather changes overall crystal brightness patiently; it no
            // longer rerolls the complete sparkling field every few seconds.
            float snowSparkleStoryAnimated = 0.78 + 0.22 * pow(
              0.5 + 0.5 * sin(uSnowCrystalTime * 0.067 + 1.8),
              3.0
            );
            float snowSparkleStory = mix(
              0.965,
              snowSparkleStoryAnimated,
              0.035 + snowCameraSparkleMotion * 0.72
            );
            float snowSunFacing = max(dot(
              snowWorldNormal,
              normalize(uSnowSunDirection)
            ), 0.0);
            float snowMoonFacing = max(dot(
              snowWorldNormal,
              normalize(uSnowMoonDirection)
            ), 0.0);
            float snowSunLight = uSnowSunStrength * snowSunFacing;
            float snowMoonLight = uSnowMoonStrength * snowMoonFacing;
            // A sparkle is a direct-light event. Adding it after Three's
            // standard lighting made it easiest to see against dark shadow,
            // which inverted the real-world read. Reuse the material's actual
            // per-fragment direct result so tree and terrain shadows suppress
            // crystals while lit powder keeps them.
            float snowDirectEnergy = dot(
              reflectedLight.directDiffuse + reflectedLight.directSpecular,
              vec3(0.2126, 0.7152, 0.0722)
            );
            float snowDirectVisibility = smoothstep(
              0.00035,
              0.052,
              snowDirectEnergy
            );
            // PCF-filtered branch gaps can carry only a small fraction of the
            // open-field direct energy. Preserve those real pinholes while a
            // fully shadowed fragment still remains below the lower edge.
            snowDirectVisibility = pow(snowDirectVisibility, 0.72);
            snowDirectVisibility *= 1.0 - uSnowAuthoringMode;
            float snowSunViewAlignment = max(dot(
              -snowViewDirection,
              normalize(uSnowSunDirection)
            ), 0.0);
            float snowMoonViewAlignment = max(dot(
              -snowViewDirection,
              normalize(uSnowMoonDirection)
            ), 0.0);
            float snowSunViewWindow = smoothstep(
              0.35,
              0.9,
              snowSunViewAlignment
            );
            float snowMoonViewWindow = smoothstep(
              0.42,
              0.92,
              snowMoonViewAlignment
            );
            float snowLowSunBoost = mix(
              1.0,
              1.85,
              1.0 - smoothstep(
                0.08,
                0.58,
                max(uSnowSunDirection.y, 0.0)
              )
            );
            vec3 snowCrystalLight =
              uSnowSunColor * snowSunLight * snowSunViewWindow *
                snowLowSunBoost * (0.42 + snowSunGlint * 1.9) +
              uSnowMoonColor * snowMoonLight *
                snowMoonViewWindow * (0.22 + snowMoonGlint * 1.35);
            float snowSparkle = (
              snowTinyCrystalA * snowTwinkleA +
              snowTinyCrystalB * snowTwinkleB * 0.8 +
              snowReadableCrystal * snowTwinkleC * 1.42
            ) * snowUpperSurface * snowCloudComfort * snowSparkleStory;
            float snowFlashPulseAnimated = pow(max(0.0, sin(
              uSnowCrystalTime * (2.8 + snowFlashSeed * 2.4) +
              snowFlashSeed * 91.0
            )), 9.0);
            float snowFlashPulse = mix(
              0.38 + snowFlashSeed * 0.34,
              snowFlashPulseAnimated,
              0.006 + snowCameraSparkleMotion * 0.96
            );
            float snowViewFlash =
              snowSunGlint * snowSunGlint * snowSunViewWindow +
              snowMoonGlint * snowMoonGlint * snowMoonViewWindow * 0.62;
            float snowLargeFlash = snowFlashCrystal * snowFlashPulse *
              snowViewFlash * (1.02 + snowCameraSparkleMotion * 2.75) *
              snowUpperSurface * snowCloudComfort;
            // Rare larger crystals flare when the view skims the snow toward
            // a low sun. A stable world-space core and a soft halo make the
            // flash readable without adding geometry or rerolling while the
            // camera is still.
            float snowGrazingView = smoothstep(
              0.46,
              0.9,
              1.0 - abs(dot(snowWorldNormal, snowViewDirection))
            );
            float snowLowSunWindow = 1.0 - smoothstep(
              0.2,
              0.68,
              max(uSnowSunDirection.y, 0.0)
            );
            float snowGrazingSunWindow = smoothstep(
              0.7,
              0.985,
              snowSunViewAlignment
            ) * snowGrazingView * snowLowSunWindow;
            float snowGrazingPulseAnimated = pow(max(0.0, sin(
              uSnowCrystalTime * (1.65 + snowGrazingCoreSeed * 1.2) +
              snowGrazingCoreSeed * 83.0
            )), 7.0);
            float snowGrazingPulse = mix(
              0.52 + snowGrazingCoreSeed * 0.28,
              snowGrazingPulseAnimated,
              0.012 + snowCameraSparkleMotion * 0.88
            );
            float snowGrazingFlash = (
              snowGrazingCore * 1.72 + snowGrazingGlow * 0.22
            ) * snowGrazingPulse * snowGrazingSunWindow *
              snowUpperSurface * snowCloudComfort;
            float snowCloudShadow = clamp(vSnowCloudShadow, 0.0, 1.0) *
              (1.0 - uSnowAuthoringMode);
            float snowCloudTransmission = 1.0 - snowCloudShadow *
              (0.16 + clamp(uSnowCloudCover, 0.0, 1.0) * 0.34);
            outgoingLight *= 0.993 +
              (snowGrain - 0.5) * 0.024 * snowGrainFade;
            outgoingLight *= snowCloudTransmission;
            outgoingLight += snowCrystalLight * snowSparkle *
              snowDirectVisibility * snowCloudTransmission *
              ${(4.65 * materialStrength).toFixed(4)};
            outgoingLight += (
              uSnowSunColor * snowSunLight * snowLowSunBoost +
              uSnowMoonColor * snowMoonLight * 0.72
            ) * snowLargeFlash * snowDirectVisibility *
              snowCloudTransmission *
              ${(8.4 * materialStrength).toFixed(4)};
            outgoingLight += uSnowSunColor * snowSunLight *
              snowGrazingFlash * snowDirectVisibility *
              snowCloudTransmission *
              ${(11.2 * materialStrength).toFixed(4)};
            #include <opaque_fragment>
          `,
        );
    };
    const previousCacheKey = material.customProgramCacheKey.bind(material);
    material.customProgramCacheKey = () =>
      `${previousCacheKey()}|iceway-snow-crystals-v6-vertex-clouds-${materialStrength}`;
    material.needsUpdate = true;
  }

  public update(input: Readonly<SnowSurfaceLighting>): void {
    this.time.value = Math.max(0, input.timeSeconds);
    this.sunDirection.value.copy(input.sunDirection).normalize();
    this.moonDirection.value.copy(input.moonDirection).normalize();
    this.sunColor.value.copy(input.sunColor);
    this.moonColor.value.copy(input.moonColor);
    this.sunStrength.value = Math.max(0, input.sunStrength);
    this.moonStrength.value = Math.max(0, input.moonStrength);
    this.cloudCover.value = Math.max(0, Math.min(1, input.cloudCover));
    const windX = input.windDirectionX ?? 1;
    const windZ = input.windDirectionZ ?? 0;
    const windLength = Math.max(0.0001, Math.hypot(windX, windZ));
    this.windDirection.value[0] = windX / windLength;
    this.windDirection.value[1] = windZ / windLength;
    this.cameraMotion.value = Math.max(
      0,
      Math.min(1, input.cameraMotion ?? 0),
    );
  }

  public setAuthoringMode(active: boolean): void {
    this.authoringMode.value = active ? 1 : 0;
  }
}
