import {
  BoxGeometry,
  BufferGeometry,
  Color,
  Float32BufferAttribute,
  Group,
  InstancedMesh,
  Mesh,
  MeshStandardMaterial,
  Object3D,
  type Scene,
} from 'three';
import {
  ICEAWAY_PROTOTYPE_WORLD_ORIGIN,
} from '../world/PrototypeWorldPositionAdapter';
import type {
  RuntimeWorldChunkDescriptor,
  RuntimeWorldChunkListener,
} from '../world/RuntimeWorldChunks';
import { ICEAWAY_TARGET_WORLD_PARTITION } from '../world/WorldPartitionTypes';
import {
  BOREALIS_GROUND_HEIGHT,
  BOREALIS_WORKSHOP_SNOWFIELD,
  borealisCoastX,
} from './BorealisLand';
import {
  TERRAIN_GRID_METRES,
  type TerrainEditBounds,
  type TerrainHeightSystem,
} from './TerrainHeightSystem';
import { WORLD_CLOUD_FIELD_GLSL } from '../environment/WorldCloudField';

interface PrototypeChunkBounds {
  minX: number;
  maxX: number;
  minZ: number;
  maxZ: number;
}

type MainlandDynamicExclusionSampler = (x: number, z: number) => boolean;

interface MainlandDynamicExclusionBounds {
  readonly minX: number;
  readonly maxX: number;
  readonly minZ: number;
  readonly maxZ: number;
}

const TERRAIN_CUTOUT_GRID_METRES = 0.125;

const chunkKey = (x: number, z: number): string => `${x},${z}`;

export const prototypeBoundsForChunk = (
  chunkX: number,
  chunkZ: number,
): PrototypeChunkBounds => {
  const size = ICEAWAY_TARGET_WORLD_PARTITION.chunkSizeMetres;
  const minX =
    (chunkX - ICEAWAY_PROTOTYPE_WORLD_ORIGIN.chunk.x) * size -
    ICEAWAY_PROTOTYPE_WORLD_ORIGIN.local.xMetres;
  const minZ =
    (chunkZ - ICEAWAY_PROTOTYPE_WORLD_ORIGIN.chunk.z) * size -
    ICEAWAY_PROTOTYPE_WORLD_ORIGIN.local.zMetres;
  return {
    minX,
    maxX: minX + size,
    minZ,
    maxZ: minZ + size,
  };
};

export class BorealisMainlandRenderer
  implements RuntimeWorldChunkListener
{
  private static readonly MAXIMUM_CACHED_CHUNKS = 32;
  private readonly root = new Group();
  private readonly chunks = new Map<string, {
    root: Group;
    descriptor: Readonly<RuntimeWorldChunkDescriptor>;
  }>();
  private readonly cachedChunks = new Map<string, {
    root: Group;
    descriptor: Readonly<RuntimeWorldChunkDescriptor>;
  }>();
  private readonly groundMaterial = new MeshStandardMaterial({
    color: new Color(0xdbe9e7),
    vertexColors: true,
    roughness: 0.97,
    metalness: 0,
  });
  private readonly coastMaterial = new MeshStandardMaterial({
    color: new Color(0xffffff),
    vertexColors: true,
    roughness: 0.9,
    metalness: 0,
  });
  private readonly cliffMaterial = new MeshStandardMaterial({
    color: new Color(0x71807a),
    vertexColors: true,
    roughness: 0.98,
    metalness: 0,
  });
  private readonly curbMaterial = new MeshStandardMaterial({
    color: new Color(0x737b7e),
    roughness: 0.94,
    metalness: 0.01,
  });
  private readonly markerMaterial = new MeshStandardMaterial({
    color: new Color(0xf0b84e),
    emissive: new Color(0x5e3608),
    emissiveIntensity: 0.32,
    roughness: 0.68,
    metalness: 0.05,
  });
  private readonly cloudTime = { value: 0 };
  private readonly cloudCover = { value: 0 };
  private readonly cloudDirection = { value: [1, 0] as [number, number] };
  private workshopMarker?: Group;
  private readonly removeTerrainListener: () => void;
  private dynamicExclusionSampler?: MainlandDynamicExclusionSampler;
  private dynamicExclusionBounds?: MainlandDynamicExclusionBounds;

  public constructor(
    scene: Scene,
    private readonly terrain: TerrainHeightSystem,
  ) {
    this.root.name = 'Borealis western mainland chunks';
    for (const material of [
      this.groundMaterial,
      this.coastMaterial,
      this.cliffMaterial,
      this.curbMaterial,
    ]) this.configureCloudShadows(material);
    scene.add(this.root);
    this.removeTerrainListener = this.terrain.addListener((bounds) =>
      this.refreshEditedChunks(bounds),
    );
  }

  public setCloudShadows(
    timeSeconds: number,
    cloudCover: number,
    directionX: number,
    directionZ: number,
  ): void {
    const length = Math.max(0.0001, Math.hypot(directionX, directionZ));
    this.cloudTime.value = Math.max(0, timeSeconds);
    this.cloudCover.value = Math.max(0, Math.min(1, cloudCover));
    this.cloudDirection.value[0] = directionX / length;
    this.cloudDirection.value[1] = directionZ / length;
  }

  public onChunkActivated(
    chunk: Readonly<RuntimeWorldChunkDescriptor>,
  ): void {
    if (
      chunk.kind !== 'WESTERN_MAINLAND' &&
      chunk.kind !== 'BOREALIS_COAST'
    ) {
      return;
    }
    const key = chunkKey(chunk.address.x, chunk.address.z);
    if (this.chunks.has(key)) return;
    const cached = this.cachedChunks.get(key);
    if (cached) {
      this.cachedChunks.delete(key);
      this.chunks.set(key, cached);
      this.root.add(cached.root);
      return;
    }
    const active = { root: this.createChunk(chunk), descriptor: chunk };
    this.chunks.set(key, active);
    this.root.add(active.root);
  }

  public onChunkDeactivated(
    chunk: Readonly<RuntimeWorldChunkDescriptor>,
  ): void {
    const key = chunkKey(chunk.address.x, chunk.address.z);
    const active = this.chunks.get(key);
    if (!active) return;
    this.chunks.delete(key);
    this.root.remove(active.root);
    this.cacheChunk(key, active);
  }

  public onChunkPreloaded(
    chunk: Readonly<RuntimeWorldChunkDescriptor>,
  ): void {
    if (
      chunk.kind !== 'WESTERN_MAINLAND' &&
      chunk.kind !== 'BOREALIS_COAST'
    ) {
      return;
    }
    const key = chunkKey(chunk.address.x, chunk.address.z);
    if (this.chunks.has(key) || this.cachedChunks.has(key)) return;
    this.cacheChunk(key, {
      root: this.createChunk(chunk),
      descriptor: chunk,
    });
  }

  public getActiveChunkCount(): number {
    return this.chunks.size;
  }

  public getCachedChunkCount(): number {
    return this.cachedChunks.size;
  }

  public setExpeditionActive(active: boolean): void {
    if (this.workshopMarker) this.workshopMarker.visible = active;
  }

  /**
   * The streamed mainland normally remains resident even outside the legacy
   * expedition. A flat authored workspace must be able to suppress that
   * ground as well, otherwise one Borealis-shaped island leaks through the
   * otherwise empty map.
   */
  public setPresentationVisible(visible: boolean): void {
    this.root.visible = visible;
  }

  /**
   * Cuts authored ground triangles above excavated shafts. Snow has its own
   * matching exclusion, but without this aperture the pale terrain top still
   * looked like a horizontal snow sheet filling the cave below.
   */
  public setDynamicExclusionSampler(
    sampler: MainlandDynamicExclusionSampler | undefined,
    bounds?: Readonly<MainlandDynamicExclusionBounds>,
  ): void {
    this.dynamicExclusionSampler = sampler;
    this.dynamicExclusionBounds = bounds ? { ...bounds } : undefined;
    if (bounds) this.refreshDynamicExclusion(bounds);
  }

  public refreshDynamicExclusion(
    bounds: Readonly<MainlandDynamicExclusionBounds>,
  ): void {
    this.dynamicExclusionBounds = { ...bounds };
    for (const active of this.chunks.values()) {
      const chunkBounds = prototypeBoundsForChunk(
        active.descriptor.address.x,
        active.descriptor.address.z,
      );
      if (!this.boundsIntersect(chunkBounds, bounds)) continue;
      const top = active.root.getObjectByName('Borealis terrain top');
      if (!(top instanceof Mesh)) continue;
      const previous = top.geometry;
      top.geometry = this.createTopGeometry(chunkBounds);
      previous.dispose();
    }
    for (const [key, cached] of [...this.cachedChunks]) {
      const chunkBounds = prototypeBoundsForChunk(
        cached.descriptor.address.x,
        cached.descriptor.address.z,
      );
      if (!this.boundsIntersect(chunkBounds, bounds)) continue;
      this.cachedChunks.delete(key);
      this.disposeChunk(cached);
    }
  }

  public dispose(): void {
    this.removeTerrainListener();
    for (const active of this.chunks.values()) {
      this.root.remove(active.root);
      this.disposeChunk(active);
    }
    this.chunks.clear();
    for (const cached of this.cachedChunks.values()) {
      this.disposeChunk(cached);
    }
    this.cachedChunks.clear();
    this.groundMaterial.dispose();
    this.coastMaterial.dispose();
    this.cliffMaterial.dispose();
    this.curbMaterial.dispose();
    this.markerMaterial.dispose();
    this.root.removeFromParent();
  }

  private createChunk(
    chunk: Readonly<RuntimeWorldChunkDescriptor>,
  ): Group {
    const chunkBounds = prototypeBoundsForChunk(
      chunk.address.x,
      chunk.address.z,
    );
    const bounds = chunkBounds;
    const group = new Group();
    group.name = `World chunk ${chunk.address.x},${chunk.address.z} ${chunk.kind}`;
    const top = new Mesh(
      this.createTopGeometry(bounds),
      this.groundMaterial,
    );
    top.name = 'Borealis terrain top';
    top.receiveShadow = true;
    top.castShadow = true;
    group.add(top);

    if (chunk.kind === 'BOREALIS_COAST') {
      const coast = new Mesh(
        this.createCoastGeometry(bounds),
        this.coastMaterial,
      );
      coast.receiveShadow = true;
      coast.castShadow = true;
      group.add(coast);
    }
    const cliffs = new Mesh(
      this.createCliffGeometry(bounds),
      this.cliffMaterial,
    );
    cliffs.name = 'Authored terrain cliff faces';
    cliffs.receiveShadow = true;
    cliffs.castShadow = true;
    group.add(cliffs);
    const curbs = new Mesh(
      this.createCurbGeometry(bounds),
      this.curbMaterial,
    );
    curbs.name = 'Raised sidewalk curb faces';
    curbs.receiveShadow = true;
    curbs.castShadow = true;
    group.add(curbs);
    this.addLandmarks(group, bounds);
    return group;
  }

  private configureCloudShadows(material: MeshStandardMaterial): void {
    const previousCompile = material.onBeforeCompile;
    material.onBeforeCompile = (shader, renderer) => {
      previousCompile.call(material, shader, renderer);
      shader.uniforms.uLandCloudTime = this.cloudTime;
      shader.uniforms.uLandCloudCover = this.cloudCover;
      shader.uniforms.uLandCloudDirection = this.cloudDirection;
      shader.vertexShader = shader.vertexShader
        .replace(
          '#include <common>',
          `#include <common>
varying float vLandCloudShadow;
uniform float uLandCloudTime;
uniform float uLandCloudCover;
uniform vec2 uLandCloudDirection;
${WORLD_CLOUD_FIELD_GLSL}`,
        )
        .replace(
          '#include <project_vertex>',
          `
            vec3 landCloudWorldPosition =
              (modelMatrix * vec4(transformed, 1.0)).xyz;
            vLandCloudShadow = icewayWorldCloudShadow(
              landCloudWorldPosition.xz,
              uLandCloudTime,
              uLandCloudDirection,
              uLandCloudCover
            );
            #include <project_vertex>
          `,
        );
      shader.fragmentShader = shader.fragmentShader
        .replace(
          '#include <common>',
          `
            #include <common>
            varying float vLandCloudShadow;
            uniform float uLandCloudCover;
          `,
        )
        .replace(
          '#include <opaque_fragment>',
          `
            float landCloudShadow = clamp(vLandCloudShadow, 0.0, 1.0);
            outgoingLight *= 1.0 - landCloudShadow *
              (0.16 + clamp(uLandCloudCover, 0.0, 1.0) * 0.34);
            #include <opaque_fragment>
          `,
        );
    };
    const previousCacheKey = material.customProgramCacheKey.bind(material);
    material.customProgramCacheKey = () =>
      `${previousCacheKey()}|iceway-world-cloud-shadow-v2-vertex`;
    material.needsUpdate = true;
  }

  private createTopGeometry(bounds: PrototypeChunkBounds): BufferGeometry {
    const minGridX = Math.floor(bounds.minX / TERRAIN_GRID_METRES);
    const maxGridX = Math.ceil(bounds.maxX / TERRAIN_GRID_METRES) - 1;
    const minGridZ = Math.floor(bounds.minZ / TERRAIN_GRID_METRES);
    const maxGridZ = Math.ceil(bounds.maxZ / TERRAIN_GRID_METRES) - 1;
    const positions: number[] = [];
    const normals: number[] = [];
    const colors: number[] = [];
    const indices: number[] = [];
    const normalCache = new Map<string, readonly [number, number, number]>();
    for (let gridZ = minGridZ; gridZ <= maxGridZ; gridZ += 1) {
      for (let gridX = minGridX; gridX <= maxGridX; gridX += 1) {
        const centerX = gridX * TERRAIN_GRID_METRES;
        const centerZ = gridZ * TERRAIN_GRID_METRES;
        if (centerX > borealisCoastX(centerZ)) continue;
        const halfGrid = TERRAIN_GRID_METRES * 0.5;
        if (this.shouldSubdivideForDynamicExclusion(
          centerX - halfGrid,
          centerX + halfGrid,
          centerZ - halfGrid,
          centerZ + halfGrid,
        )) {
          this.appendSubdividedTerrainCell(
            centerX,
            centerZ,
            positions,
            normals,
            colors,
            indices,
            normalCache,
          );
          continue;
        }
        const centerHeight = this.terrain.sampleNodeHeight(gridX, gridZ);
        const surfaceMaterial = this.terrain.sampleMaterial(centerX, centerZ);
        const corners = [
          { dx: -1, dz: -1, xEdge: 'W' as const, zEdge: 'N' as const },
          { dx: 1, dz: -1, xEdge: 'E' as const, zEdge: 'N' as const },
          { dx: -1, dz: 1, xEdge: 'W' as const, zEdge: 'S' as const },
          { dx: 1, dz: 1, xEdge: 'E' as const, zEdge: 'S' as const },
        ];
        const base = positions.length / 3;
        let minimumNormalY = 1;
        for (const corner of corners) {
          const z = centerZ + corner.dz * TERRAIN_GRID_METRES * 0.5;
          const rawX = centerX + corner.dx * TERRAIN_GRID_METRES * 0.5;
          const x = Math.min(rawX, borealisCoastX(z) - 0.12);
          const hardEdge =
            this.terrain.isCliffEdge(gridX, gridZ, corner.xEdge) ||
            this.terrain.isCliffEdge(gridX, gridZ, corner.zEdge) ||
            this.terrain.isRaisedSurfaceBoundary(gridX, gridZ, corner.xEdge) ||
            this.terrain.isRaisedSurfaceBoundary(gridX, gridZ, corner.zEdge);
          const height = hardEdge
            ? centerHeight
            : this.terrain.sampleHeight(x, z);
          positions.push(x, height - 0.035, z);
          const normal = hardEdge
            ? [0, 1, 0] as const
            : this.sampleCachedTerrainNormal(x, z, normalCache);
          normals.push(normal[0], normal[1], normal[2]);
          minimumNormalY = Math.min(minimumNormalY, normal[1]);
        }
        const elevation = clamp01((centerHeight - BOREALIS_GROUND_HEIGHT) / 80);
        const steep = clamp01(Math.acos(clamp01(minimumNormalY)) / 0.72);
        const baseColor = surfaceMaterial === 'ROCK'
          ? [0.46, 0.5, 0.48]
          : surfaceMaterial === 'DIRT'
            ? [0.4, 0.32, 0.24]
            : surfaceMaterial === 'ROAD'
              ? [0.2, 0.22, 0.22]
              : surfaceMaterial === 'SIDEWALK'
                ? [0.46, 0.49, 0.5]
              : surfaceMaterial === 'SNOW_EXCLUSION'
                ? [0.32, 0.37, 0.35]
                : [0.84, 0.9, 0.88];
        for (let vertex = 0; vertex < 4; vertex += 1) {
          colors.push(
            (baseColor[0] ?? 0.84) - elevation * 0.16 - steep * 0.1,
            (baseColor[1] ?? 0.9) - elevation * 0.14 - steep * 0.09,
            (baseColor[2] ?? 0.88) - elevation * 0.16 - steep * 0.1,
          );
        }
        indices.push(base, base + 2, base + 1, base + 1, base + 2, base + 3);
      }
    }
    const geometry = new BufferGeometry();
    geometry.setAttribute('position', new Float32BufferAttribute(positions, 3));
    geometry.setAttribute('normal', new Float32BufferAttribute(normals, 3));
    geometry.setAttribute('color', new Float32BufferAttribute(colors, 3));
    geometry.setIndex(indices);
    geometry.computeBoundingSphere();
    return geometry;
  }

  private shouldSubdivideForDynamicExclusion(
    minX: number,
    maxX: number,
    minZ: number,
    maxZ: number,
  ): boolean {
    const bounds = this.dynamicExclusionBounds;
    return this.dynamicExclusionSampler !== undefined && bounds !== undefined &&
      maxX >= bounds.minX && minX <= bounds.maxX &&
      maxZ >= bounds.minZ && minZ <= bounds.maxZ;
  }

  private appendSubdividedTerrainCell(
    centerX: number,
    centerZ: number,
    positions: number[],
    normals: number[],
    colors: number[],
    indices: number[],
    normalCache: Map<string, readonly [number, number, number]>,
  ): void {
    const halfGrid = TERRAIN_GRID_METRES * 0.5;
    const segments = Math.max(
      1,
      Math.round(TERRAIN_GRID_METRES / TERRAIN_CUTOUT_GRID_METRES),
    );
    const step = TERRAIN_GRID_METRES / segments;
    const minX = centerX - halfGrid;
    const minZ = centerZ - halfGrid;
    for (let row = 0; row < segments; row += 1) {
      for (let column = 0; column < segments; column += 1) {
        const x0 = minX + column * step;
        const x1 = x0 + step;
        const z0 = minZ + row * step;
        const z1 = z0 + step;
        const sampleX = (x0 + x1) * 0.5;
        const sampleZ = (z0 + z1) * 0.5;
        if (sampleX > borealisCoastX(sampleZ)) continue;
        // The 12.5 cm aperture tessellation is already substantially finer
        // than the 36 cm cave lattice. Centre sampling removes the complete
        // pale terrain patch instead of leaving its corner triangles hanging
        // through the darker rock surface inside the excavation.
        if (this.dynamicExclusionSampler?.(sampleX, sampleZ)) continue;
        const base = positions.length / 3;
        positions.push(
          x0, this.terrain.sampleHeight(x0, z0) - 0.035, z0,
          x1, this.terrain.sampleHeight(x1, z0) - 0.035, z0,
          x0, this.terrain.sampleHeight(x0, z1) - 0.035, z1,
          x1, this.terrain.sampleHeight(x1, z1) - 0.035, z1,
        );
        for (const [x, z] of [
          [x0, z0],
          [x1, z0],
          [x0, z1],
          [x1, z1],
        ] as const) {
          const normal = this.sampleCachedTerrainNormal(x, z, normalCache);
          normals.push(normal[0], normal[1], normal[2]);
        }
        const centerHeight = this.terrain.sampleHeight(sampleX, sampleZ);
        const surface = this.terrain.sampleSurface(sampleX, sampleZ);
        const surfaceMaterial = this.terrain.sampleMaterial(sampleX, sampleZ);
        const elevation = clamp01(
          (centerHeight - BOREALIS_GROUND_HEIGHT) / 14,
        );
        const steep = clamp01(surface.slopeRadians / 0.72);
        const baseColor = surfaceMaterial === 'ROCK'
          ? [0.46, 0.5, 0.48]
          : surfaceMaterial === 'DIRT'
            ? [0.4, 0.32, 0.24]
            : surfaceMaterial === 'ROAD'
              ? [0.2, 0.22, 0.22]
              : surfaceMaterial === 'SIDEWALK'
                ? [0.46, 0.49, 0.5]
                : surfaceMaterial === 'SNOW_EXCLUSION'
                  ? [0.32, 0.37, 0.35]
                  : [0.84, 0.9, 0.88];
        for (let vertex = 0; vertex < 4; vertex += 1) {
          colors.push(
            (baseColor[0] ?? 0.84) - elevation * 0.16 - steep * 0.1,
            (baseColor[1] ?? 0.9) - elevation * 0.14 - steep * 0.09,
            (baseColor[2] ?? 0.88) - elevation * 0.16 - steep * 0.1,
          );
        }
        indices.push(base, base + 2, base + 1, base + 1, base + 2, base + 3);
      }
    }
  }

  private sampleCachedTerrainNormal(
    x: number,
    z: number,
    cache: Map<string, readonly [number, number, number]>,
  ): readonly [number, number, number] {
    const key = `${x.toFixed(4)},${z.toFixed(4)}`;
    const cached = cache.get(key);
    if (cached) return cached;
    const surface = this.terrain.sampleSurface(x, z);
    const normal = [
      surface.normalX,
      surface.normalY,
      surface.normalZ,
    ] as const;
    cache.set(key, normal);
    return normal;
  }

  private boundsIntersect(
    left: Readonly<PrototypeChunkBounds>,
    right: Readonly<MainlandDynamicExclusionBounds>,
  ): boolean {
    return left.maxX >= right.minX && left.minX <= right.maxX &&
      left.maxZ >= right.minZ && left.minZ <= right.maxZ;
  }

  private createCoastGeometry(bounds: PrototypeChunkBounds): BufferGeometry {
    const positions: number[] = [];
    const colors: number[] = [];
    const indices: number[] = [];
    const samples = 128;
    const crossSectionLength = 4;
    for (let index = 0; index <= samples; index += 1) {
      const z =
        bounds.minZ +
        (bounds.maxZ - bounds.minZ) * (index / samples);
      const x = borealisCoastX(z);
      const topHeight = this.terrain.sampleHeight(x - 0.9, z) - 0.035;
      const elevated = Math.max(0, topHeight - BOREALIS_GROUND_HEIGHT);
      const crossSection = [
        {
          x: -0.9,
          y: topHeight,
          color: new Color(0xd8e5df).lerp(new Color(0x879189), clamp01(elevated / 12)),
        },
        {
          x: -0.12,
          y: elevated > 1.2 ? 0.2 + Math.min(0.8, elevated * 0.04) : 0.12,
          color: elevated > 1.2 ? new Color(0x68746f) : new Color(0xb7c5b5),
        },
        { x: 0.72, y: -0.075, color: new Color(0x7da8a2) },
        { x: 2.8, y: -0.28, color: new Color(0x477b7a) },
      ] as const;
      for (const point of crossSection) {
        positions.push(x + point.x, point.y, z);
        colors.push(point.color.r, point.color.g, point.color.b);
      }
      if (index >= samples) continue;
      const base = index * crossSectionLength;
      const next = base + crossSectionLength;
      for (
        let strip = 0;
        strip < crossSectionLength - 1;
        strip += 1
      ) {
        indices.push(
          base + strip,
          base + strip + 1,
          next + strip,
          next + strip,
          base + strip + 1,
          next + strip + 1,
        );
      }
    }
    const geometry = new BufferGeometry();
    geometry.setAttribute(
      'position',
      new Float32BufferAttribute(positions, 3),
    );
    geometry.setAttribute(
      'color',
      new Float32BufferAttribute(colors, 3),
    );
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    return geometry;
  }

  private createCliffGeometry(bounds: PrototypeChunkBounds): BufferGeometry {
    const positions: number[] = [];
    const colors: number[] = [];
    const indices: number[] = [];
    const minGridX = Math.floor(bounds.minX / TERRAIN_GRID_METRES) - 1;
    const maxGridX = Math.ceil(bounds.maxX / TERRAIN_GRID_METRES) + 1;
    const minGridZ = Math.floor(bounds.minZ / TERRAIN_GRID_METRES) - 1;
    const maxGridZ = Math.ceil(bounds.maxZ / TERRAIN_GRID_METRES) + 1;
    const addWall = (
      x1: number,
      z1: number,
      x2: number,
      z2: number,
      top: number,
      bottom: number,
    ): void => {
      if (top - bottom < 0.08) return;
      const base = positions.length / 3;
      positions.push(x1, top, z1, x2, top, z2, x1, bottom, z1, x2, bottom, z2);
      const shade = clamp01(0.52 - (top - bottom) * 0.012);
      for (let index = 0; index < 4; index += 1) {
        colors.push(shade, shade * 1.06, shade * 1.01);
      }
      indices.push(base, base + 2, base + 1, base + 1, base + 2, base + 3);
    };
    for (let gridZ = minGridZ; gridZ <= maxGridZ; gridZ += 1) {
      for (let gridX = minGridX; gridX <= maxGridX; gridX += 1) {
        const x = gridX * TERRAIN_GRID_METRES;
        const z = gridZ * TERRAIN_GRID_METRES;
        if (x < bounds.minX - TERRAIN_GRID_METRES || x > bounds.maxX + TERRAIN_GRID_METRES ||
            z < bounds.minZ - TERRAIN_GRID_METRES || z > bounds.maxZ + TERRAIN_GRID_METRES) continue;
        const here = this.terrain.sampleNodeHeight(gridX, gridZ) - 0.03;
        if (this.terrain.isCliffEdge(gridX, gridZ, 'E')) {
          const there = this.terrain.sampleNodeHeight(gridX + 1, gridZ) - 0.03;
          const midpointX = x + TERRAIN_GRID_METRES * 0.5;
          addWall(
            midpointX,
            z - TERRAIN_GRID_METRES * 0.5,
            midpointX,
            z + TERRAIN_GRID_METRES * 0.5,
            Math.max(here, there),
            Math.min(here, there),
          );
        }
        if (this.terrain.isCliffEdge(gridX, gridZ, 'S')) {
          const there = this.terrain.sampleNodeHeight(gridX, gridZ + 1) - 0.03;
          const midpointZ = z + TERRAIN_GRID_METRES * 0.5;
          addWall(
            x - TERRAIN_GRID_METRES * 0.5,
            midpointZ,
            x + TERRAIN_GRID_METRES * 0.5,
            midpointZ,
            Math.max(here, there),
            Math.min(here, there),
          );
        }
      }
    }
    const geometry = new BufferGeometry();
    geometry.setAttribute('position', new Float32BufferAttribute(positions, 3));
    geometry.setAttribute('color', new Float32BufferAttribute(colors, 3));
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    geometry.computeBoundingSphere();
    return geometry;
  }

  private createCurbGeometry(bounds: PrototypeChunkBounds): BufferGeometry {
    const positions: number[] = [];
    const indices: number[] = [];
    const minGridX = Math.floor(bounds.minX / TERRAIN_GRID_METRES) - 1;
    const maxGridX = Math.ceil(bounds.maxX / TERRAIN_GRID_METRES) + 1;
    const minGridZ = Math.floor(bounds.minZ / TERRAIN_GRID_METRES) - 1;
    const maxGridZ = Math.ceil(bounds.maxZ / TERRAIN_GRID_METRES) + 1;
    const addWall = (
      x1: number,
      z1: number,
      x2: number,
      z2: number,
      firstHeight: number,
      secondHeight: number,
    ): void => {
      if (Math.abs(firstHeight - secondHeight) < 0.02) return;
      const top = Math.max(firstHeight, secondHeight) - 0.028;
      const bottom = Math.min(firstHeight, secondHeight) - 0.028;
      const base = positions.length / 3;
      positions.push(x1, top, z1, x2, top, z2, x1, bottom, z1, x2, bottom, z2);
      indices.push(base, base + 2, base + 1, base + 1, base + 2, base + 3);
    };
    for (let gridZ = minGridZ; gridZ <= maxGridZ; gridZ += 1) {
      for (let gridX = minGridX; gridX <= maxGridX; gridX += 1) {
        const x = gridX * TERRAIN_GRID_METRES;
        const z = gridZ * TERRAIN_GRID_METRES;
        if (this.terrain.isRaisedSurfaceBoundary(gridX, gridZ, 'E')) {
          addWall(
            x + TERRAIN_GRID_METRES * 0.5,
            z - TERRAIN_GRID_METRES * 0.5,
            x + TERRAIN_GRID_METRES * 0.5,
            z + TERRAIN_GRID_METRES * 0.5,
            this.terrain.sampleNodeHeight(gridX, gridZ),
            this.terrain.sampleNodeHeight(gridX + 1, gridZ),
          );
        }
        if (this.terrain.isRaisedSurfaceBoundary(gridX, gridZ, 'S')) {
          addWall(
            x - TERRAIN_GRID_METRES * 0.5,
            z + TERRAIN_GRID_METRES * 0.5,
            x + TERRAIN_GRID_METRES * 0.5,
            z + TERRAIN_GRID_METRES * 0.5,
            this.terrain.sampleNodeHeight(gridX, gridZ),
            this.terrain.sampleNodeHeight(gridX, gridZ + 1),
          );
        }
      }
    }
    const geometry = new BufferGeometry();
    geometry.setAttribute('position', new Float32BufferAttribute(positions, 3));
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    geometry.computeBoundingSphere();
    return geometry;
  }

  private refreshEditedChunks(bounds: TerrainEditBounds): void {
    for (const [key, active] of [...this.chunks]) {
      const chunkBounds = prototypeBoundsForChunk(
        active.descriptor.address.x,
        active.descriptor.address.z,
      );
      if (
        chunkBounds.maxX < bounds.minX ||
        chunkBounds.minX > bounds.maxX ||
        chunkBounds.maxZ < bounds.minZ ||
        chunkBounds.minZ > bounds.maxZ
      ) continue;
      const replacement = this.createChunk(active.descriptor);
      this.root.remove(active.root);
      this.disposeChunk(active);
      this.root.add(replacement);
      this.chunks.set(key, { root: replacement, descriptor: active.descriptor });
    }
    for (const [key, cached] of [...this.cachedChunks]) {
      const chunkBounds = prototypeBoundsForChunk(
        cached.descriptor.address.x,
        cached.descriptor.address.z,
      );
      if (
        chunkBounds.maxX < bounds.minX ||
        chunkBounds.minX > bounds.maxX ||
        chunkBounds.maxZ < bounds.minZ ||
        chunkBounds.minZ > bounds.maxZ
      ) continue;
      this.cachedChunks.delete(key);
      this.disposeChunk(cached);
    }
  }

  private cacheChunk(
    key: string,
    chunk: {
      root: Group;
      descriptor: Readonly<RuntimeWorldChunkDescriptor>;
    },
  ): void {
    const previous = this.cachedChunks.get(key);
    if (previous && previous !== chunk) this.disposeChunk(previous);
    this.cachedChunks.delete(key);
    this.cachedChunks.set(key, chunk);
    while (
      this.cachedChunks.size > BorealisMainlandRenderer.MAXIMUM_CACHED_CHUNKS
    ) {
      const oldest = this.cachedChunks.entries().next().value as
        | [string, { root: Group; descriptor: Readonly<RuntimeWorldChunkDescriptor> }]
        | undefined;
      if (!oldest) break;
      this.cachedChunks.delete(oldest[0]);
      this.disposeChunk(oldest[1]);
    }
  }

  private disposeChunk(chunk: { root: Group }): void {
    chunk.root.removeFromParent();
    chunk.root.traverse((object) => {
      if (object instanceof Mesh) object.geometry.dispose();
    });
  }

  private addLandmarks(
    group: Group,
    bounds: PrototypeChunkBounds,
  ): void {
    this.addWorkshopMarker(group, bounds);
  }

  private addWorkshopMarker(
    group: Group,
    bounds: PrototypeChunkBounds,
  ): void {
    const field = BOREALIS_WORKSHOP_SNOWFIELD;
    if (
      field.centerX < bounds.minX ||
      field.centerX > bounds.maxX ||
      field.centerZ < bounds.minZ ||
      field.centerZ > bounds.maxZ
    ) {
      return;
    }
    const marker = new Group();
    marker.name = 'Borealis workshop snowfield marker';
    marker.position.set(field.centerX, 0, field.centerZ);
    marker.visible = false;
    this.workshopMarker = marker;
    const boxes = new InstancedMesh(
      new BoxGeometry(1, 1, 1),
      this.markerMaterial,
      8,
    );
    const transform = new Object3D();
    let index = 0;
    const setBox = (
      x: number,
      y: number,
      z: number,
      width: number,
      height: number,
      depth: number,
    ): void => {
      transform.position.set(x, y, z);
      transform.rotation.set(0, 0, 0);
      transform.scale.set(width, height, depth);
      transform.updateMatrix();
      boxes.setMatrixAt(index, transform.matrix);
      index += 1;
    };
    for (const x of [-field.halfWidth, field.halfWidth]) {
      for (const z of [-field.halfHeight, field.halfHeight]) {
        const ground = this.terrain.sampleHeight(field.centerX + x, field.centerZ + z);
        setBox(x, ground + 0.72, z, 0.13, 1.45, 0.13);
      }
    }
    for (const z of [-field.halfHeight, field.halfHeight]) {
      setBox(0, this.terrain.sampleHeight(field.centerX, field.centerZ + z) + 0.55, z, field.halfWidth * 2, 0.09, 0.09);
    }
    for (const x of [-field.halfWidth, field.halfWidth]) {
      setBox(x, this.terrain.sampleHeight(field.centerX + x, field.centerZ) + 0.55, 0, 0.09, 0.09, field.halfHeight * 2);
    }
    boxes.instanceMatrix.needsUpdate = true;
    boxes.castShadow = true;
    marker.add(boxes);
    group.add(marker);
  }
}

const clamp01 = (value: number): number => Math.max(0, Math.min(1, value));
