import type { SurvivalBuildV3PlacementStatus } from './SurvivalBuildV3Authority';

export interface SurvivalBuildV3GhostStyle {
  readonly color: number;
  readonly opacity: number;
  readonly emissiveIntensity: number;
  readonly pulseScale: number;
}

export interface SurvivalBuildV3SocketStyle {
  readonly color: number;
  readonly opacity: number;
  readonly scale: number;
}

/** Pure presentation policy shared by the primary ghost and drag previews. */
export const survivalBuildV3GhostStyle = (
  status: SurvivalBuildV3PlacementStatus,
  seconds: number,
  primary: boolean,
): SurvivalBuildV3GhostStyle => {
  const pulse = Math.sin(seconds * (status === 'BLOCKED' ? 5.4 : 3.8)) * 0.5 + 0.5;
  // Green is the stable part entering the world. Amber and red are direct
  // structural continuations of that same language; existing hosts/sockets
  // remain blue in the construction-system highlight policy.
  const color = status === 'SUPPORTED'
    ? 0x6ff2ac
    : status === 'CANTILEVER'
      ? 0xffc35c
      : 0xff615a;
  return {
    color,
    opacity: primary
      ? (status === 'BLOCKED' ? 0.46 + pulse * 0.08 : 0.74 + pulse * 0.05)
      : (status === 'BLOCKED' ? 0.28 : 0.46),
    emissiveIntensity: primary
      ? (status === 'BLOCKED' ? 0.58 + pulse * 0.25 : 0.5 + pulse * 0.1)
      : 0.24,
    pulseScale: primary ? 0.995 + pulse * 0.01 : 1,
  };
};

/** Existing attachment addresses are blue; selected is simply the clearest. */
export const survivalBuildV3SocketStyle = (
  selected: boolean,
  seconds: number,
): SurvivalBuildV3SocketStyle => {
  const pulse = Math.sin(seconds * 5.8) * 0.5 + 0.5;
  return selected
    ? { color: 0x63c9ec, opacity: 0.92, scale: 1.22 + pulse * 0.14 }
    : { color: 0x8edff2, opacity: 0.5, scale: 0.68 + pulse * 0.08 };
};
