import {
  AnimationMixer,
  Box3,
  Color,
  Group,
  Mesh,
  MeshBasicMaterial,
  Vector3,
  type AnimationClip,
  type Material,
  type Object3D,
} from 'three';
import type { TerrainHeightSystem } from '../land/TerrainHeightSystem';
import { clamp, hash2D, smoothstep } from '../utils/math';
import {
  createWinterAnimalModel,
  setWinterAnimalMotion,
  type WinterAnimalModelInstance,
} from './WinterAnimalModelLibrary';

const SKY_FIGURE_URL =
  'assets/vendor/quaternius-ultimate-monsters/yeti/Yeti.gltf';

export interface WildernessMythicWeatherContext {
  readonly playerX: number;
  readonly playerZ: number;
  readonly daylight?: number;
  readonly fogDensity?: number;
  readonly cloudCover?: number;
  readonly snowIntensity?: number;
}

export interface WildernessApparitionTargets {
  readonly skyFigure: number;
  readonly horizonStag: number;
}

/**
 * Deterministic apparition windows are long enough to notice and revisit in a
 * trace, but remain conditional on low light and obscuring weather. Neither
 * apparition affects gameplay state, collision, saves or animal simulation.
 */
export const resolveWildernessApparitionTargets = (
  worldTime: number,
  context: Readonly<WildernessMythicWeatherContext>,
): WildernessApparitionTargets => {
  const daylight = clamp(context.daylight ?? 0, 0, 1);
  const fog = clamp(context.fogDensity ?? 0, 0, 1);
  const clouds = clamp(context.cloudCover ?? 0, 0, 1);
  const snow = clamp(context.snowIntensity ?? 0, 0, 1);
  const darkness = 1 - smoothstep(0.12, 0.43, daylight);

  const skyCycle = ((worldTime + 71) % 360 + 360) % 360;
  const skyWindow = smoothstep(48, 75, skyCycle) *
    (1 - smoothstep(126, 162, skyCycle));
  const skyWeather = smoothstep(0.34, 0.78, Math.max(fog, clouds * 0.8, snow));

  const stagCycle = ((worldTime + 19) % 255 + 255) % 255;
  const stagWindow = smoothstep(28, 48, stagCycle) *
    (1 - smoothstep(96, 128, stagCycle));
  const stagWeather = smoothstep(0.2, 0.68, Math.max(fog, clouds * 0.62));

  return {
    skyFigure: darkness * skyWeather * skyWindow * 0.055,
    horizonStag: darkness * stagWeather * stagWindow * 0.16,
  };
};

interface LoadedSkyFigure {
  readonly root: Group;
  readonly mixer: AnimationMixer;
  readonly clip?: AnimationClip;
  readonly materials: readonly MeshBasicMaterial[];
}

const absoluteAssetUrl = (url: string): string =>
  new URL(url, document.baseURI).href;

const makeApparitionMaterial = (
  source: Material,
  color: number,
): MeshBasicMaterial => {
  const sourceColor = (source as Material & { color?: Color }).color;
  const tint = new Color(color);
  if (sourceColor) tint.multiply(sourceColor).lerp(new Color(color), 0.72);
  const result = new MeshBasicMaterial({
    color: tint,
    transparent: true,
    opacity: 0,
    depthTest: true,
    depthWrite: false,
    fog: true,
    toneMapped: false,
  });
  result.name = 'Faint mythic apparition silhouette';
  return result;
};

const replaceModelMaterials = (
  root: Object3D,
  color: number,
): MeshBasicMaterial[] => {
  const materials: MeshBasicMaterial[] = [];
  root.traverse((object) => {
    if (!(object instanceof Mesh)) return;
    const sources = Array.isArray(object.material)
      ? object.material
      : [object.material];
    const replacements = sources.map((source) => {
      const replacement = makeApparitionMaterial(source, color);
      materials.push(replacement);
      return replacement;
    });
    object.material = Array.isArray(object.material)
      ? replacements
      : replacements[0]!;
    object.castShadow = false;
    object.receiveShadow = false;
    // These figures are deliberate horizon exceptions. Depth testing still
    // lets terrain and forests occlude them correctly.
    object.frustumCulled = false;
  });
  return materials;
};

const loadSkyFigure = async (): Promise<LoadedSkyFigure | undefined> => {
  if (typeof document === 'undefined') return undefined;
  const { GLTFLoader } = await import(
    'three/examples/jsm/loaders/GLTFLoader.js'
  );
  const { clone } = await import(
    'three/examples/jsm/utils/SkeletonUtils.js'
  );
  const loaded = await new GLTFLoader().loadAsync(absoluteAssetUrl(SKY_FIGURE_URL));
  const scene = clone(loaded.scene) as Group;
  const bounds = new Box3().setFromObject(scene);
  const size = bounds.getSize(new Vector3());
  const centre = bounds.getCenter(new Vector3());
  scene.position.set(-centre.x, -bounds.min.y, -centre.z);
  scene.scale.setScalar(1 / Math.max(0.001, size.y));
  const root = new Group();
  root.name = 'Mythic sky figure · asset-library Yeti';
  root.add(scene);
  const mixer = new AnimationMixer(scene);
  const clip = loaded.animations.find((candidate) =>
    /idle/i.test(candidate.name)) ?? loaded.animations[0];
  clip && mixer.clipAction(clip).play();
  return {
    root,
    mixer,
    clip,
    materials: replaceModelMaterials(scene, 0xb8d4dc),
  };
};

/**
 * Purely presentational, rare horizon stories. Models stream after gameplay
 * has started and remain hidden at zero opacity, avoiding loading-screen and
 * ordinary-frame cost when the weather does not call for them.
 */
export class WildernessMythicApparitionSystem {
  private readonly root = new Group();
  private sky?: LoadedSkyFigure;
  private stag?: WinterAnimalModelInstance;
  private readonly stagMaterials: MeshBasicMaterial[] = [];
  private skyOpacity = 0;
  private stagOpacity = 0;
  private skyWindow = Number.NaN;
  private stagWindow = Number.NaN;
  private presentationSuppressed = false;
  private disposed = false;

  public constructor(
    parent: Group,
    private readonly terrain: TerrainHeightSystem,
  ) {
    this.root.name = 'Rare wilderness apparitions';
    this.root.visible = false;
    parent.add(this.root);
    void this.loadModels();
  }

  public update(
    deltaSeconds: number,
    worldTime: number,
    context: Readonly<WildernessMythicWeatherContext>,
  ): void {
    const targets = resolveWildernessApparitionTargets(worldTime, context);
    const skyResponse = targets.skyFigure > this.skyOpacity ? 0.18 : 0.12;
    const stagResponse = targets.horizonStag > this.stagOpacity ? 0.24 : 0.16;
    this.skyOpacity += (targets.skyFigure - this.skyOpacity) *
      (1 - Math.exp(-skyResponse * Math.max(0, deltaSeconds)));
    this.stagOpacity += (targets.horizonStag - this.stagOpacity) *
      (1 - Math.exp(-stagResponse * Math.max(0, deltaSeconds)));

    this.root.visible = !this.presentationSuppressed &&
      (this.skyOpacity > 0.001 || this.stagOpacity > 0.001);
    if (this.sky) {
      const window = Math.floor((worldTime + 71) / 360);
      if (window !== this.skyWindow) {
        this.skyWindow = window;
        const angle = hash2D(window, 421, 911) * Math.PI * 2;
        const distance = 1_450 + hash2D(window, 887, 223) * 620;
        this.sky.root.userData.apparitionDirection = angle;
        this.sky.root.userData.apparitionDistance = distance;
      }
      const angle = Number(this.sky.root.userData.apparitionDirection ?? 0);
      const distance = Number(this.sky.root.userData.apparitionDistance ?? 1_700);
      const x = context.playerX + Math.sin(angle) * distance;
      const z = context.playerZ + Math.cos(angle) * distance;
      this.sky.root.position.set(x, this.terrain.sampleHeight(x, z) + 105, z);
      this.sky.root.rotation.y = angle + Math.PI;
      this.sky.root.scale.setScalar(430);
      this.sky.root.visible = this.skyOpacity > 0.001;
      for (const material of this.sky.materials) material.opacity = this.skyOpacity;
      if (this.sky.root.visible) this.sky.mixer.update(deltaSeconds * 0.16);
    }
    if (this.stag) {
      const window = Math.floor((worldTime + 19) / 255);
      if (window !== this.stagWindow) {
        this.stagWindow = window;
        const angle = hash2D(window, 773, 307) * Math.PI * 2;
        const distance = 620 + hash2D(window, 137, 613) * 330;
        this.stag.root.userData.apparitionDirection = angle;
        this.stag.root.userData.apparitionDistance = distance;
      }
      const angle = Number(this.stag.root.userData.apparitionDirection ?? 0);
      const distance = Number(this.stag.root.userData.apparitionDistance ?? 760);
      const x = context.playerX + Math.sin(angle) * distance;
      const z = context.playerZ + Math.cos(angle) * distance;
      this.stag.root.position.set(x, this.terrain.sampleHeight(x, z), z);
      this.stag.root.rotation.y = angle + Math.PI;
      this.stag.root.scale.setScalar(58);
      this.stag.root.visible = this.stagOpacity > 0.001;
      for (const material of this.stagMaterials) material.opacity = this.stagOpacity;
      if (this.stag.root.visible) this.stag.mixer.update(deltaSeconds * 0.22);
    }
  }

  public setPresentationSuppressed(suppressed: boolean): void {
    this.presentationSuppressed = suppressed;
    if (suppressed) this.root.visible = false;
  }

  public dispose(): void {
    this.disposed = true;
    this.sky?.mixer.stopAllAction();
    this.stag?.mixer.stopAllAction();
    for (const material of this.sky?.materials ?? []) material.dispose();
    for (const material of this.stagMaterials) material.dispose();
    this.root.removeFromParent();
  }

  private async loadModels(): Promise<void> {
    try {
      const [sky, stag] = await Promise.all([
        loadSkyFigure(),
        createWinterAnimalModel('DEER', 'mythic-horizon-stag-4'),
      ]);
      if (this.disposed) {
        sky?.mixer.stopAllAction();
        stag?.mixer.stopAllAction();
        return;
      }
      if (sky) {
        this.sky = sky;
        sky.root.visible = false;
        this.root.add(sky.root);
      }
      if (stag) {
        this.stag = stag;
        setWinterAnimalMotion(stag, 'OBSERVE', 0);
        this.stagMaterials.push(...replaceModelMaterials(stag.root, 0xd8e3e1));
        stag.root.visible = false;
        this.root.add(stag.root);
      }
    } catch (error) {
      // The experiment is optional. A missing vendor model must never keep
      // the survival prototype from starting.
      console.warn('Could not stream wilderness apparition models.', error);
    }
  }
}
