import { clamp } from '../../utils/math';
import type {
  GoodType,
  PortGameplayDefinition,
  PortServiceType,
  PortState,
  RouteDefinition,
  RouteState,
} from '../definitions/GameplayTypes';
import {
  ROUTE_OPENNESS_THRESHOLD,
  ROUTE_WIDTH_THRESHOLDS,
} from './RouteRuntimeSystem';

export interface PortPresentationState {
  portId: string;
  npcDensity: number;
  vesselDensity: number;
  activeBuildingRatio: number;
  lightActivity: number;
  constructionActivity: number;
  ambientEventIntensity: number;
}

export interface PortSimulationSaveData {
  version: 1;
  ports: PortState[];
}

export interface PortSimulationUpdateResult {
  updatedPorts: number;
  levelChanges: Array<{
    portId: string;
    previousLevel: 1 | 2 | 3;
    level: 1 | 2 | 3;
  }>;
}

const routeQuality = (
  state: Readonly<RouteState> | undefined,
): number => {
  if (
    !state ||
    state.openness < ROUTE_OPENNESS_THRESHOLD ||
    state.measuredWidth < ROUTE_WIDTH_THRESHOLDS.small
  ) {
    return 0;
  }
  const widthQuality = clamp(
    state.measuredWidth / ROUTE_WIDTH_THRESHOLDS.heavy,
    0.28,
    1,
  );
  return clamp(state.openness * widthQuality, 0, 1);
};

const unlockedServices = (
  definition: Readonly<PortGameplayDefinition>,
  level: 1 | 2 | 3,
): PortServiceType[] =>
  definition.services.slice(0, level);

const initialPortState = (
  definition: Readonly<PortGameplayDefinition>,
): PortState => ({
  portId: definition.id,
  developmentLevel: 1,
  developmentProgress: 0.12,
  accessibility: 0.18,
  traffic: 0.08,
  supplySatisfaction: 0.3,
  unlockedServices: unlockedServices(definition, 1),
});

const sanitizePortState = (
  definition: Readonly<PortGameplayDefinition>,
  candidate: Readonly<PortState>,
): PortState => {
  const level = clamp(
    Math.floor(candidate.developmentLevel),
    1,
    3,
  ) as 1 | 2 | 3;
  return {
    portId: definition.id,
    developmentLevel: level,
    developmentProgress: clamp(
      Number.isFinite(candidate.developmentProgress)
        ? candidate.developmentProgress
        : 0,
      0,
      1,
    ),
    accessibility: clamp(
      Number.isFinite(candidate.accessibility)
        ? candidate.accessibility
        : 0.18,
      0.18,
      1,
    ),
    traffic: clamp(
      Number.isFinite(candidate.traffic)
        ? candidate.traffic
        : 0.08,
      0.08,
      1,
    ),
    supplySatisfaction: clamp(
      Number.isFinite(candidate.supplySatisfaction)
        ? candidate.supplySatisfaction
        : 0.3,
      0.3,
      1,
    ),
    unlockedServices: unlockedServices(definition, level),
  };
};

export class PortSimulation {
  private readonly portDefinitions = new Map<
    string,
    PortGameplayDefinition
  >();
  private readonly routeDefinitions: readonly RouteDefinition[];
  private readonly states = new Map<string, PortState>();

  public constructor(
    ports: readonly PortGameplayDefinition[],
    routes: readonly RouteDefinition[],
    saved?: Readonly<PortSimulationSaveData>,
  ) {
    this.routeDefinitions = routes;
    for (const definition of ports) {
      this.portDefinitions.set(definition.id, definition);
      this.states.set(
        definition.id,
        initialPortState(definition),
      );
    }
    if (saved) this.importState(saved);
  }

  public getState(portId: string): PortState | undefined {
    const state = this.states.get(portId);
    return state
      ? {
          ...state,
          unlockedServices: [...state.unlockedServices],
        }
      : undefined;
  }

  public getStates(): readonly PortState[] {
    return [...this.states.values()].map((state) => ({
      ...state,
      unlockedServices: [...state.unlockedServices],
    }));
  }

  public getPresentationState(
    portId: string,
  ): PortPresentationState | undefined {
    const state = this.states.get(portId);
    if (!state) return undefined;
    const development =
      (state.developmentLevel - 1 + state.developmentProgress) /
      3;
    return {
      portId,
      npcDensity: clamp(
        0.12 +
          state.traffic * 0.48 +
          development * 0.4,
        0,
        1,
      ),
      vesselDensity: clamp(
        0.08 +
          state.traffic * 0.72 +
          state.accessibility * 0.2,
        0,
        1,
      ),
      activeBuildingRatio: clamp(
        0.28 +
          state.supplySatisfaction * 0.34 +
          development * 0.38,
        0,
        1,
      ),
      lightActivity: clamp(
        0.24 +
          state.traffic * 0.32 +
          development * 0.44,
        0,
        1,
      ),
      constructionActivity:
        state.developmentLevel < 3
          ? clamp(
              state.developmentProgress *
                state.supplySatisfaction,
              0,
              1,
            )
          : 0,
      ambientEventIntensity: clamp(
        0.1 +
          state.traffic * 0.48 +
          development * 0.42,
        0,
        1,
      ),
    };
  }

  public update(
    deltaSeconds: number,
    routeStates: readonly RouteState[],
  ): PortSimulationUpdateResult {
    const delta = clamp(deltaSeconds, 0, 30);
    const routeStateById = new Map(
      routeStates.map((state) => [state.id, state]),
    );
    const qualities = new Map<string, number>();
    for (const definition of this.routeDefinitions) {
      qualities.set(
        definition.id,
        routeQuality(routeStateById.get(definition.id)),
      );
    }
    const levelChanges: PortSimulationUpdateResult['levelChanges'] =
      [];

    for (const [portId, definition] of this.portDefinitions) {
      const state = this.states.get(portId)!;
      const incidentQualities = this.routeDefinitions
        .filter(
          (route) =>
            route.fromPortId === portId ||
            route.toPortId === portId,
        )
        .map((route) => qualities.get(route.id) ?? 0);
      const bestConnection =
        incidentQualities.length > 0
          ? Math.max(...incidentQualities)
          : 0;
      const averageConnection =
        incidentQualities.length > 0
          ? incidentQualities.reduce(
              (total, value) => total + value,
              0,
            ) / incidentQualities.length
          : 0;
      const targetAccessibility =
        0.18 + bestConnection * 0.82;
      const targetTraffic =
        0.08 + averageConnection * 0.92;
      const needSatisfaction = definition.requiredGoods.map(
        (good) => {
          let bestSupply = 0;
          for (const producer of this.portDefinitions.values()) {
            if (
              producer.producedGood !== good ||
              producer.id === portId
            ) {
              continue;
            }
            bestSupply = Math.max(
              bestSupply,
              this.bestConnectionQuality(
                portId,
                producer.id,
                qualities,
              ),
            );
          }
          return 0.3 + bestSupply * 0.7;
        },
      );
      const targetSupply =
        needSatisfaction.length > 0
          ? needSatisfaction.reduce(
              (total, value) => total + value,
              0,
            ) / needSatisfaction.length
          : 1;
      const response = 1 - Math.exp(-delta / 24);
      state.accessibility +=
        (targetAccessibility - state.accessibility) * response;
      state.traffic +=
        (targetTraffic - state.traffic) * response;
      state.supplySatisfaction +=
        (targetSupply - state.supplySatisfaction) * response;
      state.accessibility = clamp(state.accessibility, 0.18, 1);
      state.traffic = clamp(state.traffic, 0.08, 1);
      state.supplySatisfaction = clamp(
        state.supplySatisfaction,
        0.3,
        1,
      );

      if (state.developmentLevel < 3 && delta > 0) {
        const developmentScore =
          state.accessibility * 0.4 +
          state.supplySatisfaction * 0.36 +
          state.traffic * 0.24;
        const drive = developmentScore - 0.52;
        const rateSeconds = drive >= 0 ? 900 : 1800;
        state.developmentProgress = clamp(
          state.developmentProgress +
            drive * delta / rateSeconds,
          0,
          1,
        );
        if (state.developmentProgress >= 0.999) {
          const previousLevel = state.developmentLevel;
          state.developmentLevel = Math.min(
            3,
            state.developmentLevel + 1,
          ) as 1 | 2 | 3;
          state.developmentProgress =
            state.developmentLevel >= 3 ? 1 : 0.08;
          levelChanges.push({
            portId,
            previousLevel,
            level: state.developmentLevel,
          });
        }
      }
      state.unlockedServices = unlockedServices(
        definition,
        state.developmentLevel,
      );
    }

    return {
      updatedPorts: this.states.size,
      levelChanges,
    };
  }

  public applyCargoDelivery(
    portId: string,
    goodType: GoodType,
    amount: number,
  ): boolean {
    const definition = this.portDefinitions.get(portId);
    const state = this.states.get(portId);
    if (
      !definition ||
      !state ||
      !definition.requiredGoods.includes(goodType) ||
      !Number.isFinite(amount) ||
      amount <= 0
    ) {
      return false;
    }
    const supplyImpact = clamp(amount / 100, 0.02, 0.2);
    state.supplySatisfaction = clamp(
      state.supplySatisfaction + supplyImpact,
      0.3,
      1,
    );
    state.traffic = clamp(
      state.traffic + supplyImpact * 0.35,
      0.08,
      1,
    );
    if (state.developmentLevel < 3) {
      state.developmentProgress = clamp(
        state.developmentProgress +
          supplyImpact * 0.08,
        0,
        1,
      );
    }
    return true;
  }

  public exportState(): PortSimulationSaveData {
    return {
      version: 1,
      ports: this.getStates().map((state) => ({
        ...state,
        unlockedServices: [...state.unlockedServices],
      })),
    };
  }

  public importState(
    saved: Readonly<PortSimulationSaveData>,
  ): boolean {
    if (saved.version !== 1 || !Array.isArray(saved.ports)) {
      return false;
    }
    for (const candidate of saved.ports) {
      const definition = this.portDefinitions.get(
        candidate.portId,
      );
      if (!definition) continue;
      this.states.set(
        definition.id,
        sanitizePortState(definition, candidate),
      );
    }
    return true;
  }

  private bestConnectionQuality(
    startPortId: string,
    destinationPortId: string,
    routeQualities: ReadonlyMap<string, number>,
  ): number {
    const qualityByPort = new Map<string, number>([
      [startPortId, 1],
    ]);
    const visited = new Set<string>();

    while (visited.size < this.portDefinitions.size) {
      let currentPortId: string | undefined;
      let currentQuality = -1;
      for (const [portId, quality] of qualityByPort) {
        if (!visited.has(portId) && quality > currentQuality) {
          currentPortId = portId;
          currentQuality = quality;
        }
      }
      if (!currentPortId) break;
      if (currentPortId === destinationPortId) {
        return clamp(currentQuality, 0, 1);
      }
      visited.add(currentPortId);
      for (const route of this.routeDefinitions) {
        const neighbor =
          route.fromPortId === currentPortId
            ? route.toPortId
            : route.toPortId === currentPortId
              ? route.fromPortId
              : undefined;
        if (!neighbor || visited.has(neighbor)) continue;
        const candidateQuality = Math.min(
          currentQuality,
          routeQualities.get(route.id) ?? 0,
        );
        if (
          candidateQuality >
          (qualityByPort.get(neighbor) ?? 0)
        ) {
          qualityByPort.set(neighbor, candidateQuality);
        }
      }
    }
    return 0;
  }
}
