import { clamp } from '../../utils/math';

export interface HydrologyContourVertex {
  readonly x: number;
  readonly z: number;
  readonly strength: number;
}

/**
 * Clips one scalar lake cell at its shoreline threshold. Unlike retaining or
 * rejecting a complete 4 m quad, edge interpolation gives lakes a continuous
 * contour and removes the conspicuous square ice plates.
 */
export const clipHydrologyCell = (
  corners: readonly HydrologyContourVertex[],
  threshold: number,
): readonly HydrologyContourVertex[] => {
  if (corners.length < 3) return [];
  const output: HydrologyContourVertex[] = [];
  const intersection = (
    from: Readonly<HydrologyContourVertex>,
    to: Readonly<HydrologyContourVertex>,
  ): HydrologyContourVertex => {
    const range = to.strength - from.strength;
    const blend = Math.abs(range) < 0.000001
      ? 0.5
      : clamp((threshold - from.strength) / range, 0, 1);
    return {
      x: from.x + (to.x - from.x) * blend,
      z: from.z + (to.z - from.z) * blend,
      strength: threshold,
    };
  };
  let previous = corners.at(-1)!;
  let previousInside = previous.strength >= threshold;
  for (const current of corners) {
    const currentInside = current.strength >= threshold;
    if (currentInside !== previousInside) {
      output.push(intersection(previous, current));
    }
    if (currentInside) output.push({ ...current });
    previous = current;
    previousInside = currentInside;
  }
  return output;
};

export const triangulateContourFan = (
  vertexCount: number,
  baseIndex = 0,
): readonly number[] => {
  const indices: number[] = [];
  for (let index = 1; index < vertexCount - 1; index += 1) {
    indices.push(baseIndex, baseIndex + index, baseIndex + index + 1);
  }
  return indices;
};
