import {
  ACESFilmicToneMapping,
  Box3,
  Color,
  DirectionalLight,
  Group,
  HemisphereLight,
  MOUSE,
  Object3D,
  PerspectiveCamera,
  Scene,
  SRGBColorSpace,
  TOUCH,
  Vector3,
  WebGLRenderer,
} from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';

export interface InspectionObjectOptions {
  targetSize?: number;
  yawRadians?: number;
  ownsObject?: boolean;
}

export interface InspectionAssetOptions
  extends Omit<InspectionObjectOptions, 'ownsObject'> {
  url: string;
}

export interface InspectionObjectFit {
  root: Group;
  sourceSize: Vector3;
  scale: number;
}

export const createInspectionObjectFit = (
  object: Object3D,
  targetSize = 2.8,
  yawRadians = 0,
): InspectionObjectFit => {
  const oriented = new Group();
  oriented.rotation.y = yawRadians;
  oriented.add(object);
  oriented.updateMatrixWorld(true);

  const bounds = new Box3().setFromObject(oriented);
  const sourceSize = bounds.getSize(new Vector3());
  const sourceCenter = bounds.getCenter(new Vector3());
  const maximumDimension = Math.max(
    sourceSize.x,
    sourceSize.y,
    sourceSize.z,
    0.001,
  );
  const scale = Math.max(0.001, targetSize) / maximumDimension;

  const centered = new Group();
  centered.position.copy(sourceCenter).multiplyScalar(-1);
  centered.add(oriented);

  const root = new Group();
  root.name = 'Inspection object';
  root.scale.setScalar(scale);
  root.add(centered);
  root.updateMatrixWorld(true);
  return { root, sourceSize, scale };
};

const disposeObject = (object: Object3D): void => {
  object.traverse((child) => {
    const renderable = child as Object3D & {
      geometry?: { dispose: () => void };
      material?:
        | { dispose: () => void }
        | Array<{ dispose: () => void }>;
    };
    renderable.geometry?.dispose();
    if (Array.isArray(renderable.material)) {
      for (const material of renderable.material) material.dispose();
    } else {
      renderable.material?.dispose();
    }
  });
};

export class ObjectInspectionViewport {
  private readonly host: HTMLElement;
  private readonly scene = new Scene();
  private readonly camera = new PerspectiveCamera(34, 1, 0.1, 100);
  private readonly cameraDirection = new Vector3(
    4.2,
    2.6,
    5.2,
  ).normalize();
  private readonly baseCameraDistance = 7.18;
  private renderer?: WebGLRenderer;
  private controls?: OrbitControls;
  private resizeObserver?: ResizeObserver;
  private objectRoot?: Group;
  private ownsCurrentObject = false;
  private active = false;
  private disposed = false;
  private loadRevision = 0;
  private renderedWidth = 0;
  private renderedHeight = 0;

  public constructor(host: HTMLElement) {
    this.host = host;
    this.scene.background = new Color(0xeaf8f7);
    this.camera.position
      .copy(this.cameraDirection)
      .multiplyScalar(this.baseCameraDistance);
    this.camera.lookAt(0, 0, 0);

    const skyLight = new HemisphereLight(0xf8ffff, 0x3b7180, 2.2);
    const keyLight = new DirectionalLight(0xfff3ce, 3.2);
    keyLight.position.set(-3.5, 5.5, 4.5);
    const fillLight = new DirectionalLight(0xa8eaff, 1.45);
    fillLight.position.set(4, 2.2, -3);
    this.scene.add(skyLight, keyLight, fillLight);
  }

  public setActive(active: boolean): void {
    if (this.disposed || this.active === active) return;
    this.active = active;
    if (active) {
      this.ensureRenderer();
      this.resize();
      this.render();
    }
  }

  public async loadAsset(
    options: Readonly<InspectionAssetOptions>,
  ): Promise<boolean> {
    if (this.disposed) return false;
    this.setActive(true);
    const revision = ++this.loadRevision;
    const gltf = await new GLTFLoader().loadAsync(options.url);
    if (this.disposed || revision !== this.loadRevision) {
      disposeObject(gltf.scene);
      return false;
    }
    this.setObject(gltf.scene, {
      targetSize: options.targetSize,
      yawRadians: options.yawRadians,
      ownsObject: true,
    });
    return true;
  }

  public setObject(
    object: Object3D,
    options: Readonly<InspectionObjectOptions> = {},
  ): void {
    if (this.disposed) return;
    this.clearObject();
    const fit = createInspectionObjectFit(
      object,
      options.targetSize,
      options.yawRadians,
    );
    this.objectRoot = fit.root;
    this.ownsCurrentObject = options.ownsObject === true;
    this.scene.add(fit.root);
    this.controls?.reset();
    this.render();
  }

  public update(): void {
    if (!this.active || !this.renderer) return;
    this.controls?.target.set(0, 0, 0);
    this.controls?.update();
    this.render();
  }

  public dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.loadRevision += 1;
    this.resizeObserver?.disconnect();
    this.controls?.dispose();
    this.clearObject();
    this.renderer?.dispose();
    this.renderer?.domElement.remove();
  }

  private ensureRenderer(): void {
    if (this.renderer) return;
    const renderer = new WebGLRenderer({
      antialias: true,
      alpha: false,
      powerPreference: 'high-performance',
    });
    renderer.outputColorSpace = SRGBColorSpace;
    renderer.toneMapping = ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.05;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.5));
    renderer.domElement.className = 'dock-inspector-canvas';
    renderer.domElement.setAttribute(
      'aria-label',
      'Rotatable vessel inspection view',
    );
    this.host.replaceChildren(renderer.domElement);
    this.renderer = renderer;

    const controls = new OrbitControls(
      this.camera,
      renderer.domElement,
    );
    controls.enableDamping = false;
    controls.enablePan = false;
    controls.zoomToCursor = false;
    controls.mouseButtons.LEFT = MOUSE.ROTATE;
    controls.mouseButtons.MIDDLE = MOUSE.DOLLY;
    controls.mouseButtons.RIGHT = MOUSE.ROTATE;
    controls.touches.ONE = TOUCH.ROTATE;
    controls.touches.TWO = TOUCH.DOLLY_ROTATE;
    controls.minDistance = 3.4;
    controls.maxDistance = 16;
    controls.minPolarAngle = Math.PI * 0.18;
    controls.maxPolarAngle = Math.PI * 0.78;
    controls.target.set(0, 0, 0);
    controls.saveState();
    this.controls = controls;

    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(this.host);
  }

  private resize(): void {
    if (!this.renderer) return;
    const bounds = this.host.getBoundingClientRect();
    const width = Math.max(1, Math.floor(bounds.width));
    const height = Math.max(1, Math.floor(bounds.height));
    if (
      width === this.renderedWidth &&
      height === this.renderedHeight
    ) {
      return;
    }
    this.renderedWidth = width;
    this.renderedHeight = height;
    this.renderer.setSize(width, height, false);
    this.camera.aspect = width / height;
    const framingDistance =
      this.baseCameraDistance *
      Math.max(1, 0.82 / this.camera.aspect);
    this.camera.position
      .copy(this.cameraDirection)
      .multiplyScalar(framingDistance);
    this.camera.updateProjectionMatrix();
    this.controls?.saveState();
    this.render();
  }

  private render(): void {
    this.renderer?.render(this.scene, this.camera);
  }

  private clearObject(): void {
    if (!this.objectRoot) return;
    this.objectRoot.removeFromParent();
    if (this.ownsCurrentObject) disposeObject(this.objectRoot);
    this.objectRoot = undefined;
    this.ownsCurrentObject = false;
  }
}
