import {
  BoxGeometry,
  ConeGeometry,
  Color,
  CylinderGeometry,
  Group,
  InstancedMesh,
  Matrix4,
  Mesh,
  MeshStandardMaterial,
  Object3D,
  Scene,
  SphereGeometry,
  Vector3,
} from 'three';
import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';
import {
  OCEAN_SEA_LEVEL,
  type OceanField,
  type OceanSurfaceSample,
} from '../ocean/OceanField';
import { clamp, damp } from '../utils/math';

export type RecoveryServiceState =
  | 'idle'
  | 'outbound'
  | 'dock-pause'
  | 'inbound';

export interface WorldRecoveryStats {
  active: boolean;
  pathPoints: number;
  buoys: number;
  serviceState: RecoveryServiceState;
  serviceTripsCompleted: number;
  serviceProgress: number;
}

interface BuoyVisual {
  anchor: Vector3;
  motion: BuoyMotionProfile;
}

export interface BuoyMotionProfile {
  bobPhase: number;
  bobFrequency: number;
  bobAmplitude: number;
  pitchPhase: number;
  pitchFrequency: number;
  pitchAmplitude: number;
  rollPhase: number;
  rollFrequency: number;
  rollAmplitude: number;
}

const buoyNoise = (index: number, salt: number): number => {
  const value = Math.sin(
    (index + 1) * 91.733 + salt * 37.119,
  ) * 43758.5453;
  return value - Math.floor(value);
};

export const createBuoyMotionProfile = (
  index: number,
): BuoyMotionProfile => ({
  bobPhase: buoyNoise(index, 1) * Math.PI * 2,
  bobFrequency: 0.82 + buoyNoise(index, 2) * 0.48,
  bobAmplitude: 0.032 + buoyNoise(index, 3) * 0.026,
  pitchPhase: buoyNoise(index, 4) * Math.PI * 2,
  pitchFrequency:
    0.68 + buoyNoise(index, 5) * 0.52,
  pitchAmplitude:
    0.034 + buoyNoise(index, 6) * 0.028,
  rollPhase: buoyNoise(index, 7) * Math.PI * 2,
  rollFrequency:
    0.72 + buoyNoise(index, 8) * 0.46,
  rollAmplitude:
    0.036 + buoyNoise(index, 9) * 0.03,
});

const SERVICE_SPEED = 1.38;
const SERVICE_DOCK_PAUSE = 3.5;
const BUOY_COUNT = 7;

export const getServiceCraftHeading = (
  tangentX: number,
  tangentZ: number,
  inbound: boolean,
): number => {
  const direction = inbound ? -1 : 1;
  return Math.atan2(
    tangentX * direction,
    tangentZ * direction,
  );
};

export class WorldRecoverySystem {
  private readonly root = new Group();
  private readonly serviceCraft = new Group();
  private readonly buoys: BuoyVisual[] = [];
  private readonly buoyMeshes: InstancedMesh[] = [];
  private readonly route: Vector3[] = [];
  private readonly routeDistances: number[] = [];
  private readonly sampledPosition = new Vector3();
  private readonly sampledTangent = new Vector3(0, 0, 1);
  private readonly buoyTransform = new Object3D();
  private readonly buoyPartTransform = new Object3D();
  private readonly buoyMatrix = new Matrix4();
  private readonly surface: OceanSurfaceSample = {
    height: OCEAN_SEA_LEVEL,
    normalX: 0,
    normalY: 1,
    normalZ: 0,
  };
  private readonly oceanField: OceanField;

  private active = false;
  private recoveryStrength = 0;
  private totalRouteDistance = 0;
  private serviceState: RecoveryServiceState = 'idle';
  private serviceDistance = 0;
  private servicePauseRemaining = 0;
  private serviceHeading = 0;
  private serviceTripsCompleted = 0;
  private buoySurgeStrength = 0;
  private buoySurgeRemaining = 0;

  public constructor(scene: Scene, oceanField: OceanField) {
    this.oceanField = oceanField;
    this.root.name = 'Visible world recovery';
    this.serviceCraft.name = 'Restored channel service craft';
    this.serviceCraft.visible = false;
    this.createServiceCraft();
    this.root.add(this.serviceCraft);
    scene.add(this.root);
  }

  public setActive(active: boolean): void {
    this.active = active;
    if (!active) this.stopServiceCraft();
  }

  public setChannelPath(points: readonly Vector3[]): void {
    this.clearBuoys();
    this.route.length = 0;
    this.routeDistances.length = 0;
    this.totalRouteDistance = 0;
    for (const point of points) {
      this.route.push(new Vector3(point.x, OCEAN_SEA_LEVEL, point.z));
    }
    if (this.route.length < 2) {
      this.stopServiceCraft();
      return;
    }

    this.routeDistances.push(0);
    for (let index = 1; index < this.route.length; index += 1) {
      const previous = this.route[index - 1];
      const current = this.route[index];
      if (!previous || !current) continue;
      this.totalRouteDistance += previous.distanceTo(current);
      this.routeDistances.push(this.totalRouteDistance);
    }
    this.createBuoys();
    this.serviceDistance = 0;
    this.placeServiceCraft(0, 0, 1);
  }

  public setServiceTripsCompleted(completed: number): void {
    this.serviceTripsCompleted = Math.max(0, Math.floor(completed));
  }

  public canLaunchServiceCraft(): boolean {
    return (
      this.active &&
      this.route.length >= 2 &&
      this.totalRouteDistance > 0.1 &&
      this.serviceState === 'idle'
    );
  }

  public launchServiceCraft(): boolean {
    if (!this.canLaunchServiceCraft()) return false;
    this.serviceState = 'outbound';
    this.serviceDistance = 0;
    this.servicePauseRemaining = 0;
    this.serviceCraft.visible = true;
    this.placeServiceCraft(0, 0, 1);
    return true;
  }

  public triggerBuoySurge(strength: number, duration: number): void {
    if (!this.active || this.buoys.length === 0) return;
    this.buoySurgeStrength = Math.max(
      this.buoySurgeStrength,
      clamp(strength, 0, 1),
    );
    this.buoySurgeRemaining = Math.max(
      this.buoySurgeRemaining,
      clamp(duration, 0.5, 12),
    );
  }

  public update(deltaSeconds: number, worldTime: number): void {
    const delta = clamp(deltaSeconds, 0, 0.1);
    this.recoveryStrength = damp(
      this.recoveryStrength,
      this.active ? 1 : 0,
      1.5,
      delta,
    );
    if (this.buoySurgeRemaining > 0) {
      this.buoySurgeRemaining = Math.max(
        0,
        this.buoySurgeRemaining - delta,
      );
    } else {
      this.buoySurgeStrength *= Math.exp(-delta * 1.8);
      if (this.buoySurgeStrength < 0.002) {
        this.buoySurgeStrength = 0;
      }
    }
    this.updateBuoys(worldTime);
    this.updateServiceCraft(delta, worldTime);
  }

  public getStats(): WorldRecoveryStats {
    const serviceProgress =
      this.totalRouteDistance > 0
        ? clamp(this.serviceDistance / this.totalRouteDistance, 0, 1)
        : 0;
    return {
      active: this.active,
      pathPoints: this.route.length,
      buoys: this.buoys.length,
      serviceState: this.serviceState,
      serviceTripsCompleted: this.serviceTripsCompleted,
      serviceProgress,
    };
  }

  public hasActiveEffect(): boolean {
    return (
      this.buoySurgeRemaining > 0 ||
      this.serviceState !== 'idle'
    );
  }

  public dispose(): void {
    this.root.removeFromParent();
    this.disposeObject(this.root);
    this.buoys.length = 0;
    this.route.length = 0;
    this.routeDistances.length = 0;
  }

  private createBuoys(): void {
    for (let index = 0; index < BUOY_COUNT; index += 1) {
      const fraction = (index + 1) / (BUOY_COUNT + 1);
      const distance = this.totalRouteDistance * fraction;
      this.sampleRoute(distance, this.sampledPosition, this.sampledTangent);
      const side = index % 2 === 0 ? -1 : 1;
      const anchor = this.sampledPosition.clone();
      anchor.x += -this.sampledTangent.z * side * 0.34;
      anchor.z += this.sampledTangent.x * side * 0.34;
      this.buoys.push({
        anchor,
        motion: createBuoyMotionProfile(index),
      });
    }
    this.createBuoyMeshes();
  }

  private createBuoyMeshes(): void {
    const body = new InstancedMesh(
      new CylinderGeometry(0.18, 0.28, 0.48, 10),
      new MeshStandardMaterial({
        color: 0xffffff,
        roughness: 0.62,
        metalness: 0.04,
      }),
      this.buoys.length,
    );
    const collar = new InstancedMesh(
      new CylinderGeometry(0.24, 0.24, 0.11, 10),
      new MeshStandardMaterial({
        color: 0xf4f6ef,
        roughness: 0.76,
      }),
      this.buoys.length,
    );
    const mast = new InstancedMesh(
      new CylinderGeometry(0.035, 0.045, 0.48, 8),
      new MeshStandardMaterial({
        color: 0x263f47,
        roughness: 0.5,
        metalness: 0.22,
      }),
      this.buoys.length,
    );
    const lamp = new InstancedMesh(
      new SphereGeometry(0.075, 8, 6),
      new MeshStandardMaterial({
        color: 0xffdb78,
        emissive: 0xffa83c,
        emissiveIntensity: 2.2,
        roughness: 0.4,
      }),
      this.buoys.length,
    );
    body.name = 'Restored channel buoy bodies';
    collar.name = 'Restored channel buoy collars';
    mast.name = 'Restored channel buoy masts';
    lamp.name = 'Restored channel buoy lamps';
    for (let index = 0; index < this.buoys.length; index += 1) {
      body.setColorAt(
        index,
        new Color(index % 2 === 0 ? 0xf15d45 : 0x38b6a7),
      );
    }
    if (body.instanceColor) body.instanceColor.needsUpdate = true;
    this.buoyMeshes.push(body, collar, mast, lamp);
    for (const mesh of this.buoyMeshes) {
      mesh.visible = false;
      mesh.frustumCulled = false;
      this.root.add(mesh);
    }
  }

  private createServiceCraft(): void {
    const hullMaterial = new MeshStandardMaterial({
      color: 0xe96d42,
      roughness: 0.62,
      metalness: 0.08,
    });
    const deckMaterial = new MeshStandardMaterial({
      color: 0x254b55,
      roughness: 0.56,
      metalness: 0.12,
    });
    const cabinMaterial = new MeshStandardMaterial({
      color: 0xe9f0e9,
      roughness: 0.66,
    });
    const windowMaterial = new MeshStandardMaterial({
      color: 0xffc45f,
      emissive: 0xff9d38,
      emissiveIntensity: 2.3,
      roughness: 0.3,
    });

    const hull = new Mesh(
      new RoundedBoxGeometry(0.9, 0.32, 1.55, 2, 0.12),
      hullMaterial,
    );
    hull.position.y = 0.2;
    this.serviceCraft.add(hull);
    const bow = new Mesh(
      new ConeGeometry(0.46, 0.72, 4),
      hullMaterial,
    );
    bow.rotation.x = Math.PI / 2;
    bow.rotation.y = Math.PI / 4;
    bow.position.set(0, 0.2, 1.08);
    this.serviceCraft.add(bow);
    const deck = new Mesh(
      new BoxGeometry(0.72, 0.1, 1.15),
      deckMaterial,
    );
    deck.position.set(0, 0.42, -0.08);
    this.serviceCraft.add(deck);
    const cabin = new Mesh(
      new RoundedBoxGeometry(0.62, 0.48, 0.62, 2, 0.07),
      cabinMaterial,
    );
    cabin.position.set(0, 0.7, -0.22);
    this.serviceCraft.add(cabin);
    const window = new Mesh(
      new BoxGeometry(0.5, 0.18, 0.025),
      windowMaterial,
    );
    window.position.set(0, 0.75, 0.1);
    this.serviceCraft.add(window);
    const mast = new Mesh(
      new CylinderGeometry(0.025, 0.035, 0.48, 8),
      deckMaterial,
    );
    mast.position.set(0, 1.08, -0.25);
    this.serviceCraft.add(mast);
    const lamp = new Mesh(
      new SphereGeometry(0.055, 8, 6),
      windowMaterial,
    );
    lamp.position.set(0, 1.34, -0.25);
    this.serviceCraft.add(lamp);
    this.serviceCraft.scale.setScalar(0.92);
  }

  private updateBuoys(worldTime: number): void {
    const scale = Math.max(0.001, this.recoveryStrength);
    const surgeAmplitude = 0.72 + this.buoySurgeStrength * 0.78;
    for (const mesh of this.buoyMeshes) {
      mesh.visible = scale > 0.01;
    }
    for (let index = 0; index < this.buoys.length; index += 1) {
      const buoy = this.buoys[index];
      if (!buoy) continue;
      this.oceanField.sampleSurface(
        buoy.anchor.x,
        buoy.anchor.z,
        worldTime,
        surgeAmplitude,
        this.surface,
      );
      this.buoyTransform.position.set(
        buoy.anchor.x,
        this.surface.height +
          0.05 +
          Math.sin(
            worldTime * buoy.motion.bobFrequency +
              buoy.motion.bobPhase,
          ) *
            buoy.motion.bobAmplitude *
            (1 + this.buoySurgeStrength * 0.72),
        buoy.anchor.z,
      );
      this.buoyTransform.rotation.x =
        this.surface.normalZ * 0.48 +
        Math.sin(
          worldTime * buoy.motion.pitchFrequency +
            buoy.motion.pitchPhase,
        ) *
          buoy.motion.pitchAmplitude *
          (1 + this.buoySurgeStrength * 0.8);
      this.buoyTransform.rotation.y =
        Math.sin(
          worldTime * 0.24 + buoy.motion.rollPhase,
        ) * 0.025;
      this.buoyTransform.rotation.z =
        -this.surface.normalX * 0.48 +
        Math.sin(
          worldTime * buoy.motion.rollFrequency +
            buoy.motion.rollPhase,
        ) *
          buoy.motion.rollAmplitude *
          (1 + this.buoySurgeStrength * 0.8);
      this.buoyTransform.scale.setScalar(scale);
      this.buoyTransform.updateMatrix();
      this.updateBuoyPart(index, 0, 0.18);
      this.updateBuoyPart(index, 1, 0.42);
      this.updateBuoyPart(index, 2, 0.69);
      this.updateBuoyPart(index, 3, 0.95);
    }
    for (const mesh of this.buoyMeshes) {
      mesh.instanceMatrix.needsUpdate = true;
    }
  }

  private updateBuoyPart(
    index: number,
    meshIndex: number,
    localY: number,
  ): void {
    const mesh = this.buoyMeshes[meshIndex];
    if (!mesh) return;
    this.buoyPartTransform.position.set(0, localY, 0);
    this.buoyPartTransform.rotation.set(0, 0, 0);
    this.buoyPartTransform.scale.set(1, 1, 1);
    this.buoyPartTransform.updateMatrix();
    this.buoyMatrix.multiplyMatrices(
      this.buoyTransform.matrix,
      this.buoyPartTransform.matrix,
    );
    mesh.setMatrixAt(index, this.buoyMatrix);
  }

  private updateServiceCraft(
    deltaSeconds: number,
    worldTime: number,
  ): void {
    if (this.serviceState === 'idle') return;
    if (this.serviceState === 'dock-pause') {
      this.servicePauseRemaining -= deltaSeconds;
      this.placeServiceCraft(
        this.totalRouteDistance,
        worldTime,
        deltaSeconds,
      );
      if (this.servicePauseRemaining <= 0) {
        this.serviceState = 'inbound';
      }
      return;
    }

    const direction = this.serviceState === 'outbound' ? 1 : -1;
    this.serviceDistance += direction * SERVICE_SPEED * deltaSeconds;
    if (
      this.serviceState === 'outbound' &&
      this.serviceDistance >= this.totalRouteDistance
    ) {
      this.serviceDistance = this.totalRouteDistance;
      this.serviceState = 'dock-pause';
      this.servicePauseRemaining = SERVICE_DOCK_PAUSE;
    } else if (
      this.serviceState === 'inbound' &&
      this.serviceDistance <= 0
    ) {
      this.serviceDistance = 0;
      this.serviceTripsCompleted += 1;
      this.stopServiceCraft();
      return;
    }
    this.placeServiceCraft(
      this.serviceDistance,
      worldTime,
      deltaSeconds,
    );
  }

  private placeServiceCraft(
    distance: number,
    worldTime: number,
    deltaSeconds: number,
  ): void {
    if (this.route.length < 2) return;
    this.sampleRoute(distance, this.sampledPosition, this.sampledTangent);
    this.oceanField.sampleSurface(
      this.sampledPosition.x,
      this.sampledPosition.z,
      worldTime,
      0.82,
      this.surface,
    );
    const targetHeading = getServiceCraftHeading(
      this.sampledTangent.x,
      this.sampledTangent.z,
      this.serviceState === 'inbound',
    );
    const headingDelta = Math.atan2(
      Math.sin(targetHeading - this.serviceHeading),
      Math.cos(targetHeading - this.serviceHeading),
    );
    this.serviceHeading +=
      headingDelta *
      (1 - Math.exp(-4.2 * deltaSeconds));
    this.serviceCraft.position.set(
      this.sampledPosition.x,
      this.surface.height + 0.18,
      this.sampledPosition.z,
    );
    this.serviceCraft.rotation.set(
      this.surface.normalZ * 0.18,
      this.serviceHeading,
      -this.surface.normalX * 0.18,
    );
  }

  private sampleRoute(
    distance: number,
    target: Vector3,
    tangent: Vector3,
  ): void {
    const clampedDistance = clamp(
      distance,
      0,
      this.totalRouteDistance,
    );
    let segment = 1;
    while (
      segment < this.routeDistances.length - 1 &&
      (this.routeDistances[segment] ?? 0) < clampedDistance
    ) {
      segment += 1;
    }
    const start = this.route[segment - 1] ?? this.route[0];
    const end =
      this.route[segment] ??
      this.route[this.route.length - 1];
    const startDistance = this.routeDistances[segment - 1] ?? 0;
    const endDistance =
      this.routeDistances[segment] ?? this.totalRouteDistance;
    const progress =
      endDistance > startDistance
        ? (clampedDistance - startDistance) /
          (endDistance - startDistance)
        : 0;
    if (!start || !end) {
      target.set(0, OCEAN_SEA_LEVEL, 0);
      tangent.set(0, 0, 1);
      return;
    }
    target.copy(start).lerp(end, progress);
    tangent.subVectors(end, start).setY(0);
    if (tangent.lengthSq() < 0.0001) {
      tangent.set(0, 0, 1);
    } else {
      tangent.normalize();
    }
  }

  private stopServiceCraft(): void {
    this.serviceState = 'idle';
    this.serviceCraft.visible = false;
    this.servicePauseRemaining = 0;
  }

  private clearBuoys(): void {
    for (const mesh of this.buoyMeshes) {
      this.root.remove(mesh);
      mesh.geometry.dispose();
      const materials = Array.isArray(mesh.material)
        ? mesh.material
        : [mesh.material];
      for (const material of materials) material.dispose();
    }
    this.buoyMeshes.length = 0;
    this.buoys.length = 0;
  }

  private disposeObject(object: Object3D): void {
    for (const child of object.children) this.disposeObject(child);
    const mesh = object as Mesh;
    mesh.geometry?.dispose();
    if (mesh.material) {
      const materials = Array.isArray(mesh.material)
        ? mesh.material
        : [mesh.material];
      for (const material of materials) material.dispose();
    }
  }
}
