import {
  cloneConstructionPlacement,
  sanitizeConstructionBlueprint,
  type ConstructionPlacement,
} from '../../construction/ConstructionBlueprint';
import { validateConstructionConnections } from '../../construction/ConstructionConnectionRules';
import {
  cloneConstructionMetadata,
  cloneReplicatedConstructionSite,
  type ConstructionStateBaselinePartPayload,
  type ConstructionStateDeltaPayload,
  type ConstructionStateResyncRequestPayload,
  type ReplicatedConstructionSite,
  type ReplicatedConstructionSiteManifest,
} from '../../netcode/protocol/ConstructionReplication';

export interface ConstructionReplicationClientDiagnostics {
  revision: number;
  sites: number;
  pieces: number;
  completedBaselines: number;
  appliedDeltas: number;
  staleDeltas: number;
  rejectedBaselines: number;
  rejectedDeltas: number;
  resyncRequests: number;
  pendingTransfers: number;
}

export type ConstructionReplicationClientEvent =
  | {
      readonly kind: 'BASELINE';
      readonly payload: Readonly<ConstructionStateBaselinePartPayload>;
      readonly sites: readonly ReplicatedConstructionSite[];
    }
  | {
      readonly kind: 'DELTA';
      readonly payload: Readonly<ConstructionStateDeltaPayload>;
      readonly site: Readonly<ReplicatedConstructionSite>;
    };

interface PendingBaselineTransfer {
  readonly transferId: string;
  readonly scope: ConstructionStateBaselinePartPayload['scope'];
  readonly revision: number;
  readonly partCount: number;
  readonly manifestsHash: string;
  readonly manifests: readonly ReplicatedConstructionSiteManifest[];
  readonly parts: Map<number, ConstructionStateBaselinePartPayload>;
}

const cloneManifest = (
  manifest: Readonly<ReplicatedConstructionSiteManifest>,
): ReplicatedConstructionSiteManifest => ({
  ...manifest,
  anchor: {
    chunk: { ...manifest.anchor.chunk },
    local: { ...manifest.anchor.local },
  },
  access: manifest.access.mode === 'OWNER_ONLY'
    ? { ...manifest.access }
    : { mode: manifest.access.mode },
  resources: manifest.resources.mode === 'AUTHORITY_INVENTORY'
    ? { ...manifest.resources }
    : { mode: 'DEV_UNLIMITED' },
  blueprint: cloneConstructionMetadata(manifest.blueprint),
});

const manifestIdentity = (
  manifests: readonly Readonly<ReplicatedConstructionSiteManifest>[],
): string => JSON.stringify(manifests);

/** Applies only complete authority baselines and contiguous revision deltas. */
export class ConstructionReplicationClient {
  private readonly sites = new Map<string, ReplicatedConstructionSite>();
  private readonly pendingTransfers = new Map<string, PendingBaselineTransfer>();
  private readonly pendingResync = new Map<string, ConstructionStateResyncRequestPayload>();
  private revisionValue = 0;
  private completedBaselines = 0;
  private appliedDeltas = 0;
  private staleDeltas = 0;
  private rejectedBaselines = 0;
  private rejectedDeltas = 0;
  private resyncRequestCount = 0;

  public constructor(
    private readonly expectedWorldDatasetHash: string,
    private readonly requestResync?: (
      request: Readonly<ConstructionStateResyncRequestPayload>,
    ) => void,
  ) {}

  public get revision(): number {
    return this.revisionValue;
  }

  public listSites(): readonly ReplicatedConstructionSite[] {
    return [...this.sites.values()]
      .sort((left, right) => left.siteId.localeCompare(right.siteId))
      .map(cloneReplicatedConstructionSite);
  }

  public getSite(siteId: string): ReplicatedConstructionSite | undefined {
    const site = this.sites.get(siteId);
    return site ? cloneReplicatedConstructionSite(site) : undefined;
  }

  public diagnostics(): ConstructionReplicationClientDiagnostics {
    return {
      revision: this.revisionValue,
      sites: this.sites.size,
      pieces: [...this.sites.values()].reduce(
        (total, site) => total + site.blueprint.placements.length,
        0,
      ),
      completedBaselines: this.completedBaselines,
      appliedDeltas: this.appliedDeltas,
      staleDeltas: this.staleDeltas,
      rejectedBaselines: this.rejectedBaselines,
      rejectedDeltas: this.rejectedDeltas,
      resyncRequests: this.resyncRequestCount,
      pendingTransfers: this.pendingTransfers.size,
    };
  }

  public applyBaselinePart(
    payload: Readonly<ConstructionStateBaselinePartPayload>,
  ): ConstructionReplicationClientEvent | undefined {
    if (payload.worldDatasetHash !== this.expectedWorldDatasetHash) {
      this.rejectedBaselines += 1;
      return undefined;
    }
    if (payload.revision < this.revisionValue && payload.scope === 'FULL') {
      this.rejectedBaselines += 1;
      return undefined;
    }
    const manifestsHash = manifestIdentity(payload.sites);
    let transfer = this.pendingTransfers.get(payload.transferId);
    if (!transfer) {
      transfer = {
        transferId: payload.transferId,
        scope: payload.scope,
        revision: payload.revision,
        partCount: payload.partCount,
        manifestsHash,
        manifests: payload.sites.map(cloneManifest),
        parts: new Map(),
      };
      this.pendingTransfers.set(payload.transferId, transfer);
      while (this.pendingTransfers.size > 4) {
        const oldest = this.pendingTransfers.keys().next().value as string | undefined;
        if (!oldest) break;
        this.pendingTransfers.delete(oldest);
      }
    }
    if (
      transfer.scope !== payload.scope ||
      transfer.revision !== payload.revision ||
      transfer.partCount !== payload.partCount ||
      transfer.manifestsHash !== manifestsHash
    ) {
      this.pendingTransfers.delete(payload.transferId);
      this.rejectedBaselines += 1;
      this.queueResync({
        version: 1,
        kind: 'CONSTRUCTION_STATE_RESYNC_REQUEST',
        observedRevision: this.revisionValue,
        scope: 'FULL',
      });
      return undefined;
    }
    const existingPart = transfer.parts.get(payload.partIndex);
    if (existingPart && JSON.stringify(existingPart) !== JSON.stringify(payload)) {
      this.pendingTransfers.delete(payload.transferId);
      this.rejectedBaselines += 1;
      this.queueResync({
        version: 1,
        kind: 'CONSTRUCTION_STATE_RESYNC_REQUEST',
        observedRevision: this.revisionValue,
        scope: 'FULL',
      });
      return undefined;
    }
    if (!existingPart) {
      transfer.parts.set(payload.partIndex, payload);
    }
    if (transfer.parts.size !== transfer.partCount) return undefined;
    this.pendingTransfers.delete(payload.transferId);
    const assembled = this.assembleBaseline(transfer);
    if (!assembled) {
      this.rejectedBaselines += 1;
      this.queueResync({
        version: 1,
        kind: 'CONSTRUCTION_STATE_RESYNC_REQUEST',
        observedRevision: this.revisionValue,
        scope: 'FULL',
      });
      return undefined;
    }
    if (payload.scope === 'FULL') this.sites.clear();
    for (const site of assembled) this.sites.set(site.siteId, site);
    this.revisionValue = payload.revision;
    this.completedBaselines += 1;
    this.pendingResync.clear();
    return {
      kind: 'BASELINE',
      payload,
      sites: assembled.map(cloneReplicatedConstructionSite),
    };
  }

  public applyDelta(
    payload: Readonly<ConstructionStateDeltaPayload>,
  ): ConstructionReplicationClientEvent | undefined {
    if (payload.revision <= this.revisionValue) {
      this.staleDeltas += 1;
      return undefined;
    }
    if (payload.baseRevision !== this.revisionValue) {
      this.rejectedDeltas += 1;
      this.queueResync({
        version: 1,
        kind: 'CONSTRUCTION_STATE_RESYNC_REQUEST',
        observedRevision: this.revisionValue,
        scope: 'FULL',
      });
      return undefined;
    }
    const change = payload.change;
    const current = this.sites.get(change.siteId);
    if (
      !current ||
      current.blueprint.id !== change.blueprintId ||
      current.blueprint.revision !== change.baseBlueprintRevision ||
      !change.metadata ||
      change.metadata.id !== change.blueprintId ||
      change.metadata.revision !== change.blueprintRevision
    ) {
      this.rejectedDeltas += 1;
      this.queueResync({
        version: 1,
        kind: 'CONSTRUCTION_STATE_RESYNC_REQUEST',
        observedRevision: this.revisionValue,
        scope: 'SITE',
        siteId: change.siteId,
      });
      return undefined;
    }
    const removed = new Set(change.removedPlacementIds);
    const upserts = new Map(
      change.upsertedPlacements.map((placement) => [placement.id, placement] as const),
    );
    const placements: ConstructionPlacement[] = current.blueprint.placements
      .filter((placement) => !removed.has(placement.id))
      .map((placement) =>
        cloneConstructionPlacement(upserts.get(placement.id) ?? placement));
    const existingIds = new Set(placements.map((placement) => placement.id));
    for (const placement of change.upsertedPlacements) {
      if (!existingIds.has(placement.id)) {
        placements.push(cloneConstructionPlacement(placement));
        existingIds.add(placement.id);
      }
    }
    const blueprint = sanitizeConstructionBlueprint({
      ...change.metadata,
      placements,
    });
    const connections = blueprint
      ? validateConstructionConnections(blueprint)
      : { accepted: false };
    if (!blueprint || !connections.accepted) {
      this.rejectedDeltas += 1;
      this.queueResync({
        version: 1,
        kind: 'CONSTRUCTION_STATE_RESYNC_REQUEST',
        observedRevision: this.revisionValue,
        scope: 'SITE',
        siteId: change.siteId,
      });
      return undefined;
    }
    const next: ReplicatedConstructionSite = {
      ...current,
      resources: change.resources
        ? change.resources.mode === 'AUTHORITY_INVENTORY'
          ? { ...change.resources }
          : { mode: 'DEV_UNLIMITED' }
        : current.resources.mode === 'AUTHORITY_INVENTORY'
          ? { ...current.resources }
          : { mode: 'DEV_UNLIMITED' },
      blueprint,
    };
    this.sites.set(next.siteId, next);
    this.revisionValue = payload.revision;
    this.appliedDeltas += 1;
    this.pendingResync.delete(`SITE:${next.siteId}`);
    return {
      kind: 'DELTA',
      payload,
      site: cloneReplicatedConstructionSite(next),
    };
  }

  public drainResyncRequests(): readonly ConstructionStateResyncRequestPayload[] {
    if (this.requestResync) return [];
    const result = [...this.pendingResync.values()];
    this.pendingResync.clear();
    return result;
  }

  public reset(): void {
    this.sites.clear();
    this.pendingTransfers.clear();
    this.pendingResync.clear();
    this.revisionValue = 0;
  }

  private assembleBaseline(
    transfer: Readonly<PendingBaselineTransfer>,
  ): ReplicatedConstructionSite[] | undefined {
    const batches = [...transfer.parts.values()]
      .sort((left, right) => left.partIndex - right.partIndex)
      .flatMap((part) => part.pieceBatches);
    const result: ReplicatedConstructionSite[] = [];
    for (const manifest of transfer.manifests) {
      const slots = new Array<ConstructionPlacement | undefined>(
        manifest.placementCount,
      );
      for (const batch of batches.filter((item) => item.siteId === manifest.siteId)) {
        if (batch.placementOffset + batch.placements.length > slots.length) {
          return undefined;
        }
        for (let index = 0; index < batch.placements.length; index += 1) {
          const target = batch.placementOffset + index;
          if (slots[target]) return undefined;
          slots[target] = cloneConstructionPlacement(batch.placements[index]!);
        }
      }
      if (slots.some((placement) => !placement)) return undefined;
      const blueprint = sanitizeConstructionBlueprint({
        ...manifest.blueprint,
        placements: slots,
      });
      const connections = blueprint
        ? validateConstructionConnections(blueprint)
        : { accepted: false };
      if (
        !blueprint ||
        !connections.accepted ||
        new Set(blueprint.placements.map((placement) => placement.id)).size !==
          blueprint.placements.length
      ) return undefined;
      result.push({
        siteId: manifest.siteId,
        anchor: {
          chunk: { ...manifest.anchor.chunk },
          local: { ...manifest.anchor.local },
        },
        access: manifest.access.mode === 'OWNER_ONLY'
          ? { ...manifest.access }
          : { mode: manifest.access.mode },
        resources: manifest.resources.mode === 'AUTHORITY_INVENTORY'
          ? { ...manifest.resources }
          : { mode: 'DEV_UNLIMITED' },
        blueprint,
      });
    }
    return result;
  }

  private queueResync(
    request: ConstructionStateResyncRequestPayload,
  ): void {
    const key = request.scope === 'FULL' ? 'FULL' : `SITE:${request.siteId}`;
    if (this.pendingResync.has(key)) return;
    if (request.scope === 'FULL') this.pendingResync.clear();
    if (this.pendingResync.has('FULL')) return;
    this.pendingResync.set(key, request);
    this.resyncRequestCount += 1;
    this.requestResync?.(request);
  }
}
