import type { WildernessInventory } from './WildernessSurvivalSimulation';

export type SurvivalHearthRecipeId =
  | 'EMBER_FISH'
  | 'ROASTED_ROOT'
  | 'SMALL_GAME_ROAST'
  | 'BERRY_ROOT'
  | 'FROSTBERRY_TONIC'
  | 'FIRE_ROOT_EXTRACT';

export interface SurvivalHearthRecipeIngredient {
  readonly inventory: keyof WildernessInventory;
  readonly amount: number;
  readonly label: string;
}

export interface SurvivalHearthRecipeDefinition {
  readonly id: SurvivalHearthRecipeId;
  readonly name: string;
  readonly category: 'FOOD' | 'REMEDY';
  readonly description: string;
  readonly ingredients: readonly SurvivalHearthRecipeIngredient[];
  readonly output: Readonly<{
    inventory: keyof WildernessInventory;
    amount: number;
    label: string;
  }>;
  readonly durationSeconds: number;
  /** Normalized useful hearth heat; retained masonry heat can finish a pot. */
  readonly minimumHeat: number;
}

/**
 * One data contract serves the fireplace insert now and later cauldrons,
 * ovens, drying racks and alchemical benches. Stations choose compatible
 * recipe ids; recipes never know about a particular mesh or building.
 */
export const SURVIVAL_HEARTH_RECIPE_CATALOG:
readonly SurvivalHearthRecipeDefinition[] = [
  {
    id: 'EMBER_FISH',
    name: 'Ember fish',
    category: 'FOOD',
    description: 'Slow-roasted fish that keeps its warmth for the next journey.',
    ingredients: [{ inventory: 'fish', amount: 1, label: 'raw fish' }],
    output: { inventory: 'emberFish', amount: 1, label: 'ember fish' },
    durationSeconds: 12,
    minimumHeat: 0.18,
  },
  {
    id: 'ROASTED_ROOT',
    name: 'Roasted winter root',
    category: 'FOOD',
    description: 'A buried root turned sweet in the stone hearth.',
    ingredients: [{ inventory: 'roots', amount: 1, label: 'winter root' }],
    output: { inventory: 'roastedRoots', amount: 1, label: 'roasted root' },
    durationSeconds: 15,
    minimumHeat: 0.16,
  },
  {
    id: 'SMALL_GAME_ROAST',
    name: 'Small-game roast',
    category: 'FOOD',
    description: 'A substantial meal cooked slowly beside the coals.',
    ingredients: [{ inventory: 'smallGame', amount: 1, label: 'small game' }],
    output: { inventory: 'roastedGame', amount: 1, label: 'small-game roast' },
    durationSeconds: 24,
    minimumHeat: 0.24,
  },
  {
    id: 'BERRY_ROOT',
    name: 'Berry-glazed root',
    category: 'FOOD',
    description: 'Frostberry sharpness over a warm roasted root.',
    ingredients: [
      { inventory: 'roots', amount: 1, label: 'winter root' },
      { inventory: 'berries', amount: 1, label: 'frost berries' },
    ],
    output: { inventory: 'berryRootMeals', amount: 1, label: 'berry-glazed root' },
    durationSeconds: 22,
    minimumHeat: 0.2,
  },
  {
    id: 'FROSTBERRY_TONIC',
    name: 'Frostberry warming tonic',
    category: 'REMEDY',
    description: 'A gentle field remedy for wet cold and tired hands.',
    ingredients: [
      { inventory: 'berries', amount: 2, label: 'frost berries' },
      { inventory: 'roots', amount: 1, label: 'winter root' },
    ],
    output: { inventory: 'frostberryTonics', amount: 1, label: 'warming tonic' },
    durationSeconds: 28,
    minimumHeat: 0.26,
  },
  {
    id: 'FIRE_ROOT_EXTRACT',
    name: 'Amber fire-root extract',
    category: 'REMEDY',
    description: 'A volatile Echo Sight dose kept just below a rolling boil.',
    ingredients: [
      { inventory: 'fireRoot', amount: 2, label: 'fire-root rhizomes' },
      { inventory: 'berries', amount: 1, label: 'frost berries' },
    ],
    output: { inventory: 'fireRootExtract', amount: 1, label: 'fire-root extract' },
    durationSeconds: 44,
    minimumHeat: 0.34,
  },
] as const;

export const survivalHearthRecipe = (
  id: SurvivalHearthRecipeId,
): Readonly<SurvivalHearthRecipeDefinition> => {
  const recipe = SURVIVAL_HEARTH_RECIPE_CATALOG.find((entry) => entry.id === id);
  if (!recipe) throw new Error(`Unknown survival hearth recipe: ${id}`);
  return recipe;
};

