const clamp01 = (value: number): number =>
  Math.max(0, Math.min(1, value));

const smoothstep = (edge0: number, edge1: number, value: number): number => {
  const t = clamp01((value - edge0) / (edge1 - edge0));
  return t * t * (3 - 2 * t);
};

export const calculateSurfaceCurrentScale = (
  openness: number,
  channelContrast = 0,
): number => {
  const permeability = smoothstep(0.12, 0.88, openness);
  const constrictionBoost =
    1 + smoothstep(0.04, 0.58, channelContrast) * 0.48;
  return (0.14 + permeability * 1.16) * constrictionBoost;
};

export const calculateRefreezeMultiplier = (
  effectiveCurrentSpeed: number,
  seaState: number,
): number => {
  const currentEnergy = smoothstep(0.012, 0.085, effectiveCurrentSpeed);
  const waveEnergy = smoothstep(0.18, 0.92, seaState);
  return Math.max(
    0.14,
    Math.min(1.08, 1.08 - currentEnergy * 0.68 - waveEnergy * 0.26),
  );
};
