export interface RadioMessage {
  id: string;
  sourceEventId: string;
  category: RadioCategory;
  priority: number;
  title: string;
  body: string;
  occurredAt: number;
  receivedAt: number;
  dedupeKey: string;
  targetRefs: WorldTargetRef[];
  urgent: boolean;
  acknowledgedAt?: number;
  stationId?: string;
  frequencyId?: string;
  receivedSignalBand?: RadioSignalBand;
  bestSignalBand?: RadioSignalBand;
  receivedSignalStrength?: number;
  bestSignalStrength?: number;
  signalDetail?: RadioSignalDetail;
  presentedSignalBand?: RadioSignalBand;
  locationUncertaintyMetres?: number;
  musicTrackId?: string;
  voiceProfileId?: string;
}

interface RadioSystemSaveDataContents {
  messages: RadioMessage[];
  dedupeEntries: {
    key: string;
    receivedAt: number;
  }[];
  processedEventIds: string[];
  mutedCategories?: RadioCategory[];
}

export interface RadioSystemSaveDataV1
  extends RadioSystemSaveDataContents {
  version: 1;
}

export interface RadioSystemSaveDataV2
  extends RadioSystemSaveDataContents {
  version: 2;
  network: RadioNetworkSaveDataV1;
}

export interface RadioSystemSaveDataV3
  extends RadioSystemSaveDataContents {
  version: 3;
  network: RadioNetworkSaveData;
}

export interface RadioSystemSaveDataV4
  extends RadioSystemSaveDataContents {
  version: 4;
  network: RadioNetworkSaveData;
  pendingBroadcasts: LogicalRadioBroadcast[];
  broadcastSupersessionEntries:
    RadioBroadcastSupersessionEntry[];
}

export interface RadioSystemSaveData
  extends RadioSystemSaveDataContents {
  version: 5;
  network: RadioNetworkSaveData;
  /** Delivery queue for this receiver. */
  pendingBroadcasts: LogicalRadioBroadcast[];
  /** Active canonical broadcasts, independent from receiver delivery. */
  logicalBroadcasts: LogicalRadioBroadcast[];
  broadcastSupersessionEntries:
    RadioBroadcastSupersessionEntry[];
}

export type CompatibleRadioSystemSaveData =
  | RadioSystemSaveDataV1
  | RadioSystemSaveDataV2
  | RadioSystemSaveDataV3
  | RadioSystemSaveDataV4
  | RadioSystemSaveData;

