const MAX_MESSAGES = 80;
const MAX_DEDUPE_ENTRIES = 160;
const MAX_PROCESSED_EVENT_IDS = 256;
export const MAX_PENDING_RADIO_BROADCASTS = 48;
const MAX_BROADCAST_SUPERSESSION_ENTRIES = 128;
const MAX_BROADCAST_DELIVERIES_PER_PROCESS = 3;
const URGENT_PRIORITY = 70;
export const RADIO_TUNING_STEP_MHZ = 0.05;
export const RADIO_TUNING_LOCK_TOLERANCE_MHZ = 0.015;
const RADIO_TUNING_RANGE_MARGIN_MHZ = 0.5;

const RADIO_CHANNEL_TYPES = new Set<RadioChannelType>([
  'HARBOR_CONTROL',
  'EMERGENCY',
  'LOCAL',
  'OPEN_BAND',
  'WEATHER_AND_ICE',
  'UNKNOWN',
]);

const RADIO_TOWER_STATES = new Set<RadioTowerState>([
  'OFFLINE',
  'DAMAGED',
  'WEAK',
  'ONLINE',
  'UPGRADED',
]);

const RADIO_SIGNAL_BAND_ORDER: readonly RadioSignalBand[] = [
  'NO_SIGNAL',
  'CARRIER_ONLY',
  'FRAGMENTED',
  'WEAK',
  'GOOD',
  'CLEAR',
];

export interface RadioReceiverUpgradeProfile {
  upgradeIds: readonly string[];
  rangeMultiplier: number;
  strengthMultiplier: number;
  lockToleranceMhz: number;
  noiseFilterActive: boolean;
  directionFinderActive: boolean;
}

const receiverUpgradeProfile = (
  upgradeIds: readonly string[],
): RadioReceiverUpgradeProfile => {
  const active = new Set(upgradeIds);
  return {
    upgradeIds: [...active].sort(),
    rangeMultiplier: active.has('improved-radio-antenna')
      ? 1.12
      : 1,
    strengthMultiplier: active.has('improved-radio-antenna')
      ? 1.08
      : 1,
    lockToleranceMhz: active.has('wideband-scanner')
      ? 0.04
      : RADIO_TUNING_LOCK_TOLERANCE_MHZ,
    noiseFilterActive: active.has('radio-noise-filter'),
    directionFinderActive:
      active.has('radio-direction-finder'),
  };
};

const RADIO_SIGNAL_BANDS = new Set<RadioSignalBand>([
  'CLEAR',
  'GOOD',
  'WEAK',
  'FRAGMENTED',
  'CARRIER_ONLY',
  'NO_SIGNAL',
]);

const RADIO_FREQUENCY_DISCOVERY_SOURCES =
  new Set<RadioFrequencyDiscoverySource>([
    'DEFAULT',
    'MANUAL_TUNING',
    'PORT',
    'TOWER_REPAIR',
    'STORY',
    'LEGACY_SAVE',
  ]);

const cloneTarget = (
  target: Readonly<WorldTargetRef>,
): WorldTargetRef => {
  if (target.kind === 'WORLD_POSITION') {
    return {
      kind: target.kind,
      position: { ...target.position },
    };
  }
  return { ...target };
};

const cloneMessage = (
  message: Readonly<RadioMessage>,
): RadioMessage => ({
  ...message,
  targetRefs: message.targetRefs.map(cloneTarget),
});

const cloneBroadcastContext = (
  context: Readonly<RadioBroadcastContext>,
): RadioBroadcastContext => ({ ...context });

const cloneBroadcast = (
  broadcast: Readonly<LogicalRadioBroadcast>,
): LogicalRadioBroadcast => ({
  ...broadcast,
  context: cloneBroadcastContext(broadcast.context),
  targetRefs: broadcast.targetRefs.map(cloneTarget),
});

const cloneNetworkState = (
  state: Readonly<RadioNetworkRuntimeState>,
): RadioNetworkRuntimeState => ({
  currentChannel: state.currentChannel,
  ...(state.tunedFrequencyId
    ? { tunedFrequencyId: state.tunedFrequencyId }
    : {}),
  autoTune: state.autoTune,
  dialFrequencyMhz: state.dialFrequencyMhz,
  discoveredFrequencyIds: [...state.discoveredFrequencyIds],
  frequencyDiscoveries: state.frequencyDiscoveries.map(
    (value) => ({ ...value }),
  ),
  knownStationIds: [...state.knownStationIds],
  towerStates: state.towerStates.map((value) => ({
    ...value,
  })),
  voiceAssignments: state.voiceAssignments.map((value) => ({
    ...value,
  })),
  signalSourceDiscoveryIds: [
    ...state.signalSourceDiscoveryIds,
  ],
});

const uniqueKnownIds = (
  values: readonly string[] | undefined,
  exists: (id: string) => boolean,
  required: readonly string[] = [],
): string[] => {
  const result = new Set(
    required.filter((id) => exists(id)),
  );
  for (const id of values ?? []) {
    if (
      typeof id === 'string' &&
      id.trim() &&
      exists(id)
    ) {
      result.add(id);
    }
  }
  return [...result].sort();
};

const createDefaultNetworkState = (
  registry: RadioNetworkRegistry,
): RadioNetworkRuntimeState => {
  const defaultFrequency =
    registry.definitions.frequencies.find(
      (frequency) => frequency.defaultKnown,
    );
  return {
    currentChannel:
      defaultFrequency?.channelType ?? 'HARBOR_CONTROL',
    ...(defaultFrequency
      ? { tunedFrequencyId: defaultFrequency.id }
      : {}),
    autoTune: true,
    dialFrequencyMhz:
      defaultFrequency?.frequencyMhz ??
      registry.definitions.frequencies[0]?.frequencyMhz ??
      0,
    discoveredFrequencyIds: registry.definitions.frequencies
      .filter((frequency) => frequency.defaultKnown)
      .map((frequency) => frequency.id)
      .sort(),
    frequencyDiscoveries: registry.definitions.frequencies
      .filter((frequency) => frequency.defaultKnown)
      .map((frequency) => ({
        frequencyId: frequency.id,
        discoveredAt: 0,
        source: 'DEFAULT' as const,
      }))
      .sort((left, right) =>
        left.frequencyId.localeCompare(right.frequencyId),
      ),
    knownStationIds: registry.definitions.stations
      .filter((station) => station.defaultKnown)
      .map((station) => station.id)
      .sort(),
    towerStates: registry.definitions.towers
      .map((tower) => ({
        towerId: tower.id,
        state: tower.initialState,
      }))
      .sort((left, right) =>
        left.towerId.localeCompare(right.towerId),
      ),
    voiceAssignments: [],
    signalSourceDiscoveryIds: registry.definitions.transmitters
      .filter((transmitter) => transmitter.enabledByDefault)
      .map((transmitter) => transmitter.id)
      .sort(),
  };
};

const restoreNetworkState = (
  saved:
    | Readonly<CompatibleRadioNetworkSaveData>
    | undefined,
  registry: RadioNetworkRegistry,
): RadioNetworkRuntimeState => {
  const fallback = createDefaultNetworkState(registry);
  if (saved?.version !== 1 && saved?.version !== 2) {
    return fallback;
  }

  const defaultFrequencies =
    fallback.discoveredFrequencyIds;
  const defaultStations = fallback.knownStationIds;
  const discoveredFrequencyIds = uniqueKnownIds(
    saved.discoveredFrequencyIds,
    (id) => registry.getFrequency(id) !== undefined,
    defaultFrequencies,
  );
  const knownStationIds = uniqueKnownIds(
    saved.knownStationIds,
    (id) => registry.getStation(id) !== undefined,
    defaultStations,
  );

  const savedTowerStates = new Map<string, RadioTowerState>();
  for (const value of saved.towerStates ?? []) {
    if (
      typeof value?.towerId === 'string' &&
      registry.getTower(value.towerId) &&
      RADIO_TOWER_STATES.has(value.state)
    ) {
      savedTowerStates.set(value.towerId, value.state);
    }
  }
  const towerStates: RadioTowerRuntimeState[] =
    registry.definitions.towers
      .map((tower) => ({
        towerId: tower.id,
        state:
          savedTowerStates.get(tower.id) ??
          tower.initialState,
      }))
      .sort((left, right) =>
        left.towerId.localeCompare(right.towerId),
      );

  const voiceAssignmentsByEntity = new Map<
    string,
    RadioVoiceAssignment
  >();
  for (const assignment of saved.voiceAssignments ?? []) {
    if (
      typeof assignment?.entityId === 'string' &&
      assignment.entityId.trim() &&
      typeof assignment.voiceProfileId === 'string' &&
      registry.getVoiceProfile(assignment.voiceProfileId)
    ) {
      voiceAssignmentsByEntity.set(
        assignment.entityId,
        {
          entityId: assignment.entityId,
          voiceProfileId: assignment.voiceProfileId,
        },
      );
    }
  }

  const tunedFrequencyId =
    typeof saved.tunedFrequencyId === 'string' &&
    discoveredFrequencyIds.includes(
      saved.tunedFrequencyId,
    )
      ? saved.tunedFrequencyId
      : fallback.tunedFrequencyId;
  const tunedFrequency = tunedFrequencyId
    ? registry.getFrequency(tunedFrequencyId)
    : undefined;
  const dialFrequencyMhz =
    saved.version === 2 &&
    Number.isFinite(saved.dialFrequencyMhz)
      ? saved.dialFrequencyMhz
      : tunedFrequency?.frequencyMhz ??
        fallback.dialFrequencyMhz;

  const discoveriesByFrequency = new Map<
    string,
    RadioFrequencyDiscoveryRecord
  >();
  if (saved.version === 2) {
    for (const discovery of saved.frequencyDiscoveries ?? []) {
      if (
        typeof discovery?.frequencyId !== 'string' ||
        !discoveredFrequencyIds.includes(
          discovery.frequencyId,
        ) ||
        !Number.isFinite(discovery.discoveredAt) ||
        !RADIO_FREQUENCY_DISCOVERY_SOURCES.has(
          discovery.source,
        ) ||
        discoveriesByFrequency.has(discovery.frequencyId)
      ) {
        continue;
      }
      discoveriesByFrequency.set(
        discovery.frequencyId,
        {
          frequencyId: discovery.frequencyId,
          discoveredAt: Math.max(
            0,
            discovery.discoveredAt,
          ),
          source: discovery.source,
        },
      );
    }
  }
  for (const frequencyId of discoveredFrequencyIds) {
    if (discoveriesByFrequency.has(frequencyId)) continue;
    discoveriesByFrequency.set(frequencyId, {
      frequencyId,
      discoveredAt: 0,
      source:
        registry.getFrequency(frequencyId)?.defaultKnown
          ? 'DEFAULT'
          : 'LEGACY_SAVE',
    });
  }

  return {
    currentChannel: RADIO_CHANNEL_TYPES.has(
      saved.currentChannel,
    )
      ? saved.currentChannel
      : tunedFrequency?.channelType ??
        fallback.currentChannel,
    ...(tunedFrequencyId ? { tunedFrequencyId } : {}),
    autoTune:
      typeof saved.autoTune === 'boolean'
        ? saved.autoTune
        : fallback.autoTune,
    dialFrequencyMhz,
    discoveredFrequencyIds,
    frequencyDiscoveries: [
      ...discoveriesByFrequency.values(),
    ].sort((left, right) =>
      left.frequencyId.localeCompare(right.frequencyId),
    ),
    knownStationIds,
    towerStates,
    voiceAssignments: [...voiceAssignmentsByEntity.values()]
      .sort((left, right) =>
        left.entityId.localeCompare(right.entityId),
      ),
    signalSourceDiscoveryIds: uniqueKnownIds(
      saved.signalSourceDiscoveryIds,
      (id) => registry.getTransmitter(id) !== undefined,
      fallback.signalSourceDiscoveryIds,
    ),
  };
};

const validCategory = (value: unknown): value is RadioCategory =>
  [
    'DISTRESS',
    'TASK_OFFER',
    'ROUTE_WARNING',
    'ROUTE_UPDATE',
    'PORT_UPDATE',
    'TRAFFIC_UPDATE',
    'WEATHER',
    'LOCAL_NOTICE',
    'AMBIENT',
    'STORY',
  ].includes(String(value));

const restoreMessage = (
  value: Readonly<RadioMessage>,
): RadioMessage | undefined => {
  if (
    !value ||
    typeof value !== 'object' ||
    typeof value.id !== 'string' ||
    !value.id.trim() ||
    typeof value.sourceEventId !== 'string' ||
    !value.sourceEventId.trim() ||
    !validCategory(value.category) ||
    !Number.isFinite(value.priority) ||
    typeof value.title !== 'string' ||
    typeof value.body !== 'string' ||
    !Number.isFinite(value.occurredAt) ||
    !Number.isFinite(value.receivedAt) ||
    typeof value.dedupeKey !== 'string' ||
    !value.dedupeKey.trim() ||
    !Array.isArray(value.targetRefs)
  ) {
    return undefined;
  }
  const receivedSignalBand = RADIO_SIGNAL_BANDS.has(
    value.receivedSignalBand as RadioSignalBand,
  )
    ? value.receivedSignalBand
    : undefined;
  const bestSignalBand = RADIO_SIGNAL_BANDS.has(
    value.bestSignalBand as RadioSignalBand,
  )
    ? value.bestSignalBand
    : receivedSignalBand;
  const receivedSignalStrength =
    Number.isFinite(value.receivedSignalStrength)
      ? Math.max(
          0,
          Math.min(1, value.receivedSignalStrength ?? 0),
        )
      : undefined;
  const bestSignalStrength =
    Number.isFinite(value.bestSignalStrength)
      ? Math.max(
          0,
          Math.min(1, value.bestSignalStrength ?? 0),
        )
      : receivedSignalStrength;
  return {
    id: value.id,
    sourceEventId: value.sourceEventId,
    category: value.category,
    priority: Math.max(0, Math.min(100, value.priority)),
    title: value.title,
    body: value.body,
    occurredAt: Math.max(0, value.occurredAt),
    receivedAt: Math.max(0, value.receivedAt),
    dedupeKey: value.dedupeKey,
    targetRefs: value.targetRefs.map(cloneTarget),
    urgent: value.priority >= URGENT_PRIORITY,
    ...(Number.isFinite(value.acknowledgedAt)
      ? {
          acknowledgedAt: Math.max(
            0,
            value.acknowledgedAt ?? 0,
          ),
        }
      : {}),
    ...(typeof value.stationId === 'string' &&
    value.stationId.trim()
      ? { stationId: value.stationId }
      : {}),
    ...(typeof value.frequencyId === 'string' &&
    value.frequencyId.trim()
      ? { frequencyId: value.frequencyId }
      : {}),
    ...(typeof value.musicTrackId === 'string' &&
    value.musicTrackId.trim()
      ? { musicTrackId: value.musicTrackId }
      : {}),
    ...(typeof value.voiceProfileId === 'string' &&
    value.voiceProfileId.trim()
      ? { voiceProfileId: value.voiceProfileId }
      : {}),
    ...(receivedSignalBand
      ? { receivedSignalBand }
      : {}),
    ...(bestSignalBand ? { bestSignalBand } : {}),
    ...(receivedSignalStrength !== undefined
      ? { receivedSignalStrength }
      : {}),
    ...(bestSignalStrength !== undefined
      ? { bestSignalStrength }
      : {}),
  };
};

const restoreBroadcast = (
  value: Readonly<LogicalRadioBroadcast>,
  networkRegistry: RadioNetworkRegistry,
): LogicalRadioBroadcast | undefined => {
  if (
    !value ||
    typeof value !== 'object' ||
    typeof value.id !== 'string' ||
    !value.id.trim() ||
    typeof value.sourceEventId !== 'string' ||
    !value.sourceEventId.trim() ||
    typeof value.definitionId !== 'string' ||
    typeof value.dedupeKey !== 'string' ||
    !value.dedupeKey.trim() ||
    !Number.isFinite(value.occurredAt) ||
    !Number.isFinite(value.expiresAt) ||
    value.expiresAt <= value.occurredAt ||
    !value.context ||
    typeof value.context !== 'object' ||
    !Array.isArray(value.targetRefs) ||
    !value.targetRefs.every(
      (target) =>
        target !== null &&
        typeof target === 'object' &&
        typeof target.kind === 'string',
    )
  ) {
    return undefined;
  }

  const definition = getHarborControlBroadcastDefinition(
    value.definitionId,
  );
  const station = definition
    ? networkRegistry.getStation(definition.stationId)
    : undefined;
  const frequency = definition
    ? networkRegistry.getFrequency(definition.frequencyId)
    : undefined;
  if (
    !definition ||
    !station ||
    !frequency ||
    !station.channelTypes.includes(definition.channelType) ||
    frequency.channelType !== definition.channelType ||
    !isValidHarborBroadcastContext(
      definition.copyKey,
      value.context,
    )
  ) {
    return undefined;
  }

  return {
    id: value.id,
    sourceEventId: value.sourceEventId,
    definitionId: definition.id,
    copyKey: definition.copyKey,
    stationId: definition.stationId,
    channelType: definition.channelType,
    frequencyId: definition.frequencyId,
    category: definition.category,
    priority: definition.priority,
    occurredAt: Math.max(0, value.occurredAt),
    expiresAt: Math.min(
      Math.max(0, value.expiresAt),
      Math.max(0, value.occurredAt) +
        definition.lifetimeSeconds,
    ),
    dedupeKey: value.dedupeKey,
    cooldownSeconds: definition.cooldownSeconds,
    ...(typeof value.supersessionKey === 'string' &&
    value.supersessionKey.trim()
      ? { supersessionKey: value.supersessionKey }
      : {}),
    context: cloneBroadcastContext(value.context),
    targetRefs: value.targetRefs.map(cloneTarget),
  };
};

const restoreSupersessionEntry = (
  value: Readonly<RadioBroadcastSupersessionEntry>,
): RadioBroadcastSupersessionEntry | undefined => {
  if (
    !value ||
    typeof value !== 'object' ||
    typeof value.key !== 'string' ||
    !value.key.trim() ||
    !Number.isFinite(value.occurredAt) ||
    typeof value.sourceEventId !== 'string' ||
    !value.sourceEventId.trim()
  ) {
    return undefined;
  }
  return {
    key: value.key,
    occurredAt: Math.max(0, value.occurredAt),
    sourceEventId: value.sourceEventId,
  };
};

const unreadOrder = (
  left: Readonly<RadioMessage>,
  right: Readonly<RadioMessage>,
): number =>
  right.priority - left.priority ||
  left.receivedAt - right.receivedAt ||
  left.id.localeCompare(right.id);

export class RadioSystem {
  private readonly registry: GameplayRegistry;
  private readonly networkRegistry: RadioNetworkRegistry;
  private readonly networkState: RadioNetworkRuntimeState;
  private readonly coverage: RadioCoverageSystem;
  private readonly messages: RadioMessage[] = [];
  private readonly dedupeReceivedAt = new Map<string, number>();
  private readonly processedEventIds = new Set<string>();
  private readonly processedEventOrder: string[] = [];
  private readonly pendingNotificationIds = new Set<string>();
  private readonly mutedCategories = new Set<RadioCategory>();
  private readonly pendingBroadcasts:
    LogicalRadioBroadcast[] = [];
  private readonly logicalBroadcasts:
    LogicalRadioBroadcast[] = [];
  private readonly latestBroadcastBySupersessionKey =
    new Map<string, RadioBroadcastSupersessionEntry>();
  private lastCoverageSimulationTime?: number;
  private receiverUpgradeProfile =
    receiverUpgradeProfile([]);

  public constructor(
    registry: GameplayRegistry,
    saved?: Readonly<CompatibleRadioSystemSaveData>,
    networkRegistry = new RadioNetworkRegistry(
      V1_RADIO_NETWORK_DEFINITIONS,
    ),
  ) {
    this.registry = registry;
    this.networkRegistry = networkRegistry;
    this.networkState = restoreNetworkState(
      saved?.version === 2 ||
        saved?.version === 3 ||
        saved?.version === 4 ||
        saved?.version === 5
        ? saved.network
        : undefined,
      this.networkRegistry,
    );
    this.coverage = new RadioCoverageSystem(
      this.networkRegistry,
    );
    if (
      saved?.version !== 1 &&
      saved?.version !== 2 &&
      saved?.version !== 3 &&
      saved?.version !== 4 &&
      saved?.version !== 5
    ) {
      return;
    }

    for (const value of saved.messages ?? []) {
      const message = restoreMessage(value);
      if (message) this.messages.push(message);
    }
    this.trimMessages();

    for (const entry of saved.dedupeEntries ?? []) {
      if (
        typeof entry?.key === 'string' &&
        entry.key.trim() &&
        Number.isFinite(entry.receivedAt)
      ) {
        this.dedupeReceivedAt.set(
          entry.key,
          Math.max(0, entry.receivedAt),
        );
      }
    }
    this.trimDedupeEntries();

    for (const eventId of saved.processedEventIds ?? []) {
      if (
        typeof eventId === 'string' &&
        eventId.trim() &&
        !this.processedEventIds.has(eventId)
      ) {
        this.processedEventIds.add(eventId);
        this.processedEventOrder.push(eventId);
      }
    }
    this.trimProcessedEvents();

    for (const category of saved.mutedCategories ?? []) {
      if (validCategory(category)) {
        this.mutedCategories.add(category);
      }
    }

    if (saved.version !== 4 && saved.version !== 5) return;

    for (
      const value of
      saved.broadcastSupersessionEntries ?? []
    ) {
      const entry = restoreSupersessionEntry(value);
      if (!entry) continue;
      const current =
        this.latestBroadcastBySupersessionKey.get(entry.key);
      if (
        !current ||
        entry.occurredAt >= current.occurredAt
      ) {
        this.latestBroadcastBySupersessionKey.delete(
          entry.key,
        );
        this.latestBroadcastBySupersessionKey.set(
          entry.key,
          entry,
        );
      }
    }
    this.trimBroadcastSupersessionEntries();

    for (const value of saved.pendingBroadcasts ?? []) {
      const broadcast = restoreBroadcast(
        value,
        this.networkRegistry,
      );
      if (!broadcast) continue;
      if (
        broadcast.supersessionKey &&
        this.isBroadcastOlderThanLatest(broadcast)
      ) {
        continue;
      }
      this.pendingBroadcasts.push(broadcast);
      this.rememberBroadcastSupersession(broadcast);
    }
    this.trimPendingBroadcasts();

    const savedLogicalBroadcasts = saved.version === 5
      ? saved.logicalBroadcasts
      : saved.pendingBroadcasts;
    for (const value of savedLogicalBroadcasts ?? []) {
      const broadcast = restoreBroadcast(
        value,
        this.networkRegistry,
      );
      if (
        !broadcast ||
        (broadcast.supersessionKey &&
          this.isBroadcastOlderThanLatest(broadcast))
      ) continue;
      this.logicalBroadcasts.push(broadcast);
    }
    this.trimLogicalBroadcasts();
  }

  public process(
    events: readonly WorldDomainEvent[],
    receivedAt: number,
  ): RadioProcessResult {
    const addedMessages: RadioMessage[] = [];
    const suppressedEventIds: string[] = [];
    const queuedBroadcastIds: string[] = [];
    const safeReceivedAt = Math.max(0, receivedAt);
    const expiredBroadcastIds =
      this.expirePendingBroadcasts(safeReceivedAt);

    for (const event of events) {
      if (this.processedEventIds.has(event.eventId)) {
        suppressedEventIds.push(event.eventId);
        continue;
      }
      this.rememberProcessedEvent(event.eventId);

      const broadcastDraft =
        createHarborControlBroadcastDraft(event);
      if (broadcastDraft) {
        const broadcast: LogicalRadioBroadcast = {
          id: `broadcast:${event.eventId}`,
          sourceEventId: event.eventId,
          definitionId: broadcastDraft.definitionId,
          copyKey: broadcastDraft.copyKey,
          stationId: broadcastDraft.stationId,
          channelType: broadcastDraft.channelType,
          frequencyId: broadcastDraft.frequencyId,
          category: broadcastDraft.category,
          priority: broadcastDraft.priority,
          occurredAt: Math.max(0, event.occurredAt),
          expiresAt:
            Math.max(0, event.occurredAt) +
            broadcastDraft.lifetimeSeconds,
          dedupeKey: broadcastDraft.dedupeKey,
          cooldownSeconds:
            broadcastDraft.cooldownSeconds,
          ...(broadcastDraft.supersessionKey
            ? {
                supersessionKey:
                  broadcastDraft.supersessionKey,
              }
            : {}),
          context: cloneBroadcastContext(
            broadcastDraft.context,
          ),
          targetRefs:
            inferWorldEventTargets(event).map(cloneTarget),
        };
        if (
          broadcast.expiresAt <= safeReceivedAt ||
          !this.enqueueBroadcast(broadcast)
        ) {
          suppressedEventIds.push(event.eventId);
          continue;
        }
        queuedBroadcastIds.push(broadcast.id);
        continue;
      }

      const candidate = this.messageForEvent(event);
      if (!candidate) continue;
      const previousReceivedAt = this.dedupeReceivedAt.get(
        candidate.dedupeKey,
      );
      if (
        previousReceivedAt !== undefined &&
        safeReceivedAt - previousReceivedAt <
          candidate.cooldownSeconds
      ) {
        suppressedEventIds.push(event.eventId);
        continue;
      }

      const message: RadioMessage = {
        id: `radio:${event.eventId}`,
        sourceEventId: event.eventId,
        category: candidate.category,
        priority: candidate.priority,
        title: candidate.title,
        body: candidate.body,
        occurredAt: Math.max(0, event.occurredAt),
        receivedAt: safeReceivedAt,
        dedupeKey: candidate.dedupeKey,
        targetRefs:
          inferWorldEventTargets(event).map(cloneTarget),
        urgent: candidate.priority >= URGENT_PRIORITY,
      };
      this.messages.push(message);
      if (!this.isNotificationMuted(message)) {
        this.pendingNotificationIds.add(message.id);
      }
      this.dedupeReceivedAt.set(
        candidate.dedupeKey,
        safeReceivedAt,
      );
      addedMessages.push(cloneMessage(message));
    }

    const delivered =
      this.deliverEligibleBroadcasts(safeReceivedAt);
    addedMessages.push(...delivered.addedMessages);
    suppressedEventIds.push(
      ...delivered.suppressedEventIds,
    );

    this.trimMessages();
    this.trimDedupeEntries();
    return {
      addedMessages,
      suppressedEventIds,
      queuedBroadcastIds,
      expiredBroadcastIds,
      unreadCount: this.getUnreadCount(),
    };
  }

  public acknowledge(
    messageId: string,
    acknowledgedAt: number,
  ): boolean {
    const message = this.messages.find(
      (candidate) => candidate.id === messageId,
    );
    if (!message || message.acknowledgedAt !== undefined) {
      return false;
    }
    message.acknowledgedAt = Math.max(0, acknowledgedAt);
    this.pendingNotificationIds.delete(messageId);
    return true;
  }

  public acknowledgeAll(acknowledgedAt: number): number {
    let changed = 0;
    for (const message of this.messages) {
      if (message.acknowledgedAt !== undefined) continue;
      message.acknowledgedAt = Math.max(0, acknowledgedAt);
      changed += 1;
    }
    this.pendingNotificationIds.clear();
    return changed;
  }

  public getMessages(): readonly RadioMessage[] {
    return [...this.messages]
      .sort(
        (left, right) =>
          right.receivedAt - left.receivedAt ||
          right.priority - left.priority ||
          right.id.localeCompare(left.id),
      )
      .map((message) => this.presentMessage(message));
  }

  public getUnreadMessages(): readonly RadioMessage[] {
    return this.messages
      .filter(
        (message) => message.acknowledgedAt === undefined,
      )
      .sort(unreadOrder)
      .map((message) => this.presentMessage(message));
  }

  public getUnreadCount(): number {
    return this.messages.filter(
      (message) => message.acknowledgedAt === undefined,
    ).length;
  }

  public getMutedCategories(): readonly RadioCategory[] {
    return [...this.mutedCategories].sort();
  }

  public setCategoryMuted(
    category: RadioCategory,
    muted: boolean,
  ): boolean {
    if (!validCategory(category)) return false;
    const wasMuted = this.mutedCategories.has(category);
    if (muted === wasMuted) return false;
    if (muted) {
      this.mutedCategories.add(category);
      for (const message of this.messages) {
        if (this.isNotificationMuted(message)) {
          this.pendingNotificationIds.delete(message.id);
        }
      }
    } else {
      this.mutedCategories.delete(category);
    }
    return true;
  }

  public getPendingBroadcasts():
    readonly LogicalRadioBroadcast[] {
    return [...this.pendingBroadcasts]
      .sort(
        (left, right) =>
          right.priority - left.priority ||
          left.occurredAt - right.occurredAt ||
          left.id.localeCompare(right.id),
      )
      .map(cloneBroadcast);
  }

  /**
   * Active authority broadcasts survive delivery to the local receiver. A
   * multiplayer receiver consuming this view therefore cannot hide a logical
   * broadcast from another player by receiving it first.
   */
  public getLogicalBroadcasts():
    readonly LogicalRadioBroadcast[] {
    return [...this.logicalBroadcasts]
      .sort(
        (left, right) =>
          right.priority - left.priority ||
          left.occurredAt - right.occurredAt ||
          left.id.localeCompare(right.id),
      )
      .map(cloneBroadcast);
  }

  /**
   * Evaluates one authority-owned logical broadcast against this receiver.
   * The source broadcast is not consumed, allowing other player receivers to
   * evaluate the same immutable record independently.
   */
  public receiveLogicalBroadcast(
    broadcast: Readonly<LogicalRadioBroadcast>,
    receivedAt: number,
  ): RadioMessage | undefined {
    const safeReceivedAt = Math.max(0, receivedAt);
    const messageId = `radio:${broadcast.sourceEventId}`;
    if (
      broadcast.expiresAt <= safeReceivedAt ||
      this.messages.some((message) => message.id === messageId) ||
      !this.canReceiveBroadcast(broadcast, safeReceivedAt)
    ) {
      return undefined;
    }
    const previousReceivedAt = this.dedupeReceivedAt.get(
      broadcast.dedupeKey,
    );
    if (
      previousReceivedAt !== undefined &&
      safeReceivedAt - previousReceivedAt < broadcast.cooldownSeconds
    ) {
      return undefined;
    }
    const candidate = this.candidateForBroadcast(broadcast);
    if (!candidate) return undefined;
    const tuning = this.getTuningSnapshot();
    const message: RadioMessage = {
      id: messageId,
      sourceEventId: broadcast.sourceEventId,
      category: candidate.category,
      priority: candidate.priority,
      title: candidate.title,
      body: candidate.body,
      occurredAt: broadcast.occurredAt,
      receivedAt: safeReceivedAt,
      dedupeKey: candidate.dedupeKey,
      targetRefs: broadcast.targetRefs.map(cloneTarget),
      urgent: candidate.priority >= URGENT_PRIORITY,
      stationId: broadcast.stationId,
      frequencyId: broadcast.frequencyId,
      receivedSignalBand: tuning.signalBand,
      bestSignalBand: tuning.signalBand,
      receivedSignalStrength: tuning.signalStrength,
      bestSignalStrength: tuning.signalStrength,
      ...(broadcast.context.musicTrackId
        ? { musicTrackId: broadcast.context.musicTrackId }
        : {}),
      ...(this.voiceProfileForBroadcast(broadcast)
        ? { voiceProfileId: this.voiceProfileForBroadcast(broadcast) }
        : {}),
    };
    this.messages.push(message);
    this.dedupeReceivedAt.set(candidate.dedupeKey, safeReceivedAt);
    if (!this.isNotificationMuted(message)) {
      this.pendingNotificationIds.add(message.id);
    }
    this.trimMessages();
    this.trimDedupeEntries();
    return this.presentMessage(message);
  }

  /** Receives system notices which do not use the frequency broadcast path. */
  public receiveDirectEvents(
    events: readonly WorldDomainEvent[],
    receivedAt: number,
  ): readonly RadioMessage[] {
    const added: RadioMessage[] = [];
    const safeReceivedAt = Math.max(0, receivedAt);
    for (const event of events) {
      if (
        createHarborControlBroadcastDraft(event) ||
        this.processedEventIds.has(event.eventId)
      ) continue;
      this.rememberProcessedEvent(event.eventId);
      const candidate = this.messageForEvent(event);
      if (!candidate) continue;
      const previousReceivedAt = this.dedupeReceivedAt.get(
        candidate.dedupeKey,
      );
      if (
        previousReceivedAt !== undefined &&
        safeReceivedAt - previousReceivedAt < candidate.cooldownSeconds
      ) continue;
      const message: RadioMessage = {
        id: `radio:${event.eventId}`,
        sourceEventId: event.eventId,
        category: candidate.category,
        priority: candidate.priority,
        title: candidate.title,
        body: candidate.body,
        occurredAt: Math.max(0, event.occurredAt),
        receivedAt: safeReceivedAt,
        dedupeKey: candidate.dedupeKey,
        targetRefs: inferWorldEventTargets(event).map(cloneTarget),
        urgent: candidate.priority >= URGENT_PRIORITY,
      };
      this.messages.push(message);
      this.dedupeReceivedAt.set(candidate.dedupeKey, safeReceivedAt);
      if (!this.isNotificationMuted(message)) {
        this.pendingNotificationIds.add(message.id);
      }
      added.push(this.presentMessage(message));
    }
    this.trimMessages();
    this.trimDedupeEntries();
    return added;
  }

  public getNotificationMessage():
    | RadioMessage
    | undefined {
    const message = this.messages
      .filter(
        (candidate) =>
          candidate.acknowledgedAt === undefined &&
          this.pendingNotificationIds.has(candidate.id),
      )
      .sort(unreadOrder)[0];
    return message
      ? this.presentMessage(message)
      : undefined;
  }

  public getNetworkState(): RadioNetworkRuntimeState {
    return cloneNetworkState(this.networkState);
  }

  public setReceiverUpgradeIds(
    upgradeIds: readonly string[],
  ): boolean {
    const next = receiverUpgradeProfile(upgradeIds);
    if (
      next.upgradeIds.join(':') ===
      this.receiverUpgradeProfile.upgradeIds.join(':')
    ) {
      return false;
    }
    this.receiverUpgradeProfile = next;
    this.coverage.invalidate();
    return true;
  }

  public getReceiverUpgradeProfile():
    RadioReceiverUpgradeProfile {
    return {
      ...this.receiverUpgradeProfile,
      upgradeIds: [
        ...this.receiverUpgradeProfile.upgradeIds,
      ],
    };
  }

  public updateCoverage(
    receiverPosition: Readonly<GlobalPosition>,
    simulationTime: number,
  ): RadioCoverageSnapshot {
    this.lastCoverageSimulationTime = Math.max(
      0,
      simulationTime,
    );
    const knownFrequencies =
      this.knownFrequencyDefinitions();
    let eligibleFrequencies: RegionalFrequencyDefinition[];
    if (this.networkState.autoTune) {
      eligibleFrequencies = knownFrequencies.filter(
        (frequency) =>
          frequency.channelType ===
          this.networkState.currentChannel,
      );
      if (eligibleFrequencies.length === 0) {
        eligibleFrequencies = knownFrequencies;
        const fallback = eligibleFrequencies[0];
        if (fallback) {
          this.networkState.currentChannel =
            fallback.channelType;
        }
      }
    } else {
      const candidate = this.frequencyNearDial(
        this.networkState.dialFrequencyMhz,
      );
      eligibleFrequencies = candidate ? [candidate] : [];
      if (candidate) {
        this.networkState.currentChannel =
          candidate.channelType;
        this.networkState.tunedFrequencyId =
          this.networkState.discoveredFrequencyIds.includes(
            candidate.id,
          )
            ? candidate.id
            : undefined;
      } else {
        this.networkState.tunedFrequencyId = undefined;
      }
    }

    const snapshot = this.coverage.update({
      receiverPosition: cloneGlobalPosition(
        receiverPosition,
      ),
      simulationTime,
      channelType: this.networkState.currentChannel,
      frequencyIds: eligibleFrequencies.map(
        (frequency) => frequency.id,
      ),
      towerStates: this.networkState.towerStates,
      receiverRangeMultiplier:
        this.receiverUpgradeProfile.rangeMultiplier,
      receiverStrengthMultiplier:
        this.receiverUpgradeProfile.strengthMultiplier,
    });
    const lockedFrequencyId =
      snapshot.selectedSource?.frequencyId;
    const lockedFrequency = lockedFrequencyId
      ? this.networkRegistry.getFrequency(
          lockedFrequencyId,
        )
      : undefined;
    if (lockedFrequency) {
      if (!this.networkState.autoTune) {
        this.discoverFrequency(
          lockedFrequency.id,
          simulationTime,
          'MANUAL_TUNING',
        );
      }
      this.networkState.tunedFrequencyId =
        lockedFrequency.id;
      this.networkState.currentChannel =
        lockedFrequency.channelType;
      this.networkState.dialFrequencyMhz =
        lockedFrequency.frequencyMhz;
    }
    this.improveReceivedMessages(snapshot);
    return snapshot;
  }

  public getCoverageSnapshot():
    | RadioCoverageSnapshot
    | undefined {
    return this.coverage.getSnapshot();
  }

  public getCoverageStats(): RadioCoverageStats {
    return this.coverage.getStats();
  }

  public getTuningSnapshot(): RadioTuningSnapshot {
    const range = this.tuningRange();
    const coverage = this.coverage.getSnapshot();
    const candidate = this.frequencyNearDial(
      this.networkState.dialFrequencyMhz,
    );
    const locked =
      coverage?.selectedSource !== undefined &&
      coverage.selectedSource.frequencyId ===
        (candidate?.id ??
          this.networkState.tunedFrequencyId);
    const lockState: RadioTuningLockState = locked
      ? 'LOCKED'
      : candidate
        ? 'NO_SIGNAL'
        : 'SEEKING';
    const rawSignalBand = locked
      ? coverage?.signalBand ?? 'NO_SIGNAL'
      : 'NO_SIGNAL';
    const signalBand = this.filteredSignalBand(
      rawSignalBand,
    );
    const bearing = locked
      ? this.signalBearing(coverage)
      : undefined;
    return {
      dialFrequencyMhz:
        this.networkState.dialFrequencyMhz,
      minimumFrequencyMhz: range.minimum,
      maximumFrequencyMhz: range.maximum,
      tuningStepMhz: RADIO_TUNING_STEP_MHZ,
      lockToleranceMhz:
        this.receiverUpgradeProfile.lockToleranceMhz,
      autoTune: this.networkState.autoTune,
      currentChannel: this.networkState.currentChannel,
      ...(this.networkState.tunedFrequencyId
        ? {
            tunedFrequencyId:
              this.networkState.tunedFrequencyId,
          }
        : {}),
      lockState,
      signalBand,
      signalStrength:
        locked ? coverage?.signalStrength ?? 0 : 0,
      ...(locked && coverage?.selectedSource?.stationId
        ? {
            stationId:
              coverage.selectedSource.stationId,
          }
        : {}),
      ...(locked &&
      coverage?.selectedSource?.transmitterId
        ? {
            transmitterId:
              coverage.selectedSource.transmitterId,
          }
        : {}),
      ...(bearing
        ? {
            signalBearingDegrees: bearing.degrees,
            signalBearingUncertaintyDegrees:
              bearing.uncertainty,
            signalRangeMetres: bearing.rangeMetres,
          }
        : {}),
      receiverUpgradeIds: [
        ...this.receiverUpgradeProfile.upgradeIds,
      ],
      receiverRangeMultiplier:
        this.receiverUpgradeProfile.rangeMultiplier,
      noiseFilterActive:
        this.receiverUpgradeProfile.noiseFilterActive,
      knownFrequencyCount:
        this.networkState.discoveredFrequencyIds.length,
      totalFrequencyCount:
        this.networkRegistry.definitions.frequencies.length,
      knownFrequencies: this.knownFrequencyDefinitions().map(
        (frequency) => ({
          id: frequency.id,
          channelType: frequency.channelType,
          frequencyMhz: frequency.frequencyMhz,
        }),
      ),
    };
  }

  public setDialFrequencyMhz(
    frequencyMhz: number,
  ): RadioTuningCommandResult {
    const range = this.tuningRange();
    if (
      !Number.isFinite(frequencyMhz) ||
      frequencyMhz < range.minimum ||
      frequencyMhz > range.maximum
    ) {
      return {
        accepted: false,
        changed: false,
        dialFrequencyMhz:
          this.networkState.dialFrequencyMhz,
        autoTune: this.networkState.autoTune,
        reason: 'INVALID_FREQUENCY',
      };
    }
    const normalized =
      Math.round(frequencyMhz * 1000) / 1000;
    const changed =
      this.networkState.dialFrequencyMhz !== normalized ||
      this.networkState.autoTune;
    this.networkState.dialFrequencyMhz = normalized;
    this.networkState.autoTune = false;
    const candidate = this.frequencyNearDial(normalized);
    if (candidate) {
      this.networkState.currentChannel =
        candidate.channelType;
      this.networkState.tunedFrequencyId =
        this.networkState.discoveredFrequencyIds.includes(
          candidate.id,
        )
          ? candidate.id
          : undefined;
    } else {
      this.networkState.tunedFrequencyId = undefined;
    }
    if (changed) this.coverage.invalidate();
    return {
      accepted: true,
      changed,
      dialFrequencyMhz:
        this.networkState.dialFrequencyMhz,
      autoTune: false,
    };
  }

  public nudgeDial(
    direction: -1 | 1,
  ): RadioTuningCommandResult {
    const range = this.tuningRange();
    const next = Math.max(
      range.minimum,
      Math.min(
        range.maximum,
        this.networkState.dialFrequencyMhz +
          direction * RADIO_TUNING_STEP_MHZ,
      ),
    );
    return this.setDialFrequencyMhz(next);
  }

  public setAutoTune(
    enabled: boolean,
  ): RadioTuningCommandResult {
    if (!enabled) {
      const changed = this.networkState.autoTune;
      this.networkState.autoTune = false;
      if (changed) this.coverage.invalidate();
      return {
        accepted: true,
        changed,
        dialFrequencyMhz:
          this.networkState.dialFrequencyMhz,
        autoTune: false,
      };
    }

    const known = this.knownFrequencyDefinitions();
    if (known.length === 0) {
      return {
        accepted: false,
        changed: false,
        dialFrequencyMhz:
          this.networkState.dialFrequencyMhz,
        autoTune: this.networkState.autoTune,
        reason: 'NO_KNOWN_FREQUENCIES',
      };
    }
    const target =
      (this.networkState.tunedFrequencyId
        ? this.networkRegistry.getFrequency(
            this.networkState.tunedFrequencyId,
          )
        : undefined) ??
      known.find(
        (frequency) =>
          frequency.channelType ===
          this.networkState.currentChannel,
      ) ??
      known[0]!;
    const changed =
      !this.networkState.autoTune ||
      this.networkState.tunedFrequencyId !== target.id ||
      this.networkState.dialFrequencyMhz !==
        target.frequencyMhz;
    this.networkState.autoTune = true;
    this.networkState.tunedFrequencyId = target.id;
    this.networkState.currentChannel =
      target.channelType;
    this.networkState.dialFrequencyMhz =
      target.frequencyMhz;
    if (changed) this.coverage.invalidate();
    return {
      accepted: true,
      changed,
      dialFrequencyMhz:
        this.networkState.dialFrequencyMhz,
      autoTune: true,
    };
  }

  public discoverFrequency(
    frequencyId: string,
    discoveredAt: number,
    source: RadioFrequencyDiscoverySource,
  ): RadioFrequencyDiscoveryResult {
    const frequency =
      this.networkRegistry.getFrequency(frequencyId);
    if (
      !frequency ||
      !RADIO_FREQUENCY_DISCOVERY_SOURCES.has(source)
    ) {
      return {
        accepted: false,
        discovered: false,
        frequencyId,
        knownFrequencyCount:
          this.networkState.discoveredFrequencyIds.length,
      };
    }
    if (
      this.networkState.discoveredFrequencyIds.includes(
        frequencyId,
      )
    ) {
      return {
        accepted: true,
        discovered: false,
        frequencyId,
        knownFrequencyCount:
          this.networkState.discoveredFrequencyIds.length,
      };
    }

    this.networkState.discoveredFrequencyIds.push(
      frequencyId,
    );
    this.networkState.discoveredFrequencyIds.sort();
    this.networkState.frequencyDiscoveries.push({
      frequencyId,
      discoveredAt: Math.max(0, discoveredAt),
      source,
    });
    this.networkState.frequencyDiscoveries.sort(
      (left, right) =>
        left.frequencyId.localeCompare(right.frequencyId),
    );
    for (const transmitter of (
      this.networkRegistry.definitions.transmitters
    )) {
      if (
        transmitter.frequencyId === frequencyId &&
        !this.networkState.knownStationIds.includes(
          transmitter.stationId,
        )
      ) {
        this.networkState.knownStationIds.push(
          transmitter.stationId,
        );
      }
    }
    this.networkState.knownStationIds.sort();
    this.coverage.invalidate();
    return {
      accepted: true,
      discovered: true,
      frequencyId,
      knownFrequencyCount:
        this.networkState.discoveredFrequencyIds.length,
    };
  }

  public setTowerState(
    towerId: string,
    state: RadioTowerState,
  ): boolean {
    if (
      !this.networkRegistry.getTower(towerId) ||
      !RADIO_TOWER_STATES.has(state)
    ) {
      return false;
    }
    const current = this.networkState.towerStates.find(
      (value) => value.towerId === towerId,
    );
    if (!current || current.state === state) return false;
    current.state = state;
    this.coverage.invalidate();
    return true;
  }

  private tuningRange(): {
    minimum: number;
    maximum: number;
  } {
    const values =
      this.networkRegistry.definitions.frequencies.map(
        (frequency) => frequency.frequencyMhz,
      );
    if (values.length === 0) {
      return { minimum: 0, maximum: 1 };
    }
    return {
      minimum:
        Math.floor(
          (Math.min(...values) -
            RADIO_TUNING_RANGE_MARGIN_MHZ) *
            1000,
        ) / 1000,
      maximum:
        Math.ceil(
          (Math.max(...values) +
            RADIO_TUNING_RANGE_MARGIN_MHZ) *
            1000,
        ) / 1000,
    };
  }

  private frequencyNearDial(
    dialFrequencyMhz: number,
  ): RegionalFrequencyDefinition | undefined {
    const nearest = [
      ...this.networkRegistry.definitions.frequencies,
    ].sort(
      (left, right) =>
        Math.abs(
          left.frequencyMhz - dialFrequencyMhz,
        ) -
          Math.abs(
            right.frequencyMhz - dialFrequencyMhz,
          ) ||
        left.id.localeCompare(right.id),
    )[0];
    return nearest &&
      Math.abs(
        nearest.frequencyMhz - dialFrequencyMhz,
      ) <= this.receiverUpgradeProfile.lockToleranceMhz
      ? nearest
      : undefined;
  }

  private filteredSignalBand(
    signalBand: RadioSignalBand,
  ): RadioSignalBand {
    if (
      !this.receiverUpgradeProfile.noiseFilterActive ||
      signalBand === 'NO_SIGNAL' ||
      signalBand === 'CLEAR'
    ) {
      return signalBand;
    }
    const index = RADIO_SIGNAL_BAND_ORDER.indexOf(
      signalBand,
    );
    return RADIO_SIGNAL_BAND_ORDER[
      Math.min(
        RADIO_SIGNAL_BAND_ORDER.length - 1,
        index + 1,
      )
    ] ?? signalBand;
  }

  private signalBearing(
    coverage: Readonly<RadioCoverageSnapshot> | undefined,
  ):
    | {
        degrees: number;
        uncertainty: number;
        rangeMetres: number;
      }
    | undefined {
    if (
      !this.receiverUpgradeProfile.directionFinderActive ||
      !coverage?.selectedSource
    ) {
      return undefined;
    }
    const receiver = globalPositionToAbsoluteMetres(
      this.networkRegistry.partition,
      coverage.receiverPosition,
    );
    const source = globalPositionToAbsoluteMetres(
      this.networkRegistry.partition,
      coverage.selectedSource.worldPosition,
    );
    const degrees =
      (
        Math.atan2(
          source.xMetres - receiver.xMetres,
          source.zMetres - receiver.zMetres,
        ) *
          180 /
          Math.PI +
        360
      ) % 360;
    const uncertainty = {
      CLEAR: 4,
      GOOD: 8,
      WEAK: 18,
      FRAGMENTED: 34,
      CARRIER_ONLY: 60,
      NO_SIGNAL: 180,
    }[coverage.signalBand];
    return {
      degrees,
      uncertainty,
      rangeMetres: coverage.selectedSource.distanceMetres,
    };
  }

  private knownFrequencyDefinitions():
    RegionalFrequencyDefinition[] {
    const known = new Set(
      this.networkState.discoveredFrequencyIds,
    );
    return this.networkRegistry.definitions.frequencies
      .filter((frequency) => known.has(frequency.id))
      .sort(
        (left, right) =>
          left.frequencyMhz - right.frequencyMhz ||
          left.id.localeCompare(right.id),
      );
  }

  private enqueueBroadcast(
    broadcast: LogicalRadioBroadcast,
  ): boolean {
    if (broadcast.supersessionKey) {
      const latest =
        this.latestBroadcastBySupersessionKey.get(
          broadcast.supersessionKey,
        );
      if (
        latest &&
        broadcast.occurredAt < latest.occurredAt
      ) {
        return false;
      }
      for (
        let index = this.pendingBroadcasts.length - 1;
        index >= 0;
        index -= 1
      ) {
        if (
          this.pendingBroadcasts[index]!
            .supersessionKey === broadcast.supersessionKey
        ) {
          this.pendingBroadcasts.splice(index, 1);
        }
      }
    } else {
      const duplicateIndex =
        this.pendingBroadcasts.findIndex(
          (candidate) =>
            candidate.dedupeKey === broadcast.dedupeKey,
        );
      if (duplicateIndex >= 0) {
        const duplicate =
          this.pendingBroadcasts[duplicateIndex]!;
        if (broadcast.occurredAt < duplicate.occurredAt) {
          return false;
        }
        this.pendingBroadcasts.splice(duplicateIndex, 1);
      }
    }

    this.pendingBroadcasts.push(cloneBroadcast(broadcast));
    this.rememberBroadcastSupersession(broadcast);
    this.trimPendingBroadcasts();
    const retained = this.pendingBroadcasts.some(
      (candidate) => candidate.id === broadcast.id,
    );
    if (retained) this.rememberLogicalBroadcast(broadcast);
    return retained;
  }

  private presentMessage(
    message: Readonly<RadioMessage>,
  ): RadioMessage {
    const cloned = cloneMessage(message);
    const signalBand =
      message.bestSignalBand ??
      message.receivedSignalBand;
    if (!signalBand) return cloned;
    const presentation = presentRadioSignal(
      message.title,
      message.body,
      message.targetRefs,
      signalBand,
    );
    return {
      ...cloned,
      title: presentation.title,
      body: presentation.body,
      signalDetail: presentation.signalDetail,
      presentedSignalBand: presentation.signalBand,
      ...(presentation.locationUncertaintyMetres !==
      undefined
        ? {
            locationUncertaintyMetres:
              presentation.locationUncertaintyMetres,
          }
        : {}),
    };
  }

  private improveReceivedMessages(
    snapshot: Readonly<RadioCoverageSnapshot>,
  ): void {
    const source = snapshot.selectedSource;
    if (!source || snapshot.signalBand === 'NO_SIGNAL') {
      return;
    }
    for (const message of this.messages) {
      if (
        message.stationId !== source.stationId ||
        message.frequencyId !== source.frequencyId
      ) {
        continue;
      }
      const previousBand =
        message.bestSignalBand ??
        message.receivedSignalBand ??
        'NO_SIGNAL';
      const previousRank =
        radioSignalBandRank(previousBand);
      const currentRank = radioSignalBandRank(
        snapshot.signalBand,
      );
      if (currentRank < previousRank) continue;
      if (
        currentRank === previousRank &&
        snapshot.signalStrength <=
          (message.bestSignalStrength ?? 0)
      ) {
        continue;
      }
      message.bestSignalBand = snapshot.signalBand;
      message.bestSignalStrength =
        snapshot.signalStrength;
    }
  }

  private deliverEligibleBroadcasts(
    receivedAt: number,
  ): {
    addedMessages: RadioMessage[];
    suppressedEventIds: string[];
  } {
    const addedMessages: RadioMessage[] = [];
    const suppressedEventIds: string[] = [];
    const ordered = [...this.pendingBroadcasts].sort(
      (left, right) =>
        right.priority - left.priority ||
        left.occurredAt - right.occurredAt ||
        left.id.localeCompare(right.id),
    );

    for (const broadcast of ordered) {
      if (
        addedMessages.length >=
        MAX_BROADCAST_DELIVERIES_PER_PROCESS
      ) {
        break;
      }
      if (
        !this.canReceiveBroadcast(broadcast, receivedAt)
      ) {
        continue;
      }

      this.removePendingBroadcast(broadcast.id);
      const previousReceivedAt = this.dedupeReceivedAt.get(
        broadcast.dedupeKey,
      );
      if (
        previousReceivedAt !== undefined &&
        receivedAt - previousReceivedAt <
          broadcast.cooldownSeconds
      ) {
        suppressedEventIds.push(
          broadcast.sourceEventId,
        );
        continue;
      }

      const candidate =
        this.candidateForBroadcast(broadcast);
      if (!candidate) {
        suppressedEventIds.push(
          broadcast.sourceEventId,
        );
        continue;
      }
      const tuning = this.getTuningSnapshot();
      const message: RadioMessage = {
        id: `radio:${broadcast.sourceEventId}`,
        sourceEventId: broadcast.sourceEventId,
        category: candidate.category,
        priority: candidate.priority,
        title: candidate.title,
        body: candidate.body,
        occurredAt: broadcast.occurredAt,
        receivedAt,
        dedupeKey: candidate.dedupeKey,
        targetRefs: broadcast.targetRefs.map(cloneTarget),
        urgent: candidate.priority >= URGENT_PRIORITY,
        stationId: broadcast.stationId,
        frequencyId: broadcast.frequencyId,
        receivedSignalBand: tuning.signalBand,
        bestSignalBand: tuning.signalBand,
        receivedSignalStrength: tuning.signalStrength,
        bestSignalStrength: tuning.signalStrength,
        ...(broadcast.context.musicTrackId
          ? {
              musicTrackId:
                broadcast.context.musicTrackId,
            }
          : {}),
        ...(this.voiceProfileForBroadcast(broadcast)
          ? {
              voiceProfileId:
                this.voiceProfileForBroadcast(broadcast),
            }
          : {}),
      };
      this.messages.push(message);
      if (!this.isNotificationMuted(message)) {
        this.pendingNotificationIds.add(message.id);
      }
      this.dedupeReceivedAt.set(
        candidate.dedupeKey,
        receivedAt,
      );
      addedMessages.push(this.presentMessage(message));
    }

    return { addedMessages, suppressedEventIds };
  }

  private canReceiveBroadcast(
    broadcast: Readonly<LogicalRadioBroadcast>,
    receivedAt: number,
  ): boolean {
    if (
      this.lastCoverageSimulationTime === undefined ||
      receivedAt - this.lastCoverageSimulationTime >
        RADIO_COVERAGE_MAXIMUM_STALE_SECONDS
    ) {
      return false;
    }
    const tuning = this.getTuningSnapshot();
    return (
      tuning.lockState === 'LOCKED' &&
      tuning.signalBand !== 'NO_SIGNAL' &&
      tuning.stationId === broadcast.stationId &&
      tuning.currentChannel === broadcast.channelType &&
      tuning.tunedFrequencyId === broadcast.frequencyId
    );
  }

  private candidateForBroadcast(
    broadcast: Readonly<LogicalRadioBroadcast>,
  ): RadioCandidate | undefined {
    const context = broadcast.context;
    switch (broadcast.copyKey) {
      case 'NPC_DISTRESS':
        if (!context.npcId || !context.incidentId) return undefined;
        if (context.incidentType === 'RESIDENT_SNOWBOUND') {
          return {
            category: broadcast.category,
            priority: broadcast.priority,
            title: `SOS from ${this.runtimeName(context.npcId)}`,
            body: 'A Borealis resident is trapped behind deep snow and has lost district heat. A careful doorstep response is requested.',
            dedupeKey: broadcast.dedupeKey,
            cooldownSeconds: broadcast.cooldownSeconds,
          };
        }
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title: `Distress call from ${this.runtimeName(context.npcId)}`,
          body: 'A traveller is stranded on a snow-blocked Borealis road and requests assistance.',
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      case 'NPC_INCIDENT_RESOLVED':
        if (!context.npcId || !context.incidentId) return undefined;
        if (context.incidentType === 'RESIDENT_SNOWBOUND') {
          return {
            category: broadcast.category,
            priority: broadcast.priority,
            title: `${this.runtimeName(context.npcId)} is safe and warm`,
            body: 'The doorway is clear and temporary heat has been installed.',
            dedupeKey: broadcast.dedupeKey,
            cooldownSeconds: broadcast.cooldownSeconds,
          };
        }
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title: `${this.runtimeName(context.npcId)} is moving again`,
          body: 'The Borealis road incident has been resolved.',
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      case 'ROUTE_CONDITION': {
        if (!context.routeId || !context.routeStatus) {
          return undefined;
        }
        const route = this.routeName(context.routeId);
        const copy = {
          OPEN: {
            title: `${route} is open`,
            body:
              'Navigation reports a stable open channel.',
          },
          NARROW: {
            title: `${route} is narrowing`,
            body:
              'Traffic should reduce speed and use caution.',
          },
          CRITICAL: {
            title: `${route} is critical`,
            body:
              'The navigable channel is close to closing.',
          },
          BLOCKED: {
            title: `${route} is blocked`,
            body:
              'Traffic cannot currently pass the route.',
          },
        } as const;
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          ...copy[context.routeStatus],
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      }
      case 'ROUTE_CAPACITY': {
        if (
          !context.routeId ||
          !context.previousWidthClass ||
          !context.widthClass
        ) {
          return undefined;
        }
        const route = this.routeName(context.routeId);
        const widened =
          ['SMALL', 'STANDARD', 'HEAVY'].indexOf(
            context.widthClass,
          ) >
          ['SMALL', 'STANDARD', 'HEAVY'].indexOf(
            context.previousWidthClass,
          );
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title: widened
            ? `${route} capacity improved`
            : `${route} capacity reduced`,
          body: widened
            ? `${context.widthClass.toLowerCase()} traffic is now cleared to use the route.`
            : `The route is now limited to ${context.widthClass.toLowerCase()} traffic.`,
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      }
      case 'SHIP_DEPARTED':
        if (
          !context.shipId ||
          !context.routeId ||
          !context.originPortId ||
          !context.destinationPortId
        ) {
          return undefined;
        }
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title: `${this.shipName(context.shipId)} departed`,
          body:
            `${this.portName(context.originPortId)} to ` +
            `${this.portName(context.destinationPortId)} via ` +
            `${this.routeName(context.routeId)}.`,
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      case 'SHIP_WAITING':
        if (!context.shipId || !context.routeId) {
          return undefined;
        }
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title: `${this.shipName(context.shipId)} is holding`,
          body:
            `The vessel is waiting on ${this.routeName(context.routeId)}.`,
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      case 'SHIP_STUCK':
        if (!context.shipId || !context.routeId) {
          return undefined;
        }
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title:
            `Distress call from ${this.shipName(context.shipId)}`,
          body:
            `The vessel is stuck on ${this.routeName(context.routeId)} ` +
            'and requests icebreaker assistance.',
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      case 'SHIP_RESUMED':
        if (!context.shipId || !context.routeId) {
          return undefined;
        }
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title:
            `${this.shipName(context.shipId)} is moving again`,
          body:
            `Traffic has resumed on ${this.routeName(context.routeId)}.`,
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      case 'ESCORT_STARTED':
        if (!context.shipId || !context.routeId) {
          return undefined;
        }
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title:
            `${this.shipName(context.shipId)} is following`,
          body:
            `Escort started on ${this.routeName(context.routeId)}. ` +
            'Maintain a steady lead through the channel.',
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      case 'ESCORT_PAUSED': {
        if (
          !context.shipId ||
          !context.routeId ||
          !context.escortPauseReason
        ) {
          return undefined;
        }
        const reasonCopy = {
          UNSAFE_ROUTE:
            'The channel is no longer safe for the cargo vessel.',
          PLAYER_TOO_FAR:
            'The icebreaker is too far ahead.',
          PLAYER_OFF_CORRIDOR:
            'The icebreaker has left the known route corridor.',
          WAITING_FOR_LEAD:
            'The vessel is waiting for the icebreaker to move ahead.',
        } as const;
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title:
            `${this.shipName(context.shipId)} has paused escort`,
          body:
            `${reasonCopy[context.escortPauseReason]} ` +
            'The vessel is holding position.',
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      }
      case 'ESCORT_RESUMED':
        if (!context.shipId || !context.routeId) {
          return undefined;
        }
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title:
            `${this.shipName(context.shipId)} is following again`,
          body:
            `Escort has resumed on ${this.routeName(context.routeId)}.`,
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      case 'INCIDENT_RESOLVED':
        if (!context.shipId || !context.routeId) {
          return undefined;
        }
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title:
            `${this.shipName(context.shipId)} is clear of the ice`,
          body:
            `The assistance incident on ${this.routeName(context.routeId)} ` +
            'is resolved and the vessel is moving again.',
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      case 'SHIP_ARRIVED':
        if (!context.shipId || !context.portId) {
          return undefined;
        }
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title:
            `${this.shipName(context.shipId)} has arrived`,
          body:
            `The vessel reached ${this.portName(context.portId)}.`,
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      case 'PORT_CARGO_DELIVERED': {
        if (
          !context.shipId ||
          !context.portId ||
          !context.goodType ||
          !Number.isFinite(context.amount)
        ) {
          return undefined;
        }
        const good =
          this.registry.getGood(context.goodType)
            ?.displayName ?? context.goodType;
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title: `Cargo at ${this.portName(context.portId)}`,
          body:
            `${this.shipName(context.shipId)} delivered ` +
            `${context.amount} ${good.toLowerCase()}.`,
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      }
      case 'WEATHER_REPORT': {
        if (!context.weatherKind) return undefined;
        const weatherName = context.weatherKind
          .replace('-', ' ')
          .toUpperCase();
        const highWind =
          (context.windMultiplier ?? 0) >= 1.25;
        const fastRefreeze =
          (context.refreezeMultiplier ?? 0) >= 1.12;
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title: `Coastal weather: ${weatherName}`,
          body:
            `${highWind ? 'Strong drift expected. ' : ''}` +
            `${fastRefreeze ? 'Broken channels may refreeze quickly.' : 'Normal channel refreeze expected.'}`,
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      }
      case 'LOCAL_PORT_NOTICE': {
        if (!context.portId || !context.noticeCode) {
          return undefined;
        }
        const copy = {
          SUPPLY_LOW:
            'Harbour stores are low. Incoming cargo has priority.',
          PORT_BUSY:
            'The harbour is busy. Keep the marked approach clear.',
          PORT_GROWING:
            'New harbour services are coming online.',
          OPERATIONS_NORMAL:
            'Harbour operations are running normally.',
        } as const;
        const notice =
          copy[
            context.noticeCode as keyof typeof copy
          ];
        if (!notice) return undefined;
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title: `${this.portName(context.portId)} local notice`,
          body: notice,
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      }
      case 'OPEN_BAND_TRAFFIC': {
        if (
          !context.shipId ||
          !context.routeId ||
          !context.navigationStatus
        ) {
          return undefined;
        }
        const statusCopy = {
          TRAVELLING_FAR: 'under way',
          WAITING_FOR_CHANNEL: 'holding for clear water',
          STUCK_ASSISTANCE: 'stopped in the ice',
          ARRIVING: 'approaching harbour',
        } as const;
        const status =
          statusCopy[
            context.navigationStatus as keyof typeof statusCopy
          ];
        if (!status) return undefined;
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title: `${this.shipName(context.shipId)} on open band`,
          body:
            `${this.shipName(context.shipId)} reports ${status} ` +
            `on ${this.routeName(context.routeId)}.`,
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      }
      case 'MYSTERY_BROADCAST': {
        if (
          context.mysteryBroadcastId !==
            'north-star-first-light' ||
          context.clueCode !== 'CURRENT_UNDER_ICE'
        ) {
          return undefined;
        }
        return {
          category: broadcast.category,
          priority: broadcast.priority,
          title: 'North Star After Dark',
          body:
            'A calm voice cuts through the static: ' +
            '"The current beside Ember is moving beneath the ice, ' +
            'not with the wind."',
          dedupeKey: broadcast.dedupeKey,
          cooldownSeconds: broadcast.cooldownSeconds,
        };
      }
    }
  }

  public exportState(): RadioSystemSaveData {
    return {
      version: 5,
      messages: this.messages.map(cloneMessage),
      dedupeEntries: [...this.dedupeReceivedAt].map(
        ([key, receivedAt]) => ({ key, receivedAt }),
      ),
      processedEventIds: [...this.processedEventOrder],
      mutedCategories: [...this.getMutedCategories()],
      network: {
        version: 2,
        ...cloneNetworkState(this.networkState),
      },
      pendingBroadcasts:
        this.pendingBroadcasts.map(cloneBroadcast),
      logicalBroadcasts:
        this.logicalBroadcasts.map(cloneBroadcast),
      broadcastSupersessionEntries: [
        ...this.latestBroadcastBySupersessionKey.values(),
      ].map((entry) => ({ ...entry })),
    };
  }

  private messageForEvent(
    event: Readonly<WorldDomainEvent>,
  ): RadioCandidate | undefined {
    switch (event.type) {
      case 'MISSION_OFFERED': {
        const mission = this.registry.getMission(
          event.missionId,
        );
        if (mission?.type === 'RESCUE_STUCK_SHIP') {
          return undefined;
        }
        const offerPorts =
          mission?.offerAtPortIds
            ?.map((portId) => this.portName(portId))
            .join(' or ') ?? 'a harbour office';
        return {
          category: 'TASK_OFFER',
          priority: 80,
          title:
            mission?.displayName ?? 'New harbour job',
          body: `A new job is available at ${offerPorts}.`,
          dedupeKey: `mission:${event.missionId}:offered`,
          cooldownSeconds: 0,
        };
      }
      case 'MISSION_EXPIRED': {
        const mission = this.registry.getMission(
          event.missionId,
        );
        return {
          category: 'TASK_OFFER',
          priority: 35,
          title: 'Job offer expired',
          body:
            `${mission?.displayName ?? event.missionId} is no longer available.`,
          dedupeKey: `mission:${event.missionId}:expired`,
          cooldownSeconds: 0,
        };
      }
      case 'MISSION_COMPLETED': {
        const mission = this.registry.getMission(
          event.missionId,
        );
        return {
          category: 'PORT_UPDATE',
          priority: 60,
          title:
            `${mission?.displayName ?? event.missionId} complete`,
          body:
            event.rewardMoney > 0
              ? `Harbour office confirms a reward of ${event.rewardMoney} credits.`
              : 'Harbour office confirms completion.',
          dedupeKey:
            `mission:${event.missionId}:completed`,
          cooldownSeconds: 0,
        };
      }
      case 'PORT_CLEARED':
        return {
          category: 'PORT_UPDATE',
          priority: 55,
          title: `${this.portName(event.portId)} is free`,
          body:
            'Harbour access is clear and will remain open.',
          dedupeKey: `port:${event.portId}:cleared`,
          cooldownSeconds: 0,
        };
      case 'BOTTLE_DISCOVERED':
        return {
          category: 'STORY',
          priority: 35,
          title: 'Message bottle recovered',
          body:
            `Recovered bottle ${event.discoveryOrder} has been added to the log.`,
          dedupeKey: `bottle:${event.bottleId}`,
          cooldownSeconds: 0,
        };
      case 'POI_DISCOVERED': {
        const poi = this.registry.getPoi(event.poiId);
        return {
          category: 'STORY',
          priority: 30,
          title: poi?.displayName ?? 'Landmark discovered',
          body:
            'The location has been added to the captain\'s log.',
          dedupeKey: `poi:${event.poiId}:discovered`,
          cooldownSeconds: 0,
        };
      }
      case 'WORLD_OUTCOME_CHANGED': {
        const towerRepair =
          V1_RADIO_TOWER_REPAIR_DEFINITIONS.find(
            (repair) =>
              repair.outcomeId === event.outcomeId,
          );
        if (towerRepair && event.state === 'ONLINE') {
          const frequency =
            this.networkRegistry.getFrequency(
              towerRepair.frequencyId,
            );
          return {
            category: 'PORT_UPDATE',
            priority: 62,
            title: `${towerRepair.displayName} restored`,
            body:
              frequency
                ? `Transmitter online at ${frequency.frequencyMhz.toFixed(3)} MHz.`
                : 'The transmitter is online.',
            dedupeKey:
              `outcome:${event.outcomeId}:${event.state}`,
            cooldownSeconds: 0,
          };
        }
        const lighthouseRestoration =
          V1_LIGHTHOUSE_RESTORATION_DEFINITIONS.find(
            (restoration) =>
              restoration.outcomeId === event.outcomeId,
          );
        if (
          lighthouseRestoration &&
          event.state === 'LIT'
        ) {
          return {
            category: 'PORT_UPDATE',
            priority: 60,
            title:
              `${lighthouseRestoration.displayName} restored`,
            body:
              'The Ember approaches chart now shows official routes, waiting points and marked shallows.',
            dedupeKey:
              `outcome:${event.outcomeId}:${event.state}`,
            cooldownSeconds: 0,
          };
        }
        return {
          category: 'STORY',
          priority: 35,
          title: 'World update',
          body:
            `${event.outcomeId} changed to ${event.state}.`,
          dedupeKey:
            `outcome:${event.outcomeId}:${event.state}`,
          cooldownSeconds: 0,
        };
      }
      case 'SHIP_RESCUED':
        if (event.routeId && event.incidentId) {
          return undefined;
        }
        return {
          category: 'TRAFFIC_UPDATE',
          priority: 65,
          title:
            `${this.shipName(event.shipId)} has been rescued`,
          body: 'The distress incident is resolved.',
          dedupeKey: `ship:${event.shipId}:rescued`,
          cooldownSeconds: 0,
        };
      case 'SHIP_ESCORTED':
        return {
          category: 'TRAFFIC_UPDATE',
          priority: 35,
          title:
            `${this.shipName(event.shipId)} escort complete`,
          body: 'The escorted vessel reached safe water.',
          dedupeKey: `ship:${event.shipId}:escorted`,
          cooldownSeconds: 0,
        };
      case 'ROUTE_OPENED':
      case 'ROUTE_SERVICED':
      case 'ROUTE_CONDITION_CHANGED':
      case 'SHIP_DEPARTED':
      case 'SHIP_WAITING':
      case 'SHIP_STUCK':
      case 'SHIP_RESUMED':
      case 'SHIP_ESCORT_STARTED':
      case 'SHIP_ESCORT_PAUSED':
      case 'SHIP_ESCORT_RESUMED':
      case 'SHIP_ARRIVED':
      case 'PORT_CARGO_DELIVERED':
      case 'MISSION_ACCEPTED':
      case 'MISSION_CANCELLED':
      case 'UPGRADE_PURCHASED':
      case 'SHIP_MODULES_REFITTED':
      case 'UPGRADE_PART_RECOVERED':
      case 'SPECIAL_COMPONENT_DELIVERED':
      case 'PORT_ACCESS_IMPROVED':
      case 'LAND_ROAD_CONDITION_CHANGED':
      case 'NPC_TRAVEL_STATE_CHANGED':
      case 'SERVICE_AVAILABILITY_CHANGED':
      case 'WORLD_INCIDENT_CHANGED':
      case 'STORY_QUEST_STATE_CHANGED':
        return undefined;
    }
  }

  private routeName(routeId: string): string {
    const route = this.registry.getRoute(routeId);
    if (!route) return routeId;
    const from =
      this.registry.getPort(route.fromPortId)?.shortName ??
      route.fromPortId;
    const to =
      this.registry.getPort(route.toPortId)?.shortName ??
      route.toPortId;
    return `${from}-${to} route`;
  }

  private portName(portId: string): string {
    return (
      this.registry.getPort(portId)?.shortName ?? portId
    );
  }

  private shipName(shipId: string): string {
    if (shipId.startsWith('mv-')) {
      const name = shipId
        .slice(3)
        .split('-')
        .filter(Boolean)
        .map(
          (part) =>
            `${part.charAt(0).toUpperCase()}${part.slice(1)}`,
        )
        .join(' ');
      return name ? `M/V ${name}` : shipId;
    }
    return shipId;
  }

  private runtimeName(id: string): string {
    return id
      .replace(/^npc-/, '')
      .split('-')
      .filter(Boolean)
      .map((part) => `${part.charAt(0).toUpperCase()}${part.slice(1)}`)
      .join(' ');
  }

  private rememberProcessedEvent(eventId: string): void {
    this.processedEventIds.add(eventId);
    this.processedEventOrder.push(eventId);
    this.trimProcessedEvents();
  }

  private isNotificationMuted(
    message: Pick<RadioMessage, 'category' | 'urgent'>,
  ): boolean {
    return (
      !message.urgent &&
      this.mutedCategories.has(message.category)
    );
  }

  private voiceProfileForBroadcast(
    broadcast: Readonly<LogicalRadioBroadcast>,
  ): string | undefined {
    const station = this.networkRegistry.getStation(
      broadcast.stationId,
    );
    if (station?.voiceProfileId) {
      return station.voiceProfileId;
    }
    return broadcast.context.shipId
      ? this.assignEntityVoiceProfile(
          broadcast.context.shipId,
        )
      : undefined;
  }

  private assignEntityVoiceProfile(
    entityId: string,
  ): string | undefined {
    const current =
      this.networkState.voiceAssignments.find(
        (assignment) =>
          assignment.entityId === entityId,
      );
    if (current) return current.voiceProfileId;
    const profiles =
      this.networkRegistry.definitions.voiceProfiles;
    if (profiles.length === 0) return undefined;
    let hash = 2166136261;
    for (const character of entityId) {
      hash ^= character.charCodeAt(0);
      hash = Math.imul(hash, 16777619);
    }
    const profile =
      profiles[Math.abs(hash) % profiles.length]!;
    this.networkState.voiceAssignments.push({
      entityId,
      voiceProfileId: profile.id,
    });
    this.networkState.voiceAssignments.sort(
      (left, right) =>
        left.entityId.localeCompare(right.entityId),
    );
    return profile.id;
  }

  private trimMessages(): void {
    if (this.messages.length <= MAX_MESSAGES) return;
    const removed = this.messages.splice(
      0,
      this.messages.length - MAX_MESSAGES,
    );
    for (const message of removed) {
      this.pendingNotificationIds.delete(message.id);
    }
  }

  private trimDedupeEntries(): void {
    if (
      this.dedupeReceivedAt.size <= MAX_DEDUPE_ENTRIES
    ) {
      return;
    }
    const entries = [...this.dedupeReceivedAt].sort(
      (left, right) => left[1] - right[1],
    );
    for (
      let index = 0;
      index < entries.length - MAX_DEDUPE_ENTRIES;
      index += 1
    ) {
      this.dedupeReceivedAt.delete(entries[index]![0]);
    }
  }

  private trimProcessedEvents(): void {
    while (
      this.processedEventOrder.length >
      MAX_PROCESSED_EVENT_IDS
    ) {
      const removed = this.processedEventOrder.shift();
      if (removed) this.processedEventIds.delete(removed);
    }
  }

  private expirePendingBroadcasts(
    simulationTime: number,
  ): string[] {
    const expiredIds = new Set<string>();
    for (
      let index = this.pendingBroadcasts.length - 1;
      index >= 0;
      index -= 1
    ) {
      const broadcast = this.pendingBroadcasts[index]!;
      if (broadcast.expiresAt > simulationTime) continue;
      expiredIds.add(broadcast.id);
      this.pendingBroadcasts.splice(index, 1);
    }
    for (
      let index = this.logicalBroadcasts.length - 1;
      index >= 0;
      index -= 1
    ) {
      const broadcast = this.logicalBroadcasts[index]!;
      if (broadcast.expiresAt > simulationTime) continue;
      expiredIds.add(broadcast.id);
      this.logicalBroadcasts.splice(index, 1);
    }
    return [...expiredIds].sort();
  }

  private removePendingBroadcast(
    broadcastId: string,
  ): void {
    const index = this.pendingBroadcasts.findIndex(
      (candidate) => candidate.id === broadcastId,
    );
    if (index >= 0) this.pendingBroadcasts.splice(index, 1);
  }

  private rememberBroadcastSupersession(
    broadcast: Readonly<LogicalRadioBroadcast>,
  ): void {
    if (!broadcast.supersessionKey) return;
    const current =
      this.latestBroadcastBySupersessionKey.get(
        broadcast.supersessionKey,
      );
    if (
      current &&
      current.occurredAt > broadcast.occurredAt
    ) {
      return;
    }
    this.latestBroadcastBySupersessionKey.delete(
      broadcast.supersessionKey,
    );
    this.latestBroadcastBySupersessionKey.set(
      broadcast.supersessionKey,
      {
        key: broadcast.supersessionKey,
        occurredAt: broadcast.occurredAt,
        sourceEventId: broadcast.sourceEventId,
      },
    );
    this.trimBroadcastSupersessionEntries();
  }

  private isBroadcastOlderThanLatest(
    broadcast: Readonly<LogicalRadioBroadcast>,
  ): boolean {
    if (!broadcast.supersessionKey) return false;
    const latest =
      this.latestBroadcastBySupersessionKey.get(
        broadcast.supersessionKey,
      );
    return (
      latest !== undefined &&
      (latest.occurredAt > broadcast.occurredAt ||
        (latest.occurredAt === broadcast.occurredAt &&
          latest.sourceEventId !==
            broadcast.sourceEventId))
    );
  }

  private trimPendingBroadcasts(): void {
    if (
      this.pendingBroadcasts.length <=
      MAX_PENDING_RADIO_BROADCASTS
    ) {
      return;
    }
    this.pendingBroadcasts.sort(
      (left, right) =>
        right.priority - left.priority ||
        right.occurredAt - left.occurredAt ||
        left.id.localeCompare(right.id),
    );
    this.pendingBroadcasts.splice(
      MAX_PENDING_RADIO_BROADCASTS,
    );
  }

  private rememberLogicalBroadcast(
    broadcast: Readonly<LogicalRadioBroadcast>,
  ): void {
    for (
      let index = this.logicalBroadcasts.length - 1;
      index >= 0;
      index -= 1
    ) {
      const candidate = this.logicalBroadcasts[index]!;
      const superseded = broadcast.supersessionKey
        ? candidate.supersessionKey === broadcast.supersessionKey
        : candidate.dedupeKey === broadcast.dedupeKey;
      if (superseded) this.logicalBroadcasts.splice(index, 1);
    }
    this.logicalBroadcasts.push(cloneBroadcast(broadcast));
    this.trimLogicalBroadcasts();
  }

  private trimLogicalBroadcasts(): void {
    if (
      this.logicalBroadcasts.length <=
      MAX_PENDING_RADIO_BROADCASTS
    ) return;
    this.logicalBroadcasts.sort(
      (left, right) =>
        right.priority - left.priority ||
        right.occurredAt - left.occurredAt ||
        left.id.localeCompare(right.id),
    );
    this.logicalBroadcasts.splice(
      MAX_PENDING_RADIO_BROADCASTS,
    );
  }

  private trimBroadcastSupersessionEntries(): void {
    while (
      this.latestBroadcastBySupersessionKey.size >
      MAX_BROADCAST_SUPERSESSION_ENTRIES
    ) {
      const oldestKey =
        this.latestBroadcastBySupersessionKey.keys().next()
          .value;
      if (typeof oldestKey !== 'string') break;
      this.latestBroadcastBySupersessionKey.delete(oldestKey);
    }
  }
}
