import {
  cloneGlobalPosition,
  globalPositionDistanceMetres,
  isGlobalPositionInPartition,
  type GlobalPosition,
} from '../../world/GlobalPosition';
import type {
  RadioChannelType,
  RadioSignalBand,
  RadioTowerRuntimeState,
  RadioTowerState,
} from './RadioNetworkTypes';
import { RadioNetworkRegistry } from './RadioNetworkRegistry';
import {
  RADIO_MAXIMUM_RANGE_MULTIPLIER,
  RadioSpatialIndex,
  type RadioIndexedTransmitter,
  type RadioSpatialIndexStats,
} from './RadioSpatialIndex';

export const RADIO_COVERAGE_MINIMUM_QUERY_INTERVAL_SECONDS = 2;
export const RADIO_COVERAGE_MAXIMUM_STALE_SECONDS = 10;
export const RADIO_COVERAGE_MOVEMENT_THRESHOLD_METRES = 8;
export const RADIO_HANDOFF_STRENGTH_MARGIN = 0.08;
export const RADIO_HANDOFF_HOLD_SECONDS = 4;

export interface RadioCoverageQueryInput {
  receiverPosition: GlobalPosition;
  simulationTime: number;
  channelType: RadioChannelType;
  frequencyId?: string;
  frequencyIds?: readonly string[];
  towerStates: readonly RadioTowerRuntimeState[];
  receiverRangeMultiplier?: number;
  receiverStrengthMultiplier?: number;
  force?: boolean;
}

export interface RadioSignalSource {
  transmitterId: string;
  stationId: string;
  regionId: string;
  frequencyId: string;
  channelType: RadioChannelType;
  worldPosition: GlobalPosition;
  distanceMetres: number;
  strength: number;
  band: RadioSignalBand;
  towerId?: string;
  towerState?: RadioTowerState;
}

export interface RadioCoverageSnapshot {
  sampledAt: number;
  fromCache: boolean;
  receiverPosition: GlobalPosition;
  channelType: RadioChannelType;
  frequencyId?: string;
  signalBand: RadioSignalBand;
  signalStrength: number;
  candidateTransmitters: number;
  eligibleTransmitters: number;
  strongestSource?: RadioSignalSource;
  selectedSource?: RadioSignalSource;
  pendingHandoffTransmitterId?: string;
}

export interface RadioCoverageStats
  extends RadioSpatialIndexStats {
  activeTransmitters: number;
  totalCoverageQueries: number;
  coverageQueriesPerSecond: number;
  cacheHits: number;
  totalCandidatesEvaluated: number;
  lastCandidateCount: number;
  maximumCandidateCount: number;
  lastQueryMs: number;
  totalQueryMs: number;
  handoffs: number;
}

interface TowerCoverageFactor {
  strengthMultiplier: number;
  rangeMultiplier: number;
}

const TOWER_COVERAGE_FACTORS: Record<
  RadioTowerState,
  TowerCoverageFactor
> = {
  OFFLINE: {
    strengthMultiplier: 0,
    rangeMultiplier: 0,
  },
  DAMAGED: {
    strengthMultiplier: 0.35,
    rangeMultiplier: 0.72,
  },
  WEAK: {
    strengthMultiplier: 0.58,
    rangeMultiplier: 0.82,
  },
  ONLINE: {
    strengthMultiplier: 1,
    rangeMultiplier: 1,
  },
  UPGRADED: {
    strengthMultiplier: 1.08,
    rangeMultiplier: RADIO_MAXIMUM_RANGE_MULTIPLIER,
  },
};

export const radioSignalBandForStrength = (
  strength: number,
): RadioSignalBand => {
  if (strength >= 0.82) return 'CLEAR';
  if (strength >= 0.62) return 'GOOD';
  if (strength >= 0.4) return 'WEAK';
  if (strength >= 0.16) return 'FRAGMENTED';
  if (strength > 0) return 'CARRIER_ONLY';
  return 'NO_SIGNAL';
};

const interpolateFalloff = (
  from: number,
  to: number,
  progress: number,
  exponent: number,
): number =>
  from +
  (to - from) *
    Math.pow(Math.max(0, Math.min(1, progress)), exponent);

const distanceSignalStrength = (
  distanceMetres: number,
  clearRadiusMetres: number,
  usableRadiusMetres: number,
  maximumRadiusMetres: number,
  falloffExponent: number,
): number => {
  if (
    maximumRadiusMetres <= 0 ||
    distanceMetres > maximumRadiusMetres
  ) {
    return 0;
  }
  if (distanceMetres <= clearRadiusMetres) {
    if (clearRadiusMetres <= 0) return 0.86;
    return interpolateFalloff(
      1,
      0.86,
      distanceMetres / clearRadiusMetres,
      falloffExponent,
    );
  }
  if (distanceMetres <= usableRadiusMetres) {
    const width =
      usableRadiusMetres - clearRadiusMetres;
    return interpolateFalloff(
      0.86,
      0.44,
      width > 0
        ? (distanceMetres - clearRadiusMetres) / width
        : 1,
      falloffExponent,
    );
  }
  const width =
    maximumRadiusMetres - usableRadiusMetres;
  return interpolateFalloff(
    0.44,
    0.02,
    width > 0
      ? (distanceMetres - usableRadiusMetres) / width
      : 1,
    falloffExponent,
  );
};

const cloneSignalSource = (
  source: Readonly<RadioSignalSource>,
): RadioSignalSource => ({
  ...source,
  worldPosition: cloneGlobalPosition(source.worldPosition),
});

const cloneSnapshot = (
  snapshot: Readonly<RadioCoverageSnapshot>,
  fromCache = snapshot.fromCache,
): RadioCoverageSnapshot => ({
  ...snapshot,
  fromCache,
  receiverPosition: cloneGlobalPosition(
    snapshot.receiverPosition,
  ),
  ...(snapshot.strongestSource
    ? {
        strongestSource: cloneSignalSource(
          snapshot.strongestSource,
        ),
      }
    : {}),
  ...(snapshot.selectedSource
    ? {
        selectedSource: cloneSignalSource(
          snapshot.selectedSource,
        ),
      }
    : {}),
});

const towerStateSignature = (
  towerStates: readonly RadioTowerRuntimeState[],
): string =>
  [...towerStates]
    .sort((left, right) =>
      left.towerId.localeCompare(right.towerId),
    )
    .map((value) => `${value.towerId}:${value.state}`)
    .join('|');

const channelKey = (
  channelType: RadioChannelType,
  frequencyId: string | undefined,
  frequencyIds: readonly string[] | undefined,
): string =>
  `${channelType}:${
    frequencyId ??
    (frequencyIds
      ? [...frequencyIds].sort().join(',')
      : '*')
  }`;

const signalOrder = (
  left: Readonly<RadioSignalSource>,
  right: Readonly<RadioSignalSource>,
): number =>
  right.strength - left.strength ||
  left.distanceMetres - right.distanceMetres ||
  left.transmitterId.localeCompare(right.transmitterId);

export class RadioCoverageSystem {
  private readonly registry: RadioNetworkRegistry;
  private readonly index: RadioSpatialIndex;
  private lastSnapshot?: RadioCoverageSnapshot;
  private lastReceiverPosition?: GlobalPosition;
  private lastSampledAt = Number.NEGATIVE_INFINITY;
  private lastTowerStateSignature = '';
  private lastChannelKey = '';
  private selectedSource?: RadioSignalSource;
  private pendingHandoffTransmitterId?: string;
  private pendingHandoffSince = 0;
  private queryTimes: number[] = [];
  private activeTransmitters = 0;
  private totalCoverageQueries = 0;
  private cacheHits = 0;
  private totalCandidatesEvaluated = 0;
  private lastCandidateCount = 0;
  private maximumCandidateCount = 0;
  private lastQueryMs = 0;
  private totalQueryMs = 0;
  private handoffs = 0;

  public constructor(
    registry: RadioNetworkRegistry,
    index = new RadioSpatialIndex(registry),
  ) {
    this.registry = registry;
    this.index = index;
    this.refreshActiveTransmitterCount([]);
  }

  public update(
    input: Readonly<RadioCoverageQueryInput>,
  ): RadioCoverageSnapshot {
    const simulationTime = Math.max(
      0,
      input.simulationTime,
    );
    const nextTowerSignature = towerStateSignature(
      input.towerStates,
    );
    const nextChannelKey = channelKey(
      input.channelType,
      input.frequencyId,
      input.frequencyIds,
    );
    const elapsed = simulationTime - this.lastSampledAt;
    const channelChanged =
      nextChannelKey !== this.lastChannelKey;
    const towerStateChanged =
      nextTowerSignature !==
      this.lastTowerStateSignature;
    const moved = this.lastReceiverPosition
      ? globalPositionDistanceMetres(
          this.registry.partition,
          this.lastReceiverPosition,
          input.receiverPosition,
        )
      : Number.POSITIVE_INFINITY;
    const pendingHandoffDue =
      this.pendingHandoffTransmitterId !== undefined &&
      elapsed >=
        RADIO_COVERAGE_MINIMUM_QUERY_INTERVAL_SECONDS;
    const minimumIntervalElapsed =
      elapsed >=
      RADIO_COVERAGE_MINIMUM_QUERY_INTERVAL_SECONDS;
    const meaningfulMovement =
      moved >= RADIO_COVERAGE_MOVEMENT_THRESHOLD_METRES;
    const stale =
      elapsed >= RADIO_COVERAGE_MAXIMUM_STALE_SECONDS;
    const mustSample =
      input.force === true ||
      !this.lastSnapshot ||
      elapsed < 0 ||
      channelChanged ||
      towerStateChanged ||
      (minimumIntervalElapsed &&
        (meaningfulMovement ||
          stale ||
          pendingHandoffDue));

    if (!mustSample && this.lastSnapshot) {
      this.cacheHits += 1;
      return cloneSnapshot(this.lastSnapshot, true);
    }

    if (towerStateChanged) {
      this.refreshActiveTransmitterCount(
        input.towerStates,
      );
    }
    if (channelChanged) {
      this.selectedSource = undefined;
      this.pendingHandoffTransmitterId = undefined;
      this.pendingHandoffSince = simulationTime;
    }

    const startedAt = performance.now();
    const result = this.evaluateSources(input);
    this.applyHandoff(
      result.sources,
      simulationTime,
    );
    this.lastQueryMs = performance.now() - startedAt;
    this.totalQueryMs += this.lastQueryMs;
    this.totalCoverageQueries += 1;
    this.totalCandidatesEvaluated +=
      result.candidateTransmitters;
    this.lastCandidateCount =
      result.candidateTransmitters;
    this.maximumCandidateCount = Math.max(
      this.maximumCandidateCount,
      result.candidateTransmitters,
    );
    this.queryTimes.push(simulationTime);
    this.queryTimes = this.queryTimes.filter(
      (time) => time >= simulationTime - 10,
    );

    const strongestSource = result.sources[0];
    const selectedSource = this.selectedSource;
    const sampledFrequencyId =
      selectedSource?.frequencyId ?? input.frequencyId;
    this.lastSnapshot = {
      sampledAt: simulationTime,
      fromCache: false,
      receiverPosition: cloneGlobalPosition(
        input.receiverPosition,
      ),
      channelType: input.channelType,
      ...(sampledFrequencyId
        ? { frequencyId: sampledFrequencyId }
        : {}),
      signalBand:
        selectedSource?.band ?? 'NO_SIGNAL',
      signalStrength: selectedSource?.strength ?? 0,
      candidateTransmitters:
        result.candidateTransmitters,
      eligibleTransmitters: result.sources.length,
      ...(strongestSource
        ? {
            strongestSource:
              cloneSignalSource(strongestSource),
          }
        : {}),
      ...(selectedSource
        ? {
            selectedSource:
              cloneSignalSource(selectedSource),
          }
        : {}),
      ...(this.pendingHandoffTransmitterId
        ? {
            pendingHandoffTransmitterId:
              this.pendingHandoffTransmitterId,
          }
        : {}),
    };
    this.lastReceiverPosition = cloneGlobalPosition(
      input.receiverPosition,
    );
    this.lastSampledAt = simulationTime;
    this.lastTowerStateSignature = nextTowerSignature;
    this.lastChannelKey = nextChannelKey;
    return cloneSnapshot(this.lastSnapshot);
  }

  public getSnapshot():
    | RadioCoverageSnapshot
    | undefined {
    return this.lastSnapshot
      ? cloneSnapshot(this.lastSnapshot)
      : undefined;
  }

  public getStats(): RadioCoverageStats {
    const indexStats = this.index.getStats();
    const firstQueryAt = this.queryTimes[0];
    const lastQueryAt =
      this.queryTimes[this.queryTimes.length - 1];
    const queryWindow =
      firstQueryAt !== undefined &&
      lastQueryAt !== undefined
        ? Math.max(
            1,
            Math.min(
              10,
              lastQueryAt -
                firstQueryAt +
                RADIO_COVERAGE_MINIMUM_QUERY_INTERVAL_SECONDS,
            ),
          )
        : 1;
    return {
      ...indexStats,
      activeTransmitters: this.activeTransmitters,
      totalCoverageQueries: this.totalCoverageQueries,
      coverageQueriesPerSecond:
        this.queryTimes.length / queryWindow,
      cacheHits: this.cacheHits,
      totalCandidatesEvaluated:
        this.totalCandidatesEvaluated,
      lastCandidateCount: this.lastCandidateCount,
      maximumCandidateCount:
        this.maximumCandidateCount,
      lastQueryMs: this.lastQueryMs,
      totalQueryMs: this.totalQueryMs,
      handoffs: this.handoffs,
    };
  }

  public invalidate(): void {
    this.lastSampledAt = Number.NEGATIVE_INFINITY;
  }

  private evaluateSources(
    input: Readonly<RadioCoverageQueryInput>,
  ): {
    candidateTransmitters: number;
    sources: RadioSignalSource[];
  } {
    if (
      !isGlobalPositionInPartition(
        this.registry.partition,
        input.receiverPosition,
      )
    ) {
      return {
        candidateTransmitters: 0,
        sources: [],
      };
    }
    const candidates = this.index.getCandidates(
      input.receiverPosition,
    );
    const towerStates = new Map(
      input.towerStates.map((value) => [
        value.towerId,
        value.state,
      ]),
    );
    const sources = candidates.flatMap((candidate) => {
      const source = this.evaluateSource(
        candidate,
        input,
        towerStates,
      );
      return source ? [source] : [];
    });
    sources.sort(signalOrder);
    return {
      candidateTransmitters: candidates.length,
      sources,
    };
  }

  private evaluateSource(
    candidate: Readonly<RadioIndexedTransmitter>,
    input: Readonly<RadioCoverageQueryInput>,
    towerStates: ReadonlyMap<string, RadioTowerState>,
  ): RadioSignalSource | undefined {
    if (!candidate.enabledByDefault) return undefined;
    const frequency = this.registry.getFrequency(
      candidate.frequencyId,
    )!;
    if (frequency.channelType !== input.channelType) {
      return undefined;
    }
    if (
      input.frequencyId !== undefined &&
      candidate.frequencyId !== input.frequencyId
    ) {
      return undefined;
    }
    if (
      input.frequencyIds !== undefined &&
      !input.frequencyIds.includes(candidate.frequencyId)
    ) {
      return undefined;
    }

    const profile = this.registry.getCoverageProfile(
      candidate.coverageProfileId,
    )!;
    const tower = candidate.towerId
      ? this.registry.getTower(candidate.towerId)
      : undefined;
    const towerState = tower
      ? towerStates.get(tower.id) ?? tower.initialState
      : undefined;
    const factor = towerState
      ? TOWER_COVERAGE_FACTORS[towerState]
      : TOWER_COVERAGE_FACTORS.ONLINE;
    if (factor.rangeMultiplier <= 0) return undefined;
    const receiverRangeMultiplier = Math.max(
      1,
      Math.min(
        RADIO_MAXIMUM_RANGE_MULTIPLIER,
        input.receiverRangeMultiplier ?? 1,
      ),
    );
    const receiverStrengthMultiplier = Math.max(
      1,
      Math.min(
        RADIO_MAXIMUM_RANGE_MULTIPLIER,
        input.receiverStrengthMultiplier ?? 1,
      ),
    );

    const distanceMetres = globalPositionDistanceMetres(
      this.registry.partition,
      input.receiverPosition,
      candidate.worldPosition,
    );
    const strength = Math.max(
      0,
      Math.min(
        1,
        distanceSignalStrength(
          distanceMetres,
          profile.clearRadiusMetres *
            factor.rangeMultiplier *
            receiverRangeMultiplier,
          profile.usableRadiusMetres *
            factor.rangeMultiplier *
            receiverRangeMultiplier,
          profile.maximumRadiusMetres *
            factor.rangeMultiplier *
            receiverRangeMultiplier,
          profile.falloffExponent,
        ) *
          factor.strengthMultiplier *
          receiverStrengthMultiplier,
      ),
    );
    if (strength <= 0) return undefined;

    return {
      transmitterId: candidate.transmitterId,
      stationId: candidate.stationId,
      regionId: candidate.regionId,
      frequencyId: candidate.frequencyId,
      channelType: frequency.channelType,
      worldPosition: cloneGlobalPosition(
        candidate.worldPosition,
      ),
      distanceMetres,
      strength,
      band: radioSignalBandForStrength(strength),
      ...(candidate.towerId
        ? { towerId: candidate.towerId }
        : {}),
      ...(towerState ? { towerState } : {}),
    };
  }

  private applyHandoff(
    sources: readonly RadioSignalSource[],
    simulationTime: number,
  ): void {
    const strongest = sources[0];
    if (!strongest) {
      this.selectedSource = undefined;
      this.pendingHandoffTransmitterId = undefined;
      return;
    }

    if (!this.selectedSource) {
      this.selectedSource = cloneSignalSource(strongest);
      this.pendingHandoffTransmitterId = undefined;
      return;
    }

    const current = sources.find(
      (source) =>
        source.transmitterId ===
        this.selectedSource?.transmitterId,
    );
    if (!current) {
      this.selectedSource = cloneSignalSource(strongest);
      this.pendingHandoffTransmitterId = undefined;
      this.handoffs += 1;
      return;
    }
    if (
      strongest.transmitterId === current.transmitterId
    ) {
      this.selectedSource = cloneSignalSource(current);
      this.pendingHandoffTransmitterId = undefined;
      return;
    }

    if (
      strongest.strength <
      current.strength + RADIO_HANDOFF_STRENGTH_MARGIN
    ) {
      this.selectedSource = cloneSignalSource(current);
      this.pendingHandoffTransmitterId = undefined;
      return;
    }

    if (
      this.pendingHandoffTransmitterId !==
      strongest.transmitterId
    ) {
      this.pendingHandoffTransmitterId =
        strongest.transmitterId;
      this.pendingHandoffSince = simulationTime;
      this.selectedSource = cloneSignalSource(current);
      return;
    }
    if (
      simulationTime - this.pendingHandoffSince <
      RADIO_HANDOFF_HOLD_SECONDS
    ) {
      this.selectedSource = cloneSignalSource(current);
      return;
    }

    this.selectedSource = cloneSignalSource(strongest);
    this.pendingHandoffTransmitterId = undefined;
    this.handoffs += 1;
  }

  private refreshActiveTransmitterCount(
    towerStates: readonly RadioTowerRuntimeState[],
  ): void {
    const states = new Map(
      towerStates.map((value) => [
        value.towerId,
        value.state,
      ]),
    );
    this.activeTransmitters =
      this.registry.definitions.transmitters.filter(
        (transmitter) => {
          if (!transmitter.enabledByDefault) return false;
          if (transmitter.source.kind !== 'TOWER') {
            return true;
          }
          const tower = this.registry.getTower(
            transmitter.source.towerId,
          )!;
          return (
            (states.get(tower.id) ??
              tower.initialState) !== 'OFFLINE'
          );
        },
      ).length;
  }
}
