import type { GlobalPosition } from '../../world/GlobalPosition';
import { prototypeLocalToGlobalPosition } from '../../world/PrototypeWorldPositionAdapter';

export type PortableItemTag =
  | 'PORTABLE'
  | 'TOOL'
  | 'CONSUMABLE'
  | 'RADIO'
  | 'INFRASTRUCTURE_COMPONENT'
  | 'CONSTRUCTION_RESOURCE';

export interface PortableItemDefinition {
  readonly definitionId: string;
  readonly displayName: string;
  readonly tags: readonly PortableItemTag[];
  readonly consumable: boolean;
  readonly maximumStackSize: 1;
  readonly radioUpgradeId?: string;
}

export interface PortableInventorySlotDefinition {
  readonly slotId: string;
  readonly acceptedTags?: readonly PortableItemTag[];
}

export interface PortableWorldContainerDefinition {
  readonly containerId: string;
  readonly worldPosition: GlobalPosition;
  readonly slots: readonly PortableInventorySlotDefinition[];
}

