export const V1_PORTABLE_ITEM_DEFINITIONS: ReadonlyMap<
  string,
  Readonly<PortableItemDefinition>
> = new Map(itemDefinitions.map((definition) => [
  definition.definitionId,
  Object.freeze({ ...definition, tags: Object.freeze([...definition.tags]) }),
]));

