const storageSlots = Array.from({ length: 12 }, (_, index) => ({
  slotId: `storage-${index + 1}`,
})) satisfies PortableInventorySlotDefinition[];

export const BOREALIS_EQUIPMENT_LOCKER_ID = 'borealis-equipment-locker';

export const V1_PORTABLE_WORLD_CONTAINERS = Object.freeze([
  {
    containerId: BOREALIS_EQUIPMENT_LOCKER_ID,
    worldPosition: prototypeLocalToGlobalPosition({ x: -38.5, y: 0, z: 23.5 }),
    slots: Object.freeze(storageSlots),
  },
] as const satisfies readonly PortableWorldContainerDefinition[]);

export const portableItemDefinition = (
  definitionId: string,
): Readonly<PortableItemDefinition> | undefined =>
  V1_PORTABLE_ITEM_DEFINITIONS.get(definitionId);

export const itemFitsPortableSlot = (
  definition: Readonly<PortableItemDefinition>,
  slot: Readonly<PortableInventorySlotDefinition>,
): boolean =>
  !slot.acceptedTags ||
  slot.acceptedTags.some((tag) => definition.tags.includes(tag));
