import { clamp } from '../../utils/math';
import type { GameplayRegistry } from '../definitions/GameplayRegistry';
import type {
  GoodType,
  RouteDefinition,
  RouteState,
  ShipClass,
  Vec3Like,
} from '../definitions/GameplayTypes';
import type {
  ShipEscortPauseReason,
  WorldDomainEvent,
} from '../events/WorldDomainEvent';
