import {
  BoxGeometry,
  Color,
  CylinderGeometry,
  DynamicDrawUsage,
  Group,
  InstancedMesh,
  MeshStandardMaterial,
  Object3D,
  SphereGeometry,
  type Scene,
} from 'three';
import type { TerrainHeightSystem } from '../land/TerrainHeightSystem';
import type { LandSnowSystem } from '../land/LandSnowSystem';
import {
  initialLandSnowDepth,
  visualLandSnowHeight,
} from '../land/LandSnowData';
import { clamp, hash2D } from '../utils/math';
import {
  SNOW_EMERGENCY_CITY_LAYOUT,
  snowEmergencyRoadAt,
  snowEmergencySidewalkAt,
  type SnowEmergencyCityLayout,
  type SnowEmergencyPlowClass,
  type SnowEmergencyRoadClass,
} from './SnowEmergencyCityLayout';
import {
  SnowEmergencyTrafficSimulation,
  type SnowEmergencyTrafficStats,
  type SnowEmergencyVehicleType,
} from './SnowEmergencyTrafficSimulation';

export interface SnowEmergencyCityStats extends SnowEmergencyTrafficStats {
  readonly active: boolean;
  readonly visibleVehicles: number;
  readonly passableRoadSegments: number;
  readonly totalRoadSegments: number;
  readonly passablePrioritySegments: number;
  readonly totalPrioritySegments: number;
  readonly plowedDistanceMetres: number;
  readonly movedSnow: number;
  readonly maximumBankHeight: number;
}

const MAX_VISIBLE_TRAFFIC = 176;
const ROAD_MATERIAL_COLORS: Readonly<Record<SnowEmergencyRoadClass, number>> = {
  BOULEVARD: 0x202a31,
  AVENUE: 0x273137,
  LOCAL: 0x2d3438,
};

const VEHICLE_COLORS: Readonly<Record<SnowEmergencyVehicleType, number>> = {
  CAR: 0x65a9b3,
  BICYCLE: 0xe4bd4e,
  SNOWMOBILE: 0x4e5961,
  BUS: 0xe2a83b,
  TRUCK: 0x65727b,
  AMBULANCE: 0xf3f4ef,
  GARBAGE_TRUCK: 0x66855e,
};

const VEHICLE_DIMENSIONS: Readonly<
  Record<SnowEmergencyVehicleType, readonly [number, number, number]>
> = {
  CAR: [1.75, 1.25, 3.8],
  BICYCLE: [0.55, 1, 1.55],
  SNOWMOBILE: [1.05, 0.86, 2.25],
  BUS: [2.45, 2.95, 9.6],
  TRUCK: [2.45, 3.15, 8.4],
  AMBULANCE: [2.15, 2.25, 5.4],
  GARBAGE_TRUCK: [2.4, 3, 7.2],
};

const VEHICLE_PRESENTATION_SCALE: Readonly<
  Record<SnowEmergencyVehicleType, number>
> = {
  CAR: 0.68,
  BICYCLE: 0.62,
  SNOWMOBILE: 0.68,
  BUS: 0.78,
  TRUCK: 0.76,
  AMBULANCE: 0.72,
  GARBAGE_TRUCK: 0.76,
};

interface RoadSnowCoverPatch {
  readonly x: number;
  readonly z: number;
  readonly y: number;
  readonly width: number;
  readonly depth: number;
}

const createMaterial = (
  color: number,
  roughness = 0.82,
  emissive = 0,
): MeshStandardMaterial => new MeshStandardMaterial({
  color,
  roughness,
  metalness: 0.04,
  emissive,
  emissiveIntensity: emissive ? 0.75 : 0,
});

export class SnowEmergencyCitySystem {
  private readonly root = new Group();
  private readonly transform = new Object3D();
  private readonly color = new Color();
  private readonly materials: MeshStandardMaterial[] = [];
  private readonly traffic: SnowEmergencyTrafficSimulation;
  private readonly trafficBodies: InstancedMesh;
  private readonly trafficCabins: InstancedMesh;
  private buildingMesh!: InstancedMesh;
  private buildingRoofCaps!: InstancedMesh;
  private buildingWindowBands!: InstancedMesh;
  private roadSnowCover!: InstancedMesh;
  private readonly roadSnowCoverPatches: RoadSnowCoverPatch[] = [];
  private signalBulbs!: InstancedMesh;
  private readonly signalApproaches: Array<Readonly<{
    intersectionId: string;
    axis: 'X' | 'Z';
    x: number;
    z: number;
    heading: number;
  }>> = [];
  private active = false;
  private trafficAccumulator = 0;
  private roadObservationAccumulator = 0;
  private signalAccumulator = 0;
  private presentationAccumulator = 0;
  private visibleVehicles = 0;
  private passableRoadSegments = 0;
  private passablePrioritySegments = 0;
  private plowedDistanceMetres = 0;
  private movedSnow = 0;
  private maximumBankHeight = 0;

  public constructor(
    scene: Scene,
    private readonly terrain: TerrainHeightSystem,
    public readonly layout: Readonly<SnowEmergencyCityLayout> =
      SNOW_EMERGENCY_CITY_LAYOUT,
  ) {
    this.root.name = 'Northbridge snow emergency city';
    this.root.visible = false;
    scene.add(this.root);
    this.traffic = new SnowEmergencyTrafficSimulation(layout, 360);
    this.createRoadPresentation();
    this.createBuildingPresentation();
    this.createSignalPresentation();

    const vehicleMaterial = createMaterial(0xffffff, 0.62);
    const cabinMaterial = createMaterial(0x9fc8d2, 0.42, 0x152329);
    this.materials.push(vehicleMaterial, cabinMaterial);
    this.trafficBodies = new InstancedMesh(
      new BoxGeometry(1, 1, 1),
      vehicleMaterial,
      MAX_VISIBLE_TRAFFIC,
    );
    this.trafficCabins = new InstancedMesh(
      new BoxGeometry(1, 1, 1),
      cabinMaterial,
      MAX_VISIBLE_TRAFFIC,
    );
    this.trafficBodies.name = 'Snow city pooled traffic bodies';
    this.trafficCabins.name = 'Snow city pooled traffic cabins';
    this.trafficBodies.instanceMatrix.setUsage(DynamicDrawUsage);
    this.trafficCabins.instanceMatrix.setUsage(DynamicDrawUsage);
    this.trafficBodies.castShadow = true;
    this.trafficBodies.receiveShadow = true;
    this.trafficCabins.castShadow = false;
    this.trafficBodies.count = 0;
    this.trafficCabins.count = 0;
    this.root.add(this.trafficBodies, this.trafficCabins);
  }

  public setActive(active: boolean): void {
    this.active = active;
    this.root.visible = active;
  }

  public isActive(): boolean {
    return this.active;
  }

  public isInside(x: number, z: number, padding = 0): boolean {
    return x >= this.layout.bounds.minX - padding &&
      x <= this.layout.bounds.maxX + padding &&
      z >= this.layout.bounds.minZ - padding &&
      z <= this.layout.bounds.maxZ + padding;
  }

  public canDriveAt(x: number, z: number, radius = 0.9): boolean {
    if (!this.isInside(x, z, 4)) return true;
    const clearOfBuildings = this.layout.buildings.every((building) =>
      Math.abs(x - building.x) > building.width * 0.5 + radius ||
      Math.abs(z - building.z) > building.depth * 0.5 + radius
    );
    if (!clearOfBuildings || !this.active) return clearOfBuildings;
    const inMunicipalStagingBay =
      Math.abs(x - this.layout.spawn.x) < 5 &&
      (
        Math.abs(z - this.layout.spawn.z) < 5 ||
        Math.abs(z - this.layout.centerZ) < 5
      );
    if (inMunicipalStagingBay) return true;
    return this.traffic.listAgents().every((agent) => {
      const position = this.traffic.positionForAgent(agent);
      if (!position) return true;
      const dimensions = VEHICLE_DIMENSIONS[agent.type];
      const scale = VEHICLE_PRESENTATION_SCALE[agent.type];
      const trafficRadius = Math.max(dimensions[0] * 0.55, dimensions[2] * 0.2);
      return Math.hypot(position.x - x, position.z - z) >
        radius + trafficRadius * scale;
    });
  }

  public requiredPlowAt(
    x: number,
    z: number,
  ): SnowEmergencyPlowClass | undefined {
    // Full-length sidewalk strips overlap crossing geometry at intersections;
    // the drivable road must own those shared pixels.
    const road = snowEmergencyRoadAt(x, z, this.layout);
    if (road) return road.requiredPlow;
    if (snowEmergencySidewalkAt(x, z, this.layout)) return 'COMPACT';
    return undefined;
  }

  public recordPlayerPlow(
    distanceMetres: number,
    movedSnow: number,
    peakBankHeight: number,
  ): void {
    if (!this.active) return;
    if (movedSnow > 0.0001) {
      this.plowedDistanceMetres += Math.max(0, distanceMetres);
      this.movedSnow += movedSnow;
    }
    this.maximumBankHeight = Math.max(
      this.maximumBankHeight,
      Math.max(0, peakBankHeight),
    );
  }

  public update(
    deltaSeconds: number,
    focus: Readonly<{ x: number; z: number }>,
    snow: LandSnowSystem,
    camera?: Readonly<{ x: number; y: number; z: number }>,
    isometricCutaway = false,
  ): void {
    if (!this.active) return;
    const delta = clamp(deltaSeconds, 0, 0.1);
    this.trafficAccumulator += delta;
    while (this.trafficAccumulator >= 0.1) {
      this.traffic.step(0.1, {
        sampleSnowDepth: (x, z) => snow.sampleDepth(x, z),
        player: { x: focus.x, z: focus.z, radius: 2.1 },
      });
      this.trafficAccumulator -= 0.1;
    }
    this.roadObservationAccumulator += delta;
    if (this.roadObservationAccumulator >= 0.75) {
      this.roadObservationAccumulator = 0;
      this.updateRoadPassability(snow);
    }
    this.signalAccumulator += delta;
    if (this.signalAccumulator >= 0.1) {
      this.signalAccumulator = 0;
      this.updateSignalPresentation();
    }
    this.presentationAccumulator += delta;
    if (this.presentationAccumulator >= 1 / 30) {
      this.presentationAccumulator = 0;
      this.updateBuildingCutaway(focus, camera, isometricCutaway);
      this.updateRoadSnowCover(focus);
      this.updateTrafficPresentation(focus, snow);
    }
  }

  public getStats(): SnowEmergencyCityStats {
    const traffic = this.traffic.getStats();
    const totalPrioritySegments = this.layout.roads.filter(
      (road) => road.priority >= 2,
    ).length;
    return {
      ...traffic,
      active: this.active,
      visibleVehicles: this.visibleVehicles,
      passableRoadSegments: this.passableRoadSegments,
      totalRoadSegments: this.layout.roads.length,
      passablePrioritySegments: this.passablePrioritySegments,
      totalPrioritySegments,
      plowedDistanceMetres: this.plowedDistanceMetres,
      movedSnow: this.movedSnow,
      maximumBankHeight: this.maximumBankHeight,
    };
  }

  public dispose(): void {
    const geometries = new Set<BoxGeometry | CylinderGeometry | SphereGeometry>();
    this.root.traverse((object) => {
      if (object instanceof InstancedMesh) {
        geometries.add(object.geometry as BoxGeometry | CylinderGeometry | SphereGeometry);
      }
    });
    for (const geometry of geometries) geometry.dispose();
    for (const material of this.materials) material.dispose();
    this.root.removeFromParent();
  }

  private createRoadPresentation(): void {
    const unitBox = new BoxGeometry(1, 1, 1);
    for (const roadClass of ['BOULEVARD', 'AVENUE', 'LOCAL'] as const) {
      const roads = this.layout.roads.filter(
        (road) => road.roadClass === roadClass,
      );
      const roadPatches = roads.flatMap((road) => {
        const patchCount = 8;
        return Array.from({ length: patchCount }, (_, patch) => {
          const along = ((patch + 0.5) / patchCount - 0.5) * road.length;
          return {
            road,
            x: road.centerX + (road.axis === 'X' ? along : 0),
            z: road.centerZ + (road.axis === 'Z' ? along : 0),
            length: road.length / patchCount + 0.12,
          };
        });
      });
      const material = createMaterial(ROAD_MATERIAL_COLORS[roadClass], 0.98);
      this.materials.push(material);
      const mesh = new InstancedMesh(unitBox, material, roadPatches.length);
      mesh.name = `Snow city ${roadClass.toLowerCase()} road slabs`;
      roadPatches.forEach((patch, index) => {
        const { road } = patch;
        const y = this.terrain.sampleHeight(patch.x, patch.z) + 0.018;
        this.transform.position.set(patch.x, y, patch.z);
        this.transform.rotation.set(0, 0, 0);
        this.transform.scale.set(
          road.axis === 'X' ? patch.length : road.width,
          0.035,
          road.axis === 'X' ? road.width : patch.length,
        );
        this.transform.updateMatrix();
        mesh.setMatrixAt(index, this.transform.matrix);
      });
      mesh.instanceMatrix.needsUpdate = true;
      mesh.receiveShadow = true;
      this.root.add(mesh);
    }
    const sidewalkMaterial = createMaterial(0x747c7e, 0.96);
    this.materials.push(sidewalkMaterial);
    const sidewalkPatches = this.layout.sidewalks.flatMap((sidewalk) => {
      const patchCount = 8;
      const { axis } = sidewalk;
      const length = axis === 'X' ? sidewalk.width : sidewalk.depth;
      const crossWidth = axis === 'X' ? sidewalk.depth : sidewalk.width;
      return Array.from({ length: patchCount }, (_, patch) => {
        const along = ((patch + 0.5) / patchCount - 0.5) * length;
        return {
          x: sidewalk.centerX + (axis === 'X' ? along : 0),
          z: sidewalk.centerZ + (axis === 'Z' ? along : 0),
          width: axis === 'X' ? length / patchCount + 0.08 : crossWidth,
          depth: axis === 'Z' ? length / patchCount + 0.08 : crossWidth,
        };
      });
    });
    const sidewalkMesh = new InstancedMesh(
      new BoxGeometry(1, 1, 1),
      sidewalkMaterial,
      sidewalkPatches.length,
    );
    sidewalkMesh.name = 'Snow city compact-plow sidewalks';
    sidewalkPatches.forEach((sidewalk, index) => {
      const y = this.terrain.sampleHeight(
        sidewalk.x,
        sidewalk.z,
      ) + 0.075;
      this.transform.position.set(sidewalk.x, y, sidewalk.z);
      this.transform.rotation.set(0, 0, 0);
      this.transform.scale.set(sidewalk.width, 0.15, sidewalk.depth);
      this.transform.updateMatrix();
      sidewalkMesh.setMatrixAt(index, this.transform.matrix);
    });
    sidewalkMesh.instanceMatrix.needsUpdate = true;
    sidewalkMesh.receiveShadow = true;
    this.root.add(sidewalkMesh);

    const stripeMaterial = createMaterial(0xd9e2dd, 0.82);
    this.materials.push(stripeMaterial);
    const laneMarkers: Array<Readonly<{
      x: number;
      z: number;
      width: number;
      depth: number;
    }>> = [];
    for (const road of this.layout.roads) {
      const dashes = Math.max(2, Math.floor(road.length / 6));
      const lateralOffsets = road.laneCountPerDirection === 2
        ? [-road.width * 0.23, 0, road.width * 0.23]
        : [0];
      for (const lateral of lateralOffsets) {
        for (let dash = 0; dash < dashes; dash += 1) {
          if (dash % 2 !== 0) continue;
          const along = ((dash + 0.5) / dashes - 0.5) * road.length;
          laneMarkers.push({
            x: road.centerX + (road.axis === 'X' ? along : lateral),
            z: road.centerZ + (road.axis === 'Z' ? along : lateral),
            width: road.axis === 'X' ? 2.8 : 0.11,
            depth: road.axis === 'Z' ? 2.8 : 0.11,
          });
        }
      }
    }
    const laneMarkerMesh = new InstancedMesh(
      new BoxGeometry(1, 1, 1),
      stripeMaterial,
      laneMarkers.length,
    );
    laneMarkerMesh.name = 'Snow city pooled lane markings';
    laneMarkers.forEach((marker, index) => {
      const y = this.terrain.sampleHeight(marker.x, marker.z) + 0.048;
      this.transform.position.set(marker.x, y, marker.z);
      this.transform.rotation.set(0, 0, 0);
      this.transform.scale.set(marker.width, 0.022, marker.depth);
      this.transform.updateMatrix();
      laneMarkerMesh.setMatrixAt(index, this.transform.matrix);
    });
    laneMarkerMesh.instanceMatrix.needsUpdate = true;
    this.root.add(laneMarkerMesh);

    const snowCoverMaterial = createMaterial(0xe7f1ef, 0.98);
    this.materials.push(snowCoverMaterial);
    for (const road of this.layout.roads) {
      const patchCount = 8;
      for (let patch = 0; patch < patchCount; patch += 1) {
        const along = ((patch + 0.5) / patchCount - 0.5) * road.length;
        const x = road.centerX + (road.axis === 'X' ? along : 0);
        const z = road.centerZ + (road.axis === 'Z' ? along : 0);
        const depth = initialLandSnowDepth(x, z);
        this.roadSnowCoverPatches.push({
          x,
          z,
          y: this.terrain.sampleHeight(x, z) + 0.016 +
            visualLandSnowHeight(depth, 0),
          width: road.axis === 'X' ? road.length / patchCount + 0.12 : road.width,
          depth: road.axis === 'Z' ? road.length / patchCount + 0.12 : road.width,
        });
      }
    }
    this.roadSnowCover = new InstancedMesh(
      new BoxGeometry(1, 1, 1),
      snowCoverMaterial,
      this.roadSnowCoverPatches.length,
    );
    this.roadSnowCover.name = 'Snow city distant road snow continuity cover';
    this.roadSnowCover.instanceMatrix.setUsage(DynamicDrawUsage);
    this.roadSnowCover.receiveShadow = true;
    this.root.add(this.roadSnowCover);
    this.updateRoadSnowCover({ x: Number.POSITIVE_INFINITY, z: 0 });

    const stripeCount = this.layout.intersections.length * 8;
    const stripes = new InstancedMesh(
      new BoxGeometry(1, 1, 1),
      stripeMaterial,
      stripeCount,
    );
    stripes.name = 'Snow city crosswalk markings';
    let stripeIndex = 0;
    for (const intersection of this.layout.intersections) {
      for (let stripe = -2; stripe <= 1; stripe += 1) {
        for (const axis of ['X', 'Z'] as const) {
          const y = this.terrain.sampleHeight(intersection.x, intersection.z) +
            0.045;
          this.transform.position.set(
            intersection.x + (axis === 'X' ? stripe * 1.3 : 0),
            y,
            intersection.z + (axis === 'Z' ? stripe * 1.3 : 0),
          );
          this.transform.rotation.set(0, 0, 0);
          this.transform.scale.set(
            axis === 'X' ? 0.7 : 7.2,
            0.025,
            axis === 'X' ? 7.2 : 0.7,
          );
          this.transform.updateMatrix();
          stripes.setMatrixAt(stripeIndex++, this.transform.matrix);
        }
      }
    }
    stripes.instanceMatrix.needsUpdate = true;
    this.root.add(stripes);
  }

  private createBuildingPresentation(): void {
    const buildingMaterial = createMaterial(0xffffff, 0.88);
    const windowMaterial = createMaterial(0xdff6ee, 0.42, 0x7ca89d);
    const roofMaterial = createMaterial(0xe8efec, 0.98);
    this.materials.push(buildingMaterial, windowMaterial, roofMaterial);
    const buildings = new InstancedMesh(
      new BoxGeometry(1, 1, 1),
      buildingMaterial,
      this.layout.buildings.length,
    );
    buildings.name = 'Snow city low-poly towers';
    buildings.instanceMatrix.setUsage(DynamicDrawUsage);
    buildings.castShadow = true;
    buildings.receiveShadow = true;
    const roofCaps = new InstancedMesh(
      new BoxGeometry(1, 1, 1),
      roofMaterial,
      this.layout.buildings.length,
    );
    roofCaps.name = 'Snow city tower roof snow caps';
    roofCaps.instanceMatrix.setUsage(DynamicDrawUsage);
    const bandCount = this.layout.buildings.length * 5;
    const windowBands = new InstancedMesh(
      new BoxGeometry(1, 1, 1),
      windowMaterial,
      bandCount,
    );
    windowBands.name = 'Snow city pooled lit window bands';
    windowBands.instanceMatrix.setUsage(DynamicDrawUsage);
    let bandIndex = 0;
    this.layout.buildings.forEach((building, index) => {
      const ground = this.terrain.sampleHeight(building.x, building.z);
      this.transform.position.set(
        building.x,
        ground + building.height * 0.5 + 0.1,
        building.z,
      );
      this.transform.rotation.set(0, 0, 0);
      this.transform.scale.set(
        building.width,
        building.height,
        building.depth,
      );
      this.transform.updateMatrix();
      buildings.setMatrixAt(index, this.transform.matrix);
      buildings.setColorAt(index, this.color.setHex(building.color));

      this.transform.position.y = ground + building.height + 0.22;
      this.transform.scale.set(
        building.width * 1.025,
        0.42,
        building.depth * 1.025,
      );
      this.transform.updateMatrix();
      roofCaps.setMatrixAt(index, this.transform.matrix);

      for (let band = 0; band < 5; band += 1) {
        this.transform.position.set(
          building.x,
          ground + building.height * ((band + 1) / 6),
          building.z,
        );
        this.transform.scale.set(
          building.width * 1.012,
          Math.min(0.24, building.height * 0.012),
          building.depth * 1.012,
        );
        this.transform.updateMatrix();
        windowBands.setMatrixAt(bandIndex++, this.transform.matrix);
      }
    });
    buildings.instanceMatrix.needsUpdate = true;
    buildings.instanceColor!.needsUpdate = true;
    roofCaps.instanceMatrix.needsUpdate = true;
    windowBands.instanceMatrix.needsUpdate = true;
    this.root.add(buildings, roofCaps, windowBands);
    this.buildingMesh = buildings;
    this.buildingRoofCaps = roofCaps;
    this.buildingWindowBands = windowBands;
  }

  private updateBuildingCutaway(
    focus: Readonly<{ x: number; z: number }>,
    camera: Readonly<{ x: number; y: number; z: number }> | undefined,
    active: boolean,
  ): void {
    if (!this.buildingMesh || !camera) return;
    const cameraDeltaX = camera.x - focus.x;
    const cameraDeltaZ = camera.z - focus.z;
    const cameraDistance = Math.hypot(cameraDeltaX, cameraDeltaZ);
    const viewX = cameraDistance > 0.001 ? cameraDeltaX / cameraDistance : 0;
    const viewZ = cameraDistance > 0.001 ? cameraDeltaZ / cameraDistance : 1;
    let bandIndex = 0;
    this.layout.buildings.forEach((building, index) => {
      const offsetX = building.x - focus.x;
      const offsetZ = building.z - focus.z;
      const alongView = offsetX * viewX + offsetZ * viewZ;
      const acrossView = Math.abs(offsetX * viewZ - offsetZ * viewX);
      const footprintRadius = Math.hypot(building.width, building.depth) * 0.45;
      const cut = active &&
        alongView > -footprintRadius * 0.3 &&
        alongView < Math.min(82, cameraDistance + footprintRadius) &&
        acrossView < footprintRadius + 3.8;
      const height = cut ? Math.min(3.1, building.height) : building.height;
      const ground = this.terrain.sampleHeight(building.x, building.z);
      this.transform.position.set(
        building.x,
        ground + height * 0.5 + 0.1,
        building.z,
      );
      this.transform.rotation.set(0, 0, 0);
      this.transform.scale.set(building.width, height, building.depth);
      this.transform.updateMatrix();
      this.buildingMesh.setMatrixAt(index, this.transform.matrix);

      this.transform.position.y = ground + height + 0.22;
      this.transform.scale.set(
        building.width * 1.025,
        0.42,
        building.depth * 1.025,
      );
      this.transform.updateMatrix();
      this.buildingRoofCaps.setMatrixAt(index, this.transform.matrix);

      for (let band = 0; band < 5; band += 1) {
        this.transform.position.set(
          building.x,
          cut ? ground - 2 : ground + height * ((band + 1) / 6),
          building.z,
        );
        this.transform.scale.set(
          cut ? 0.001 : building.width * 1.012,
          cut ? 0.001 : Math.min(0.24, height * 0.012),
          cut ? 0.001 : building.depth * 1.012,
        );
        this.transform.updateMatrix();
        this.buildingWindowBands.setMatrixAt(bandIndex++, this.transform.matrix);
      }
    });
    this.buildingMesh.instanceMatrix.needsUpdate = true;
    this.buildingRoofCaps.instanceMatrix.needsUpdate = true;
    this.buildingWindowBands.instanceMatrix.needsUpdate = true;
  }

  private updateRoadSnowCover(
    focus: Readonly<{ x: number; z: number }>,
  ): void {
    if (!this.roadSnowCover) return;
    this.roadSnowCoverPatches.forEach((patch, index) => {
      const deformableSnowOwnsPatch =
        Math.hypot(patch.x - focus.x, patch.z - focus.z) < 30;
      this.transform.position.set(
        patch.x,
        deformableSnowOwnsPatch ? -20 : patch.y,
        patch.z,
      );
      this.transform.rotation.set(0, 0, 0);
      this.transform.scale.set(
        patch.width,
        deformableSnowOwnsPatch ? 0.001 : 0.045,
        patch.depth,
      );
      this.transform.updateMatrix();
      this.roadSnowCover.setMatrixAt(index, this.transform.matrix);
    });
    this.roadSnowCover.instanceMatrix.needsUpdate = true;
  }

  private createSignalPresentation(): void {
    const poleMaterial = createMaterial(0x283338, 0.7);
    const bulbMaterial = createMaterial(0xffffff, 0.48, 0xffffff);
    this.materials.push(poleMaterial, bulbMaterial);
    const count = this.layout.intersections.length * 4;
    const poles = new InstancedMesh(
      new CylinderGeometry(0.09, 0.12, 3.3, 6),
      poleMaterial,
      count,
    );
    poles.name = 'Snow city traffic signal poles';
    this.signalBulbs = new InstancedMesh(
      new SphereGeometry(0.19, 7, 5),
      bulbMaterial,
      count,
    );
    this.signalBulbs.name = 'Snow city working traffic signals';
    let index = 0;
    for (const intersection of this.layout.intersections) {
      for (const approach of [
        { dx: -1, dz: -1, axis: 'X' as const, heading: Math.PI / 2 },
        { dx: 1, dz: 1, axis: 'X' as const, heading: -Math.PI / 2 },
        { dx: -1, dz: 1, axis: 'Z' as const, heading: 0 },
        { dx: 1, dz: -1, axis: 'Z' as const, heading: Math.PI },
      ]) {
        const x = intersection.x + approach.dx * 6.2;
        const z = intersection.z + approach.dz * 6.2;
        const ground = this.terrain.sampleHeight(x, z);
        this.transform.position.set(x, ground + 1.65, z);
        this.transform.rotation.set(0, 0, 0);
        this.transform.scale.set(1, 1, 1);
        this.transform.updateMatrix();
        poles.setMatrixAt(index, this.transform.matrix);
        this.transform.position.y = ground + 3.15;
        this.transform.updateMatrix();
        this.signalBulbs.setMatrixAt(index, this.transform.matrix);
        this.signalApproaches.push({
          intersectionId: intersection.id,
          axis: approach.axis,
          x,
          z,
          heading: approach.heading,
        });
        index += 1;
      }
    }
    poles.instanceMatrix.needsUpdate = true;
    this.signalBulbs.instanceMatrix.needsUpdate = true;
    this.root.add(poles, this.signalBulbs);
    this.updateSignalPresentation();
  }

  private updateSignalPresentation(): void {
    this.signalApproaches.forEach((approach, index) => {
      const state = this.traffic.signalState(
        approach.intersectionId,
        approach.axis,
      );
      this.signalBulbs.setColorAt(
        index,
        this.color.setHex(
          state === 'GREEN'
            ? 0x56ef8d
            : state === 'YELLOW'
              ? 0xffc94e
              : 0xff4f54,
        ),
      );
    });
    this.signalBulbs.instanceColor!.needsUpdate = true;
  }

  private updateTrafficPresentation(
    focus: Readonly<{ x: number; z: number }>,
    snow: LandSnowSystem,
  ): void {
    const nearest = this.traffic.listAgents()
      .map((agent) => {
        const position = this.traffic.positionForAgent(agent);
        return position
          ? {
              agent,
              position,
              distance: Math.hypot(position.x - focus.x, position.z - focus.z),
            }
          : undefined;
      })
      .filter((entry): entry is NonNullable<typeof entry> =>
        entry !== undefined && entry.distance <= 92
      )
      .sort((a, b) => a.distance - b.distance)
      .slice(0, MAX_VISIBLE_TRAFFIC);
    let index = 0;
    for (const entry of nearest) {
      const dimensions = VEHICLE_DIMENSIONS[entry.agent.type];
      const presentationScale = VEHICLE_PRESENTATION_SCALE[entry.agent.type];
      const surfaceY = snow.sampleSurfaceHeight(
        entry.position.x,
        entry.position.z,
      );
      this.transform.position.set(
        entry.position.x,
        surfaceY + dimensions[1] * 0.34,
        entry.position.z,
      );
      this.transform.rotation.set(0, entry.position.heading, 0);
      this.transform.scale.set(
        dimensions[0] * presentationScale,
        dimensions[1] * 0.58 * presentationScale,
        dimensions[2] * presentationScale,
      );
      this.transform.updateMatrix();
      this.trafficBodies.setMatrixAt(index, this.transform.matrix);
      let color = VEHICLE_COLORS[entry.agent.type];
      if (entry.agent.crashed) {
        color = Math.floor(performance.now() / 220 + entry.agent.id) % 2 === 0
          ? 0xff343b
          : 0x5e171d;
      } else if (
        entry.agent.type === 'AMBULANCE' &&
        Math.floor(performance.now() / 180 + entry.agent.id) % 2 === 0
      ) color = 0x3f79ff;
      this.trafficBodies.setColorAt(index, this.color.setHex(color));

      this.transform.position.y = surfaceY + dimensions[1] * 0.78;
      this.transform.scale.set(
        dimensions[0] * 0.76 * presentationScale,
        dimensions[1] * 0.34 * presentationScale,
        dimensions[2] * (entry.agent.type === 'BUS' ? 0.78 : 0.48) *
          presentationScale,
      );
      this.transform.updateMatrix();
      this.trafficCabins.setMatrixAt(index, this.transform.matrix);
      index += 1;
    }
    this.visibleVehicles = index;
    this.trafficBodies.count = index;
    this.trafficCabins.count = index;
    this.trafficBodies.instanceMatrix.needsUpdate = true;
    this.trafficCabins.instanceMatrix.needsUpdate = true;
    if (this.trafficBodies.instanceColor) {
      this.trafficBodies.instanceColor.needsUpdate = true;
    }
  }

  private updateRoadPassability(snow: LandSnowSystem): void {
    let passable = 0;
    let priorityPassable = 0;
    for (const road of this.layout.roads) {
      let depth = 0;
      for (const progress of [0.2, 0.5, 0.8]) {
        const x = road.axis === 'X'
          ? road.centerX + (progress - 0.5) * road.length
          : road.centerX;
        const z = road.axis === 'Z'
          ? road.centerZ + (progress - 0.5) * road.length
          : road.centerZ;
        depth += snow.sampleDepth(x, z);
      }
      const averageDepth = depth / 3;
      const threshold = road.roadClass === 'BOULEVARD' ? 0.26 : 0.2;
      if (averageDepth <= threshold) {
        passable += 1;
        if (road.priority >= 2) priorityPassable += 1;
      }
    }
    this.passableRoadSegments = passable;
    this.passablePrioritySegments = priorityPassable;
  }
}
