import {
  CONSTRUCTION_GRID_METRES,
  type ConstructionBlueprint,
  type ConstructionDirection,
  type ConstructionPlacement,
} from './ConstructionBlueprint';
import {
  getResolvedConstructionModule,
  type ConstructionModuleSocket,
} from './ConstructionModuleCatalog';

export interface HeadlessResolvedConstructionSocket {
  placementId: string;
  moduleId: string;
  socket: ConstructionModuleSocket;
  position: ConstructionDirection;
  normal: ConstructionDirection;
}

export interface ConstructionConnectionValidationResult {
  accepted: boolean;
  reason?: string;
}

interface QuaternionLike {
  x: number;
  y: number;
  z: number;
  w: number;
}

const degreesToRadians = (degrees: number): number =>
  degrees * Math.PI / 180;

/** Matches Three.js Euler order XYZ without importing a renderer package. */
const placementQuaternion = (
  placement: Readonly<ConstructionPlacement>,
): QuaternionLike => {
  const x = degreesToRadians(placement.pitchDegrees) * 0.5;
  const y = degreesToRadians(placement.yawDegrees) * 0.5;
  const z = degreesToRadians(placement.rollDegrees) * 0.5;
  const c1 = Math.cos(x);
  const c2 = Math.cos(y);
  const c3 = Math.cos(z);
  const s1 = Math.sin(x);
  const s2 = Math.sin(y);
  const s3 = Math.sin(z);
  return {
    x: s1 * c2 * c3 + c1 * s2 * s3,
    y: c1 * s2 * c3 - s1 * c2 * s3,
    z: c1 * c2 * s3 + s1 * s2 * c3,
    w: c1 * c2 * c3 - s1 * s2 * s3,
  };
};

const rotateDirection = (
  direction: Readonly<ConstructionDirection>,
  placement: Readonly<ConstructionPlacement>,
): ConstructionDirection => {
  const vector = {
    x: direction.x,
    y: direction.y,
    z: placement.flipped ? -direction.z : direction.z,
  };
  const quaternion = placementQuaternion(placement);
  const ix = quaternion.w * vector.x + quaternion.y * vector.z - quaternion.z * vector.y;
  const iy = quaternion.w * vector.y + quaternion.z * vector.x - quaternion.x * vector.z;
  const iz = quaternion.w * vector.z + quaternion.x * vector.y - quaternion.y * vector.x;
  const iw = -quaternion.x * vector.x - quaternion.y * vector.y - quaternion.z * vector.z;
  return {
    x: ix * quaternion.w + iw * -quaternion.x + iy * -quaternion.z - iz * -quaternion.y,
    y: iy * quaternion.w + iw * -quaternion.y + iz * -quaternion.x - ix * -quaternion.z,
    z: iz * quaternion.w + iw * -quaternion.z + ix * -quaternion.y - iy * -quaternion.x,
  };
};

export const constructionSocketsCompatibleHeadless = (
  target: Readonly<ConstructionModuleSocket>,
  source: Readonly<ConstructionModuleSocket>,
): boolean => {
  if (target.connectionKind !== source.connectionKind) return false;
  if (target.polarity === 'neutral' || source.polarity === 'neutral') {
    if (target.polarity !== 'neutral' || source.polarity !== 'neutral') {
      return false;
    }
    if (
      target.connectionKind === 'keel-run' ||
      target.connectionKind === 'hull-spine'
    ) {
      return (
        (target.id === 'forward' && source.id === 'aft') ||
        (target.id === 'aft' && source.id === 'forward')
      );
    }
    if (target.connectionKind === 'hull-bottom-expand') {
      const spansMatch =
        target.spanCells === undefined ||
        source.spanCells === undefined ||
        target.spanCells === source.spanCells;
      return spansMatch && (target.id === 'inner') !== (source.id === 'inner');
    }
    return true;
  }
  return (
    (target.polarity === 'top' && source.polarity === 'bottom') ||
    (target.polarity === 'bottom' && source.polarity === 'top')
  );
};

export const resolveConstructionSocketHeadless = (
  placement: Readonly<ConstructionPlacement>,
  socket: Readonly<ConstructionModuleSocket>,
): HeadlessResolvedConstructionSocket => {
  const localPosition = rotateDirection(socket.position, placement);
  const normal = rotateDirection(socket.normal, placement);
  return {
    placementId: placement.id,
    moduleId: placement.moduleId,
    socket: { ...socket },
    position: {
      x: placement.position.x * CONSTRUCTION_GRID_METRES + localPosition.x,
      y: placement.position.y * CONSTRUCTION_GRID_METRES + localPosition.y,
      z: placement.position.z * CONSTRUCTION_GRID_METRES + localPosition.z,
    },
    normal,
  };
};

export const constructionSocketOccupiedHeadless = (
  blueprint: Readonly<ConstructionBlueprint>,
  placementId: string,
  socketId: string,
  ignoredPlacementId?: string,
): boolean =>
  blueprint.placements.some((placement) => {
    if (
      placement.id === ignoredPlacementId ||
      placement.mount.kind !== 'grid' ||
      !placement.mount.connection
    ) return false;
    const connection = placement.mount.connection;
    return (
      (connection.hostPlacementId === placementId &&
        connection.hostSocketId === socketId) ||
      (placement.id === placementId && connection.sourceSocketId === socketId)
    );
  });

const socketDistance = (
  left: Readonly<ConstructionDirection>,
  right: Readonly<ConstructionDirection>,
): number => Math.hypot(left.x - right.x, left.y - right.y, left.z - right.z);

const normalizedDot = (
  left: Readonly<ConstructionDirection>,
  right: Readonly<ConstructionDirection>,
): number => {
  const leftLength = Math.hypot(left.x, left.y, left.z);
  const rightLength = Math.hypot(right.x, right.y, right.z);
  if (leftLength < 1e-6 || rightLength < 1e-6) return 1;
  return (
    left.x * right.x + left.y * right.y + left.z * right.z
  ) / (leftLength * rightLength);
};

/** Validates catalog identity, exclusivity and spatial alignment for all joins. */
export const validateConstructionConnections = (
  blueprint: Readonly<ConstructionBlueprint>,
): ConstructionConnectionValidationResult => {
  const byId = new Map(
    blueprint.placements.map((placement) => [placement.id, placement] as const),
  );
  const occupiedTargets = new Set<string>();
  for (const placement of blueprint.placements) {
    if (placement.mount.kind !== 'grid' || !placement.mount.connection) continue;
    const connection = placement.mount.connection;
    const host = byId.get(connection.hostPlacementId);
    if (!host || host.id === placement.id) {
      return { accepted: false, reason: 'INVALID_SOCKET_HOST' };
    }
    const hostDefinition = getResolvedConstructionModule(host.moduleId, host.shape);
    const sourceDefinition = getResolvedConstructionModule(
      placement.moduleId,
      placement.shape,
    );
    const hostSocket = hostDefinition?.sockets.find(
      (socket) => socket.id === connection.hostSocketId,
    );
    const sourceSocket = sourceDefinition?.sockets.find(
      (socket) => socket.id === connection.sourceSocketId,
    );
    if (!hostSocket || !sourceSocket) {
      return { accepted: false, reason: 'UNKNOWN_SOCKET_ID' };
    }
    if (!constructionSocketsCompatibleHeadless(hostSocket, sourceSocket)) {
      return { accepted: false, reason: 'INCOMPATIBLE_SOCKETS' };
    }
    const targetKey = `${host.id}\u0000${hostSocket.id}`;
    if (occupiedTargets.has(targetKey)) {
      return { accepted: false, reason: 'SOCKET_OCCUPIED' };
    }
    occupiedTargets.add(targetKey);
    const target = resolveConstructionSocketHeadless(host, hostSocket);
    const source = resolveConstructionSocketHeadless(placement, sourceSocket);
    if (socketDistance(target.position, source.position) > 0.035) {
      return { accepted: false, reason: 'SOCKET_POSITION_MISMATCH' };
    }
    if (normalizedDot(target.normal, source.normal) > -0.99) {
      return { accepted: false, reason: 'SOCKET_NORMAL_MISMATCH' };
    }
  }

  // Every mount chain must terminate instead of forming a dependency cycle.
  for (const placement of blueprint.placements) {
    const visited = new Set<string>();
    let cursor: ConstructionPlacement | undefined = placement;
    while (cursor) {
      if (visited.has(cursor.id)) {
        return { accepted: false, reason: 'MOUNT_DEPENDENCY_CYCLE' };
      }
      visited.add(cursor.id);
      const hostId: string | undefined = cursor.mount.kind === 'surface'
        ? cursor.mount.hostPlacementId
        : cursor.mount.connection?.hostPlacementId;
      cursor = hostId ? byId.get(hostId) : undefined;
    }
  }
  return { accepted: true };
};
