import { OrthographicCamera, Vector3 } from 'three';

export interface WeatherCoverage {
  centerX: number;
  centerZ: number;
  width: number;
  depth: number;
}

const direction = new Vector3();
const cameraRight = new Vector3();
const cameraUp = new Vector3();
const groundUp = new Vector3();
const spawnCameraUp = new Vector3();

export const calculateWeatherCoverage = (
  camera: OrthographicCamera,
  seaLevel = 0,
): WeatherCoverage => {
  camera.updateMatrixWorld();
  camera.getWorldDirection(direction);
  const distanceToSea =
    Math.abs(direction.y) > 0.0001
      ? (seaLevel - camera.position.y) / direction.y
      : 0;
  const centerX = camera.position.x + direction.x * distanceToSea;
  const centerZ = camera.position.z + direction.z * distanceToSea;
  const viewWidth = (camera.right - camera.left) / camera.zoom;
  const viewHeight = (camera.top - camera.bottom) / camera.zoom;
  const elements = camera.matrixWorld.elements;
  cameraRight.set(elements[0]!, elements[1]!, elements[2]!);
  cameraUp.set(elements[4]!, elements[5]!, elements[6]!);
  groundUp
    .copy(cameraUp)
    .addScaledVector(
      direction,
      -cameraUp.y / Math.min(-0.0001, direction.y),
    );

  const horizontalSpan =
    Math.abs(cameraRight.x) * viewWidth +
    Math.abs(groundUp.x) * viewHeight;
  const depthSpan =
    Math.abs(cameraRight.z) * viewWidth +
    Math.abs(groundUp.z) * viewHeight;

  return {
    centerX,
    centerZ,
    width: horizontalSpan * 1.18 + 8,
    depth: depthSpan * 1.18 + 8,
  };
};

export const calculateWeatherSpawnCenter = (
  camera: OrthographicCamera,
  coverage: Readonly<WeatherCoverage>,
  screenUpOffset: number,
  seaLevel = 0,
  target = new Vector3(),
): Vector3 => {
  camera.updateMatrixWorld();
  const elements = camera.matrixWorld.elements;
  spawnCameraUp.set(
    elements[4]!,
    elements[5]!,
    elements[6]!,
  );
  return target
    .set(coverage.centerX, seaLevel, coverage.centerZ)
    .addScaledVector(spawnCameraUp, screenUpOffset);
};
