import { clamp } from '../utils/math';
import type {
  VesselControlCommand,
  VesselController,
} from '../vessels/VesselController';
import type { VesselState } from '../vessels/VesselState';
import {
  gamepadAxis,
  gamepadButtonPressed,
  gamepadButtonValue,
  getPrimaryGamepad,
} from './GamepadInput';

const CONTROL_KEYS = new Set([
  'ArrowUp',
  'ArrowDown',
  'ArrowLeft',
  'ArrowRight',
  'KeyW',
  'KeyA',
  'KeyS',
  'KeyD',
  'ShiftLeft',
  'ShiftRight',
  'Space',
  'KeyG',
  'KeyR',
]);

export class PlayerVesselController implements VesselController {
  private readonly pressed = new Set<string>();
  private enabled = false;
  private realisticSteering = false;
  private lightsToggleRequested = false;
  private hornRequested = false;
  private resetRequested = false;
  private gamepadLightsPressed = false;
  private gamepadHornPressed = false;
  private virtualThrottle = 0;
  private virtualRight = 0;

  public constructor() {
    window.addEventListener('keydown', this.onKeyDown);
    window.addEventListener('keyup', this.onKeyUp);
    window.addEventListener('blur', this.onBlur);
  }

  public setEnabled(enabled: boolean): void {
    this.enabled = enabled;
    if (!enabled) {
      this.pressed.clear();
      this.lightsToggleRequested = false;
      this.gamepadLightsPressed = false;
      this.gamepadHornPressed = false;
      this.virtualThrottle = 0;
      this.virtualRight = 0;
    }
  }

  /** Input seam for a later mobile helm stick. */
  public setVirtualMovement(right: number, forward: number): void {
    this.virtualRight = clamp(right, -1, 1);
    this.virtualThrottle = clamp(forward, -1, 1);
  }

  public setRealisticSteering(realistic: boolean): void {
    this.realisticSteering = realistic;
  }

  public sampleControls(
    _state: Readonly<VesselState>,
    _deltaSeconds: number,
  ): VesselControlCommand {
    if (!this.enabled) {
      return {
        throttleTarget: 0,
        steeringTarget: 0,
        boost: false,
        toggleLights: false,
        horn: false,
        requestReset: false,
      };
    }

    const forward = this.isPressed('KeyW', 'ArrowUp') ? 1 : 0;
    const reverse = this.isPressed('KeyS', 'ArrowDown') ? 1 : 0;
    const left = this.isPressed('KeyA', 'ArrowLeft') ? 1 : 0;
    const right = this.isPressed('KeyD', 'ArrowRight') ? 1 : 0;
    const gamepad = getPrimaryGamepad();
    const gamepadThrottle =
      gamepadButtonValue(gamepad, 7) -
      gamepadButtonValue(gamepad, 6);
    const gamepadSteering = gamepadAxis(gamepad, 0);
    const gamepadLights = gamepadButtonPressed(gamepad, 12);
    if (gamepadLights && !this.gamepadLightsPressed) {
      this.lightsToggleRequested = true;
    }
    this.gamepadLightsPressed = gamepadLights;
    const gamepadHorn = gamepadButtonPressed(gamepad, 0);
    if (gamepadHorn && !this.gamepadHornPressed) {
      this.hornRequested = true;
    }
    this.gamepadHornPressed = gamepadHorn;
    // In the simulation's heading convention a negative steering command
    // turns the presented bow right. Default input follows the visible turn;
    // realistic mode treats the keys as direct rudder input instead.
    const steeringDirection = this.realisticSteering ? 1 : -1;
    const keyboardThrottle = clamp(forward - reverse, -1, 1);
    const keyboardSteering = clamp(right - left, -1, 1);
    const command = {
      throttleTarget:
        Math.abs(keyboardThrottle) > 0.01
          ? keyboardThrottle
          : Math.abs(this.virtualThrottle) > 0.01
            ? this.virtualThrottle
            : gamepadThrottle,
      steeringTarget:
        (Math.abs(keyboardSteering) > 0.01
          ? keyboardSteering
          : Math.abs(this.virtualRight) > 0.01
            ? this.virtualRight
            : gamepadSteering) * steeringDirection,
      boost:
        this.isPressed('ShiftLeft', 'ShiftRight') ||
        gamepadButtonPressed(gamepad, 1),
      toggleLights: this.lightsToggleRequested,
      horn: this.hornRequested,
      requestReset: this.resetRequested,
    };
    this.lightsToggleRequested = false;
    this.hornRequested = false;
    this.resetRequested = false;
    return command;
  }

  public dispose(): void {
    window.removeEventListener('keydown', this.onKeyDown);
    window.removeEventListener('keyup', this.onKeyUp);
    window.removeEventListener('blur', this.onBlur);
  }

  private isPressed(...codes: string[]): boolean {
    return codes.some((code) => this.pressed.has(code));
  }

  private onKeyDown = (event: KeyboardEvent): void => {
    if (!this.enabled) return;
    if (CONTROL_KEYS.has(event.code)) event.preventDefault();
    this.pressed.add(event.code);
    if (!event.repeat && event.code === 'KeyG') {
      this.lightsToggleRequested = true;
    }
    if (!event.repeat && event.code === 'Space') this.hornRequested = true;
    if (!event.repeat && event.code === 'KeyR') this.resetRequested = true;
  };

  private onKeyUp = (event: KeyboardEvent): void => {
    this.pressed.delete(event.code);
  };

  private onBlur = (): void => {
    this.pressed.clear();
    this.lightsToggleRequested = false;
    this.gamepadLightsPressed = false;
  };
}
