import {
  BoxGeometry,
  Color,
  ConeGeometry,
  CylinderGeometry,
  DodecahedronGeometry,
  Group,
  InstancedMesh,
  Matrix4,
  Mesh,
  MeshStandardMaterial,
  Object3D,
  PointLight,
  Quaternion,
  SphereGeometry,
  TorusGeometry,
  Vector3,
  type BufferGeometry,
  type Scene,
} from 'three';
import { clamp, hash2D } from '../utils/math';
import { BOREALIS_GROUND_HEIGHT } from './BorealisLand';
import { BOREALIS_PARK_RESERVED_AREA } from './BorealisTownLayout';
import type { TerrainHeightSystem } from './TerrainHeightSystem';
import type { SnowObstacleDescriptor } from './SnowObstacleRegistry';

export const BOREALIS_PARK_CENTER = Object.freeze({
  x: BOREALIS_PARK_RESERVED_AREA.centerX,
  z: BOREALIS_PARK_RESERVED_AREA.centerZ,
});

export interface ParkCleaningObjectSaveData {
  id: string;
  snow: readonly number[];
  damaged?: boolean;
}

export interface ParkCleaningSaveData {
  version: 1;
  objects: readonly ParkCleaningObjectSaveData[];
}

export interface ParkBlowResult {
  removedSnow: number;
  cleanedPatches: number;
  cleanRatio: number;
  targetX: number;
  targetZ: number;
}

export interface ParkVehicleInteraction {
  blocked: boolean;
  damagedId?: string;
}

interface SnowPatch {
  objectId: string;
  x: number;
  y: number;
  z: number;
  scaleX: number;
  scaleY: number;
  scaleZ: number;
  rotation: number;
  snow: number;
}

interface CleanableParkObject {
  id: string;
  displayName: string;
  x: number;
  z: number;
  radius: number;
  group: Group;
  patches: SnowPatch[];
  damaged: boolean;
}

interface InstanceTransform {
  x: number;
  y: number;
  z: number;
  scaleX: number;
  scaleY: number;
  scaleZ: number;
  rotation?: number;
}

interface ParkObstacle {
  x: number;
  z: number;
  radius: number;
}

const CLEANING_RANGE = 4.2;
const CLEANING_HALF_ANGLE = 0.44;
const SNOW_PATCH_COUNT_PER_OBJECT = 10;
const PARK_SNOW_WEATHER_INTERVAL = 0.5;

export class BorealisParkSystem {
  private readonly root = new Group();
  private readonly geometries = new Set<BufferGeometry>();
  private readonly materials = new Set<MeshStandardMaterial>();
  private readonly cleanables: CleanableParkObject[] = [];
  private readonly obstacles: ParkObstacle[] = [];
  private readonly snowPatches: SnowPatch[] = [];
  private readonly snowMesh: InstancedMesh;
  private readonly transform = new Object3D();
  private readonly lights: PointLight[] = [];
  private visible = false;
  private night = 0;
  private snowDirty = true;
  private snowWeatherAccumulator = 0;
  private instancedProps = 0;
  private instancedDrawGroups = 0;
  private heroMeshes = 0;
  private readonly removeTerrainListener: () => void;

  public constructor(
    scene: Scene,
    terrain?: TerrainHeightSystem,
  ) {
    this.root.name = 'Borealis buried northwest park';
    const snowMaterial = this.material(0xe9f7f7, 0.96, 0);
    const snowGeometry = this.geometry(new SphereGeometry(1, 10, 7));
    this.createScenery();
    this.createCleanableObjects();
    this.snowMesh = new InstancedMesh(
      snowGeometry,
      snowMaterial,
      this.snowPatches.length,
    );
    this.snowMesh.name = 'Cleanable park asset snow shrouds';
    this.snowMesh.castShadow = true;
    this.snowMesh.receiveShadow = true;
    this.snowMesh.frustumCulled = false;
    this.root.add(this.snowMesh);
    this.updateSnowInstances();
    this.setVisible(false);
    scene.add(this.root);
    const alignToTerrain = (): void => {
      this.root.position.y = terrain
        ? terrain.sampleHeight(BOREALIS_PARK_CENTER.x, BOREALIS_PARK_CENTER.z) -
          BOREALIS_GROUND_HEIGHT
        : 0;
    };
    alignToTerrain();
    this.removeTerrainListener = terrain?.addListener(() => alignToTerrain()) ??
      (() => undefined);
  }

  public setVisible(visible: boolean): void {
    this.visible = visible;
    this.root.visible = visible;
    this.applyLightState();
  }

  public setEnvironmentLighting(night: number): void {
    this.night = clamp(night, 0, 1);
    this.applyLightState();
  }

  public update(): void {
    if (this.snowDirty) this.updateSnowInstances();
  }

  /** Re-covers every intact cold park detail during active snowfall. */
  public applySnowfall(deltaSeconds: number, snowIntensity: number): number {
    this.snowWeatherAccumulator += clamp(deltaSeconds, 0, 0.25);
    if (this.snowWeatherAccumulator < PARK_SNOW_WEATHER_INTERVAL) return 0;
    const elapsed = this.snowWeatherAccumulator;
    this.snowWeatherAccumulator = 0;
    const addition = clamp(snowIntensity, 0, 1) * elapsed * 0.0034;
    if (addition <= 0.00001) return 0;
    let changedPatches = 0;
    for (const object of this.cleanables) {
      if (object.damaged) continue;
      for (const patch of object.patches) {
        const next = Math.min(1, patch.snow + addition);
        if (next - patch.snow <= 0.00001) continue;
        patch.snow = next;
        changedPatches += 1;
      }
    }
    if (changedPatches > 0) this.snowDirty = true;
    return changedPatches;
  }

  public blowSnow(
    x: number,
    z: number,
    heading: number,
    deltaSeconds: number,
  ): ParkBlowResult {
    const forwardX = Math.sin(heading);
    const forwardZ = Math.cos(heading);
    const cosineLimit = Math.cos(CLEANING_HALF_ANGLE);
    let removedSnow = 0;
    let cleanedPatches = 0;
    let targetX = x + forwardX * 2.2;
    let targetZ = z + forwardZ * 2.2;
    let targetWeight = 0;
    for (const patch of this.snowPatches) {
      if (patch.snow <= 0.001) continue;
      const dx = patch.x - x;
      const dz = patch.z - z;
      const distance = Math.hypot(dx, dz);
      if (distance < 0.18 || distance > CLEANING_RANGE) continue;
      const facing = (dx * forwardX + dz * forwardZ) / distance;
      if (facing < cosineLimit) continue;
      const proximity = 1 - distance / CLEANING_RANGE;
      const direction = clamp(
        (facing - cosineLimit) / (1 - cosineLimit),
        0,
        1,
      );
      const strength =
        Math.max(0, deltaSeconds) *
        (0.22 + proximity * 0.62) *
        (0.35 + direction * 0.65);
      const previous = patch.snow;
      patch.snow = Math.max(0, patch.snow - strength);
      const removed = previous - patch.snow;
      if (removed <= 0) continue;
      removedSnow += removed;
      cleanedPatches += 1;
      targetX += patch.x * removed;
      targetZ += patch.z * removed;
      targetWeight += removed;
      this.snowDirty = true;
    }
    if (targetWeight > 0) {
      targetX /= 1 + targetWeight;
      targetZ /= 1 + targetWeight;
    }
    return {
      removedSnow,
      cleanedPatches,
      cleanRatio: this.getCleanRatio(),
      targetX,
      targetZ,
    };
  }

  public canWalkAt(x: number, z: number): boolean {
    return (
      !this.cleanables.some(
        (object) =>
          Math.hypot(x - object.x, z - object.z) < object.radius + 0.12,
      ) &&
      !this.obstacles.some(
        (obstacle) =>
          Math.hypot(x - obstacle.x, z - obstacle.z) < obstacle.radius,
      )
    );
  }

  public interactWithBulldozer(
    x: number,
    z: number,
    speed: number,
    bladeDown: boolean,
  ): ParkVehicleInteraction {
    if (
      this.obstacles.some(
        (obstacle) =>
          Math.hypot(x - obstacle.x, z - obstacle.z) <
          obstacle.radius + 0.92,
      )
    ) {
      return { blocked: true };
    }
    for (const object of this.cleanables) {
      if (Math.hypot(x - object.x, z - object.z) > object.radius + 1.05) {
        continue;
      }
      if (bladeDown && Math.abs(speed) > 0.32 && !object.damaged) {
        object.damaged = true;
        object.group.rotation.z = hash2D(object.x, object.z, 73) > 0.5
          ? 0.24
          : -0.24;
        for (const patch of object.patches) patch.snow = 0;
        this.snowDirty = true;
        return { blocked: true, damagedId: object.id };
      }
      return { blocked: true };
    }
    return { blocked: false };
  }

  public getCleanRatio(): number {
    if (this.snowPatches.length === 0) return 1;
    const remaining = this.cleanables.reduce(
      (sum, object) =>
        sum +
        (object.damaged
          ? object.patches.length
          : object.patches.reduce(
              (objectSum, patch) => objectSum + patch.snow,
              0,
            )),
      0,
    );
    return clamp(1 - remaining / this.snowPatches.length, 0, 1);
  }

  public getStats(): {
    cleanableObjects: number;
    snowPatches: number;
    instancedProps: number;
    drawGroups: number;
    cleanRatio: number;
    damagedObjects: number;
  } {
    return {
      cleanableObjects: this.cleanables.length,
      snowPatches: this.snowPatches.length,
      instancedProps: this.instancedProps,
      drawGroups: this.instancedDrawGroups + this.heroMeshes + 1,
      cleanRatio: this.getCleanRatio(),
      damagedObjects: this.cleanables.filter((object) => object.damaged).length,
    };
  }

  /** Ground-drift shapes shared with buildings and editor-authored assets. */
  public listSnowObstacleDescriptors(): readonly SnowObstacleDescriptor[] {
    return [
      ...this.cleanables.map((object) => ({
        id: `park-cleanable:${object.id}`,
        owner: 'PARK' as const,
        x: object.x,
        z: object.z,
        width: object.radius * 2,
        depth: object.radius * 2,
        height: Math.max(0.55, object.radius * 2.1),
        porosity: 0.22,
        snowCatch: object.damaged ? 0.55 : 1,
      })),
      ...this.obstacles.map((obstacle, index) => ({
        id: `park-obstacle:${index}`,
        owner: 'PARK' as const,
        x: obstacle.x,
        z: obstacle.z,
        width: obstacle.radius * 2,
        depth: obstacle.radius * 2,
        height: Math.max(0.5, obstacle.radius * 1.8),
        porosity: 0.16,
        snowCatch: 0.9,
      })),
    ];
  }

  public writePerformanceTrace(target: {
    parkInstancedProps?: number;
    parkDrawGroups?: number;
    parkCleanRatio?: number;
  }): void {
    target.parkInstancedProps = this.instancedProps;
    target.parkDrawGroups =
      this.instancedDrawGroups + this.heroMeshes + 1;
    target.parkCleanRatio = this.getCleanRatio();
  }

  public importState(saved: unknown): boolean {
    if (!saved || typeof saved !== 'object') return false;
    const candidate = saved as Partial<ParkCleaningSaveData>;
    if (candidate.version !== 1 || !Array.isArray(candidate.objects)) {
      return false;
    }
    for (const savedObject of candidate.objects) {
      const object = this.cleanables.find((item) => item.id === savedObject.id);
      if (!object || !Array.isArray(savedObject.snow)) continue;
      for (let index = 0; index < object.patches.length; index += 1) {
        const encoded = savedObject.snow[index];
        if (!Number.isFinite(encoded)) continue;
        object.patches[index]!.snow = clamp(encoded / 255, 0, 1);
      }
      object.damaged = savedObject.damaged === true;
      object.group.rotation.z = object.damaged ? 0.24 : 0;
    }
    this.snowDirty = true;
    return true;
  }

  public exportState(): ParkCleaningSaveData {
    return {
      version: 1,
      objects: this.cleanables.map((object) => ({
        id: object.id,
        snow: object.patches.map((patch) => Math.round(patch.snow * 255)),
        ...(object.damaged ? { damaged: true } : {}),
      })),
    };
  }

  public dispose(): void {
    this.removeTerrainListener();
    this.root.removeFromParent();
    for (const geometry of this.geometries) geometry.dispose();
    for (const material of this.materials) material.dispose();
    this.geometries.clear();
    this.materials.clear();
  }

  private createScenery(): void {
    const trunk = this.material(0x6d5138, 0.95, 0);
    const evergreen = this.material(0x315d56, 0.92, 0);
    const evergreenSnow = this.material(0xe5f3f2, 0.97, 0);
    const shrub = this.material(0x55776d, 0.96, 0);
    const stone = this.material(0x718587, 0.94, 0.02);
    const metal = this.material(0x33484b, 0.7, 0.32);
    const warmGlass = this.material(
      0xffd888,
      0.28,
      0.02,
      0xffb34d,
      1.1,
    );
    const wood = this.material(0x8b6844, 0.87, 0.02);

    const trunks: InstanceTransform[] = [];
    const crowns: InstanceTransform[] = [];
    const crownSnow: InstanceTransform[] = [];
    for (let index = 0; index < 34; index += 1) {
      const angle = (index / 34) * Math.PI * 2;
      const radius = 10.5 + hash2D(index, 3, 911) * 4.5;
      const x = BOREALIS_PARK_CENTER.x + Math.cos(angle) * radius;
      const z = BOREALIS_PARK_CENTER.z + Math.sin(angle) * radius * 0.72;
      const height = 2.5 + hash2D(index, 7, 912) * 2.2;
      trunks.push({
        x,
        y: BOREALIS_GROUND_HEIGHT + height * 0.28,
        z,
        scaleX: 0.18 + height * 0.018,
        scaleY: height * 0.56,
        scaleZ: 0.18 + height * 0.018,
      });
      crowns.push({
        x,
        y: BOREALIS_GROUND_HEIGHT + height * 0.76,
        z,
        scaleX: 0.95 + height * 0.13,
        scaleY: height * 0.72,
        scaleZ: 0.95 + height * 0.13,
        rotation: angle * 0.37,
      });
      crownSnow.push({
        x,
        y: BOREALIS_GROUND_HEIGHT + height * 1.04,
        z,
        scaleX: 0.72 + height * 0.09,
        scaleY: height * 0.24,
        scaleZ: 0.72 + height * 0.09,
        rotation: angle * 0.37,
      });
      this.obstacles.push({ x, z, radius: 0.48 + height * 0.018 });
    }
    this.addInstances(
      'Borealis park tree trunks',
      new CylinderGeometry(1, 1.25, 1, 7),
      trunk,
      trunks,
    );
    this.addInstances(
      'Borealis park evergreen crowns',
      new ConeGeometry(1, 1, 8, 2),
      evergreen,
      crowns,
    );
    this.addInstances(
      'Borealis park evergreen snow caps',
      new ConeGeometry(1, 1, 8, 1),
      evergreenSnow,
      crownSnow,
    );

    const shrubs: InstanceTransform[] = [];
    const rocks: InstanceTransform[] = [];
    for (let index = 0; index < 42; index += 1) {
      const x = BOREALIS_PARK_CENTER.x - 11 + hash2D(index, 2, 230) * 22;
      const z = BOREALIS_PARK_CENTER.z - 8 + hash2D(index, 4, 231) * 16;
      const scale = 0.3 + hash2D(index, 5, 232) * 0.55;
      const isRock = index % 3 === 0;
      (isRock ? rocks : shrubs).push({
        x,
        y: BOREALIS_GROUND_HEIGHT + scale * 0.32,
        z,
        scaleX: scale,
        scaleY: scale * (index % 3 === 0 ? 0.52 : 0.72),
        scaleZ: scale * 0.86,
        rotation: hash2D(index, 8, 233) * Math.PI,
      });
      if (isRock) this.obstacles.push({ x, z, radius: scale * 0.58 });
    }
    this.addInstances(
      'Borealis park shrubs',
      new DodecahedronGeometry(1, 0),
      shrub,
      shrubs,
    );
    this.addInstances(
      'Borealis park rocks',
      new DodecahedronGeometry(1, 0),
      stone,
      rocks,
    );

    const lampPosts: InstanceTransform[] = [];
    const lampGlobes: InstanceTransform[] = [];
    for (let index = 0; index < 10; index += 1) {
      const side = index % 2 === 0 ? -1 : 1;
      const along = Math.floor(index / 2);
      const x = BOREALIS_PARK_CENTER.x - 7 + along * 3.5;
      const z = BOREALIS_PARK_CENTER.z + side * 3.7;
      lampPosts.push({
        x,
        y: BOREALIS_GROUND_HEIGHT + 1.45,
        z,
        scaleX: 0.07,
        scaleY: 2.9,
        scaleZ: 0.07,
      });
      lampGlobes.push({
        x,
        y: BOREALIS_GROUND_HEIGHT + 2.95,
        z,
        scaleX: 0.18,
        scaleY: 0.22,
        scaleZ: 0.18,
      });
      if (index === 2 || index === 7) {
        const light = new PointLight(0xffd38a, 0, 10, 2);
        light.position.set(x, BOREALIS_GROUND_HEIGHT + 2.85, z);
        light.name = 'Borealis park practical lamp';
        this.lights.push(light);
        this.root.add(light);
      }
      this.obstacles.push({ x, z, radius: 0.2 });
    }
    this.addInstances(
      'Borealis park lamp posts',
      new CylinderGeometry(1, 1, 1, 8),
      metal,
      lampPosts,
    );
    this.addInstances(
      'Borealis park lamp globes',
      new SphereGeometry(1, 8, 6),
      warmGlass,
      lampGlobes,
    );

    const fence: InstanceTransform[] = [];
    for (let index = 0; index < 18; index += 1) {
      const x = BOREALIS_PARK_CENTER.x - 9 + index;
      const z = BOREALIS_PARK_CENTER.z + 7.2;
      fence.push({
        x,
        y: BOREALIS_GROUND_HEIGHT + 0.62,
        z,
        scaleX: 0.1,
        scaleY: 1.24,
        scaleZ: 0.1,
      });
      this.obstacles.push({ x, z, radius: 0.22 });
      if (index < 17) {
        fence.push({
          x: x + 0.5,
          y: BOREALIS_GROUND_HEIGHT + 0.76,
          z,
          scaleX: 1,
          scaleY: 0.08,
          scaleZ: 0.08,
        });
      }
    }
    this.addInstances(
      'Borealis park wooden fence',
      new BoxGeometry(1, 1, 1),
      wood,
      fence,
    );
  }

  private createCleanableObjects(): void {
    this.createBench('park-bench-east', 'East park bench', -54.5, -3.3, 0.15);
    this.createBench('park-bench-west', 'West park bench', -63.2, -7.2, -0.25);
    this.createBin('park-litter-bin', 'Park litter bin', -57.2, -6.2);
    this.createStatue('park-penguin-statue', 'Old penguin statue', -60.4, -10.2);
    this.createFountain('park-fountain', 'Frozen park fountain', -66.2, -2.8);
  }

  private createBench(
    id: string,
    displayName: string,
    x: number,
    z: number,
    rotation: number,
  ): void {
    const group = new Group();
    group.position.set(x, BOREALIS_GROUND_HEIGHT, z);
    group.rotation.y = rotation;
    const wood = this.material(0x9b7549, 0.88, 0.03);
    const metal = this.material(0x34484b, 0.72, 0.34);
    for (const y of [0.56, 0.83, 1.04]) {
      const slat = this.mesh(new BoxGeometry(2.2, 0.11, 0.16), wood);
      slat.position.set(0, y, y > 0.7 ? -0.38 : 0);
      group.add(slat);
    }
    for (const side of [-0.83, 0.83]) {
      const leg = this.mesh(new BoxGeometry(0.12, 0.72, 0.12), metal);
      leg.position.set(side, 0.34, 0);
      group.add(leg);
    }
    this.root.add(group);
    this.registerCleanable(id, displayName, x, z, 1.25, group, [
      [-0.85, 0.72, 0],
      [-0.42, 0.78, 0],
      [0, 0.8, 0],
      [0.42, 0.78, 0],
      [0.85, 0.72, 0],
      [-0.78, 1.12, -0.38],
      [-0.25, 1.16, -0.38],
      [0.25, 1.16, -0.38],
      [0.78, 1.12, -0.38],
      [0, 1.34, -0.34],
    ], rotation);
  }

  private createBin(id: string, displayName: string, x: number, z: number): void {
    const group = new Group();
    group.position.set(x, BOREALIS_GROUND_HEIGHT, z);
    const metal = this.material(0x3f6964, 0.78, 0.2);
    const body = this.mesh(new CylinderGeometry(0.42, 0.35, 0.92, 10), metal);
    body.position.y = 0.46;
    group.add(body);
    const lid = this.mesh(new CylinderGeometry(0.47, 0.47, 0.12, 10), metal);
    lid.position.y = 0.96;
    group.add(lid);
    this.root.add(group);
    this.registerCleanable(id, displayName, x, z, 0.48, group, [
      ...Array.from({ length: 8 }, (_, index) => {
        const angle = index / 8 * Math.PI * 2;
        return [Math.cos(angle) * 0.3, 0.72, Math.sin(angle) * 0.3] as const;
      }),
      [0, 1.08, 0],
      [0.15, 1.16, -0.08],
    ]);
  }

  private createStatue(id: string, displayName: string, x: number, z: number): void {
    const group = new Group();
    group.position.set(x, BOREALIS_GROUND_HEIGHT, z);
    const stone = this.material(0x829496, 0.91, 0.03);
    const base = this.mesh(new CylinderGeometry(0.75, 0.92, 0.55, 10), stone);
    base.position.y = 0.28;
    const body = this.mesh(new SphereGeometry(0.62, 10, 8), stone);
    body.scale.y = 1.35;
    body.position.y = 1.08;
    const head = this.mesh(new SphereGeometry(0.38, 10, 8), stone);
    head.position.y = 1.76;
    const beak = this.mesh(new ConeGeometry(0.19, 0.45, 6), stone);
    beak.rotation.x = Math.PI / 2;
    beak.position.set(0, 1.73, 0.42);
    group.add(base, body, head, beak);
    this.root.add(group);
    this.registerCleanable(id, displayName, x, z, 0.82, group, [
      [-0.45, 0.45, 0], [0.45, 0.45, 0], [0, 0.68, 0.35],
      [-0.38, 1.12, 0], [0.38, 1.12, 0], [0, 1.28, 0.32],
      [-0.28, 1.7, 0], [0.28, 1.7, 0], [0, 1.92, 0], [0, 1.7, 0.38],
    ]);
  }

  private createFountain(id: string, displayName: string, x: number, z: number): void {
    const group = new Group();
    group.position.set(x, BOREALIS_GROUND_HEIGHT, z);
    const stone = this.material(0x70868a, 0.88, 0.05);
    const ice = this.material(0x8fd5df, 0.25, 0.08, 0x2b8796, 0.22);
    const bowl = this.mesh(new TorusGeometry(1.45, 0.22, 8, 18), stone);
    bowl.rotation.x = Math.PI / 2;
    bowl.position.y = 0.45;
    const pool = this.mesh(new CylinderGeometry(1.25, 1.25, 0.12, 18), ice);
    pool.position.y = 0.42;
    const pillar = this.mesh(new CylinderGeometry(0.25, 0.38, 1.35, 10), stone);
    pillar.position.y = 1.05;
    const cap = this.mesh(new SphereGeometry(0.38, 10, 7), ice);
    cap.position.y = 1.72;
    group.add(bowl, pool, pillar, cap);
    this.root.add(group);
    this.registerCleanable(id, displayName, x, z, 1.6, group, [
      [-1.1, 0.58, 0], [-0.55, 0.65, 0.85], [0.55, 0.65, 0.85],
      [1.1, 0.58, 0], [0.55, 0.65, -0.85], [-0.55, 0.65, -0.85],
      [0, 0.78, 0], [0, 1.18, 0], [0, 1.62, 0], [0, 1.92, 0],
    ]);
  }

  private registerCleanable(
    id: string,
    displayName: string,
    x: number,
    z: number,
    radius: number,
    group: Group,
    offsets: readonly (readonly [number, number, number])[],
    rotation = 0,
  ): void {
    const patches: SnowPatch[] = [];
    const cosine = Math.cos(rotation);
    const sine = Math.sin(rotation);
    for (let index = 0; index < SNOW_PATCH_COUNT_PER_OBJECT; index += 1) {
      const offset = offsets[index] ?? [0, 0.5, 0];
      const localX = offset[0];
      const localZ = offset[2];
      const patch: SnowPatch = {
        objectId: id,
        x: x + localX * cosine + localZ * sine,
        y: BOREALIS_GROUND_HEIGHT + offset[1],
        z: z - localX * sine + localZ * cosine,
        scaleX: 0.46 + hash2D(index, id.length, 771) * 0.22,
        scaleY: 0.34 + hash2D(index, id.length, 772) * 0.18,
        scaleZ: 0.43 + hash2D(index, id.length, 773) * 0.24,
        rotation: hash2D(index, id.length, 774) * Math.PI,
        snow: 1,
      };
      patches.push(patch);
      this.snowPatches.push(patch);
    }
    this.cleanables.push({
      id,
      displayName,
      x,
      z,
      radius,
      group,
      patches,
      damaged: false,
    });
  }

  private updateSnowInstances(): void {
    const hiddenMatrix = new Matrix4().makeTranslation(0, -100, 0);
    for (let index = 0; index < this.snowPatches.length; index += 1) {
      const patch = this.snowPatches[index]!;
      if (patch.snow <= 0.006) {
        this.snowMesh.setMatrixAt(index, hiddenMatrix);
        continue;
      }
      const visibleScale = 0.12 + patch.snow * 0.88;
      this.transform.position.set(
        patch.x,
        patch.y - (1 - patch.snow) * patch.scaleY * 0.45,
        patch.z,
      );
      this.transform.rotation.set(0, patch.rotation, 0);
      this.transform.scale.set(
        patch.scaleX * visibleScale,
        patch.scaleY * Math.max(0.06, patch.snow),
        patch.scaleZ * visibleScale,
      );
      this.transform.updateMatrix();
      this.snowMesh.setMatrixAt(index, this.transform.matrix);
    }
    this.snowMesh.instanceMatrix.needsUpdate = true;
    this.snowDirty = false;
  }

  private addInstances(
    name: string,
    geometry: BufferGeometry,
    material: MeshStandardMaterial,
    instances: readonly InstanceTransform[],
  ): void {
    this.instancedProps += instances.length;
    this.instancedDrawGroups += 1;
    this.geometry(geometry);
    const mesh = new InstancedMesh(geometry, material, instances.length);
    mesh.name = name;
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    const quaternion = new Quaternion();
    const position = new Vector3();
    const scale = new Vector3();
    const matrix = new Matrix4();
    for (let index = 0; index < instances.length; index += 1) {
      const instance = instances[index]!;
      position.set(instance.x, instance.y, instance.z);
      quaternion.setFromAxisAngle(
        new Vector3(0, 1, 0),
        instance.rotation ?? 0,
      );
      scale.set(instance.scaleX, instance.scaleY, instance.scaleZ);
      matrix.compose(position, quaternion, scale);
      mesh.setMatrixAt(index, matrix);
    }
    mesh.instanceMatrix.needsUpdate = true;
    this.root.add(mesh);
  }

  private mesh(geometry: BufferGeometry, material: MeshStandardMaterial): Mesh {
    this.geometry(geometry);
    this.heroMeshes += 1;
    const mesh = new Mesh(geometry, material);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    return mesh;
  }

  private geometry<T extends BufferGeometry>(geometry: T): T {
    this.geometries.add(geometry);
    return geometry;
  }

  private material(
    color: number,
    roughness: number,
    metalness: number,
    emissive = 0,
    emissiveIntensity = 0,
  ): MeshStandardMaterial {
    const material = new MeshStandardMaterial({
      color: new Color(color),
      roughness,
      metalness,
      emissive: new Color(emissive),
      emissiveIntensity,
    });
    this.materials.add(material);
    return material;
  }

  private applyLightState(): void {
    const strength = this.visible
      ? clamp((this.night - 0.18) / 0.72, 0, 1)
      : 0;
    for (const light of this.lights) {
      light.intensity = strength * 16;
      light.visible = strength > 0.01;
    }
  }
}
