export type WildernessRuneEffectKind =
  | 'WARD'
  | 'WIND_SHELTER'
  | 'HEAT'
  | 'FIRE_LINE'
  | 'LIGHT'
  | 'BEACON'
  | 'ALARM'
  | 'THAW'
