export interface WildernessRuneOffering {
  readonly inventory: keyof WildernessInventory;
  readonly amount: number;
  readonly label: string;
}

export interface WildernessRuneDefinition {
  readonly id: WildernessRuneId;
  readonly name: string;
  readonly icon: string;
  readonly description: string;
  readonly family: 'PROTECTION' | 'UTILITY' | 'HEARTH' | 'WILDERNESS';
  readonly color: number;
  readonly effect: WildernessRuneEffectKind;
  readonly radius: number;
  readonly durationSeconds: number;
  readonly strength: number;
  readonly offering: readonly WildernessRuneOffering[];
  /** Local two-dimensional guide, in metres, starting at the player. */
  readonly template: readonly (readonly [number, number])[];
  readonly implemented: boolean;
}

const circle = (radius: number, points = 17): readonly (readonly [number, number])[] =>
  Array.from({ length: points }, (_, index) => {
    const angle = index / (points - 1) * Math.PI * 2;
    return [Math.sin(angle) * radius, radius - Math.cos(angle) * radius] as const;
  });

const gate = (radius: number): readonly (readonly [number, number])[] =>
  Array.from({ length: 13 }, (_, index) => {
    const angle = -Math.PI * 0.5 + index / 12 * Math.PI;
    return [Math.sin(angle) * radius + radius, Math.cos(angle) * radius] as const;
  });

const triangle: readonly (readonly [number, number])[] = [
  [0, 0], [1.35, 2.25], [-1.35, 2.25], [0, 0],
];

