import { ICEWAY_PLAYTEST_MODE } from '../../core/RuntimeBuildFlags';
import { generatedWorldData, generatedWorldStats } from './GeneratedWorldRuntime';
import type { GeneratedWorldLayer } from './GeneratedWorldTypes';

const LAYERS: readonly GeneratedWorldLayer[] = [
  'FINAL',
  'HEIGHT',
  'WATER',
  'MOISTURE',
  'FOREST',
  'ROCKINESS',
  'FUEL',
];

const downloadBlob = (name: string, blob: Blob): void => {
  const link = document.createElement('a');
  link.download = name;
  link.href = URL.createObjectURL(blob);
  link.click();
  window.setTimeout(() => URL.revokeObjectURL(link.href), 1_000);
};

export class WorldGenerationLab {
  private readonly element = document.createElement('aside');
  private open = false;

  public constructor(
    root: HTMLElement,
    private readonly setLayer: (layer: GeneratedWorldLayer) => void,
    initialLayer: GeneratedWorldLayer,
  ) {
    const stats = generatedWorldStats();
    const data = generatedWorldData();
    const heightRange = data
      ? Math.max(...data.elevation) - Math.min(...data.elevation)
      : 0;
    this.element.className = 'world-generation-lab is-hidden';
    this.element.setAttribute('aria-label', 'World Generation Lab');
    this.element.innerHTML = `
      <header>
        <div><small>THE LONG WINTER · DEV</small><strong>WORLD GENERATION LAB</strong></div>
        <button type="button" data-worldgen-action="close" aria-label="Close">×</button>
      </header>
      <p class="worldgen-summary">
        Seeded macro terrain, erosion, catchments and ecology masks. Editor
        deltas, snow, ice, fire and authored assets remain separate layers.
      </p>
      <dl>
        <div><dt>SEED</dt><dd>${stats.seed}</dd></div>
        <div><dt>GRID</dt><dd>${stats.width} × ${stats.height} · ${stats.cellSizeMetres} m</dd></div>
        <div><dt>BUILD</dt><dd>${stats.generationMilliseconds.toFixed(1)} ms</dd></div>
        <div><dt>RELIEF</dt><dd>${heightRange.toFixed(1)} m</dd></div>
        <div><dt>WATER</dt><dd>${stats.riverCells} river · ${stats.lakeCells} lake cells</dd></div>
      </dl>
      <label>
        <span>WORLD SEED</span>
        <input type="number" step="1" value="${stats.seed}" data-worldgen-seed />
      </label>
      <div class="worldgen-layer-grid" role="group" aria-label="Generated data view">
        ${LAYERS.map((layer) => `
          <button type="button" data-worldgen-layer="${layer}" aria-pressed="${String(layer === initialLayer)}">${layer}</button>
        `).join('')}
      </div>
      <div class="worldgen-actions">
        <button type="button" data-worldgen-action="apply-seed">RELOAD SEED</button>
        <button type="button" data-worldgen-action="download-layer">DOWNLOAD VIEW PNG</button>
        <button type="button" data-worldgen-action="download-manifest">DOWNLOAD MANIFEST</button>
        <button type="button" data-worldgen-action="legacy">OPEN LEGACY WORLD</button>
      </div>
      <footer>
        <span>World Builder edits stay sparse 2 m deltas. Use <code>?worldgen=off</code> for instant rollback.</span>
      </footer>
    `;
    root.appendChild(this.element);
    this.element.addEventListener('click', (event) => {
      const target = event.target instanceof Element ? event.target : undefined;
      const layer = target?.closest<HTMLElement>('[data-worldgen-layer]')
        ?.dataset.worldgenLayer as GeneratedWorldLayer | undefined;
      if (layer && LAYERS.includes(layer)) {
        this.setLayer(layer);
        for (const button of this.element.querySelectorAll<HTMLElement>('[data-worldgen-layer]')) {
          button.setAttribute('aria-pressed', String(button.dataset.worldgenLayer === layer));
        }
        return;
      }
      const action = target?.closest<HTMLElement>('[data-worldgen-action]')
        ?.dataset.worldgenAction;
      if (action === 'close') this.setOpen(false);
      else if (action === 'apply-seed') this.reloadWithSeed();
      else if (action === 'legacy') this.openLegacyWorld();
      else if (action === 'download-layer') this.downloadCurrentLayer();
      else if (action === 'download-manifest') this.downloadManifest();
    });
  }

  public toggle(): void {
    if (!ICEWAY_PLAYTEST_MODE) return;
    this.setOpen(!this.open);
  }

  public setOpen(open: boolean): void {
    this.open = open && ICEWAY_PLAYTEST_MODE;
    this.element.classList.toggle('is-hidden', !this.open);
  }

  public dispose(): void {
    this.element.remove();
  }

  private reloadWithSeed(): void {
    const input = this.element.querySelector<HTMLInputElement>('[data-worldgen-seed]');
    const seed = Math.trunc(Number(input?.value));
    if (!Number.isFinite(seed)) return;
    const url = new URL(window.location.href);
    url.searchParams.set('worldgen', 'on');
    url.searchParams.set('worldSeed', String(seed));
    window.location.assign(url);
  }

  private openLegacyWorld(): void {
    const url = new URL(window.location.href);
    url.searchParams.set('worldgen', 'off');
    window.location.assign(url);
  }

  private selectedLayer(): GeneratedWorldLayer {
    const selected = this.element.querySelector<HTMLElement>(
      '[data-worldgen-layer][aria-pressed="true"]',
    )?.dataset.worldgenLayer as GeneratedWorldLayer | undefined;
    return selected ?? 'FINAL';
  }

  private downloadCurrentLayer(): void {
    const data = generatedWorldData();
    if (!data) return;
    const layer = this.selectedLayer();
    const canvas = document.createElement('canvas');
    canvas.width = data.width;
    canvas.height = data.height;
    const context = canvas.getContext('2d');
    if (!context) return;
    const image = context.createImageData(data.width, data.height);
    const minimumHeight = Math.min(...data.elevation);
    const maximumHeight = Math.max(...data.elevation);
    const heightRange = Math.max(0.001, maximumHeight - minimumHeight);
    const mask = layer === 'WATER'
      ? undefined
      : layer === 'MOISTURE'
        ? data.moisture
        : layer === 'FOREST'
          ? data.forest
          : layer === 'ROCKINESS'
            ? data.rockiness
            : layer === 'FUEL'
              ? data.fuel
              : undefined;
    for (let index = 0; index < data.elevation.length; index += 1) {
      const offset = index * 4;
      let red = 0;
      let green = 0;
      let blue = 0;
      if (layer === 'WATER') {
        red = data.lake[index] ?? 0;
        green = data.river[index] ?? 0;
        blue = Math.max(red, green);
      } else {
        const value = mask
          ? mask[index] ?? 0
          : Math.round((data.elevation[index]! - minimumHeight) / heightRange * 255);
        red = value;
        green = value;
        blue = value;
      }
      image.data[offset] = red;
      image.data[offset + 1] = green;
      image.data[offset + 2] = blue;
      image.data[offset + 3] = 255;
    }
    context.putImageData(image, 0, 0);
    canvas.toBlob((blob) => {
      if (blob) downloadBlob(`iceway-worldgen-${data.config.seed}-${layer.toLowerCase()}.png`, blob);
    }, 'image/png');
  }

  private downloadManifest(): void {
    const data = generatedWorldData();
    if (!data) return;
    const stats = generatedWorldStats();
    downloadBlob(
      `iceway-worldgen-${data.config.seed}-manifest.json`,
      new Blob([JSON.stringify({
        version: 1,
        config: data.config,
        width: data.width,
        height: data.height,
        layers: {
          height: '16-bit PNG / float source in the offline compiler',
          water: 'R=lake, G=river, B=combined',
          moisture: '8-bit mask',
          forest: '8-bit density mask',
          rockiness: '8-bit density mask',
          fuel: '8-bit future fire-fuel mask',
        },
        stats,
      }, null, 2)], { type: 'application/json' }),
    );
  }
}
