import {
  ICEAWAY_PROTOTYPE_WORLD_ORIGIN,
} from '../PrototypeWorldPositionAdapter';
import { ICEAWAY_TARGET_WORLD_PARTITION } from '../WorldPartitionTypes';
import type { GeneratedWorldConfig } from './GeneratedWorldTypes';

const partition = ICEAWAY_TARGET_WORLD_PARTITION;
const originAbsoluteX =
  ICEAWAY_PROTOTYPE_WORLD_ORIGIN.chunk.x * partition.chunkSizeMetres +
  ICEAWAY_PROTOTYPE_WORLD_ORIGIN.local.xMetres;
const originAbsoluteZ =
  ICEAWAY_PROTOTYPE_WORLD_ORIGIN.chunk.z * partition.chunkSizeMetres +
  ICEAWAY_PROTOTYPE_WORLD_ORIGIN.local.zMetres;

/** Complete partition in prototype-local metres, used by isolated authoring. */
export const WORLD_AUTHORING_BOUNDS = Object.freeze({
  minX:
    partition.minimumChunk.x * partition.chunkSizeMetres - originAbsoluteX,
  maxX:
    (partition.minimumChunk.x + partition.chunkColumns) *
      partition.chunkSizeMetres -
    originAbsoluteX,
  minZ:
    partition.minimumChunk.z * partition.chunkSizeMetres - originAbsoluteZ,
  maxZ:
    (partition.minimumChunk.z + partition.chunkRows) *
      partition.chunkSizeMetres -
      originAbsoluteZ,
});

/** Western mainland only. Borealis coast remains an authored transition. */
export const GENERATED_WORLD_BOUNDS = Object.freeze({
  ...WORLD_AUTHORING_BOUNDS,
  maxX: -64,
});

export const DEFAULT_GENERATED_WORLD_SEED = 34711;

export const generatedWorldConfig = (
  seed = DEFAULT_GENERATED_WORLD_SEED,
): GeneratedWorldConfig => ({
  version: 1,
  seed: Math.trunc(Number.isFinite(seed) ? seed : DEFAULT_GENERATED_WORLD_SEED),
  bounds: GENERATED_WORLD_BOUNDS,
  // Macro data stays compact. The canonical 2 m terrain and 25/12.5/6.25 cm
  // snow fields interpolate and refine this layer only where they are active.
  cellSizeMetres: 16,
  seaLevelMetres: 0.31,
  thermalErosionPasses: 7,
  hydraulicErosionPasses: 3,
  riverAccumulationThreshold: 54,
});
