import { clamp, hash2D, smoothstep, valueNoise2D } from '../utils/math';
import { winterRouteSnowDepressionAt } from '../world/WinterWorldRoutes';
import { isBorealisLand } from './BorealisLand';
import { wildernessSnowTopographicFill } from '../survival/WildernessBiome';

export const LAND_SNOW_TILE_SIZE = 16;
/** Snow V3 gameplay lattice: one authoritative sample every 25 centimetres. */
export const LAND_SNOW_SEGMENTS = 64;
export const LAND_SNOW_SPACING = LAND_SNOW_TILE_SIZE / LAND_SNOW_SEGMENTS;
export const LAND_SNOW_SAMPLES = LAND_SNOW_SEGMENTS + 1;
export const LAND_SNOW_SAMPLE_COUNT = LAND_SNOW_SAMPLES * LAND_SNOW_SAMPLES;
export const LEGACY_LAND_SNOW_SEGMENTS = 32;
export const LEGACY_LAND_SNOW_SPACING =
  LAND_SNOW_TILE_SIZE / LEGACY_LAND_SNOW_SEGMENTS;
export const LEGACY_LAND_SNOW_SAMPLES = LEGACY_LAND_SNOW_SEGMENTS + 1;
export const LEGACY_LAND_SNOW_SAMPLE_COUNT =
  LEGACY_LAND_SNOW_SAMPLES * LEGACY_LAND_SNOW_SAMPLES;
export const LEGACY_MAXIMUM_SNOW_DEPTH = 2.2;
export const MAXIMUM_SNOW_DEPTH = 6;
export const LEGACY_LAND_SNOW_BASELINE_ID = 'borealis-snow-v1';
export const LEGACY_LAND_SNOW_FORMAT_VERSION = 1;
export const LAND_SNOW_BASELINE_ID = 'borealis-snow-v2-25cm';
export const LAND_SNOW_FORMAT_VERSION = 2;

/** Quantized sparse snow sample shared by saves, authority and wire codecs. */
export type PackedSnowSample = readonly [
  sampleIndex: number,
  encodedDepth: number,
  encodedCompaction: number,
];

export const landSnowTileKey = (tileX: number, tileZ: number): string =>
  `${tileX},${tileZ}`;

export const landSnowSampleIndex = (column: number, row: number): number =>
  row * LAND_SNOW_SAMPLES + column;

export const landSnowCellPattern = (x: number, z: number): number => {
  const scale = 1 / 3.2;
  const sampleX = x * scale;
  const sampleZ = z * scale;
  const cellX = Math.floor(sampleX);
  const cellZ = Math.floor(sampleZ);
  let nearest = Number.POSITIVE_INFINITY;
  let secondNearest = Number.POSITIVE_INFINITY;
  for (let offsetZ = -1; offsetZ <= 1; offsetZ += 1) {
    for (let offsetX = -1; offsetX <= 1; offsetX += 1) {
      const candidateX = cellX + offsetX;
      const candidateZ = cellZ + offsetZ;
      const featureX =
        candidateX + hash2D(candidateX, candidateZ, 5227) * 0.76 + 0.12;
      const featureZ =
        candidateZ + hash2D(candidateX, candidateZ, 9403) * 0.76 + 0.12;
      const distance = Math.hypot(sampleX - featureX, sampleZ - featureZ);
      if (distance < nearest) {
        secondNearest = nearest;
        nearest = distance;
      } else if (distance < secondNearest) {
        secondNearest = distance;
      }
    }
  }
  return smoothstep(0.04, 0.42, secondNearest - nearest);
};

export const initialLandSnowDepth = (
  x: number,
  z: number,
  cachedCellular?: number,
): number => {
  if (!isBorealisLand(x, z)) return 0;
  const cellular = cachedCellular ?? landSnowCellPattern(x, z);
  const broad = valueNoise2D(x * 0.115, z * 0.115, 7713);
  const detail = valueNoise2D(x * 0.31, z * 0.31, 1709);
  const windDrift =
    Math.sin(x * 0.115 + z * 0.038) * 0.072 +
    Math.sin(x * 0.037 - z * 0.061 + 1.7) * 0.046;
  const topographicFill = wildernessSnowTopographicFill(x, z);
  const routeDepression = winterRouteSnowDepressionAt(x, z);
  return clamp(
    0.4 + broad * 0.25 + detail * 0.075 +
      // Cellular structure should break the silhouette, never draw a visible
      // Voronoi net across a flat field.
      (cellular - 0.5) * 0.012 + windDrift + topographicFill -
      routeDepression,
    0.27,
    1.28,
  );
};

export const encodeLandSnowDepth = (depth: number): number =>
  Math.round(clamp(depth / MAXIMUM_SNOW_DEPTH, 0, 1) * 65535);

export const decodeLandSnowDepth = (value: number): number =>
  clamp(value, 0, 65535) / 65535 * MAXIMUM_SNOW_DEPTH;

export const decodeLegacyLandSnowDepth = (value: number): number =>
  clamp(value, 0, 255) / 255 * LEGACY_MAXIMUM_SNOW_DEPTH;

export const encodeLandSnowUnit = (value: number): number =>
  Math.round(clamp(value, 0, 1) * 255);

export const decodeLandSnowUnit = (value: number): number =>
  clamp(value, 0, 255) / 255;

/**
 * Refines a sparse 50 cm Snow V1/V2 tile to the Snow V3 25 cm lattice.
 * Bilinear subdivision preserves the integral of the old piecewise-linear
 * surface, while comparing against the new deterministic baseline keeps the
 * result sparse. This is intentionally shared by browser saves and the
 * headless multiplayer authority so both sides migrate identically.
 */
export const refineLegacyLandSnowChanges = (
  tileX: number,
  tileZ: number,
  changes: readonly (readonly [number, number, number])[],
  legacyDepthEncoding: 'U8' | 'U16' = 'U16',
): readonly PackedSnowSample[] => {
  const oldDepth = new Float32Array(LEGACY_LAND_SNOW_SAMPLE_COUNT);
  const oldCompaction = new Float32Array(LEGACY_LAND_SNOW_SAMPLE_COUNT);
  const changedOldIndices = new Set<number>();
  for (let row = 0; row < LEGACY_LAND_SNOW_SAMPLES; row += 1) {
    for (let column = 0; column < LEGACY_LAND_SNOW_SAMPLES; column += 1) {
      const index = row * LEGACY_LAND_SNOW_SAMPLES + column;
      oldDepth[index] = initialLandSnowDepth(
        tileX * LAND_SNOW_TILE_SIZE + column * LEGACY_LAND_SNOW_SPACING,
        tileZ * LAND_SNOW_TILE_SIZE + row * LEGACY_LAND_SNOW_SPACING,
      );
    }
  }
  for (const [index, encodedDepth, encodedCompaction] of changes) {
    if (
      !Number.isInteger(index) ||
      index < 0 ||
      index >= LEGACY_LAND_SNOW_SAMPLE_COUNT ||
      !Number.isFinite(encodedDepth) ||
      !Number.isFinite(encodedCompaction)
    ) continue;
    oldDepth[index] = legacyDepthEncoding === 'U8'
      ? decodeLegacyLandSnowDepth(encodedDepth)
      : decodeLandSnowDepth(encodedDepth);
    oldCompaction[index] = decodeLandSnowUnit(encodedCompaction);
    changedOldIndices.add(index);
  }

  const refined: PackedSnowSample[] = [];
  const sampleOld = (
    values: Float32Array,
    column: number,
    row: number,
  ): number => values[row * LEGACY_LAND_SNOW_SAMPLES + column] ?? 0;
  for (let row = 0; row < LAND_SNOW_SAMPLES; row += 1) {
    const oldRow = row * 0.5;
    const row0 = Math.floor(oldRow);
    const row1 = Math.min(LEGACY_LAND_SNOW_SEGMENTS, row0 + 1);
    const mixZ = oldRow - row0;
    for (let column = 0; column < LAND_SNOW_SAMPLES; column += 1) {
      const oldColumn = column * 0.5;
      const column0 = Math.floor(oldColumn);
      const column1 = Math.min(LEGACY_LAND_SNOW_SEGMENTS, column0 + 1);
      const mixX = oldColumn - column0;
      const cornerIndices = [
        row0 * LEGACY_LAND_SNOW_SAMPLES + column0,
        row0 * LEGACY_LAND_SNOW_SAMPLES + column1,
        row1 * LEGACY_LAND_SNOW_SAMPLES + column0,
        row1 * LEGACY_LAND_SNOW_SAMPLES + column1,
      ];
      if (!cornerIndices.some((index) => changedOldIndices.has(index))) continue;
      const interpolate = (values: Float32Array): number => {
        const top = sampleOld(values, column0, row0) * (1 - mixX) +
          sampleOld(values, column1, row0) * mixX;
        const bottom = sampleOld(values, column0, row1) * (1 - mixX) +
          sampleOld(values, column1, row1) * mixX;
        return top * (1 - mixZ) + bottom * mixZ;
      };
      const depth = interpolate(oldDepth);
      const compaction = interpolate(oldCompaction);
      const x = tileX * LAND_SNOW_TILE_SIZE + column * LAND_SNOW_SPACING;
      const z = tileZ * LAND_SNOW_TILE_SIZE + row * LAND_SNOW_SPACING;
      const encodedDepth = encodeLandSnowDepth(depth);
      const encodedCompaction = encodeLandSnowUnit(compaction);
      if (
        encodedDepth === encodeLandSnowDepth(initialLandSnowDepth(x, z)) &&
        encodedCompaction === 0
      ) continue;
      refined.push([
        landSnowSampleIndex(column, row),
        encodedDepth,
        encodedCompaction,
      ]);
    }
  }
  return refined;
};

export const visualLandSnowHeight = (
  depth: number,
  compaction: number,
): number =>
  depth * (0.62 - compaction * 0.085) +
  Math.max(0, depth - 0.9) * smoothstep(0.8, 1.35, depth) * 0.45;
