import {
  type JsonValue,
  type ServerTick,
  type SessionEpoch,
  type SessionId,
  type StreamSequence,
  isJsonValue,
  serverTick,
  sessionEpoch,
  sessionId,
  streamSequence,
} from '../core/NetworkPrimitives';

export const ICEWAY_PROTOCOL_VERSION = Object.freeze({ major: 1, minor: 0 });

export interface ProtocolVersion {
  major: number;
  minor: number;
}

export type NetworkDeliveryClass =
  | 'LATEST_SEQUENCED'
  | 'RELIABLE_ORDERED'
  | 'RELIABLE_IDEMPOTENT'
  | 'CONTROL'
  | 'BASELINE_STREAM';

export type CoreNetworkMessageType =
  | 'CLIENT_HELLO'
  | 'SERVER_HELLO'
  | 'JOIN_ACCEPTED'
  | 'JOIN_REJECTED'
  | 'CLOCK_PING'
  | 'CLOCK_PONG'
  | 'SESSION_POLICY'
  | 'PLAYER_COMMAND_BATCH'
  | 'RELIABLE_AUTHORITY_OPERATION'
  | 'COMMAND_RECEIPT'
  | 'TRANSACTION_RESULT'
  | 'CONTROL_LEASE_CHANGED'
  | 'ENTITY_SNAPSHOT_BATCH'
  | 'ENTITY_RELIABLE_DELTA'
  | 'BASELINE_MANIFEST'
  | 'BASELINE_COMPLETE'
  | 'SNOW_TILE_BASELINE'
  | 'SNOW_TILE_DELTA'
  | 'SNOW_TILE_RESYNC_REQUEST'
  | 'ICE_CHUNK_BASELINE'
  | 'ICE_CHUNK_DELTA'
  | 'ICE_CHUNK_RESYNC_REQUEST'
  | 'ICE_FLOE_BASELINE'
  | 'ICE_FLOE_LIFECYCLE'
  | 'ICE_FLOE_MOVEMENT'
  | 'ICE_FRACTURE_VISUAL'
  | 'WORLD_STATE_BASELINE'
  | 'WORLD_STATE_DELTA'
