  SERVER_HELLO: 'CONTROL',
  JOIN_ACCEPTED: 'CONTROL',
  JOIN_REJECTED: 'CONTROL',
  CLOCK_PING: 'CONTROL',
  CLOCK_PONG: 'CONTROL',
  SESSION_POLICY: 'RELIABLE_ORDERED',
  PLAYER_COMMAND_BATCH: 'LATEST_SEQUENCED',
  RELIABLE_AUTHORITY_OPERATION: 'RELIABLE_IDEMPOTENT',
  COMMAND_RECEIPT: 'LATEST_SEQUENCED',
  TRANSACTION_RESULT: 'RELIABLE_IDEMPOTENT',
  CONTROL_LEASE_CHANGED: 'RELIABLE_ORDERED',
  ENTITY_SNAPSHOT_BATCH: 'LATEST_SEQUENCED',
  ENTITY_RELIABLE_DELTA: 'RELIABLE_ORDERED',
  BASELINE_MANIFEST: 'BASELINE_STREAM',
  BASELINE_COMPLETE: 'BASELINE_STREAM',
  SNOW_TILE_BASELINE: 'BASELINE_STREAM',
  SNOW_TILE_DELTA: 'RELIABLE_ORDERED',
  SNOW_TILE_RESYNC_REQUEST: 'RELIABLE_IDEMPOTENT',
  ICE_CHUNK_BASELINE: 'BASELINE_STREAM',
  ICE_CHUNK_DELTA: 'RELIABLE_ORDERED',
  ICE_CHUNK_RESYNC_REQUEST: 'RELIABLE_IDEMPOTENT',
  ICE_FLOE_BASELINE: 'BASELINE_STREAM',
  ICE_FLOE_LIFECYCLE: 'RELIABLE_ORDERED',
  ICE_FLOE_MOVEMENT: 'LATEST_SEQUENCED',
