  WORLD_EVENT_RESYNC_REQUEST: 'RELIABLE_IDEMPOTENT',
  CONSTRUCTION_STATE_BASELINE: 'BASELINE_STREAM',
  CONSTRUCTION_STATE_DELTA: 'RELIABLE_ORDERED',
  CONSTRUCTION_STATE_RESYNC_REQUEST: 'RELIABLE_IDEMPOTENT',
  INVENTORY_STATE_BASELINE: 'BASELINE_STREAM',
  INVENTORY_STATE_DELTA: 'RELIABLE_ORDERED',
  INVENTORY_STATE_RESYNC_REQUEST: 'RELIABLE_IDEMPOTENT',
