import {
  BufferGeometry,
  Color,
  DoubleSide,
  Float32BufferAttribute,
  Group,
  Mesh,
  MeshBasicMaterial,
  MeshStandardMaterial,
  Scene,
} from 'three';
import {
  DEFAULT_ICE_VISUAL_PROFILE_ID,
  getIceVisualStyle,
  type IceMaterialDebugMode,
  type IceVisualProfileId,
  type IceVisualStyle,
} from '../ice/IceThicknessProfile';
import { hash2D } from '../utils/math';
import { WORLD } from '../world/WorldConfig';
import {
  getOrganicIceBoundaryOffset,
  getOrganicIceCornerOffset,
} from './IceSurfaceChunkRenderer';
import {
  castsIceEdgeShadow,
  ICE_SHADOW_CULL_HYSTERESIS,
  isInsideIceShadowRange,
  type IceShadowQualitySettings,
} from './IceShadowRendering';

export interface DetachedFloeRenderState {
  id: number;
  cells: readonly number[];
  centerX: number;
  centerZ: number;
  meanThickness: number;
  pressure: number;
  renderOffsetX: number;
  renderOffsetZ: number;
  angle: number;
  heave: number;
  pitch: number;
  roll: number;
}

export interface DetachedFloeCellSample {
  thickness: number;
  openness: number;
  snow: number;
  wetness: number;
}

export interface DetachedFloeRenderStats {
  floes: number;
  snowUpdates: number;
  cells: number;
  triangles: number;
}

type DetachedFloeCellSampler = (
  index: number,
  target: DetachedFloeCellSample,
) => DetachedFloeCellSample;

interface FloeMeshEntry {
  bodyMesh: Mesh<BufferGeometry, MeshStandardMaterial>;
  opticalMesh: Mesh<BufferGeometry, MeshStandardMaterial>;
  shadowMesh: Mesh<BufferGeometry, MeshBasicMaterial>;
  cellSet: ReadonlySet<number>;
  cellIndices: readonly number[];
  cells: number;
  triangles: number;
}

interface DetachedFloeGeometry {
  surface: BufferGeometry;
  shadow: BufferGeometry;
}

interface FloeTopVertex {
  index: number;
  x: number;
  y: number;
  z: number;
}

export class DetachedFloeRenderer {
  private readonly root = new Group();
  private readonly bodyMaterial = new MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.78,
    metalness: 0,
    vertexColors: true,
    transparent: false,
    depthWrite: true,
  });
  private readonly opticalMaterial = new MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.78,
    metalness: 0,
    vertexColors: true,
    transparent: true,
    depthWrite: false,
    alphaTest: 0.025,
  });
  private readonly shadowMaterial = new MeshBasicMaterial({
    color: 0x000000,
    colorWrite: false,
    depthWrite: false,
    depthTest: false,
    side: DoubleSide,
    toneMapped: false,
  });
  private readonly entries = new Map<number, FloeMeshEntry>();
  private readonly width: number;
  private readonly height: number;
  private readonly sample: DetachedFloeCellSample = {
    thickness: 0,
    openness: 0,
    snow: 0,
    wetness: 0,
  };
  private readonly color = new Color();
  private readonly sideColor = new Color();
  private readonly bottomSideColor = new Color();
  private readonly materialDebugModeUniform = { value: 0 };
  private readonly weatherContrastUniform = { value: 1 };
  private readonly warmthUniform = { value: 0 };
  private readonly wetnessEmphasisUniform = { value: 1 };
  private readonly snowLightResponseUniform = { value: 1 };
  private visualProfile: IceVisualProfileId;
  private snowUpdates = 0;

  public constructor(
    scene: Scene,
    private readonly columns: number,
    private readonly rows: number,
    visualProfile: IceVisualProfileId =
      DEFAULT_ICE_VISUAL_PROFILE_ID,
  ) {
    this.visualProfile = visualProfile;
    this.width = columns * WORLD.cellSize;
    this.height = rows * WORLD.cellSize;
    this.bodyMaterial.colorWrite = false;
    this.root.name = 'Detached floe surfaces';
    scene.add(this.root);
    const configureMaterial = (
      material: MeshStandardMaterial,
      layer: 0 | 1,
    ): void => {
      material.onBeforeCompile = (shader) => {
        shader.vertexShader = shader.vertexShader
        .replace(
          '#include <common>',
          [
            '#include <common>',
            'attribute float floeOpacity;',
            'attribute float floeSnow;',
            'attribute float floeRoughness;',
            'attribute float floeThickness;',
            'attribute float floeWetness;',
            'attribute vec3 floeWeights;',
            'varying float vFloeOpacity;',
            'varying float vFloeSnow;',
            'varying float vFloeRoughness;',
            'varying float vFloeThickness;',
            'varying float vFloeWetness;',
            'varying vec3 vFloeWeights;',
          ].join('\n'),
        )
        .replace(
          '#include <begin_vertex>',
          [
            '#include <begin_vertex>',
            'vFloeOpacity = floeOpacity;',
            'vFloeSnow = floeSnow;',
            'vFloeRoughness = floeRoughness;',
            'vFloeThickness = floeThickness;',
            'vFloeWetness = floeWetness;',
            'vFloeWeights = floeWeights;',
          ].join('\n'),
        );
        shader.fragmentShader = shader.fragmentShader
        .replace(
          '#include <common>',
          [
            '#include <common>',
            'uniform float uFloeWeatherContrast;',
            'uniform float uFloeWarmth;',
            'uniform float uFloeWetnessEmphasis;',
            'uniform float uFloeSnowLightResponse;',
            'uniform float uFloeMaterialDebugMode;',
            'uniform float uFloeLayer;',
            'varying float vFloeOpacity;',
            'varying float vFloeSnow;',
            'varying float vFloeRoughness;',
            'varying float vFloeThickness;',
            'varying float vFloeWetness;',
            'varying vec3 vFloeWeights;',
          ].join('\n'),
        )
        .replace(
          'vec4 diffuseColor = vec4( diffuse, opacity );',
          [
            'vec3 floeColor = diffuse;',
            'if (uFloeMaterialDebugMode < 0.5) {',
            '  float weatherLuma = dot(',
            '    floeColor,',
            '    vec3(0.2126, 0.7152, 0.0722)',
            '  );',
            '  floeColor = mix(',
            '    vec3(weatherLuma),',
            '    floeColor,',
            '    uFloeWeatherContrast',
            '  );',
            '  floeColor = mix(',
            '    floeColor,',
            '    vec3(0.76, 0.88, 0.92),',
            '    max(0.0, -uFloeWarmth) * 0.16',
            '  );',
            '  floeColor = mix(',
            '    floeColor,',
            '    vec3(1.0, 0.91, 0.78),',
            '    max(0.0, uFloeWarmth) * 0.13',
            '  );',
            '  floeColor = mix(',
            '    floeColor,',
            '    vec3(0.45, 0.72, 0.77),',
            '    vFloeWetness * 0.18 * uFloeWetnessEmphasis',
            '  );',
            '  floeColor = mix(',
            '    floeColor,',
            '    vec3(0.96, 0.985, 1.0),',
            '    vFloeSnow * 0.82 * uFloeSnowLightResponse',
            '  );',
            '} else if (uFloeMaterialDebugMode > 1.5) {',
            '  floeColor = vec3(',
            '    vFloeWeights.z,',
            '    vFloeWeights.y,',
            '    vFloeWeights.x',
            '  );',
            '} else if (uFloeMaterialDebugMode > 0.5) {',
            '  floeColor = vec3(clamp(vFloeThickness, 0.0, 1.0));',
            '}',
            'vec4 diffuseColor = vec4(',
            '  floeColor,',
            '  opacity * vFloeOpacity',
            ');',
            'if (uFloeMaterialDebugMode > 0.5) {',
            '  if (uFloeLayer > 0.5) discard;',
            '  diffuseColor.a = 1.0;',
            '} else if (uFloeLayer < 0.5) {',
            '  float bodyCoverage = vFloeWeights.z;',
            '  if (bodyCoverage < 0.985) discard;',
            '  diffuseColor.a = 1.0;',
            '} else {',
            '  diffuseColor.a *= 1.0;',
            '}',
          ].join('\n'),
        )
        .replace(
          '#include <roughnessmap_fragment>',
          [
            '#include <roughnessmap_fragment>',
            'roughnessFactor =',
            '  uFloeMaterialDebugMode < 0.5',
            '    ? mix(',
            '        vFloeRoughness,',
            '        0.98,',
            '        vFloeSnow * 0.72',
            '      )',
            '    : 0.92;',
          ].join('\n'),
        );
        shader.uniforms.uFloeMaterialDebugMode =
          this.materialDebugModeUniform;
        shader.uniforms.uFloeWeatherContrast =
          this.weatherContrastUniform;
        shader.uniforms.uFloeWarmth = this.warmthUniform;
        shader.uniforms.uFloeWetnessEmphasis =
          this.wetnessEmphasisUniform;
        shader.uniforms.uFloeSnowLightResponse =
          this.snowLightResponseUniform;
        shader.uniforms.uFloeLayer = { value: layer };
      };
      material.customProgramCacheKey = () =>
        `detached-floe-surface-v4-${layer}`;
    };
    configureMaterial(this.bodyMaterial, 0);
    configureMaterial(this.opticalMaterial, 1);
  }

  public syncTopology(
    floes: readonly DetachedFloeRenderState[],
    sampleCell: DetachedFloeCellSampler,
  ): void {
    const staleIds = new Set(this.entries.keys());
    for (const floe of floes) {
      if (floe.cells.length === 0) continue;
      const existing = this.entries.get(floe.id);
      const translation = existing
        ? this.getCellTranslation(
            existing.cellIndices,
            floe.cells,
          )
        : undefined;
      if (existing && translation) {
        this.translateSnowCoordinates(
          existing.bodyMesh.geometry,
          translation.column,
          translation.row,
        );
        existing.cellSet = new Set(floe.cells);
        existing.cellIndices = [...floe.cells];
        existing.cells = floe.cells.length;
        staleIds.delete(floe.id);
        continue;
      }
      if (existing) {
        existing.bodyMesh.geometry.dispose();
        existing.shadowMesh.geometry.dispose();
        this.root.remove(
          existing.bodyMesh,
          existing.opticalMesh,
          existing.shadowMesh,
        );
        this.entries.delete(floe.id);
      }
      const geometry = this.createGeometry(floe, sampleCell);
      const bodyMesh = new Mesh(
        geometry.surface,
        this.bodyMaterial,
      );
      bodyMesh.name = `Detached floe surface ${floe.id}`;
      bodyMesh.castShadow = false;
      bodyMesh.receiveShadow = true;
      bodyMesh.frustumCulled = true;
      bodyMesh.renderOrder = 10;
      const opticalMesh = new Mesh(
        geometry.surface,
        this.opticalMaterial,
      );
      opticalMesh.name =
        `Detached floe optical ${floe.id}`;
      opticalMesh.castShadow = false;
      opticalMesh.receiveShadow = true;
      opticalMesh.frustumCulled = true;
      opticalMesh.renderOrder = 11;
      const shadowMesh = new Mesh(
        geometry.shadow,
        this.shadowMaterial,
      );
      shadowMesh.name =
        `Detached floe edge shadow ${floe.id}`;
      shadowMesh.castShadow = true;
      shadowMesh.receiveShadow = false;
      shadowMesh.frustumCulled = true;
      shadowMesh.visible = false;
      this.root.add(bodyMesh, opticalMesh, shadowMesh);
      this.entries.set(floe.id, {
        bodyMesh,
        opticalMesh,
        shadowMesh,
        cellSet: new Set(floe.cells),
        cellIndices: [...floe.cells],
        cells: floe.cells.length,
        triangles:
          (geometry.surface.getIndex()?.count ?? 0) / 3,
      });
      staleIds.delete(floe.id);
    }
    for (const id of staleIds) {
      const entry = this.entries.get(id);
      if (!entry) continue;
      entry.bodyMesh.geometry.dispose();
      entry.shadowMesh.geometry.dispose();
      this.root.remove(
        entry.bodyMesh,
        entry.opticalMesh,
        entry.shadowMesh,
      );
      this.entries.delete(id);
    }
    this.updateTransforms(floes);
  }

  public updateTransforms(
    floes: readonly DetachedFloeRenderState[],
  ): void {
    for (const floe of floes) {
      const entry = this.entries.get(floe.id);
      if (!entry) continue;
      for (const mesh of [
        entry.bodyMesh,
        entry.opticalMesh,
        entry.shadowMesh,
      ]) {
        mesh.position.set(
          floe.centerX + floe.renderOffsetX,
          floe.heave,
          floe.centerZ + floe.renderOffsetZ,
        );
        mesh.rotation.set(
          floe.pitch,
          floe.angle,
          floe.roll,
        );
        mesh.scale.y = 1 + floe.pressure * 0.08;
      }
    }
  }

  public setEnvironmentAppearance(
    weatherContrast: number,
    warmth: number,
    wetnessEmphasis = 1,
    snowLightResponse = 1,
  ): void {
    this.weatherContrastUniform.value = Math.max(
      0.72,
      Math.min(1.12, weatherContrast),
    );
    this.warmthUniform.value = Math.max(
      -1,
      Math.min(1, warmth),
    );
    this.wetnessEmphasisUniform.value = Math.max(
      0.6,
      Math.min(1.5, wetnessEmphasis),
    );
    this.snowLightResponseUniform.value = Math.max(
      0.7,
      Math.min(1.35, snowLightResponse),
    );
  }

  public setMaterialDebugMode(
    mode: IceMaterialDebugMode,
  ): void {
    this.materialDebugModeUniform.value =
      mode === 'thickness' ? 1 : mode === 'weights' ? 2 : 0;
    this.bodyMaterial.colorWrite = mode !== 'normal';
  }

  public setVisualProfile(profile: IceVisualProfileId): void {
    this.visualProfile = profile;
  }

  public setVisible(visible: boolean): void {
    this.root.visible = visible;
  }

  public setShadowState(
    presentationVisible: boolean,
    focusX: number,
    focusZ: number,
    settings: Readonly<IceShadowQualitySettings>,
  ): void {
    for (const entry of this.entries.values()) {
      const sphere = entry.shadowMesh.geometry.boundingSphere;
      entry.shadowMesh.visible =
        presentationVisible &&
        settings.enabled &&
        entry.shadowMesh.geometry.getAttribute('position').count > 0 &&
        isInsideIceShadowRange(
          entry.shadowMesh.position.x,
          entry.shadowMesh.position.z,
          sphere?.radius ?? 0,
          focusX,
          focusZ,
          settings.casterRadius +
            (
              entry.shadowMesh.visible
                ? ICE_SHADOW_CULL_HYSTERESIS
                : 0
            ),
        );
    }
  }

  public getStats(): DetachedFloeRenderStats {
    let cells = 0;
    let triangles = 0;
    for (const entry of this.entries.values()) {
      cells += entry.cells;
      triangles += entry.triangles;
    }
    return {
      floes: this.entries.size,
      snowUpdates: this.snowUpdates,
      cells,
      triangles,
    };
  }

  public dispose(): void {
    for (const entry of this.entries.values()) {
      entry.bodyMesh.geometry.dispose();
      entry.shadowMesh.geometry.dispose();
    }
    this.entries.clear();
    this.root.removeFromParent();
    this.bodyMaterial.dispose();
    this.opticalMaterial.dispose();
    this.shadowMaterial.dispose();
  }

  public updateSnow(
    sampleCell: DetachedFloeCellSampler,
  ): number {
    let changed = 0;
    for (const entry of this.entries.values()) {
      const snow = entry.bodyMesh.geometry.getAttribute(
        'floeSnow',
      ) as Float32BufferAttribute | undefined;
      const coordinates = entry.bodyMesh.geometry.getAttribute(
        'floeSnowCoordinate',
      ) as Float32BufferAttribute | undefined;
      if (!snow || !coordinates) continue;
      let entryChanged = false;
      for (let index = 0; index < snow.count; index += 1) {
        const next =
          this.sampleSnowAtGridCoordinate(
            coordinates.getX(index),
            coordinates.getY(index),
            entry.cellSet,
            sampleCell,
          ) * coordinates.getZ(index);
        if (Math.abs(snow.getX(index) - next) < 0.0001) {
          continue;
        }
        snow.setX(index, next);
        entryChanged = true;
        changed += 1;
      }
      if (entryChanged) snow.needsUpdate = true;
    }
    if (changed > 0) this.snowUpdates += 1;
    return changed;
  }

  private createGeometry(
    floe: Readonly<DetachedFloeRenderState>,
    sampleCell: DetachedFloeCellSampler,
  ): DetachedFloeGeometry {
    const positions: number[] = [];
    const colors: number[] = [];
    const opacity: number[] = [];
    const snow: number[] = [];
    const roughness: number[] = [];
    const thicknessData: number[] = [];
    const wetness: number[] = [];
    const weights: number[] = [];
    const snowCoordinates: number[] = [];
    const indices: number[] = [];
    const shadowPositions: number[] = [];
    const shadowIndices: number[] = [];
    const cellSet = new Set(floe.cells);
    const samplesByCell = new Map<
      number,
      DetachedFloeCellSample
    >();
    for (const index of floe.cells) {
      const sampled = sampleCell(index, this.sample);
      const cached = {
        thickness: sampled.thickness,
        openness: sampled.openness,
        snow: sampled.snow,
        wetness: sampled.wetness,
      };
      samplesByCell.set(index, cached);
    }
    const cornerSamples = new Map<
      number,
      DetachedFloeCellSample
    >();
    const sampleCorner = (
      column: number,
      row: number,
    ): DetachedFloeCellSample => {
      const key = row * (this.columns + 1) + column;
      const cached = cornerSamples.get(key);
      if (cached) return cached;
      let thickness = 0;
      let openness = 0;
      let snowCover = 0;
      let wetnessValue = 0;
      let count = 0;
      const adjacent = [
        this.cellIndex(column - 1, row - 1),
        this.cellIndex(column, row - 1),
        this.cellIndex(column - 1, row),
        this.cellIndex(column, row),
      ];
      for (const adjacentIndex of adjacent) {
        if (
          adjacentIndex === undefined ||
          !cellSet.has(adjacentIndex)
        ) {
          continue;
        }
        const sample = samplesByCell.get(adjacentIndex);
        if (!sample) continue;
        thickness += sample.thickness;
        openness += sample.openness;
        snowCover += sample.snow;
        wetnessValue += sample.wetness;
        count += 1;
      }
      const inverse = 1 / Math.max(1, count);
      const result = {
        thickness: thickness * inverse,
        openness: openness * inverse,
        snow: snowCover * inverse,
        wetness: wetnessValue * inverse,
      };
      cornerSamples.set(key, result);
      return result;
    };
    const sampleSurface = (
      column: number,
      row: number,
    ): DetachedFloeCellSample => {
      const left = Math.floor(column);
      const top = Math.floor(row);
      const amountX = column - left;
      const amountY = row - top;
      const topLeft = sampleCorner(left, top);
      const topRight = sampleCorner(left + 1, top);
      const bottomLeft = sampleCorner(left, top + 1);
      const bottomRight = sampleCorner(left + 1, top + 1);
      const interpolate = (
        topLeftValue: number,
        topRightValue: number,
        bottomLeftValue: number,
        bottomRightValue: number,
      ): number =>
        (
          topLeftValue +
          (topRightValue - topLeftValue) * amountX
        ) *
          (1 - amountY) +
        (
          bottomLeftValue +
          (bottomRightValue - bottomLeftValue) * amountX
        ) *
          amountY;
      return {
        thickness: interpolate(
          topLeft.thickness,
          topRight.thickness,
          bottomLeft.thickness,
          bottomRight.thickness,
        ),
        openness: interpolate(
          topLeft.openness,
          topRight.openness,
          bottomLeft.openness,
          bottomRight.openness,
        ),
        snow: interpolate(
          topLeft.snow,
          topRight.snow,
          bottomLeft.snow,
          bottomRight.snow,
        ),
        wetness: interpolate(
          topLeft.wetness,
          topRight.wetness,
          bottomLeft.wetness,
          bottomRight.wetness,
        ),
      };
    };
    const surfaceBaseY =
      0.075 +
      floe.pressure * 0.028;
    const topVertices = new Map<string, FloeTopVertex>();
    const topVertex = (
      column: number,
      row: number,
    ): FloeTopVertex => {
      const key = `${column},${row}`;
      const cached = topVertices.get(key);
      if (cached) return cached;
      const topSample = sampleSurface(column, row);
      const topStyle = getIceVisualStyle(
        topSample.thickness,
        hash2D(column, row, 1901) * 2 - 1,
        this.visualProfile,
      );
      const point = this.surfacePoint(
        column,
        row,
        floe,
        cellSet,
        surfaceBaseY + topStyle.heightScale * 0.095,
      );
      const topOpacity =
        topStyle.opacity *
        (0.7 + (1 - topSample.openness) * 0.3);
      this.color.setHex(topStyle.color);
      const vertex = {
        index: this.pushVertex(
          point.x,
          point.y,
          point.z,
          this.color,
          topOpacity,
          topSample.snow,
          topStyle.roughness,
          topSample.thickness,
          topSample.wetness,
          topStyle,
          [column, row, 1],
          positions,
          colors,
          opacity,
          snow,
          roughness,
          thicknessData,
          wetness,
          weights,
          snowCoordinates,
        ),
        ...point,
      };
      topVertices.set(key, vertex);
      return vertex;
    };

    for (const index of floe.cells) {
      const sample = samplesByCell.get(index)!;
      const column = index % this.columns;
      const row = Math.floor(index / this.columns);
      const surfaceStyle = getIceVisualStyle(
        sample.thickness,
        hash2D(column, row, 1901) * 2 - 1,
        this.visualProfile,
      );
      const cellOpacity =
        surfaceStyle.opacity *
        (0.7 + (1 - sample.openness) * 0.3);
      const topLeft = topVertex(column, row);
      const leftMiddle = topVertex(column, row + 0.5);
      const bottomLeft = topVertex(column, row + 1);
      const bottomMiddle = topVertex(column + 0.5, row + 1);
      const bottomRight = topVertex(column + 1, row + 1);
      const rightMiddle = topVertex(column + 1, row + 0.5);
      const topRight = topVertex(column + 1, row);
      const topMiddle = topVertex(column + 0.5, row);
      const center = topVertex(column + 0.5, row + 0.5);
      const ring = [
        topLeft,
        leftMiddle,
        bottomLeft,
        bottomMiddle,
        bottomRight,
        rightMiddle,
        topRight,
        topMiddle,
      ] as const;
      for (let ringIndex = 0; ringIndex < ring.length; ringIndex += 1) {
        const current = ring[ringIndex]!;
        const next = ring[(ringIndex + 1) % ring.length]!;
        indices.push(center.index, current.index, next.index);
      }

      const edges = [
        {
          neighbor: this.cellIndex(column - 1, row),
          points: [bottomLeft, leftMiddle, topLeft],
        },
        {
          neighbor: this.cellIndex(column + 1, row),
          points: [topRight, rightMiddle, bottomRight],
        },
        {
          neighbor: this.cellIndex(column, row - 1),
          points: [topLeft, topMiddle, topRight],
        },
        {
          neighbor: this.cellIndex(column, row + 1),
          points: [bottomRight, bottomMiddle, bottomLeft],
        },
      ] as const;
      for (const edge of edges) {
        if (
          edge.neighbor !== undefined &&
          cellSet.has(edge.neighbor)
        ) {
          continue;
        }
        this.sideColor.setHex(surfaceStyle.sideColor);
        this.bottomSideColor
          .copy(this.sideColor)
          .multiplyScalar(0.74);
        const sideOpacity = Math.max(
          0.12,
          cellOpacity * 0.76,
        );
        for (
          let segmentIndex = 0;
          segmentIndex < edge.points.length - 1;
          segmentIndex += 1
        ) {
          const a = edge.points[segmentIndex]!;
          const b = edge.points[segmentIndex + 1]!;
          const bottomY = Math.max(
            0.012,
            Math.min(a.y, b.y) -
              0.055 -
              surfaceStyle.heightScale * 0.1,
          );
          const side = [
            this.pushVertex(
              a.x,
              a.y,
              a.z,
              this.sideColor,
              sideOpacity,
              sample.snow * 0.2,
              Math.min(0.96, surfaceStyle.roughness + 0.08),
              sample.thickness,
              sample.wetness,
              surfaceStyle,
              [column + 0.5, row + 0.5, 0.2],
              positions,
              colors,
              opacity,
              snow,
              roughness,
              thicknessData,
              wetness,
              weights,
              snowCoordinates,
            ),
            this.pushVertex(
              b.x,
              b.y,
              b.z,
              this.sideColor,
              sideOpacity,
              sample.snow * 0.2,
              Math.min(0.96, surfaceStyle.roughness + 0.08),
              sample.thickness,
              sample.wetness,
              surfaceStyle,
              [column + 0.5, row + 0.5, 0.2],
              positions,
              colors,
              opacity,
              snow,
              roughness,
              thicknessData,
              wetness,
              weights,
              snowCoordinates,
            ),
            this.pushVertex(
              b.x,
              bottomY,
              b.z,
              this.bottomSideColor,
              sideOpacity,
              0,
              Math.min(0.96, surfaceStyle.roughness + 0.08),
              sample.thickness,
              sample.wetness,
              surfaceStyle,
              [column + 0.5, row + 0.5, 0],
              positions,
              colors,
              opacity,
              snow,
              roughness,
              thicknessData,
              wetness,
              weights,
              snowCoordinates,
            ),
            this.pushVertex(
              a.x,
              bottomY,
              a.z,
              this.bottomSideColor,
              sideOpacity,
              0,
              Math.min(0.96, surfaceStyle.roughness + 0.08),
              sample.thickness,
              sample.wetness,
              surfaceStyle,
              [column + 0.5, row + 0.5, 0],
              positions,
              colors,
              opacity,
              snow,
              roughness,
              thicknessData,
              wetness,
              weights,
              snowCoordinates,
            ),
          ];
          indices.push(
            side[0]!,
            side[1]!,
            side[2]!,
            side[0]!,
            side[2]!,
            side[3]!,
          );
          if (castsIceEdgeShadow(sample.thickness)) {
            this.pushShadowQuad(
              a,
              b,
              { x: b.x, y: bottomY, z: b.z },
              { x: a.x, y: bottomY, z: a.z },
              shadowPositions,
              shadowIndices,
            );
          }
        }
      }
    }

    const geometry = new BufferGeometry();
    geometry.setAttribute(
      'position',
      new Float32BufferAttribute(positions, 3),
    );
    geometry.setAttribute(
      'color',
      new Float32BufferAttribute(colors, 3),
    );
    geometry.setAttribute(
      'floeOpacity',
      new Float32BufferAttribute(opacity, 1),
    );
    geometry.setAttribute(
      'floeSnow',
      new Float32BufferAttribute(snow, 1),
    );
    geometry.setAttribute(
      'floeRoughness',
      new Float32BufferAttribute(roughness, 1),
    );
    geometry.setAttribute(
      'floeThickness',
      new Float32BufferAttribute(thicknessData, 1),
    );
    geometry.setAttribute(
      'floeWetness',
      new Float32BufferAttribute(wetness, 1),
    );
    geometry.setAttribute(
      'floeWeights',
      new Float32BufferAttribute(weights, 3),
    );
    geometry.setAttribute(
      'floeSnowCoordinate',
      new Float32BufferAttribute(snowCoordinates, 3),
    );
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    geometry.computeBoundingSphere();
    const shadow = new BufferGeometry();
    shadow.setAttribute(
      'position',
      new Float32BufferAttribute(shadowPositions, 3),
    );
    shadow.setIndex(shadowIndices);
    shadow.computeBoundingSphere();
    return { surface: geometry, shadow };
  }

  private pushShadowQuad(
    a: Readonly<{ x: number; y: number; z: number }>,
    b: Readonly<{ x: number; y: number; z: number }>,
    c: Readonly<{ x: number; y: number; z: number }>,
    d: Readonly<{ x: number; y: number; z: number }>,
    positions: number[],
    indices: number[],
  ): void {
    const start = positions.length / 3;
    for (const vertex of [a, b, c, d]) {
      positions.push(vertex.x, vertex.y, vertex.z);
    }
    indices.push(
      start,
      start + 1,
      start + 2,
      start,
      start + 2,
      start + 3,
    );
  }

  private surfacePoint(
    column: number,
    row: number,
    floe: Readonly<DetachedFloeRenderState>,
    cellSet: ReadonlySet<number>,
    y: number,
  ): { x: number; y: number; z: number } {
    const columnIsWhole = Number.isInteger(column);
    const rowIsWhole = Number.isInteger(row);
    if (columnIsWhole && rowIsWhole) {
      return this.corner(column, row, floe, y);
    }
    if (!columnIsWhole && !rowIsWhole) {
      return {
        x:
          column * WORLD.cellSize -
          this.width * 0.5 -
          floe.centerX,
        y,
        z:
          row * WORLD.cellSize -
          this.height * 0.5 -
          floe.centerZ,
      };
    }

    const horizontal = !columnIsWhole;
    const first = horizontal
      ? this.corner(Math.floor(column), row, floe, y)
      : this.corner(column, Math.floor(row), floe, y);
    const second = horizontal
      ? this.corner(Math.ceil(column), row, floe, y)
      : this.corner(column, Math.ceil(row), floe, y);
    let x = (first.x + second.x) * 0.5;
    let z = (first.z + second.z) * 0.5;
    let normalX = 0;
    let normalZ = 0;
    if (horizontal) {
      const edgeColumn = Math.floor(column);
      const edgeRow = row;
      const above = this.cellIndex(edgeColumn, edgeRow - 1);
      const below = this.cellIndex(edgeColumn, edgeRow);
      const aboveOccupied =
        above !== undefined && cellSet.has(above);
      const belowOccupied =
        below !== undefined && cellSet.has(below);
      if (aboveOccupied !== belowOccupied) {
        normalZ = aboveOccupied ? 1 : -1;
      }
    } else {
      const edgeColumn = column;
      const edgeRow = Math.floor(row);
      const left = this.cellIndex(edgeColumn - 1, edgeRow);
      const right = this.cellIndex(edgeColumn, edgeRow);
      const leftOccupied =
        left !== undefined && cellSet.has(left);
      const rightOccupied =
        right !== undefined && cellSet.has(right);
      if (leftOccupied !== rightOccupied) {
        normalX = leftOccupied ? 1 : -1;
      }
    }
    if (normalX !== 0 || normalZ !== 0) {
      let edgeColumn = Math.floor(column);
      let edgeRow = Math.floor(row);
      let edgeIndex = 0;
      if (horizontal) {
        if (normalZ > 0) {
          edgeRow = row - 1;
          edgeIndex = 3;
        } else {
          edgeRow = row;
          edgeIndex = 2;
        }
      } else if (normalX > 0) {
        edgeColumn = column - 1;
        edgeIndex = 1;
      }
      const offset = getOrganicIceBoundaryOffset(
        edgeColumn,
        edgeRow,
        edgeIndex,
        normalX,
        normalZ,
      );
      x += offset.x;
      z += offset.z;
    }
    return { x, y, z };
  }

  private corner(
    column: number,
    row: number,
    floe: Readonly<DetachedFloeRenderState>,
    y: number,
  ): { x: number; y: number; z: number } {
    const offset = getOrganicIceCornerOffset(
      column,
      row,
      this.columns,
      this.rows,
    );
    return {
      x:
        column * WORLD.cellSize -
        this.width * 0.5 -
        floe.centerX +
        offset.x,
      y,
      z:
        row * WORLD.cellSize -
        this.height * 0.5 -
        floe.centerZ +
        offset.z,
    };
  }

  private getCellTranslation(
    previous: readonly number[],
    next: readonly number[],
  ): Readonly<{ column: number; row: number }> | undefined {
    if (previous.length !== next.length || previous.length === 0) {
      return undefined;
    }
    const minimum = (cells: readonly number[]) => {
      let column = this.columns;
      let row = this.rows;
      for (const index of cells) {
        column = Math.min(column, index % this.columns);
        row = Math.min(row, Math.floor(index / this.columns));
      }
      return { column, row };
    };
    const previousMinimum = minimum(previous);
    const nextMinimum = minimum(next);
    const deltaColumn =
      nextMinimum.column - previousMinimum.column;
    const deltaRow = nextMinimum.row - previousMinimum.row;
    if (deltaColumn === 0 && deltaRow === 0) {
      return undefined;
    }
    const nextSet = new Set(next);
    for (const index of previous) {
      const column = index % this.columns;
      const row = Math.floor(index / this.columns);
      const translatedColumn = column + deltaColumn;
      const translatedRow = row + deltaRow;
      if (
        translatedColumn < 0 ||
        translatedColumn >= this.columns ||
        translatedRow < 0 ||
        translatedRow >= this.rows ||
        !nextSet.has(
          translatedRow * this.columns + translatedColumn,
        )
      ) {
        return undefined;
      }
    }
    return {
      column: deltaColumn,
      row: deltaRow,
    };
  }

  private translateSnowCoordinates(
    geometry: BufferGeometry,
    deltaColumn: number,
    deltaRow: number,
  ): void {
    if (deltaColumn === 0 && deltaRow === 0) return;
    const coordinates = geometry.getAttribute(
      'floeSnowCoordinate',
    ) as Float32BufferAttribute | undefined;
    if (!coordinates) return;
    for (let index = 0; index < coordinates.count; index += 1) {
      coordinates.setXY(
        index,
        coordinates.getX(index) + deltaColumn,
        coordinates.getY(index) + deltaRow,
      );
    }
    coordinates.needsUpdate = true;
  }

  private cellIndex(
    column: number,
    row: number,
  ): number | undefined {
    if (
      column < 0 ||
      row < 0 ||
      column >= this.columns ||
      row >= this.rows
    ) {
      return undefined;
    }
    return row * this.columns + column;
  }

  private sampleSnowAtGridCoordinate(
    column: number,
    row: number,
    cellSet: ReadonlySet<number>,
    sampleCell: DetachedFloeCellSampler,
  ): number {
    const left = Math.floor(column);
    const top = Math.floor(row);
    const amountX = column - left;
    const amountY = row - top;
    const topLeft = this.sampleSnowAtCorner(
      left,
      top,
      cellSet,
      sampleCell,
    );
    const topRight = this.sampleSnowAtCorner(
      left + 1,
      top,
      cellSet,
      sampleCell,
    );
    const bottomLeft = this.sampleSnowAtCorner(
      left,
      top + 1,
      cellSet,
      sampleCell,
    );
    const bottomRight = this.sampleSnowAtCorner(
      left + 1,
      top + 1,
      cellSet,
      sampleCell,
    );
    return (
      (topLeft + (topRight - topLeft) * amountX) *
        (1 - amountY) +
      (bottomLeft + (bottomRight - bottomLeft) * amountX) *
        amountY
    );
  }

  private sampleSnowAtCorner(
    cornerColumn: number,
    cornerRow: number,
    cellSet: ReadonlySet<number>,
    sampleCell: DetachedFloeCellSampler,
  ): number {
    let total = 0;
    let samples = 0;
    const adjacent = [
      this.cellIndex(cornerColumn - 1, cornerRow - 1),
      this.cellIndex(cornerColumn, cornerRow - 1),
      this.cellIndex(cornerColumn - 1, cornerRow),
      this.cellIndex(cornerColumn, cornerRow),
    ];
    for (const index of adjacent) {
      if (index === undefined || !cellSet.has(index)) continue;
      total += sampleCell(index, this.sample).snow;
      samples += 1;
    }
    return samples > 0 ? total / samples : 0;
  }

  private pushVertex(
    x: number,
    y: number,
    z: number,
    color: Readonly<Color>,
    vertexOpacity: number,
    vertexSnow: number,
    vertexRoughness: number,
    vertexThickness: number,
    vertexWetness: number,
    style: Readonly<IceVisualStyle>,
    snowCoordinate: readonly [number, number, number],
    positions: number[],
    colors: number[],
    opacity: number[],
    snow: number[],
    roughness: number[],
    thicknessData: number[],
    wetness: number[],
    weights: number[],
    snowCoordinates: number[],
  ): number {
    const index = positions.length / 3;
    positions.push(x, y, z);
    colors.push(color.r, color.g, color.b);
    opacity.push(vertexOpacity);
    snow.push(vertexSnow);
    roughness.push(vertexRoughness);
    thicknessData.push(vertexThickness);
    wetness.push(vertexWetness);
    weights.push(
      style.weights.thin,
      style.weights.medium,
      style.weights.thick,
    );
    snowCoordinates.push(
      snowCoordinate[0],
      snowCoordinate[1],
      snowCoordinate[2],
    );
    return index;
  }
}
