import { clamp, lerp, smoothstep } from '../utils/math';
import { BOREALIS_GROUND_HEIGHT, isBorealisLand } from './BorealisLand';
import {
  sampleBorealisRasterElevation,
  sampleBorealisRasterSurfaceMaterial,
} from './BorealisCoastRaster';
import { applyWildernessTerrainProfile } from '../survival/WildernessBiome';
import { sampleGeneratedWorld } from '../world/generation/GeneratedWorldRuntime';

/** Horizontal authoring resolution. It intentionally matches the snow grid. */
export const TERRAIN_GRID_METRES = 2;
/** One editor click raises or lowers the selected terrain node by one metre. */
export const TERRAIN_HEIGHT_STEP_METRES = 1;
/** Normal terrain may change this much between adjacent two-metre nodes. */
export const TERRAIN_SMOOTH_STEP_METRES = 0.5;
/**
 * Ordinary sculpting is deliberately broad. The 2 m authoring grid remains
 * useful for selecting and saving terrain, but must never become the visible
 * silhouette of a hill. Eight metres gives a one-cell raise a rounded,
 * walkable shoulder while the separate mountain/cliff tools retain their
 * deliberately assertive profiles.
 */
export const TERRAIN_SOFT_SCULPT_FEATHER_METRES = 8;
export const SIDEWALK_RISE_METRES = 0.15;

export type TerrainCliffEdge = 'N' | 'E' | 'S' | 'W';
export type TerrainBrushMode =
  | 'RAISE'
  | 'LOWER'
  | 'SMOOTH'
  | 'FLATTEN'
  | 'PLATEAU'
  | 'MOUNTAIN'
  | 'CLIFF'
  | 'RAMP'
  | 'SURFACE'
  | 'ROAD_PATH'
  | 'SIDEWALK_PATH'
  | 'RESTORE';
export type TerrainSurfaceMaterial =
  | 'TUNDRA'
  | 'ROCK'
  | 'DIRT'
  | 'ROAD'
  | 'SIDEWALK'
  | 'SNOW_EXCLUSION';

export interface TerrainCellSaveData {
  readonly gridX: number;
  readonly gridZ: number;
  readonly deltaMetres: number;
}

export interface TerrainCliffSaveData {
  readonly gridX: number;
  readonly gridZ: number;
  readonly edge: TerrainCliffEdge;
}

export interface TerrainHeightSaveData {
  readonly version: 1;
  /**
   * `WORLD` keeps the authored/procedural Ice-A-Way base beneath sparse edits.
   * `FLAT` is an isolated World Builder canvas and deliberately bypasses every
   * raster, wilderness and generated-world elevation source.
   */
  readonly baseProfile?: 'WORLD' | 'FLAT';
  readonly flatBaseHeightMetres?: number;
  readonly cells: readonly TerrainCellSaveData[];
  readonly cliffs: readonly TerrainCliffSaveData[];
  readonly surfaces?: readonly TerrainSurfaceSaveData[];
}

export interface TerrainSurfaceSaveData {
  readonly gridX: number;
  readonly gridZ: number;
  readonly material: TerrainSurfaceMaterial;
}

/**
 * Indexed editor checkpoint. The serializable copy is persisted separately
 * from the continuously autosaved current terrain state.
 */
export interface TerrainHeightRestorePoint {
  readonly saveData: TerrainHeightSaveData;
  readonly deltaByCell: ReadonlyMap<string, number>;
  readonly cliffEdges: ReadonlySet<string>;
  readonly surfaceByCell: ReadonlyMap<string, TerrainSurfaceMaterial>;
}

export interface TerrainEditBounds {
  readonly minX: number;
  readonly maxX: number;
  readonly minZ: number;
  readonly maxZ: number;
  readonly revision: number;
  readonly kind: 'HEIGHT' | 'CLIFF' | 'SURFACE' | 'IMPORT';
}

export interface TerrainSurfaceSample {
  readonly height: number;
  readonly normalX: number;
  readonly normalY: number;
  readonly normalZ: number;
  readonly slopeRadians: number;
  readonly walkable: boolean;
  readonly driveable: boolean;
}

/**
 * One editable two-by-two metre world square. `gridX/gridZ` identify its
 * north-west corner node; the square owns the four nodes from (x,z) through
 * (x + 1,z + 1). Adjacent squares deliberately share their edge nodes.
 */
export interface TerrainGridCell {
  readonly gridX: number;
  readonly gridZ: number;
}

export type TerrainHeightListener = (bounds: TerrainEditBounds) => void;

const cellKey = (gridX: number, gridZ: number): string => `${gridX},${gridZ}`;
const cliffKey = (
  gridX: number,
  gridZ: number,
  edge: TerrainCliffEdge,
): string => `${gridX},${gridZ},${edge}`;

const oppositeEdge = (edge: TerrainCliffEdge): TerrainCliffEdge => {
  if (edge === 'N') return 'S';
  if (edge === 'E') return 'W';
  if (edge === 'S') return 'N';
  return 'E';
};

const edgeOffset = (
  edge: TerrainCliffEdge,
): Readonly<{ x: number; z: number }> => {
  if (edge === 'N') return { x: 0, z: -1 };
  if (edge === 'E') return { x: 1, z: 0 };
  if (edge === 'S') return { x: 0, z: 1 };
  return { x: -1, z: 0 };
};

const validGridCoordinate = (value: unknown): value is number =>
  Number.isSafeInteger(value) && Math.abs(value as number) <= 1_000_000;

/**
 * One canonical terrain surface shared by rendering, snow, movement and tools.
 * Authored/base terrain stays deterministic; the dev editor writes only sparse
 * delta nodes and cliff edges, so an enormous world does not allocate an
 * enormous height array.
 */
export class TerrainHeightSystem {
  private readonly deltaByCell = new Map<string, number>();
  private readonly cliffEdges = new Set<string>();
  private readonly surfaceByCell = new Map<string, TerrainSurfaceMaterial>();
  private readonly listeners = new Set<TerrainHeightListener>();
  private revision = 0;
  private baseProfile: 'WORLD' | 'FLAT' = 'WORLD';
  private flatBaseHeightMetres = BOREALIS_GROUND_HEIGHT;

  public getRevision(): number {
    return this.revision;
  }

  public getBaseProfile(): 'WORLD' | 'FLAT' {
    return this.baseProfile;
  }

  private isEditableLand(x: number, z: number): boolean {
    return this.baseProfile === 'FLAT' || isBorealisLand(x, z);
  }

  public addListener(listener: TerrainHeightListener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  public worldToGrid(value: number): number {
    return Math.round(value / TERRAIN_GRID_METRES);
  }

  public gridToWorld(value: number): number {
    return value * TERRAIN_GRID_METRES;
  }

  public snapWorld(value: number): number {
    return this.gridToWorld(this.worldToGrid(value));
  }

  public worldToCell(value: number): number {
    return Math.floor(value / TERRAIN_GRID_METRES);
  }

  public cellCenterWorld(cell: number): number {
    return (cell + 0.5) * TERRAIN_GRID_METRES;
  }

  public snapCellCenterWorld(value: number): number {
    return this.cellCenterWorld(this.worldToCell(value));
  }

  /** Returns the exact world squares covered by a circular editor brush. */
  public brushCells(
    worldX: number,
    worldZ: number,
    radiusMetres = TERRAIN_GRID_METRES * 0.5,
  ): readonly TerrainGridCell[] {
    const centerGridX = this.worldToCell(worldX);
    const centerGridZ = this.worldToCell(worldZ);
    const centerX = this.cellCenterWorld(centerGridX);
    const centerZ = this.cellCenterWorld(centerGridZ);
    const radius = Math.max(TERRAIN_GRID_METRES * 0.5, radiusMetres);
    const extent = Math.ceil(radius / TERRAIN_GRID_METRES);
    const cells: TerrainGridCell[] = [];
    for (
      let gridZ = centerGridZ - extent;
      gridZ <= centerGridZ + extent;
      gridZ += 1
    ) {
      for (
        let gridX = centerGridX - extent;
        gridX <= centerGridX + extent;
        gridX += 1
      ) {
        const x = this.cellCenterWorld(gridX);
        const z = this.cellCenterWorld(gridZ);
        if (Math.hypot(x - centerX, z - centerZ) > radius + 0.001) continue;
        if (!this.isEditableLand(x, z)) continue;
        cells.push({ gridX, gridZ });
      }
    }
    return cells;
  }

  /**
   * Returns an odd-sized square of editable world cells. Terrain authoring
   * uses this instead of a circular radius so a 1 x 1 brush is visibly and
   * semantically one complete two-metre grid square.
   */
  public squareBrushCells(
    worldX: number,
    worldZ: number,
    requestedSizeCells = 1,
  ): readonly TerrainGridCell[] {
    const size = Math.max(1, Math.min(17, Math.round(requestedSizeCells)));
    const oddSize = size % 2 === 0 ? size + 1 : size;
    const half = Math.floor(oddSize / 2);
    const centerGridX = this.worldToCell(worldX);
    const centerGridZ = this.worldToCell(worldZ);
    const cells: TerrainGridCell[] = [];
    for (
      let gridZ = centerGridZ - half;
      gridZ <= centerGridZ + half;
      gridZ += 1
    ) {
      for (
        let gridX = centerGridX - half;
        gridX <= centerGridX + half;
        gridX += 1
      ) {
        if (!this.isEditableLand(
          this.cellCenterWorld(gridX),
          this.cellCenterWorld(gridZ),
        )) continue;
        cells.push({ gridX, gridZ });
      }
    }
    return cells;
  }

  public sampleBaseHeight(x: number, z: number): number {
    if (this.baseProfile === 'FLAT') return this.flatBaseHeightMetres;
    const rasterElevation = sampleBorealisRasterElevation(x, z);
    if (rasterElevation !== undefined) {
      return BOREALIS_GROUND_HEIGHT + rasterElevation;
    }
    // Preserve the current playable town as a deliberately authored terrace.
    // Beyond it, broad deterministic hills prove the streaming heightfield
    // without introducing small suspension-jolting vertex noise.
    const westDistance = Math.max(0, -x - 252);
    const northDistance = Math.max(0, Math.abs(z) - 94);
    const wilderness = smoothstep(0, 72, Math.max(westDistance, northDistance));
    if (wilderness <= 0) return BOREALIS_GROUND_HEIGHT;
    const broad =
      2.7 +
      Math.sin(x * 0.018 + z * 0.006) * 1.9 +
      Math.sin(z * 0.027 - 0.7) * 1.25 +
      Math.sin((x - z) * 0.009) * 0.8;
    const ridge = smoothstep(90, 280, westDistance) * 5.5;
    const legacyHeight =
      BOREALIS_GROUND_HEIGHT + wilderness * Math.max(0, broad + ridge);
    const generated = sampleGeneratedWorld(x, z);
    // Borealis and its immediate authoring hinterland remain hand-built. The
    // generated macro world fades in west of the town, after which editor
    // deltas, roads, caves and snow continue to operate exactly as before.
    const generatedBlend = generated.inside
      ? smoothstep(310, 430, westDistance)
      : 0;
    return applyWildernessTerrainProfile(
      lerp(legacyHeight, generated.elevation, generatedBlend),
      x,
      z,
    );
  }

  public sampleNodeHeight(gridX: number, gridZ: number): number {
    const x = this.gridToWorld(gridX);
    const z = this.gridToWorld(gridZ);
    return (
      this.sampleBaseHeight(x, z) +
      (this.deltaByCell.get(cellKey(gridX, gridZ)) ?? 0) +
      this.surfaceHeightOffsetAtGrid(gridX, gridZ)
    );
  }

  public sampleHeight(x: number, z: number): number {
    const scaledX = x / TERRAIN_GRID_METRES;
    const scaledZ = z / TERRAIN_GRID_METRES;
    const minX = Math.floor(scaledX);
    const minZ = Math.floor(scaledZ);
    const maxX = minX + 1;
    const maxZ = minZ + 1;
    const blendX = smoothstep(0, 1, scaledX - minX);
    const blendZ = smoothstep(0, 1, scaledZ - minZ);
    // The procedural/raster base is already continuous at arbitrary world
    // coordinates. Resampling that smooth function only at the 2 m authoring
    // nodes produced visible scallops on the large wilderness ridge. Keep the
    // base continuous and interpolate only authored height/surface offsets;
    // editor plateaus and cliffs retain their shared-node semantics.
    const nodeOffset = (gridX: number, gridZ: number): number =>
      (this.deltaByCell.get(cellKey(gridX, gridZ)) ?? 0) +
      this.surfaceHeightOffsetAtGrid(gridX, gridZ);
    const nearOffset = lerp(
      nodeOffset(minX, minZ),
      nodeOffset(maxX, minZ),
      blendX,
    );
    const farOffset = lerp(
      nodeOffset(minX, maxZ),
      nodeOffset(maxX, maxZ),
      blendX,
    );
    return this.sampleBaseHeight(x, z) +
      lerp(nearOffset, farOffset, blendZ);
  }

  public sampleSurface(x: number, z: number): TerrainSurfaceSample {
    const halfStep = TERRAIN_GRID_METRES * 0.5;
    const left = this.sampleHeight(x - halfStep, z);
    const right = this.sampleHeight(x + halfStep, z);
    const near = this.sampleHeight(x, z - halfStep);
    const far = this.sampleHeight(x, z + halfStep);
    let normalX = left - right;
    let normalY = TERRAIN_GRID_METRES;
    let normalZ = near - far;
    const length = Math.hypot(normalX, normalY, normalZ) || 1;
    normalX /= length;
    normalY /= length;
    normalZ /= length;
    const slopeRadians = Math.acos(clamp(normalY, -1, 1));
    return {
      height: this.sampleHeight(x, z),
      normalX,
      normalY,
      normalZ,
      slopeRadians,
      // On-foot traversal can scramble up a roughly 54 degree natural slope.
      // The movement simulation is already heavily slowed before this limit;
      // this extra margin prevents a coarse macro-mountain sample from
      // becoming an invisible wall while authored near-vertical cliffs remain
      // blocked.
      walkable: slopeRadians <= Math.PI * 0.3,
      driveable: slopeRadians <= Math.PI * 0.115,
    };
  }

  public sampleMaterial(x: number, z: number): TerrainSurfaceMaterial {
    return this.sampleMaterialAtGrid(this.worldToGrid(x), this.worldToGrid(z));
  }

  public isRaisedSurfaceBoundary(
    gridX: number,
    gridZ: number,
    edge: TerrainCliffEdge,
  ): boolean {
    const offset = edgeOffset(edge);
    return (
      this.surfaceHeightOffsetAtGrid(gridX, gridZ) !==
      this.surfaceHeightOffsetAtGrid(gridX + offset.x, gridZ + offset.z)
    );
  }

  public createRestorePoint(input?: unknown): TerrainHeightRestorePoint {
    const fallback = this.exportState();
    const candidate = input && typeof input === 'object'
      ? input as Partial<TerrainHeightSaveData>
      : fallback;
    const source = candidate.version === 1 &&
      Array.isArray(candidate.cells) &&
      Array.isArray(candidate.cliffs)
      ? candidate
      : fallback;
    const deltaByCell = new Map<string, number>();
    for (const cell of source.cells ?? []) {
      if (
        !cell ||
        !validGridCoordinate(cell.gridX) ||
        !validGridCoordinate(cell.gridZ) ||
        !Number.isFinite(cell.deltaMetres)
      ) continue;
      const deltaMetres = clamp(cell.deltaMetres, -64, 64);
      if (Math.abs(deltaMetres) >= 0.0001) {
        deltaByCell.set(cellKey(cell.gridX, cell.gridZ), deltaMetres);
      }
    }
    const cliffEdges = new Set<string>();
    for (const cliff of source.cliffs ?? []) {
      if (
        !cliff ||
        !validGridCoordinate(cliff.gridX) ||
        !validGridCoordinate(cliff.gridZ) ||
        !(['N', 'E', 'S', 'W'] as const).includes(cliff.edge)
      ) continue;
      cliffEdges.add(cliffKey(cliff.gridX, cliff.gridZ, cliff.edge));
    }
    const surfaceByCell = new Map<string, TerrainSurfaceMaterial>();
    for (const surface of source.surfaces ?? []) {
      if (
        !surface ||
        !validGridCoordinate(surface.gridX) ||
        !validGridCoordinate(surface.gridZ) ||
        !(['TUNDRA', 'ROCK', 'DIRT', 'ROAD', 'SIDEWALK', 'SNOW_EXCLUSION'] as const)
          .includes(surface.material)
      ) continue;
      surfaceByCell.set(
        cellKey(surface.gridX, surface.gridZ),
        surface.material,
      );
    }
    const saveData: TerrainHeightSaveData = {
      version: 1,
      baseProfile: source.baseProfile === 'FLAT' ? 'FLAT' : 'WORLD',
      ...(source.baseProfile === 'FLAT'
        ? {
            flatBaseHeightMetres: clamp(
              Number(source.flatBaseHeightMetres) || 0,
              -64,
              64,
            ),
          }
        : {}),
      cells: [...deltaByCell.entries()].map(([key, deltaMetres]) => {
        const [gridX, gridZ] = key.split(',');
        return { gridX: Number(gridX), gridZ: Number(gridZ), deltaMetres };
      }),
      cliffs: [...cliffEdges].map((key) => {
        const [gridX, gridZ, edge] = key.split(',');
        return {
          gridX: Number(gridX),
          gridZ: Number(gridZ),
          edge: edge as TerrainCliffEdge,
        };
      }),
      surfaces: [...surfaceByCell.entries()].map(([key, material]) => {
        const [gridX, gridZ] = key.split(',');
        return { gridX: Number(gridX), gridZ: Number(gridZ), material };
      }),
    };
    return { saveData, deltaByCell, cliffEdges, surfaceByCell };
  }

  /** Restores only a square grid brush from an explicit editor checkpoint. */
  public restoreSquare(
    restorePoint: Readonly<TerrainHeightRestorePoint>,
    worldX: number,
    worldZ: number,
    radiusMetres = TERRAIN_GRID_METRES * 0.5,
  ): TerrainEditBounds | undefined {
    const centerX = this.worldToGrid(worldX);
    const centerZ = this.worldToGrid(worldZ);
    if (!this.isEditableLand(this.gridToWorld(centerX), this.gridToWorld(centerZ))) {
      return undefined;
    }
    const radiusNodes = Math.max(
      0,
      Math.floor(Math.max(0, radiusMetres) / TERRAIN_GRID_METRES),
    );
    const minX = centerX - radiusNodes;
    const maxX = centerX + radiusNodes;
    const minZ = centerZ - radiusNodes;
    const maxZ = centerZ + radiusNodes;
    let changed = false;
    for (let gridZ = minZ; gridZ <= maxZ; gridZ += 1) {
      for (let gridX = minX; gridX <= maxX; gridX += 1) {
        const key = cellKey(gridX, gridZ);
        const checkpointDelta = restorePoint.deltaByCell.get(key);
        const currentDelta = this.deltaByCell.get(key);
        if (checkpointDelta === undefined) {
          if (currentDelta !== undefined) {
            this.deltaByCell.delete(key);
            changed = true;
          }
        } else if (currentDelta !== checkpointDelta) {
          this.deltaByCell.set(key, checkpointDelta);
          changed = true;
        }
        const checkpointSurface = restorePoint.surfaceByCell.get(key);
        const currentSurface = this.surfaceByCell.get(key);
        if (checkpointSurface === undefined) {
          if (currentSurface !== undefined) {
            this.surfaceByCell.delete(key);
            changed = true;
          }
        } else if (currentSurface !== checkpointSurface) {
          this.surfaceByCell.set(key, checkpointSurface);
          changed = true;
        }
      }
    }
    // Restore every directional edge touching the square, including an edge
    // whose stored owner node lies just outside the selected area.
    for (let gridZ = minZ - 1; gridZ <= maxZ + 1; gridZ += 1) {
      for (let gridX = minX - 1; gridX <= maxX + 1; gridX += 1) {
        for (const edge of ['N', 'E', 'S', 'W'] as const) {
          const offset = edgeOffset(edge);
          const ownerInside =
            gridX >= minX && gridX <= maxX && gridZ >= minZ && gridZ <= maxZ;
          const neighbourX = gridX + offset.x;
          const neighbourZ = gridZ + offset.z;
          const neighbourInside =
            neighbourX >= minX && neighbourX <= maxX &&
            neighbourZ >= minZ && neighbourZ <= maxZ;
          if (!ownerInside && !neighbourInside) continue;
          const key = cliffKey(gridX, gridZ, edge);
          const checkpointEnabled = restorePoint.cliffEdges.has(key);
          const currentEnabled = this.cliffEdges.has(key);
          if (checkpointEnabled === currentEnabled) continue;
          if (checkpointEnabled) this.cliffEdges.add(key);
          else this.cliffEdges.delete(key);
          changed = true;
        }
      }
    }
    if (!changed) return undefined;
    this.emitGridBounds(minX - 1, maxX + 1, minZ - 1, maxZ + 1, 'IMPORT');
    return this.gridBounds(minX - 1, maxX + 1, minZ - 1, maxZ + 1, 'IMPORT');
  }

  public isCliffEdge(
    gridX: number,
    gridZ: number,
    edge: TerrainCliffEdge,
  ): boolean {
    if (this.cliffEdges.has(cliffKey(gridX, gridZ, edge))) return true;
    const offset = edgeOffset(edge);
    return this.cliffEdges.has(
      cliffKey(gridX + offset.x, gridZ + offset.z, oppositeEdge(edge)),
    );
  }

  public isNearCliff(x: number, z: number, radiusMetres = 0.35): boolean {
    const centerGridX = this.worldToGrid(x);
    const centerGridZ = this.worldToGrid(z);
    const half = TERRAIN_GRID_METRES * 0.5;
    for (let gridZ = centerGridZ - 1; gridZ <= centerGridZ + 1; gridZ += 1) {
      for (let gridX = centerGridX - 1; gridX <= centerGridX + 1; gridX += 1) {
        const centerX = this.gridToWorld(gridX);
        const centerZ = this.gridToWorld(gridZ);
        if (this.isCliffEdge(gridX, gridZ, 'E')) {
          const lineX = centerX + half;
          if (
            Math.abs(x - lineX) <= radiusMetres &&
            z >= centerZ - half - radiusMetres &&
            z <= centerZ + half + radiusMetres
          ) return true;
        }
        if (this.isCliffEdge(gridX, gridZ, 'S')) {
          const lineZ = centerZ + half;
          if (
            Math.abs(z - lineZ) <= radiusMetres &&
            x >= centerX - half - radiusMetres &&
            x <= centerX + half + radiusMetres
          ) return true;
        }
      }
    }
    return false;
  }

  public toggleCliffEdge(
    gridX: number,
    gridZ: number,
    edge: TerrainCliffEdge,
    force?: boolean,
  ): boolean {
    const key = cliffKey(gridX, gridZ, edge);
    const enabled = force ?? !this.cliffEdges.has(key);
    if (enabled) this.cliffEdges.add(key);
    else this.cliffEdges.delete(key);
    this.emitGridBounds(gridX - 1, gridX + 1, gridZ - 1, gridZ + 1, 'CLIFF');
    return enabled;
  }

  public setCellDelta(gridX: number, gridZ: number, deltaMetres: number): void {
    const key = cellKey(gridX, gridZ);
    const finite = Number.isFinite(deltaMetres) ? deltaMetres : 0;
    if (Math.abs(finite) < 0.0001) this.deltaByCell.delete(key);
    else this.deltaByCell.set(key, clamp(finite, -64, 64));
  }

  public applyBrush(
    mode: TerrainBrushMode,
    worldX: number,
    worldZ: number,
    options: Readonly<{
      radiusMetres?: number;
      heightStepMetres?: number;
      targetHeight?: number;
      cliffEdge?: TerrainCliffEdge;
      surfaceMaterial?: TerrainSurfaceMaterial;
    }> = {},
  ): TerrainEditBounds | undefined {
    const centerX = this.worldToGrid(worldX);
    const centerZ = this.worldToGrid(worldZ);
    if (!this.isEditableLand(this.gridToWorld(centerX), this.gridToWorld(centerZ))) {
      return undefined;
    }
    if (mode === 'CLIFF') {
      this.toggleCliffEdge(
        centerX,
        centerZ,
        options.cliffEdge ?? 'E',
      );
      return this.gridBounds(
        centerX - 1,
        centerX + 1,
        centerZ - 1,
        centerZ + 1,
        'CLIFF',
      );
    }
    if (
      mode === 'RAMP' ||
      mode === 'ROAD_PATH' ||
      mode === 'SIDEWALK_PATH' ||
      mode === 'RESTORE'
    ) return undefined;

    if (
      mode === 'RAISE' ||
      mode === 'LOWER' ||
      mode === 'SMOOTH' ||
      mode === 'FLATTEN' ||
      mode === 'PLATEAU' ||
      mode === 'MOUNTAIN'
    ) {
      return this.applyBrushCells(
        mode,
        this.brushCells(
          worldX,
          worldZ,
          options.radiusMetres ?? TERRAIN_GRID_METRES * 0.5,
        ),
        {
          ...options,
          targetHeight:
            (mode === 'FLATTEN' || mode === 'PLATEAU') &&
              !Number.isFinite(options.targetHeight)
              ? this.sampleHeight(worldX, worldZ)
              : options.targetHeight,
        },
      );
    }

    const radiusNodes = Math.max(
      0,
      Math.floor((options.radiusMetres ?? TERRAIN_GRID_METRES * 0.5) /
        TERRAIN_GRID_METRES),
    );
    const heightStepMetres = clamp(
      options.heightStepMetres ?? TERRAIN_HEIGHT_STEP_METRES,
      0.5,
      TERRAIN_HEIGHT_STEP_METRES,
    );
    const touched: Array<{ x: number; z: number }> = [];
    for (let z = centerZ - radiusNodes; z <= centerZ + radiusNodes; z += 1) {
      for (let x = centerX - radiusNodes; x <= centerX + radiusNodes; x += 1) {
        if (!this.isEditableLand(this.gridToWorld(x), this.gridToWorld(z))) continue;
        const current = this.sampleNodeHeight(x, z);
        let next = current;
        if (mode === 'SURFACE') {
          const material = options.surfaceMaterial ?? 'TUNDRA';
          const key = cellKey(x, z);
          // Tundra is stored too: an editor patch must be able to override a
          // non-tundra material coming from the raster source layer.
          this.surfaceByCell.set(key, material);
          touched.push({ x, z });
          continue;
        }
        if (mode === 'RAISE') next += heightStepMetres;
        else if (mode === 'LOWER') next -= heightStepMetres;
        else if (mode === 'MOUNTAIN') {
          // The mountain brush is intentionally much more assertive than the
          // everyday sculpt brush. Its separate relaxation profile below
          // permits a real ridge instead of spreading every click into a hill.
          next += Math.max(1, heightStepMetres * 2);
        } else if (mode === 'FLATTEN' || mode === 'PLATEAU') {
          next = Number.isFinite(options.targetHeight)
            ? options.targetHeight as number
            : this.sampleNodeHeight(centerX, centerZ);
        } else if (mode === 'SMOOTH') {
          const neighbours = this.neighbours(x, z)
            .filter((item) => !this.isCliffEdge(x, z, item.edge))
            .map((item) => this.sampleNodeHeight(item.x, item.z));
          next = neighbours.length > 0
            ? (current + neighbours.reduce((sum, value) => sum + value, 0)) /
              (neighbours.length + 1)
            : current;
        }
        this.setAbsoluteNodeHeight(x, z, next);
        touched.push({ x, z });
      }
    }
    if (touched.length === 0) return undefined;
    if (mode === 'SURFACE') {
      const minX = Math.min(...touched.map((item) => item.x));
      const maxX = Math.max(...touched.map((item) => item.x));
      const minZ = Math.min(...touched.map((item) => item.z));
      const maxZ = Math.max(...touched.map((item) => item.z));
      this.emitGridBounds(minX - 1, maxX + 1, minZ - 1, maxZ + 1, 'SURFACE');
      return this.gridBounds(
        minX - 1,
        maxX + 1,
        minZ - 1,
        maxZ + 1,
        'SURFACE',
      );
    }
    const relaxed = mode === 'MOUNTAIN'
      ? this.relaxFrom(touched, 12, 1.5)
      : this.relaxFrom(touched, 20, TERRAIN_SMOOTH_STEP_METRES);
    const all = [...touched, ...relaxed];
    const minX = Math.min(...all.map((item) => item.x));
    const maxX = Math.max(...all.map((item) => item.x));
    const minZ = Math.min(...all.map((item) => item.z));
    const maxZ = Math.max(...all.map((item) => item.z));
    this.emitGridBounds(minX - 1, maxX + 1, minZ - 1, maxZ + 1, 'HEIGHT');
    return this.gridBounds(minX - 1, maxX + 1, minZ - 1, maxZ + 1);
  }

  /**
   * Applies a height operation to complete world squares. Every selected
   * square contributes all four shared corner vertices. Exact-height tools
   * lock those core vertices; ordinary raise/lower builds a broad continuous
   * influence field around them so the selection grid is never the visible
   * silhouette of the resulting landform.
   *
   * `reference` is normally the immutable terrain at stroke start. It makes
   * an overlapping painted stroke deterministic: a vertex shared by two
   * selected squares is still raised exactly once, never once per stamp.
   */
  public applyBrushCells(
    mode: Extract<
      TerrainBrushMode,
      'RAISE' | 'LOWER' | 'SMOOTH' | 'FLATTEN' | 'PLATEAU' | 'MOUNTAIN'
    >,
    cells: readonly TerrainGridCell[],
    options: Readonly<{
      heightStepMetres?: number;
      targetHeight?: number;
    }> = {},
    reference: TerrainHeightSystem = this,
  ): TerrainEditBounds | undefined {
    const selected = new Map<string, TerrainGridCell>();
    for (const cell of cells) {
      if (!validGridCoordinate(cell.gridX) || !validGridCoordinate(cell.gridZ)) {
        continue;
      }
      const centerX = this.cellCenterWorld(cell.gridX);
      const centerZ = this.cellCenterWorld(cell.gridZ);
      if (!this.isEditableLand(centerX, centerZ)) continue;
      selected.set(cellKey(cell.gridX, cell.gridZ), cell);
    }
    if (selected.size === 0) return undefined;

    const core = new Map<string, { x: number; z: number }>();
    for (const cell of selected.values()) {
      for (const offsetZ of [0, 1]) {
        for (const offsetX of [0, 1]) {
          const x = cell.gridX + offsetX;
          const z = cell.gridZ + offsetZ;
          core.set(cellKey(x, z), { x, z });
        }
      }
    }

    const step = clamp(
      options.heightStepMetres ?? TERRAIN_HEIGHT_STEP_METRES,
      0.5,
      TERRAIN_HEIGHT_STEP_METRES,
    );
    if (mode === 'RAISE' || mode === 'LOWER') {
      return this.applySoftSculptNodes(
        core,
        mode === 'RAISE' ? step : -step,
        reference,
      );
    }
    const targetHeight = Number.isFinite(options.targetHeight)
      ? options.targetHeight as number
      : undefined;
    const nextByNode = new Map<string, number>();
    for (const node of core.values()) {
      const current = reference.sampleNodeHeight(node.x, node.z);
      let next = current;
      if (mode === 'MOUNTAIN') next = current + Math.max(1, step * 2);
      else if (mode === 'FLATTEN' || mode === 'PLATEAU') {
        next = targetHeight ?? reference.sampleNodeHeight(node.x, node.z);
      } else {
        const neighbours = reference.neighbours(node.x, node.z)
          .filter((item) => !reference.isCliffEdge(
            node.x,
            node.z,
            item.edge,
          ))
          .map((item) => reference.sampleNodeHeight(item.x, item.z));
        next = neighbours.length > 0
          ? (current + neighbours.reduce((sum, value) => sum + value, 0)) /
            (neighbours.length + 1)
          : current;
      }
      nextByNode.set(cellKey(node.x, node.z), next);
    }
    for (const node of core.values()) {
      this.setAbsoluteNodeHeight(
        node.x,
        node.z,
        nextByNode.get(cellKey(node.x, node.z)) ??
          reference.sampleNodeHeight(node.x, node.z),
      );
    }

    const protectedNodes = new Set(core.keys());
    const starts = [...core.values()];
    const relaxed = mode === 'MOUNTAIN'
      ? this.relaxFrom(starts, 12, 1.5, protectedNodes)
      : this.relaxFrom(
          starts,
          20,
          TERRAIN_SMOOTH_STEP_METRES,
          protectedNodes,
        );
    const all = [...starts, ...relaxed];
    const minX = Math.min(...all.map((item) => item.x));
    const maxX = Math.max(...all.map((item) => item.x));
    const minZ = Math.min(...all.map((item) => item.z));
    const maxZ = Math.max(...all.map((item) => item.z));
    this.emitGridBounds(minX - 1, maxX + 1, minZ - 1, maxZ + 1, 'HEIGHT');
    return this.gridBounds(minX - 1, maxX + 1, minZ - 1, maxZ + 1);
  }

  /**
   * Cuts a narrow hydrology bed without invoking the normal 20-node hill
   * relaxation. The selected cells form the actual bed and only a compact
   * two-cell shoulder is softened, so a 2–4 m creek does not flatten an
   * entire neighbourhood.
   */
  public applyChannelCells(
    cells: readonly TerrainGridCell[],
    requestedDepthMetres: number,
  ): TerrainEditBounds | undefined {
    const selected = new Map<string, TerrainGridCell>();
    for (const cell of cells) {
      if (!validGridCoordinate(cell.gridX) || !validGridCoordinate(cell.gridZ)) continue;
      const x = this.cellCenterWorld(cell.gridX);
      const z = this.cellCenterWorld(cell.gridZ);
      if (!this.isEditableLand(x, z)) continue;
      selected.set(cellKey(cell.gridX, cell.gridZ), cell);
    }
    if (selected.size === 0) return undefined;
    const depth = clamp(requestedDepthMetres, 0.15, 6);
    const core = new Map<string, { x: number; z: number }>();
    for (const cell of selected.values()) {
      this.surfaceByCell.set(cellKey(cell.gridX, cell.gridZ), 'DIRT');
      for (const offsetZ of [0, 1]) {
        for (const offsetX of [0, 1]) {
          const x = cell.gridX + offsetX;
          const z = cell.gridZ + offsetZ;
          core.set(cellKey(x, z), { x, z });
        }
      }
    }
    for (const node of core.values()) {
      this.setAbsoluteNodeHeight(
        node.x,
        node.z,
        this.sampleNodeHeight(node.x, node.z) - depth,
      );
    }
    const relaxed = this.relaxFrom(
      [...core.values()],
      2,
      Math.max(0.35, Math.min(0.85, depth * 0.65)),
      new Set(core.keys()),
    );
    const all = [...core.values(), ...relaxed];
    const minX = Math.min(...all.map((item) => item.x));
    const maxX = Math.max(...all.map((item) => item.x));
    const minZ = Math.min(...all.map((item) => item.z));
    const maxZ = Math.max(...all.map((item) => item.z));
    this.emitGridBounds(minX, maxX, minZ, maxZ, 'HEIGHT');
    return this.gridBounds(minX, maxX, minZ, maxZ, 'HEIGHT');
  }

  public applyRamp(
    startWorldX: number,
    startWorldZ: number,
    endWorldX: number,
    endWorldZ: number,
    widthMetres = TERRAIN_GRID_METRES,
  ): TerrainEditBounds | undefined {
    const startX = this.worldToGrid(startWorldX);
    const startZ = this.worldToGrid(startWorldZ);
    const endX = this.worldToGrid(endWorldX);
    const endZ = this.worldToGrid(endWorldZ);
    const steps = Math.max(Math.abs(endX - startX), Math.abs(endZ - startZ));
    if (steps < 1) return undefined;
    const startHeight = this.sampleNodeHeight(startX, startZ);
    const endHeight = this.sampleNodeHeight(endX, endZ);
    const radius = Math.max(0, Math.floor(widthMetres / TERRAIN_GRID_METRES * 0.5));
    const touched: Array<{ x: number; z: number }> = [];
    for (let step = 0; step <= steps; step += 1) {
      const t = step / steps;
      const centerX = Math.round(lerp(startX, endX, t));
      const centerZ = Math.round(lerp(startZ, endZ, t));
      const target = lerp(startHeight, endHeight, t);
      for (let offsetZ = -radius; offsetZ <= radius; offsetZ += 1) {
        for (let offsetX = -radius; offsetX <= radius; offsetX += 1) {
          const gridX = centerX + offsetX;
          const gridZ = centerZ + offsetZ;
          if (!this.isEditableLand(this.gridToWorld(gridX), this.gridToWorld(gridZ))) continue;
          this.setAbsoluteNodeHeight(gridX, gridZ, target);
          touched.push({ x: gridX, z: gridZ });
        }
      }
    }
    if (touched.length === 0) return undefined;
    const relaxed = this.relaxFrom(touched, 8);
    const all = [...touched, ...relaxed];
    const minX = Math.min(...all.map((item) => item.x));
    const maxX = Math.max(...all.map((item) => item.x));
    const minZ = Math.min(...all.map((item) => item.z));
    const maxZ = Math.max(...all.map((item) => item.z));
    this.emitGridBounds(minX - 1, maxX + 1, minZ - 1, maxZ + 1, 'HEIGHT');
    return this.gridBounds(minX - 1, maxX + 1, minZ - 1, maxZ + 1);
  }

  /** Authors a connected road/sidewalk strip between two snapped points. */
  public applySurfacePath(
    startWorldX: number,
    startWorldZ: number,
    endWorldX: number,
    endWorldZ: number,
    widthMetres: number,
    material: 'ROAD' | 'SIDEWALK',
  ): TerrainEditBounds | undefined {
    const startX = this.snapWorld(startWorldX);
    const startZ = this.snapWorld(startWorldZ);
    const endX = this.snapWorld(endWorldX);
    const endZ = this.snapWorld(endWorldZ);
    const halfWidth = Math.max(TERRAIN_GRID_METRES * 0.5, widthMetres * 0.5);
    const padding = Math.ceil(halfWidth / TERRAIN_GRID_METRES) + 1;
    const minGridX = Math.min(this.worldToGrid(startX), this.worldToGrid(endX)) - padding;
    const maxGridX = Math.max(this.worldToGrid(startX), this.worldToGrid(endX)) + padding;
    const minGridZ = Math.min(this.worldToGrid(startZ), this.worldToGrid(endZ)) - padding;
    const maxGridZ = Math.max(this.worldToGrid(startZ), this.worldToGrid(endZ)) + padding;
    const segmentX = endX - startX;
    const segmentZ = endZ - startZ;
    const segmentLengthSquared = segmentX * segmentX + segmentZ * segmentZ;
    const touched: Array<{ x: number; z: number }> = [];
    for (let gridZ = minGridZ; gridZ <= maxGridZ; gridZ += 1) {
      for (let gridX = minGridX; gridX <= maxGridX; gridX += 1) {
        const x = this.gridToWorld(gridX);
        const z = this.gridToWorld(gridZ);
        if (!this.isEditableLand(x, z)) continue;
        const projection = segmentLengthSquared <= 0.0001
          ? 0
          : clamp(
              ((x - startX) * segmentX + (z - startZ) * segmentZ) /
                segmentLengthSquared,
              0,
              1,
            );
        const closestX = startX + segmentX * projection;
        const closestZ = startZ + segmentZ * projection;
        if (Math.hypot(x - closestX, z - closestZ) > halfWidth + 0.001) continue;
        this.surfaceByCell.set(cellKey(gridX, gridZ), material);
        touched.push({ x: gridX, z: gridZ });
      }
    }
    if (touched.length === 0) return undefined;
    const minX = Math.min(...touched.map((item) => item.x));
    const maxX = Math.max(...touched.map((item) => item.x));
    const minZ = Math.min(...touched.map((item) => item.z));
    const maxZ = Math.max(...touched.map((item) => item.z));
    this.emitGridBounds(minX - 1, maxX + 1, minZ - 1, maxZ + 1, 'SURFACE');
    return this.gridBounds(minX - 1, maxX + 1, minZ - 1, maxZ + 1, 'SURFACE');
  }

  /**
   * Commits a bounded editor preview without importing or rebuilding the
   * entire sparse world. Height, material and cliff data are copied together
   * so every terrain consumer observes one canonical revision on release.
   */
  public applyRegionFrom(
    source: TerrainHeightSystem,
    bounds: Readonly<Pick<TerrainEditBounds, 'minX' | 'maxX' | 'minZ' | 'maxZ'>>,
  ): TerrainEditBounds | undefined {
    const minGridX = Math.floor(bounds.minX / TERRAIN_GRID_METRES);
    const maxGridX = Math.ceil(bounds.maxX / TERRAIN_GRID_METRES);
    const minGridZ = Math.floor(bounds.minZ / TERRAIN_GRID_METRES);
    const maxGridZ = Math.ceil(bounds.maxZ / TERRAIN_GRID_METRES);
    let changed = false;
    for (let gridZ = minGridZ; gridZ <= maxGridZ; gridZ += 1) {
      for (let gridX = minGridX; gridX <= maxGridX; gridX += 1) {
        const key = cellKey(gridX, gridZ);
        const nextDelta = source.deltaByCell.get(key);
        const currentDelta = this.deltaByCell.get(key);
        if (nextDelta === undefined) {
          if (currentDelta !== undefined) {
            this.deltaByCell.delete(key);
            changed = true;
          }
        } else if (currentDelta !== nextDelta) {
          this.deltaByCell.set(key, nextDelta);
          changed = true;
        }
        const nextSurface = source.surfaceByCell.get(key);
        const currentSurface = this.surfaceByCell.get(key);
        if (nextSurface === undefined) {
          if (currentSurface !== undefined) {
            this.surfaceByCell.delete(key);
            changed = true;
          }
        } else if (currentSurface !== nextSurface) {
          this.surfaceByCell.set(key, nextSurface);
          changed = true;
        }
        for (const edge of ['N', 'E', 'S', 'W'] as const) {
          const keyForEdge = cliffKey(gridX, gridZ, edge);
          const nextCliff = source.cliffEdges.has(keyForEdge);
          const currentCliff = this.cliffEdges.has(keyForEdge);
          if (nextCliff === currentCliff) continue;
          if (nextCliff) this.cliffEdges.add(keyForEdge);
          else this.cliffEdges.delete(keyForEdge);
          changed = true;
        }
      }
    }
    if (!changed) return undefined;
    this.emitGridBounds(
      minGridX - 1,
      maxGridX + 1,
      minGridZ - 1,
      maxGridZ + 1,
      'IMPORT',
    );
    return this.gridBounds(
      minGridX - 1,
      maxGridX + 1,
      minGridZ - 1,
      maxGridZ + 1,
      'IMPORT',
    );
  }

  public importState(input: unknown): boolean {
    if (!input || typeof input !== 'object') return false;
    const saved = input as Partial<TerrainHeightSaveData>;
    if (saved.version !== 1 || !Array.isArray(saved.cells) || !Array.isArray(saved.cliffs)) {
      return false;
    }
    const nextCells = new Map<string, number>();
    for (const cell of saved.cells) {
      if (
        !cell ||
        !validGridCoordinate(cell.gridX) ||
        !validGridCoordinate(cell.gridZ) ||
        !Number.isFinite(cell.deltaMetres)
      ) continue;
      const delta = clamp(cell.deltaMetres, -64, 64);
      if (Math.abs(delta) >= 0.0001) nextCells.set(cellKey(cell.gridX, cell.gridZ), delta);
    }
    const nextCliffs = new Set<string>();
    for (const cliff of saved.cliffs) {
      if (
        !cliff ||
        !validGridCoordinate(cliff.gridX) ||
        !validGridCoordinate(cliff.gridZ) ||
        !(['N', 'E', 'S', 'W'] as const).includes(cliff.edge)
      ) continue;
      nextCliffs.add(cliffKey(cliff.gridX, cliff.gridZ, cliff.edge));
    }
    const nextSurfaces = new Map<string, TerrainSurfaceMaterial>();
    for (const surface of saved.surfaces ?? []) {
      if (
        !surface ||
        !validGridCoordinate(surface.gridX) ||
        !validGridCoordinate(surface.gridZ) ||
        !(['TUNDRA', 'ROCK', 'DIRT', 'ROAD', 'SIDEWALK', 'SNOW_EXCLUSION'] as const)
          .includes(surface.material)
      ) continue;
      nextSurfaces.set(cellKey(surface.gridX, surface.gridZ), surface.material);
    }
    this.baseProfile = saved.baseProfile === 'FLAT' ? 'FLAT' : 'WORLD';
    this.flatBaseHeightMetres = clamp(
      Number(saved.flatBaseHeightMetres) || 0,
      -64,
      64,
    );
    this.deltaByCell.clear();
    this.cliffEdges.clear();
    this.surfaceByCell.clear();
    for (const [key, value] of nextCells) this.deltaByCell.set(key, value);
    for (const key of nextCliffs) this.cliffEdges.add(key);
    for (const [key, material] of nextSurfaces) this.surfaceByCell.set(key, material);
    this.revision += 1;
    this.emit({
      minX: -Number.MAX_SAFE_INTEGER,
      maxX: Number.MAX_SAFE_INTEGER,
      minZ: -Number.MAX_SAFE_INTEGER,
      maxZ: Number.MAX_SAFE_INTEGER,
      revision: this.revision,
      kind: 'IMPORT',
    });
    return true;
  }

  public exportState(): TerrainHeightSaveData {
    const cells = [...this.deltaByCell.entries()]
      .map(([key, deltaMetres]) => {
        const parts = key.split(',');
        return {
          gridX: Number(parts[0] ?? 0),
          gridZ: Number(parts[1] ?? 0),
          deltaMetres,
        };
      })
      .sort((left, right) => left.gridZ - right.gridZ || left.gridX - right.gridX);
    const cliffs = [...this.cliffEdges]
      .map((key) => {
        const [gridX, gridZ, edge] = key.split(',');
        return {
          gridX: Number(gridX),
          gridZ: Number(gridZ),
          edge: edge as TerrainCliffEdge,
        };
      })
      .sort((left, right) =>
        left.gridZ - right.gridZ || left.gridX - right.gridX || left.edge.localeCompare(right.edge),
      );
    const surfaces = [...this.surfaceByCell.entries()]
      .map(([key, material]) => {
        const parts = key.split(',');
        return {
          gridX: Number(parts[0] ?? 0),
          gridZ: Number(parts[1] ?? 0),
          material,
        };
      })
      .sort((left, right) => left.gridZ - right.gridZ || left.gridX - right.gridX);
    return {
      version: 1,
      baseProfile: this.baseProfile,
      ...(this.baseProfile === 'FLAT'
        ? { flatBaseHeightMetres: this.flatBaseHeightMetres }
        : {}),
      cells,
      cliffs,
      surfaces,
    };
  }

  private setAbsoluteNodeHeight(gridX: number, gridZ: number, height: number): void {
    this.setCellDelta(
      gridX,
      gridZ,
      height -
        this.sampleBaseHeight(this.gridToWorld(gridX), this.gridToWorld(gridZ)) -
        this.surfaceHeightOffsetAtGrid(gridX, gridZ),
    );
  }

  private sampleMaterialAtGrid(
    gridX: number,
    gridZ: number,
  ): TerrainSurfaceMaterial {
    return this.surfaceByCell.get(cellKey(gridX, gridZ)) ??
      (this.baseProfile === 'FLAT' ? 'TUNDRA' : undefined) ??
      sampleBorealisRasterSurfaceMaterial(
        this.gridToWorld(gridX),
        this.gridToWorld(gridZ),
      ) ??
      'TUNDRA';
  }

  private surfaceHeightOffsetAtGrid(gridX: number, gridZ: number): number {
    return this.sampleMaterialAtGrid(gridX, gridZ) === 'SIDEWALK'
      ? SIDEWALK_RISE_METRES
      : 0;
  }

  private relaxFrom(
    starts: readonly { x: number; z: number }[],
    maximumDistance: number,
    maximumCardinalStepMetres = TERRAIN_SMOOTH_STEP_METRES,
    protectedNodes: ReadonlySet<string> = new Set(),
  ): readonly { x: number; z: number }[] {
    const queue = starts.map((item) => ({ ...item, distance: 0 }));
    const visited = new Set(starts.map((item) => cellKey(item.x, item.z)));
    const changed: Array<{ x: number; z: number }> = [];
    for (let cursor = 0; cursor < queue.length; cursor += 1) {
      const source = queue[cursor];
      if (!source || source.distance >= maximumDistance) continue;
      const sourceHeight = this.sampleNodeHeight(source.x, source.z);
      for (const neighbour of this.relaxationNeighbours(source.x, source.z)) {
        if (protectedNodes.has(cellKey(neighbour.x, neighbour.z))) continue;
        if (
          neighbour.edge &&
          this.isCliffEdge(source.x, source.z, neighbour.edge)
        ) continue;
        if (!neighbour.edge) {
          const horizontalEdge: TerrainCliffEdge = neighbour.x > source.x
            ? 'E'
            : 'W';
          const verticalEdge: TerrainCliffEdge = neighbour.z > source.z
            ? 'S'
            : 'N';
          if (
            this.isCliffEdge(source.x, source.z, horizontalEdge) ||
            this.isCliffEdge(source.x, source.z, verticalEdge)
          ) continue;
        }
        const worldX = this.gridToWorld(neighbour.x);
        const worldZ = this.gridToWorld(neighbour.z);
        if (!this.isEditableLand(worldX, worldZ)) continue;
        const current = this.sampleNodeHeight(neighbour.x, neighbour.z);
        const difference = current - sourceHeight;
        const maximumStep =
          maximumCardinalStepMetres * neighbour.distanceScale;
        if (Math.abs(difference) <= maximumStep + 0.0001) continue;
        const next = sourceHeight + Math.sign(difference) * maximumStep;
        this.setAbsoluteNodeHeight(neighbour.x, neighbour.z, next);
        changed.push({ x: neighbour.x, z: neighbour.z });
        const key = cellKey(neighbour.x, neighbour.z);
        if (!visited.has(key)) {
          visited.add(key);
          queue.push({
            x: neighbour.x,
            z: neighbour.z,
            distance: source.distance + neighbour.distanceScale,
          });
        }
      }
    }
    return changed;
  }

  /**
   * Builds a continuous, cliff-aware influence field around the selected
   * cells. A multi-source distance pass is preferable to relaxing heights
   * one neighbour at a time: the latter leaves square/diamond terraces and
   * its result depends on traversal order. Here every core node receives the
   * requested edit once and the shoulder follows one deterministic smoothstep
   * curve in world metres.
   */
  private applySoftSculptNodes(
    core: ReadonlyMap<string, { x: number; z: number }>,
    signedStepMetres: number,
    reference: TerrainHeightSystem,
  ): TerrainEditBounds | undefined {
    interface DistanceNode {
      readonly x: number;
      readonly z: number;
      readonly distanceMetres: number;
    }

    const maximumDistance = TERRAIN_SOFT_SCULPT_FEATHER_METRES;
    const distanceByNode = new Map<string, number>();
    const pending: DistanceNode[] = [];

    const push = (node: DistanceNode): void => {
      pending.push(node);
      let index = pending.length - 1;
      while (index > 0) {
        const parent = Math.floor((index - 1) / 2);
        if (
          (pending[parent]?.distanceMetres ?? Number.POSITIVE_INFINITY) <=
          node.distanceMetres
        ) break;
        pending[index] = pending[parent]!;
        index = parent;
      }
      pending[index] = node;
    };
    const pop = (): DistanceNode | undefined => {
      const first = pending[0];
      const last = pending.pop();
      if (!first || !last || pending.length === 0) return first;
      let index = 0;
      while (true) {
        const left = index * 2 + 1;
        if (left >= pending.length) break;
        const right = left + 1;
        const child = right < pending.length &&
            pending[right]!.distanceMetres < pending[left]!.distanceMetres
          ? right
          : left;
        if (pending[child]!.distanceMetres >= last.distanceMetres) break;
        pending[index] = pending[child]!;
        index = child;
      }
      pending[index] = last;
      return first;
    };

    for (const node of core.values()) {
      const key = cellKey(node.x, node.z);
      if (distanceByNode.has(key)) continue;
      distanceByNode.set(key, 0);
      push({ ...node, distanceMetres: 0 });
    }

    while (pending.length > 0) {
      const source = pop();
      if (!source) break;
      const sourceKey = cellKey(source.x, source.z);
      if (source.distanceMetres > (distanceByNode.get(sourceKey) ?? Infinity)) {
        continue;
      }
      if (source.distanceMetres >= maximumDistance) continue;
      for (const neighbour of reference.relaxationNeighbours(
        source.x,
        source.z,
      )) {
        if (
          neighbour.edge &&
          reference.isCliffEdge(source.x, source.z, neighbour.edge)
        ) continue;
        if (!neighbour.edge) {
          const horizontalEdge: TerrainCliffEdge = neighbour.x > source.x
            ? 'E'
            : 'W';
          const verticalEdge: TerrainCliffEdge = neighbour.z > source.z
            ? 'S'
            : 'N';
          if (
            reference.isCliffEdge(source.x, source.z, horizontalEdge) ||
            reference.isCliffEdge(source.x, source.z, verticalEdge)
          ) continue;
        }
        if (!this.isEditableLand(
          reference.gridToWorld(neighbour.x),
          reference.gridToWorld(neighbour.z),
        )) continue;
        const distanceMetres = source.distanceMetres +
          neighbour.distanceScale * TERRAIN_GRID_METRES;
        if (distanceMetres > maximumDistance + 0.0001) continue;
        const key = cellKey(neighbour.x, neighbour.z);
        if (distanceMetres >= (distanceByNode.get(key) ?? Infinity) - 0.0001) {
          continue;
        }
        distanceByNode.set(key, distanceMetres);
        push({
          x: neighbour.x,
          z: neighbour.z,
          distanceMetres,
        });
      }
    }

    // A soft hill may curl around the end of a cliff, but its first low-side
    // node must not be raised through the authored rock face. Without this
    // guard an alternate diagonal path in the distance field could quietly
    // erode the very discontinuity the cliff tool was asked to preserve.
    for (const node of core.values()) {
      for (const neighbour of reference.neighbours(node.x, node.z)) {
        if (
          !core.has(cellKey(neighbour.x, neighbour.z)) &&
          reference.isCliffEdge(node.x, node.z, neighbour.edge)
        ) {
          distanceByNode.delete(cellKey(neighbour.x, neighbour.z));
        }
      }
    }

    const changed: Array<{ x: number; z: number }> = [];
    for (const [key, distanceMetres] of distanceByNode) {
      const influence = 1 - smoothstep(
        0,
        maximumDistance,
        distanceMetres,
      );
      if (influence <= 0.0001) continue;
      const [rawX, rawZ] = key.split(',');
      const x = Number(rawX);
      const z = Number(rawZ);
      this.setAbsoluteNodeHeight(
        x,
        z,
        reference.sampleNodeHeight(x, z) + signedStepMetres * influence,
      );
      changed.push({ x, z });
    }
    if (changed.length === 0) return undefined;
    const minX = Math.min(...changed.map((item) => item.x));
    const maxX = Math.max(...changed.map((item) => item.x));
    const minZ = Math.min(...changed.map((item) => item.z));
    const maxZ = Math.max(...changed.map((item) => item.z));
    this.emitGridBounds(minX - 1, maxX + 1, minZ - 1, maxZ + 1, 'HEIGHT');
    return this.gridBounds(minX - 1, maxX + 1, minZ - 1, maxZ + 1);
  }

  private neighbours(gridX: number, gridZ: number): readonly {
    x: number;
    z: number;
    edge: TerrainCliffEdge;
  }[] {
    return [
      { x: gridX, z: gridZ - 1, edge: 'N' },
      { x: gridX + 1, z: gridZ, edge: 'E' },
      { x: gridX, z: gridZ + 1, edge: 'S' },
      { x: gridX - 1, z: gridZ, edge: 'W' },
    ];
  }

  /**
   * Eight-way relaxation prevents the diamond-shaped diagonal seams produced
   * by a four-neighbour height pass. Diagonal allowance is scaled by √2 so the
   * resulting maximum slope is direction-independent in world space.
   */
  private relaxationNeighbours(gridX: number, gridZ: number): readonly {
    x: number;
    z: number;
    edge?: TerrainCliffEdge;
    distanceScale: number;
  }[] {
    return [
      { x: gridX, z: gridZ - 1, edge: 'N', distanceScale: 1 },
      { x: gridX + 1, z: gridZ, edge: 'E', distanceScale: 1 },
      { x: gridX, z: gridZ + 1, edge: 'S', distanceScale: 1 },
      { x: gridX - 1, z: gridZ, edge: 'W', distanceScale: 1 },
      { x: gridX + 1, z: gridZ - 1, distanceScale: Math.SQRT2 },
      { x: gridX + 1, z: gridZ + 1, distanceScale: Math.SQRT2 },
      { x: gridX - 1, z: gridZ + 1, distanceScale: Math.SQRT2 },
      { x: gridX - 1, z: gridZ - 1, distanceScale: Math.SQRT2 },
    ];
  }

  private gridBounds(
    minGridX: number,
    maxGridX: number,
    minGridZ: number,
    maxGridZ: number,
    kind: TerrainEditBounds['kind'] = 'HEIGHT',
  ): TerrainEditBounds {
    return {
      minX: this.gridToWorld(minGridX),
      maxX: this.gridToWorld(maxGridX),
      minZ: this.gridToWorld(minGridZ),
      maxZ: this.gridToWorld(maxGridZ),
      revision: this.revision,
      kind,
    };
  }

  private emitGridBounds(
    minGridX: number,
    maxGridX: number,
    minGridZ: number,
    maxGridZ: number,
    kind: TerrainEditBounds['kind'],
  ): void {
    this.revision += 1;
    this.emit({
      ...this.gridBounds(minGridX, maxGridX, minGridZ, maxGridZ),
      kind,
    });
  }

  private emit(bounds: TerrainEditBounds): void {
    for (const listener of this.listeners) listener(bounds);
  }
}
