import type { BulldozerControlCommand } from '../../input/PlayerBulldozerController';
import type { LandMachineControlCommand } from '../../input/PlayerLandMachineController';
import type { PenguinControlCommand } from '../../input/PlayerPenguinController';
import type { VesselControlCommand } from '../../vessels/VesselController';
import type {
  CommandSequence,
  NetworkEntityId,
  PlayerId,
  ServerTick,
} from '../../netcode/core/NetworkPrimitives';
import {
  PLAYER_COMMAND_ACTION,
  type PlayerCommandFrame,
} from '../../netcode/protocol/AuthorityIngress';

const hasAction = (
  frame: Readonly<PlayerCommandFrame>,
  action: number,
): boolean => (frame.actionBits & action) !== 0;

const toDiscreteAxis = (value: number): -1 | 0 | 1 =>
  value > 0.01 ? 1 : value < -0.01 ? -1 : 0;

export interface PlayerCommandFrameIdentity {
  playerId: PlayerId;
  controlledEntityId: NetworkEntityId;
  commandSequence: CommandSequence;
  predictedTick: ServerTick;
}

const baseFrame = (
  identity: Readonly<PlayerCommandFrameIdentity>,
): PlayerCommandFrame => ({
  version: 1,
  ...identity,
  movement: {
    forward: 0,
    lateral: 0,
    steering: 0,
    yaw: 0,
    vertical: 0,
  },
  tool: { primaryAxis: 0, secondaryAxis: 0 },
  actionBits: 0,
});

export const frameFromBulldozerControlCommand = (
  identity: Readonly<PlayerCommandFrameIdentity>,
  command: Readonly<BulldozerControlCommand>,
): PlayerCommandFrame => ({
  ...baseFrame(identity),
  movement: {
    forward: command.throttle,
    lateral: 0,
    steering: command.steering,
    yaw: 0,
    vertical: 0,
  },
  tool: {
    primaryAxis: command.bladeMotion,
    secondaryAxis: command.bladeAngleMotion,
  },
  actionBits: actionBitsFromBulldozerCommand(command),
});

export const frameFromLandMachineControlCommand = (
  identity: Readonly<PlayerCommandFrameIdentity>,
  command: Readonly<LandMachineControlCommand>,
): PlayerCommandFrame => ({
  ...baseFrame(identity),
  movement: {
    forward: command.forward,
    lateral: command.lateral,
    steering: command.steering,
    yaw: command.yaw,
    vertical: command.vertical,
  },
  tool: { primaryAxis: 0, secondaryAxis: command.toolTilt },
  actionBits: 0,
});

export const frameFromPenguinControlCommand = (
  identity: Readonly<PlayerCommandFrameIdentity>,
  command: Readonly<PenguinControlCommand>,
  originX: number,
  originZ: number,
): PlayerCommandFrame => {
  const dx = command.aimX === undefined ? undefined : command.aimX - originX;
  const dz = command.aimZ === undefined ? undefined : command.aimZ - originZ;
  const aimHeading =
    dx === undefined || dz === undefined || Math.hypot(dx, dz) < 0.0001
      ? undefined
      : normalizeHeading(Math.atan2(dx, dz));
  return {
    ...baseFrame(identity),
    movement: {
      forward: command.forward,
      lateral: command.right,
      steering: 0,
      yaw: 0,
      vertical: 0,
      aimHeading,
    },
    tool: { primaryAxis: 0, secondaryAxis: 0 },
    actionBits: actionBitsFromPenguinCommand(command),
  };
};

export const frameFromVesselControlCommand = (
  identity: Readonly<PlayerCommandFrameIdentity>,
  command: Readonly<VesselControlCommand>,
): PlayerCommandFrame => ({
  ...baseFrame(identity),
  movement: {
    forward: command.throttleTarget,
    lateral: 0,
    steering: command.steeringTarget,
    yaw: 0,
    vertical: 0,
  },
  tool: { primaryAxis: 0, secondaryAxis: 0 },
  actionBits: actionBitsFromVesselCommand(command),
});

export const toBulldozerControlCommand = (
  frame: Readonly<PlayerCommandFrame>,
): BulldozerControlCommand => ({
  throttle: frame.movement.forward,
  steering: frame.movement.steering,
  bladeMotion: toDiscreteAxis(frame.tool.primaryAxis),
  bladeAngleMotion: toDiscreteAxis(frame.tool.secondaryAxis),
  bucketTiltMotion: toDiscreteAxis(frame.tool.secondaryAxis),
  cycleBladeMode: hasAction(
    frame,
    PLAYER_COMMAND_ACTION.TOGGLE_TOOL_MODE,
  ),
  toggleBeacon: hasAction(frame, PLAYER_COMMAND_ACTION.TOGGLE_BEACON),
  toggleLights: hasAction(frame, PLAYER_COMMAND_ACTION.TOGGLE_LIGHTS),
  horn: hasAction(frame, PLAYER_COMMAND_ACTION.HORN),
  requestExitVehicle: hasAction(frame, PLAYER_COMMAND_ACTION.INTERACT),
  requestReturn: hasAction(frame, PLAYER_COMMAND_ACTION.RETURN_OR_RESET),
});

export const toLandMachineControlCommand = (
  frame: Readonly<PlayerCommandFrame>,
): LandMachineControlCommand => ({
  forward: frame.movement.forward,
  lateral: frame.movement.lateral,
  steering: frame.movement.steering,
  yaw: frame.movement.yaw,
  vertical: frame.movement.vertical,
  toolTilt: frame.tool.secondaryAxis,
});

export const toPenguinControlCommand = (
  frame: Readonly<PlayerCommandFrame>,
  originX?: number,
  originZ?: number,
): PenguinControlCommand => ({
  forward: frame.movement.forward,
  right: frame.movement.lateral,
  run: hasAction(frame, PLAYER_COMMAND_ACTION.RUN_OR_BOOST),
  jump: false,
  blower: hasAction(frame, PLAYER_COMMAND_ACTION.PRIMARY_USE),
  requestEnterVehicle: hasAction(frame, PLAYER_COMMAND_ACTION.INTERACT),
  ...(originX === undefined || originZ === undefined
    ? {}
    : resolveAimPoint(frame, originX, originZ)),
});

export const toVesselControlCommand = (
  frame: Readonly<PlayerCommandFrame>,
): VesselControlCommand => ({
  throttleTarget: frame.movement.forward,
  steeringTarget: frame.movement.steering,
  boost: hasAction(frame, PLAYER_COMMAND_ACTION.RUN_OR_BOOST),
  toggleLights: hasAction(frame, PLAYER_COMMAND_ACTION.TOGGLE_LIGHTS),
  horn: hasAction(frame, PLAYER_COMMAND_ACTION.HORN),
  requestReset: hasAction(frame, PLAYER_COMMAND_ACTION.RETURN_OR_RESET),
});

export const normalizeHeading = (heading: number): number => {
  const wrapped = ((heading + Math.PI) % (Math.PI * 2) + Math.PI * 2) %
    (Math.PI * 2);
  return wrapped - Math.PI;
};

export const resolveAimPoint = (
  frame: Readonly<PlayerCommandFrame>,
  originX: number,
  originZ: number,
  distance = 12,
): Pick<PenguinControlCommand, 'aimX' | 'aimZ'> => {
  const heading = frame.movement.aimHeading;
  if (heading === undefined) return {};
  return {
    aimX: originX + Math.sin(heading) * distance,
    aimZ: originZ + Math.cos(heading) * distance,
  };
};

export const actionBitsFromBulldozerCommand = (
  command: Readonly<BulldozerControlCommand>,
): number =>
  (command.requestExitVehicle ? PLAYER_COMMAND_ACTION.INTERACT : 0) |
  (command.cycleBladeMode ? PLAYER_COMMAND_ACTION.TOGGLE_TOOL_MODE : 0) |
  (command.toggleBeacon ? PLAYER_COMMAND_ACTION.TOGGLE_BEACON : 0) |
  (command.toggleLights ? PLAYER_COMMAND_ACTION.TOGGLE_LIGHTS : 0) |
  (command.horn ? PLAYER_COMMAND_ACTION.HORN : 0) |
  (command.requestReturn ? PLAYER_COMMAND_ACTION.RETURN_OR_RESET : 0);

export const actionBitsFromPenguinCommand = (
  command: Readonly<PenguinControlCommand>,
): number =>
  (command.requestEnterVehicle ? PLAYER_COMMAND_ACTION.INTERACT : 0) |
  (command.blower ? PLAYER_COMMAND_ACTION.PRIMARY_USE : 0) |
  (command.run ? PLAYER_COMMAND_ACTION.RUN_OR_BOOST : 0);

export const actionBitsFromVesselCommand = (
  command: Readonly<VesselControlCommand>,
): number =>
  (command.boost ? PLAYER_COMMAND_ACTION.RUN_OR_BOOST : 0) |
  (command.toggleLights ? PLAYER_COMMAND_ACTION.TOGGLE_LIGHTS : 0) |
  (command.horn ? PLAYER_COMMAND_ACTION.HORN : 0) |
  (command.requestReset ? PLAYER_COMMAND_ACTION.RETURN_OR_RESET : 0);
