import {
  BufferGeometry,
  Color,
  Float32BufferAttribute,
  Group,
  InstancedMesh,
  Matrix4,
  Mesh,
  MeshStandardMaterial,
  Quaternion,
  ShaderMaterial,
  Vector2,
  Vector3,
  type Scene,
} from 'three';
import type { TerrainHeightSystem } from '../../land/TerrainHeightSystem';
import {
  initialLandSnowDepth,
  visualLandSnowHeight,
} from '../../land/LandSnowData';
import type {
  WorldAssetPlacementSystem,
  WorldAssetRuntimeBatch,
  WorldAssetRuntimeSnowBatch,
} from '../../land/WorldAssetPlacementSystem';
import { WILDERNESS_SURVIVAL_REGION } from '../../survival/WildernessBiome';
import { WORLD_CLOUD_FIELD_GLSL } from '../../environment/WorldCloudField';
import { clamp, smoothstep } from '../../utils/math';
import { generatedWorldData, sampleGeneratedWorld } from './GeneratedWorldRuntime';
import { WORLD_AUTHORING_BOUNDS } from './GeneratedWorldConfig';
import type { GeneratedWorldLayer } from './GeneratedWorldTypes';
import { WINTER_WORLD_LOD } from '../WinterWorldLodPolicy';
import {
  clipHydrologyCell,
  triangulateContourFan,
} from './HydrologySurfaceMesher';

const VISUAL_CHUNK_METRES = 128;
const MACRO_RENDER_GRID_METRES = 8;
const VISUAL_RADIUS_CHUNKS = 1;
const FAR_VISUAL_RADIUS_CHUNKS = Math.ceil(
  WINTER_WORLD_LOD.ecologyHorizonMetres / VISUAL_CHUNK_METRES,
);
// One distant candidate cell is still cheap to evaluate, while a nearly
// cell-wide jitter plus deterministic satellites removes every visible row.
// The old 36 m lattice was sparse enough to read as planted timber rather
// than a boreal forest from an OTS camera.
const FAR_VISUAL_SPACING_METRES = 22;
const FAR_REBUILD_CHUNK_STRIDE = 4;
const AUTHORED_WILDERNESS_CLEAR_RADIUS = 102;
const GENERATED_COAST_TRANSITION_X = -430;
// Lakes now get a component-level level surface and rivers retain a sloped
// surface, so generated hydrology is safe to render instead of tinting the
// terrain blue and making apparent water climb hills.
const GENERATED_HYDROLOGY_VISUALS_ENABLED = true;

const deterministic = (x: number, z: number, seed: number): number => {
  let value = Math.imul(x ^ seed, 0x45d9f3b);
  value = Math.imul(value ^ z, 0x45d9f3b);
  value ^= value >>> 16;
  return (value >>> 0) / 0xffffffff;
};

interface ScatterInstance {
  readonly prefabId: string;
  readonly x: number;
  readonly z: number;
  readonly heading: number;
  readonly scale: number;
}

interface VisualScatterChunk {
  readonly root: Group;
  readonly batches: readonly WorldAssetRuntimeBatch[];
  readonly snowBatches: readonly WorldAssetRuntimeSnowBatch[];
  readonly chunkX: number;
  readonly chunkZ: number;
}

export type GeneratedWorldPresentationMode =
  | 'FULL'
  | 'TERRAIN_ONLY'
  | 'HIDDEN';

const chunkKey = (x: number, z: number): string => `${x},${z}`;

/**
 * Far macro terrain and bounded visual ecology. Detailed collision, authored
 * assets and deformable snow remain in their existing streamed systems.
 */
export class GeneratedWorldPresenter {
  private readonly root = new Group();
  private readonly macroSunDirection = new Vector3(0, 1, 0);
  private readonly macroSunStrength = { value: 1 };
  private readonly macroDistantSnowEnabled = { value: 1 };
  private readonly macroTerrainOnly = { value: 0 };
  private readonly macroCloudTime = { value: 0 };
  private readonly macroCloudCover = { value: 0 };
  private readonly macroCloudDirection = { value: [1, 0] as [number, number] };
  private readonly macroViewerPosition = { value: new Vector2() };
  private readonly terrainMaterial = new MeshStandardMaterial({
    color: 0xffffff,
    vertexColors: true,
    roughness: 0.99,
    metalness: 0,
    polygonOffset: true,
    polygonOffsetFactor: 1,
    polygonOffsetUnits: 2,
  });
  private readonly waterMaterial = new ShaderMaterial({
    name: 'Generated hydrology · cold flowing water',
    uniforms: {
      uTime: { value: 0 },
      uDeep: { value: new Color(0x275f72) },
      uShallow: { value: new Color(0x75c2ca) },
      uSunDirection: { value: new Vector3(0, 1, 0) },
      uMoonDirection: { value: new Vector3(0, -1, 0) },
      uSunIntensity: { value: 1 },
      uMoonIntensity: { value: 0 },
      uFreeze: { value: 0.72 },
    },
    vertexShader: `
      attribute float aFlow;
      attribute float aShore;
      varying vec3 vWorld;
      varying float vFlow;
      varying float vShore;
      uniform float uTime;
      void main() {
        vec3 p = position;
        p.y += sin((p.x + p.z) * 0.19 - uTime * (0.7 + aFlow * 1.4)) * 0.018;
        vec4 world = modelMatrix * vec4(p, 1.0);
        vWorld = world.xyz;
        vFlow = aFlow;
        vShore = aShore;
        gl_Position = projectionMatrix * viewMatrix * world;
      }
    `,
    fragmentShader: `
      varying vec3 vWorld;
      varying float vFlow;
      varying float vShore;
      uniform float uTime;
      uniform vec3 uDeep;
      uniform vec3 uShallow;
      uniform vec3 uSunDirection;
      uniform vec3 uMoonDirection;
      uniform float uSunIntensity;
      uniform float uMoonIntensity;
      uniform float uFreeze;
      void main() {
        float bands = sin((vWorld.x * 0.31 + vWorld.z * 0.23) - uTime * (1.1 + vFlow));
        float glint = pow(max(0.0, bands), 12.0) * 0.22;
        vec3 color = mix(uShallow, uDeep, 0.42 + vFlow * 0.32);
        color = mix(vec3(0.39, 0.58, 0.59), color, 0.38 + vShore * 0.62);
        color += vec3(0.36, 0.48, 0.48) * glint;
        float cameraDistance = distance(cameraPosition.xz, vWorld.xz);
        // Ordinary blue water belongs to the readable mid-ground. Only the
        // narrow, correctly aligned celestial streak is allowed to survive in
        // the far landscape; this prevents hydrology quads glowing through
        // haze on the side opposite the sun or moon.
        float localVisibility = 1.0 - smoothstep(280.0, 610.0, cameraDistance);
        vec3 viewDirection = normalize(cameraPosition - vWorld);
        vec3 surfaceNormal = vec3(0.0, 1.0, 0.0);
        vec3 reflectedSun = reflect(-normalize(uSunDirection), surfaceNormal);
        vec3 reflectedMoon = reflect(-normalize(uMoonDirection), surfaceNormal);
        float solarReflection = pow(
          max(dot(viewDirection, reflectedSun), 0.0),
          156.0
        ) * smoothstep(-0.015, 0.055, uSunDirection.y) *
          clamp(uSunIntensity, 0.0, 1.25);
        float lunarReflection = pow(
          max(dot(viewDirection, reflectedMoon), 0.0),
          176.0
        ) * smoothstep(-0.015, 0.055, uMoonDirection.y) *
          clamp(uMoonIntensity, 0.0, 1.15);
        // A narrow celestial streak may reveal otherwise distant ice. It is
        // still directional: the old all-direction cyan resurrection cannot
        // appear on the side opposite both reflected bodies.
        float celestialReflection = solarReflection + lunarReflection * 0.88;
        float distantReflection = celestialReflection *
          (1.0 - smoothstep(1120.0, 1900.0, cameraDistance)) *
          mix(1.0, 0.18, uFreeze);
        color = mix(
          color,
          vec3(0.86, 0.9, 0.84),
          clamp(distantReflection * 0.86, 0.0, 0.92)
        );
        float alpha = 0.72 * localVisibility + distantReflection * 0.34;
        if (alpha < 0.008) discard;
        gl_FragColor = vec4(color, alpha);
      }
    `,
    transparent: true,
    depthWrite: false,
  });
  private readonly iceMaterial = new ShaderMaterial({
    name: 'Generated hydrology · current-aware ice',
    uniforms: {
      uFreeze: { value: 0.72 },
      uTime: { value: 0 },
      uSunDirection: { value: new Vector3(0, 1, 0) },
      uMoonDirection: { value: new Vector3(0, -1, 0) },
      uSunIntensity: { value: 1 },
      uMoonIntensity: { value: 0 },
    },
    vertexShader: `
      attribute float aFlow;
      attribute float aShore;
      varying float vFlow;
      varying float vShore;
      varying vec3 vWorld;
      void main() {
        vFlow = aFlow;
        vShore = aShore;
        vec4 world = modelMatrix * vec4(position, 1.0);
        vWorld = world.xyz;
        gl_Position = projectionMatrix * viewMatrix * world;
      }
    `,
    fragmentShader: `
      varying float vFlow;
      varying float vShore;
      varying vec3 vWorld;
      uniform float uFreeze;
      uniform float uTime;
      uniform vec3 uSunDirection;
      uniform vec3 uMoonDirection;
      uniform float uSunIntensity;
      uniform float uMoonIntensity;
      void main() {
        float localFreeze = clamp(uFreeze - vFlow * 0.48, 0.0, 1.0);
        if (localFreeze < 0.08) discard;
        float grain = sin(vWorld.x * 0.42 + sin(vWorld.z * 0.28) * 1.7 + uTime * 0.025);
        vec3 ice = mix(vec3(0.38, 0.68, 0.72), vec3(0.77, 0.91, 0.91), 0.5 + grain * 0.12);
        ice = mix(vec3(0.48, 0.65, 0.66), ice, 0.32 + vShore * 0.68);
        float cameraDistance = distance(cameraPosition.xz, vWorld.xz);
        float localVisibility = 1.0 - smoothstep(300.0, 650.0, cameraDistance);
        vec3 viewDirection = normalize(cameraPosition - vWorld);
        vec3 surfaceNormal = vec3(0.0, 1.0, 0.0);
        vec3 reflectedSun = reflect(-normalize(uSunDirection), surfaceNormal);
        vec3 reflectedMoon = reflect(-normalize(uMoonDirection), surfaceNormal);
        float solarReflection = pow(
          max(dot(viewDirection, reflectedSun), 0.0),
          176.0
        ) * smoothstep(-0.015, 0.055, uSunDirection.y) *
          clamp(uSunIntensity, 0.0, 1.25);
        float lunarReflection = pow(
          max(dot(viewDirection, reflectedMoon), 0.0),
          196.0
        ) * smoothstep(-0.015, 0.055, uMoonDirection.y) *
          clamp(uMoonIntensity, 0.0, 1.15);
        float celestialReflection = (solarReflection + lunarReflection * 0.94) *
          (1.0 - smoothstep(1180.0, 1950.0, cameraDistance));
        ice = mix(
          ice,
          vec3(0.84, 0.89, 0.87),
          clamp(celestialReflection * 0.9, 0.0, 0.94)
        );
        float alpha = localFreeze * (
          localVisibility * 0.7 + celestialReflection * 0.38
        );
        if (alpha < 0.008) discard;
        gl_FragColor = vec4(ice, alpha);
      }
    `,
    transparent: true,
    depthWrite: false,
  });
  private terrainMesh?: Mesh;
  private waterMesh?: Mesh;
  private iceMesh?: Mesh;
  private layer: GeneratedWorldLayer = 'FINAL';
  private readonly scatterChunks = new Map<string, VisualScatterChunk>();
  private farScatterRoot?: Group;
  private farScatterBatches: WorldAssetRuntimeBatch[] = [];
  private farScatterSnowBatches: WorldAssetRuntimeSnowBatch[] = [];
  private farAnchorChunkX?: number;
  private farAnchorChunkZ?: number;
  private centerChunkX?: number;
  private centerChunkZ?: number;
  private presentationMode: GeneratedWorldPresentationMode = 'FULL';
  private rebuildScheduled = false;
  private readonly removeTerrainListener: () => void;
  private readonly removeAssetListener: () => void;
  private disposed = false;

  public constructor(
    scene: Scene,
    private readonly terrain: TerrainHeightSystem,
    private readonly assets: WorldAssetPlacementSystem,
  ) {
    this.root.name = 'Generated macro world · terrain, hydrology and visual ecology';
    this.configureMacroTerrainLighting();
    scene.add(this.root);
    this.buildMacroMeshes();
    this.removeTerrainListener = terrain.addListener(() => this.scheduleTerrainRebuild());
    this.removeAssetListener = assets.addVisualListener(() => this.rebuildScatter());
  }

  public setDebugLayer(layer: GeneratedWorldLayer): void {
    if (this.layer === layer) return;
    this.layer = layer;
    this.macroDistantSnowEnabled.value = layer === 'FINAL' ? 1 : 0;
    this.updateTerrainColors();
  }

  public getDebugLayer(): GeneratedWorldLayer {
    return this.layer;
  }

  /** Backwards-compatible visibility switch for the complete generated world. */
  public setVisible(visible: boolean): void {
    this.setPresentationMode(visible ? 'FULL' : 'HIDDEN');
  }

  /**
   * Keeps the large terrain underlay available to an authored flat world
   * without leaking generated water, forests, rocks or other ecology into it.
   */
  public setPresentationMode(mode: GeneratedWorldPresentationMode): void {
    if (this.presentationMode === mode) {
      this.syncPresentationMode();
      return;
    }
    const previous = this.presentationMode;
    this.presentationMode = mode;
    if (mode !== 'HIDDEN') {
      // Workspace switches replace the complete terrain profile immediately.
      // Do not leave the asynchronous listener as the sole owner here: a
      // queued GAME rebuild can otherwise win the frame and keep its relief
      // under an already-open blank DRAFT until another edit occurs.
      this.rebuildTerrainGeometry();
    }
    this.syncPresentationMode();
    if (mode === 'FULL' && previous !== 'FULL') {
      // The terrain-only workspace intentionally pauses ecology streaming.
      // Force one refresh when returning so its close and far rings catch up
      // with a camera that may have travelled in the editor.
      this.centerChunkX = undefined;
      this.centerChunkZ = undefined;
      this.farAnchorChunkX = undefined;
      this.farAnchorChunkZ = undefined;
    }
  }

  public updateCenter(x: number, z: number): void {
    // Surface ownership is radial and must track sub-chunk movement. The
    // scatter stream itself can still retain its coarse chunk hysteresis.
    this.macroViewerPosition.value.set(x, z);
    if (this.presentationMode !== 'FULL') return;
    const nextX = Math.floor(x / VISUAL_CHUNK_METRES);
    const nextZ = Math.floor(z / VISUAL_CHUNK_METRES);
    if (this.centerChunkX === nextX && this.centerChunkZ === nextZ) return;
    this.centerChunkX = nextX;
    this.centerChunkZ = nextZ;
    const wanted = new Set<string>();
    for (let dz = -VISUAL_RADIUS_CHUNKS; dz <= VISUAL_RADIUS_CHUNKS; dz += 1) {
      for (let dx = -VISUAL_RADIUS_CHUNKS; dx <= VISUAL_RADIUS_CHUNKS; dx += 1) {
        const chunkX = nextX + dx;
        const chunkZ = nextZ + dz;
        const key = chunkKey(chunkX, chunkZ);
        wanted.add(key);
        if (!this.scatterChunks.has(key)) {
          const created = this.createScatterChunk(chunkX, chunkZ);
          if (created) {
            created.root.visible = this.presentationMode === 'FULL';
            this.scatterChunks.set(key, created);
            this.root.add(created.root);
          }
        }
      }
    }
    for (const [key, chunk] of this.scatterChunks) {
      if (wanted.has(key)) continue;
      this.disposeScatterChunk(chunk);
      this.scatterChunks.delete(key);
    }
    this.updateScatterShadowLod();
    this.rebuildFarScatter();
  }

  public updateEnvironment(
    worldTime: number,
    temperatureCelsius: number,
    sunAzimuth: number,
    sunHeight: number,
    moonAzimuth: number,
    moonHeight: number,
    sunIntensity = 1,
    moonIntensity = 0,
    cloudCover = 0,
    windDirectionX = 1,
    windDirectionZ = 0,
  ): void {
    this.waterMaterial.uniforms.uTime!.value = worldTime;
    this.iceMaterial.uniforms.uTime!.value = worldTime;
    const freeze = clamp(
      -temperatureCelsius / 13,
      0,
      1,
    );
    this.waterMaterial.uniforms.uFreeze!.value = freeze;
    this.iceMaterial.uniforms.uFreeze!.value = freeze;
    const vertical = clamp(sunHeight, -0.24, 0.92);
    const horizontal = Math.sqrt(Math.max(0, 1 - vertical * vertical));
    const sunDirection = this.waterMaterial.uniforms.uSunDirection!.value as
      Vector3;
    sunDirection.set(
      Math.cos(sunAzimuth) * horizontal,
      vertical,
      Math.sin(sunAzimuth) * horizontal,
    ).normalize();
    (this.iceMaterial.uniforms.uSunDirection!.value as Vector3).copy(
      sunDirection,
    );
    this.macroSunDirection.copy(sunDirection);
    this.macroSunStrength.value = clamp(
      sunIntensity * smoothstep(-0.035, 0.1, sunDirection.y),
      0,
      1,
    );
    this.macroCloudTime.value = Math.max(0, worldTime);
    this.macroCloudCover.value = clamp(cloudCover, 0, 1);
    const windLength = Math.max(
      0.0001,
      Math.hypot(windDirectionX, windDirectionZ),
    );
    this.macroCloudDirection.value[0] = windDirectionX / windLength;
    this.macroCloudDirection.value[1] = windDirectionZ / windLength;
    const moonVertical = clamp(moonHeight, -0.36, 0.92);
    const moonHorizontal = Math.sqrt(Math.max(
      0,
      1 - moonVertical * moonVertical,
    ));
    const moonDirection = this.waterMaterial.uniforms.uMoonDirection!.value as
      Vector3;
    moonDirection.set(
      Math.cos(moonAzimuth) * moonHorizontal,
      moonVertical,
      Math.sin(moonAzimuth) * moonHorizontal,
    ).normalize();
    (this.iceMaterial.uniforms.uMoonDirection!.value as Vector3).copy(
      moonDirection,
    );
    for (const material of [this.waterMaterial, this.iceMaterial]) {
      material.uniforms.uSunIntensity!.value = clamp(sunIntensity, 0, 1.25);
      material.uniforms.uMoonIntensity!.value = clamp(moonIntensity, 0, 1.15);
    }
  }

  public dispose(): void {
    this.disposed = true;
    this.removeTerrainListener();
    this.removeAssetListener();
    for (const chunk of this.scatterChunks.values()) this.disposeScatterChunk(chunk);
    this.scatterChunks.clear();
    this.disposeFarScatter();
    this.terrainMesh?.geometry.dispose();
    this.waterMesh?.geometry.dispose();
    this.iceMesh?.geometry.dispose();
    this.terrainMaterial.dispose();
    this.waterMaterial.dispose();
    this.iceMaterial.dispose();
    this.root.removeFromParent();
  }

  private buildMacroMeshes(): void {
    const data = generatedWorldData();
    if (!data) return;
    const terrainGeometry = this.createTerrainGeometry();
    this.terrainMesh = new Mesh(terrainGeometry, this.terrainMaterial);
    this.terrainMesh.name = 'Generated distant terrain underlay';
    this.terrainMesh.receiveShadow = true;
    this.terrainMesh.castShadow = false;
    this.root.add(this.terrainMesh);
    if (GENERATED_HYDROLOGY_VISUALS_ENABLED) {
      const waterGeometry = this.createHydrologyGeometry();
      this.waterMesh = new Mesh(waterGeometry, this.waterMaterial);
      this.waterMesh.name = 'Generated lakes and river ribbons';
      this.waterMesh.renderOrder = 3;
      this.root.add(this.waterMesh);
      this.iceMesh = new Mesh(waterGeometry.clone(), this.iceMaterial);
      this.iceMesh.name = 'Generated freezing layer';
      this.iceMesh.position.y = 0.025;
      this.iceMesh.renderOrder = 4;
      this.root.add(this.iceMesh);
    }
    this.syncPresentationMode();
  }

  private syncPresentationMode(): void {
    const visible = this.presentationMode !== 'HIDDEN';
    const full = this.presentationMode === 'FULL';
    this.root.visible = visible;
    if (this.terrainMesh) this.terrainMesh.visible = visible;
    if (this.waterMesh) this.waterMesh.visible = full;
    if (this.iceMesh) this.iceMesh.visible = full;
    for (const chunk of this.scatterChunks.values()) {
      chunk.root.visible = full;
    }
    if (this.farScatterRoot) this.farScatterRoot.visible = full;
    this.macroTerrainOnly.value = this.presentationMode === 'TERRAIN_ONLY'
      ? 1
      : 0;
  }

  /**
   * The nearby shadow map intentionally covers only the playable bubble. A
   * two-kilometre shadow camera would destroy its resolution and cost. This
   * normal-based grade keeps a distant mountain's sunward and sheltered faces
   * readable through atmospheric haze without adding a draw pass or texture.
   */
  private configureMacroTerrainLighting(): void {
    this.terrainMaterial.onBeforeCompile = (shader) => {
      shader.uniforms.uMacroSunDirection = { value: this.macroSunDirection };
      shader.uniforms.uMacroSunStrength = this.macroSunStrength;
      shader.uniforms.uMacroDistantSnowEnabled =
        this.macroDistantSnowEnabled;
      shader.uniforms.uMacroTerrainOnly = this.macroTerrainOnly;
      shader.uniforms.uMacroCloudTime = this.macroCloudTime;
      shader.uniforms.uMacroCloudCover = this.macroCloudCover;
      shader.uniforms.uMacroCloudDirection = this.macroCloudDirection;
      shader.uniforms.uMacroViewerPosition = this.macroViewerPosition;
      shader.vertexShader = shader.vertexShader
        .replace(
          '#include <common>',
          '#include <common>\n' +
            'attribute float aDistantSnowLift;\n' +
            'attribute float aMacroSafetyDrop;\n' +
            'varying vec3 vMacroWorldNormal;\n' +
            'varying float vMacroCloudShadow;\n' +
            'varying float vMacroSnowColour;\n' +
            'varying float vMacroDistantSnow;\n' +
            'uniform float uMacroDistantSnowEnabled;\n' +
            'uniform float uMacroTerrainOnly;\n' +
            'uniform float uMacroCloudTime;\n' +
            'uniform float uMacroCloudCover;\n' +
            'uniform vec2 uMacroCloudDirection;\n' +
            'uniform vec2 uMacroViewerPosition;\n' +
            WORLD_CLOUD_FIELD_GLSL,
        )
        .replace(
          '#include <begin_vertex>',
          `
            #include <begin_vertex>
            vec4 macroGroundWorld = modelMatrix * vec4(transformed, 1.0);
            float macroViewerDistance = distance(
              uMacroViewerPosition,
              macroGroundWorld.xz
            );
            // One visible owner at a time: medium snow remains above this
            // underlay throughout the overlap. The conservative per-vertex
            // drop additionally guarantees that an 8 m triangle cannot cut
            // through a curved two-metre/25 cm surface on a hillside.
            float macroDistanceOwnership = smoothstep(
              ${WINTER_WORLD_LOD.macroOwnershipFadeStartMetres.toFixed(1)},
              ${WINTER_WORLD_LOD.macroOwnershipFadeEndMetres.toFixed(1)},
              macroViewerDistance
            );
            // The authoring view uses one hard owner at a time. Blending two
            // opaque surfaces by sinking both halfway formed metre-deep rings
            // that looked like terrain relief on an otherwise flat draft.
            float macroAuthoringOwnership = step(
              ${((WINTER_WORLD_LOD.macroOwnershipFadeStartMetres + WINTER_WORLD_LOD.macroOwnershipFadeEndMetres) * 0.5).toFixed(1)},
              macroViewerDistance
            );
            float macroOwnership = mix(
              macroDistanceOwnership,
              macroAuthoringOwnership,
              uMacroTerrainOnly
            );
            vMacroDistantSnow = macroOwnership *
              uMacroDistantSnowEnabled * step(0.001, aDistantSnowLift);
            vMacroSnowColour = uMacroDistantSnowEnabled *
              step(0.001, aDistantSnowLift);
            transformed.y += aDistantSnowLift * vMacroDistantSnow;
            transformed.y -= aMacroSafetyDrop;
            transformed.y -= (1.0 - macroOwnership) *
              ${WINTER_WORLD_LOD.hiddenSurfaceSinkMetres.toFixed(2)};
            vec3 macroCloudWorldPosition =
              (modelMatrix * vec4(transformed, 1.0)).xyz;
            vMacroCloudShadow = icewayWorldCloudShadow(
              macroCloudWorldPosition.xz,
              uMacroCloudTime,
              uMacroCloudDirection,
              uMacroCloudCover
            );
          `,
        )
        .replace(
          '#include <beginnormal_vertex>',
          '#include <beginnormal_vertex>\n' +
            'vMacroWorldNormal = normalize(mat3(modelMatrix) * objectNormal);',
        );
      shader.fragmentShader = shader.fragmentShader
        .replace(
          '#include <common>',
          '#include <common>\n' +
            'varying vec3 vMacroWorldNormal;\n' +
            'varying float vMacroCloudShadow;\n' +
            'varying float vMacroSnowColour;\n' +
            'varying float vMacroDistantSnow;\n' +
            'uniform vec3 uMacroSunDirection;\n' +
            'uniform float uMacroSunStrength;\n' +
            'uniform float uMacroCloudCover;\n' +
            'uniform float uMacroTerrainOnly;',
        )
        .replace(
          '#include <color_fragment>',
          `
            #include <color_fragment>
            vec3 macroDistantSnowColour = mix(
              vec3(0.80, 0.86, 0.87),
              vec3(0.92, 0.96, 0.97),
              smoothstep(-0.1, 0.72, normalize(vMacroWorldNormal).y)
            );
            // A clean blank authoring canvas must not make its LOD boundary
            // look like terrain relief. Match the neutral two-metre snow base
            // while leaving the atmospheric GAME presentation untouched.
            macroDistantSnowColour = mix(
              macroDistantSnowColour,
              vec3(0.82, 0.86, 0.89),
              uMacroTerrainOnly
            );
            diffuseColor.rgb = mix(
              diffuseColor.rgb,
              macroDistantSnowColour,
              vMacroSnowColour * 0.97
            );
          `,
        )
        .replace(
          '#include <opaque_fragment>',
          `
            float macroSunFacing = dot(
              normalize(vMacroWorldNormal),
              normalize(uMacroSunDirection)
            );
            float macroSlopeGrade = mix(
              0.72,
              1.08,
              smoothstep(-0.48, 0.68, macroSunFacing)
            );
            outgoingLight *= mix(
              1.0,
              macroSlopeGrade,
              clamp(uMacroSunStrength, 0.0, 1.0) *
                (1.0 - uMacroTerrainOnly)
            );
            float macroCloudShadow = clamp(vMacroCloudShadow, 0.0, 1.0) *
              (1.0 - uMacroTerrainOnly);
            outgoingLight *= 1.0 - macroCloudShadow *
              (0.16 + clamp(uMacroCloudCover, 0.0, 1.0) * 0.34);
            #include <opaque_fragment>
          `,
        );
    };
    this.terrainMaterial.customProgramCacheKey = () =>
      'iceway-generated-macro-terrain-owned-snow-v5';
  }

  private createTerrainGeometry(): BufferGeometry {
    const data = generatedWorldData();
    const geometry = new BufferGeometry();
    if (!data) return geometry;
    const bounds = this.presentationMode === 'TERRAIN_ONLY'
      ? WORLD_AUTHORING_BOUNDS
      : data.config.bounds;
    const renderWidth = Math.round(
      (bounds.maxX - bounds.minX) /
        MACRO_RENDER_GRID_METRES,
    ) + 1;
    const renderHeight = Math.round(
      (bounds.maxZ - bounds.minZ) /
        MACRO_RENDER_GRID_METRES,
    ) + 1;
    const positions = new Float32Array(renderWidth * renderHeight * 3);
    const colors = new Float32Array(renderWidth * renderHeight * 3);
    const distantSnowLift = new Float32Array(renderWidth * renderHeight);
    const targetSurface = new Float32Array(renderWidth * renderHeight);
    const safetyDrop = new Float32Array(renderWidth * renderHeight);
    const indices: number[] = [];
    const baselineSnowDepth = (x: number, z: number): number => {
      return this.presentationMode === 'TERRAIN_ONLY'
        ? 0.52
        : initialLandSnowDepth(x, z);
    };
    const sampleTargetSurface = (x: number, z: number): number => {
      const snowDepth = baselineSnowDepth(x, z);
      return this.terrain.sampleHeight(x, z) + 0.012 +
        visualLandSnowHeight(snowDepth, 0);
    };
    for (let row = 0; row < renderHeight; row += 1) {
      const z = bounds.minZ + row * MACRO_RENDER_GRID_METRES;
      for (let column = 0; column < renderWidth; column += 1) {
        const x = bounds.minX + column * MACRO_RENDER_GRID_METRES;
        const index = row * renderWidth + column;
        positions[index * 3] = x;
        const snowDepth = baselineSnowDepth(x, z);
        // Keep the actual terrain safely below every deformable near-snow
        // state, including completely cleared ground. The shader raises it to
        // baseline snow height only beyond the 285-365 m horizon transition.
        positions[index * 3 + 1] = this.terrain.sampleHeight(x, z) - 0.115;
        distantSnowLift[index] = snowDepth > 0.001
          ? 0.127 + visualLandSnowHeight(snowDepth, 0)
          : 0;
        targetSurface[index] = this.terrain.sampleHeight(x, z) + 0.012 +
          visualLandSnowHeight(snowDepth, 0);
        positions[index * 3 + 2] = z;
        const color = this.colorForPoint(x, z);
        colors[index * 3] = color.r;
        colors[index * 3 + 1] = color.g;
        colors[index * 3 + 2] = color.b;
        if (row >= renderHeight - 1 || column >= renderWidth - 1) continue;
        const next = index + renderWidth;
        indices.push(index, next, index + 1, index + 1, next, next + 1);
      }
    }
    // An 8 m bilinear triangle may bridge above a sharp valley or edited
    // shoulder even though each of its corner vertices is below the detailed
    // surface. Measure that possible overshoot inside every macro cell and
    // push the complete cell safely down. This is conservative by design: a
    // tiny extra gap hidden by the medium surface is preferable to one bright
    // square cutting through a hill.
    const probes = [1 / 3, 0.5, 2 / 3] as const;
    for (let row = 0; row < renderHeight - 1; row += 1) {
      const z0 = bounds.minZ + row * MACRO_RENDER_GRID_METRES;
      for (let column = 0; column < renderWidth - 1; column += 1) {
        const x0 = bounds.minX + column * MACRO_RENDER_GRID_METRES;
        const a = row * renderWidth + column;
        const b = a + 1;
        const c = a + renderWidth;
        const d = c + 1;
        let maximumOvershoot = 0;
        for (const tz of probes) {
          for (const tx of probes) {
            const near = targetSurface[a]! * (1 - tx) +
              targetSurface[b]! * tx;
            const far = targetSurface[c]! * (1 - tx) +
              targetSurface[d]! * tx;
            const interpolated = near * (1 - tz) + far * tz;
            const actual = sampleTargetSurface(
              x0 + tx * MACRO_RENDER_GRID_METRES,
              z0 + tz * MACRO_RENDER_GRID_METRES,
            );
            maximumOvershoot = Math.max(
              maximumOvershoot,
              interpolated - actual,
            );
          }
        }
        const conservativeDrop = Math.max(0.035, maximumOvershoot + 0.045);
        safetyDrop[a] = Math.max(safetyDrop[a]!, conservativeDrop);
        safetyDrop[b] = Math.max(safetyDrop[b]!, conservativeDrop);
        safetyDrop[c] = Math.max(safetyDrop[c]!, conservativeDrop);
        safetyDrop[d] = Math.max(safetyDrop[d]!, conservativeDrop);
      }
    }
    geometry.setAttribute('position', new Float32BufferAttribute(positions, 3));
    geometry.setAttribute('color', new Float32BufferAttribute(colors, 3));
    geometry.setAttribute(
      'aDistantSnowLift',
      new Float32BufferAttribute(distantSnowLift, 1),
    );
    geometry.setAttribute(
      'aMacroSafetyDrop',
      new Float32BufferAttribute(safetyDrop, 1),
    );
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    geometry.computeBoundingSphere();
    return geometry;
  }

  private createHydrologyGeometry(): BufferGeometry {
    const data = generatedWorldData();
    const geometry = new BufferGeometry();
    if (!data) return geometry;
    const positions: number[] = [];
    const flowValues: number[] = [];
    const shoreValues: number[] = [];
    const indices: number[] = [];
    const appendQuad = (
      corners: readonly (readonly [number, number, number])[],
      flow: number,
    ): void => {
      const base = positions.length / 3;
      for (const corner of corners) {
        positions.push(corner[0], corner[1], corner[2]);
        flowValues.push(flow);
        shoreValues.push(flow > 0.04 ? 0.82 : 1);
      }
      indices.push(base, base + 2, base + 1, base + 1, base + 2, base + 3);
    };
    const appendLakeContour = (
      contour: ReturnType<typeof clipHydrologyCell>,
      surface: number,
    ): void => {
      if (contour.length < 3) return;
      const base = positions.length / 3;
      for (const vertex of contour) {
        positions.push(vertex.x, surface, vertex.z);
        flowValues.push(0.02);
        shoreValues.push(smoothstep(0.1, 0.58, vertex.strength));
      }
      indices.push(...triangulateContourFan(contour.length, base));
    };
    const step = data.config.cellSizeMetres;
    const lakeSubdivisions = 4;
    const lakeStep = step / lakeSubdivisions;
    const sampleLakeStrength = (gridX: number, gridZ: number): number => {
      const clampedX = clamp(gridX, 0, data.width - 1);
      const clampedZ = clamp(gridZ, 0, data.height - 1);
      const x0 = Math.floor(clampedX);
      const z0 = Math.floor(clampedZ);
      const x1 = Math.min(data.width - 1, x0 + 1);
      const z1 = Math.min(data.height - 1, z0 + 1);
      const tx = clampedX - x0;
      const tz = clampedZ - z0;
      const near = (data.lake[z0 * data.width + x0] ?? 0) * (1 - tx) +
        (data.lake[z0 * data.width + x1] ?? 0) * tx;
      const far = (data.lake[z1 * data.width + x0] ?? 0) * (1 - tx) +
        (data.lake[z1 * data.width + x1] ?? 0) * tx;
      return (near * (1 - tz) + far * tz) / 255;
    };
    // Priority-flood supplies a water surface per cell. Resolve every
    // connected lake to one representative spill height before authoring
    // quads. A lake is horizontal; only its basin floor and shoreline belong
    // to the terrain heightfield.
    const flatLakeSurface = new Float32Array(data.lake.length);
    flatLakeSurface.fill(Number.NaN);
    const visited = new Uint8Array(data.lake.length);
    for (let seedIndex = 0; seedIndex < data.lake.length; seedIndex += 1) {
      if (visited[seedIndex] || (data.lake[seedIndex] ?? 0) < 26) continue;
      const stack = [seedIndex];
      const component: number[] = [];
      const quantizedLevels = new Map<number, number>();
      visited[seedIndex] = 1;
      while (stack.length > 0) {
        const index = stack.pop()!;
        component.push(index);
        const levelKey = Math.round((data.waterSurface[index] ?? 0) * 20);
        quantizedLevels.set(levelKey, (quantizedLevels.get(levelKey) ?? 0) + 1);
        const row = Math.floor(index / data.width);
        const column = index - row * data.width;
        const neighbours = [
          column > 0 ? index - 1 : -1,
          column < data.width - 1 ? index + 1 : -1,
          row > 0 ? index - data.width : -1,
          row < data.height - 1 ? index + data.width : -1,
        ];
        for (const neighbour of neighbours) {
          if (
            neighbour < 0 || visited[neighbour] ||
            (data.lake[neighbour] ?? 0) < 26
          ) continue;
          visited[neighbour] = 1;
          stack.push(neighbour);
        }
      }
      let resolvedKey = 0;
      let resolvedCount = -1;
      for (const [levelKey, count] of quantizedLevels) {
        if (count <= resolvedCount) continue;
        resolvedKey = levelKey;
        resolvedCount = count;
      }
      const resolvedSurface = resolvedKey / 20 + 0.025;
      for (const index of component) flatLakeSurface[index] = resolvedSurface;
    }
    for (let row = 1; row < data.height - 1; row += 1) {
      const z = data.config.bounds.minZ + row * step;
      for (let column = 1; column < data.width - 1; column += 1) {
        const x = data.config.bounds.minX + column * step;
        if (x > GENERATED_COAST_TRANSITION_X || this.inAuthoredWilderness(x, z)) continue;
        const index = row * data.width + column;
        const river = (data.river[index] ?? 0) / 255;
        const lake = (data.lake[index] ?? 0) / 255;
        const surface = data.waterSurface[index]! + 0.025;
        if (lake >= 0.035) {
          const lakeSurface = Number.isFinite(flatLakeSurface[index])
            ? flatLakeSurface[index]!
            : surface;
          // Subdivide only retained water cells. Four-metre shoreline pieces
          // remove the former 16 m plates, while the component-resolved Y
          // keeps every lake physically level.
          for (let subZ = 0; subZ < lakeSubdivisions; subZ += 1) {
            for (let subX = 0; subX < lakeSubdivisions; subX += 1) {
              const minX = x - step * 0.5 + subX * lakeStep;
              const minZ = z - step * 0.5 + subZ * lakeStep;
              const minGridX = column - 0.5 + subX / lakeSubdivisions;
              const minGridZ = row - 0.5 + subZ / lakeSubdivisions;
              const maxGridX = minGridX + 1 / lakeSubdivisions;
              const maxGridZ = minGridZ + 1 / lakeSubdivisions;
              const contour = clipHydrologyCell([
                {
                  x: minX,
                  z: minZ,
                  strength: sampleLakeStrength(minGridX, minGridZ),
                },
                {
                  x: minX + lakeStep,
                  z: minZ,
                  strength: sampleLakeStrength(maxGridX, minGridZ),
                },
                {
                  x: minX + lakeStep,
                  z: minZ + lakeStep,
                  strength: sampleLakeStrength(maxGridX, maxGridZ),
                },
                {
                  x: minX,
                  z: minZ + lakeStep,
                  strength: sampleLakeStrength(minGridX, maxGridZ),
                },
              ], 0.1);
              appendLakeContour(contour, lakeSurface);
            }
          }
        }
        if (river < 0.1 || lake > 0.38) continue;
        const dx = data.flowDirectionX[index] ?? 0;
        const dz = data.flowDirectionZ[index] ?? 0;
        const length = Math.hypot(dx, dz);
        if (length < 0.5) continue;
        const flowX = dx / length;
        const flowZ = dz / length;
        const sideX = -flowZ;
        const sideZ = flowX;
        const halfWidth = 0.65 + river * 3.8;
        const startX = x - flowX * step * 0.12;
        const startZ = z - flowZ * step * 0.12;
        const endX = x + flowX * step * 1.12;
        const endZ = z + flowZ * step * 1.12;
        const downstreamSurface = sampleGeneratedWorld(endX, endZ).waterSurface +
          0.025;
        appendQuad([
          [startX - sideX * halfWidth, surface, startZ - sideZ * halfWidth],
          [startX + sideX * halfWidth, surface, startZ + sideZ * halfWidth],
          [endX - sideX * halfWidth, downstreamSurface, endZ - sideZ * halfWidth],
          [endX + sideX * halfWidth, downstreamSurface, endZ + sideZ * halfWidth],
        ], river);
      }
    }
    geometry.setAttribute('position', new Float32BufferAttribute(positions, 3));
    geometry.setAttribute('aFlow', new Float32BufferAttribute(flowValues, 1));
    geometry.setAttribute('aShore', new Float32BufferAttribute(shoreValues, 1));
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    geometry.computeBoundingSphere();
    return geometry;
  }

  private colorForPoint(x: number, z: number): Color {
    const data = generatedWorldData();
    if (!data) return new Color(0x9aa7a1);
    const sample = sampleGeneratedWorld(x, z);
    if (this.layer === 'WATER') {
      return new Color(0x313b40).lerp(
        new Color(0x46c4dc),
        sample.water,
      );
    }
    if (this.layer === 'MOISTURE') {
      return new Color(0xc9b780).lerp(new Color(0x397d89), sample.moisture);
    }
    if (this.layer === 'FOREST') {
      return new Color(0xd1d0bd).lerp(new Color(0x214c3f), sample.forest);
    }
    if (this.layer === 'ROCKINESS') {
      return new Color(0xc8d0ca).lerp(new Color(0x4a5250), sample.rockiness);
    }
    if (this.layer === 'FUEL') {
      return new Color(0x403730).lerp(new Color(0xe58a45), sample.fuel);
    }
    if (this.layer === 'HEIGHT') {
      return new Color(0x48696a).lerp(
        new Color(0xe9eeea),
        clamp((sample.elevation - 1) / 100, 0, 1),
      );
    }
    return new Color(0xb9cbc4)
      .lerp(new Color(0x72867c), sample.moisture * 0.24)
      .lerp(new Color(0x48534f), sample.rockiness * 0.42)
      .lerp(new Color(0x526d61), sample.forest * 0.22)
      // A very light damp-bank grade can remain, but the actual blue water is
      // a separate flat/sloped mesh and never follows the terrain surface.
      .lerp(new Color(0x829c97), smoothstep(0.08, 0.56, sample.water) * 0.12);
  }

  private updateTerrainColors(): void {
    const data = generatedWorldData();
    const color = this.terrainMesh?.geometry.getAttribute('color');
    if (!data || !color) return;
    const position = this.terrainMesh?.geometry.getAttribute('position');
    if (!position) return;
    for (let index = 0; index < position.count; index += 1) {
      const next = this.colorForPoint(position.getX(index), position.getZ(index));
      color.setXYZ(index, next.r, next.g, next.b);
    }
    color.needsUpdate = true;
  }

  private createScatterChunk(
    chunkX: number,
    chunkZ: number,
  ): VisualScatterChunk | undefined {
    const data = generatedWorldData();
    if (!data) return undefined;
    const minX = chunkX * VISUAL_CHUNK_METRES;
    const minZ = chunkZ * VISUAL_CHUNK_METRES;
    const maxX = minX + VISUAL_CHUNK_METRES;
    const maxZ = minZ + VISUAL_CHUNK_METRES;
    if (
      maxX < data.config.bounds.minX || minX > data.config.bounds.maxX ||
      maxZ < data.config.bounds.minZ || minZ > data.config.bounds.maxZ
    ) return undefined;
    const instances: ScatterInstance[] = [];
    const spacing = 10;
    for (let z = minZ + spacing * 0.5; z < maxZ; z += spacing) {
      for (let x = minX + spacing * 0.5; x < maxX; x += spacing) {
        if (x > GENERATED_COAST_TRANSITION_X || this.inAuthoredWilderness(x, z)) continue;
        const gridX = Math.floor(x / spacing);
        const gridZ = Math.floor(z / spacing);
        const jitterX = (deterministic(gridX, gridZ, data.config.seed + 601) - 0.5) * 7;
        const jitterZ = (deterministic(gridX, gridZ, data.config.seed + 607) - 0.5) * 7;
        const px = x + jitterX;
        const pz = z + jitterZ;
        const sample = sampleGeneratedWorld(px, pz);
        if (!sample.inside || sample.water > 0.08) continue;
        const selector = deterministic(gridX, gridZ, data.config.seed + 613);
        if (selector < sample.forest * 0.62) {
          const variant = deterministic(gridX, gridZ, data.config.seed + 617);
          instances.push({
            prefabId: variant < 0.42
              ? 'CONIFER_SPRUCE_01'
              : variant < 0.78
                ? 'CONIFER_SPRUCE_03'
                : 'CONIFER_SPRUCE_05',
            x: px,
            z: pz,
            heading: deterministic(gridX, gridZ, data.config.seed + 619) * Math.PI * 2,
            scale: 0.48 + deterministic(gridX, gridZ, data.config.seed + 631) * 0.68,
          });
        } else if (
          deterministic(gridX, gridZ, data.config.seed + 641) <
          sample.rockiness * 0.075
        ) {
          instances.push({
            prefabId: deterministic(gridX, gridZ, data.config.seed + 643) < 0.7
              ? 'ROCK_SMALL_02'
              : 'ROCK_LARGE_03',
            x: px,
            z: pz,
            heading: deterministic(gridX, gridZ, data.config.seed + 647) * Math.PI * 2,
            scale: 0.6 + deterministic(gridX, gridZ, data.config.seed + 653) * 0.75,
          });
        }
      }
    }
    if (instances.length === 0) return undefined;
    const root = new Group();
    root.name = `Generated visual ecology ${chunkX},${chunkZ}`;
    const batches: WorldAssetRuntimeBatch[] = [];
    const snowBatches: WorldAssetRuntimeSnowBatch[] = [];
    const matrix = new Matrix4();
    const quaternion = new Quaternion();
    const position = new Vector3();
    const scale = new Vector3();
    const up = new Vector3(0, 1, 0);
    const grouped = new Map<string, ScatterInstance[]>();
    for (const instance of instances) {
      const group = grouped.get(instance.prefabId) ?? [];
      group.push(instance);
      grouped.set(instance.prefabId, group);
    }
    for (const [prefabId, group] of grouped) {
      const batch = this.assets.createRuntimeBatch(prefabId, group.length);
      if (!batch) continue;
      const snow = this.assets.createRuntimeSnowBatch(prefabId, group.length);
      for (const [index, instance] of group.entries()) {
        position.set(
          instance.x,
          this.terrain.sampleHeight(instance.x, instance.z),
          instance.z,
        );
        quaternion.setFromAxisAngle(up, instance.heading);
        scale.setScalar(instance.scale);
        matrix.compose(position, quaternion, scale);
        batch.setMatrixAt(index, matrix);
        snow?.setMatrixAt(index, matrix);
        snow?.setAmountAt(index, 0.38);
      }
      batch.setCount(group.length);
      batch.commit();
      root.add(batch.root);
      batches.push(batch);
      if (snow) {
        snow.setCount(group.length);
        snow.commit();
        root.add(snow.root);
        snowBatches.push(snow);
      }
    }
    return { root, batches, snowBatches, chunkX, chunkZ };
  }

  private inAuthoredWilderness(x: number, z: number): boolean {
    return Math.hypot(
      x - WILDERNESS_SURVIVAL_REGION.centerX,
      z - WILDERNESS_SURVIVAL_REGION.centerZ,
    ) <= AUTHORED_WILDERNESS_CLEAR_RADIUS;
  }

  private updateScatterShadowLod(): void {
    if (this.centerChunkX === undefined || this.centerChunkZ === undefined) return;
    for (const chunk of this.scatterChunks.values()) {
      const distance = Math.max(
        Math.abs(chunk.chunkX - this.centerChunkX),
        Math.abs(chunk.chunkZ - this.centerChunkZ),
      );
      chunk.root.traverse((object) => {
        if (!(object instanceof InstancedMesh)) return;
        object.castShadow = distance <= 1;
        object.receiveShadow = distance <= 2;
      });
    }
  }

  private rebuildScatter(): void {
    if (this.centerChunkX === undefined || this.centerChunkZ === undefined) return;
    for (const chunk of this.scatterChunks.values()) this.disposeScatterChunk(chunk);
    this.scatterChunks.clear();
    const x = this.centerChunkX * VISUAL_CHUNK_METRES + 1;
    const z = this.centerChunkZ * VISUAL_CHUNK_METRES + 1;
    this.centerChunkX = undefined;
    this.centerChunkZ = undefined;
    this.updateCenter(x, z);
  }

  /**
   * The close ecology ring owns real snow-covered assets. This second ring
   * uses single-part asset-bank HLOD silhouettes: no collision, shadow or
   * separate snow geometry. It can therefore reach the macro horizon without
   * multiplying the close-tree triangle and draw-call budget.
   */
  private rebuildFarScatter(): void {
    const data = generatedWorldData();
    if (
      !data ||
      this.centerChunkX === undefined ||
      this.centerChunkZ === undefined
    ) return;
    const anchorChunkX = Math.floor(
      this.centerChunkX / FAR_REBUILD_CHUNK_STRIDE,
    ) * FAR_REBUILD_CHUNK_STRIDE;
    const anchorChunkZ = Math.floor(
      this.centerChunkZ / FAR_REBUILD_CHUNK_STRIDE,
    ) * FAR_REBUILD_CHUNK_STRIDE;
    if (
      this.farScatterRoot &&
      this.farAnchorChunkX === anchorChunkX &&
      this.farAnchorChunkZ === anchorChunkZ
    ) return;
    this.disposeFarScatter();
    this.farAnchorChunkX = anchorChunkX;
    this.farAnchorChunkZ = anchorChunkZ;
    const centerX = (anchorChunkX + FAR_REBUILD_CHUNK_STRIDE * 0.5) *
      VISUAL_CHUNK_METRES;
    const centerZ = (anchorChunkZ + FAR_REBUILD_CHUNK_STRIDE * 0.5) *
      VISUAL_CHUNK_METRES;
    const outer = FAR_VISUAL_RADIUS_CHUNKS * VISUAL_CHUNK_METRES;
    const inner = (VISUAL_RADIUS_CHUNKS + 0.65) * VISUAL_CHUNK_METRES;
    const instances: ScatterInstance[] = [];
    const startX = Math.floor((centerX - outer) / FAR_VISUAL_SPACING_METRES) *
      FAR_VISUAL_SPACING_METRES;
    const startZ = Math.floor((centerZ - outer) / FAR_VISUAL_SPACING_METRES) *
      FAR_VISUAL_SPACING_METRES;
    for (let z = startZ; z <= centerZ + outer; z += FAR_VISUAL_SPACING_METRES) {
      for (let x = startX; x <= centerX + outer; x += FAR_VISUAL_SPACING_METRES) {
        if (Math.max(Math.abs(x - centerX), Math.abs(z - centerZ)) < inner) continue;
        if (x > GENERATED_COAST_TRANSITION_X || this.inAuthoredWilderness(x, z)) continue;
        const gridX = Math.floor(x / FAR_VISUAL_SPACING_METRES);
        const gridZ = Math.floor(z / FAR_VISUAL_SPACING_METRES);
        const px = x + (
          deterministic(gridX, gridZ, data.config.seed + 701) - 0.5
        ) * (FAR_VISUAL_SPACING_METRES * 0.94);
        const pz = z + (
          deterministic(gridX, gridZ, data.config.seed + 709) - 0.5
        ) * (FAR_VISUAL_SPACING_METRES * 0.94);
        const sample = sampleGeneratedWorld(px, pz);
        if (!sample.inside || sample.water > 0.08) continue;
        const patchiness = deterministic(
          Math.floor(px / 88),
          Math.floor(pz / 88),
          data.config.seed + 713,
        );
        const density = clamp(
          smoothstep(0.055, 0.68, sample.forest) *
            (0.72 + patchiness * 0.45),
          0,
          0.94,
        );
        if (deterministic(gridX, gridZ, data.config.seed + 719) >= density) {
          continue;
        }
        // Dense cells grow a two- or three-tree deterministic grove. These
        // satellites break the final suggestion of a lattice and make strong
        // forest masks read as closed woodland without extra draw calls.
        const satelliteChance = deterministic(
          gridX,
          gridZ,
          data.config.seed + 723,
        );
        const count = 1 + (
          density > 0.48 && satelliteChance < density * 0.72 ? 1 : 0
        ) + (
          density > 0.76 && satelliteChance < density * 0.27 ? 1 : 0
        );
        for (let copy = 0; copy < count; copy += 1) {
          const angle = deterministic(
            gridX * 3 + copy,
            gridZ * 5 - copy,
            data.config.seed + 725,
          ) * Math.PI * 2;
          const radius = copy === 0
            ? 0
            : 4 + deterministic(
              gridX * 7 + copy,
              gridZ * 11 + copy,
              data.config.seed + 726,
            ) * 8.5;
          const treeX = px + Math.cos(angle) * radius;
          const treeZ = pz + Math.sin(angle) * radius;
          const treeSample = copy === 0
            ? sample
            : sampleGeneratedWorld(treeX, treeZ);
          if (!treeSample.inside || treeSample.water > 0.08) continue;
          const variant = deterministic(
            gridX * 13 + copy,
            gridZ * 17 - copy,
            data.config.seed + 727,
          );
          instances.push({
            prefabId: variant < 0.68
              ? 'NATURE_FOREST_HLOD_SPRUCE_01'
              : 'NATURE_FOREST_HLOD_PINE_01',
            x: treeX,
            z: treeZ,
            heading: deterministic(
              gridX * 19 + copy,
              gridZ * 23 - copy,
              data.config.seed + 733,
            ) * Math.PI * 2,
            scale: 0.58 + deterministic(
              gridX * 29 + copy,
              gridZ * 31 - copy,
              data.config.seed + 739,
            ) * 0.58,
          });
        }
      }
    }
    if (instances.length === 0) return;

    const root = new Group();
    root.name = 'Generated far ecology · pooled horizon forest';
    const grouped = new Map<string, ScatterInstance[]>();
    for (const instance of instances) {
      const group = grouped.get(instance.prefabId) ?? [];
      group.push(instance);
      grouped.set(instance.prefabId, group);
    }
    const matrix = new Matrix4();
    const quaternion = new Quaternion();
    const position = new Vector3();
    const scale = new Vector3();
    const up = new Vector3(0, 1, 0);
    for (const [prefabId, group] of grouped) {
      const batch = this.assets.createRuntimeBatch(prefabId, group.length);
      if (!batch) continue;
      for (const [index, instance] of group.entries()) {
        position.set(
          instance.x,
          this.terrain.sampleHeight(instance.x, instance.z),
          instance.z,
        );
        quaternion.setFromAxisAngle(up, instance.heading);
        scale.setScalar(instance.scale);
        matrix.compose(position, quaternion, scale);
        batch.setMatrixAt(index, matrix);
      }
      batch.setCount(group.length);
      batch.commit();
      batch.root.traverse((object) => {
        if (!(object instanceof InstancedMesh)) return;
        object.castShadow = false;
        object.receiveShadow = false;
      });
      root.add(batch.root);
      this.farScatterBatches.push(batch);
    }
    this.farScatterRoot = root;
    this.root.add(root);
    this.syncPresentationMode();
  }

  private disposeFarScatter(): void {
    for (const batch of this.farScatterBatches) batch.dispose();
    for (const batch of this.farScatterSnowBatches) batch.dispose();
    this.farScatterBatches = [];
    this.farScatterSnowBatches = [];
    this.farScatterRoot?.removeFromParent();
    this.farScatterRoot = undefined;
    this.farAnchorChunkX = undefined;
    this.farAnchorChunkZ = undefined;
  }

  private disposeScatterChunk(chunk: VisualScatterChunk): void {
    for (const batch of chunk.batches) batch.dispose();
    for (const batch of chunk.snowBatches) batch.dispose();
    chunk.root.removeFromParent();
  }

  private scheduleTerrainRebuild(): void {
    if (this.rebuildScheduled || this.disposed) return;
    this.rebuildScheduled = true;
    const schedule = typeof requestAnimationFrame === 'function'
      ? requestAnimationFrame
      : (callback: FrameRequestCallback): number => {
          queueMicrotask(() => callback(0));
          return 0;
        };
    schedule(() => {
      this.rebuildScheduled = false;
      if (this.disposed) return;
      this.rebuildTerrainGeometry();
      if (this.presentationMode === 'FULL') this.rebuildScatter();
      this.syncPresentationMode();
    });
  }

  private rebuildTerrainGeometry(): void {
    if (!this.terrainMesh) return;
    const previous = this.terrainMesh.geometry;
    this.terrainMesh.geometry = this.createTerrainGeometry();
    previous.dispose();
  }
}
