import type {
  GameplayRegistry,
  GameplayRegistryIssue,
} from '../definitions/GameplayRegistry';
import type { Vec3Like } from '../definitions/GameplayTypes';

export type WorldTargetRef =
  | {
      readonly kind: 'PORT';
      readonly portId: string;
    }
  | {
      readonly kind: 'ROUTE';
      readonly routeId: string;
    }
  | {
      readonly kind: 'POI';
      readonly poiId: string;
    }
  | {
      readonly kind: 'SHIP';
      readonly shipId: string;
      readonly shipDefinitionId?: string;
    }
  | {
      readonly kind: 'WORLD_OBJECT';
      readonly objectId: string;
    }
  | {
      readonly kind: 'WORLD_POSITION';
      readonly position: Vec3Like;
    }
  | {
      readonly kind: 'NPC';
      readonly npcId: string;
    }
  | {
      readonly kind: 'ROAD_SEGMENT';
      readonly segmentId: string;
    }
  | {
      readonly kind: 'SERVICE';
      readonly serviceId: string;
    }
  | {
      readonly kind: 'INCIDENT';
      readonly incidentId: string;
    }
  | {
      readonly kind: 'LOCATION';
      readonly locationId: string;
    };

export const worldTarget = {
  port: (portId: string): WorldTargetRef => ({
    kind: 'PORT',
    portId,
  }),
  route: (routeId: string): WorldTargetRef => ({
    kind: 'ROUTE',
    routeId,
  }),
  poi: (poiId: string): WorldTargetRef => ({
    kind: 'POI',
    poiId,
  }),
  ship: (
    shipId: string,
    shipDefinitionId?: string,
  ): WorldTargetRef => ({
    kind: 'SHIP',
    shipId,
    ...(shipDefinitionId ? { shipDefinitionId } : {}),
  }),
  object: (objectId: string): WorldTargetRef => ({
    kind: 'WORLD_OBJECT',
    objectId,
  }),
  position: (position: Vec3Like): WorldTargetRef => ({
    kind: 'WORLD_POSITION',
    position: { ...position },
  }),
  npc: (npcId: string): WorldTargetRef => ({ kind: 'NPC', npcId }),
  roadSegment: (segmentId: string): WorldTargetRef => ({ kind: 'ROAD_SEGMENT', segmentId }),
  service: (serviceId: string): WorldTargetRef => ({ kind: 'SERVICE', serviceId }),
  incident: (incidentId: string): WorldTargetRef => ({ kind: 'INCIDENT', incidentId }),
  location: (locationId: string): WorldTargetRef => ({ kind: 'LOCATION', locationId }),
};

const nonEmpty = (value: string): boolean =>
  value.trim().length > 0;

const finitePosition = (position: Vec3Like): boolean =>
  Number.isFinite(position.x) &&
  Number.isFinite(position.y) &&
  Number.isFinite(position.z);

export const worldTargetKey = (
  target: Readonly<WorldTargetRef>,
): string => {
  switch (target.kind) {
    case 'PORT':
      return `port:${target.portId}`;
    case 'ROUTE':
      return `route:${target.routeId}`;
    case 'POI':
      return `poi:${target.poiId}`;
    case 'SHIP':
      return `ship:${target.shipId}`;
    case 'WORLD_OBJECT':
      return `object:${target.objectId}`;
    case 'WORLD_POSITION':
      return (
        `position:${target.position.x}:` +
        `${target.position.y}:${target.position.z}`
      );
    case 'NPC':
      return `npc:${target.npcId}`;
    case 'ROAD_SEGMENT':
      return `road:${target.segmentId}`;
    case 'SERVICE':
      return `service:${target.serviceId}`;
    case 'INCIDENT':
      return `incident:${target.incidentId}`;
    case 'LOCATION':
      return `location:${target.locationId}`;
  }
};

export const validateWorldTargetRef = (
  target: Readonly<WorldTargetRef>,
  registry: GameplayRegistry,
  path = 'target',
): readonly GameplayRegistryIssue[] => {
  const issues: GameplayRegistryIssue[] = [];
  const missing = (
    targetPath: string,
    kind: string,
    id: string,
  ): void => {
    issues.push({
      path: targetPath,
      message: `Missing ${kind} "${id}"`,
    });
  };

  switch (target.kind) {
    case 'PORT':
      if (!nonEmpty(target.portId)) {
        issues.push({
          path: `${path}.portId`,
          message: 'Port ID must be a non-empty string',
        });
      } else if (!registry.getPort(target.portId)) {
        missing(`${path}.portId`, 'port', target.portId);
      }
      break;
    case 'ROUTE':
      if (!nonEmpty(target.routeId)) {
        issues.push({
          path: `${path}.routeId`,
          message: 'Route ID must be a non-empty string',
        });
      } else if (!registry.getRoute(target.routeId)) {
        missing(`${path}.routeId`, 'route', target.routeId);
      }
      break;
    case 'POI':
      if (!nonEmpty(target.poiId)) {
        issues.push({
          path: `${path}.poiId`,
          message: 'POI ID must be a non-empty string',
        });
      } else if (!registry.getPoi(target.poiId)) {
        missing(`${path}.poiId`, 'POI', target.poiId);
      }
      break;
    case 'SHIP':
      if (!nonEmpty(target.shipId)) {
        issues.push({
          path: `${path}.shipId`,
          message: 'Runtime ship ID must be a non-empty string',
        });
      }
      if (
        target.shipDefinitionId !== undefined &&
        !registry.getShip(target.shipDefinitionId)
      ) {
        missing(
          `${path}.shipDefinitionId`,
          'ship definition',
          target.shipDefinitionId,
        );
      }
      break;
    case 'WORLD_OBJECT':
      if (!nonEmpty(target.objectId)) {
        issues.push({
          path: `${path}.objectId`,
          message: 'World object ID must be a non-empty string',
        });
      }
      break;
    case 'WORLD_POSITION':
      if (!finitePosition(target.position)) {
        issues.push({
          path: `${path}.position`,
          message: 'World position components must be finite',
        });
      }
      break;
    case 'NPC':
      if (!nonEmpty(target.npcId)) issues.push({ path: `${path}.npcId`, message: 'NPC ID must be a non-empty string' });
      break;
    case 'ROAD_SEGMENT':
      if (!nonEmpty(target.segmentId)) issues.push({ path: `${path}.segmentId`, message: 'Road segment ID must be a non-empty string' });
      break;
    case 'SERVICE':
      if (!nonEmpty(target.serviceId)) issues.push({ path: `${path}.serviceId`, message: 'Service ID must be a non-empty string' });
      break;
    case 'INCIDENT':
      if (!nonEmpty(target.incidentId)) issues.push({ path: `${path}.incidentId`, message: 'Incident ID must be a non-empty string' });
      break;
    case 'LOCATION':
      if (!nonEmpty(target.locationId)) issues.push({ path: `${path}.locationId`, message: 'Location ID must be a non-empty string' });
      break;
  }
  return issues;
};
