import {
  type CommandSequence,
  type TransactionId,
  commandSequence,
  connectionId,
  networkEntityId,
  playerId,
  serverTick,
  sessionEpoch,
  transactionId,
} from '../../netcode/core/NetworkPrimitives';
import type { ClockPongPayload } from '../../netcode/core/AuthorityClock';
import type { ReliableAuthorityChannel } from '../../netcode/protocol/AuthorityIngress';
import {
  type JoinAcceptedPayload,
  type ServerHelloPayload,
  type SessionCapability,
  type SessionChatMessagePayload,
  validateSessionCompatibilityDescriptor,
} from '../../netcode/protocol/SessionHandshake';
import type { SessionId } from '../../netcode/core/NetworkPrimitives';
import { validateCompatibilityRejectionNotice } from '../../netcode/protocol/DeploymentPolicy';
import type { CompatibilityRejectionNoticePayload } from '../../netcode/protocol/DeploymentPolicy';

export interface CommandReceiptEntry {
  commandSequence: CommandSequence;
  accepted: boolean;
  reason?: string;
}

export interface CommandReceiptPayload {
  version: 1;
  playerId: ReturnType<typeof playerId>;
  receipts: readonly CommandReceiptEntry[];
}

export interface TransactionResultPayload {
  version: 1;
  requestId: TransactionId;
  playerId: ReturnType<typeof playerId>;
  channel: ReliableAuthorityChannel;
  accepted: boolean;
  status: string;
  reason?: string | null;
}

const CHANNELS = new Set<ReliableAuthorityChannel>([
  'CONTEXTUAL_INTERACTION',
  'INVENTORY',
  'DIALOGUE',
  'MAP',
  'QUEST',
  'TEXT_CHAT',
  'CONSTRUCTION',
  'RADIO',
  'SETTLEMENT',
  'SESSION',
]);

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);

const isBoundedString = (value: unknown, maximum: number): value is string =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= maximum;

const isNonNegativeInteger = (value: unknown): value is number =>
  typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;

export const validateServerHelloPayload = (
  input: unknown,
): ServerHelloPayload | undefined => {
  if (!isRecord(input) || input.version !== 1 || typeof input.accepted !== 'boolean') {
    return undefined;
  }
  if (!isBoundedString(input.authorityBuildId, 160)) return undefined;
  const compatibility = validateSessionCompatibilityDescriptor(input.compatibility);
  if (!compatibility.ok || !Array.isArray(input.negotiatedCapabilities)) return undefined;
  const authorityCapabilities = new Set(compatibility.value.capabilities);
  if (
    input.negotiatedCapabilities.length > authorityCapabilities.size ||
    !input.negotiatedCapabilities.every(
      (capability) =>
        typeof capability === 'string' &&
        authorityCapabilities.has(capability as SessionCapability),
    ) ||
    (input.rejection !== undefined && typeof input.rejection !== 'string')
  ) {
    return undefined;
  }
  const rejectionNotice = input.rejectionNotice === undefined
    ? undefined
    : validateCompatibilityRejectionNotice(input.rejectionNotice);
  if (input.rejectionNotice !== undefined && !rejectionNotice) return undefined;
  return {
    version: 1,
    accepted: input.accepted,
    authorityBuildId: input.authorityBuildId,
    compatibility: compatibility.value,
    negotiatedCapabilities: [
      ...new Set(input.negotiatedCapabilities as SessionCapability[]),
    ].sort(),
    rejection: input.rejection as ServerHelloPayload['rejection'],
    ...(rejectionNotice ? { rejectionNotice } : {}),
  };
};

export const validateChatMessagePayload = (
  input: unknown,
): SessionChatMessagePayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    !isBoundedString(input.messageId, 160) ||
    !isBoundedString(input.playerId, 160) ||
    !isBoundedString(input.displayName, 48) ||
    !isNonNegativeInteger(input.serverTick) ||
    !isBoundedString(input.text, 500)
  ) {
    return undefined;
  }
  return {
    version: 1,
    messageId: input.messageId,
    playerId: playerId(input.playerId),
    displayName: input.displayName,
    serverTick: serverTick(input.serverTick),
    text: input.text,
  };
};

export const validateJoinAcceptedPayload = (
  input: unknown,
  expectedSessionId: SessionId,
  maximumChatHistory: number,
): JoinAcceptedPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    input.sessionId !== expectedSessionId ||
    !isNonNegativeInteger(input.sessionEpoch) ||
    !isNonNegativeInteger(input.serverTick) ||
    !isBoundedString(input.playerId, 160) ||
    !isBoundedString(input.connectionId, 160) ||
    !isBoundedString(input.resumeToken, 256) ||
    (input.characterEntityId !== undefined &&
      !isBoundedString(input.characterEntityId, 160)) ||
    !isRecord(input.stateHashes) ||
    !Array.isArray(input.chatHistory) ||
    input.chatHistory.length > maximumChatHistory
  ) {
    return undefined;
  }
  const hashes = input.stateHashes;
  const hashKeys = ['players', 'entities', 'leases', 'ingress', 'combined'] as const;
  if (hashKeys.some((key) => !isBoundedString(hashes[key], 256))) return undefined;
  const chatHistory: SessionChatMessagePayload[] = [];
  for (const candidate of input.chatHistory) {
    const message = validateChatMessagePayload(candidate);
    if (!message) return undefined;
    chatHistory.push(message);
  }
  return {
    version: 1,
    sessionId: expectedSessionId,
    sessionEpoch: sessionEpoch(input.sessionEpoch),
    serverTick: serverTick(input.serverTick),
    playerId: playerId(input.playerId),
    connectionId: connectionId(input.connectionId),
    resumeToken: input.resumeToken,
    characterEntityId:
      input.characterEntityId === undefined
        ? undefined
        : networkEntityId(input.characterEntityId),
    stateHashes: {
      players: hashes.players as string,
      entities: hashes.entities as string,
      leases: hashes.leases as string,
      ingress: hashes.ingress as string,
      combined: hashes.combined as string,
    },
    chatHistory,
  };
};

export const validateClockPongPayload = (
  input: unknown,
): ClockPongPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    !isNonNegativeInteger(input.pingId) ||
    typeof input.clientSendMs !== 'number' ||
    !Number.isFinite(input.clientSendMs) ||
    typeof input.serverReceiveMs !== 'number' ||
    !Number.isFinite(input.serverReceiveMs) ||
    typeof input.serverSendMs !== 'number' ||
    !Number.isFinite(input.serverSendMs) ||
    !isNonNegativeInteger(input.serverTick)
  ) {
    return undefined;
  }
  return {
    version: 1,
    pingId: input.pingId,
    clientSendMs: input.clientSendMs,
    serverReceiveMs: input.serverReceiveMs,
    serverSendMs: input.serverSendMs,
    serverTick: serverTick(input.serverTick),
  };
};

export const validateCommandReceiptPayload = (
  input: unknown,
): CommandReceiptPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    !isBoundedString(input.playerId, 160) ||
    !Array.isArray(input.receipts) ||
    input.receipts.length === 0 ||
    input.receipts.length > 8
  ) {
    return undefined;
  }
  const receipts: CommandReceiptEntry[] = [];
  for (const candidate of input.receipts) {
    if (
      !isRecord(candidate) ||
      !isNonNegativeInteger(candidate.commandSequence) ||
      typeof candidate.accepted !== 'boolean' ||
      (candidate.reason !== undefined && typeof candidate.reason !== 'string')
    ) {
      return undefined;
    }
    receipts.push({
      commandSequence: commandSequence(candidate.commandSequence),
      accepted: candidate.accepted,
      ...(candidate.reason ? { reason: candidate.reason } : {}),
    });
  }
  return { version: 1, playerId: playerId(input.playerId), receipts };
};

export const validateTransactionResultPayload = (
  input: unknown,
): TransactionResultPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    !isBoundedString(input.requestId, 160) ||
    !isBoundedString(input.playerId, 160) ||
    typeof input.channel !== 'string' ||
    !CHANNELS.has(input.channel as ReliableAuthorityChannel) ||
    typeof input.accepted !== 'boolean' ||
    !isBoundedString(input.status, 160) ||
    (input.reason !== undefined && input.reason !== null &&
      typeof input.reason !== 'string')
  ) {
    return undefined;
  }
  return {
    version: 1,
    requestId: transactionId(input.requestId),
    playerId: playerId(input.playerId),
    channel: input.channel as ReliableAuthorityChannel,
    accepted: input.accepted,
    status: input.status,
    reason: input.reason as string | null | undefined,
  };
};

export const validateJoinRejectedReason = (input: unknown): string | undefined =>
  isRecord(input) &&
  input.version === 1 &&
  isBoundedString(input.reason, 256)
    ? input.reason
    : undefined;

export const validateJoinRejectedPayload = (
  input: unknown,
): Readonly<{
  reason: string;
  notice?: CompatibilityRejectionNoticePayload;
}> | undefined => {
  const reason = validateJoinRejectedReason(input);
  if (!reason || !isRecord(input)) return undefined;
  const notice = input.notice === undefined
    ? undefined
    : validateCompatibilityRejectionNotice(input.notice);
  if (input.notice !== undefined && !notice) return undefined;
  return { reason, ...(notice ? { notice } : {}) };
};
