const stableBuildUnit = (id: string): number => {
  let hash = 2166136261;
  for (let index = 0; index < id.length; index += 1) {
    hash ^= id.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0) / 0xffffffff;
};

const normalizeDegrees = (degrees: number): number =>
  ((degrees + 180) % 360 + 360) % 360 - 180;

const rotateXZ = (x: number, z: number, yawDegrees: number): readonly [number, number] => {
  const yaw = MathUtils.degToRad(yawDegrees);
  return [x * Math.cos(yaw) + z * Math.sin(yaw), -x * Math.sin(yaw) + z * Math.cos(yaw)];
};

/**
 * Socket attachment describes structure, not support. Sample the actual base
 * footprint so a second foundation/floor touching terrain clears snow just
 * like the first piece, while suspended beams and roofs leave it untouched.
 */
export const survivalBuildPlacementTouchesTerrain = (
  definition: Readonly<Pick<
    SurvivalBuildPieceDefinition,
    'halfWidth' | 'halfDepth'
  >>,
  placement: Readonly<{
    x: number;
    y: number;
    z: number;
    yawDegrees: number;
  }>,
  sampleTerrainHeight: (x: number, z: number) => number,
  toleranceMetres = TERRAIN_CONTACT_TOLERANCE_METRES,
): boolean => {
  const sampleWidth = definition.halfWidth * 0.82;
  const sampleDepth = definition.halfDepth * 0.82;
  const localSamples: readonly (readonly [number, number])[] = [
    [0, 0],
    [-sampleWidth, -sampleDepth],
    [-sampleWidth, sampleDepth],
    [sampleWidth, -sampleDepth],
    [sampleWidth, sampleDepth],
    [-sampleWidth, 0],
    [sampleWidth, 0],
    [0, -sampleDepth],
    [0, sampleDepth],
  ];
  return localSamples.some(([localX, localZ]) => {
    const [offsetX, offsetZ] = rotateXZ(
      localX,
      localZ,
      placement.yawDegrees,
    );
    const terrainY = sampleTerrainHeight(
      placement.x + offsetX,
      placement.z + offsetZ,
    );
    return placement.y - terrainY <= toleranceMetres;
  });
};

const cloneMaterialForPaint = (source: Material): Material => {
  const cloned = source.clone();
  const colored = cloned as Material & {
    color?: Color;
    emissive?: Color;
    emissiveIntensity?: number;
  };
  if (colored.color) cloned.userData.survivalBuildBaseColor = colored.color.getHex();
  if (colored.color) cloned.userData.survivalBuildRestColor = colored.color.getHex();
  if (colored.emissive) {
    cloned.userData.survivalBuildBaseEmissive = colored.emissive.getHex();
    cloned.userData.survivalBuildBaseEmissiveIntensity = colored.emissiveIntensity ?? 0;
    cloned.userData.survivalBuildRestEmissive = colored.emissive.getHex();
    cloned.userData.survivalBuildRestEmissiveIntensity = colored.emissiveIntensity ?? 0;
  }
  cloned.userData.survivalBuildBaseOpacity = cloned.opacity;
  cloned.userData.survivalBuildBaseTransparent = cloned.transparent;
  cloned.userData.survivalBuildBaseDepthWrite = cloned.depthWrite;
  cloned.userData.survivalBuildOwnedMaterial = true;
  return cloned;
};

