import type {
  StoryQuestDefinition,
  StoryQuestRuntimeState,
} from './EmergentWorldTypes';

export interface LandStoryObjectiveView {
  readonly questId: string;
  readonly stageId: string;
  readonly title: string;
  readonly description: string;
  readonly status: string;
  readonly progress: number;
  readonly targetLocationId?: string;
}

/**
 * Projects many authored stories into one calm, readable world-HUD objective.
 * Full quest state stays in the tablet; this function never owns progression.
 */
export const selectLandStoryObjective = (
  definitions: readonly Readonly<StoryQuestDefinition>[],
  states: readonly Readonly<StoryQuestRuntimeState>[],
): LandStoryObjectiveView | undefined => {
  const stateById = new Map(states.map((state) => [state.questId, state]));
  const candidates = definitions.flatMap((definition) => {
    const state = stateById.get(definition.id);
    if (state?.status !== 'ACTIVE' || !state.currentStageId) return [];
    const stageIndex = definition.stages.findIndex(
      (stage) => stage.id === state.currentStageId,
    );
    if (stageIndex < 0) return [];
    const stage = definition.stages[stageIndex]!;
    return [{
      definition,
      state,
      stage,
      stageIndex,
      priority: definition.hudPriority ?? 0,
    }];
  }).sort((left, right) =>
    right.priority - left.priority ||
    (left.state.startedAt ?? Number.MAX_SAFE_INTEGER) -
      (right.state.startedAt ?? Number.MAX_SAFE_INTEGER) ||
    left.definition.id.localeCompare(right.definition.id));
  const selected = candidates[0];
  if (!selected) return undefined;
  return {
    questId: selected.definition.id,
    stageId: selected.stage.id,
    title: selected.definition.hudTitle ?? selected.definition.displayName,
    description: selected.stage.hudGuidance ??
      selected.definition.requestPresentation?.summary ??
      selected.definition.description ??
      selected.stage.displayName,
    status: selected.stage.displayName,
    progress: selected.stageIndex / Math.max(1, selected.definition.stages.length),
    ...(selected.stage.hudTargetLocationId
      ? { targetLocationId: selected.stage.hudTargetLocationId }
      : {}),
  };
};
