import {
  AnimationMixer,
  Box3,
  Group,
  LoopRepeat,
  Mesh,
  Vector3,
  type AnimationAction,
  type AnimationClip,
  type Color,
  type Material,
} from 'three';
import type { WildernessAnimalSpecies } from './WildernessSurvivalSimulation';

type AuthoredWinterSpecies =
  | 'RABBIT'
  | 'DEER'
  | 'FOX'
  | 'WOLF'
  | 'RAVEN'
  | 'CROW'
  | 'EAGLE';

interface WinterAnimalAssetDefinition {
  readonly url: string;
  readonly targetHeight: number;
  readonly animationAliases: Readonly<Record<WinterAnimalMotion, string>>;
  readonly format?: 'GLB' | 'FBX';
  /** Authored model forward axis relative to Iceway's local +Z forward. */
  readonly forwardYawRadians?: number;
}

export type WinterAnimalMotion =
  | 'IDLE'
  | 'OBSERVE'
  | 'SNIFF'
  | 'EAT'
  | 'WALK'
  | 'RUN'
  | 'ATTACK'
  | 'HIT';

export interface WinterAnimalModelInstance {
  readonly root: Group;
  readonly mixer: AnimationMixer;
  readonly clips: readonly AnimationClip[];
  readonly actions: Map<WinterAnimalMotion, AnimationAction>;
  readonly phaseOffset: number;
  currentMotion?: WinterAnimalMotion;
}

