interface LoadedAnimalSource {
  readonly scene: Group;
  readonly clips: readonly AnimationClip[];
}

const sourceCache = new Map<string, Promise<LoadedAnimalSource>>();
const bounds = new Box3();
const size = new Vector3();
const centre = new Vector3();

const configureSource = (scene: Group): void => {
  scene.traverse((object) => {
    if (!(object instanceof Mesh)) return;
    object.castShadow = false;
    object.receiveShadow = true;
    object.frustumCulled = true;
    const materials = Array.isArray(object.material)
      ? object.material
      : [object.material];
    for (const candidate of materials as Material[]) {
      candidate.depthWrite = true;
      candidate.transparent = false;
    }
  });
};

const loadSource = async (
  definition: Readonly<WinterAnimalAssetDefinition>,
): Promise<LoadedAnimalSource> => {
  const absoluteUrl = new URL(definition.url, document.baseURI).href;
  const cached = sourceCache.get(absoluteUrl);
  if (cached) return cached;
  const pending = (async (): Promise<LoadedAnimalSource> => {
    if (definition.format === 'FBX') {
      const { FBXLoader } = await import(
        'three/examples/jsm/loaders/FBXLoader.js'
      );
      const scene = await new FBXLoader().loadAsync(absoluteUrl);
      configureSource(scene);
      return {
        scene,
        clips: scene.animations,
      };
    }
    const { GLTFLoader } = await import(
      'three/examples/jsm/loaders/GLTFLoader.js'
    );
    const loader = new GLTFLoader();
    const gltf = await loader.loadAsync(absoluteUrl);
    configureSource(gltf.scene);
    return {
      scene: gltf.scene,
      clips: gltf.animations,
    };
  })();
  sourceCache.set(absoluteUrl, pending);
  try {
    return await pending;
  } catch (error) {
    sourceCache.delete(absoluteUrl);
    throw error;
  }
};

const definitionFor = (
  species: WildernessAnimalSpecies,
  individualId: string,
): WinterAnimalAssetDefinition | undefined => {
  if (species === 'DEER') {
    // A restrained stag variation gives a herd readable hierarchy without a
    // separate ecosystem species or extra simulation state.
    const ordinal = Number(individualId.match(/\d+$/)?.[0] ?? 0);
    return ordinal % 4 === 0 ? STAG_ASSET : ANIMAL_ASSETS.DEER;
  }
  if (species === 'RABBIT' || species === 'FOX' || species === 'WOLF') {
    return ANIMAL_ASSETS[species];
  }
  if (species === 'RAVEN' || species === 'CROW' || species === 'EAGLE') {
    return ANIMAL_ASSETS[species];
  }
  return undefined;
};

/**
 * Streams and skeleton-clones an authored winter animal. The central asset
 * mapping is the single replacement seam; ecosystem/save data never depends
 * on model filenames. Procedural asset-bank animals remain the fallback.
 */
export const createWinterAnimalModel = async (
  species: WildernessAnimalSpecies,
  individualId: string,
): Promise<WinterAnimalModelInstance | undefined> => {
  if (typeof document === 'undefined') return undefined;
  const definition = definitionFor(species, individualId);
  if (!definition) return undefined;
  const source = await loadSource(definition);
  const { clone: cloneSkeleton } = await import(
    'three/examples/jsm/utils/SkeletonUtils.js'
  );
  const clonedScene = cloneSkeleton(source.scene) as Group;
  if (species === 'RAVEN' || species === 'CROW' || species === 'EAGLE') {
    const tint = species === 'RAVEN'
      ? 0x182126
      : species === 'CROW'
        ? 0x273136
        : 0x795f39;
    clonedScene.traverse((object) => {
      if (!(object instanceof Mesh)) return;
      const recolor = (candidate: Material): Material => {
        const cloned = candidate.clone() as Material & { color?: Color };
        cloned.color?.setHex(tint);
        return cloned;
      };
      object.material = Array.isArray(object.material)
        ? object.material.map(recolor)
        : recolor(object.material);
    });
  }
  clonedScene.updateMatrixWorld(true);
  bounds.setFromObject(clonedScene);
  bounds.getSize(size);
  bounds.getCenter(centre);
  const scale = definition.targetHeight / Math.max(0.001, size.y);

  const content = new Group();
  content.name = `${species.toLowerCase()} authored content`;
  // Quaternius' eagle rig (shared by the raven/crow/eagle silhouettes) is
  // authored facing -Z, while wilderness flight kinematics use +Z as local
  // forward. Keep the correction at the asset seam: changing the simulated
  // heading would reverse flight paths, steering and flock intent as well.
  content.rotation.y = definition.forwardYawRadians ?? 0;
  clonedScene.position.set(-centre.x, -bounds.min.y, -centre.z);
  content.scale.setScalar(scale);
  content.add(clonedScene);

  const root = new Group();
  root.name = `Winter animal asset · ${species}`;
  // Prevent the wilderness disposer from deleting geometry retained by the
  // shared asynchronous source cache.
  root.userData.worldAssetPrefabId = `WINTER_ANIMAL_${species}`;
  root.add(content);

  const mixer = new AnimationMixer(clonedScene);
  const actions = new Map<WinterAnimalMotion, AnimationAction>();
  for (const [motion, clipName] of Object.entries(
    definition.animationAliases,
  ) as Array<[WinterAnimalMotion, string]>) {
    const clip = source.clips.find((candidate) => candidate.name === clipName);
    if (!clip) continue;
    const action = mixer.clipAction(clip);
    action.setLoop(LoopRepeat, Number.POSITIVE_INFINITY);
    action.clampWhenFinished = false;
    actions.set(motion, action);
  }
  let identityHash = 2166136261;
  for (let index = 0; index < individualId.length; index += 1) {
    identityHash ^= individualId.charCodeAt(index);
    identityHash = Math.imul(identityHash, 16777619);
  }
  const phaseOffset = (identityHash >>> 0) / 0xffff_ffff;
  return { root, mixer, clips: source.clips, actions, phaseOffset };
};

export const setWinterAnimalMotion = (
  model: WinterAnimalModelInstance,
  motion: WinterAnimalMotion,
  fadeSeconds = 0.24,
): void => {
  if (model.currentMotion === motion) return;
  const fallback = motion === 'RUN' || motion === 'ATTACK'
    ? model.actions.get('WALK')
    : model.actions.get('IDLE');
  const next = model.actions.get(motion) ?? fallback;
  if (!next) return;
  const previous = model.currentMotion
    ? model.actions.get(model.currentMotion)
    : undefined;
  // Several authored packs intentionally map many semantic bird states to
  // one Flying clip. Fading an AnimationAction out against itself stops it,
  // which left some ravens and crows gliding with frozen wings after their
  // first WALK/RUN or OBSERVE/IDLE transition.
  if (previous === next) {
    next.enabled = true;
    next.paused = false;
    if (!next.isRunning()) next.play();
    model.currentMotion = motion;
    return;
  }
  next.enabled = true;
  next.reset();
  next.time = next.getClip().duration * model.phaseOffset;
  next.fadeIn(fadeSeconds).play();
  previous?.fadeOut(fadeSeconds);
  model.currentMotion = motion;
};

/**
 * Holds the authored flying clip on its widest, near-horizontal wing pose
 * during a glide. Releasing the hold resumes the same action without a
 * cross-fade, so a short maintaining burst does not visibly restart a flap.
 */
export const setWinterAnimalGliding = (
  model: WinterAnimalModelInstance,
  gliding: boolean,
): void => {
  const action = model.currentMotion
    ? model.actions.get(model.currentMotion)
    : undefined;
  if (!action) return;
  action.enabled = true;
  if (gliding) {
    action.time = 0;
    action.paused = true;
    model.mixer.update(0);
    return;
  }
  action.paused = false;
  if (!action.isRunning()) action.play();
};
