import {
  CatmullRomCurve3,
  Group,
  Mesh,
  MeshBasicMaterial,
  PointLight,
  Ray,
  SphereGeometry,
  TubeGeometry,
  Vector3,
  type Scene,
} from 'three';
import { ICEWAY_PLAYTEST_MODE } from '../core/RuntimeBuildFlags';
import type { LandSnowSystem } from '../land/LandSnowSystem';
import type { TerrainHeightSystem } from '../land/TerrainHeightSystem';
import { clamp, smoothstep } from '../utils/math';
import type { LocalWorldInfluence } from './LocalWorldInfluenceRegistry';
import {
  WILDERNESS_RUNE_CATALOG,
  wildernessRuneDefinition,
  type WildernessRuneDefinition,
  type WildernessRuneId,
} from './WildernessRuneCatalog';
import type {
  WildernessAnimalState,
  WildernessInventory,
} from './WildernessSurvivalSimulation';

export interface WildernessRuneInstanceState {
  readonly id: string;
  readonly runeId: WildernessRuneId;
  readonly points: readonly Readonly<{ x: number; z: number }>[];
  remainingSeconds: number;
  charge: number;
  revision: number;
}

export interface WildernessRuneSaveData {
  readonly version: 1;
  readonly selectedRuneId?: WildernessRuneId;
  readonly discoveredRuneIds?: readonly WildernessRuneId[];
  readonly instances: readonly WildernessRuneInstanceState[];
}

export interface WildernessRuneView {
  readonly paletteOpen: boolean;
  readonly tracing: boolean;
  readonly selectedRuneId: WildernessRuneId;
  readonly selectedRuneName: string;
  readonly description: string;
  readonly costLabel: string;
  readonly status: string;
  readonly activeRunes: number;
  readonly implemented: boolean;
  /** Discovered, functional runes that may occupy quick-wheel slots. */
  readonly availableRuneIds: readonly WildernessRuneId[];
}

export interface WildernessRuneActionResult {
  readonly accepted: boolean;
  readonly message: string;
  readonly tone?: 'achievement' | 'warning';
}

interface RuneVisual {
  readonly root: Group;
  readonly material: MeshBasicMaterial;
  readonly burst?: Mesh;
  readonly burstMaterial?: MeshBasicMaterial;
  age: number;
}

const TRACE_STEP_METRES = 0.16;
const MAX_TRACE_POINTS = 192;

const pathLength = (points: readonly Readonly<{ x: number; z: number }>[]): number => {
  let total = 0;
  for (let index = 1; index < points.length; index += 1) {
    total += Math.hypot(points[index]!.x - points[index - 1]!.x, points[index]!.z - points[index - 1]!.z);
  }
  return total;
};

const distanceToSegment = (
  x: number,
  z: number,
  ax: number,
  az: number,
  bx: number,
  bz: number,
): number => {
  const dx = bx - ax;
  const dz = bz - az;
  const denominator = dx * dx + dz * dz;
  const t = denominator <= 0.0001
    ? 0
    : clamp(((x - ax) * dx + (z - az) * dz) / denominator, 0, 1);
  return Math.hypot(x - (ax + dx * t), z - (az + dz * t));
};

export const scoreRuneTrace = (
  trace: readonly Readonly<{ x: number; z: number }>[],
  guide: readonly Readonly<{ x: number; z: number }>[],
): Readonly<{ score: number; coverage: number; lengthRatio: number }> => {
  if (trace.length < 2 || guide.length < 2) return { score: 99, coverage: 0, lengthRatio: 0 };
  let error = 0;
  const visited = new Set<number>();
  for (const point of trace) {
    let best = Number.POSITIVE_INFINITY;
    let bestIndex = 0;
    for (let index = 1; index < guide.length; index += 1) {
      const distance = distanceToSegment(
        point.x, point.z,
        guide[index - 1]!.x, guide[index - 1]!.z,
        guide[index]!.x, guide[index]!.z,
      );
      if (distance < best) {
        best = distance;
        bestIndex = index;
      }
    }
    error += best;
    visited.add(bestIndex);
  }
  return {
    score: error / trace.length,
    coverage: visited.size / Math.max(1, guide.length - 1),
    lengthRatio: pathLength(trace) / Math.max(0.01, pathLength(guide)),
  };
};

export class WildernessRuneSystem {
  private readonly root = new Group();
  /** One persistent glow avoids shader recompiles as runes awaken/expire. */
  private readonly lightRoot = new Group();
  private readonly pooledLight = new PointLight(0xff9f58, 0, 7, 2);
  private readonly guideRoot = new Group();
  private readonly instanceRoot = new Group();
  private readonly instances: WildernessRuneInstanceState[];
  private readonly visuals = new Map<string, RuneVisual>();
  private readonly discovered = new Set<WildernessRuneId>();
  private selectedRuneId: WildernessRuneId;
  private paletteOpen = false;
  private active = false;
  private tracing = false;
  private guidePoints: Array<{ x: number; z: number }> = [];
  private tracePoints: Array<{ x: number; z: number }> = [];
  private guideLine?: Mesh;
  private traceLine?: Mesh;
  private readonly raySample = new Vector3();
  private serial = 1;
  private lastAwakenedInstanceId?: string;
  private snowAccumulator = 0;
  private status = 'Choose a mark, then draw its glowing guide into the snow.';

  public constructor(
    scene: Scene,
    private readonly terrain: TerrainHeightSystem,
    private readonly inventory: WildernessInventory,
    saved?: Readonly<WildernessRuneSaveData>,
  ) {
    this.root.name = 'Diegetic walked wilderness runes';
    this.lightRoot.name = 'Pooled wilderness rune light';
    this.pooledLight.name = 'Pooled wilderness rune light source';
    this.pooledLight.castShadow = false;
    this.lightRoot.add(this.pooledLight);
    this.guideRoot.name = 'Walkable rune guides';
    this.instanceRoot.name = 'Persistent rune effects';
    this.root.add(this.guideRoot, this.instanceRoot);
    scene.add(this.root);
    scene.add(this.lightRoot);
    this.selectedRuneId = saved?.selectedRuneId ?? 'FIRE_GATE';
    // New worlds begin with two simple marks. The wilderness, animals and
    // old stones teach the rest; playtest mode no longer silently exposes the
    // whole catalogue and accidentally bypasses that progression.
    (saved?.discoveredRuneIds ?? (
      ICEWAY_PLAYTEST_MODE
        ? ['FIRE_GATE', 'RETURN_MARK', 'SNOW_SWEEP']
        : ['FIRE_GATE', 'RETURN_MARK']
    ))
      .forEach((id) => this.discovered.add(id));
    this.instances = (saved?.instances ?? []).flatMap((instance) =>
      WILDERNESS_RUNE_CATALOG.some((definition) => definition.id === instance.runeId)
        ? [{ ...instance, points: instance.points.map((point) => ({ ...point })) }]
        : []);
    this.serial = this.instances.reduce((maximum, instance) => {
      const value = Number(instance.id.split(':').at(-1));
      return Number.isFinite(value) ? Math.max(maximum, value + 1) : maximum;
    }, 1);
    for (const instance of this.instances) this.createInstanceVisual(instance);
    this.root.visible = false;
  }

  public setActive(active: boolean): void {
    this.active = active;
    this.root.visible = active;
    if (!active) this.pooledLight.intensity = 0;
    if (!active) this.close();
  }

  public togglePalette(): void {
    if (!this.active) return;
    if (this.tracing) {
      this.cancelTrace();
      this.paletteOpen = false;
      this.status = 'Rune tracing cancelled.';
      return;
    }
    this.paletteOpen = !this.paletteOpen;
    this.status = this.paletteOpen
      ? 'Choose a rune from the quick wheel.'
      : 'Rune chalk stowed.';
  }

  public close(): void {
    this.paletteOpen = false;
    this.cancelTrace();
  }

  public isModeActive(): boolean {
    return this.paletteOpen || this.tracing;
  }

  public isTracing(): boolean {
    return this.tracing;
  }

  public selectRune(id: WildernessRuneId): void {
    if (!WILDERNESS_RUNE_CATALOG.some((entry) => entry.id === id)) return;
    this.selectedRuneId = id;
    this.paletteOpen = true;
    this.cancelTrace();
    const definition = wildernessRuneDefinition(id);
    this.status = definition.implemented
      ? `${definition.name} selected.`
      : `${definition.name} has its data contract, but its world effect is reserved for a later pass.`;
  }

  public cycleRune(direction: -1 | 1): void {
    const usable = WILDERNESS_RUNE_CATALOG.filter((entry) =>
      entry.implemented && this.discovered.has(entry.id));
    const index = usable.findIndex((entry) => entry.id === this.selectedRuneId);
    this.selectRune(usable[(Math.max(0, index) + direction + usable.length) % usable.length]!.id);
  }

  public performAction(player: Readonly<{ x: number; z: number; heading: number }>): WildernessRuneActionResult {
    if (!this.paletteOpen && !this.tracing) {
      return { accepted: false, message: 'Open runes first.' };
    }
    if (!this.tracing) return this.beginTrace(player);
    return this.finishTrace();
  }

  public update(
    deltaSeconds: number,
    player: Readonly<{ x: number; z: number; heading: number }>,
    snow: LandSnowSystem,
  ): void {
    if (!this.active) return;
    this.advanceTimers(deltaSeconds);
    for (const [id, visual] of this.visuals) {
      const instance = this.instances.find((candidate) => candidate.id === id);
      if (!instance) continue;
      visual.age += deltaSeconds;
      const pulse = 0.7 + Math.sin(visual.age * 3.2 + id.length) * 0.2;
      visual.material.opacity = pulse * clamp(instance.charge * 2.5, 0.12, 1);
      if (visual.burst && visual.burstMaterial) {
        const expansion = clamp(visual.age / 1.15, 0, 1);
        const easedExpansion = 1 - (1 - expansion) ** 3;
        visual.burst.scale.setScalar(0.12 + easedExpansion * 0.98);
        visual.burstMaterial.opacity = (1 - smoothstep(0.18, 1, expansion)) *
          0.82;
        visual.burst.visible = visual.burstMaterial.opacity > 0.005;
      }
    }
    this.updatePooledLight(player);
    this.snowAccumulator += deltaSeconds;
    if (this.snowAccumulator >= 0.75) {
      this.snowAccumulator = 0;
      const candidates = this.instances
        .filter((instance) => {
          const definition = wildernessRuneDefinition(instance.runeId);
          return definition.effect === 'FIRE_LINE' || definition.effect === 'THAW';
        })
        .sort((a, b) => this.distanceFromRune(player.x, player.z, a) -
          this.distanceFromRune(player.x, player.z, b))
        .slice(0, 3);
      for (const instance of candidates) {
        if (this.distanceFromRune(player.x, player.z, instance) > 34) continue;
        const definition = wildernessRuneDefinition(instance.runeId);
        const stride = Math.max(1, Math.floor(instance.points.length / 8));
        for (let pointIndex = 0; pointIndex < instance.points.length; pointIndex += stride) {
          const point = instance.points[pointIndex]!;
          if (!snow.isTileActiveAt(point.x, point.z)) continue;
          snow.meltSnowRadial(
            point.x,
            point.z,
            definition.effect === 'FIRE_LINE' ? 0.56 : 0.42,
            definition.strength * 0.0024,
            0.012,
            'BACKGROUND',
          );
        }
      }
    }
  }

  /** Writes one held-pointer sample into the active rune stroke. */
  public drawPointerStroke(
    ray: Readonly<Ray>,
    player: Readonly<{ x: number; z: number }>,
    snow: LandSnowSystem,
  ): boolean {
    if (!this.active || !this.tracing) return false;
    const point = this.intersectTerrain(ray, 220);
    if (!point || Math.hypot(point.x - player.x, point.z - player.z) > 8.5) {
      this.status = 'The hand-drawn mark must stay within reach.';
      return false;
    }
    return this.recordTracePoint(point.x, point.z, snow);
  }

  /** Direct world-space seam used by deterministic tests and touch adapters. */
  public drawWorldStrokePoint(
    x: number,
    z: number,
    snow: LandSnowSystem,
  ): boolean {
    if (!this.active || !this.tracing) return false;
    return this.recordTracePoint(x, z, snow);
  }

  /** Rune charge is simulation state and keeps ageing while its scene is hidden. */
  public updatePersistent(deltaSeconds: number): void {
    this.advanceTimers(deltaSeconds);
  }

  private advanceTimers(deltaSeconds: number): void {
    for (let index = this.instances.length - 1; index >= 0; index -= 1) {
      const instance = this.instances[index]!;
      instance.remainingSeconds = Math.max(0, instance.remainingSeconds - deltaSeconds);
      instance.charge = clamp(instance.remainingSeconds /
        Math.max(1, wildernessRuneDefinition(instance.runeId).durationSeconds), 0, 1);
      if (instance.remainingSeconds <= 0) {
        this.removeInstanceAt(index);
      }
    }
  }

  public windMultiplierAt(x: number, z: number): number {
    let multiplier = 1;
    for (const instance of this.instances) {
      const definition = wildernessRuneDefinition(instance.runeId);
      if (definition.effect !== 'WIND_SHELTER') continue;
      const centre = this.centre(instance.points);
      const distance = Math.hypot(x - centre.x, z - centre.z);
      const falloff = clamp(1 - distance / definition.radius, 0, 1);
      multiplier = Math.min(multiplier, 1 - falloff * definition.strength);
    }
    return clamp(multiplier, 0.28, 1);
  }

  public applyWardsToAnimals(animals: WildernessAnimalState[]): void {
    const wards = this.instances.filter((instance) => {
      const effect = wildernessRuneDefinition(instance.runeId).effect;
      return effect === 'WARD' || effect === 'FIRE_LINE';
    });
    for (const animal of animals) {
      if (!['WOLF', 'BEAR', 'POLAR_BEAR', 'FOX'].includes(animal.species)) continue;
      for (const ward of wards) {
        const definition = wildernessRuneDefinition(ward.runeId);
        const centre = this.centre(ward.points);
        const dx = animal.x - centre.x;
        const dz = animal.z - centre.z;
        const distance = Math.max(0.01, Math.hypot(dx, dz));
        if (distance > definition.radius) continue;
        animal.behavior = 'RETREAT';
        animal.retreatSeconds = Math.max(animal.retreatSeconds, 2.4);
        animal.targetX = centre.x + dx / distance * (definition.radius + 5);
        animal.targetZ = centre.z + dz / distance * (definition.radius + 5);
        animal.alert = Math.max(animal.alert, 0.8);
        break;
      }
    }
  }

  public applyCalmToAnimals(animals: WildernessAnimalState[]): void {
    const calmRunes = this.instances.filter((instance) =>
      wildernessRuneDefinition(instance.runeId).effect === 'CALM');
    for (const animal of animals) {
      for (const rune of calmRunes) {
        const definition = wildernessRuneDefinition(rune.runeId);
        const centre = this.centre(rune.points);
        const distance = Math.hypot(animal.x - centre.x, animal.z - centre.z);
        if (distance > definition.radius) continue;
        animal.alert = Math.max(0, animal.alert - definition.strength * 0.04);
        animal.trust = clamp((animal.trust ?? 0) + definition.strength * 0.0008, 0, 1);
        if (animal.behavior === 'FLEE' && (animal.trust ?? 0) > 0.24) {
          animal.targetSeconds = Math.min(animal.targetSeconds, 0.35);
        }
        break;
      }
    }
  }

  public discoverRune(id: WildernessRuneId): WildernessRuneActionResult {
    const definition = wildernessRuneDefinition(id);
    if (!definition.implemented) {
      return { accepted: false, message: `${definition.name} is still dormant.`, tone: 'warning' };
    }
    if (this.discovered.has(id)) {
      return { accepted: false, message: `${definition.name} is already known.` };
    }
    this.discovered.add(id);
    this.selectedRuneId = id;
    this.status = `${definition.name} learned · its mark now turns in the rune wheel.`;
    return { accepted: true, message: this.status, tone: 'achievement' };
  }

  public takeLastAwakened(): Readonly<{
    instanceId: string;
    runeId: WildernessRuneId;
    x: number;
    z: number;
  }> | undefined {
    const id = this.lastAwakenedInstanceId;
    this.lastAwakenedInstanceId = undefined;
    const instance = id
      ? this.instances.find((candidate) => candidate.id === id)
      : undefined;
    if (!instance) return undefined;
    const centre = this.centre(instance.points);
    return { instanceId: instance.id, runeId: instance.runeId, ...centre };
  }

  public absorbInstance(id: string): boolean {
    const index = this.instances.findIndex((instance) => instance.id === id);
    if (index < 0) return false;
    this.removeInstanceAt(index);
    return true;
  }

  public influences(): readonly LocalWorldInfluence[] {
    return this.instances.flatMap((instance): LocalWorldInfluence[] => {
      const definition = wildernessRuneDefinition(instance.runeId);
      const centre = this.centre(instance.points);
      const bounds = {
        minX: centre.x - definition.radius,
        maxX: centre.x + definition.radius,
        minZ: centre.z - definition.radius,
        maxZ: centre.z + definition.radius,
      };
      const entries: LocalWorldInfluence[] = [];
      if (definition.effect === 'FIRE_LINE' || definition.effect === 'HEAT' || definition.effect === 'THAW') {
        entries.push({
          kind: 'THERMAL_SOURCE',
          id: `rune-thermal:${instance.id}`,
          ownerId: instance.id,
          revision: instance.revision + Math.round(instance.charge * 20),
          bounds,
          x: centre.x,
          y: this.terrain.sampleHeight(centre.x, centre.z) + 0.08,
          z: centre.z,
          heatOutput: definition.strength * instance.charge,
          radiantRadius: definition.radius * 0.7,
          convectiveRadius: definition.radius,
          fuelLimited: false,
        });
      }
      if (definition.effect === 'WARD' || definition.effect === 'FIRE_LINE') {
        entries.push({
          kind: 'THREAT_WARD',
          id: `rune-ward:${instance.id}`,
          ownerId: instance.id,
          revision: instance.revision + Math.round(instance.charge * 20),
          bounds,
          x: centre.x,
          z: centre.z,
          radius: definition.radius,
          strength: definition.strength,
          charge: instance.charge,
        });
      }
      return entries;
    });
  }

  public view(): WildernessRuneView {
    const definition = wildernessRuneDefinition(this.selectedRuneId);
    return {
      paletteOpen: this.paletteOpen,
      tracing: this.tracing,
      selectedRuneId: definition.id,
      selectedRuneName: definition.name,
      description: definition.description,
      costLabel: ICEWAY_PLAYTEST_MODE
        ? 'PLAYTEST · offering assisted'
        : definition.offering.map((entry) => `${entry.amount} ${entry.label}`).join(' · '),
      status: this.status,
      activeRunes: this.instances.length,
      implemented: definition.implemented,
      availableRuneIds: WILDERNESS_RUNE_CATALOG
        .filter((entry) => entry.implemented && this.discovered.has(entry.id))
        .map((entry) => entry.id),
    };
  }

  public exportState(): WildernessRuneSaveData {
    return {
      version: 1,
      selectedRuneId: this.selectedRuneId,
      discoveredRuneIds: [...this.discovered],
      instances: this.instances.map((instance) => ({
        ...instance,
        points: instance.points.map((point) => ({ ...point })),
      })),
    };
  }

  public dispose(): void {
    this.cancelTrace();
    for (const visual of this.visuals.values()) {
      visual.root.traverse((object) => {
        if (object instanceof Mesh) object.geometry.dispose();
      });
      visual.material.dispose();
      visual.burstMaterial?.dispose();
      visual.root.removeFromParent();
    }
    this.visuals.clear();
    this.lightRoot.removeFromParent();
    this.root.removeFromParent();
  }

  private beginTrace(player: Readonly<{ x: number; z: number; heading: number }>): WildernessRuneActionResult {
    const definition = wildernessRuneDefinition(this.selectedRuneId);
    if (!definition.implemented) {
      return { accepted: false, message: `${definition.name} is documented but not awakened in v1.`, tone: 'warning' };
    }
    if (!this.canAfford(definition)) {
      return { accepted: false, message: `The mark asks for ${definition.offering.map((entry) => `${entry.amount} ${entry.label}`).join(' · ')}.`, tone: 'warning' };
    }
    const sine = Math.sin(player.heading);
    const cosine = Math.cos(player.heading);
    this.guidePoints = definition.template.map(([right, forward]) => ({
      x: player.x + right * cosine + forward * sine,
      z: player.z - right * sine + forward * cosine,
    }));
    this.tracePoints = [];
    this.tracing = true;
    this.paletteOpen = false;
    this.rebuildGuideVisual(definition);
    this.rebuildTraceVisual(definition);
    this.status = `Draw ${definition.name} · hold the left mouse button and sweep along the glowing mark.`;
    return { accepted: true, message: this.status };
  }

  private finishTrace(): WildernessRuneActionResult {
    const definition = wildernessRuneDefinition(this.selectedRuneId);
    const evaluation = scoreRuneTrace(this.tracePoints, this.guidePoints);
    const threshold = ICEWAY_PLAYTEST_MODE ? 1.15 : 0.72;
    const valid = evaluation.score <= threshold &&
      evaluation.coverage >= 0.38 &&
      evaluation.lengthRatio >= 0.48;
    if (!valid) {
      this.status = `The mark almost wakes · path ${Math.round(evaluation.coverage * 100)}% · stay nearer the guide.`;
      this.cancelTrace(false);
      return { accepted: false, message: this.status, tone: 'warning' };
    }
    if (!this.consume(definition)) {
      this.cancelTrace();
      return { accepted: false, message: 'The offering is no longer in your pack.', tone: 'warning' };
    }
    const instance: WildernessRuneInstanceState = {
      id: `wilderness-rune:${this.serial++}`,
      runeId: definition.id,
      points: this.tracePoints.map((point) => ({ ...point })),
      remainingSeconds: definition.durationSeconds,
      charge: 1,
      revision: 1,
    };
    this.instances.push(instance);
    this.lastAwakenedInstanceId = instance.id;
    this.discovered.add(definition.id);
    this.createInstanceVisual(instance);
    this.cancelTrace();
    this.paletteOpen = false;
    this.status = `${definition.name} awakens · ${Math.round(definition.durationSeconds / 60)} calm minutes.`;
    return { accepted: true, message: this.status, tone: 'achievement' };
  }

  private recordTracePoint(
    x: number,
    z: number,
    snow: LandSnowSystem,
  ): boolean {
    const previous = this.tracePoints.at(-1);
    if (previous && Math.hypot(x - previous.x, z - previous.z) < TRACE_STEP_METRES) return false;
    if (this.tracePoints.length >= MAX_TRACE_POINTS) return false;
    if (previous) snow.brushRuneStroke(previous.x, previous.z, x, z);
    this.tracePoints.push({ x, z });
    this.rebuildTraceVisual(wildernessRuneDefinition(this.selectedRuneId));
    return true;
  }

  private rebuildGuideVisual(definition: Readonly<WildernessRuneDefinition>): void {
    if (this.guideLine) {
      this.guideLine.geometry.dispose();
      (this.guideLine.material as MeshBasicMaterial).dispose();
      this.guideLine.removeFromParent();
    }
    const points = this.guidePoints.map((point) => new Vector3(
      point.x,
      this.terrain.sampleHeight(point.x, point.z) + 0.055,
      point.z,
    ));
    const curve = new CatmullRomCurve3(points, false, 'centripetal');
    this.guideLine = new Mesh(
      new TubeGeometry(curve, Math.min(128, Math.max(16, points.length * 5)), 0.052, 6, false),
      new MeshBasicMaterial({
        color: definition.color,
        transparent: true,
        opacity: 0.68,
        depthWrite: false,
        depthTest: false,
        toneMapped: false,
      }),
    );
    this.guideLine.renderOrder = 9_970;
    this.guideRoot.add(this.guideLine);
  }

  private rebuildTraceVisual(definition: Readonly<WildernessRuneDefinition>): void {
    if (this.traceLine) {
      this.traceLine.geometry.dispose();
      (this.traceLine.material as MeshBasicMaterial).dispose();
      this.traceLine.removeFromParent();
    }
    const points = this.tracePoints.map((point) => new Vector3(
      point.x,
      this.terrain.sampleHeight(point.x, point.z) + 0.075,
      point.z,
    ));
    if (points.length === 0) {
      this.traceLine = undefined;
      return;
    }
    if (points.length === 1) {
      points.push(points[0]!.clone().add(new Vector3(0.008, 0, 0.008)));
    }
    const curve = new CatmullRomCurve3(points, false, 'centripetal');
    this.traceLine = new Mesh(
      new TubeGeometry(curve, Math.min(160, Math.max(8, points.length * 4)), 0.064, 6, false),
      new MeshBasicMaterial({
        color: 0xffe39b,
        transparent: true,
        opacity: 0.96,
        depthWrite: false,
        depthTest: false,
        toneMapped: false,
      }),
    );
    this.traceLine.renderOrder = 9_975;
    this.guideRoot.add(this.traceLine);
    void definition;
  }

  private createInstanceVisual(instance: Readonly<WildernessRuneInstanceState>): void {
    const definition = wildernessRuneDefinition(instance.runeId);
    const root = new Group();
    root.name = `Awakened rune · ${definition.name}`;
    const points = instance.points.map((point) => new Vector3(
      point.x,
      this.terrain.sampleHeight(point.x, point.z) + 0.045,
      point.z,
    ));
    if (points.length === 1) points.push(points[0]!.clone().add(new Vector3(0.01, 0, 0)));
    const material = new MeshBasicMaterial({
      color: definition.color,
      transparent: true,
      opacity: 0.8,
      depthWrite: false,
      toneMapped: false,
    });
    if (points.length >= 2) {
      const curve = new CatmullRomCurve3(points, false, 'centripetal');
      const tube = new Mesh(
        new TubeGeometry(curve, Math.min(96, Math.max(8, points.length * 2)), 0.026, 5, false),
        material,
      );
      tube.renderOrder = 8;
      root.add(tube);
    }
    const centre = this.centre(instance.points);
    const focus = new Mesh(
      new SphereGeometry(0.09, 8, 5),
      material,
    );
    focus.position.set(centre.x, this.terrain.sampleHeight(centre.x, centre.z) + 0.12, centre.z);
    root.add(focus);
    let burst: Mesh | undefined;
    let burstMaterial: MeshBasicMaterial | undefined;
    if (definition.effect === 'CLEAR_SNOW') {
      // The mark clears an exact five-metre camp square. A fast expanding
      // rounded-square breath makes that footprint readable without spawning
      // a CPU particle burst or leaving a permanent placement decal.
      const halfSize = definition.radius;
      const burstPoints = [
        new Vector3(-halfSize, 0, -halfSize),
        new Vector3(halfSize, 0, -halfSize),
        new Vector3(halfSize, 0, halfSize),
        new Vector3(-halfSize, 0, halfSize),
        new Vector3(-halfSize, 0, -halfSize),
      ];
      burstMaterial = new MeshBasicMaterial({
        color: definition.color,
        transparent: true,
        opacity: 0.82,
        depthWrite: false,
        depthTest: false,
        toneMapped: false,
      });
      burst = new Mesh(
        new TubeGeometry(
          new CatmullRomCurve3(burstPoints, false, 'centripetal'),
          44,
          0.045,
          5,
          false,
        ),
        burstMaterial,
      );
      burst.name = 'Winter Palm five metre clearing breath';
      burst.position.set(
        centre.x,
        this.terrain.sampleHeight(centre.x, centre.z) + 0.09,
        centre.z,
      );
      burst.scale.setScalar(0.12);
      burst.renderOrder = 9;
      root.add(burst);
    }
    this.instanceRoot.add(root);
    this.visuals.set(instance.id, {
      root,
      material,
      burst,
      burstMaterial,
      age: 0,
    });
  }

  private updatePooledLight(
    player: Readonly<{ x: number; z: number }>,
  ): void {
    const instance = this.instances
      .filter((candidate) => ['FIRE_LINE', 'LIGHT', 'BEACON', 'THAW']
        .includes(wildernessRuneDefinition(candidate.runeId).effect))
      .sort((left, right) =>
        this.distanceFromRune(player.x, player.z, left) -
        this.distanceFromRune(player.x, player.z, right))[0];
    if (!this.active || !instance) {
      this.pooledLight.intensity = 0;
      return;
    }
    const definition = wildernessRuneDefinition(instance.runeId);
    const centre = this.centre(instance.points);
    const visual = this.visuals.get(instance.id);
    const pulse = 0.7 + Math.sin((visual?.age ?? 0) * 3.2 + instance.id.length) * 0.2;
    this.pooledLight.color.setHex(definition.color);
    this.pooledLight.position.set(
      centre.x,
      this.terrain.sampleHeight(centre.x, centre.z) + 0.42,
      centre.z,
    );
    this.pooledLight.distance = definition.effect === 'LIGHT' ? 8 : 5.5;
    this.pooledLight.intensity = pulse * instance.charge * 1.8;
  }

  private removeInstanceAt(index: number): void {
    const [instance] = this.instances.splice(index, 1);
    if (!instance) return;
    const visual = this.visuals.get(instance.id);
    if (visual) {
      visual.root.traverse((object) => {
        if (object instanceof Mesh) object.geometry.dispose();
      });
      visual.material.dispose();
      visual.burstMaterial?.dispose();
      visual.root.removeFromParent();
      this.visuals.delete(instance.id);
    }
  }

  private cancelTrace(resetStatus = true): void {
    this.tracing = false;
    this.guidePoints = [];
    this.tracePoints = [];
    if (this.guideLine) {
      this.guideLine.geometry.dispose();
      (this.guideLine.material as MeshBasicMaterial).dispose();
      this.guideLine.removeFromParent();
      this.guideLine = undefined;
    }
    if (this.traceLine) {
      this.traceLine.geometry.dispose();
      (this.traceLine.material as MeshBasicMaterial).dispose();
      this.traceLine.removeFromParent();
      this.traceLine = undefined;
    }
    if (resetStatus) this.status = 'Choose a mark, then draw its glowing guide into the snow.';
  }

  private intersectTerrain(
    ray: Readonly<Ray>,
    maximumDistance: number,
  ): Vector3 | undefined {
    let previousT = 0;
    this.raySample.copy(ray.origin);
    let previousDelta = this.raySample.y -
      this.terrain.sampleHeight(this.raySample.x, this.raySample.z);
    const step = Math.max(0.4, maximumDistance / 160);
    for (let t = step; t <= maximumDistance; t += step) {
      this.raySample.copy(ray.direction).multiplyScalar(t).add(ray.origin);
      const delta = this.raySample.y -
        this.terrain.sampleHeight(this.raySample.x, this.raySample.z);
      if (delta <= 0 && previousDelta >= 0) {
        let low = previousT;
        let high = t;
        for (let iteration = 0; iteration < 7; iteration += 1) {
          const middle = (low + high) * 0.5;
          this.raySample.copy(ray.direction).multiplyScalar(middle).add(ray.origin);
          const middleDelta = this.raySample.y -
            this.terrain.sampleHeight(this.raySample.x, this.raySample.z);
          if (middleDelta > 0) low = middle;
          else high = middle;
        }
        this.raySample.copy(ray.direction)
          .multiplyScalar((low + high) * 0.5)
          .add(ray.origin);
        this.raySample.y = this.terrain.sampleHeight(
          this.raySample.x,
          this.raySample.z,
        );
        return this.raySample.clone();
      }
      previousT = t;
      previousDelta = delta;
    }
    return undefined;
  }

  private canAfford(definition: Readonly<WildernessRuneDefinition>): boolean {
    return ICEWAY_PLAYTEST_MODE || definition.offering.every((entry) =>
      this.inventory[entry.inventory] >= entry.amount);
  }

  private consume(definition: Readonly<WildernessRuneDefinition>): boolean {
    if (!this.canAfford(definition)) return false;
    if (ICEWAY_PLAYTEST_MODE) return true;
    for (const entry of definition.offering) this.inventory[entry.inventory] -= entry.amount;
    return true;
  }

  private centre(points: readonly Readonly<{ x: number; z: number }>[]): { x: number; z: number } {
    if (points.length === 0) return { x: 0, z: 0 };
    const total = points.reduce(
      (sum, point) => ({ x: sum.x + point.x, z: sum.z + point.z }),
      { x: 0, z: 0 },
    );
    return { x: total.x / points.length, z: total.z / points.length };
  }

  private distanceFromRune(x: number, z: number, instance: Readonly<WildernessRuneInstanceState>): number {
    const centre = this.centre(instance.points);
    return Math.hypot(x - centre.x, z - centre.z);
  }
}
