import {
  cloneGlobalPosition,
  globalPositionToAbsoluteMetres,
  isGlobalPositionInPartition,
  type GlobalPosition,
} from '../../world/GlobalPosition';
import type { WorldChunkAddress } from '../../world/WorldPartitionTypes';
import type { RadioTransmitterDefinition } from './RadioNetworkTypes';
import { RadioNetworkRegistry } from './RadioNetworkRegistry';

export const RADIO_MAXIMUM_RANGE_MULTIPLIER = 1.15;

export interface RadioIndexedTransmitter {
  transmitterId: string;
  stationId: string;
  regionId: string;
  frequencyId: string;
  worldPosition: GlobalPosition;
  coverageProfileId: string;
  maximumIndexedRadiusMetres: number;
  towerId?: string;
  enabledByDefault: boolean;
}

export interface RadioSpatialIndexStats {
  transmitters: number;
  activeByDefault: number;
  occupiedChunks: number;
  indexedReferences: number;
  maximumCandidatesPerChunk: number;
}

const chunkKey = (
  chunk: Readonly<WorldChunkAddress>,
): string => `${chunk.x}:${chunk.z}`;

const circleIntersectsChunk = (
  centerX: number,
  centerZ: number,
  radius: number,
  chunk: Readonly<WorldChunkAddress>,
  chunkSizeMetres: number,
): boolean => {
  const minimumX = chunk.x * chunkSizeMetres;
  const minimumZ = chunk.z * chunkSizeMetres;
  const maximumX = minimumX + chunkSizeMetres;
  const maximumZ = minimumZ + chunkSizeMetres;
  const closestX = Math.max(
    minimumX,
    Math.min(maximumX, centerX),
  );
  const closestZ = Math.max(
    minimumZ,
    Math.min(maximumZ, centerZ),
  );
  const distanceX = centerX - closestX;
  const distanceZ = centerZ - closestZ;
  return (
    distanceX * distanceX + distanceZ * distanceZ <=
    radius * radius
  );
};

const cloneIndexedTransmitter = (
  value: Readonly<RadioIndexedTransmitter>,
): RadioIndexedTransmitter => ({
  ...value,
  worldPosition: cloneGlobalPosition(value.worldPosition),
});

export class RadioSpatialIndex {
  private readonly registry: RadioNetworkRegistry;
  private readonly transmittersById = new Map<
    string,
    RadioIndexedTransmitter
  >();
  private readonly transmittersByChunk = new Map<
    string,
    readonly RadioIndexedTransmitter[]
  >();
  private readonly stats: RadioSpatialIndexStats;

  public constructor(registry: RadioNetworkRegistry) {
    this.registry = registry;
    const mutableChunkEntries = new Map<
      string,
      RadioIndexedTransmitter[]
    >();

    for (const definition of registry.definitions.transmitters) {
      const indexed = this.resolveTransmitter(definition);
      this.transmittersById.set(
        indexed.transmitterId,
        indexed,
      );
      this.indexTransmitter(indexed, mutableChunkEntries);
    }

    let indexedReferences = 0;
    let maximumCandidatesPerChunk = 0;
    for (const [key, values] of mutableChunkEntries) {
      values.sort((left, right) =>
        left.transmitterId.localeCompare(
          right.transmitterId,
        ),
      );
      const frozen = Object.freeze([...values]);
      this.transmittersByChunk.set(key, frozen);
      indexedReferences += frozen.length;
      maximumCandidatesPerChunk = Math.max(
        maximumCandidatesPerChunk,
        frozen.length,
      );
    }

    this.stats = Object.freeze({
      transmitters: this.transmittersById.size,
      activeByDefault:
        registry.definitions.transmitters.filter(
          (transmitter) => transmitter.enabledByDefault,
        ).length,
      occupiedChunks: this.transmittersByChunk.size,
      indexedReferences,
      maximumCandidatesPerChunk,
    });
  }

  public getCandidates(
    receiverPosition: Readonly<GlobalPosition>,
  ): readonly RadioIndexedTransmitter[] {
    if (
      !isGlobalPositionInPartition(
        this.registry.partition,
        receiverPosition,
      )
    ) {
      return [];
    }
    return (
      this.transmittersByChunk.get(
        chunkKey(receiverPosition.chunk),
      ) ?? []
    );
  }

  public getTransmitter(
    transmitterId: string,
  ): RadioIndexedTransmitter | undefined {
    const transmitter =
      this.transmittersById.get(transmitterId);
    return transmitter
      ? cloneIndexedTransmitter(transmitter)
      : undefined;
  }

  public getStats(): RadioSpatialIndexStats {
    return { ...this.stats };
  }

  private resolveTransmitter(
    definition: Readonly<RadioTransmitterDefinition>,
  ): RadioIndexedTransmitter {
    if (definition.source.kind === 'TOWER') {
      const tower = this.registry.getTower(
        definition.source.towerId,
      )!;
      const profile = this.registry.getCoverageProfile(
        tower.coverageProfileId,
      )!;
      return Object.freeze({
        transmitterId: definition.id,
        stationId: definition.stationId,
        regionId: definition.regionId,
        frequencyId: definition.frequencyId,
        worldPosition: Object.freeze(
          cloneGlobalPosition(tower.worldPosition),
        ),
        coverageProfileId: profile.id,
        maximumIndexedRadiusMetres:
          profile.maximumRadiusMetres *
          RADIO_MAXIMUM_RANGE_MULTIPLIER,
        towerId: tower.id,
        enabledByDefault: definition.enabledByDefault,
      });
    }

    const profile = this.registry.getCoverageProfile(
      definition.source.coverageProfileId,
    )!;
    return Object.freeze({
      transmitterId: definition.id,
      stationId: definition.stationId,
      regionId: definition.regionId,
      frequencyId: definition.frequencyId,
      worldPosition: Object.freeze(
        cloneGlobalPosition(
          definition.source.worldPosition,
        ),
      ),
      coverageProfileId: profile.id,
      maximumIndexedRadiusMetres:
        profile.maximumRadiusMetres,
      enabledByDefault: definition.enabledByDefault,
    });
  }

  private indexTransmitter(
    transmitter: Readonly<RadioIndexedTransmitter>,
    entries: Map<string, RadioIndexedTransmitter[]>,
  ): void {
    const partition = this.registry.partition;
    const size = partition.chunkSizeMetres;
    const center = globalPositionToAbsoluteMetres(
      partition,
      transmitter.worldPosition,
    );
    const radius =
      transmitter.maximumIndexedRadiusMetres;
    const minimumPartitionX = partition.minimumChunk.x;
    const minimumPartitionZ = partition.minimumChunk.z;
    const maximumPartitionX =
      minimumPartitionX + partition.chunkColumns - 1;
    const maximumPartitionZ =
      minimumPartitionZ + partition.chunkRows - 1;
    const minimumChunkX = Math.max(
      minimumPartitionX,
      Math.floor((center.xMetres - radius) / size),
    );
    const maximumChunkX = Math.min(
      maximumPartitionX,
      Math.floor((center.xMetres + radius) / size),
    );
    const minimumChunkZ = Math.max(
      minimumPartitionZ,
      Math.floor((center.zMetres - radius) / size),
    );
    const maximumChunkZ = Math.min(
      maximumPartitionZ,
      Math.floor((center.zMetres + radius) / size),
    );

    for (
      let chunkZ = minimumChunkZ;
      chunkZ <= maximumChunkZ;
      chunkZ += 1
    ) {
      for (
        let chunkX = minimumChunkX;
        chunkX <= maximumChunkX;
        chunkX += 1
      ) {
        const chunk = { x: chunkX, z: chunkZ };
        if (
          !circleIntersectsChunk(
            center.xMetres,
            center.zMetres,
            radius,
            chunk,
            size,
          )
        ) {
          continue;
        }
        const key = chunkKey(chunk);
        const values = entries.get(key) ?? [];
        values.push(transmitter as RadioIndexedTransmitter);
        entries.set(key, values);
      }
    }
  }
}
