import { SettlementBuildingSystem, type SettlementStaffResolver } from './SettlementBuildingSystem';
import { SettlementContentRegistry } from './SettlementContentRegistry';
import { SettlementCropSystem } from './SettlementCropSystem';
import { SettlementCultivationSystem } from './SettlementCultivationSystem';
import { SettlementAnimalSystem } from './SettlementAnimalSystem';
import { SettlementProductionSystem } from './SettlementProductionSystem';
import { SettlementResourceNodeSystem } from './SettlementResourceNodeSystem';
import { SettlementTrainSystem } from './SettlementTrainSystem';
import type {
  SettlementContentDefinitionSet,
  SettlementGoodAmount,
  SettlementMutationResult,
  SettlementSaveData,
  SettlementSnapshot,
  SettlementUpdateResult,
} from './SettlementTypes';
import { SettlementWarehouse } from './SettlementWarehouse';

const validRequestId = (value: string): boolean =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= 192;

/**
 * World-owned facade for village restoration, storage and production.
 * Request IDs make reliable multiplayer retries idempotent without coupling
 * the domain model to a transport protocol.
 */
export class SettlementSystem {
  public readonly registry: SettlementContentRegistry;
  public readonly warehouse: SettlementWarehouse;
  public readonly buildings: SettlementBuildingSystem;
  public readonly production: SettlementProductionSystem;
  public readonly train: SettlementTrainSystem;
  public readonly resourceNodes: SettlementResourceNodeSystem;
  public readonly cropPlots: SettlementCropSystem;
  public readonly cultivation: SettlementCultivationSystem;
  public readonly animals: SettlementAnimalSystem;

  private readonly processedRequestIds = new Set<string>();
  private revision = 0;
  private lastSimulationTime = 0;

  public constructor(
    definitions: Readonly<SettlementContentDefinitionSet>,
    resolveStaff: SettlementStaffResolver = () => 'ASSIGNED',
    saved?: Readonly<SettlementSaveData>,
  ) {
    this.registry = new SettlementContentRegistry(definitions);
    const compatible = saved?.version === 1 && saved.definitionSetId === definitions.id
      ? saved
      : undefined;
    this.revision = compatible && Number.isSafeInteger(compatible.revision) && compatible.revision >= 0
      ? compatible.revision
      : 0;
    this.lastSimulationTime = compatible && Number.isFinite(compatible.lastSimulationTime)
      ? Math.max(0, compatible.lastSimulationTime ?? 0)
      : 0;
    for (const requestId of compatible?.processedRequestIds ?? []) {
      if (validRequestId(requestId)) this.processedRequestIds.add(requestId);
    }
    this.warehouse = new SettlementWarehouse(this.registry, compatible?.warehouse);
    this.buildings = new SettlementBuildingSystem(
      this.registry,
      resolveStaff,
      compatible?.buildings,
    );
    this.production = new SettlementProductionSystem(
      this.registry,
      this.buildings,
      this.warehouse,
      compatible?.production,
    );
    this.resourceNodes = new SettlementResourceNodeSystem(
      this.registry,
      this.warehouse,
      compatible?.resourceNodes,
    );
    this.cropPlots = new SettlementCropSystem(
      this.registry,
      this.warehouse,
      compatible?.cropPlots,
    );
    this.cultivation = new SettlementCultivationSystem(
      this.registry,
      this.warehouse,
      compatible?.cultivation,
    );
    this.animals = new SettlementAnimalSystem(
      this.registry,
      this.warehouse,
      compatible?.animals,
    );
    this.train = new SettlementTrainSystem(
      definitions.train,
      this.buildings,
      this.warehouse,
      compatible?.train,
    );
  }

  public grantGoods(
    requestId: string,
    goods: readonly Readonly<SettlementGoodAmount>[],
  ): SettlementMutationResult {
    return this.process(requestId, () => {
      if (!this.warehouse.canApply(goods, 1)) {
        return { accepted: false, stateChanged: false, status: 'WAREHOUSE_FULL_OR_INVALID' };
      }
      const quantity = goods.reduce((total, amount) => total + amount.quantity, 0);
      const changed = this.warehouse.apply(goods, 1);
      return { accepted: changed, stateChanged: changed, status: changed ? 'GOODS_GRANTED' : 'NO_CHANGE', quantity };
    });
  }

  public contributeToBuilding(
    requestId: string,
    buildingId: string,
    goodId: string,
    requestedQuantity: number,
  ): SettlementMutationResult {
    return this.process(requestId, () => {
      if (!Number.isSafeInteger(requestedQuantity) || requestedQuantity <= 0) {
        return { accepted: false, stateChanged: false, status: 'INVALID_QUANTITY' };
      }
      const quantity = Math.min(
        requestedQuantity,
        this.buildings.contributionCapacity(buildingId, goodId),
        this.warehouse.getQuantity(goodId),
      );
      if (quantity <= 0) {
        return { accepted: false, stateChanged: false, status: 'NOTHING_TO_CONTRIBUTE' };
      }
      if (!this.warehouse.apply([{ goodId, quantity }], -1)) {
        return { accepted: false, stateChanged: false, status: 'WAREHOUSE_TRANSACTION_FAILED' };
      }
      if (!this.buildings.contribute(buildingId, goodId, quantity)) {
        // The single-threaded domain should never race, but preserve mass if
        // a future caller introduces a conflicting mutation.
        this.warehouse.apply([{ goodId, quantity }], 1);
        return { accepted: false, stateChanged: false, status: 'BUILDING_TRANSACTION_FAILED' };
      }
      return { accepted: true, stateChanged: true, status: 'MATERIALS_CONTRIBUTED', quantity };
    });
  }

  public startBuildingWork(
    requestId: string,
    buildingId: string,
    simulationTime: number,
  ): SettlementMutationResult {
    return this.process(requestId, () => {
      const changed = this.buildings.startWork(buildingId, simulationTime);
      return {
        accepted: changed,
        stateChanged: changed,
        status: changed ? 'BUILDING_WORK_STARTED' : 'BUILDING_NOT_READY',
      };
    });
  }

  public startProduction(
    requestId: string,
    recipeId: string,
    simulationTime: number,
  ): SettlementMutationResult {
    return this.process(requestId, () => {
      const result = this.production.start(
        recipeId,
        simulationTime,
        `settlement-operation:${requestId}`,
      );
      return {
        accepted: result.accepted,
        stateChanged: result.accepted,
        status: result.status,
        operationId: result.operationId,
      };
    });
  }

  public collectProduction(
    requestId: string,
    operationId: string,
  ): SettlementMutationResult {
    return this.process(requestId, () => {
      const status = this.production.collect(operationId);
      const changed = status === 'OUTPUT_COLLECTED';
      return { accepted: changed, stateChanged: changed, status, operationId };
    });
  }

  public hasProcessedRequest(requestId: string): boolean {
    return this.processedRequestIds.has(requestId);
  }

  public contributeToTrainManifest(
    requestId: string,
    goodId: string,
    requestedQuantity: number,
  ): SettlementMutationResult {
    return this.process(requestId, () => {
      const quantity = this.train.contribute(goodId, requestedQuantity);
      return {
        accepted: quantity > 0,
        stateChanged: quantity > 0,
        status: quantity > 0 ? 'TRAIN_MANIFEST_CONTRIBUTED' : 'TRAIN_MANIFEST_REJECTED',
        quantity,
      };
    });
  }

  public dispatchTrain(
    requestId: string,
    simulationTime: number,
  ): SettlementMutationResult {
    this.lastSimulationTime = Math.max(this.lastSimulationTime, simulationTime);
    return this.process(requestId, () => {
      const changed = this.train.dispatch(simulationTime);
      return {
        accepted: changed,
        stateChanged: changed,
        status: changed ? 'TRAIN_DISPATCHED' : 'TRAIN_NOT_READY',
      };
    });
  }

  public harvestResourceNode(
    requestId: string,
    nodeId: string,
    simulationTime: number,
  ): SettlementMutationResult {
    this.lastSimulationTime = Math.max(this.lastSimulationTime, simulationTime);
    return this.process(requestId, () =>
      this.resourceNodes.harvest(nodeId, simulationTime));
  }

  public plantCrop(
    requestId: string,
    plotId: string,
    cropId: string,
    simulationTime: number,
  ): SettlementMutationResult {
    this.lastSimulationTime = Math.max(this.lastSimulationTime, simulationTime);
    return this.process(requestId, () =>
      this.cropPlots.plant(plotId, cropId, simulationTime));
  }

  public harvestCrop(
    requestId: string,
    plotId: string,
    simulationTime: number,
  ): SettlementMutationResult {
    this.lastSimulationTime = Math.max(this.lastSimulationTime, simulationTime);
    return this.process(requestId, () =>
      this.cropPlots.harvest(plotId, simulationTime));
  }

  public tillCultivationPatch(
    requestId: string,
    patchId: string,
  ): SettlementMutationResult {
    return this.process(requestId, () => this.cultivation.tillPatch(patchId));
  }

  public restoreCultivationLawn(
    requestId: string,
    patchId: string,
  ): SettlementMutationResult {
    return this.process(requestId, () => this.cultivation.restoreLawnPatch(patchId));
  }

  public clearCultivationLeaves(
    requestId: string,
    patchId: string,
  ): SettlementMutationResult {
    return this.process(requestId, () => this.cultivation.clearLeavesPatch(patchId));
  }

  public blowCultivationLeaves(
    x: number,
    z: number,
    heading: number,
    deltaSeconds: number,
  ): ReturnType<SettlementCultivationSystem['blowLeaves']> {
    const result = this.cultivation.blowLeaves(x, z, heading, deltaSeconds);
    if (result.changed) this.revision += 1;
    return result;
  }

  public plantCultivationPatch(
    requestId: string,
    patchId: string,
    plantId: string,
    simulationTime: number,
  ): SettlementMutationResult {
    this.lastSimulationTime = Math.max(this.lastSimulationTime, simulationTime);
    return this.process(requestId, () =>
      this.cultivation.plantPatch(patchId, plantId, simulationTime));
  }

  public sickleCultivationPatch(
    requestId: string,
    patchId: string,
    simulationTime: number,
  ): SettlementMutationResult {
    this.lastSimulationTime = Math.max(this.lastSimulationTime, simulationTime);
    return this.process(requestId, () =>
      this.cultivation.sicklePatch(patchId, simulationTime));
  }

  public collectAnimalProducts(
    requestId: string,
    habitatId: string,
    simulationTime: number,
  ): SettlementMutationResult {
    this.lastSimulationTime = Math.max(this.lastSimulationTime, simulationTime);
    return this.process(requestId, () =>
      this.animals.collectHabitatProducts(habitatId, simulationTime));
  }

  public upgradeAnimalHabitat(
    requestId: string,
    habitatId: string,
    simulationTime: number,
  ): SettlementMutationResult {
    this.lastSimulationTime = Math.max(this.lastSimulationTime, simulationTime);
    return this.process(requestId, () =>
      this.animals.upgradeHabitat(habitatId, simulationTime));
  }

  public update(simulationTime: number): SettlementUpdateResult {
    this.lastSimulationTime = Math.max(this.lastSimulationTime, simulationTime);
    const completedBuildingIds = this.buildings.update(simulationTime);
    const readyProductionOperationIds = this.production.update(simulationTime);
    const trainChanged = this.train.update(simulationTime);
    const resourceNodesChanged = this.resourceNodes.update(simulationTime);
    const cropPlotsChanged = this.cropPlots.update(simulationTime);
    const cultivationChanged = this.cultivation.update(simulationTime);
    const animalsChanged = this.animals.update(simulationTime);
    const stateChanged = completedBuildingIds.length > 0 ||
      readyProductionOperationIds.length > 0 || trainChanged ||
      resourceNodesChanged;
    const combinedStateChanged = stateChanged || cropPlotsChanged ||
      cultivationChanged || animalsChanged;
    if (combinedStateChanged) this.revision += 1;
    return {
      stateChanged: combinedStateChanged,
      completedBuildingIds,
      readyProductionOperationIds,
    };
  }

  public snapshot(simulationTime = this.lastSimulationTime): SettlementSnapshot {
    return {
      definitionSetId: this.registry.definitions.id,
      revision: this.revision,
      warehouse: this.warehouse.snapshot(),
      buildings: this.buildings.getViews(),
      production: this.production.getViews(),
      train: this.train.snapshot(simulationTime),
      resourceNodes: this.resourceNodes.getViews(simulationTime),
      cropPlots: this.cropPlots.getViews(simulationTime),
      cultivation: this.cultivation.getPatchViews(simulationTime),
      animalHabitats: this.animals.getHabitatViews(simulationTime),
    };
  }

  public exportState(): SettlementSaveData {
    return {
      version: 1,
      definitionSetId: this.registry.definitions.id,
      revision: this.revision,
      lastSimulationTime: this.lastSimulationTime,
      warehouse: this.warehouse.exportState(),
      buildings: this.buildings.exportState(),
      production: this.production.exportState(),
      train: this.train.exportState(),
      resourceNodes: this.resourceNodes.exportState(),
      cropPlots: this.cropPlots.exportState(),
      cultivation: this.cultivation.exportState(),
      animals: this.animals.exportState(),
      processedRequestIds: [...this.processedRequestIds],
    };
  }

  private process(
    requestId: string,
    mutate: () => SettlementMutationResult,
  ): SettlementMutationResult {
    if (!validRequestId(requestId)) {
      return { accepted: false, stateChanged: false, status: 'INVALID_REQUEST_ID' };
    }
    if (this.processedRequestIds.has(requestId)) {
      return { accepted: false, stateChanged: false, status: 'DUPLICATE_REQUEST' };
    }
    const result = mutate();
    this.processedRequestIds.add(requestId);
    while (this.processedRequestIds.size > 2_048) {
      const oldest = this.processedRequestIds.values().next().value as string | undefined;
      if (!oldest) break;
      this.processedRequestIds.delete(oldest);
    }
    if (result.stateChanged) this.revision += 1;
    return result;
  }
}
