import {
  CONSTRUCTION_GRID_METRES,
  type ConstructionBlueprint,
  type ConstructionDirection,
  type ConstructionPlacement,
} from './ConstructionBlueprint';
import { Euler, MathUtils, Quaternion, Vector3 } from 'three';
import type {
  ConstructionModuleDefinition,
  ConstructionModuleSocket,
} from './ConstructionModuleCatalog';
import {
  constructionSocketsCompatibleHeadless,
} from './ConstructionConnectionRules';

export interface ResolvedConstructionSocket {
  placementId: string;
  moduleId: string;
  socket: ConstructionModuleSocket;
  position: ConstructionDirection;
  normal: ConstructionDirection;
}

/**
 * Minimal socket frame shared by vehicle construction and diegetic world
 * building. The world builder deliberately keeps this independent from a
 * blueprint/grid so a survival wall can snap directly to another live piece.
 */
export interface WorldConstructionSocketFrame {
  readonly position: Readonly<ConstructionDirection>;
  readonly normal: Readonly<ConstructionDirection>;
}

export interface WorldSocketSnappedTransform {
  readonly x: number;
  readonly y: number;
  readonly z: number;
  readonly yawDegrees: number;
}

const normalizeDegrees = (degrees: number): number =>
  ((degrees + 180) % 360 + 360) % 360 - 180;

/**
 * Aligns a local, horizontal source socket to an exposed world socket. This
 * is the same source-normal-to-opposite-target-normal rule used by the vessel
 * editor, reduced to yaw so terrain construction remains calm and readable.
 */
export const createWorldSocketSnappedTransform = (options: {
  readonly target: Readonly<WorldConstructionSocketFrame>;
  readonly source: Readonly<WorldConstructionSocketFrame>;
  readonly yawOffsetDegrees?: number;
}): WorldSocketSnappedTransform | undefined => {
  const targetNormal = new Vector3(
    options.target.normal.x,
    0,
    options.target.normal.z,
  );
  const sourceNormal = new Vector3(
    options.source.normal.x,
    0,
    options.source.normal.z,
  );
  if (targetNormal.lengthSq() < 0.25 || sourceNormal.lengthSq() < 0.25) {
    return undefined;
  }
  targetNormal.normalize();
  sourceNormal.normalize();
  const desiredAngle = Math.atan2(-targetNormal.x, -targetNormal.z);
  const sourceAngle = Math.atan2(sourceNormal.x, sourceNormal.z);
  const yawDegrees = normalizeDegrees(
    MathUtils.radToDeg(desiredAngle - sourceAngle) +
      (options.yawOffsetDegrees ?? 0),
  );
  const yaw = MathUtils.degToRad(yawDegrees);
  const cosine = Math.cos(yaw);
  const sine = Math.sin(yaw);
  const localX = options.source.position.x * cosine +
    options.source.position.z * sine;
  const localZ = -options.source.position.x * sine +
    options.source.position.z * cosine;
  return {
    x: options.target.position.x - localX,
    y: options.target.position.y - options.source.position.y,
    z: options.target.position.z - localZ,
    yawDegrees,
  };
};

const transformLocalDirection = (
  direction: Readonly<ConstructionDirection>,
  rotation: Readonly<{
    pitchDegrees: number;
    yawDegrees: number;
    rollDegrees: number;
  }>,
  flipped: boolean,
): ConstructionDirection => {
  const vector = new Vector3(
    direction.x,
    direction.y,
    flipped ? -direction.z : direction.z,
  ).applyEuler(
    new Euler(
      MathUtils.degToRad(rotation.pitchDegrees),
      MathUtils.degToRad(rotation.yawDegrees),
      MathUtils.degToRad(rotation.rollDegrees),
      'XYZ',
    ),
  );
  return {
    x: vector.x,
    y: vector.y,
    z: vector.z,
  };
};

export const constructionSocketsCompatible = (
  target: Readonly<ConstructionModuleSocket>,
  source: Readonly<ConstructionModuleSocket>,
): boolean => constructionSocketsCompatibleHeadless(target, source);

const oppositeSocketId = (id: string): string | undefined => {
  if (id === 'left') return 'right';
  if (id === 'right') return 'left';
  if (id === 'forward') return 'aft';
  if (id === 'aft') return 'forward';
  if (id === 'top') return 'bottom';
  if (id === 'bottom') return 'top';
  if (id === 'port') return 'starboard';
  if (id === 'starboard') return 'port';
  if (id === 'inner') return 'outer';
  if (id === 'outer') return 'inner';
  return undefined;
};

/**
 * Keeps automatic construction readable: a continuation prefers the other
 * end of a part, while still allowing deliberate perpendicular deck and
 * transition joins when no direct continuation is available.
 */
export const constructionSocketMatePenalty = (
  target: Readonly<ConstructionModuleSocket>,
  source: Readonly<ConstructionModuleSocket>,
): number => {
  if (!constructionSocketsCompatible(target, source)) {
    return Number.POSITIVE_INFINITY;
  }
  if (target.connectionKind === 'hull-bottom-expand') return 0;
  const opposite = oppositeSocketId(target.id);
  if (opposite === source.id) return 0;
  if (target.id === source.id) return 24;
  return 7;
};

export const resolveConstructionSocket = (
  placement: Readonly<ConstructionPlacement>,
  socket: Readonly<ConstructionModuleSocket>,
): ResolvedConstructionSocket => {
  const localPosition = transformLocalDirection(
    socket.position,
    placement,
    placement.flipped,
  );
  const normal = transformLocalDirection(
    socket.normal,
    placement,
    placement.flipped,
  );
  return {
    placementId: placement.id,
    moduleId: placement.moduleId,
    socket: { ...socket },
    position: {
      x:
        placement.position.x * CONSTRUCTION_GRID_METRES +
        localPosition.x,
      y:
        placement.position.y * CONSTRUCTION_GRID_METRES +
        localPosition.y,
      z:
        placement.position.z * CONSTRUCTION_GRID_METRES +
        localPosition.z,
    },
    normal,
  };
};

export const constructionSocketOccupied = (
  blueprint: Readonly<ConstructionBlueprint>,
  placementId: string,
  socketId: string,
): boolean =>
  blueprint.placements.some((placement) => {
    if (placement.mount.kind !== 'grid' || !placement.mount.connection) {
      return false;
    }
    const connection = placement.mount.connection;
    return (
      (connection.hostPlacementId === placementId &&
        connection.hostSocketId === socketId) ||
      (placement.id === placementId &&
        connection.sourceSocketId === socketId)
    );
  });

export const createSocketSnappedPlacement = (options: {
  definition: Readonly<ConstructionModuleDefinition>;
  target: Readonly<ResolvedConstructionSocket>;
  sourceSocket: Readonly<ConstructionModuleSocket>;
  requestedYawDegrees: number;
  flipped: boolean;
  materialId: ConstructionPlacement['materialId'];
  surfaceId: ConstructionPlacement['surfaceId'];
}): ConstructionPlacement | undefined => {
  const {
    definition,
    target,
    sourceSocket,
    requestedYawDegrees,
    flipped,
    materialId,
    surfaceId,
  } = options;
  if (!constructionSocketsCompatible(target.socket, sourceSocket)) {
    return undefined;
  }

  const baseEuler = new Euler(
    0,
    MathUtils.degToRad(requestedYawDegrees),
    0,
    'XYZ',
  );
  const baseQuaternion = new Quaternion().setFromEuler(baseEuler);
  const sourceNormal = new Vector3(
    sourceSocket.normal.x,
    sourceSocket.normal.y,
    flipped ? -sourceSocket.normal.z : sourceSocket.normal.z,
  )
    .applyQuaternion(baseQuaternion)
    .normalize();
  const desiredNormal = new Vector3(
    -target.normal.x,
    -target.normal.y,
    -target.normal.z,
  ).normalize();
  if (sourceNormal.lengthSq() < 0.5 || desiredNormal.lengthSq() < 0.5) {
    return undefined;
  }
  const alignment = new Quaternion().setFromUnitVectors(
    sourceNormal,
    desiredNormal,
  );
  const finalQuaternion = alignment.multiply(baseQuaternion).normalize();
  const finalEuler = new Euler().setFromQuaternion(
    finalQuaternion,
    'XYZ',
  );
  const rotation = {
    pitchDegrees: Number(
      normalizeDegrees(MathUtils.radToDeg(finalEuler.x)).toFixed(4),
    ),
    yawDegrees: Number(
      normalizeDegrees(MathUtils.radToDeg(finalEuler.y)).toFixed(4),
    ),
    rollDegrees: Number(
      normalizeDegrees(MathUtils.radToDeg(finalEuler.z)).toFixed(4),
    ),
  };
  const sourcePositionVector = new Vector3(
    sourceSocket.position.x,
    sourceSocket.position.y,
    flipped ? -sourceSocket.position.z : sourceSocket.position.z,
  ).applyQuaternion(finalQuaternion);
  const worldPosition = {
    x: target.position.x - sourcePositionVector.x,
    y: target.position.y - sourcePositionVector.y,
    z: target.position.z - sourcePositionVector.z,
  };
  const gridPosition = {
    x: Number((worldPosition.x / CONSTRUCTION_GRID_METRES).toFixed(4)),
    y: Number((worldPosition.y / CONSTRUCTION_GRID_METRES).toFixed(4)),
    z: Number((worldPosition.z / CONSTRUCTION_GRID_METRES).toFixed(4)),
  };

  return {
    id: 'preview',
    moduleId: definition.id,
    position: gridPosition,
    yawDegrees: rotation.yawDegrees,
    pitchDegrees: rotation.pitchDegrees,
    rollDegrees: rotation.rollDegrees,
    flipped,
    materialId,
    surfaceId,
    mount: {
      kind: 'grid',
      connection: {
        hostPlacementId: target.placementId,
        hostSocketId: target.socket.id,
        sourceSocketId: sourceSocket.id,
      },
    },
  };
};
