import {
  BufferGeometry,
  Color,
  DynamicDrawUsage,
  Float32BufferAttribute,
  Group,
  Mesh,
  MeshStandardMaterial,
  Sphere,
  Uint32BufferAttribute,
  Vector3,
  type Scene,
} from 'three';
import { clamp, hash2D, smoothstep, valueNoise2D } from '../utils/math';
import { isBorealisLand } from './BorealisLand';
import {
  LAND_SNOW_TILE_SIZE,
  landSnowTileKey,
} from './LandSnowData';
import type {
  LandSnowMutationBounds,
  LandSnowSystem,
} from './LandSnowSystem';
import type {
  TerrainEditBounds,
  TerrainHeightSystem,
} from './TerrainHeightSystem';
import {
  SnowSurfaceMaterialController,
  type SnowSurfaceLighting,
} from './SnowSurfaceMaterial';
import { resolveHumanSnowContactProfile } from './PenguinSimulation';
import { resolveSnowWadeProfile } from './SnowWadeProfile';

export type LandSnowDetailQuality = 'LOW' | 'MEDIUM' | 'HIGH' | 'ULTRA';
export type LandSnowMicrodetailLevel = 'V5' | 'V6';

export const LAND_SNOW_DETAIL_QUALITY_ORDER: readonly LandSnowDetailQuality[] = [
  'LOW',
  'MEDIUM',
  'HIGH',
  'ULTRA',
];

export interface LandSnowMicroStamp {
  readonly id: number;
  readonly kind: 'FOOT' | 'WADE' | 'ANIMAL';
  readonly x: number;
  readonly z: number;
  readonly heading: number;
  readonly radiusX: number;
  readonly radiusZ: number;
  readonly depth: number;
}

export interface LandSnowV5SaveData {
  readonly version: 1 | 2;
  readonly stamps: readonly LandSnowMicroStamp[];
}

export interface LandSnowV5Stats {
  readonly quality: LandSnowDetailQuality;
  readonly activeTiles: number;
  readonly cachedTiles: number;
  readonly v5Tiles: number;
  readonly v6Tiles: number;
  readonly vertices: number;
  readonly triangles: number;
  readonly microStamps: number;
  readonly pendingTiles: number;
  readonly pendingInteractionRefreshTiles: number;
  readonly pendingBackgroundRefreshTiles: number;
  readonly lastUpdateMs: number;
  readonly maximumUpdateMs: number;
}

interface DetailTile {
  readonly key: string;
  readonly tileX: number;
  readonly tileZ: number;
  readonly level: LandSnowMicrodetailLevel;
  readonly segments: number;
  readonly spacing: number;
  readonly samples: number;
  readonly mesh: Mesh<BufferGeometry, MeshStandardMaterial>;
  /**
   * A tile that has reached the GPU at least once remains the presentation
   * owner while a replacement patch is assembled. This prevents every foot
   * contact from alternating the complete 16 m tile between V3 and V5/V6.
   */
  presentationReady: boolean;
  /** Weather and persistent heat are allowed to converge gradually. */
  dirty?: LandSnowMutationBounds;
  refresh?: DetailTileRefreshJob;
  /** Footsteps and tools pre-empt an in-progress background refresh. */
  interactionDirty?: LandSnowMutationBounds;
  interactionRefresh?: DetailTileRefreshJob;
}

interface DetailTileRefreshJob {
  readonly minColumn: number;
  readonly maxColumn: number;
  readonly minRow: number;
  readonly maxRow: number;
  stage: 'POSITIONS' | 'NORMALS';
  row: number;
}

interface RequestedTile {
  readonly key: string;
  readonly tileX: number;
  readonly tileZ: number;
  readonly level: LandSnowMicrodetailLevel;
}

interface DetailTileBuildJob {
  readonly request: RequestedTile;
  readonly segments: number;
  readonly samples: number;
  readonly spacing: number;
  readonly positions: Float32Array;
  readonly colors: Float32Array;
  readonly normals: Float32Array;
  readonly indices: Uint32Array;
  indexCount: number;
  stage: 'VERTICES' | 'INDICES' | 'NORMALS';
  row: number;
}

const QUALITY_STORAGE_KEY = 'iceway.land-snow-detail-quality';
// A two-metre bucket put hundreds of accumulated foot contacts into every
// V6 vertex query. Half-metre buckets keep the same exact stamps while a
// refresh only visits contacts that can physically touch that vertex.
const MICRO_BUCKET_METRES = 0.5;
// A ten-metre human trail fits in one detail tile without rolling its first
// contacts out while the player is already walking back over it. Exact repeat
// contacts are deduplicated below, so this does not grow on every return pass.
// A deep-snow human emits two swept boot contacts and an occasional body
// contact every ~8 cm. 384 entries discarded the first part of a straight
// 16 m crossing while it was still directly behind the actor. The spatial
// buckets keep query cost local, so retention can cover the full tile plus
// animal traffic without increasing per-vertex lookup work.
const MAXIMUM_MICRO_STAMPS_PER_TILE = 1_536;
const MAXIMUM_CACHED_V5_TILES = 24;
const MAXIMUM_CACHED_V6_TILES = 2;
// The detail owner must not change every time a character jitters across an
// exact 16 m boundary. Canonical V3 can stream independently; this only keeps
// the visible V5/V6 presentation window stable until the actor has committed
// two metres into the neighbouring tile.
const DETAIL_TILE_SWITCH_HYSTERESIS_METRES = 2;
// Fine contact stamps are a bounded reconstruction cache over persistent V3
// mass. Retaining a short travelled corridor means walking back never turns a
// detailed trail into virgin snow merely because it left the current 3x3
// window. Oldest non-visible tiles eventually collapse safely into V3.
const MAXIMUM_RETAINED_MICRO_STAMP_TILES = 24;
// Atomic does not have to mean unbounded. A merged contact patch can contain
// expensive V6 micro-stamp lookups; larger patches retain the previous GPU
// snapshot and complete over bounded slices instead of blocking a frame.
const IMMEDIATE_INTERACTION_REFRESH_SAMPLES = 2_048;
const IMMEDIATE_INTERACTION_REFRESH_TOTAL_SAMPLES = 4_096;

const readQuality = (): LandSnowDetailQuality => {
  if (typeof window === 'undefined') return 'MEDIUM';
  const stored = window.localStorage.getItem(QUALITY_STORAGE_KEY);
  return LAND_SNOW_DETAIL_QUALITY_ORDER.includes(
    stored as LandSnowDetailQuality,
  ) ? stored as LandSnowDetailQuality : 'MEDIUM';
};

const bucketKey = (x: number, z: number): string =>
  `${Math.floor(x / MICRO_BUCKET_METRES)},${Math.floor(z / MICRO_BUCKET_METRES)}`;

const mergeBounds = (
  previous: Readonly<LandSnowMutationBounds> | undefined,
  incoming: Readonly<LandSnowMutationBounds>,
): LandSnowMutationBounds => previous
  ? {
      minX: Math.min(previous.minX, incoming.minX),
      maxX: Math.max(previous.maxX, incoming.maxX),
      minZ: Math.min(previous.minZ, incoming.minZ),
      maxZ: Math.max(previous.maxZ, incoming.maxZ),
      priority:
        previous.priority === 'INTERACTION' || incoming.priority === 'INTERACTION'
          ? 'INTERACTION'
          : previous.priority ?? incoming.priority,
    }
  : { ...incoming };

/**
 * Local 12.5 cm / 6.25 cm presentation layered over the canonical 25 cm V3
 * mass field. Whole aligned V3 tiles remain simulated but are hidden only
 * after their replacement detail mesh has finished building. Sparse visual
 * residual stamps add foot-scale information without changing netcode mass.
 */
export class LandSnowV5MicrodetailSystem {
  private readonly root = new Group();
  private readonly material = new MeshStandardMaterial({
    color: new Color(0xffffff),
    vertexColors: true,
    roughness: 0.96,
    metalness: 0,
  });
  private readonly surfaceMaterialController =
    new SnowSurfaceMaterialController(this.material, 1.08);
  private readonly activeTiles = new Map<string, DetailTile>();
  private readonly cachedTiles = new Map<string, DetailTile>();
  private readonly buildQueue: RequestedTile[] = [];
  private readonly requestedKeys = new Set<string>();
  private activeBuild?: DetailTileBuildJob;
  private readonly stampsByTile = new Map<string, LandSnowMicroStamp[]>();
  private readonly stampBuckets = new Map<string, LandSnowMicroStamp[]>();
  private readonly desiredStampTileKeys = new Set<string>();
  private readonly stampTileRecency = new Map<string, true>();
  private readonly removeMutationListener: () => void;
  private readonly removeTerrainListener: () => void;
  private quality = readQuality();
  private visible = false;
  private nextStampId = 1;
  private lastFootX = Number.POSITIVE_INFINITY;
  private lastFootZ = Number.POSITIVE_INFINITY;
  private footSide: -1 | 1 = -1;
  private lastUpdateMs = 0;
  private maximumUpdateMs = 0;
  private detailAnchorTileX?: number;
  private detailAnchorTileZ?: number;

  public constructor(
    scene: Scene,
    private readonly snow: LandSnowSystem,
    private readonly terrain: TerrainHeightSystem,
    saved?: Readonly<LandSnowV5SaveData>,
  ) {
    this.root.name = 'Snow V5 local hierarchical microdetail';
    this.root.visible = false;
    scene.add(this.root);
    this.removeMutationListener = this.snow.addMutationListener((bounds) =>
      this.invalidateBounds(bounds),
    );
    this.removeTerrainListener = this.terrain.addListener((bounds) => {
      if (bounds.kind === 'HEIGHT') this.invalidateBounds(bounds);
      else this.refreshTopology(bounds);
    });
    if (saved) this.importState(saved);
  }

  public getQuality(): LandSnowDetailQuality {
    return this.quality;
  }

  public setSurfaceLighting(input: Readonly<SnowSurfaceLighting>): void {
    this.surfaceMaterialController.update(input);
  }

  public setAuthoringPresentation(active: boolean): void {
    this.surfaceMaterialController.setAuthoringMode(active);
  }

  public setQuality(quality: LandSnowDetailQuality): void {
    if (this.quality === quality) return;
    this.quality = quality;
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(QUALITY_STORAGE_KEY, quality);
    }
    this.clearMicroStamps();
    this.clearDetailTiles();
    this.root.visible = this.visible && quality !== 'LOW';
  }

  public cycleQuality(): LandSnowDetailQuality {
    const index = LAND_SNOW_DETAIL_QUALITY_ORDER.indexOf(this.quality);
    const next = LAND_SNOW_DETAIL_QUALITY_ORDER[
      (Math.max(0, index) + 1) % LAND_SNOW_DETAIL_QUALITY_ORDER.length
    ]!;
    this.setQuality(next);
    return next;
  }

  public setVisible(visible: boolean): void {
    if (this.visible === visible) return;
    this.visible = visible;
    this.root.visible = visible && this.quality !== 'LOW';
    if (!visible) {
      // V5/V6 is a transient reconstruction of canonical V3 mass. Releasing
      // it on mode changes avoids maintaining a second persistent snow world.
      this.clearMicroStamps();
      this.clearDetailTiles();
    }
  }

  public recordWalk(input: Readonly<{
    previousX: number;
    previousZ: number;
    x: number;
    z: number;
    heading: number;
    snowDepth: number;
    wadeStrength: number;
    actorKind?: 'HUMAN' | 'PENGUIN';
  }>): void {
    if (this.quality === 'LOW' || input.snowDepth <= 0.035) return;
    if (![input.x, input.z, input.heading, input.snowDepth].every(Number.isFinite)) {
      return;
    }
    if (!Number.isFinite(this.lastFootX)) {
      this.lastFootX = input.previousX;
      this.lastFootZ = input.previousZ;
    }
    const spacing = Math.hypot(input.x - this.lastFootX, input.z - this.lastFootZ);
    if (spacing > 2) {
      this.lastFootX = input.x;
      this.lastFootZ = input.z;
      return;
    }
    if (input.actorKind === 'HUMAN') {
      const contact = resolveHumanSnowContactProfile(input.snowDepth);
      if (contact.legSweepStrength > 0.04) {
        // In deep snow a boot does not teleport between discrete prints. The
        // foot and lower leg physically sweep a narrow capsule through the
        // snow. Two overlapping elongated stamps preserve those continuous
        // left/right channels while a third, pelvis-sized stamp is added only
        // when the visible snow surface actually reaches the upper thigh.
        if (spacing < 0.08) return;
        const movementHeading = Math.atan2(
          input.x - this.lastFootX,
          input.z - this.lastFootZ,
        );
        const midpointX = (this.lastFootX + input.x) * 0.5;
        const midpointZ = (this.lastFootZ + input.z) * 0.5;
        const rightX = Math.cos(movementHeading);
        const rightZ = -Math.sin(movementHeading);
        const contactStamps: LandSnowMicroStamp[] = [];
        for (const side of [-1, 1] as const) {
          contactStamps.push({
            id: this.nextStampId++,
            kind: 'FOOT',
            x: midpointX + rightX * side * contact.footSeparation * 0.5,
            z: midpointZ + rightZ * side * contact.footSeparation * 0.5,
            heading: movementHeading,
            // 11-12 cm wide and roughly 26 cm long, extended only by the
            // distance swept since the previous accepted contact sample.
            radiusX: 0.055 + contact.legSweepStrength * 0.005,
            radiusZ: spacing * 0.5 + 0.13,
            // Boots own the deepest part of a human trail. Keeping this
            // markedly deeper than the optional pelvis contact preserves two
            // readable grooves instead of one uniform centre strip.
            depth: 0.05 + contact.legSweepStrength * 0.065,
          });
        }
        if (contact.bodyWadeStrength > 0.015) {
          const pelvis = resolveSnowWadeProfile(contact.bodyWadeStrength);
          contactStamps.push({
            id: this.nextStampId++,
            kind: 'WADE',
            x: midpointX,
            z: midpointZ,
            heading: movementHeading,
            radiusX: pelvis.trailRadius,
            radiusZ: spacing * 0.5 + pelvis.trailRadius * 0.86,
            // Hip contact lightly tamps the ridge between the legs. It must
            // never become deeper than the boot channels surrounding it.
            depth: 0.012 + contact.bodyWadeStrength * 0.022,
          });
        }
        // Both boots and the optional pelvis trough describe one physical
        // contact. Publish one combined dirty region instead of waking the
        // fine mesh three times in the same simulation step.
        this.addContactStampBatch(contactStamps);
        this.lastFootX = input.x;
        this.lastFootZ = input.z;
        return;
      }
      // Below lower-leg depth, retain readable alternating boot prints.
      if (spacing < 0.28) return;
      const rightX = Math.cos(input.heading);
      const rightZ = -Math.sin(input.heading);
      const side = this.footSide * contact.footSeparation * 0.5;
      this.addStamp({
        id: this.nextStampId++,
        kind: 'FOOT',
        x: input.x + rightX * side,
        z: input.z + rightZ * side,
        heading: input.heading,
        radiusX: 0.055,
        radiusZ: 0.135,
        depth: 0.024,
      });
      this.footSide = this.footSide === -1 ? 1 : -1;
      this.lastFootX = input.x;
      this.lastFootZ = input.z;
      return;
    }
    if (spacing < (input.wadeStrength > 0.2 ? 0.24 : 0.31)) return;
    const rightX = Math.cos(input.heading);
    const rightZ = -Math.sin(input.heading);
    const bodyWading = clamp(input.wadeStrength, 0, 1);
    const deep = smoothstep(0.48, 1.05, input.snowDepth);
    const side = this.footSide * (0.095 + deep * 0.0275);
    // The fine field owns a real boot silhouette: 11 cm wide in ordinary
    // snow, growing only to 16 cm when the leg has to force deep snow aside.
    const footStamp: LandSnowMicroStamp = {
      id: this.nextStampId++,
      kind: 'FOOT',
      x: input.x + rightX * side,
      z: input.z + rightZ * side,
      heading: input.heading,
      radiusX: 0.055 + deep * 0.025,
      radiusZ: 0.135 + deep * 0.04,
      depth: 0.02 + deep * 0.036,
    };
    this.footSide = this.footSide === -1 ? 1 : -1;
    this.lastFootX = input.x;
    this.lastFootZ = input.z;
    this.addStamp(footStamp);
    if (bodyWading > 0.035) {
      // Hip-deep snow additionally touches the legs/body. This centred trough
      // grows gradually; it never replaces the alternating feet.
      this.addStamp({
        id: this.nextStampId++,
        kind: 'WADE',
        x: input.x,
        z: input.z,
        heading: input.heading,
        radiusX: 0.1 + bodyWading * 0.18,
        radiusZ: 0.145 + bodyWading * 0.19,
        depth: 0.012 + bodyWading * 0.052,
      });
    }
  }

  /**
   * Adds a paired paw/hoof impression to the same sparse microdetail field as
   * player footprints. V3 receives the durable compression separately; this
   * method only restores the small readable shape when a fine tile is near.
   */
  public recordAnimalTrack(input: Readonly<{
    x: number;
    z: number;
    heading: number;
    scale: number;
    snowDepth: number;
    species?: string;
  }>): void {
    if (this.quality === 'LOW' || input.snowDepth <= 0.028) return;
    if (![input.x, input.z, input.heading, input.scale].every(Number.isFinite)) {
      return;
    }
    const scale = clamp(input.scale, 0.07, 0.28);
    const dimensions = (() => {
      switch (input.species) {
        case 'RABBIT':
          return { halfSeparation: 0.042, radiusX: 0.026, radiusZ: 0.052 };
        case 'DEER':
          return { halfSeparation: 0.052, radiusX: 0.035, radiusZ: 0.066 };
        case 'MOOSE':
          return { halfSeparation: 0.072, radiusX: 0.052, radiusZ: 0.086 };
        case 'BEAR':
        case 'POLAR_BEAR':
          return { halfSeparation: 0.09, radiusX: 0.078, radiusZ: 0.105 };
        case 'WOLF':
          return { halfSeparation: 0.057, radiusX: 0.046, radiusZ: 0.07 };
        case 'FOX':
          return { halfSeparation: 0.048, radiusX: 0.038, radiusZ: 0.061 };
        default:
          return {
            halfSeparation: scale * 0.32,
            radiusX: scale * 0.3,
            radiusZ: scale * 0.46,
          };
      }
    })();
    const rightX = Math.cos(input.heading);
    const rightZ = -Math.sin(input.heading);
    for (const side of [-1, 1] as const) {
      this.addStamp({
        id: this.nextStampId++,
        kind: 'ANIMAL',
        x: input.x + rightX * side * dimensions.halfSeparation,
        z: input.z + rightZ * side * dimensions.halfSeparation,
        heading: input.heading,
        radiusX: dimensions.radiusX,
        radiusZ: dimensions.radiusZ,
        depth: clamp(
          0.012 + dimensions.radiusZ * 0.19 + input.snowDepth * 0.013,
          0.016,
          0.047,
        ),
      });
    }
  }

  public update(
    focus: Readonly<{ x: number; z: number }>,
  ): void {
    const startedAt = performance.now();
    if (!this.visible || this.quality === 'LOW') {
      if (this.activeTiles.size > 0) this.clearDetailTiles();
      this.lastUpdateMs = performance.now() - startedAt;
      return;
    }
    const desired = this.desiredTiles(focus.x, focus.z);
    const desiredByKey = new Map(desired.map((tile) => [tile.key, tile]));
    const discardedMicrodetail = this.reconcileMicroStampTiles(
      new Set(desiredByKey.keys()),
    );
    for (const [key, tile] of [...this.activeTiles]) {
      const request = desiredByKey.get(key);
      // Keep the already-present level as a presentation fallback while an
      // Ultra centre changes from V5 to V6 (or back again). Replacing it with
      // canonical V3 for the several time-sliced build frames made the snow
      // visibly pop every time the actor crossed a tile boundary.
      if (request) continue;
      this.activeTiles.delete(key);
      if (!discardedMicrodetail.has(key)) this.cacheTile(tile);
      else this.disposeTile(tile);
    }
    for (const key of discardedMicrodetail) {
      for (const [cachedKey, cached] of [...this.cachedTiles]) {
        if (cached.key !== key) continue;
        this.cachedTiles.delete(cachedKey);
        this.disposeTile(cached);
      }
    }
    const hasInteractionWork = [...this.activeTiles.values()].some((tile) =>
      Boolean(tile.interactionDirty || tile.interactionRefresh)
    );
    if (this.activeBuild && !hasInteractionWork) {
      const activeRequest = this.activeBuild.request;
      const desiredRequest = desiredByKey.get(activeRequest.key);
      if (desiredRequest?.level !== activeRequest.level) {
        this.activeBuild = undefined;
      }
    }
    this.buildQueue.splice(
      0,
      this.buildQueue.length,
      ...this.buildQueue.filter((request) => {
        const desiredRequest = desiredByKey.get(request.key);
        return desiredRequest?.level === request.level &&
          this.activeTiles.get(request.key)?.level !== request.level;
      }),
    );
    this.requestedKeys.clear();
    // A player contact must win the frame over an unrelated fine-tile build.
    // Continuing the streamer first could leave a footprint visually one or
    // two strides behind a running character even though canonical V3 snow
    // had already changed in the same fixed step.
    if (this.activeBuild && !hasInteractionWork) {
      this.requestedKeys.add(this.activeBuild.request.key);
    }
    for (const request of this.buildQueue) this.requestedKeys.add(request.key);
    for (const request of desired) {
      const cachedKey = this.detailCacheKey(request.key, request.level);
      const cached = this.cachedTiles.get(cachedKey);
      const fallback = this.activeTiles.get(request.key);
      // Never replace a complete visible fallback with a stale cached mesh.
      // Doing so exposed V3 for several refresh frames and made a footprint
      // disappear, then teleport back. Keep the fallback until a newly built
      // requested level is ready for one atomic ownership swap.
      if (cached && !cached.presentationReady && fallback?.presentationReady) {
        this.cachedTiles.delete(cachedKey);
        this.disposeTile(cached);
      } else if (cached) {
        this.cachedTiles.delete(cachedKey);
        if (fallback && fallback !== cached) this.cacheTile(fallback);
        this.activeTiles.set(request.key, cached);
        this.root.add(cached.mesh);
        for (let index = this.buildQueue.length - 1; index >= 0; index -= 1) {
          if (this.buildQueue[index]?.key === request.key) {
            this.buildQueue.splice(index, 1);
          }
        }
        if (this.activeBuild?.request.key === request.key) {
          this.activeBuild = undefined;
        }
        this.requestedKeys.delete(request.key);
        continue;
      }
      if (
        this.activeTiles.get(request.key)?.level === request.level ||
        this.requestedKeys.has(request.key)
      ) {
        continue;
      }
      // Ultra's centre V6 tile is built first; remaining neighbours stream
      // through the same bounded frame-time slices.
      if (request.level === 'V6') this.buildQueue.unshift(request);
      else this.buildQueue.push(request);
      this.requestedKeys.add(request.key);
    }
    if (!this.activeBuild) {
      const request = this.buildQueue.shift();
      if (request) this.activeBuild = this.createBuildJob(request);
    }
    if (this.activeBuild) {
      // Large V5/V6 meshes are intentionally spread across frames. V3 stays
      // visible until the replacement tile is complete, so streaming cannot
      // create a hole or a 100 ms synchronous generation hitch.
      const completed = this.advanceBuildJob(
        this.activeBuild,
        performance.now() + 1.8,
      );
      if (completed) {
        const request = this.activeBuild.request;
        this.requestedKeys.delete(request.key);
        this.activeBuild = undefined;
        const tile = completed;
        const fallback = this.activeTiles.get(request.key);
        if (fallback && fallback !== tile) this.cacheTile(fallback);
        this.activeTiles.set(request.key, tile);
        this.root.add(tile.mesh);
      }
    }
    // Fine-mesh mutations are time sliced too. Full-tile weather updates can
    // otherwise be more expensive than creating an entire V5 tile.
    const refreshDeadline = performance.now() +
      (hasInteractionWork ? 2.35 : 1.4);
    const refreshTiles = [...this.activeTiles.values()].sort((left, right) => {
      const leftX = (left.tileX + 0.5) * LAND_SNOW_TILE_SIZE - focus.x;
      const leftZ = (left.tileZ + 0.5) * LAND_SNOW_TILE_SIZE - focus.z;
      const rightX = (right.tileX + 0.5) * LAND_SNOW_TILE_SIZE - focus.x;
      const rightZ = (right.tileZ + 0.5) * LAND_SNOW_TILE_SIZE - focus.z;
      const leftUrgent = left.interactionDirty || left.interactionRefresh ? 1 : 0;
      const rightUrgent = right.interactionDirty || right.interactionRefresh ? 1 : 0;
      return rightUrgent - leftUrgent ||
        leftX * leftX + leftZ * leftZ -
          (rightX * rightX + rightZ * rightZ);
    });
    // Publish all small pieces of one contact before spending the remainder
    // of the budget on any old broad job. Otherwise the first side of a seam
    // could consume the deadline and its duplicated neighbour arrived one
    // render frame later.
    let immediateInteractionSamples = 0;
    for (const tile of refreshTiles) {
      if (tile.interactionDirty) {
        const immediate = this.createRefreshJob(tile, tile.interactionDirty);
        const sampleCount = this.refreshJobSampleCount(immediate);
        if (sampleCount <= IMMEDIATE_INTERACTION_REFRESH_SAMPLES &&
          immediateInteractionSamples + sampleCount <=
            IMMEDIATE_INTERACTION_REFRESH_TOTAL_SAMPLES) {
          // The newest contact is the visible truth even while an older broad
          // weather/tool patch is still converging. Updating this small patch
          // now prevents footprints from appearing only after the actor turns
          // around, without restarting or expanding the in-flight job.
          this.advanceRefreshJob(tile, immediate, Number.POSITIVE_INFINITY);
          tile.interactionDirty = undefined;
          immediateInteractionSamples += sampleCount;
        } else if (!tile.interactionRefresh) {
          tile.interactionRefresh = immediate;
          tile.interactionDirty = undefined;
        }
      }
    }
    for (const tile of refreshTiles) {
      if (tile.interactionRefresh) {
        if (this.advanceRefreshJob(
          tile,
          tile.interactionRefresh,
          refreshDeadline,
        )) {
          tile.interactionRefresh = undefined;
        }
        if (performance.now() >= refreshDeadline) break;
      }
      if (!tile.refresh && tile.dirty) {
        tile.refresh = this.createRefreshJob(tile, tile.dirty);
        tile.dirty = undefined;
      }
      if (!tile.refresh) continue;
      if (this.advanceRefreshJob(tile, tile.refresh, refreshDeadline)) {
        tile.refresh = undefined;
      }
      if (performance.now() >= refreshDeadline) break;
    }
    this.syncDetailCoverage();
    this.lastUpdateMs = performance.now() - startedAt;
    this.maximumUpdateMs = Math.max(this.maximumUpdateMs, this.lastUpdateMs);
  }

  public exportState(): LandSnowV5SaveData {
    return {
      version: 2,
      // The durable footprint/trough is already recorded into canonical V3.
      // Exact fine stamps are camera-local cache data and must not inflate or
      // compete with the authoritative save.
      stamps: [],
    };
  }

  public importState(input: unknown): boolean {
    if (!input || typeof input !== 'object') return false;
    const candidate = input as Partial<LandSnowV5SaveData>;
    if (
      (candidate.version !== 1 && candidate.version !== 2) ||
      !Array.isArray(candidate.stamps)
    ) return false;
    // Version 1 stored exact camera-local stamps. V3 already contains their
    // durable mass change, so migration intentionally drops those residuals.
    this.clearMicroStamps();
    return true;
  }

  public getStats(): LandSnowV5Stats {
    let vertices = 0;
    let triangles = 0;
    let v5Tiles = 0;
    let v6Tiles = 0;
    let pendingInteractionRefreshTiles = 0;
    let pendingBackgroundRefreshTiles = 0;
    for (const tile of this.activeTiles.values()) {
      vertices += tile.samples * tile.samples;
      triangles += tile.segments * tile.segments * 2;
      if (tile.level === 'V6') v6Tiles += 1;
      else v5Tiles += 1;
      if (tile.interactionDirty || tile.interactionRefresh) {
        pendingInteractionRefreshTiles += 1;
      }
      if (tile.dirty || tile.refresh) pendingBackgroundRefreshTiles += 1;
    }
    return {
      quality: this.quality,
      activeTiles: this.activeTiles.size,
      cachedTiles: this.cachedTiles.size,
      v5Tiles,
      v6Tiles,
      vertices,
      triangles,
      microStamps: [...this.stampsByTile.values()].reduce(
        (total, stamps) => total + stamps.length,
        0,
      ),
      pendingTiles: this.buildQueue.length + (this.activeBuild ? 1 : 0),
      pendingInteractionRefreshTiles,
      pendingBackgroundRefreshTiles,
      lastUpdateMs: this.lastUpdateMs,
      maximumUpdateMs: this.maximumUpdateMs,
    };
  }

  public dispose(): void {
    this.removeMutationListener();
    this.removeTerrainListener();
    this.clearDetailTiles();
    this.material.dispose();
    this.root.removeFromParent();
  }

  private desiredTiles(x: number, z: number): RequestedTile[] {
    const requests: RequestedTile[] = [];
    const anchor = this.resolveDetailAnchor(x, z);
    if (this.quality === 'MEDIUM') {
      // A centred 3x3 guard band remains larger than the maximum normal
      // character-camera view. The old asymmetric 2x2 window could expose its
      // edge when the camera orbited away from the movement direction.
      const centerTileX = anchor.tileX;
      const centerTileZ = anchor.tileZ;
      for (let dz = -1; dz <= 1; dz += 1) {
        for (let dx = -1; dx <= 1; dx += 1) {
          const tileX = centerTileX + dx;
          const tileZ = centerTileZ + dz;
          requests.push({
            key: landSnowTileKey(tileX, tileZ), tileX, tileZ, level: 'V5',
          });
        }
      }
      return this.sortNearestFirst(requests, x, z);
    }
    const centerTileX = anchor.tileX;
    const centerTileZ = anchor.tileZ;
    for (let dz = -1; dz <= 1; dz += 1) {
      for (let dx = -1; dx <= 1; dx += 1) {
        const tileX = centerTileX + dx;
        const tileZ = centerTileZ + dz;
        requests.push({
          key: landSnowTileKey(tileX, tileZ),
          tileX,
          tileZ,
          level: this.quality === 'ULTRA' && dx === 0 && dz === 0
            ? 'V6'
            : 'V5',
        });
      }
    }
    return this.sortNearestFirst(requests, x, z);
  }

  private resolveDetailAnchor(
    x: number,
    z: number,
  ): Readonly<{ tileX: number; tileZ: number }> {
    const rawX = Math.floor(x / LAND_SNOW_TILE_SIZE);
    const rawZ = Math.floor(z / LAND_SNOW_TILE_SIZE);
    if (
      this.detailAnchorTileX === undefined ||
      this.detailAnchorTileZ === undefined
    ) {
      this.detailAnchorTileX = rawX;
      this.detailAnchorTileZ = rawZ;
      return { tileX: rawX, tileZ: rawZ };
    }
    const resolveAxis = (
      anchor: number,
      raw: number,
      position: number,
    ): number => {
      // Teleports and quick travel should converge immediately instead of
      // stepping the detail ring through every intermediate tile.
      if (Math.abs(raw - anchor) > 1) return raw;
      if (
        raw > anchor &&
        position >= (anchor + 1) * LAND_SNOW_TILE_SIZE +
          DETAIL_TILE_SWITCH_HYSTERESIS_METRES
      ) return raw;
      if (
        raw < anchor &&
        position <= anchor * LAND_SNOW_TILE_SIZE -
          DETAIL_TILE_SWITCH_HYSTERESIS_METRES
      ) return raw;
      return anchor;
    };
    this.detailAnchorTileX = resolveAxis(this.detailAnchorTileX, rawX, x);
    this.detailAnchorTileZ = resolveAxis(this.detailAnchorTileZ, rawZ, z);
    return {
      tileX: this.detailAnchorTileX,
      tileZ: this.detailAnchorTileZ,
    };
  }

  private sortNearestFirst(
    requests: RequestedTile[],
    x: number,
    z: number,
  ): RequestedTile[] {
    return requests.sort((left, right) => {
      if (left.level === 'V6' && right.level !== 'V6') return -1;
      if (right.level === 'V6' && left.level !== 'V6') return 1;
      const leftX = (left.tileX + 0.5) * LAND_SNOW_TILE_SIZE - x;
      const leftZ = (left.tileZ + 0.5) * LAND_SNOW_TILE_SIZE - z;
      const rightX = (right.tileX + 0.5) * LAND_SNOW_TILE_SIZE - x;
      const rightZ = (right.tileZ + 0.5) * LAND_SNOW_TILE_SIZE - z;
      return leftX * leftX + leftZ * leftZ -
        (rightX * rightX + rightZ * rightZ);
    });
  }

  private createBuildJob(
    request: Readonly<RequestedTile>,
  ): DetailTileBuildJob {
    const segments = request.level === 'V6' ? 256 : 128;
    const samples = segments + 1;
    const spacing = LAND_SNOW_TILE_SIZE / segments;
    return {
      request: { ...request },
      segments,
      samples,
      spacing,
      positions: new Float32Array(samples * samples * 3),
      colors: new Float32Array(samples * samples * 3),
      normals: new Float32Array(samples * samples * 3),
      indices: new Uint32Array(segments * segments * 6),
      indexCount: 0,
      stage: 'VERTICES',
      row: 0,
    };
  }

  private advanceBuildJob(
    job: DetailTileBuildJob,
    deadline: number,
  ): DetailTile | undefined {
    while (performance.now() < deadline) {
      if (job.stage === 'VERTICES') {
        const row = job.row;
        for (let column = 0; column < job.samples; column += 1) {
          this.writeVertex(
            job.request.tileX,
            job.request.tileZ,
            job.segments,
            job.spacing,
            job.positions,
            job.colors,
            column,
            row,
          );
        }
        job.row += 1;
        if (job.row >= job.samples) {
          job.stage = 'INDICES';
          job.row = 0;
        }
        continue;
      }
      if (job.stage === 'INDICES') {
        const row = job.row;
        for (let column = 0; column < job.segments; column += 1) {
          const centerX = job.request.tileX * LAND_SNOW_TILE_SIZE +
            (column + 0.5) * job.spacing;
          const centerZ = job.request.tileZ * LAND_SNOW_TILE_SIZE +
            (row + 0.5) * job.spacing;
          if (
            !isBorealisLand(centerX, centerZ) ||
            this.snow.isSnowSurfaceExcludedAt(centerX, centerZ) ||
            this.terrain.isNearCliff(
              centerX,
              centerZ,
              Math.max(0.12, job.spacing),
            )
          ) continue;
          const a = row * job.samples + column;
          const b = a + 1;
          const c = a + job.samples;
          const d = c + 1;
          const offset = job.indexCount;
          job.indices[offset] = a;
          job.indices[offset + 1] = c;
          job.indices[offset + 2] = b;
          job.indices[offset + 3] = b;
          job.indices[offset + 4] = c;
          job.indices[offset + 5] = d;
          job.indexCount += 6;
        }
        job.row += 1;
        if (job.row >= job.segments) {
          job.stage = 'NORMALS';
          job.row = 0;
        }
        continue;
      }
      this.writeBuildNormalRow(job, job.row);
      job.row += 1;
      if (job.row >= job.samples) return this.finishBuildJob(job);
    }
    return undefined;
  }

  private finishBuildJob(job: DetailTileBuildJob): DetailTile {
    const {
      request,
      segments,
      samples,
      spacing,
      positions,
      colors,
      normals,
      indices,
    } = job;
    const geometry = new BufferGeometry();
    geometry.setAttribute(
      'position',
      new Float32BufferAttribute(positions, 3).setUsage(DynamicDrawUsage),
    );
    geometry.setAttribute(
      'color',
      new Float32BufferAttribute(colors, 3).setUsage(DynamicDrawUsage),
    );
    geometry.setAttribute(
      'normal',
      new Float32BufferAttribute(normals, 3).setUsage(DynamicDrawUsage),
    );
    geometry.setIndex(new Uint32BufferAttribute(
      indices.subarray(0, job.indexCount),
      1,
    ));
    geometry.boundingSphere = new Sphere(
      new Vector3(
        (request.tileX + 0.5) * LAND_SNOW_TILE_SIZE,
        this.snow.sampleSurfaceHeight(
          (request.tileX + 0.5) * LAND_SNOW_TILE_SIZE,
          (request.tileZ + 0.5) * LAND_SNOW_TILE_SIZE,
        ),
        (request.tileZ + 0.5) * LAND_SNOW_TILE_SIZE,
      ),
      LAND_SNOW_TILE_SIZE * 1.35,
    );
    const mesh = new Mesh(geometry, this.material);
    mesh.name = `Snow ${request.level} detail tile ${request.key}`;
    mesh.receiveShadow = true;
    mesh.castShadow = false;
    mesh.frustumCulled = true;
    return {
      ...request,
      segments,
      spacing,
      samples,
      mesh,
      presentationReady: true,
    };
  }

  private writeBuildNormalRow(
    job: Readonly<DetailTileBuildJob>,
    row: number,
  ): void {
    const height = (column: number, sampleRow: number): number =>
      job.positions[(sampleRow * job.samples + column) * 3 + 1] ?? 0;
    for (let column = 0; column < job.samples; column += 1) {
      if (
        column === 0 || column === job.segments ||
        row === 0 || row === job.segments
      ) {
        const x = job.request.tileX * LAND_SNOW_TILE_SIZE +
          column * job.spacing;
        const z = job.request.tileZ * LAND_SNOW_TILE_SIZE + row * job.spacing;
        this.writeWorldSnowNormal(
          x,
          z,
          job.normals,
          row * job.samples + column,
        );
        continue;
      }
      // V6 doubles geometry density for silhouettes and contacts, not for a
      // visibly faceted lighting lattice. Its derivative therefore spans the
      // same physical 25 cm window as V5 instead of exposing every 6.25 cm
      // vertex at a grazing camera angle.
      const normalStride = job.request.level === 'V6' ? 2 : 1;
      const left = Math.max(0, column - normalStride);
      const right = Math.min(job.segments, column + normalStride);
      const near = Math.max(0, row - normalStride);
      const far = Math.min(job.segments, row + normalStride);
      const slopeX = (height(right, row) - height(left, row)) /
        Math.max(0.001, (right - left) * job.spacing);
      const slopeZ = (height(column, far) - height(column, near)) /
        Math.max(0.001, (far - near) * job.spacing);
      const length = Math.max(0.001, Math.hypot(slopeX, 1, slopeZ));
      const index = (row * job.samples + column) * 3;
      job.normals[index] = -slopeX / length;
      job.normals[index + 1] = 1 / length;
      job.normals[index + 2] = -slopeZ / length;
    }
  }

  private writeVertex(
    tileX: number,
    tileZ: number,
    segments: number,
    spacing: number,
    positions: Float32Array,
    colors: Float32Array,
    column: number,
    row: number,
  ): void {
    const x = tileX * LAND_SNOW_TILE_SIZE + column * spacing;
    const z = tileZ * LAND_SNOW_TILE_SIZE + row * spacing;
    const depth = this.snow.sampleDepth(x, z);
    const edgeDistance = Math.min(
      column * spacing,
      row * spacing,
      (segments - column) * spacing,
      (segments - row) * spacing,
    );
    const edgeFade = smoothstep(0, 0.7, edgeDistance);
    const snowPresence = smoothstep(0.025, 0.17, depth);
    // Geometry may only carry wavelengths that this detail lattice can
    // sample cleanly. High-frequency vertex noise aliases into a square quilt
    // at glancing angles, so actual powder grain belongs to the per-fragment
    // snow material and these two very low-amplitude fields only break broad
    // flatness.
    const powderA = valueNoise2D(
      x * 0.83 + z * 0.24,
      z * 0.83 - x * 0.24,
      18317,
    );
    const powderB = valueNoise2D(
      x * 1.77 - z * 0.51,
      z * 1.77 + x * 0.51,
      28771,
    );
    const proceduralAmplitude = spacing < 0.08 ? 0.00055 : 0.0024;
    const procedural = (
      (powderA - 0.5) * 0.68 + (powderB - 0.5) * 0.32
    ) * proceduralAmplitude * snowPresence;
    // Contact masks are world-space data, not tile-local decoration. Fading
    // them to zero at every 16 m edge created a clean gap in a footprint until
    // the coarser canonical mesh caught up. Both owners now use the same V5
    // sampling kernel exactly at the shared edge and blend toward the finer
    // V6 kernel only inside the tile, keeping both height copies bit-identical
    // without sacrificing Ultra detail away from the seam.
    const sharedResidual = this.microHeightAt(x, z, 0.125);
    const preciseResidual = spacing < 0.08
      ? this.microHeightAt(x, z, spacing)
      : sharedResidual;
    const residualPrecision = smoothstep(0, 0.32, edgeDistance);
    const residual = (
      sharedResidual + (preciseResidual - sharedResidual) * residualPrecision
    ) * snowPresence;
    const index = (row * (segments + 1) + column) * 3;
    positions[index] = x;
    positions[index + 1] = this.presentationSurfaceHeightAt(
      x,
      z,
      spacing,
      edgeFade,
    ) +
      procedural * edgeFade + residual;
    positions[index + 2] = z;
    const effectiveSnow = smoothstep(0.018, 0.15, depth + residual);
    // Do not encode powder colour per vertex: interpolation makes the detail
    // topology visible. Fine colour and sparkle are evaluated continuously in
    // SnowSurfaceMaterial instead.
    colors[index] = 0.24 + effectiveSnow * 0.69;
    colors[index + 1] = 0.29 + effectiveSnow * 0.68;
    colors[index + 2] = 0.28 + effectiveSnow * 0.69;
  }

  private createRefreshJob(
    tile: DetailTile,
    bounds: Readonly<LandSnowMutationBounds>,
  ): DetailTileRefreshJob {
    const originX = tile.tileX * LAND_SNOW_TILE_SIZE;
    const originZ = tile.tileZ * LAND_SNOW_TILE_SIZE;
    const minColumn = clamp(
      Math.floor((bounds.minX - originX) / tile.spacing) - 2,
      0,
      tile.segments,
    );
    const maxColumn = clamp(
      Math.ceil((bounds.maxX - originX) / tile.spacing) + 2,
      0,
      tile.segments,
    );
    const minRow = clamp(
      Math.floor((bounds.minZ - originZ) / tile.spacing) - 2,
      0,
      tile.segments,
    );
    const maxRow = clamp(
      Math.ceil((bounds.maxZ - originZ) / tile.spacing) + 2,
      0,
      tile.segments,
    );
    return {
      minColumn,
      maxColumn,
      minRow,
      maxRow,
      stage: 'POSITIONS',
      row: minRow,
    };
  }

  private refreshJobSampleCount(job: Readonly<DetailTileRefreshJob>): number {
    const columns = Math.max(0, job.maxColumn - job.minColumn + 1);
    const rows = Math.max(0, job.maxRow - job.minRow + 1);
    return columns * rows;
  }

  private advanceRefreshJob(
    tile: DetailTile,
    job: DetailTileRefreshJob,
    deadline: number,
  ): boolean {
    const positions = tile.mesh.geometry.getAttribute('position') as Float32BufferAttribute;
    const colors = tile.mesh.geometry.getAttribute('color') as Float32BufferAttribute;
    while (performance.now() < deadline) {
      if (job.stage === 'POSITIONS') {
        const row = job.row;
        for (let column = job.minColumn; column <= job.maxColumn; column += 1) {
          this.writeVertex(
            tile.tileX,
            tile.tileZ,
            tile.segments,
            tile.spacing,
            positions.array as Float32Array,
            colors.array as Float32Array,
            column,
            row,
          );
        }
        job.row += 1;
        if (job.row > job.maxRow) {
          job.stage = 'NORMALS';
          job.row = Math.max(0, job.minRow - 1);
        }
        continue;
      }
      const normalStride = tile.level === 'V6' ? 2 : 1;
      const normalMinColumn = Math.max(0, job.minColumn - normalStride);
      const normalMaxColumn = Math.min(
        tile.segments,
        job.maxColumn + normalStride,
      );
      const normalMaxRow = Math.min(tile.segments, job.maxRow + normalStride);
      const row = job.row;
      this.updateNormals(
        tile,
        normalMinColumn,
        row,
        normalMaxColumn,
        row,
      );
      job.row += 1;
      if (job.row > normalMaxRow) {
        // Publish positions, colour and normals together. Uploading each row
        // separately let the camera see a refresh scanline crawl through a
        // footprint; hiding the tile instead made the whole trail blink back
        // to V3 on every step.
        this.commitRefreshJob(tile, job);
        return true;
      }
    }
    return false;
  }

  private commitRefreshJob(
    tile: DetailTile,
    job: Readonly<DetailTileRefreshJob>,
  ): void {
    const positions = tile.mesh.geometry.getAttribute(
      'position',
    ) as Float32BufferAttribute;
    const colors = tile.mesh.geometry.getAttribute(
      'color',
    ) as Float32BufferAttribute;
    const normals = tile.mesh.geometry.getAttribute(
      'normal',
    ) as Float32BufferAttribute;
    const positionStart = (
      job.minRow * tile.samples + job.minColumn
    ) * 3;
    const positionEnd = (
      job.maxRow * tile.samples + job.maxColumn + 1
    ) * 3;
    const normalStride = tile.level === 'V6' ? 2 : 1;
    const normalMinColumn = Math.max(0, job.minColumn - normalStride);
    const normalMaxColumn = Math.min(
      tile.segments,
      job.maxColumn + normalStride,
    );
    const normalMinRow = Math.max(0, job.minRow - 1);
    const normalMaxRow = Math.min(tile.segments, job.maxRow + normalStride);
    const normalStart = (
      normalMinRow * tile.samples + normalMinColumn
    ) * 3;
    const normalEnd = (
      normalMaxRow * tile.samples + normalMaxColumn + 1
    ) * 3;
    for (const attribute of [positions, colors]) {
      attribute.clearUpdateRanges();
      attribute.addUpdateRange(positionStart, positionEnd - positionStart);
      attribute.needsUpdate = true;
    }
    normals.clearUpdateRanges();
    normals.addUpdateRange(normalStart, normalEnd - normalStart);
    normals.needsUpdate = true;
    tile.presentationReady = true;
  }

  private updateNormals(
    tile: DetailTile,
    minColumn: number,
    minRow: number,
    maxColumn: number,
    maxRow: number,
  ): void {
    const positions = tile.mesh.geometry.getAttribute('position') as Float32BufferAttribute;
    const normals = tile.mesh.geometry.getAttribute('normal') as Float32BufferAttribute;
    const values = positions.array as Float32Array;
    const output = normals.array as Float32Array;
    const height = (column: number, row: number): number =>
      values[(row * tile.samples + column) * 3 + 1] ?? 0;
    for (let row = minRow; row <= maxRow; row += 1) {
      for (let column = minColumn; column <= maxColumn; column += 1) {
        if (
          column === 0 || column === tile.segments ||
          row === 0 || row === tile.segments
        ) {
          const x = tile.tileX * LAND_SNOW_TILE_SIZE + column * tile.spacing;
          const z = tile.tileZ * LAND_SNOW_TILE_SIZE + row * tile.spacing;
          this.writeWorldSnowNormal(
            x,
            z,
            output,
            row * tile.samples + column,
          );
          continue;
        }
        const normalStride = tile.level === 'V6' ? 2 : 1;
        const left = Math.max(0, column - normalStride);
        const right = Math.min(tile.segments, column + normalStride);
        const near = Math.max(0, row - normalStride);
        const far = Math.min(tile.segments, row + normalStride);
        const dx = (right - left) * tile.spacing;
        const dz = (far - near) * tile.spacing;
        const slopeX = (height(right, row) - height(left, row)) / Math.max(0.001, dx);
        const slopeZ = (height(column, far) - height(column, near)) / Math.max(0.001, dz);
        const length = Math.max(0.001, Math.hypot(slopeX, 1, slopeZ));
        const index = (row * tile.samples + column) * 3;
        output[index] = -slopeX / length;
        output[index + 1] = 1 / length;
        output[index + 2] = -slopeZ / length;
      }
    }
  }

  private writeWorldSnowNormal(
    x: number,
    z: number,
    output: Float32Array,
    sample: number,
  ): void {
    // Shared vertices use a world-space derivative containing the same exact
    // contact mask on both sides of a tile edge. This welds not only geometry
    // but also the lighting of a track which crosses that edge.
    const step = 0.125;
    const sharedHeight = (sampleX: number, sampleZ: number): number => {
      const depth = this.snow.sampleDepth(sampleX, sampleZ);
      return this.snow.sampleSurfaceHeight(sampleX, sampleZ) +
        this.microHeightAt(sampleX, sampleZ, 0.125) *
          smoothstep(0.025, 0.17, depth);
    };
    const slopeX = (
      sharedHeight(x + step, z) - sharedHeight(x - step, z)
    ) / (step * 2);
    const slopeZ = (
      sharedHeight(x, z + step) - sharedHeight(x, z - step)
    ) / (step * 2);
    const length = Math.max(0.0001, Math.hypot(slopeX, 1, slopeZ));
    const index = sample * 3;
    output[index] = -slopeX / length;
    output[index + 1] = 1 / length;
    output[index + 2] = -slopeZ / length;
  }

  private invalidateBounds(bounds: Readonly<LandSnowMutationBounds>): void {
    const queueRefresh = (tile: DetailTile): void => {
      const minX = tile.tileX * LAND_SNOW_TILE_SIZE;
      const minZ = tile.tileZ * LAND_SNOW_TILE_SIZE;
      if (
        minX + LAND_SNOW_TILE_SIZE < bounds.minX || minX > bounds.maxX ||
        minZ + LAND_SNOW_TILE_SIZE < bounds.minZ || minZ > bounds.maxZ
      ) return;
      if (bounds.priority === 'BACKGROUND') {
        tile.dirty = mergeBounds(tile.dirty, bounds);
      } else {
        let interactionBounds: LandSnowMutationBounds = {
          ...bounds,
          priority: 'INTERACTION',
        };
        // Never restart a patch that is already being assembled. At running
        // speed that turned a small boot update into a continually growing
        // path and repeated its first rows every frame. Finish the current
        // atomic snapshot, then consume one merged follow-up patch.
        if (tile.interactionRefresh) {
          tile.interactionDirty = mergeBounds(
            tile.interactionDirty,
            interactionBounds,
          );
          return;
        }
        tile.interactionDirty = mergeBounds(
          tile.interactionDirty,
          interactionBounds,
        );
      }
    };
    for (const tile of this.activeTiles.values()) queueRefresh(tile);
    for (const tile of this.cachedTiles.values()) {
      const beforeDirty = tile.dirty;
      const beforeInteractionDirty = tile.interactionDirty;
      queueRefresh(tile);
      if (
        tile.dirty !== beforeDirty ||
        tile.interactionDirty !== beforeInteractionDirty
      ) {
        // A cached mesh has no current presentation contract. When it returns,
        // canonical V3 remains visible until the queued patch is complete;
        // then ownership swaps only once.
        tile.presentationReady = false;
      }
    }
    // Active tiles retain their last complete GPU snapshot while the next
    // patch is assembled. Cached stale tiles stay hidden until their atomic
    // refresh commit. Neither path alternates every footstep between meshes.
    this.syncDetailCoverage();
  }

  /**
   * Cliff, surface-mask and cave edits can change triangle topology instead
   * of only vertex heights. Drop only intersecting detail tiles and let the
   * normal time-sliced streamer rebuild them safely.
   */
  public refreshTopology(bounds: Readonly<LandSnowMutationBounds>): void {
    for (const [key, tile] of [...this.activeTiles]) {
      const minX = tile.tileX * LAND_SNOW_TILE_SIZE;
      const minZ = tile.tileZ * LAND_SNOW_TILE_SIZE;
      if (
        minX + LAND_SNOW_TILE_SIZE < bounds.minX || minX > bounds.maxX ||
        minZ + LAND_SNOW_TILE_SIZE < bounds.minZ || minZ > bounds.maxZ
      ) continue;
      this.disposeTile(tile);
      this.activeTiles.delete(key);
    }
    for (const [key, tile] of [...this.cachedTiles]) {
      const minX = tile.tileX * LAND_SNOW_TILE_SIZE;
      const minZ = tile.tileZ * LAND_SNOW_TILE_SIZE;
      if (
        minX + LAND_SNOW_TILE_SIZE < bounds.minX || minX > bounds.maxX ||
        minZ + LAND_SNOW_TILE_SIZE < bounds.minZ || minZ > bounds.maxZ
      ) continue;
      this.cachedTiles.delete(key);
      this.disposeTile(tile);
    }
    this.buildQueue.splice(
      0,
      this.buildQueue.length,
      ...this.buildQueue.filter((request) => {
        const minX = request.tileX * LAND_SNOW_TILE_SIZE;
        const minZ = request.tileZ * LAND_SNOW_TILE_SIZE;
        return minX + LAND_SNOW_TILE_SIZE < bounds.minX || minX > bounds.maxX ||
          minZ + LAND_SNOW_TILE_SIZE < bounds.minZ || minZ > bounds.maxZ;
      }),
    );
    if (this.activeBuild) {
      const request = this.activeBuild.request;
      const minX = request.tileX * LAND_SNOW_TILE_SIZE;
      const minZ = request.tileZ * LAND_SNOW_TILE_SIZE;
      if (!(
        minX + LAND_SNOW_TILE_SIZE < bounds.minX || minX > bounds.maxX ||
        minZ + LAND_SNOW_TILE_SIZE < bounds.minZ || minZ > bounds.maxZ
      )) {
        this.activeBuild = undefined;
      }
    }
    this.requestedKeys.clear();
    if (this.activeBuild) {
      this.requestedKeys.add(this.activeBuild.request.key);
    }
    for (const request of this.buildQueue) this.requestedKeys.add(request.key);
    this.syncDetailCoverage();
  }

  private stampBounds(
    stamp: Readonly<LandSnowMicroStamp>,
  ): LandSnowMutationBounds {
    const radius = Math.max(stamp.radiusX, stamp.radiusZ) * 1.65;
    return {
      minX: stamp.x - radius,
      maxX: stamp.x + radius,
      minZ: stamp.z - radius,
      maxZ: stamp.z + radius,
      priority: 'INTERACTION',
    };
  }

  private hasNearbyContactStamp(
    stamp: Readonly<LandSnowMicroStamp>,
  ): boolean {
    const nearby = this.stampBuckets.get(bucketKey(stamp.x, stamp.z));
    if (!nearby) return false;
    const duplicateRadius = stamp.kind === 'WADE' ? 0.065 : 0.038;
    return nearby.some((candidate) =>
      candidate.kind === stamp.kind &&
      Math.hypot(candidate.x - stamp.x, candidate.z - stamp.z) <
        duplicateRadius
    );
  }

  private addContactStampBatch(
    stamps: readonly LandSnowMicroStamp[],
  ): void {
    let dirty: LandSnowMutationBounds | undefined;
    for (const stamp of stamps) {
      // Returning through a tamped path must not stack another visual trench
      // or evict the exact contacts that are still visible behind the player.
      if (this.hasNearbyContactStamp(stamp)) continue;
      const changed = this.addStamp(stamp, false);
      if (changed) dirty = mergeBounds(dirty, changed);
    }
    if (dirty) this.invalidateBounds(dirty);
  }

  private addStamp(
    stamp: LandSnowMicroStamp,
    invalidate = true,
  ): LandSnowMutationBounds | undefined {
    const tileX = Math.floor(stamp.x / LAND_SNOW_TILE_SIZE);
    const tileZ = Math.floor(stamp.z / LAND_SNOW_TILE_SIZE);
    const tileKey = landSnowTileKey(tileX, tileZ);
    if (
      this.desiredStampTileKeys.size > 0 &&
      !this.desiredStampTileKeys.has(tileKey)
    ) return undefined;
    let dirty: LandSnowMutationBounds | undefined = this.stampBounds(stamp);
    const stamps = this.stampsByTile.get(tileKey) ?? [];
    stamps.push(stamp);
    this.stampsByTile.set(tileKey, stamps);
    this.touchMicroStampTile(tileKey);
    this.addStampToBuckets(stamp);
    if (stamps.length > MAXIMUM_MICRO_STAMPS_PER_TILE) {
      const removed = stamps.shift();
      if (removed) {
        this.removeStampFromBuckets(removed);
        dirty = mergeBounds(dirty, this.stampBounds(removed));
      }
    }
    if (invalidate && dirty) this.invalidateBounds(dirty);
    return dirty;
  }

  private addStampToBuckets(stamp: LandSnowMicroStamp): void {
    const radius = Math.max(stamp.radiusX, stamp.radiusZ) * 1.65;
    const minX = Math.floor((stamp.x - radius) / MICRO_BUCKET_METRES);
    const maxX = Math.floor((stamp.x + radius) / MICRO_BUCKET_METRES);
    const minZ = Math.floor((stamp.z - radius) / MICRO_BUCKET_METRES);
    const maxZ = Math.floor((stamp.z + radius) / MICRO_BUCKET_METRES);
    for (let z = minZ; z <= maxZ; z += 1) {
      for (let x = minX; x <= maxX; x += 1) {
        const key = `${x},${z}`;
        const bucket = this.stampBuckets.get(key) ?? [];
        bucket.push(stamp);
        this.stampBuckets.set(key, bucket);
      }
    }
  }

  private removeStampFromBuckets(stamp: Readonly<LandSnowMicroStamp>): void {
    const radius = Math.max(stamp.radiusX, stamp.radiusZ) * 1.65;
    const minX = Math.floor((stamp.x - radius) / MICRO_BUCKET_METRES);
    const maxX = Math.floor((stamp.x + radius) / MICRO_BUCKET_METRES);
    const minZ = Math.floor((stamp.z - radius) / MICRO_BUCKET_METRES);
    const maxZ = Math.floor((stamp.z + radius) / MICRO_BUCKET_METRES);
    for (let z = minZ; z <= maxZ; z += 1) {
      for (let x = minX; x <= maxX; x += 1) {
        const key = `${x},${z}`;
        const bucket = this.stampBuckets.get(key);
        if (!bucket) continue;
        const index = bucket.findIndex((candidate) => candidate.id === stamp.id);
        if (index >= 0) bucket.splice(index, 1);
        if (bucket.length === 0) this.stampBuckets.delete(key);
      }
    }
  }

  private reconcileMicroStampTiles(
    desiredKeys: ReadonlySet<string>,
  ): Set<string> {
    const discarded = new Set<string>();
    this.desiredStampTileKeys.clear();
    for (const key of desiredKeys) {
      this.desiredStampTileKeys.add(key);
      if (this.stampsByTile.has(key)) this.touchMicroStampTile(key);
    }
    while (this.stampsByTile.size > MAXIMUM_RETAINED_MICRO_STAMP_TILES) {
      let oldestOutsideWindow: string | undefined;
      for (const key of this.stampTileRecency.keys()) {
        if (!desiredKeys.has(key)) {
          oldestOutsideWindow = key;
          break;
        }
      }
      if (!oldestOutsideWindow) break;
      this.discardMicroStampTile(oldestOutsideWindow);
      discarded.add(oldestOutsideWindow);
    }
    return discarded;
  }

  private touchMicroStampTile(key: string): void {
    this.stampTileRecency.delete(key);
    this.stampTileRecency.set(key, true);
  }

  private discardMicroStampTile(key: string): void {
    const stamps = this.stampsByTile.get(key);
    if (stamps) {
      for (const stamp of stamps) this.removeStampFromBuckets(stamp);
      this.stampsByTile.delete(key);
    }
    this.stampTileRecency.delete(key);
  }

  private clearMicroStamps(): void {
    this.stampsByTile.clear();
    this.stampBuckets.clear();
    this.desiredStampTileKeys.clear();
    this.stampTileRecency.clear();
  }

  private microHeightAt(x: number, z: number, sampleSpacing = 0): number {
    const stamps = this.stampBuckets.get(bucketKey(x, z));
    if (!stamps) return 0;
    let deepestDepression = 0;
    let strongestLip = 0;
    for (const stamp of stamps) {
      const dx = x - stamp.x;
      const dz = z - stamp.z;
      const right = dx * Math.cos(stamp.heading) - dz * Math.sin(stamp.heading);
      const forward = dx * Math.sin(stamp.heading) + dz * Math.cos(stamp.heading);
      // V5's 12.5 cm lattice cannot reliably hit an exact 11 cm boot. Expand
      // only the sampling kernel (not the authored contact or V6 shape) far
      // enough that every step owns at least one vertex. This restores the
      // deep channel without widening the saved/canonical trail.
      const sampledRadiusX = Math.max(
        stamp.radiusX,
        sampleSpacing > 0.08
          ? sampleSpacing * 0.68
          : sampleSpacing > 0
            ? sampleSpacing * 0.92
            : stamp.radiusX,
      );
      const sampledRadiusZ = Math.max(
        stamp.radiusZ,
        sampleSpacing > 0.08 ? sampleSpacing * 0.76 : stamp.radiusZ,
      );
      const distance = Math.hypot(
        right / sampledRadiusX,
        forward / sampledRadiusZ,
      );
      if (distance >= 1.6) continue;
      const depression = distance < 1
        ? -stamp.depth * (1 - smoothstep(0.18, 1, distance))
        : 0;
      // Smooth inner and outer shoulders retain displaced snow without a
      // triangular peak landing exactly on individual V6 vertices.
      const lip = stamp.depth * 0.24 *
        smoothstep(0.78, 1.12, distance) *
        (1 - smoothstep(1.12, 1.53, distance));
      // Overlapping swept contacts describe one tamped surface, not repeated
      // excavation. Max-composition keeps a continuous groove while preventing
      // the fine mask from sinking again when the same route is retraced.
      deepestDepression = Math.min(deepestDepression, depression);
      strongestLip = Math.max(strongestLip, Math.max(0, lip));
    }
    return clamp(deepestDepression + strongestLip, -0.16, 0.1);
  }

  /**
   * V6 smooths only the canonical 25 cm carrier surface, never the authored
   * boot or pelvis contact. Filtering the contact itself was why Ultra lost
   * the narrow drag channels which were readable on V5. This blend fades to
   * the exact canonical height at tile edges, keeping V5/V6 seams welded.
   */
  private presentationSurfaceHeightAt(
    x: number,
    z: number,
    sampleSpacing: number,
    edgeFade: number,
  ): number {
    const centre = this.snow.sampleSurfaceHeight(x, z);
    if (sampleSpacing >= 0.08 || sampleSpacing <= 0) return centre;
    const shoulder = 0.125;
    const reconstructed = centre * 0.5 + (
      this.snow.sampleSurfaceHeight(x - shoulder, z) +
      this.snow.sampleSurfaceHeight(x + shoulder, z) +
      this.snow.sampleSurfaceHeight(x, z - shoulder) +
      this.snow.sampleSurfaceHeight(x, z + shoulder)
    ) * 0.125;
    return centre + (reconstructed - centre) * edgeFade * 0.78;
  }

  private clearDetailTiles(): void {
    for (const tile of this.activeTiles.values()) {
      this.disposeTile(tile);
    }
    this.activeTiles.clear();
    for (const tile of this.cachedTiles.values()) this.disposeTile(tile);
    this.cachedTiles.clear();
    this.buildQueue.length = 0;
    this.activeBuild = undefined;
    this.requestedKeys.clear();
    this.detailAnchorTileX = undefined;
    this.detailAnchorTileZ = undefined;
    this.snow.setDetailCoveredTileKeys(new Set());
  }

  /**
   * Recently visited fine meshes are cheap to retain and expensive to
   * regenerate. Keeping a small level-aware LRU makes a return journey show
   * the exact same V5/V6 shape immediately instead of briefly falling back to
   * coarse V3 and rebuilding a 66k-vertex tile in view.
   */
  private cacheTile(tile: DetailTile): void {
    tile.mesh.removeFromParent();
    if (
      tile.dirty || tile.refresh ||
      tile.interactionDirty || tile.interactionRefresh
    ) {
      // The CPU arrays may contain an unfinished patch which the GPU has not
      // received. A returning cache entry must wait for the atomic commit
      // before it can hide canonical V3 again.
      tile.presentationReady = false;
    }
    const key = this.detailCacheKey(tile.key, tile.level);
    const previous = this.cachedTiles.get(key);
    if (previous && previous !== tile) this.disposeTile(previous);
    this.cachedTiles.delete(key);
    this.cachedTiles.set(key, tile);
    this.pruneCachedLevel('V5', MAXIMUM_CACHED_V5_TILES);
    this.pruneCachedLevel('V6', MAXIMUM_CACHED_V6_TILES);
  }

  private pruneCachedLevel(
    level: LandSnowMicrodetailLevel,
    maximum: number,
  ): void {
    let count = 0;
    for (const tile of this.cachedTiles.values()) {
      if (tile.level === level) count += 1;
    }
    if (count <= maximum) return;
    for (const [key, tile] of this.cachedTiles) {
      if (tile.level !== level) continue;
      this.cachedTiles.delete(key);
      this.disposeTile(tile);
      count -= 1;
      if (count <= maximum) break;
    }
  }

  private disposeTile(tile: DetailTile): void {
    tile.mesh.geometry.dispose();
    tile.mesh.removeFromParent();
  }

  private detailCacheKey(
    worldTileKey: string,
    level: LandSnowMicrodetailLevel,
  ): string {
    return `${worldTileKey}|${level}`;
  }

  private isTilePresentationReady(tile: Readonly<DetailTile>): boolean {
    return tile.presentationReady;
  }

  private syncDetailCoverage(): void {
    const covered = new Set<string>();
    for (const [key, tile] of this.activeTiles) {
      const ready = this.isTilePresentationReady(tile);
      tile.mesh.visible = ready;
      if (ready) covered.add(key);
    }
    this.snow.setDetailCoveredTileKeys(covered);
  }
}
