import {
  BoxGeometry,
  BufferAttribute,
  BufferGeometry,
  CircleGeometry,
  Color,
  CylinderGeometry,
  DoubleSide,
  Group,
  LineBasicMaterial,
  LineSegments,
  Mesh,
  MeshBasicMaterial,
  MeshStandardMaterial,
  Points,
  PointsMaterial,
  SphereGeometry,
  type Material,
  type Scene,
} from 'three';
import { clamp, damp, hash2D, smoothstep } from '../../utils/math';
import type { BorealisArrivalSequenceState } from './BorealisArrivalSequence';
import { BOREALIS_VERTICAL_SLICE_ASSETS } from './BorealisVerticalSliceAssetCatalog';

const ROPE_TOPS = [
  [-2.5, 3.8, -0.9],
  [-1.25, 4.1, 0.75],
  [1.25, 4.1, 0.75],
  [2.5, 3.8, -0.9],
] as const;

const ROPE_BOTTOMS = [
  [-0.22, 0.76, -0.08],
  [-0.18, 0.78, 0.12],
  [0.18, 0.78, 0.12],
  [0.22, 0.76, -0.08],
] as const;

const PARTICLE_COUNT = 96;

export class BorealisArrivalPresenter {
  private readonly root = new Group();
  private readonly canopy = new Group();
  private readonly ropes = new LineSegments();
  private readonly pack = new Group();
  private readonly plane = new Group();
  private readonly shadow: Mesh;
  private readonly particles: Points;
  private readonly particlePositions = new Float32Array(PARTICLE_COUNT * 3);
  private readonly particleVelocities = new Float32Array(PARTICLE_COUNT * 3);
  private readonly particleLives = new Float32Array(PARTICLE_COUNT);
  private readonly particleGeometry = new BufferGeometry();
  private readonly materials: Material[] = [];
  private readonly ropeGeometry = new BufferGeometry();
  private readonly ropePositions = new Float32Array(ROPE_TOPS.length * 2 * 3);
  private previousPhase = 'PENDING';
  private collapseSeconds = 0;
  private visible = false;

  public constructor(private readonly scene: Scene) {
    this.root.name = 'Borealis arrival parachute';
    this.root.userData.assetBankId = BOREALIS_VERTICAL_SLICE_ASSETS.parachute.id;
    this.canopy.position.y = 0;
    this.createCanopy();
    this.createPack();
    this.createMailPlane();
    this.ropeGeometry.setAttribute('position', new BufferAttribute(this.ropePositions, 3));
    const ropeMaterial = new LineBasicMaterial({ color: 0xd8d0b5, transparent: true, opacity: 0.84 });
    this.materials.push(ropeMaterial);
    this.ropes.geometry = this.ropeGeometry;
    this.ropes.material = ropeMaterial;
    this.ropes.name = 'Parachute suspension lines';
    this.root.add(this.canopy, this.ropes, this.pack);

    const shadowMaterial = new MeshBasicMaterial({
      color: 0x23434b,
      transparent: true,
      opacity: 0.16,
      depthWrite: false,
      side: DoubleSide,
    });
    this.materials.push(shadowMaterial);
    this.shadow = new Mesh(new CircleGeometry(1, 24), shadowMaterial);
    this.shadow.rotation.x = -Math.PI / 2;
    this.shadow.name = 'Parachute ground shadow';

    const particleMaterial = new PointsMaterial({
      color: new Color(0xe8f5f5),
      size: 0.22,
      transparent: true,
      opacity: 0.88,
      depthWrite: false,
      sizeAttenuation: true,
    });
    this.materials.push(particleMaterial);
    this.particleGeometry.setAttribute('position', new BufferAttribute(this.particlePositions, 3));
    this.particles = new Points(this.particleGeometry, particleMaterial);
    this.particles.frustumCulled = false;
    this.particles.name = 'Parachute landing snow puff';
    this.scene.add(this.root, this.plane, this.shadow, this.particles);
    this.setVisible(false);
  }

  public setVisible(visible: boolean): void {
    this.visible = visible;
    this.root.visible = visible;
    this.shadow.visible = visible;
    this.plane.visible = visible;
    this.particles.visible = visible;
  }

  public update(
    state: Readonly<BorealisArrivalSequenceState>,
    deltaSeconds: number,
    groundY: number,
    elapsedWorldSeconds: number,
  ): void {
    const delta = clamp(deltaSeconds, 0, 0.05);
    const active = state.phase === 'DESCENDING' || state.phase === 'TOUCHDOWN';
    const lingering = state.phase === 'COMPLETE' && this.collapseSeconds < 3.6;
    this.setVisible(active || lingering);
    if (!this.visible) return;

    const characterY = groundY + state.altitude;
    this.root.position.set(state.x, characterY, state.z);
    this.root.rotation.y = state.heading;
    const steerLeanX = clamp(state.steeringX, -1, 1);
    const steerLeanZ = clamp(state.steeringZ, -1, 1);
    const gust = Math.sin(elapsedWorldSeconds * 1.4 + state.x * 0.03) * 0.035;
    this.canopy.rotation.z = damp(this.canopy.rotation.z, -steerLeanX * 0.34 + gust, 7, delta);
    this.canopy.rotation.x = damp(this.canopy.rotation.x, steerLeanZ * 0.23, 7, delta);
    this.pack.rotation.z = this.canopy.rotation.z * 0.38;
    this.pack.rotation.x = this.canopy.rotation.x * 0.3;
    this.writeRopes();

    const shadowScale = 0.85 + smoothstep(0, 65, state.altitude) * 2.7;
    this.shadow.position.set(state.x, groundY + 0.035, state.z);
    this.shadow.scale.setScalar(shadowScale);
    (this.shadow.material as MeshBasicMaterial).opacity =
      0.22 * (1 - smoothstep(28, 110, state.altitude));

    const planeLife = clamp(1 - state.elapsedSeconds / 10, 0, 1);
    this.plane.visible = active && planeLife > 0;
    this.plane.position.set(
      state.x - 18 - state.elapsedSeconds * 7.5,
      characterY + 13 + state.elapsedSeconds * 0.7,
      state.z - 12 - state.elapsedSeconds * 3.2,
    );
    this.plane.rotation.y = 1.12;
    this.plane.rotation.z = -0.08;
    this.plane.scale.setScalar(0.78 + planeLife * 0.22);

    if (this.previousPhase !== 'TOUCHDOWN' && state.phase === 'TOUCHDOWN') {
      this.emitLandingPuff(state.x, groundY + 0.1, state.z);
    }
    if (state.phase === 'TOUCHDOWN') {
      const squash = smoothstep(0, 0.7, state.touchdownSeconds);
      this.canopy.scale.y = 1 - squash * 0.42;
      this.canopy.position.z = -squash * 0.7;
    } else if (state.phase === 'COMPLETE') {
      this.collapseSeconds += delta;
      const collapse = smoothstep(0, 1.6, this.collapseSeconds);
      this.canopy.scale.set(1 - collapse * 0.62, 0.58 - collapse * 0.5, 1 - collapse * 0.22);
      this.canopy.position.set(-collapse * 1.9, -collapse * 3.3, -collapse * 1.4);
      this.canopy.rotation.z += delta * 0.42;
      this.pack.visible = collapse < 0.55;
      this.ropes.visible = collapse < 0.8;
    }
    this.previousPhase = state.phase;
    this.updateLandingPuff(delta);
  }

  public dispose(): void {
    for (const object of [this.root, this.plane, this.shadow, this.particles]) {
      object.traverse((child) => {
        if (child instanceof Mesh) child.geometry.dispose();
      });
      object.removeFromParent();
    }
    this.ropeGeometry.dispose();
    this.particleGeometry.dispose();
    for (const material of this.materials) material.dispose();
  }

  private createCanopy(): void {
    const colors = [0xe77a3d, 0xf2c36b, 0xe8eee7, 0x4f8d98, 0xe8eee7, 0xf2c36b, 0xe77a3d];
    colors.forEach((color, index) => {
      const material = new MeshStandardMaterial({
        color,
        roughness: 0.78,
        metalness: 0,
        side: DoubleSide,
      });
      this.materials.push(material);
      const panel = new Mesh(new SphereGeometry(
        1,
        5,
        4,
        index / colors.length * Math.PI * 2,
        Math.PI * 2 / colors.length + 0.018,
        0,
        Math.PI * 0.48,
      ), material);
      panel.scale.set(2.68, 1.05, 2.68);
      panel.castShadow = true;
      panel.receiveShadow = true;
      this.canopy.add(panel);
    });
    this.canopy.position.y = 4.05;
    this.canopy.rotation.x = 0.04;
    this.canopy.name = 'Low-poly caretaker parachute canopy';
  }

  private createPack(): void {
    const cloth = new MeshStandardMaterial({ color: 0x4d665f, roughness: 0.88 });
    const straps = new MeshStandardMaterial({ color: 0x27383a, roughness: 0.82 });
    this.materials.push(cloth, straps);
    const bag = new Mesh(new BoxGeometry(0.42, 0.5, 0.2), cloth);
    bag.position.set(0, 0.68, -0.23);
    const left = new Mesh(new BoxGeometry(0.055, 0.5, 0.07), straps);
    left.position.set(-0.17, 0.62, 0.02);
    const right = left.clone();
    right.position.x = 0.17;
    this.pack.add(bag, left, right);
    this.pack.name = 'Caretaker parachute harness';
    this.pack.userData.assetBankId = BOREALIS_VERTICAL_SLICE_ASSETS.parachutePack.id;
  }

  private createMailPlane(): void {
    const red = new MeshStandardMaterial({ color: 0xb44d3e, roughness: 0.7, metalness: 0.08 });
    const pale = new MeshStandardMaterial({ color: 0xd9e3df, roughness: 0.74 });
    const dark = new MeshStandardMaterial({ color: 0x27383d, roughness: 0.68, metalness: 0.2 });
    this.materials.push(red, pale, dark);
    const fuselage = new Mesh(new CylinderGeometry(0.55, 0.38, 4.6, 8), red);
    fuselage.rotation.x = Math.PI / 2;
    const wing = new Mesh(new BoxGeometry(7.2, 0.16, 1.1), pale);
    wing.position.z = 0.2;
    const tail = new Mesh(new BoxGeometry(2.45, 0.12, 0.6), pale);
    tail.position.z = -1.75;
    const fin = new Mesh(new BoxGeometry(0.12, 1.1, 0.72), red);
    fin.position.set(0, 0.56, -1.8);
    const nose = new Mesh(new CylinderGeometry(0.06, 0.06, 3.1, 8), dark);
    nose.rotation.z = Math.PI / 2;
    nose.position.z = 2.36;
    for (const mesh of [fuselage, wing, tail, fin, nose]) {
      mesh.castShadow = true;
      this.plane.add(mesh);
    }
    this.plane.name = 'Low-poly Borealis mail plane';
    this.plane.userData.assetBankId = BOREALIS_VERTICAL_SLICE_ASSETS.mailPlane.id;
  }

  private writeRopes(): void {
    for (let index = 0; index < ROPE_TOPS.length; index += 1) {
      const top = ROPE_TOPS[index]!;
      const bottom = ROPE_BOTTOMS[index]!;
      const offset = index * 6;
      this.ropePositions[offset] = top[0];
      this.ropePositions[offset + 1] = top[1];
      this.ropePositions[offset + 2] = top[2];
      this.ropePositions[offset + 3] = bottom[0];
      this.ropePositions[offset + 4] = bottom[1];
      this.ropePositions[offset + 5] = bottom[2];
    }
    this.ropeGeometry.getAttribute('position').needsUpdate = true;
  }

  private emitLandingPuff(x: number, y: number, z: number): void {
    for (let index = 0; index < PARTICLE_COUNT; index += 1) {
      const angle = hash2D(index, 14, 91) * Math.PI * 2;
      const speed = 0.9 + hash2D(index, 37, 112) * 2.5;
      this.particlePositions[index * 3] = x + Math.cos(angle) * 0.16;
      this.particlePositions[index * 3 + 1] = y + hash2D(index, 61, 77) * 0.22;
      this.particlePositions[index * 3 + 2] = z + Math.sin(angle) * 0.16;
      this.particleVelocities[index * 3] = Math.cos(angle) * speed;
      this.particleVelocities[index * 3 + 1] = 0.45 + hash2D(index, 88, 31) * 1.9;
      this.particleVelocities[index * 3 + 2] = Math.sin(angle) * speed;
      this.particleLives[index] = 0.55 + hash2D(index, 123, 9) * 0.65;
    }
    this.particleGeometry.getAttribute('position').needsUpdate = true;
  }

  private updateLandingPuff(delta: number): void {
    for (let index = 0; index < PARTICLE_COUNT; index += 1) {
      const offset = index * 3;
      if (this.particleLives[index]! <= 0) {
        this.particlePositions[offset + 1] = -100;
        continue;
      }
      this.particleLives[index] = this.particleLives[index]! - delta;
      this.particlePositions[offset] = this.particlePositions[offset]! + this.particleVelocities[offset]! * delta;
      this.particlePositions[offset + 1] = this.particlePositions[offset + 1]! + this.particleVelocities[offset + 1]! * delta;
      this.particlePositions[offset + 2] = this.particlePositions[offset + 2]! + this.particleVelocities[offset + 2]! * delta;
      this.particleVelocities[offset] = this.particleVelocities[offset]! * (1 - delta * 2.4);
      this.particleVelocities[offset + 1] = this.particleVelocities[offset + 1]! - 3.8 * delta;
      this.particleVelocities[offset + 2] = this.particleVelocities[offset + 2]! * (1 - delta * 2.4);
    }
    this.particleGeometry.getAttribute('position').needsUpdate = true;
  }
}
