export interface ModelBounds {
  minX: number;
  minY: number;
  minZ: number;
  maxX: number;
  maxY: number;
  maxZ: number;
}

export interface VesselModelTarget {
  width: number;
  height: number;
  length: number;
  bottom: number;
}

export interface VesselModelFit {
  sourceWidth: number;
  sourceHeight: number;
  sourceLength: number;
  centerX: number;
  centerZ: number;
  bottomY: number;
  scaleX: number;
  scaleY: number;
  scaleZ: number;
  renderedWidth: number;
  renderedHeight: number;
  renderedLength: number;
  rotationY: number;
}

const positiveSize = (minimum: number, maximum: number): number =>
  Math.max(0.0001, maximum - minimum);

export const fitVesselModel = (
  bounds: Readonly<ModelBounds>,
  target: Readonly<VesselModelTarget>,
): VesselModelFit => {
  const sizeX = positiveSize(bounds.minX, bounds.maxX);
  const sizeY = positiveSize(bounds.minY, bounds.maxY);
  const sizeZ = positiveSize(bounds.minZ, bounds.maxZ);
  const lengthAlongX = sizeX > sizeZ;
  const sourceWidth = lengthAlongX ? sizeZ : sizeX;
  const sourceLength = lengthAlongX ? sizeX : sizeZ;
  const uniformScale = Math.min(
    target.width / sourceWidth,
    target.height / sizeY,
    target.length / sourceLength,
  );

  return {
    sourceWidth,
    sourceHeight: sizeY,
    sourceLength,
    centerX: (bounds.minX + bounds.maxX) * 0.5,
    centerZ: (bounds.minZ + bounds.maxZ) * 0.5,
    bottomY: bounds.minY,
    scaleX: uniformScale,
    scaleY: uniformScale,
    scaleZ: uniformScale,
    renderedWidth: sourceWidth * uniformScale,
    renderedHeight: sizeY * uniformScale,
    renderedLength: sourceLength * uniformScale,
    rotationY: lengthAlongX ? -Math.PI * 0.5 : 0,
  };
};
