import type { JsonValue } from './NetworkPrimitives';

const canonicalize = (value: JsonValue): string => {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) {
    return `[${value.map((item) => canonicalize(item)).join(',')}]`;
  }
  const record = value as { readonly [key: string]: JsonValue };
  return `{${Object.keys(record)
    .sort()
    .map((key) => `${JSON.stringify(key)}:${canonicalize(record[key]!)}`)
    .join(',')}}`;
};

/** Stable FNV-1a hash for traces and convergence checks, not security. */
const normalizeSerializable = (value: unknown): JsonValue => {
  const encoded = JSON.stringify(value);
  if (typeof encoded !== 'string') {
    throw new Error('State hash input is not JSON serializable.');
  }
  return JSON.parse(encoded) as JsonValue;
};

export const deterministicStateHash = (value: unknown): string => {
  const input = canonicalize(normalizeSerializable(value));
  let hash = 0x811c9dc5;
  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
};

export const canonicalStateJson = (value: unknown): string =>
  canonicalize(normalizeSerializable(value));
