  private createTrailer(): Mesh {
    const steel = this.material(0x51686b, 0.62, 0.3); const dark = this.material(0x242c2e); const snow = this.material(0xd8f1f2, 0.94, 0);
    // Open tray: the former solid box hid most partial snow loads.
    // The bed pivots around its rear edge (local Z 0); the drawbar and wheels
    // remain with the chassis while the front of the tray rises.
    this.trailerBed.name = 'Small snow trailer tipping bed';
    this.trailerTailgate.name = 'Small snow trailer opening tailgate';
    this.trailerBed.position.z = -1.03;
    this.addBox(this.trailerBed, [1.7, 0.16, 2.2], [0, 0.25, 1.03], steel);
    this.addBox(this.trailerBed, [0.15, 0.62, 2.2], [-0.78, 0.56, 1.03], steel);
    this.addBox(this.trailerBed, [0.15, 0.62, 2.2], [0.78, 0.56, 1.03], steel);
    this.addBox(this.trailerBed, [1.42, 0.62, 0.14], [0, 0.56, 2.06], steel);
    this.trailerTailgate.position.set(0, 0.87, 0);
    this.addBox(this.trailerTailgate, [1.42, 0.62, 0.14], [0, -0.31, 0], steel);
    this.trailerBed.add(this.trailerTailgate);
    this.trailerRoot.add(this.trailerBed);
    const drawbar = this.addBox(this.trailerRoot, [0.12, 0.12, 1.6], [0, 0.35, 1.7], steel); drawbar.rotation.x = -0.02;
    for (const x of [-0.9, 0.9]) {
      const wheel = new Mesh(new CylinderGeometry(0.34, 0.34, 0.24, 12), dark);
      wheel.rotation.z = Math.PI / 2; wheel.position.set(x, 0.3, -0.2); this.trailerRoot.add(wheel);
    }
    const cargo = this.addBox(this.trailerBed, [1.4, 0.72, 1.86], [0, 0.4, 1.03], snow);
    cargo.name = 'Visible snow in small trailer';
    cargo.visible = false;
    this.trailerRoot.name = 'Attachable small snow trailer';
    return cargo;
  }

