import type { ConstructionBlueprint } from './ConstructionBlueprint';
import { getConstructionModule } from './ConstructionModuleCatalog';

export interface ConstructionUtilityAnalysis {
  machineCount: number;
  enabledMachineCount: number;
  powerGeneration: number;
  powerDemand: number;
  workCapacity: number;
  powerCoverage: number;
  warnings: readonly string[];
}

export const analyzeConstructionUtilities = (
  blueprint: Readonly<ConstructionBlueprint>,
): ConstructionUtilityAnalysis => {
  let machineCount = 0;
  let enabledMachineCount = 0;
  let powerGeneration = 0;
  let powerDemand = 0;
  let workCapacity = 0;
  const warnings: string[] = [];

  for (const placement of blueprint.placements) {
    const definition = getConstructionModule(placement.moduleId);
    if (!definition?.mechanism) continue;
    machineCount += 1;
    const state = placement.machineState ?? { enabled: true, control: 1 };
    if (!state.enabled) continue;
    enabledMachineCount += 1;
    const control = Math.max(0, Math.min(1, state.control));
    for (const port of definition.utilityPorts ?? []) {
      const capacity = port.capacity * control;
      if (port.kind === 'power' && port.direction === 'output') {
        powerGeneration += capacity;
      } else if (port.kind === 'power' && port.direction === 'input') {
        powerDemand += capacity;
      } else if (port.kind === 'work' && port.direction === 'output') {
        workCapacity += capacity;
      }
    }
  }

  if (powerDemand > powerGeneration + 0.001) {
    warnings.push(
      `Power demand exceeds generation by ${(powerDemand - powerGeneration).toFixed(1)} units.`,
    );
  }
  if (enabledMachineCount > 0 && powerGeneration === 0 && powerDemand > 0) {
    warnings.push('Powered machinery has no enabled generator.');
  }

  return {
    machineCount,
    enabledMachineCount,
    powerGeneration,
    powerDemand,
    workCapacity,
    powerCoverage:
      powerDemand <= 0 ? 1 : Math.min(1, powerGeneration / powerDemand),
    warnings,
  };
};

