import type { SettlementContentRegistry } from './SettlementContentRegistry';
import type { SettlementBuildingSystem } from './SettlementBuildingSystem';
import type { SettlementWarehouse } from './SettlementWarehouse';
import type {
  SettlementProductionRuntimeState,
  SettlementProductionSaveData,
  SettlementProductionView,
} from './SettlementTypes';

interface MutableProductionState {
  operationId: string;
  recipeId: string;
  buildingId: string;
  status: 'RUNNING' | 'OUTPUT_READY';
  startedAt: number;
  completesAt: number;
  revision: number;
}

export interface SettlementProductionStartResult {
  readonly accepted: boolean;
  readonly status: string;
  readonly operationId?: string;
}

const cloneRuntime = (
  state: Readonly<MutableProductionState>,
): SettlementProductionRuntimeState => ({ ...state });

/** Timed recipes consume inputs atomically and retain blocked outputs safely. */
export class SettlementProductionSystem {
  private readonly operations = new Map<string, MutableProductionState>();
  private readonly completedOperationIds = new Set<string>();

  public constructor(
    private readonly registry: SettlementContentRegistry,
    private readonly buildings: SettlementBuildingSystem,
    private readonly warehouse: SettlementWarehouse,
    saved?: Readonly<SettlementProductionSaveData>,
  ) {
    if (saved?.version !== 1) return;
    for (const operationId of saved.completedOperationIds ?? []) {
      if (typeof operationId === 'string' && operationId.length <= 192) {
        this.completedOperationIds.add(operationId);
      }
    }
    for (const candidate of saved.operations ?? []) this.importRuntime(candidate);
  }

  public start(
    recipeId: string,
    simulationTime: number,
    operationId: string,
  ): SettlementProductionStartResult {
    const recipe = this.registry.getRecipe(recipeId);
    if (!recipe) return { accepted: false, status: 'UNKNOWN_RECIPE' };
    if (this.operations.has(operationId) || this.completedOperationIds.has(operationId)) {
      return { accepted: false, status: 'DUPLICATE_OPERATION' };
    }
    if ([...this.operations.values()].some(
      (operation) => operation.buildingId === recipe.buildingId,
    )) {
      return { accepted: false, status: 'BUILDING_BUSY' };
    }
    if (this.buildings.getStructuralLevel(recipe.buildingId) < recipe.minimumBuildingLevel) {
      return { accepted: false, status: 'BUILDING_NOT_READY' };
    }
    if (
      recipe.requiresAssignedNpcPresent &&
      this.buildings.getStaffing(recipe.buildingId) !== 'PRESENT'
    ) {
      return { accepted: false, status: 'REQUIRED_STAFF_ABSENT' };
    }
    if (!this.warehouse.canApply(recipe.inputs, -1)) {
      return { accepted: false, status: 'MISSING_INPUTS' };
    }
    if (!this.warehouse.apply(recipe.inputs, -1)) {
      return { accepted: false, status: 'INPUT_TRANSACTION_FAILED' };
    }
    const startedAt = Math.max(0, simulationTime);
    this.operations.set(operationId, {
      operationId,
      recipeId,
      buildingId: recipe.buildingId,
      status: 'RUNNING',
      startedAt,
      completesAt: startedAt + recipe.durationSeconds,
      revision: 1,
    });
    return { accepted: true, status: 'PRODUCTION_STARTED', operationId };
  }

  public update(simulationTime: number): readonly string[] {
    const ready: string[] = [];
    for (const operation of this.operations.values()) {
      if (operation.status !== 'RUNNING' || simulationTime < operation.completesAt) continue;
      operation.status = 'OUTPUT_READY';
      operation.revision += 1;
      ready.push(operation.operationId);
    }
    return ready.sort();
  }

  public collect(operationId: string): string {
    const operation = this.operations.get(operationId);
    if (!operation) {
      return this.completedOperationIds.has(operationId)
        ? 'ALREADY_COLLECTED'
        : 'UNKNOWN_OPERATION';
    }
    if (operation.status !== 'OUTPUT_READY') return 'OUTPUT_NOT_READY';
    const recipe = this.registry.getRecipe(operation.recipeId);
    if (!recipe) return 'UNKNOWN_RECIPE';
    if (!this.warehouse.canApply(recipe.outputs, 1)) return 'WAREHOUSE_FULL';
    if (!this.warehouse.apply(recipe.outputs, 1)) return 'OUTPUT_TRANSACTION_FAILED';
    this.operations.delete(operationId);
    this.completedOperationIds.add(operationId);
    while (this.completedOperationIds.size > 2_048) {
      const oldest = this.completedOperationIds.values().next().value as string | undefined;
      if (!oldest) break;
      this.completedOperationIds.delete(oldest);
    }
    return 'OUTPUT_COLLECTED';
  }

  public getViews(): readonly SettlementProductionView[] {
    return [...this.operations.values()]
      .sort((left, right) => left.operationId.localeCompare(right.operationId))
      .flatMap((operation) => {
        const recipe = this.registry.getRecipe(operation.recipeId);
        return recipe
          ? [{
              ...cloneRuntime(operation),
              displayName: recipe.displayName,
              outputs: recipe.outputs.map((output) => ({ ...output })),
            }]
          : [];
      });
  }

  public exportState(): SettlementProductionSaveData {
    return {
      version: 1,
      operations: [...this.operations.values()]
        .sort((left, right) => left.operationId.localeCompare(right.operationId))
        .map(cloneRuntime),
      completedOperationIds: [...this.completedOperationIds],
    };
  }

  private importRuntime(candidate: Readonly<SettlementProductionRuntimeState>): void {
    const recipe = this.registry.getRecipe(candidate?.recipeId);
    if (
      !recipe || candidate.buildingId !== recipe.buildingId ||
      typeof candidate.operationId !== 'string' || candidate.operationId.length > 192 ||
      !['RUNNING', 'OUTPUT_READY'].includes(candidate.status) ||
      !Number.isFinite(candidate.startedAt) || !Number.isFinite(candidate.completesAt) ||
      candidate.completesAt < candidate.startedAt ||
      this.operations.has(candidate.operationId) ||
      [...this.operations.values()].some((value) => value.buildingId === recipe.buildingId)
    ) return;
    this.operations.set(candidate.operationId, {
      operationId: candidate.operationId,
      recipeId: recipe.id,
      buildingId: recipe.buildingId,
      status: candidate.status,
      startedAt: Math.max(0, candidate.startedAt),
      completesAt: Math.max(0, candidate.completesAt),
      revision: Number.isSafeInteger(candidate.revision) && candidate.revision >= 0
        ? candidate.revision
        : 0,
    });
  }
}
