const EARTH_RADIUS_METRES = 6_360_000;
/**
 * The source photographs are not true equirectangular panoramas: repeating
 * them creates a visible seam and some contain a photographed horizon. Keep
 * the loader available as an authoring fallback, but ship the seamless
 * physical/procedural atmosphere in gameplay.
 */
const PHOTOGRAPHIC_SKY_BACKDROPS_ENABLED = false;
const ARCTIC_SKY_BACKDROP_URLS: Readonly<Record<SkyBackdropId, string>> = {
  PURE_SKY: './assets/environment/arctic-overcast-sky-2k.jpg',
  SNOWY_FIELD: './assets/environment/snowy-field-2k.jpg',
  WINTER_ROADSIDE: './assets/environment/rural-winter-roadside-2k.jpg',
  EVENING_FIELD: './assets/environment/evening-field-2k.jpg',
};
const SUN_SURFACE_URL =
  './assets/environment/celestial/nasa-sdo-sun-1k.jpg';
const MOON_SURFACE_URL =
  './assets/environment/celestial/nasa-lro-moon-color-2k.jpg';
const SUN_DISC_ANGULAR_RADIUS = 0.0092;
const MOON_DISC_ANGULAR_RADIUS = 0.0086;
const SUN_HORIZON_SAMPLE_COUNT = 36;
const SUN_HORIZON_NEAR_DISTANCE = 2.5;
// The visible character camera ends before 2.6 km. A farther terrain sample
// must not make the star disappear behind a ridge the player cannot yet see.
// Reflections still use the longer sample below so remote massifs cannot leak
// a bright celestial streak through their hidden side.
const VISIBLE_CELESTIAL_HORIZON_FAR_DISTANCE = 2_400;
const REFLECTION_CELESTIAL_HORIZON_FAR_DISTANCE = 8_000;
// Human vision notices the exposure lift well before a gaze is centred on the
// solar disc. This broad 25 degree shoulder is intentionally non-damaging;
// retained blindness still requires the much narrower direct-gaze cone below.
const SUN_GAZE_GLOW_OUTER_ANGLE = 25 * Math.PI / 180;
const SUN_GAZE_GLOW_INNER_ANGLE = 2.5 * Math.PI / 180;
// The retina starts to react in a slightly wider cone than the old three
// degrees, but exposure now accumulates much more patiently below. This makes
// the response readable without turning a quick sunset glance into a flash.
const DIRECT_SUN_GAZE_OUTER_ANGLE = 10 * Math.PI / 180;
const DIRECT_SUN_GAZE_INNER_ANGLE = 1.25 * Math.PI / 180;
const EXACT_SUN_GAZE_OUTER_ANGLE = 3.2 * Math.PI / 180;
const EXACT_SUN_GAZE_INNER_ANGLE = 0.45 * Math.PI / 180;
const SIRION_GAZE_OUTER_ANGLE = 14 * Math.PI / 180;
const SIRION_GAZE_INNER_ANGLE = 2.8 * Math.PI / 180;

/** Broad, non-damaging exposure lift while looking generally toward the sun. */
export const resolveSunGazeProximity = (alignment: number): number =>
  smoothstep(
    Math.cos(SUN_GAZE_GLOW_OUTER_ANGLE),
    Math.cos(SUN_GAZE_GLOW_INNER_ANGLE),
    clamp(alignment, -1, 1),
  );

/** Exact-gaze response shared by retinal accumulation and visual gating. */
export const resolveDirectSunGaze = (alignment: number): number =>
  smoothstep(
    Math.cos(DIRECT_SUN_GAZE_OUTER_ANGLE),
    Math.cos(DIRECT_SUN_GAZE_INNER_ANGLE),
    clamp(alignment, -1, 1),
  );

/** Narrow cone capable of eventually bleaching vision after a long stare. */
export const resolveExactSunGaze = (alignment: number): number =>
  smoothstep(
    Math.cos(EXACT_SUN_GAZE_OUTER_ANGLE),
    Math.cos(EXACT_SUN_GAZE_INNER_ANGLE),
    clamp(alignment, -1, 1),
  );

/**
 * A formed negative retinal image is screen-space memory. Looking through or
 * across the solar disc may overpower it with glare, but must never erase its
 * state and make it reappear as a one-frame pop on the other side.
 */
export const resolveRetinalAfterimageVisibility = (
  currentVisibility: number,
  charge: number,
  directGaze: boolean,
  awayLongEnough: boolean,
  deltaSeconds: number,
): number => {
  if (directGaze) return clamp(currentVisibility, 0, 1);
  const target = awayLongEnough && charge > 0.035 ? 1 : 0;
  return clamp(
    currentVisibility + (target - currentVisibility) *
      (1 - Math.exp(-3.4 * Math.max(0, deltaSeconds))),
    0,
    1,
  );
};

/** Capture a new retinal location only after the previous mark has cleared. */
export const canCaptureRetinalAfterimageCentre = (
  charge: number,
  visibility: number,
): boolean => charge <= 0.035 && visibility <= 0.035;

/** Cool, non-retaining exposure lift around Sirion's visible surface. */
export const resolveSirionGazeProximity = (alignment: number): number =>
  smoothstep(
    Math.cos(SIRION_GAZE_OUTER_ANGLE),
    Math.cos(SIRION_GAZE_INNER_ANGLE),
    clamp(alignment, -1, 1),
  );

export interface SunOcclusionOptics {
  /** Weak radial shafts are strongest while the disc is partly covered. */
  shaftStrength: number;
  /** Normalized view-local exposure reduction; never affects world lights. */
  viewDimming: number;
}

export const resolveSunOcclusionOptics = (
  terrainVisibility: number,
  objectVisibility: number,
): SunOcclusionOptics => {
  const visibility = clamp(terrainVisibility, 0, 1) *
    clamp(objectVisibility, 0, 1);
  const occlusion = 1 - visibility;
  return {
    shaftStrength:
      smoothstep(0.06, 0.28, occlusion) *
      (1 - smoothstep(0.82, 0.98, occlusion)),
    // Peripheral foliage must not darken the frame before it actually covers
    // a meaningful part of the solar disc. The visible corona reacts first;
    // camera exposure starts after roughly one fifth and then follows area.
    viewDimming: smoothstep(0.22, 0.94, occlusion),
  };
};

/**
 * Fraction of a celestial disc covered by a circular projected occluder.
 * The tiny angular circles are evaluated as a 2D lens: this is both cheaper
 * and much more precise than a wide world-space cylinder around every tree.
 */
export const resolveCelestialDiscOcclusion = (
  angularSeparation: number,
  celestialAngularRadius: number,
  occluderAngularRadius: number,
): number => {
  const distance = Math.max(0, angularSeparation);
  const celestialRadius = Math.max(0.000_001, celestialAngularRadius);
  const occluderRadius = Math.max(0, occluderAngularRadius);
  if (occluderRadius <= 0 || distance >= celestialRadius + occluderRadius) {
    return 0;
  }
  if (distance <= Math.abs(occluderRadius - celestialRadius)) {
    return occluderRadius >= celestialRadius
      ? 1
      : clamp(
          (occluderRadius * occluderRadius) /
            (celestialRadius * celestialRadius),
          0,
          1,
        );
  }
  const separationSquared = distance * distance;
  const celestialSquared = celestialRadius * celestialRadius;
  const occluderSquared = occluderRadius * occluderRadius;
  const celestialAngle = Math.acos(clamp(
    (separationSquared + celestialSquared - occluderSquared) /
      (2 * distance * celestialRadius),
    -1,
    1,
  ));
  const occluderAngle = Math.acos(clamp(
    (separationSquared + occluderSquared - celestialSquared) /
      (2 * distance * occluderRadius),
    -1,
    1,
  ));
  const lensHeight = 0.5 * Math.sqrt(Math.max(
    0,
    (-distance + celestialRadius + occluderRadius) *
      (distance + celestialRadius - occluderRadius) *
      (distance - celestialRadius + occluderRadius) *
      (distance + celestialRadius + occluderRadius),
  ));
  const overlapArea = celestialSquared * celestialAngle +
    occluderSquared * occluderAngle - lensHeight;
  return clamp(overlapArea / (Math.PI * celestialSquared), 0, 1);
};

/**
 * Project an oriented ellipsoid onto the radial line between it and a
 * celestial disc. This is a compact silhouette approximation for foliage
 * tiers and low-poly rocks: unlike a bounding sphere, vertical height cannot
 * make an asset start covering the sun early at its left or right edge (and
 * vice versa).
 */
export const resolveProjectedEllipsoidDiscOcclusion = (
  origin: Readonly<{ x: number; y: number; z: number }>,
  celestialDirection: Readonly<{ x: number; y: number; z: number }>,
  celestialAngularRadius: number,
  centre: Readonly<{ x: number; y: number; z: number }>,
  halfSize: Readonly<{ x: number; y: number; z: number }>,
  yawRadians = 0,
): number => {
  const toX = centre.x - origin.x;
  const toY = centre.y - origin.y;
  const toZ = centre.z - origin.z;
  const distance = Math.hypot(toX, toY, toZ);
  if (distance <= 0.0001) return 1;
  const directionLength = Math.max(
    0.0001,
    Math.hypot(
      celestialDirection.x,
      celestialDirection.y,
      celestialDirection.z,
    ),
  );
  const sunX = celestialDirection.x / directionLength;
  const sunY = celestialDirection.y / directionLength;
  const sunZ = celestialDirection.z / directionLength;
  const objectX = toX / distance;
  const objectY = toY / distance;
  const objectZ = toZ / distance;
  const alignment = clamp(
    objectX * sunX + objectY * sunY + objectZ * sunZ,
    -1,
    1,
  );
  if (alignment <= 0) return 0;
  const angularSeparation = Math.acos(alignment);

  // Direction of separation on the celestial tangent plane. At exact centre
  // there is no unique radial direction, so use the largest projected axis;
  // only the contained/full-cover branch is relevant in that case.
  let tangentX = objectX - sunX * alignment;
  let tangentY = objectY - sunY * alignment;
  let tangentZ = objectZ - sunZ * alignment;
  const tangentLength = Math.hypot(tangentX, tangentY, tangentZ);
  let projectedHalfExtent: number;
  if (tangentLength <= 0.000001) {
    projectedHalfExtent = Math.max(
      Math.abs(halfSize.x),
      Math.abs(halfSize.y),
      Math.abs(halfSize.z),
    );
  } else {
    tangentX /= tangentLength;
    tangentY /= tangentLength;
    tangentZ /= tangentLength;
    const cosYaw = Math.cos(yawRadians);
    const sinYaw = Math.sin(yawRadians);
    const localTangentX = tangentX * cosYaw - tangentZ * sinYaw;
    const localTangentZ = tangentX * sinYaw + tangentZ * cosYaw;
    projectedHalfExtent = Math.sqrt(
      (localTangentX * halfSize.x) ** 2 +
      (tangentY * halfSize.y) ** 2 +
      (localTangentZ * halfSize.z) ** 2,
    );
  }
  const angularHalfExtent = Math.asin(clamp(
    projectedHalfExtent / distance,
    0,
    1,
  ));
  return resolveCelestialDiscOcclusion(
    angularSeparation,
    celestialAngularRadius,
    angularHalfExtent,
  );
};

/**
 * A close asset produces a shaft glint only while its edge is crossing the
 * solar disc. A static partly covered sun therefore settles back to normal
 * instead of leaving a permanent godray overlay throughout a forest.
 */
export const resolveSunOcclusionEdgePulse = (
  previousVisibility: number,
  nextVisibility: number,
): number => {
  const previous = clamp(previousVisibility, 0, 1);
  const next = clamp(nextVisibility, 0, 1);
  const edgeCrossing = smoothstep(0.03, 0.12, Math.abs(next - previous));
  const partialCover = smoothstep(0.04, 0.22, next) *
    (1 - smoothstep(0.78, 0.97, next));
  return edgeCrossing * partialCover;
};

export type CelestialTerrainHeightSampler = (
  x: number,
  z: number,
) => number;

/**
 * Optional close-range optical occlusion. Terrain owns the horizon test;
 * gameplay systems can cheaply describe nearby trees, rocks and structures
 * without raycasting the complete rendered scene.
 */
export type CelestialObjectOcclusionSampler = (
  origin: Readonly<{ x: number; y: number; z: number }>,
  celestialDirection: Readonly<{ x: number; y: number; z: number }>,
  celestialAngularRadius?: number,
) => number;

/**
 * Angular elevation of the highest terrain silhouette in one celestial
 * azimuth. Unlike a visibility percentage this is a stable world-space line:
 * as a disc descends, the same horizon continues cutting it at the same
 * screen elevation.
 */
export const resolveTerrainCelestialHorizonElevation = (
  origin: Readonly<{ x: number; y: number; z: number }>,
  celestialDirection: Readonly<{ x: number; y: number; z: number }>,
  sampleHeight: CelestialTerrainHeightSampler | undefined,
  farDistance = VISIBLE_CELESTIAL_HORIZON_FAR_DISTANCE,
): number => {
  if (!sampleHeight) return 0;
  const horizontalLength = Math.hypot(
    celestialDirection.x,
    celestialDirection.z,
  );
  if (horizontalLength <= 0.0001) return 0;
  const directionX = celestialDirection.x / horizontalLength;
  const directionZ = celestialDirection.z / horizontalLength;
  let terrainHorizon = 0;
  const distanceRatio =
    Math.max(SUN_HORIZON_NEAR_DISTANCE, farDistance) /
    SUN_HORIZON_NEAR_DISTANCE;
  for (let index = 0; index < SUN_HORIZON_SAMPLE_COUNT; index += 1) {
    const progress = index / Math.max(1, SUN_HORIZON_SAMPLE_COUNT - 1);
    const distance = SUN_HORIZON_NEAR_DISTANCE *
      Math.pow(distanceRatio, progress);
    const height = sampleHeight(
      origin.x + directionX * distance,
      origin.z + directionZ * distance,
    );
    if (!Number.isFinite(height)) continue;
    terrainHorizon = Math.max(
      terrainHorizon,
      Math.atan2(height + 0.08 - origin.y, distance),
    );
  }
  return terrainHorizon;
};

/**
 * Resolves whether the centre of an infinitely distant sun clears the actual
 * terrain horizon. Samples are logarithmic so a nearby ridge and a far
 * mountain both get useful precision without a per-frame scene raycast.
 */
export const resolveTerrainCelestialVisibility = (
  origin: Readonly<{ x: number; y: number; z: number }>,
  celestialDirection: Readonly<{ x: number; y: number; z: number }>,
  sampleHeight: CelestialTerrainHeightSampler | undefined,
  angularRadius = SUN_DISC_ANGULAR_RADIUS,
  farDistance = VISIBLE_CELESTIAL_HORIZON_FAR_DISTANCE,
): number => {
  const elevation = Math.asin(clamp(celestialDirection.y, -1, 1));
  if (elevation <= -angularRadius) return 0;
  if (!sampleHeight) {
    return smoothstep(
      -angularRadius,
      angularRadius,
      elevation,
    );
  }
  const terrainHorizon = resolveTerrainCelestialHorizonElevation(
    origin,
    celestialDirection,
    sampleHeight,
    farDistance,
  );
  return smoothstep(
    terrainHorizon - angularRadius * 1.15,
    terrainHorizon + angularRadius * 1.15,
    elevation,
  );
};

/** Backwards-compatible solar specialization used by existing tests/tools. */
export const resolveTerrainSunVisibility = (
  origin: Readonly<{ x: number; y: number; z: number }>,
  sunDirection: Readonly<{ x: number; y: number; z: number }>,
  sampleHeight: CelestialTerrainHeightSampler | undefined,
): number => resolveTerrainCelestialVisibility(
  origin,
  sunDirection,
  sampleHeight,
  SUN_DISC_ANGULAR_RADIUS,
);

/**
 * Keeps every remaining stellar fragment fully luminous until the final edge
 * crosses the geometric horizon. Actual terrain/asset depth clips the disc
 * spatially; a scalar fade would incorrectly make the complete star ghostly.
 */
export const resolveCelestialDiscPresence = (
  elevationRadians: number,
  angularRadius: number,
): number => elevationRadians > -Math.max(0, angularRadius) ? 1 : 0;

const fract = (value: number): number => value - Math.floor(value);

const skyHash = (x: number, y: number): number => {
  let pointX = fract(x * 123.34);
  let pointY = fract(y * 456.21);
  const offset = pointX * (pointX + 45.32) +
    pointY * (pointY + 45.32);
  pointX += offset;
  pointY += offset;
  return fract(pointX * pointY);
};

const skyNoise = (x: number, y: number): number => {
  const cellX = Math.floor(x);
  const cellY = Math.floor(y);
  const localX = fract(x);
  const localY = fract(y);
  const blendX = localX * localX * (3 - 2 * localX);
  const blendY = localY * localY * (3 - 2 * localY);
  const near = skyHash(cellX, cellY) * (1 - blendX) +
    skyHash(cellX + 1, cellY) * blendX;
  const far = skyHash(cellX, cellY + 1) * (1 - blendX) +
    skyHash(cellX + 1, cellY + 1) * blendX;
  return near * (1 - blendY) + far * blendY;
};

/** Mirrors the authored sky shader at the sun direction for direct lighting. */
export const resolveProceduralSunCloudTransmission = (
  sunDirection: Readonly<{ x: number; y: number; z: number }>,
  worldTime: number,
  cloudOpacity: number,
  windDirection: Readonly<{ x: number; z: number }> = { x: 1, z: 0 },
  windGust = 0.35,
  viewerPosition: Readonly<{ x: number; y: number; z: number }> = {
    x: 0,
    y: 0,
    z: 0,
  },
  integratedCloudOffset?: Readonly<{ x: number; z: number }>,
): number => {
  const opacity = clamp(cloudOpacity, 0, 1);
  if (opacity <= 0.001) return 1;
  const directionV = Math.asin(clamp(sunDirection.y, -1, 1)) /
    Math.PI + 0.5;
  const skyV = 0.52 + Math.abs(directionV - 0.5) * 0.5;
  const windLength = Math.max(
    0.0001,
    Math.hypot(windDirection.x, windDirection.z),
  );
  const windX = windDirection.x / windLength;
  const windZ = windDirection.z / windLength;
  const travel = Math.max(0, worldTime) *
    (0.0028 + clamp(windGust, 0, 1) * 0.0016);
  const cloudOffsetX = integratedCloudOffset?.x ?? windX * travel;
  const cloudOffsetZ = integratedCloudOffset?.z ?? windZ * travel;
  // Direction-vector coordinates join exactly at the panorama wrap. The old
  // 0..1 azimuth noise sampled unrelated values at its two ends, producing a
  // vertical sky seam and clouds that appeared to split east and west.
  // Keep the optical layer continuous through the horizon. A hard clamp made
  // the veil snap and swell on the exact frame Aerion crossed this altitude.
  const cloudRayY = Math.hypot(Math.max(0, sunDirection.y), 0.055);
  const cloudDistance = Math.max(0, (980 - viewerPosition.y) / cloudRayY);
  const cloudWorldX = (viewerPosition.x + sunDirection.x * cloudDistance) *
    0.00105;
  const cloudWorldZ = (viewerPosition.z + sunDirection.z * cloudDistance) *
    0.00105;
  // Translation moves the bank; these two very slow, bounded offsets let its
  // vapour condense and erode in place. Keeping them independent from gust
  // direction prevents the solar wisps from looking like a static stencil.
  const evolutionX = Math.sin(worldTime * 0.0043) * 0.16 +
    Math.sin(worldTime * 0.0017 + 1.9) * 0.07;
  const evolutionZ = Math.cos(worldTime * 0.0037 + 0.6) * 0.15 +
    Math.sin(worldTime * 0.0013 + 3.1) * 0.06;
  const broadX = cloudWorldX * 2.55 - cloudOffsetX + skyV * 0.34 +
    evolutionX;
  const broadZ = cloudWorldZ * 2.55 - cloudOffsetZ - skyV * 0.27 +
    evolutionZ;
  const broad = skyNoise(broadX, broadZ);
  const detail = skyNoise(
    cloudWorldX * 6.9 - cloudOffsetX * 1.18 + skyV * 0.71 +
      evolutionX * 1.73,
    cloudWorldZ * 6.9 - cloudOffsetZ * 1.18 - skyV * 0.58 +
      evolutionZ * 1.61,
  );
  const wisps = skyNoise(
    cloudWorldX * 13.8 - cloudOffsetX * 1.42 - skyV * 0.91 +
      evolutionX * 2.47,
    cloudWorldZ * 13.8 - cloudOffsetZ * 1.42 + skyV * 0.83 +
      evolutionZ * 2.31,
  );
  const wispLife = 0.86 + Math.sin(
    worldTime * 0.011 + cloudWorldX * 1.7 - cloudWorldZ * 1.3,
  ) * 0.14;
  const condensate = Math.sin(
    worldTime * 0.0067 + cloudWorldX * 2.1 + cloudWorldZ * 1.4,
  ) * 0.018;
  const cloudField = broad * 0.61 + detail * 0.27 +
    wisps * 0.12 * wispLife + condensate;
  const cloudCoreShape = smoothstep(0.5, 0.585, cloudField);
  const cloudExtendedShape = smoothstep(0.37, 0.49, cloudField);
  const cloudShape = lerp(
    cloudCoreShape,
    Math.max(cloudCoreShape, cloudExtendedShape),
    smoothstep(0.16, 0.9, opacity),
  );
  const cloudBand = smoothstep(0.49, 0.58, skyV);
  const localOcclusion = cloudShape * cloudBand * opacity;
  const overcastOcclusion = smoothstep(0.72, 0.92, opacity) * 0.96;
  return clamp(
    (1 - overcastOcclusion) * (1 - localOcclusion * 0.97),
    0.025,
    1,
  );
};

