import type { EmergentWorldRegistry } from './EmergentWorldRegistry';
import type {
  AccessConditionStatus,
  MobilityProfileDefinition,
  RoadConditionState,
  RoadSurfaceObservation,
} from './EmergentWorldTypes';

export interface RoadConditionTransition {
  segmentId: string;
  previousStatus: AccessConditionStatus;
  status: AccessConditionStatus;
  occurredAt: number;
  state: RoadConditionState;
}

export interface RoadTraversalAssessment {
  traversable: boolean;
  status: AccessConditionStatus;
  costMultiplier: number;
  speedMultiplier: number;
  reason: string;
}

interface RoadConditionSaveData {
  version: 1;
  states: RoadConditionState[];
}

const cloneState = (state: Readonly<RoadConditionState>): RoadConditionState => ({
  ...state,
  impediments: [...state.impediments],
});

export class RoadConditionSystem {
  private readonly states = new Map<string, RoadConditionState>();

  public constructor(
    private readonly registry: EmergentWorldRegistry,
    saved?: unknown,
  ) {
    for (const definition of registry.definitions.roadSegments) {
      this.states.set(definition.id, {
        segmentId: definition.id,
        status: 'UNKNOWN',
        previousStatus: 'UNKNOWN',
        stateChangedAt: 0,
        revision: 0,
        measuredAt: 0,
        sourceRevision: -1,
        sampleCount: 0,
        averageDepth: 0,
        maximumDepth: 0,
        deepSampleRatio: 0,
        impediments: [],
      });
    }
    this.importState(saved);
  }

  public update(
    simulationTime: number,
    observations: readonly RoadSurfaceObservation[],
  ): readonly RoadConditionTransition[] {
    const transitions: RoadConditionTransition[] = [];
    for (const observation of [...observations].sort((a, b) => a.segmentId.localeCompare(b.segmentId))) {
      const definition = this.registry.getRoad(observation.segmentId);
      const state = this.states.get(observation.segmentId);
      if (!definition || !state || observation.measuredAt < state.measuredAt) continue;
      if (
        observation.sourceRevision === state.sourceRevision &&
        observation.measuredAt === state.measuredAt
      ) continue;
      Object.assign(state, observation, { impediments: [...observation.impediments] });
      const candidate = this.resolveStatus(state.status, observation, definition.condition);
      if (candidate === state.status) {
        state.pendingStatus = undefined;
        state.pendingSince = undefined;
        continue;
      }
      if (state.status === 'UNKNOWN') {
        transitions.push(this.applyStatus(state, candidate, simulationTime));
        continue;
      }
      if (state.pendingStatus !== candidate) {
        state.pendingStatus = candidate;
        state.pendingSince = simulationTime;
        if (definition.condition.stableSeconds === 0) {
          transitions.push(this.applyStatus(state, candidate, simulationTime));
        }
        continue;
      }
      if (simulationTime - (state.pendingSince ?? simulationTime) >= definition.condition.stableSeconds) {
        transitions.push(this.applyStatus(state, candidate, simulationTime));
      }
    }
    return transitions;
  }

  public getState(segmentId: string): RoadConditionState | undefined {
    const state = this.states.get(segmentId);
    return state ? cloneState(state) : undefined;
  }

  public getStates(): readonly RoadConditionState[] {
    return [...this.states.values()].sort((a, b) => a.segmentId.localeCompare(b.segmentId)).map(cloneState);
  }

  public getStateCount(): number { return this.states.size; }

  public assess(
    segmentId: string,
    profile: Readonly<MobilityProfileDefinition>,
  ): RoadTraversalAssessment {
    const definition = this.registry.getRoad(segmentId);
    const state = this.states.get(segmentId);
    if (!definition || !state) {
      return { traversable: false, status: 'UNKNOWN', costMultiplier: 99, speedMultiplier: 0, reason: 'UNKNOWN_SEGMENT' };
    }
    if (!definition.mobilityClasses.includes(profile.mobilityClass)) {
      return { traversable: false, status: state.status, costMultiplier: 99, speedMultiplier: 0, reason: 'MOBILITY_CLASS_UNSUPPORTED' };
    }
    if (profile.mobilityClass === 'AIRCRAFT') {
      return { traversable: true, status: state.status, costMultiplier: 1, speedMultiplier: 1, reason: 'AIRBORNE' };
    }
    if (state.status === 'UNKNOWN') {
      return { traversable: false, status: state.status, costMultiplier: 99, speedMultiplier: 0, reason: 'NO_SURFACE_OBSERVATION' };
    }
    const depthRatio = profile.maximumSnowDepth > 0
      ? state.averageDepth / profile.maximumSnowDepth
      : Number.POSITIVE_INFINITY;
    const traversable =
      // A short local drift may sit slightly above nominal axle clearance
      // while the lane remains usable; average depth still guards the whole
      // route. This also prevents one 25 cm sample at a plow-bank edge from
      // invalidating an otherwise continuous vehicle track.
      state.maximumDepth <= profile.maximumSnowDepth * 1.2 &&
      state.averageDepth <= profile.maximumSnowDepth;
    const speedMultiplier = traversable
      ? 1 - Math.min(1, depthRatio) * (1 - profile.deepSnowSpeedMultiplier)
      : 0;
    return {
      traversable,
      status: state.status,
      costMultiplier: traversable ? 1 / Math.max(0.05, speedMultiplier) : 99,
      speedMultiplier,
      reason: traversable ? (depthRatio > 0.55 ? 'DEEP_SNOW_SLOWDOWN' : 'PASSABLE') : 'SNOW_TOO_DEEP',
    };
  }

  public exportState(): RoadConditionSaveData {
    return { version: 1, states: this.getStates().map(cloneState) };
  }

  private importState(saved: unknown): boolean {
    const candidate = saved as Partial<RoadConditionSaveData> | undefined;
    if (candidate?.version !== 1 || !Array.isArray(candidate.states)) return false;
    for (const state of candidate.states) {
      if (!this.registry.getRoad(state?.segmentId) || !['UNKNOWN', 'OPEN', 'DEGRADED', 'BLOCKED'].includes(state.status)) continue;
      this.states.set(state.segmentId, cloneState(state));
    }
    return true;
  }

  private resolveStatus(
    current: AccessConditionStatus,
    observation: Readonly<RoadSurfaceObservation>,
    threshold: Readonly<{ degradedAverageDepth: number; blockedAverageDepth: number; blockedMaximumDepth: number; reopenAverageDepth: number }>,
  ): AccessConditionStatus {
    if (current === 'BLOCKED' && observation.averageDepth > threshold.reopenAverageDepth) return 'BLOCKED';
    if (current === 'DEGRADED' && observation.averageDepth > threshold.reopenAverageDepth) {
      return observation.averageDepth >= threshold.blockedAverageDepth || observation.maximumDepth >= threshold.blockedMaximumDepth
        ? 'BLOCKED'
        : 'DEGRADED';
    }
    if (
      observation.averageDepth >= threshold.blockedAverageDepth ||
      observation.maximumDepth >= threshold.blockedMaximumDepth ||
      observation.deepSampleRatio >= 0.42
    ) return 'BLOCKED';
    if (observation.averageDepth >= threshold.degradedAverageDepth) return 'DEGRADED';
    return 'OPEN';
  }

  private applyStatus(
    state: RoadConditionState,
    status: AccessConditionStatus,
    simulationTime: number,
  ): RoadConditionTransition {
    const previousStatus = state.status;
    state.previousStatus = previousStatus;
    state.status = status;
    state.stateChangedAt = simulationTime;
    state.pendingStatus = undefined;
    state.pendingSince = undefined;
    state.revision += 1;
    return { segmentId: state.segmentId, previousStatus, status, occurredAt: simulationTime, state: cloneState(state) };
  }
}
