import {
  AnimationClip,
  AnimationMixer,
  Box3,
  Group,
  InterpolateDiscrete,
  InterpolateSmooth,
  Mesh,
  SkinnedMesh,
  Vector3,
  type Object3D,
} from 'three';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js';
import {
  HOODED_ADVENTURER_DEFAULT_POSE_ID,
  HOODED_ADVENTURER_MODEL_URL,
  hoodedAdventurerAnimation,
  type HoodedAdventurerAnimationId,
} from './HoodedAdventurerAnimationCatalog';

export const HOODED_ADVENTURER_TARGET_HEIGHT_METRES = 1.72;

const horizontalRootTrack = /(?:^|[:|])mixamorigHips\.position$/i;

export const resolveHoodedAdventurerAssetUrl = (
  relativeUrl: string,
  baseUri = typeof document === 'undefined' ? undefined : document.baseURI,
): string => baseUri ? new URL(relativeUrl, baseUri).href : relativeUrl;

/**
 * Controller-owned movement with animation-owned vertical motion. Mixamo
 * walk/run files contain roughly 0.9–1.8 metres of forward translation; if
 * retained, the rendered character would slide away from its authoritative
 * gameplay position every loop.
 */
export const prepareHoodedAdventurerClip = (
  source: Readonly<AnimationClip>,
  id: HoodedAdventurerAnimationId,
): AnimationClip => {
  const clip = source.clone();
  clip.name = id;
  for (const track of clip.tracks) {
    if (!horizontalRootTrack.test(track.name) || track.values.length < 3) continue;
    const firstX = track.values[0] ?? 0;
    const firstZ = track.values[2] ?? 0;
    for (let offset = 0; offset < track.values.length; offset += 3) {
      track.values[offset] = firstX;
      track.values[offset + 2] = firstZ;
    }
  }
  clip.resetDuration();
  clip.optimize();
  return clip;
};

/**
 * Produces a stable one-frame pose without borrowing a carry/held-item idle.
 * This is intentionally temporary until a dedicated relaxed idle is added.
 */
export const createHoodedAdventurerStaticPoseClip = (
  source: Readonly<AnimationClip>,
  name: string,
  sampleTimeSeconds = 0,
): AnimationClip => {
  const sampleTime = clampNumber(sampleTimeSeconds, 0, source.duration);
  const tracks = source.tracks.map((track) => {
    const poseTrack = track.clone();
    const sampled = new Float32Array(track.getValueSize());
    const interpolation = track.getInterpolation();
    const interpolant = interpolation === InterpolateDiscrete
      ? track.InterpolantFactoryMethodDiscrete(sampled)
      : interpolation === InterpolateSmooth
        ? track.InterpolantFactoryMethodSmooth(sampled)
        : track.InterpolantFactoryMethodLinear(sampled);
    interpolant.evaluate(sampleTime);
    poseTrack.times = new Float32Array([0]);
    poseTrack.values = sampled;
    return poseTrack;
  });
  return new AnimationClip(name, 1, tracks, source.blendMode);
};

const clampNumber = (value: number, minimum: number, maximum: number): number =>
  Math.max(minimum, Math.min(maximum, value));

export interface HoodedAdventurerModelAsset {
  readonly root: Group;
  readonly visual: Object3D;
  readonly sourceHeight: number;
  readonly scale: number;
  readonly boneNames: ReadonlySet<string>;
  /** Temporary default until a dedicated relaxed idle is imported. */
  readonly initialPoseId: typeof HOODED_ADVENTURER_DEFAULT_POSE_ID;
}

const collectBoneNames = (root: Object3D): ReadonlySet<string> => {
  const names = new Set<string>();
  root.traverse((object) => {
    if (object.type === 'Bone') names.add(object.name);
  });
  return names;
};

export class HoodedAdventurerAnimationLibrary {
  private readonly loader = new FBXLoader();
  private readonly clips = new Map<
    HoodedAdventurerAnimationId,
    Promise<AnimationClip>
  >();

  public async loadModel(): Promise<HoodedAdventurerModelAsset> {
    const [visual, initialPose] = await Promise.all([
      this.loader.loadAsync(resolveHoodedAdventurerAssetUrl(
        HOODED_ADVENTURER_MODEL_URL,
      )),
      this.loadClip(HOODED_ADVENTURER_DEFAULT_POSE_ID),
    ]);

    // The rigged model's bind pose is authored Z-up, while its Mixamo motion
    // clips correctly drive it Y-up. Sampling a compatible first frame avoids
    // a one-frame character lying on its back without rotating every animated
    // pose onto the floor. A later gameplay AnimationMixer can take over these
    // same bone properties normally.
    const poseMixer = new AnimationMixer(visual);
    poseMixer.clipAction(initialPose).play();
    poseMixer.setTime(0);
    visual.updateMatrixWorld(true);
    const sourceBounds = new Box3().setFromObject(visual);
    const sourceSize = sourceBounds.getSize(new Vector3());
    const sourceHeight = Math.max(sourceSize.y, 0.001);
    const scale = HOODED_ADVENTURER_TARGET_HEIGHT_METRES / sourceHeight;
    const root = new Group();
    root.name = 'Hooded adventurer player asset';
    root.scale.setScalar(scale);
    root.add(visual);
    visual.traverse((object) => {
      if (!(object instanceof Mesh || object instanceof SkinnedMesh)) return;
      object.castShadow = true;
      object.receiveShadow = true;
    });
    return {
      root,
      visual,
      sourceHeight,
      scale,
      boneNames: collectBoneNames(visual),
      initialPoseId: HOODED_ADVENTURER_DEFAULT_POSE_ID,
    };
  }

  public loadClip(id: HoodedAdventurerAnimationId): Promise<AnimationClip> {
    const cached = this.clips.get(id);
    if (cached) return cached;
    const definition = hoodedAdventurerAnimation(id);
    const request = this.loader.loadAsync(resolveHoodedAdventurerAssetUrl(
      definition.url,
    )).then((asset) => {
      const source = asset.animations[0];
      if (!source) throw new Error(`${definition.url} contains no animation clip.`);
      return prepareHoodedAdventurerClip(source, id);
    });
    this.clips.set(id, request);
    request.catch(() => this.clips.delete(id));
    return request;
  }

  public async preload(
    ids: readonly HoodedAdventurerAnimationId[],
  ): Promise<ReadonlyMap<HoodedAdventurerAnimationId, AnimationClip>> {
    const entries = await Promise.all(ids.map(async (id) =>
      [id, await this.loadClip(id)] as const));
    return new Map(entries);
  }
}
