import type {
  SurvivalBurnedBuildDebris,
  SurvivalConstructionSnowHeatSource,
} from './SurvivalConstructionState';

const clamp = (value: number, minimum: number, maximum: number): number =>
  Math.max(minimum, Math.min(maximum, value));

export const survivalStructuralFireSnowHeatSource = (options: Readonly<{
  id: string;
  x: number;
  z: number;
  halfWidth: number;
  halfDepth: number;
  coverage: number;
}>): SurvivalConstructionSnowHeatSource => ({
  id: `burning-build:${options.id}`,
  x: options.x,
  z: options.z,
  radius: clamp(
    Math.max(options.halfWidth, options.halfDepth) + 0.85 + options.coverage * 0.7,
    1.15,
    3.2,
  ),
  heat: 0.28 + options.coverage * 0.72,
  impactMeltDepth: 0,
});

export const survivalBurnedDebrisSnowHeatSource = (
  debris: Readonly<SurvivalBurnedBuildDebris>,
  falling: boolean,
): SurvivalConstructionSnowHeatSource | undefined => {
  if (debris.heat <= 0.001 && debris.impactMeltDepth <= 0.0001) return undefined;
  return {
    id: debris.id,
    x: debris.x,
    z: debris.z,
    radius: 1.55 + debris.heat * 1.35,
    heat: falling ? 0 : debris.heat,
    impactMeltDepth: falling ? 0 : debris.impactMeltDepth,
  };
};
