import { clamp, damp, lerp, smoothstep } from '../../utils/math';
import { BOREALIS_PARACHUTE_INTRO } from './BorealisArrivalDefinitions';
import { BOREALIS_WORLD_ANCHORS } from '../../world/BorealisWorldLayout';

export type BorealisArrivalPhase =
  | 'PENDING'
  | 'DESCENDING'
  | 'TOUCHDOWN'
  | 'COMPLETE';

export interface BorealisArrivalSequenceSaveData {
  readonly version: 1;
  readonly phase: BorealisArrivalPhase;
  readonly x: number;
  readonly z: number;
  readonly altitude: number;
  readonly heading: number;
  readonly elapsedSeconds: number;
  readonly offsetX: number;
  readonly offsetZ: number;
  readonly steeringX: number;
  readonly steeringZ: number;
  readonly touchdownSeconds: number;
}

export interface BorealisArrivalSequenceState {
  phase: BorealisArrivalPhase;
  x: number;
  z: number;
  altitude: number;
  heading: number;
  elapsedSeconds: number;
  offsetX: number;
  offsetZ: number;
  touchdownSeconds: number;
  steeringX: number;
  steeringZ: number;
}

export interface BorealisArrivalStepResult {
  readonly startedTouchdown: boolean;
  readonly completed: boolean;
}

const ENTRY = BOREALIS_WORLD_ANCHORS.dropEntry;
const LANDING = BOREALIS_WORLD_ANCHORS.arrivalLanding;
const ENTRY_ALTITUDE = BOREALIS_PARACHUTE_INTRO.releaseAltitudeMetres;
const DESCENT_SPEED = 4.25;
const TOUCHDOWN_DURATION = 1.65;
const APPROACH_X = LANDING.x - ENTRY.x;
const APPROACH_Z = LANDING.z - ENTRY.z;
const APPROACH_LENGTH = Math.max(0.001, Math.hypot(APPROACH_X, APPROACH_Z));
const APPROACH_FORWARD_X = APPROACH_X / APPROACH_LENGTH;
const APPROACH_FORWARD_Z = APPROACH_Z / APPROACH_LENGTH;
const APPROACH_RIGHT_X = APPROACH_FORWARD_Z;
const APPROACH_RIGHT_Z = -APPROACH_FORWARD_X;
const FORWARD_REACH_METRES =
  BOREALIS_PARACHUTE_INTRO.maximumPlayerDriftMetres * 0.91;
const GUIDED_END = Object.freeze({
  x: LANDING.x - APPROACH_FORWARD_X * FORWARD_REACH_METRES,
  z: LANDING.z - APPROACH_FORWARD_Z * FORWARD_REACH_METRES,
});
const DESCENT_DURATION = ENTRY_ALTITUDE / DESCENT_SPEED;

const shortestAngleDelta = (from: number, to: number): number =>
  Math.atan2(Math.sin(to - from), Math.cos(to - from));

const dampAngle = (
  current: number,
  target: number,
  smoothing: number,
  deltaSeconds: number,
): number => current + shortestAngleDelta(current, target) *
  (1 - Math.exp(-smoothing * deltaSeconds));

const defaultState = (): BorealisArrivalSequenceState => ({
  phase: 'PENDING',
  x: ENTRY.x,
  z: ENTRY.z,
  altitude: ENTRY_ALTITUDE,
  heading: ENTRY.heading,
  elapsedSeconds: 0,
  offsetX: 0,
  offsetZ: 0,
  touchdownSeconds: 0,
  steeringX: 0,
  steeringZ: 0,
});

/** Deterministic, renderer-free guided parachute path. */
export class BorealisArrivalSequence {
  public readonly state = defaultState();

  public constructor(saved?: unknown, alreadyCompleted = false) {
    if (alreadyCompleted) {
      this.completeImmediately();
      return;
    }
    this.importState(saved);
  }

  public isActive(): boolean {
    return this.state.phase === 'DESCENDING' ||
      this.state.phase === 'TOUCHDOWN';
  }

  public isPending(): boolean {
    return this.state.phase === 'PENDING';
  }

  public start(): boolean {
    if (!this.isPending()) return false;
    Object.assign(this.state, defaultState(), { phase: 'DESCENDING' });
    return true;
  }

  public skip(): boolean {
    if (
      this.state.phase !== 'DESCENDING' ||
      this.state.elapsedSeconds < BOREALIS_PARACHUTE_INTRO.skippableAfterSeconds
    ) return false;
    this.state.x = LANDING.x;
    this.state.z = LANDING.z;
    this.state.altitude = 0.18;
    this.state.phase = 'TOUCHDOWN';
    this.state.touchdownSeconds = 0;
    return true;
  }

  public step(
    deltaSeconds: number,
    input: Readonly<{ right: number; forward: number }>,
    wind: Readonly<{ x: number; z: number; strength: number }>,
  ): BorealisArrivalStepResult {
    const delta = clamp(deltaSeconds, 0, 0.05);
    if (delta <= 0 || !this.isActive()) {
      return { startedTouchdown: false, completed: false };
    }
    const state = this.state;
    state.elapsedSeconds += delta;
    if (state.phase === 'TOUCHDOWN') {
      state.touchdownSeconds += delta;
      state.altitude = Math.max(0, 0.18 * (1 - state.touchdownSeconds / TOUCHDOWN_DURATION));
      state.steeringX = damp(state.steeringX, 0, 8, delta);
      state.steeringZ = damp(state.steeringZ, 0, 8, delta);
      if (state.touchdownSeconds >= TOUCHDOWN_DURATION) {
        this.completeAtTouchdown();
        return { startedTouchdown: false, completed: true };
      }
      return { startedTouchdown: false, completed: false };
    }

    const right = clamp(input.right, -1, 1);
    const forward = clamp(input.forward, -1, 1);
    state.steeringX = damp(state.steeringX, right, 5.5, delta);
    state.steeringZ = damp(state.steeringZ, forward, 5.5, delta);
    // A full-duration forward input supplies almost exactly the remaining
    // reach to the square. Neutral or sideways input still lands safely in a
    // generous 20-30 metre arrival area instead of being corrected away near
    // the ground.
    const offsetSpeed =
      BOREALIS_PARACHUTE_INTRO.maximumPlayerDriftMetres /
      DESCENT_DURATION *
      1.08 *
      BOREALIS_PARACHUTE_INTRO.playerSteeringWeight;
    state.offsetX += (
      state.steeringX * APPROACH_RIGHT_X +
      state.steeringZ * APPROACH_FORWARD_X
    ) * offsetSpeed * delta;
    state.offsetZ += (
      state.steeringX * APPROACH_RIGHT_Z +
      state.steeringZ * APPROACH_FORWARD_Z
    ) * offsetSpeed * delta;
    const offsetLength = Math.hypot(state.offsetX, state.offsetZ);
    if (offsetLength > BOREALIS_PARACHUTE_INTRO.maximumPlayerDriftMetres) {
      const scale = BOREALIS_PARACHUTE_INTRO.maximumPlayerDriftMetres / offsetLength;
      state.offsetX *= scale;
      state.offsetZ *= scale;
    }

    const previousX = state.x;
    const previousZ = state.z;
    state.altitude = Math.max(0, state.altitude - DESCENT_SPEED * delta);
    const descentProgress = 1 - state.altitude / ENTRY_ALTITUDE;
    const routeProgress = smoothstep(0, 1, descentProgress);
    const guidance = smoothstep(0.38, 0.96, routeProgress) *
      BOREALIS_PARACHUTE_INTRO.guidanceWeightNearGround;
    const freedom = 1 - guidance;
    const baseX = lerp(ENTRY.x, GUIDED_END.x, routeProgress);
    const baseZ = lerp(ENTRY.z, GUIDED_END.z, routeProgress);
    const windStrength = clamp((wind.strength - 0.35) / 1.2, 0, 1);
    const windSway = Math.sin(state.elapsedSeconds * 0.52) * windStrength *
      Math.min(2.6, state.altitude * 0.035);
    let targetX = baseX + state.offsetX * freedom + wind.x * windSway;
    let targetZ = baseZ + state.offsetZ * freedom + wind.z * windSway;
    if (routeProgress > 0.86) {
      const landingDeltaX = targetX - LANDING.x;
      const landingDeltaZ = targetZ - LANDING.z;
      const landingDistance = Math.hypot(landingDeltaX, landingDeltaZ);
      const safeRadius = BOREALIS_PARACHUTE_INTRO.guidedLandingRadiusMetres;
      if (landingDistance > safeRadius) {
        const scale = safeRadius / Math.max(0.001, landingDistance);
        targetX = LANDING.x + landingDeltaX * scale;
        targetZ = LANDING.z + landingDeltaZ * scale;
      }
    }
    state.x = damp(state.x, targetX, 2.8 + guidance * 3.8, delta);
    state.z = damp(state.z, targetZ, 2.8 + guidance * 3.8, delta);
    const velocityX = state.x - previousX;
    const velocityZ = state.z - previousZ;
    if (Math.hypot(velocityX, velocityZ) > 0.0001) {
      const desiredHeading = Math.atan2(velocityX, velocityZ);
      state.heading = dampAngle(state.heading, desiredHeading, 5, delta);
    }

    if (state.altitude <= 0.18) {
      state.phase = 'TOUCHDOWN';
      state.touchdownSeconds = 0;
      return { startedTouchdown: true, completed: false };
    }
    return { startedTouchdown: false, completed: false };
  }

  public normalizedDescent(): number {
    return clamp(1 - this.state.altitude / ENTRY_ALTITUDE, 0, 1);
  }

  public cameraZoom(): number {
    const progress = smoothstep(0.02, 0.94, this.normalizedDescent());
    return lerp(1.42, 3.15, progress);
  }

  public cameraFocusAltitude(): number {
    // Follow the airborne character, not a point between the character and
    // the ground. The previous fractional altitude placed the actor dozens of
    // metres outside the orthographic view at the beginning of the jump.
    return this.state.altitude + 0.15;
  }

  public exportState(): BorealisArrivalSequenceSaveData {
    const state = this.state;
    return {
      version: 1,
      phase: state.phase,
      x: state.x,
      z: state.z,
      altitude: state.altitude,
      heading: state.heading,
      elapsedSeconds: state.elapsedSeconds,
      offsetX: state.offsetX,
      offsetZ: state.offsetZ,
      steeringX: state.steeringX,
      steeringZ: state.steeringZ,
      touchdownSeconds: state.touchdownSeconds,
    };
  }

  /** Used by completed saves and explicit playtest travel that bypasses intro. */
  public completeImmediately(): void {
    Object.assign(this.state, {
      phase: 'COMPLETE',
      x: LANDING.x,
      z: LANDING.z,
      altitude: 0,
      heading: ENTRY.heading,
      offsetX: 0,
      offsetZ: 0,
      touchdownSeconds: TOUCHDOWN_DURATION,
      steeringX: 0,
      steeringZ: 0,
    });
  }

  private completeAtTouchdown(): void {
    Object.assign(this.state, {
      phase: 'COMPLETE',
      altitude: 0,
      touchdownSeconds: TOUCHDOWN_DURATION,
      steeringX: 0,
      steeringZ: 0,
    });
  }

  private importState(saved: unknown): boolean {
    const value = saved as Partial<BorealisArrivalSequenceSaveData> | undefined;
    if (
      value?.version !== 1 ||
      !['PENDING', 'DESCENDING', 'TOUCHDOWN', 'COMPLETE'].includes(value.phase ?? '') ||
      ![value.x, value.z, value.altitude, value.heading, value.elapsedSeconds,
        value.offsetX, value.offsetZ, value.steeringX, value.steeringZ,
        value.touchdownSeconds]
        .every(Number.isFinite)
    ) return false;
    Object.assign(this.state, {
      phase: value.phase!,
      x: value.x!,
      z: value.z!,
      altitude: clamp(value.altitude!, 0, ENTRY_ALTITUDE),
      heading: value.heading!,
      elapsedSeconds: Math.max(0, value.elapsedSeconds!),
      offsetX: value.offsetX!,
      offsetZ: value.offsetZ!,
      steeringX: value.steeringX!,
      steeringZ: value.steeringZ!,
      touchdownSeconds: Math.max(0, value.touchdownSeconds!),
    });
    return true;
  }
}
