export const selectBorealisMartaConversationId = (
  arrivalState?: Readonly<StoryQuestRuntimeState>,
): string => arrivalState?.status === 'LOCKED' || !arrivalState
  ? BOREALIS_ARRIVAL_DIALOGUE_ID
  : arrivalState.status === 'ACTIVE' &&
      arrivalState.currentStageId === 'clear-landing-drift'
    ? BOREALIS_MARTA_SHOVEL_CHECK_IN_DIALOGUE_ID
    : arrivalState.status === 'ACTIVE' &&
        arrivalState.currentStageId === 'report-first-shoveling'
      ? BOREALIS_MARTA_EQUIPMENT_BRIEFING_DIALOGUE_ID
      : arrivalState.status === 'ACTIVE' &&
          arrivalState.currentStageId === 'clear-snow-thrower-drift'
        ? BOREALIS_MARTA_SNOW_THROWER_CHECK_IN_DIALOGUE_ID
        : arrivalState.status === 'ACTIVE' &&
            arrivalState.currentStageId === 'report-snow-thrower'
          ? BOREALIS_MARTA_TRACTOR_BRIEFING_DIALOGUE_ID
          : arrivalState.status === 'ACTIVE'
        ? BOREALIS_MARTA_TRACTOR_CHECK_IN_DIALOGUE_ID
        : 'borealis-marta-revival-introduction';

