import type { DefinitionId } from '../../netcode/core/NetworkPrimitives';
import type {
  NormalizedMovementCommand,
  NormalizedToolCommand,
} from '../../netcode/protocol/AuthorityIngress';
import { PLAYER_COMMAND_ACTION } from '../../netcode/protocol/AuthorityIngress';
import type { ReplicatedEntitySnapshot } from '../../netcode/protocol/EntityReplication';
import { ICEWAY_ENTITY_DEFINITIONS } from '../entities/IcewayEntityManifest';
import {
  HELICOPTER_ROTOR_TAKEOFF_SPEED,
  helicopterRotorControlAuthority,
  resolveHelicopterRotorTarget,
  stepHelicopterRotorSpeed,
} from '../../land/HelicopterFlightModel';

export interface ReplicatedKinematicProfile {
  mode: 'CHARACTER' | 'GROUND' | 'AIR' | 'VESSEL' | 'PASSIVE';
  maximumForwardSpeed: number;
  maximumReverseSpeed: number;
  acceleration: number;
  braking: number;
  turnRate: number;
  verticalSpeed: number;
  toolRate: number;
}

/** Controller-neutral command consumed by the one canonical kinematic path. */
export interface ReplicatedEntityCommandInput {
  readonly movement: Readonly<NormalizedMovementCommand>;
  readonly tool: Readonly<NormalizedToolCommand>;
  readonly actionBits: number;
}

const PROFILE_BY_DEFINITION = new Map<DefinitionId, ReplicatedKinematicProfile>([
  [ICEWAY_ENTITY_DEFINITIONS.penguin, {
    mode: 'CHARACTER', maximumForwardSpeed: 2.18, maximumReverseSpeed: 2.18,
    acceleration: 10, braking: 13, turnRate: 10, verticalSpeed: 0, toolRate: 1.4,
  }],
  [ICEWAY_ENTITY_DEFINITIONS.starterDozer, {
    mode: 'GROUND', maximumForwardSpeed: 2.9, maximumReverseSpeed: 1.55,
    acceleration: 2.9, braking: 4.2, turnRate: 0.72, verticalSpeed: 0, toolRate: 0.72,
  }],
  [ICEWAY_ENTITY_DEFINITIONS.heavyDozer, {
    mode: 'GROUND', maximumForwardSpeed: 3.25, maximumReverseSpeed: 1.8,
    acceleration: 2.2, braking: 4.4, turnRate: 0.64, verticalSpeed: 0, toolRate: 0.72,
  }],
  [ICEWAY_ENTITY_DEFINITIONS.wheelLoader, {
    mode: 'GROUND', maximumForwardSpeed: 5.2, maximumReverseSpeed: 3.2,
    acceleration: 1.8, braking: 4.8, turnRate: 0.72, verticalSpeed: 0, toolRate: 0.9,
  }],
  [ICEWAY_ENTITY_DEFINITIONS.snowTruck, {
    mode: 'GROUND', maximumForwardSpeed: 5.2, maximumReverseSpeed: 3.1,
    acceleration: 1.8, braking: 4.5, turnRate: 0.62, verticalSpeed: 0, toolRate: 0,
  }],
  [ICEWAY_ENTITY_DEFINITIONS.helicopter, {
    mode: 'AIR', maximumForwardSpeed: 7.4, maximumReverseSpeed: 7.4,
    acceleration: 2.6, braking: 6, turnRate: 1.45, verticalSpeed: 4.4, toolRate: 0,
  }],
  [ICEWAY_ENTITY_DEFINITIONS.playerIcebreaker, {
    mode: 'VESSEL', maximumForwardSpeed: 1.75, maximumReverseSpeed: 0.82,
    acceleration: 0.42, braking: 0.65, turnRate: 0.38, verticalSpeed: 0, toolRate: 0,
  }],
  [ICEWAY_ENTITY_DEFINITIONS.smallSnowTrailer, {
    mode: 'PASSIVE', maximumForwardSpeed: 0, maximumReverseSpeed: 0,
    acceleration: 0, braking: 8, turnRate: 0, verticalSpeed: 0, toolRate: 0,
  }],
]);

const clamp = (value: number, minimum: number, maximum: number): number =>
  Math.max(minimum, Math.min(maximum, value));
const approach = (current: number, target: number, maximumDelta: number): number =>
  current < target
    ? Math.min(target, current + maximumDelta)
    : Math.max(target, current - maximumDelta);
const damp = (current: number, target: number, response: number, delta: number): number =>
  current + (target - current) * (1 - Math.exp(-response * delta));
const wrapAngle = (angle: number): number => {
  let wrapped = angle;
  while (wrapped > Math.PI) wrapped -= Math.PI * 2;
  while (wrapped < -Math.PI) wrapped += Math.PI * 2;
  return wrapped;
};

export const kinematicProfileFor = (
  definition: DefinitionId,
): Readonly<ReplicatedKinematicProfile> =>
  PROFILE_BY_DEFINITION.get(definition) ?? {
    mode: 'PASSIVE', maximumForwardSpeed: 0, maximumReverseSpeed: 0,
    acceleration: 0, braking: 8, turnRate: 0, verticalSpeed: 0, toolRate: 0,
  };

/**
 * Pure command integrator shared by the headless authority and client
 * prediction. Domain adapters can replace a profile without changing wire DTOs.
 */
export const stepReplicatedEntityCommand = (
  entity: ReplicatedEntitySnapshot,
  command: Readonly<ReplicatedEntityCommandInput> | undefined,
  deltaSeconds: number,
  previousActionBits = 0,
): boolean => {
  const delta = clamp(deltaSeconds, 0, 0.05);
  if (delta <= 0) return false;
  const profile = kinematicProfileFor(entity.definitionId);
  const root = entity.root;
  const before = [
    root.x, root.y, root.z, root.heading, root.pitch, root.roll,
    root.velocityX, root.velocityY, root.velocityZ,
    entity.tool.primaryPosition, entity.tool.secondaryPosition,
    entity.tool.lightsEnabled ? 1 : 0,
    entity.tool.beaconEnabled ? 1 : 0,
  ];
  const movement = command?.movement ?? {
    forward: 0, lateral: 0, steering: 0, yaw: 0, vertical: 0,
  };

  if (profile.mode === 'CHARACTER') {
    // Character movement axes are body-relative at command sampling time.
    // Preserve that movement vector while aim independently turns the body;
    // otherwise mouse aiming would incorrectly turn A/D strafe into forward
    // movement on the authority.
    const movementHeading = root.heading;
    const forwardX = Math.sin(movementHeading);
    const forwardZ = Math.cos(movementHeading);
    const rightX = Math.cos(movementHeading);
    const rightZ = -Math.sin(movementHeading);
    if (movement.aimHeading !== undefined) {
      root.heading += wrapAngle(movement.aimHeading - root.heading) *
        (1 - Math.exp(-profile.turnRate * delta));
    } else if (Math.hypot(movement.forward, movement.lateral) > 0.05) {
      const desired = root.heading + Math.atan2(movement.lateral, movement.forward);
      root.heading += wrapAngle(desired - root.heading) *
        (1 - Math.exp(-profile.turnRate * delta));
    }
    const inputMagnitude = Math.hypot(movement.forward, movement.lateral);
    const normalizedScale = profile.maximumForwardSpeed /
      Math.max(1, inputMagnitude);
    const targetX = (
      forwardX * movement.forward + rightX * movement.lateral
    ) * normalizedScale;
    const targetZ = (
      forwardZ * movement.forward + rightZ * movement.lateral
    ) * normalizedScale;
    root.velocityX = damp(root.velocityX, targetX, movement.forward || movement.lateral ? 10 : 13, delta);
    root.velocityZ = damp(root.velocityZ, targetZ, movement.forward || movement.lateral ? 10 : 13, delta);
  } else if (profile.mode === 'AIR') {
    const rotorTarget = resolveHelicopterRotorTarget(
      root.y,
      entity.tool.primaryPosition,
      movement,
    );
    entity.tool.primaryPosition = stepHelicopterRotorSpeed(
      entity.tool.primaryPosition,
      rotorTarget,
      delta,
    );
    const rotorAuthority = helicopterRotorControlAuthority(
      entity.tool.primaryPosition,
    );
    const flightAuthority = root.y > 0.025 ||
        (movement.vertical > 0.05 &&
          entity.tool.primaryPosition >= HELICOPTER_ROTOR_TAKEOFF_SPEED)
      ? rotorAuthority
      : 0;
    root.heading = wrapAngle(
      root.heading - movement.yaw * profile.turnRate * delta * flightAuthority,
    );
    root.pitch = damp(
      root.pitch,
      movement.forward * 0.24 * flightAuthority,
      4.8,
      delta,
    );
    root.roll = damp(
      root.roll,
      movement.lateral * 0.28 * flightAuthority,
      4.8,
      delta,
    );
    const forwardX = Math.sin(root.heading);
    const forwardZ = Math.cos(root.heading);
    const rightX = Math.cos(root.heading);
    const rightZ = -Math.sin(root.heading);
    // Match the rendered helicopter: its roll sign is visually correct while
    // lateral thrust uses the mirrored movement-space axis.
    const targetX = (forwardX * movement.forward - rightX * movement.lateral) *
      profile.maximumForwardSpeed * flightAuthority;
    const targetZ = (forwardZ * movement.forward - rightZ * movement.lateral) *
      profile.maximumForwardSpeed * flightAuthority;
    root.velocityX = damp(root.velocityX, targetX, movement.forward || movement.lateral ? profile.acceleration : profile.braking, delta);
    root.velocityZ = damp(root.velocityZ, targetZ, movement.forward || movement.lateral ? profile.acceleration : profile.braking, delta);
    root.velocityY = damp(
      root.velocityY,
      movement.vertical * profile.verticalSpeed * flightAuthority,
      movement.vertical ? 3.2 : 6,
      delta,
    );
    root.y = clamp(root.y + root.velocityY * delta, 0, 28);
    if (root.y <= 0) root.velocityY = Math.max(0, root.velocityY);
  } else if (profile.mode === 'GROUND' || profile.mode === 'VESSEL') {
    const currentForward = root.velocityX * Math.sin(root.heading) +
      root.velocityZ * Math.cos(root.heading);
    const maximum = movement.forward >= 0
      ? profile.maximumForwardSpeed
      : profile.maximumReverseSpeed;
    const targetForward = movement.forward * maximum;
    const nextForward = approach(
      currentForward,
      targetForward,
      (Math.abs(movement.forward) > 0.01 ? profile.acceleration : profile.braking) * delta,
    );
    const direction = nextForward >= 0 ? 1 : -1;
    const turnAuthority = clamp(Math.abs(nextForward) / 0.6, 0, 1);
    root.heading = wrapAngle(
      root.heading + movement.steering * direction * turnAuthority * profile.turnRate * delta,
    );
    root.velocityX = Math.sin(root.heading) * nextForward;
    root.velocityZ = Math.cos(root.heading) * nextForward;
  } else {
    root.velocityX = damp(root.velocityX, 0, profile.braking, delta);
    root.velocityY = damp(root.velocityY, 0, profile.braking, delta);
    root.velocityZ = damp(root.velocityZ, 0, profile.braking, delta);
  }

  if (profile.mode !== 'AIR') root.y += root.velocityY * delta;
  root.x += root.velocityX * delta;
  root.z += root.velocityZ * delta;
  root.heading = wrapAngle(root.heading);

  if (command) {
    entity.tool.primaryPosition = clamp(
      entity.tool.primaryPosition + command.tool.primaryAxis * profile.toolRate * delta,
      0,
      1,
    );
    entity.tool.secondaryPosition = clamp(
      entity.tool.secondaryPosition + command.tool.secondaryAxis * profile.toolRate * delta,
      0,
      1,
    );
    const risingActions = command.actionBits & ~previousActionBits;
    if ((risingActions & PLAYER_COMMAND_ACTION.TOGGLE_LIGHTS) !== 0) {
      entity.tool.lightsEnabled = !entity.tool.lightsEnabled;
    }
    if ((risingActions & PLAYER_COMMAND_ACTION.TOGGLE_BEACON) !== 0) {
      entity.tool.beaconEnabled = !entity.tool.beaconEnabled;
    }
  }
  const after = [
    root.x, root.y, root.z, root.heading, root.pitch, root.roll,
    root.velocityX, root.velocityY, root.velocityZ,
    entity.tool.primaryPosition, entity.tool.secondaryPosition,
    entity.tool.lightsEnabled ? 1 : 0,
    entity.tool.beaconEnabled ? 1 : 0,
  ];
  return after.some((value, index) => Math.abs(value - before[index]!) > 1e-8);
};
