interface BlowerParticle {
  x: number;
  y: number;
  z: number;
  velocityX: number;
  velocityY: number;
  velocityZ: number;
  life: number;
}

const PENGUIN_HEIGHT = 1.18;
const PARTICLE_COUNT = 112;
const BLOWER_FORWARD_OFFSET = 0.82;
const BLOWER_RIGHT_OFFSET = 0.3;
const PLAYER_SHELL_STENCIL_REFERENCE = 2;

export type PenguinHeldTool = 'PICKAXE' | 'DRILL' | 'DYNAMITE' | 'FLARE';
