import {
  cloneConstructionBlueprint,
  createConstructionBlueprint,
  sanitizeConstructionBlueprint,
  type ConstructionBlueprint,
} from './ConstructionBlueprint';

const STORAGE_KEY = 'iceway-construction-blueprints-v1';

interface BlueprintEnvelope {
  version: 1;
  activeBlueprintId: string;
  blueprints: ConstructionBlueprint[];
}

export class ConstructionBlueprintStore {
  public constructor(private readonly storage: Storage = window.localStorage) {}

  public loadActive(): ConstructionBlueprint {
    const envelope = this.loadEnvelope();
    const active = envelope?.blueprints.find(
      (blueprint) => blueprint.id === envelope.activeBlueprintId,
    );
    if (active) return cloneConstructionBlueprint(active);
    return createConstructionBlueprint();
  }

  public save(blueprint: Readonly<ConstructionBlueprint>): void {
    const clean = sanitizeConstructionBlueprint(blueprint);
    if (!clean) throw new Error('Cannot save an invalid vessel blueprint.');
    const current = this.loadEnvelope();
    const blueprints = current?.blueprints.filter(
      (item) => item.id !== clean.id,
    ) ?? [];
    blueprints.push(clean);
    const envelope: BlueprintEnvelope = {
      version: 1,
      activeBlueprintId: clean.id,
      blueprints: blueprints.slice(-12),
    };
    this.storage.setItem(STORAGE_KEY, JSON.stringify(envelope));
  }

  public importJson(json: string): ConstructionBlueprint {
    const parsed = sanitizeConstructionBlueprint(JSON.parse(json));
    if (!parsed) throw new Error('The selected file is not an ICE-A-WAY blueprint.');
    this.save(parsed);
    return cloneConstructionBlueprint(parsed);
  }

  public exportJson(
    blueprint: Readonly<ConstructionBlueprint>,
  ): string {
    return JSON.stringify(blueprint, null, 2);
  }

  private loadEnvelope(): BlueprintEnvelope | undefined {
    try {
      const raw = this.storage.getItem(STORAGE_KEY);
      if (!raw) return undefined;
      const parsed = JSON.parse(raw) as Partial<BlueprintEnvelope>;
      if (parsed.version !== 1 || !Array.isArray(parsed.blueprints)) {
        return undefined;
      }
      const blueprints = parsed.blueprints
        .map(sanitizeConstructionBlueprint)
        .filter(
          (blueprint): blueprint is ConstructionBlueprint =>
            blueprint !== undefined,
        );
      return {
        version: 1,
        activeBlueprintId:
          typeof parsed.activeBlueprintId === 'string'
            ? parsed.activeBlueprintId
            : blueprints[0]?.id ?? '',
        blueprints,
      };
    } catch (error) {
      console.warn('ICE-A-WAY blueprints could not be loaded.', error);
      return undefined;
    }
  }
}

