export const survivalBuildDefinition = (
  id: SurvivalBuildPieceId,
): SurvivalBuildPieceDefinition =>
  SURVIVAL_BUILDING_CATALOG.find((entry) => entry.id === id) ??
  SURVIVAL_BUILDING_CATALOG[0]!;

export const survivalBuildSocketsCompatible = (
  target: Readonly<SurvivalBuildSocketDefinition>,
  source: Readonly<SurvivalBuildSocketDefinition>,
): boolean => target.accepts.includes(source.kind) || source.accepts.includes(target.kind);
